/** The latest version in a lead's quotation chain — the one "current"
 *  quotation, whatever its status, since a chain never skips versions. */
const currentQuotationForLead = (leadId: string): Quotation | undefined =>
  quotations.filter((q) => q.leadId === leadId).sort((a, b) => b.version - a.version)[0];

/** Every AIEC site captured so far is in Maharashtra — a city outside this
 *  list is exactly the "state has no Lift Act clause configured yet" case
 *  screen 075 falls back on, since lift regulation in India is
 *  state-specific rather than centrally governed. */
const MAHARASHTRA_CITIES = new Set(['Pune', 'Pimpri-Chinchwad', 'Mumbai', 'Nashik']);
const deriveStateFromCity = (city: string): string | null => (MAHARASHTRA_CITIES.has(city) ? 'Maharashtra' : null);

function buildContractClauses(
  lead: Lead,
  dealTerms: DealTerms,
  quotation: Quotation | undefined,
  template: QuotationTemplate | undefined,
): { clauses: ContractClause[]; usedStateClauseFallback: boolean } {
  const state = deriveStateFromCity(lead.city);
  const stateOverride = state ? template?.stateOverrides[state] : undefined;
  const usedStateClauseFallback = !stateOverride;
  const driveLabel = quotation?.driveType.replace(/_/g, ' ') ?? 'the agreed';
  const stagesText = dealTerms.paymentStagePlan.map((s) => `${s.stage.replace(/_/g, ' ')} ${s.percentage}%`).join(', ');
  const nationalDefault =
    template?.legalBoilerplate ??
    'This contract follows the National Building Code of India and applicable BIS standards, including IS 14665.';

  const clauses: ContractClause[] = [
    {
      key: 'scope',
      legalText: `AIEC shall supply and arrange installation of one (1) elevator at ${lead.siteName}, ${lead.address}, ${lead.city}, configured per Quotation ${quotation?.code ?? 'on file'} (${driveLabel} drive), for the price stated below.`,
      plainLanguageSummary: `This contract covers one elevator at ${lead.siteName}, built to the specification you already agreed on in your quotation.`,
    },
    {
      key: 'price_and_payment',
      legalText: `The final agreed price is ${formatINR(dealTerms.finalAgreedPrice)}, inclusive of applicable GST at ${quotation?.cost.gstPercent ?? 18}%, payable in stages: ${stagesText} — exactly as locked in on the confirmed Deal Terms record.`,
      plainLanguageSummary: `You'll pay ${formatINR(dealTerms.finalAgreedPrice)} in total, split across the payment stages you already agreed to.`,
    },
    {
      key: 'installation_and_liability',
      legalText:
        'Installation shall be carried out by an AIEC-assigned technician in accordance with IS 14665 and applicable safety codes. The assigned technician/installer is responsible for correct on-site installation; the equipment manufacturer/supplier is responsible for equipment defects; AIEC’s role is limited to facilitation, coordination, and quality oversight, and AIEC does not itself assume manufacturer or installer liability.',
      plainLanguageSummary: "Your technician is responsible for a correct, safe installation; the equipment maker is responsible for the equipment itself; AIEC coordinates and oversees rather than carrying that liability directly.",
    },
    {
      key: 'warranty_and_amc',
      legalText:
        "The equipment carries the manufacturer's standard warranty from the date of handover. An Annual Maintenance Contract, if selected, follows the tier and response-time terms published in AIEC's current AMC schedule.",
      plainLanguageSummary: "Your elevator is covered by the manufacturer's warranty from handover; any AMC you've chosen follows its own published response-time promise.",
    },
    {
      key: 'state_compliance',
      legalText: usedStateClauseFallback
        ? `${nationalDefault} A state-specific Lift Act clause set has not yet been configured for this location and has been flagged for Admin to add.`
        : `${nationalDefault} ${stateOverride}`.trim(),
      plainLanguageSummary: usedStateClauseFallback
        ? "We're using our standard national compliance language for your location since a state-specific clause set hasn't been added for it yet — this has been flagged internally."
        : `This contract also complies with ${state}'s own Lift Act, on top of our standard national terms.`,
    },
  ];

  return { clauses, usedStateClauseFallback };
}

/** Rough, honest estimates from the moment of closure — real enough to set
 *  accurate customer expectations without a full scheduling subsystem.
 *  'advance' isn't listed: it's due immediately, or (as for dl-6) may
 *  already have been invoiced before formal closure. */
const CLOSURE_STAGE_DELAY_DAYS: Record<string, number> = { material: 15, installation: 40, handover: 65, retention: 120 };

/** Creates only the stages that don't already have a Payment row for this
 *  deal — an advance often gets invoiced during negotiation, well before
 *  the deal is formally closed, and this never double-books it. */
function createDealPaymentSchedule(deal: Deal, dealTerms: DealTerms | undefined): string[] {
  const finalPrice = dealTerms?.finalAgreedPrice ?? (deal.agreedPrice || deal.quotedPrice);
  const plan = dealTerms?.paymentStagePlan ?? [];
  const closedAt = deal.closedAt ?? new Date().toISOString();
  const ids: string[] = [];
  for (const item of plan) {
    const existing = payments.find((p) => p.dealId === deal.id && p.stage === item.stage);
    if (existing) {
      ids.push(existing.id);
      continue;
    }
    const delayDays = CLOSURE_STAGE_DELAY_DAYS[item.stage] ?? 0;
    const dueDate = new Date(new Date(closedAt).getTime() + delayDays * 24 * 60 * 60 * 1000).toISOString();
    closurePaymentCounter += 1;
    const created: Payment = {
      id: `p-new-${closurePaymentCounter}`,
      code: `AIEC-P-${4200 + closurePaymentCounter}`,
      dealId: deal.id,
      stage: item.stage,
      amount: Math.round((finalPrice * item.percentage) / 100),
      status: 'due',
      dueDate,
      isDemo: true,
    };
    payments.push(created);
    ids.push(created.id);
  }
  return ids;
}

/** Reuses an already-recognized 'leadConverted' commission if one exists
 *  for this deal (a lead can be recognized before formal deal closure)
 *  rather than crediting the surveyor twice for the same conversion. */
function createOrReuseLeadConvertedCommission(deal: Deal, lead: Lead): string {
  const existing = commissions.find((c) => c.dealId === deal.id && c.reasonKey === 'commission.reason.leadConverted');
  if (existing) return existing.id;
  closureCommissionCounter += 1;
  const created: CommissionEntry = {
    id: `c-new-${closureCommissionCounter}`,
    userId: lead.originalSurveyorId,
    leadId: lead.id,
    dealId: deal.id,
    reasonKey: 'commission.reason.leadConverted',
    amount: Math.round((deal.agreedPrice || deal.quotedPrice) * (surveyorConversionPct(lead.originalSurveyorId) / 100)),
    status: 'projected',
    earnedAt: deal.closedAt ?? new Date().toISOString(),
    isDemo: true,
  };
  commissions.push(created);
  return created.id;
}

/** A failed PO never blocks the deal's own closure — it surfaces on the
 *  Automation Health Monitor (screen 027) and Alerts exactly the way any
 *  other automation failure in this build does. */
function triggerSupplierPo(deal: Deal): { id: string; failed: boolean } {
  const supplier = deal.supplierId ? byId(suppliers, deal.supplierId) : null;
  const failed = !supplier || !isSupplierEligibleForPO(supplier);
  const failureReason = !supplier
    ? 'No supplier is assigned to this deal yet.'
    : failed
      ? `${supplier.name} is not yet an active, approved supplier.`
      : undefined;
  supplierPurchaseOrderCounter += 1;
  const now = new Date().toISOString();
  const created: SupplierPurchaseOrder = {
    id: `spo-new-${supplierPurchaseOrderCounter}`,
    code: `AIEC-PO-${9000 + supplierPurchaseOrderCounter}`,
    dealId: deal.id,
    supplierId: deal.supplierId,
    status: failed ? 'failed' : 'triggered',
    failureReason,
    triggeredAt: now,
    isDemo: true,
  };
  supplierPurchaseOrders.push(created);

  if (failed) {
    const rule = automations.find((a) => a.actionKey === 'automation.action.raisePurchaseOrder' && a.triggerKey === 'automation.trigger.dealWon');
    if (rule) {
      patchInPlace(automations, rule.id, {
        runsToday: rule.runsToday + 1,
        failuresToday: rule.failuresToday + 1,
        lastRunAt: now,
        status: 'degraded' as const,
      });
      raiseAlert({
        titleKey: 'alerts.type.automationFailing',
        context: `${deal.code} · supplier PO failed — ${failureReason}`,
        severity: 'medium',
        category: 'automation',
        relatedId: rule.id,
        sourceRoute: `/admin/deals/${deal.id}/purchase-orders`,
      });
    }
  }
  logAutomatedAction({
    ruleId: automations.find((a) => a.actionKey === 'automation.action.raisePurchaseOrder' && a.triggerKey === 'automation.trigger.dealWon')?.id,
    sourceKey: failed ? 'deal_closure.supplier_po_failed' : 'deal_closure.supplier_po',
    triggeringCondition: `Deal ${deal.code} closed`,
    actionTaken: failed ? `Supplier PO attempt failed — ${failureReason}` : `Supplier PO ${created.code} triggered`,
    affectedRecordId: created.id,
    affectedRecordType: 'purchase_order',
    subjectLabel: deal.code,
  });

  return { id: created.id, failed };
}

/** Screen 092's own fixed baseline — every elevator installation needs
 *  these six regardless of drive type or finish tier; a real per-config
 *  bill of materials belongs to a later, deeper module than this one. */
const REQUIRED_PO_CATEGORIES = ['traction_machine', 'controller', 'cabin', 'door_operator', 'guide_rails', 'ropes'];

/** How far `agreedUnitPrice` may drift from the catalog price before a PO
 *  needs Admin's explicit approval to send — protects the deal's
 *  already-locked-in margin per the spec's own business rule. */
const PO_PRICE_TOLERANCE_PCT = 0.05;

/** A supplier's live listing for a category (the cheaper one if they list
 *  two). Discontinued, flagged and rejected items are never drafted onto a
 *  new PO — 093's catalog is the only cost source, there is no other. */
function liveCatalogItemFor(supplierId: string, category: string): SupplierCatalogItem | null {
  return (
    supplierCatalogItems
      .filter((c) => c.supplierId === supplierId && c.category === category && c.status === 'active')
      .sort((a, b) => a.unitPrice - b.unitPrice)[0] ?? null
  );
}

function catalogPriceFor(supplierId: string, category: string): number | null {
  return liveCatalogItemFor(supplierId, category)?.unitPrice ?? null;
}

function categoryDescription(category: string): string {
  return supplierCatalogItems.find((c) => c.category === category && c.status === 'active')?.description ?? category;
}

/** Each eligible supplier's live listing for a category — one fitting the
 *  deal's drive type if they have one, else their cheapest. What 094's
 *  matching ranks; never an ineligible supplier, so 092's compliance rule
 *  holds at the point of matching, not just at send time. */
function offersFor(category: string, driveType: DriveType | null): MatchOffer[] {
  const offers: MatchOffer[] = [];
  for (const supplier of suppliers) {
    if (!isSupplierEligibleForPO(supplier)) continue;
    // A supplier with no agreement in force can't be sent a PO (098), so
    // drafting one for them would only strand it.
    if (!canIssueNewPo(agreementStateFor(supplier.id).status)) continue;
    const live = supplierCatalogItems
      .filter((c) => c.supplierId === supplier.id && c.category === category && c.status === 'active')
      .sort((x, y) => x.unitPrice - y.unitPrice);
    const item = live.find((c) => !driveType || c.driveTypes.length === 0 || c.driveTypes.includes(driveType)) ?? live[0];
    if (item) offers.push({ supplier, item });
  }
  return offers;
}

/** The drive type the customer actually bought, from the lead's current quote. */
function driveTypeForDeal(deal: Deal): DriveType | null {
  return currentQuotationForLead(deal.leadId)?.driveType ?? null;
}

function matchRequiredCategories(driveType: DriveType | null, assignedSupplierId: string | null, rules: AutoPoRules): CategoryMatchResult[] {
  return REQUIRED_PO_CATEGORIES.map((category) => matchCategory(category, offersFor(category, driveType), rules, driveType, assignedSupplierId));
}

/** Whether a won deal has reached 094's configured drafting trigger. */
function poTriggerMet(deal: Deal): boolean {
  if (deal.status !== 'won') return false;
  if (autoPoRules.triggerCondition === 'on_countersignature') return true;
  return payments.some((p) => p.dealId === deal.id && p.stage === 'advance' && p.status === 'paid');
}

/**
 * Drafts a won deal's POs under 094's current rules: every required category
 * matched by the configured weights (the deal's assigned supplier first, if
 * the rules say so), grouped into one PO per chosen supplier — naturally
 * several linked POs when no single supplier covers everything. Each PO
 * keeps the full ranking behind every line, so "why this supplier?" always
 * has an answer, and a later rule change never rewrites it.
 */
function draftPurchaseOrdersForDeal(deal: Deal, manualBy?: string): SupplierPurchaseOrder[] {
  const results = matchRequiredCategories(driveTypeForDeal(deal), deal.supplierId ?? null, autoPoRules);
  const bySupplier = new Map<string, CategoryMatchResult[]>();
  for (const result of results) {
    if (!result.chosenSupplierId) continue;
    bySupplier.set(result.chosenSupplierId, [...(bySupplier.get(result.chosenSupplierId) ?? []), result]);
  }
  const now = new Date().toISOString();
  const created: SupplierPurchaseOrder[] = [];
  for (const [supplierId, supplierResults] of bySupplier) {
    const lineItems: PurchaseOrderLineItem[] = supplierResults.map((result) => {
      const chosen = result.candidates.find((c) => c.supplierId === supplierId)!;
      const item = byId(supplierCatalogItems, chosen.itemId);
      poLineItemCounter += 1;
      return {
        id: `poli-${poLineItemCounter}`,
        category: result.category,
        description: item?.description ?? categoryDescription(result.category),
        quantity: 1,
        catalogUnitPriceAtDraft: chosen.unitPrice,
        agreedUnitPrice: chosen.unitPrice,
      };
    });
    supplierPurchaseOrderCounter += 1;
    const po: SupplierPurchaseOrder = {
      id: `spo-new-${supplierPurchaseOrderCounter}`,
      code: `AIEC-PO-${9000 + supplierPurchaseOrderCounter}`,
      dealId: deal.id,
      supplierId,
      status: 'draft',
      triggeredAt: now,
      lineItems,
      matchedByRulesVersion: autoPoRules.version,
      selection: supplierResults,
      isDemo: true,
    };
    supplierPurchaseOrders.push(po);
    created.push(po);
    if (!manualBy) {
      logAutomatedAction({
        sourceKey: 'purchase_order.auto_draft',
        triggeringCondition: `Deal ${deal.code} reached the ${autoPoRules.triggerCondition} trigger with no purchase order yet`,
        actionTaken: `Drafted ${po.code} with ${lineItems.length} line item(s) under rules v${autoPoRules.version}`,
        affectedRecordId: po.id,
        affectedRecordType: 'purchase_order',
        subjectLabel: po.code,
      });
    }
  }
  return created;
}

/** Won deals whose trigger has fired get their POs without anyone opening
 *  092 — the heartbeat calls this. Idempotent: a deal with any real PO is
 *  never drafted again, whatever the rules say now. */
function autoDraftDuePurchaseOrders(): void {
  if (!autoPoRules.autoDraftEnabled) return;
  for (const deal of deals) {
    if (!poTriggerMet(deal)) continue;
    if (supplierPurchaseOrders.some((po) => po.dealId === deal.id && po.lineItems)) continue;
    draftPurchaseOrdersForDeal(deal);
  }
}

const poTotalOf = (lines: PurchaseOrderLineItem[]) => lines.reduce((sum, l) => sum + l.quantity * l.agreedUnitPrice, 0);

/** Why a PO must wait for Admin before it can be sent: a price drifted from
 *  the catalog (092), or its value is over 094's approval line — oversight
 *  proportional to the size of the commitment, however good the match was.
 *  Read live, so lowering the line reaches every PO not yet sent. */
function purchaseOrderApprovalReasons(lines: PurchaseOrderLineItem[]): ('price_deviation' | 'over_value_threshold')[] {
  const reasons: ('price_deviation' | 'over_value_threshold')[] = [];
  if (lines.some((l) => l.catalogUnitPriceAtDraft > 0 && Math.abs(l.agreedUnitPrice - l.catalogUnitPriceAtDraft) / l.catalogUnitPriceAtDraft > PO_PRICE_TOLERANCE_PCT)) {
    reasons.push('price_deviation');
  }
  if (poTotalOf(lines) > autoPoRules.approvalThreshold) reasons.push('over_value_threshold');
  return reasons;
}

function purchaseOrderNeedsApproval(lines: PurchaseOrderLineItem[]): boolean {
  return purchaseOrderApprovalReasons(lines).length > 0;
}

function buildPurchaseOrderView(po: SupplierPurchaseOrder): PurchaseOrderView {
  const supplier = po.supplierId ? byId(suppliers, po.supplierId) : null;
  const lines = po.lineItems ?? [];
  const approvalReasons = po.status === 'sent' ? [] : purchaseOrderApprovalReasons(lines);
  const requiresApproval = approvalReasons.length > 0 && !po.approvedAt;
  return {
    approvalReasons,
    po,
    supplierName: supplier?.name ?? '',
    supplierEligible: supplier ? isSupplierEligibleForPO(supplier) : false,
    lines: lines.map((line): PurchaseOrderLineView => ({ ...line, currentCatalogUnitPrice: po.supplierId ? catalogPriceFor(po.supplierId, line.category) : null })),
    totalAmount: poTotalOf(lines),
    requiresApproval,
    agreementStatus: po.supplierId ? agreementStateFor(po.supplierId).status : 'none',
  };
}

/** Same "positive stage move" proxy the Communication Analytics screen's
 *  conversion-influence metric uses — did the lead this was used on go on
 *  to reach "won"? — kept below this row count, `earlyData` says so instead
 *  of a misleadingly confident percentage. */
const OBJECTION_SCRIPT_EARLY_DATA_THRESHOLD = 3;

/** The three categories the bot's Objection Scenario Map (screen 071) also
 *  classifies negotiation replies into — literally the same string values
 *  as `NegotiationObjectionKey`, never a second drifting taxonomy. */
const BOT_SHARED_OBJECTION_CATEGORIES: ObjectionCategory[] = ['competitor_comparison', 'price_too_high', 'wants_to_delay'] satisfies NegotiationObjectionKey[];

function effectivenessScoreFor(usages: ObjectionScriptUsage[]): number | null {
  if (usages.length === 0) return null;
  const wonCount = usages.filter((u) => resolveLead(u.leadId)?.stage === 'won').length;
  return Math.round((wonCount / usages.length) * 100);
}

function buildObjectionScriptListItem(script: ObjectionScript): ObjectionScriptListItem {
  const usages = objectionScriptUsages.filter((u) => u.scriptId === script.id);
  const byTerritory = new Map<string, ObjectionScriptUsage[]>();
  for (const usage of usages) {
    const territory = resolveLead(usage.leadId)?.city ?? 'unknown';
    const list = byTerritory.get(territory) ?? [];
    list.push(usage);
    byTerritory.set(territory, list);
  }
  const territoryStats: ObjectionScriptTerritoryStat[] = [...byTerritory.entries()]
    .map(([territory, rows]) => ({ territory, usageCount: rows.length, effectivenessScore: effectivenessScoreFor(rows) }))
    .sort((a, b) => b.usageCount - a.usageCount);

  return {
    script,
    usageCount: usages.length,
    effectivenessScore: effectivenessScoreFor(usages),
    earlyData: usages.length < OBJECTION_SCRIPT_EARLY_DATA_THRESHOLD,
    territoryStats,
    usedByBot: BOT_SHARED_OBJECTION_CATEGORIES.includes(script.category),
  };
}

/**
 * Everyone with a legitimate commission claim on this deal — screen 080.
 * The original capturing surveyor keeps that entitlement forever regardless
 * of reassignment (per `Lead.originalSurveyorId`'s own contract, screen
 * 044), so they're always included; the current surveyor is only added
 * separately when reassignment actually happened, so the ordinary
 * single-surveyor case never shows a duplicate row.
 */
function buildDealCelebrationStaffSummaries(lead: Lead, deal: Deal): DealCelebrationStaffSummary[] {
  const staff: { id: string; role: DealCelebrationStaffSummary['role'] }[] = [{ id: lead.originalSurveyorId, role: 'original_surveyor' }];
  if (lead.surveyorId && lead.surveyorId !== lead.originalSurveyorId) {
    staff.push({ id: lead.surveyorId, role: 'current_surveyor' });
  }
  return staff
    .filter((s) => s.id)
    .map(({ id, role }) => {
      const entries = commissions.filter((c) => c.userId === id && (c.dealId === deal.id || c.leadId === lead.id));
      return {
        userId: id,
        name: nameOf(id),
        role,
        entries,
        total: entries.filter((e) => e.status !== 'forfeited').reduce((sum, e) => sum + e.amount, 0),
      };
    });
}

/** Resolves a milestone-triggered stage's due date live from the deal's own
 *  primary installation job — never stored, so a delayed milestone shifts
 *  the due date on the very next read with no separate update anywhere.
 *  Deliberately only the first job created for the deal: a deal can pick
 *  up unrelated later jobs (a second wing, a standalone service call) once
 *  it's underway, and those should never resolve a payment stage's
 *  milestone that was never about them. */
function resolveMilestoneDueDate(dealId: string, triggerMilestone: string): string | null {
  const primaryJob = jobs.find((j) => j.dealId === dealId);
  const step = primaryJob?.steps.find((s) => s.labelKey === triggerMilestone);
  if (step && step.status === 'complete' && step.completedAt) return step.completedAt;
  // "Materials received" is also what a signed delivery confirmation (104) says,
  // before anyone has ticked the installation step for it.
  return triggerMilestone === MATERIALS_MILESTONE ? materialsConfirmedAt(dealId) : null;
}

/** What the schedule's stages must sum to exactly — derived from the
 *  confirmed `paymentStagePlan`'s own percentages against the deal value,
 *  since that plan's percentages summing past 100 (a retention holdback on
 *  top) is the AIEC norm, not something this screen should silently
 *  correct back down to a flat 100%. Falls back to the deal value itself
 *  if no plan exists yet (shouldn't happen once `canSetUp` gates this). */
function expectedPaymentScheduleTotal(dealValue: number, dealTerms: DealTerms | null): number {
  if (!dealTerms || dealTerms.paymentStagePlan.length === 0) return dealValue;
  const totalPct = dealTerms.paymentStagePlan.reduce((sum, p) => sum + p.percentage, 0);
  return Math.round((dealValue * totalPct) / 100);
}

function resolvePaymentScheduleStages(dealId: string, stages: PaymentScheduleStage[]): PaymentScheduleStageResolved[] {
  return [...stages]
    .sort((a, b) => a.sequenceOrder - b.sequenceOrder)
    .map((stage) => ({
      stage,
      resolvedDueDate: stage.dueTrigger === 'fixed_date' ? (stage.fixedDueDate ?? null) : resolveMilestoneDueDate(dealId, stage.triggerMilestone ?? ''),
    }));
}

function sendReminderMessage(payment: Payment, lead: Lead, byName: string, channel: CommChannel, templateGroupId: string): CommMessage {
  const template = templateInGroup(templateGroupId, 'en');
  const body = template
    ? renderTemplateBody(template.body, { customerName: lead.contactName, buildingName: lead.siteName, quoteAmount: formatINRCompact(remainingBalance(payment)) })
    : `Reminder: payment of ${formatINRCompact(remainingBalance(payment))} is due for ${lead.siteName}.`;
  let conversation = conversations.find((c) => c.leadId === lead.id) ?? null;
  const now = new Date().toISOString();
  if (!conversation) {
    conversationCounter += 1;
    conversation = { id: `conv-new-${conversationCounter}`, leadId: lead.id, lastMessageAt: now, isDemo: true };
    conversations.push(conversation);
  }
  messageCounter += 1;
  const message: CommMessage = {
    id: `cm-new-${messageCounter}`,
    conversationId: conversation.id,
    channel,
    sender: 'agent',
    senderName: byName,
    body,
    templateGroupId,
    status: 'sent',
    at: now,
    handled: true,
  };
  commMessages.push(message);
  patchInPlace(conversations, conversation.id, { lastMessageAt: now });
  return message;
}

const activeDealPause = (dealId: string) => paymentReminderPauses.find((p) => p.dealId === dealId && p.paused);

/** How far back a missed reminder step is still worth sending. Past this,
 *  089's escalation queue owns the payment — a week-old "friendly nudge"
 *  arriving now would read as a glitch, not a reminder. */
const REMINDER_CATCH_UP_DAYS = 7;

/**
 * The reminder cadence (083), run by 083's own "Run now" and by the
 * follow-up engine's heartbeat alike.
 *
 * Catch-up, not exact-day: the latest step whose day has arrived fires once
 * even if nobody had the app open on that exact day — otherwise one quiet
 * day loses a reminder for good. Earlier steps it overtook are marked as
 * superseded, never sent late on top of it. One firing per payment, step
 * and due date, so a heartbeat every minute can't message a customer twice,
 * and moving a due date (081) re-arms the cadence against the new date.
 */
/** How long the owner gets to make an auto-created collection call. */
const COLLECTION_CALL_WINDOW = hours(4);

function runPaymentReminders(byName: string, nowMs = Date.now()): ReminderRunResult {
  const result: ReminderRunResult = { sent: 0, callTasksCreated: 0, skippedOptedOut: 0, skippedPaused: 0, skippedOutsideWindow: 0 };
  const now = new Date(nowMs);
  const withinWindow = now.getHours() >= paymentReminderConfig.sendWindowStartHour && now.getHours() < paymentReminderConfig.sendWindowEndHour;
  const todayKey = now.toISOString().slice(0, 10);
  const oldestKey = new Date(now.getTime() - days(REMINDER_CATCH_UP_DAYS)).toISOString().slice(0, 10);
  const ruleId = automations.find((a) => a.triggerKey === 'automation.trigger.paymentDueSoon')?.id;
  for (const payment of payments.filter(isOutstanding)) {
    const deal = byId(deals, payment.dealId);
    if (!deal) continue;
    const lead = resolveLead(deal.leadId);
    if (!lead) continue;
    const dueTime = new Date(payment.dueDate).getTime();
    const arrived = paymentReminderConfig.steps
      .map((step) => ({ step, dayKey: new Date(dueTime + step.daysOffset * 86_400_000).toISOString().slice(0, 10) }))
      .filter((entry) => entry.dayKey <= todayKey)
      .sort((a, b) => (a.dayKey < b.dayKey ? 1 : a.dayKey > b.dayKey ? -1 : b.step.daysOffset - a.step.daysOffset));
    const latest = arrived[0];
    if (!latest || latest.dayKey < oldestKey) continue;
    const keyFor = (stepId: string) => `${payment.id}|${stepId}|${payment.dueDate}`;
    const firedKey = keyFor(latest.step.id);
    if (firedReminderKeys.has(firedKey)) continue;
    if (activeDealPause(deal.id)) {
      result.skippedPaused += 1;
      continue;
    }
    if (!withinWindow) {
      result.skippedOutsideWindow += 1;
      continue;
    }
    const step = latest.step;
    if (step.escalationTier === 'call_task') {
      followUpTaskCounter += 1;
      followUpTasks.push({
        id: `ft-new-${followUpTaskCounter}`,
        leadId: lead.id,
        title: `Call ${lead.contactName} about the overdue payment for ${lead.siteName}`,
        // "Call today", not "already late" the instant it's created.
        dueDate: new Date(nowMs + COLLECTION_CALL_WINDOW).toISOString(),
        assignedTo: lead.surveyorId || 'u-admin-1',
        status: 'open',
        source: 'auto',
        purpose: 'collection',
        createdAt: now.toISOString(),
        isDemo: true,
      });
      result.callTasksCreated += 1;
      logAutomatedAction({
        ruleId,
        sourceKey: 'payment_reminder.call_task',
        triggeringCondition: `${payment.code} reached its ${step.daysOffset}-day call step`,
        actionTaken: `Created call task for ${lead.surveyorId ? nameOf(lead.surveyorId) : 'Admin'}`,
        affectedRecordId: payment.id,
        affectedRecordType: 'payment',
        subjectLabel: payment.code,
      });
    } else if (isOptedOutSync(lead.contactPhone, step.channel)) {
      result.skippedOptedOut += 1;
    } else {
      sendReminderMessage(payment, lead, byName, step.channel, step.templateGroupId ?? 'tpl-payment-reminder');
      result.sent += 1;
      logAutomatedAction({
        ruleId,
        sourceKey: 'payment_reminder.message',
        triggeringCondition: `${payment.code} reached its ${step.daysOffset}-day reminder step`,
        actionTaken: `Sent ${step.escalationTier} ${step.channel} reminder to ${lead.contactName}`,
        affectedRecordId: payment.id,
        affectedRecordType: 'payment',
        subjectLabel: payment.code,
      });
    }
    for (const entry of arrived) firedReminderKeys.add(keyFor(entry.step.id));
  }
  return result;
}

/** Screen 089's tier badge — days-overdue and remaining amount set the base
 *  level, then a good-standing customer's one late stage is tempered down
 *  exactly one level (never suppressed outright: the money is still owed),
 *  the relationship-history weighting the spec calls for. */
function computeEscalationTier(overdueDays: number, overdueAmount: number, goodStanding: boolean): EscalationTier {
  let severity: 0 | 1 | 2 = 0;
  if (overdueDays >= 21 || overdueAmount >= 500_000) severity = 2;
  else if (overdueDays >= 14 || overdueAmount >= 200_000) severity = 1;
  if (goodStanding && severity > 0) severity = (severity - 1) as 0 | 1;
  return severity === 2 ? 'installation_hold' : severity === 1 ? 'formal_notice' : 'call';
}

/** Resolves the reminder cadence against one payment's real, current due
 *  date — recomputed fresh every call, so a milestone-shifted due date (see
 *  081) is reflected immediately with no separate recalculation step. A
 *  currently-paused deal skips every step outright; an opted-out contact
 *  only skips the one step on that channel. */
function buildReminderTimeline(payment: Payment, lead: Lead, config: PaymentReminderConfig, now: number): ReminderTimelineEntry[] {
  const paused = Boolean(activeDealPause(payment.dealId));
  const dueTime = new Date(payment.dueDate).getTime();
  const dayMs = 86_400_000;
  // Calendar-date string comparison, not a rounded time difference — must
  // match runDueRemindersNow's own todayKey check exactly, or the preview
  // can call a step "due today" that the real run (fired minutes later)
  // classifies as already past or still upcoming.
  const todayKey = new Date(now).toISOString().slice(0, 10);
  return [...config.steps]
    .sort((a, b) => a.daysOffset - b.daysOffset)
    .map((step) => {
      const fireDate = new Date(dueTime + step.daysOffset * dayMs).toISOString();
      let outcome: ReminderTimelineEntry['outcome'];
      if (paused) {
        outcome = 'skipped_paused';
      } else if (step.channel !== 'call' && isOptedOutSync(lead.contactPhone, step.channel)) {
        outcome = 'skipped_opted_out';
      } else {
        const fireDateKey = fireDate.slice(0, 10);
        outcome = fireDateKey < todayKey ? 'sent_in_past' : fireDateKey === todayKey ? 'due_today' : 'upcoming';
      }
      return { step, fireDate, outcome };
    });
}

/** This build's one financing partner — a real, comparable value on every
 *  `LoanApplication`, not a UI-only label, so 086's per-partner stats mean
 *  something even with only one row today. */
const FINANCING_PARTNER_NAME = 'Suvidha Finance Ltd';

/** AIEC's own GSTIN — real invoice data, so it's a plain constant, not a
 *  translated UI string; every invoice 087 issues carries it. */
const AIEC_GSTIN = '27AABCA1234B1Z5';

/** Screen 090's own SLA target for resolving a payment dispute — 5 days,
 *  a reasonable ceiling for a financial-trust issue per the spec's own
 *  framing of unresolved disputes as a reputational risk. */
const DISPUTE_SLA = hours(120);

/** Splits a GST-inclusive total into its taxable value and GST amount —
 *  every `Payment.amount`/`Deal.agreedPrice` in this build is already
 *  GST-inclusive (see `QuotationCostBreakdown.finalPrice`), so every
 *  invoice figure is derived by working backward from it, never entered
 *  independently. */
function splitGst(totalInclusive: number, gstPercent: number): { taxableValue: number; gstAmount: number } {
  const taxableValue = Math.round(totalInclusive / (1 + gstPercent / 100));
  return { taxableValue, gstAmount: totalInclusive - taxableValue };
}

function customerAddressOf(lead: Lead | null): string {
  return lead ? `${lead.address}, ${lead.city} ${lead.pincode}` : '';
}

/** Idempotently backfills a `'stage'` invoice for every `Payment` on this
 *  deal that's `'paid'` and doesn't already have one — see
 *  `getInvoicesForDeal`'s own doc comment for why this, not a live event,
 *  is what "auto-generates as it's collected" resolves to here. */
function ensureStageInvoices(dealId: string, deal: Deal, lead: Lead | null): void {
  // Also backfills a stage that's *now* `'disputed'` but was fully `'paid'`
  // right before the dispute (090's own refund flow needs a real invoice to
  // issue a credit note against, even when nobody happened to open the
  // Invoice screen while the stage was still simply `'paid'`).
  const paidWithoutInvoice = payments.filter(
    (p) => p.dealId === dealId && (p.status === 'paid' || (p.status === 'disputed' && p.preDisputeStatus === 'paid')) && !invoices.some((inv) => inv.paymentId === p.id),
  );
  for (const payment of paidWithoutInvoice) {
    const { taxableValue, gstAmount } = splitGst(payment.amount, deal.gstPercent);
    invoiceCounter += 1;
    invoices.push({
      id: `inv-${invoiceCounter}`,
      code: `AIEC-INV-${4000 + invoiceCounter}`,
      dealId,
      paymentId: payment.id,
      stage: payment.stage,
      type: 'stage',
      customerName: deal.customerId ? nameOf(deal.customerId) : (lead?.contactName ?? ''),
      customerAddress: customerAddressOf(lead),
      customerGstin: deal.customerGstin,
      aiecGstin: AIEC_GSTIN,
      taxableValue,
      gstPercent: deal.gstPercent,
      gstAmount,
      totalAmount: payment.amount,
      issuedAt: payment.paidAt ?? new Date().toISOString(),
      issuedBy: 'AIEC',
      isDemo: true,
    });
    logAutomatedAction({
      sourceKey: 'invoice.stage_backfill',
      triggeringCondition: `Payment ${payment.code} is paid with no invoice`,
      actionTaken: `Issued stage invoice AIEC-INV-${4000 + invoiceCounter}`,
      affectedRecordId: `inv-${invoiceCounter}`,
      affectedRecordType: 'invoice',
      subjectLabel: payment.code,
    });
  }
}

/** What was actually collected on a disputed payment, for screen 090 —
 *  `receivedAmountOf` alone isn't enough here, because it keys off the
 *  payment's *current* status, and disputing a stage moves that status
 *  away from `'paid'` to `'disputed'` (a seeded record may also never have
 *  had `amountReceived` set explicitly if it simply started `'paid'`).
 *  `preDisputeStatus` — snapshotted the moment the dispute was raised — is
 *  the one durable record of whether this stage was genuinely paid in
 *  full before the dispute, and stays authoritative through resolution. */
function amountCollectedForDispute(payment: Payment): number {
  if (payment.preDisputeStatus === 'paid') return payment.amount;
  return receivedAmountOf(payment);
}

/** Shared by `issueCreditNote` (087) and 090's own refund resolution —
 *  one credit-note-creation path, never two independent ones that could
 *  drift on the GST split. */
function createCreditNote(original: Invoice, amount: number, reason: string, byName: string): Invoice {
  const { taxableValue, gstAmount } = splitGst(amount, original.gstPercent);
  invoiceCounter += 1;
  const created: Invoice = {
    id: `inv-${invoiceCounter}`,
    code: `AIEC-CN-${4000 + invoiceCounter}`,
    dealId: original.dealId,
    type: 'credit_note',
    customerName: original.customerName,
    customerAddress: original.customerAddress,
    customerGstin: original.customerGstin,
    aiecGstin: original.aiecGstin,
    taxableValue,
    gstPercent: original.gstPercent,
    gstAmount,
    totalAmount: amount,
    issuedAt: new Date().toISOString(),
    issuedBy: byName,
    referencesInvoiceId: original.id,
    creditNoteReason: reason.trim(),
    isDemo: true,
  };
  invoices.push(created);
  return created;
}

/** One payment as 088's receipt list shows it — always looked up against
 *  whatever invoice `ensureStageInvoices` has (or hasn't yet) generated
 *  for it, never a second, independent invoice reference. */
function buildReceiptLine(payment: Payment, deal: Deal, lead: Lead | null): PaymentReceiptLine {
  const invoice = invoices.find((inv) => inv.paymentId === payment.id);
  return {
    payment,
    receivedAmount: receivedAmountOf(payment),
    dealCode: deal.code,
    siteName: lead?.siteName ?? '',
    customerName: deal.customerId ? nameOf(deal.customerId) : (lead?.contactName ?? ''),
    invoiceId: invoice?.id ?? null,
    invoiceCode: invoice?.code ?? null,
  };
}

/** How long an `'approved'` application may sit before 086 treats it as
 *  stuck and surfaces an Alert rather than leaving it to be discovered by
 *  chance — the spec's own "not sit silently" edge case. */
const LOAN_STUCK_WINDOW = days(5);

/** The financing partner's own underwriting call, standing in for a real
 *  decision this build has no lender to make — deterministic on the
 *  precheck's income bracket (never randomness), so the same application
 *  always resolves the same way. Lower brackets cap the approved amount
 *  below what was requested, which is exactly what exercises 085's
 *  "approved for less than requested" edge case. */
function approvedAmountFor(incomeRange: LoanIncomeRange, requestedAmount: number): number {
  const cap: Record<LoanIncomeRange, number> = {
    below_5l: 300_000,
    '5l_10l': 600_000,
    '10l_25l': Infinity,
    above_25l: Infinity,
  };
  return Math.min(requestedAmount, cap[incomeRange]);
}

/** The one moment a loan application touches `Payment` — settles the
 *  deal's outstanding stages, oldest due date first, up to `amount`,
 *  using the exact same partial-payment mechanics 082/084 already use
 *  (`amountReceived` accumulates, `status` only flips to `'paid'` once it
 *  covers the stage in full). If `amount` runs out partway, later stages
 *  are deliberately left exactly as owed — that gap is what 085's
 *  "approved for less" state points the customer back to 084 to cover. */
function settleDealPaymentsWithFinancing(dealId: string, amount: number): void {
  let remaining = amount;
  const outstanding = payments.filter((p) => p.dealId === dealId && isOutstanding(p)).sort((a, b) => a.dueDate.localeCompare(b.dueDate));
  for (const p of outstanding) {
    if (remaining <= 0) break;
    const applied = Math.min(remainingBalance(p), remaining);
    const newReceived = (p.amountReceived ?? 0) + applied;
    patchInPlace(payments, p.id, {
      amountReceived: newReceived,
      method: 'financing',
      status: newReceived >= p.amount ? 'paid' : p.status,
      paidAt: newReceived >= p.amount ? new Date().toISOString() : p.paidAt,
      lastReceivedAt: new Date().toISOString(),
    });
    remaining -= applied;
  }
}

function pushTimelineEvent(event: Omit<LeadTimelineEvent, 'id'>): LeadTimelineEvent {
  const full: LeadTimelineEvent = { ...event, id: `lt-${(timelineEventCounter += 1)}` };
  leadTimeline.push(full);
  return full;
}

const PIPELINE_RANK: Lead['stage'][] = [
  'captured',
  'contacted',
  'site_visit',
  'quoted',
  'negotiation',
  'won',
];
const rankOf = (stage: Lead['stage']) => {
  const i = PIPELINE_RANK.indexOf(stage);
  return i === -1 ? -1 : i;
};

/** Cancels any open follow-up whose lead has since closed, so a stale task
 *  never lingers just because nobody remembered to close it by hand. */
function reconcileFollowUpTasks() {
  for (let i = 0; i < followUpTasks.length; i += 1) {
    const task = followUpTasks[i];
    if (task.status !== 'open' || task.purpose === 'collection') continue;
    const lead = resolveLead(task.leadId);
    if (lead && (lead.stage === 'won' || lead.stage === 'lost')) {
      followUpTasks[i] = {
        ...task,
        status: 'cancelled',
        rescheduleReasonKey: 'followUp.reason.leadClosed',
      };
    }
  }
}

const CONSTRUCTION_READINESS: Record<NonNullable<Lead['spec']>['constructionStage'], number> = {
  foundation: 0.25,
  structure: 0.5,
  finishing: 0.75,
  ready: 1,
};

/** Every factor is a documented, explainable 0..1 value — never an opaque
 *  black-box number — per screen 046's requirement that a score can always
 *  be broken down on request. */
function computeLeadScore(lead: Lead, profile: ScoreWeightingProfile): { score: number; breakdown: ScoreFactor[] } {
  const buildingSizeValue = lead.spec
    ? Math.min(1, (lead.spec.floors * lead.spec.capacityPersons) / 200)
    : 0.5;
  const readinessValue = lead.spec ? CONSTRUCTION_READINESS[lead.spec.constructionStage] : 0.5;
  // No responsiveness history yet on a brand-new capture — neutral default,
  // not an artificially low score, per the scoring screen's edge-case rule.
  const responsivenessValue = lead.stage === 'captured' ? 0.5 : 0.7;
  const cityLeads = leads.filter((l) => l.city === lead.city);
  const cityWon = cityLeads.filter((l) => l.stage === 'won').length;
  const territoryValue = cityLeads.length ? cityWon / cityLeads.length : 0.5;

  const factors: ScoreFactor[] = [
    { key: 'buildingSize', weight: profile.buildingSize, value: buildingSizeValue, contribution: Math.round(profile.buildingSize * buildingSizeValue * 100) },
    { key: 'constructionReadiness', weight: profile.constructionReadiness, value: readinessValue, contribution: Math.round(profile.constructionReadiness * readinessValue * 100) },
    { key: 'responsiveness', weight: profile.responsiveness, value: responsivenessValue, contribution: Math.round(profile.responsiveness * responsivenessValue * 100) },
    { key: 'territoryHistory', weight: profile.territoryHistory, value: territoryValue, contribution: Math.round(profile.territoryHistory * territoryValue * 100) },
  ];
  const score = Math.max(0, Math.min(100, factors.reduce((sum, f) => sum + f.contribution, 0)));
  return { score, breakdown: factors };
}

/** Recomputes only leads still active in the pipeline — a closed record's
 *  score stays exactly what it was under the weighting active when it was
 *  computed, so old records never reshuffle retroactively. */
function recomputeActiveScores(profile: ScoreWeightingProfile) {
  const now = new Date().toISOString();
  for (let i = 0; i < leads.length; i += 1) {
    const lead = leads[i];
    if (lead.stage === 'won' || lead.stage === 'lost') continue;
    const { score, breakdown } = computeLeadScore(lead, profile);
    leads[i] = { ...lead, score, scoreFactorBreakdown: breakdown, scoreLastComputed: now };
  }
}
recomputeActiveScores(scoreWeightingProfile);

const IMPORT_REQUIRED_FIELDS = ['builderName', 'contactName', 'contactPhone', 'siteName', 'city'] as const;

/** Runs every imported row through the same required-field and duplicate
 *  checks a field capture goes through — a migrated spreadsheet can carry
 *  its own duplicates or overlap with existing leads just as easily. */
function buildImportPreview(rows: Record<string, string>[]): ImportPreview {
  const validated: ImportValidationRow[] = rows.map((values, i) => {
    const errors: string[] = [];
    for (const field of IMPORT_REQUIRED_FIELDS) {
      if (!values[field]?.trim()) errors.push(`missing_${field}`);
    }
    const phone = values.contactPhone?.replace(/\D/g, '') ?? '';
    if (phone && phone.length !== 10) errors.push('invalid_phone');

    let duplicateOfLeadId: string | undefined;
    const siteName = values.siteName?.trim().toLowerCase();
    const match = leads.find(
      (l) => (phone && l.contactPhone.replace(/\D/g, '') === phone) || (siteName && l.siteName.trim().toLowerCase() === siteName),
    );
    if (match) duplicateOfLeadId = match.id;

    return { rowNumber: i + 1, values, errors, duplicateOfLeadId };
  });
  const errorCount = validated.filter((r) => r.errors.length > 0).length;
  return { rows: validated, validCount: validated.length - errorCount, errorCount };
}

function patchInPlace<T extends { id: string }>(list: T[], id: string, patch: Partial<T>): T {
  const index = list.findIndex((item) => item.id === id);
  if (index === -1) throw new RepositoryError('not_found');
  const next = { ...list[index], ...patch } as T;
  list[index] = next;
  return next;
}

/* -------------------------------------------------- Communication engine */

/** Resolves what real data exists for a lead's merge fields — an empty
 *  string here is exactly what tells `renderTemplateBody` to fall back to
 *  its sensible default phrase instead of a broken blank. */
function buildMergeValuesForLead(lead: Lead): Record<string, string> {
  const deal = deals.find((d) => d.leadId === lead.id);
  const job = deal ? jobs.find((j) => j.dealId === deal.id) : undefined;
  const currentStep = job?.steps.find((s) => s.status === 'current') ?? job?.steps.find((s) => s.status === 'complete');
  const readableStep = currentStep
    ? currentStep.labelKey
        .replace('job.step.', '')
        .replace(/([A-Z])/g, ' $1')
        .trim()
        .replace(/^./, (c) => c.toUpperCase())
    : '';
  const routeStop = routePlans.flatMap((r) => r.stops).find((s) => s.leadId === lead.id);

  return {
    customerName: lead.contactName,
    buildingName: lead.siteName,
    quoteAmount: deal && (deal.agreedPrice || deal.quotedPrice) ? formatINRCompact(deal.agreedPrice || deal.quotedPrice) : '',
    installStep: readableStep,
    visitDate: routeStop ? routeStop.windowStart.slice(0, 10) : '',
  };
}

function findTemplate(id: string): CommTemplate {
  const template = byId(commTemplates, id);
  if (!template) throw new RepositoryError('not_found');
  return template;
}

function templateInGroup(groupId: string, language: string): CommTemplate | undefined {
  return commTemplates.find((t) => t.groupId === groupId && t.language === language);
}

const OPT_OUT_KEYWORDS = ['stop', 'unsubscribe'];

/** Most recent event per phone+channel (or 'all') wins — opt-outs are
 *  channel-specific by default, with 'all' as the explicit blanket option. */
function isOptedOutSync(phone: string, channel: CommChannel): boolean {
  const relevant = optOutEvents.filter((e) => e.contactPhone === phone && (e.channel === channel || e.channel === 'all'));
  if (relevant.length === 0) return false;
  const latest = [...relevant].sort((a, b) => b.at.localeCompare(a.at))[0];
  return latest.type === 'opted_out';
}

/** Deterministic per-number simulation of WhatsApp reachability — no real
 *  gateway exists in this demo, so the same contact always resolves the same
 *  way on retry rather than flapping randomly. */
function whatsappReachableSync(phone: string): boolean {
  return Number(phone.slice(-1)) % 2 === 1;
}

/** Explainable, not opaque: a multi-shaft commercial building gets the
 *  Commercial Bulk terms, a premium or luxury finish gets Premium/Luxury,
 *  everything else gets Residential Standard. */
function selectQuotationTemplateVariant(quotation: Quotation, lead: Lead | null): QuotationTemplateVariant {
  if (lead?.spec?.buildingType === 'commercial_office' && lead.spec.shaftCount >= 2) return 'commercial_bulk';
  if (quotation.finishTier !== 'standard') return 'premium_luxury';
  return 'residential_standard';
}

/** The currently active template for the matching variant — never a fixed
 *  index — so an edited template is always what actually goes out. */
function selectActiveQuotationTemplate(quotation: Quotation, lead: Lead | null): QuotationTemplate | undefined {
  const variant = selectQuotationTemplateVariant(quotation, lead);
  const matches = quotationTemplates.filter((t) => t.variant === variant);
  if (matches.length === 0) return quotationTemplates[0];
  return [...matches].sort((a, b) => b.version - a.version)[0];
}

/**
 * The one place a quotation actually goes out — used for both an immediate
 * send and a scheduled one whose time has arrived. WhatsApp opt-out and a
 * bounced/unregistered number are handled the same way: the channel is
 * recorded as failed and, if an email is on file and wasn't already part of
 * the send, it's added automatically so the customer never simply hears
 * nothing. Every channel's real outcome is kept, never collapsed into one
 * ambiguous status.
 */
function executeQuotationSend(quotation: Quotation, channels: QuotationDeliveryChannel[], coverMessage: string): Quotation {
  const now = new Date().toISOString();
  const lead = resolveLead(quotation.leadId);
  const template = selectActiveQuotationTemplate(quotation, lead);
  const validityDate = new Date(Date.now() + (template?.validityPeriodDays ?? 15) * 86_400_000).toISOString();

  const deliveryResults: QuotationDeliveryResult[] = [];
  let actualChannels = [...channels];

  if (channels.includes('whatsapp')) {
    const optedOut = lead ? isOptedOutSync(lead.contactPhone, 'whatsapp') : true;
    const reachable = !optedOut && lead ? whatsappReachableSync(lead.contactPhone) : false;
    if (reachable) {
      deliveryResults.push({ channel: 'whatsapp', status: 'delivered', at: now });
    } else {
      deliveryResults.push({ channel: 'whatsapp', status: 'failed', failureReason: optedOut ? 'opted_out' : 'not_on_whatsapp', at: now });
      if (lead?.contactEmail && !actualChannels.includes('email')) {
        actualChannels = [...actualChannels, 'email'];
      }
    }
  }

  if (actualChannels.includes('email') && !deliveryResults.some((r) => r.channel === 'email')) {
    if (lead?.contactEmail) {
      deliveryResults.push({ channel: 'email', status: 'delivered', at: now });
    } else {
      deliveryResults.push({ channel: 'email', status: 'failed', failureReason: 'no_email_on_file', at: now });
    }
  }

  const updated = patchInPlace(quotations, quotation.id, {
    status: quotation.status === 'draft' || quotation.status === 'change_requested' ? ('sent' as const) : quotation.status,
    deliveryChannels: actualChannels,
    coverMessage,
    scheduledSendAt: undefined,
    sentAt: now,
    deliveryResults,
    templateId: template?.id,
    templateVersionAtSend: template?.version,
    validityDate,
  });

  // Sending is what actually transitions the lead's CRM stage to Quoted —
  // keeps the Kanban board and this action perfectly synced.
  if (lead && rankOf(lead.stage) < rankOf('quoted')) {
    patchInPlace(leads, lead.id, { stage: 'quoted', stageEnteredAt: now, updatedAt: now });
    pushTimelineEvent({ leadId: lead.id, kind: 'stage_changed', actorName: 'Automation', at: now, fromValue: lead.stage, toValue: 'quoted', detail: `Quotation ${quotation.code} sent` });
  }
  return updated;
}

/** Deterministic breakdown of a failure count across causes — no randomness,
 *  so the same send always reports the same delivery report on reload. */
function splitFailureReasons(total: number): Partial<Record<SmsFailureReason, number>> {
  const invalidNumber = Math.ceil(total * 0.5);
  const carrierBlock = Math.ceil((total - invalidNumber) * 0.6);
  const handsetUnreachable = total - invalidNumber - carrierBlock;
  const breakdown: Partial<Record<SmsFailureReason, number>> = {};
  if (invalidNumber > 0) breakdown.invalid_number = invalidNumber;
  if (carrierBlock > 0) breakdown.carrier_block = carrierBlock;
  if (handsetUnreachable > 0) breakdown.handset_unreachable = handsetUnreachable;
  return breakdown;
}

const ESCALATION_KEYWORDS = ['legal', 'lawyer', 'unsafe', 'danger', 'injur', 'complaint', 'sue', 'accident'];
const DISCOUNT_PATTERN = /(\d+(?:\.\d+)?)\s*%/;

/** A deliberately simple, deterministic heuristic — not a real ML call.
 *  Keyword-matched escalation topics always win over everything else, the
 *  bot never independently reasons its way past a configured boundary. */
function runBotSimulation(sampleMessage: string, config: BotConfig): BotSimulationResult {
  const lower = sampleMessage.toLowerCase();

  if (ESCALATION_KEYWORDS.some((kw) => lower.includes(kw))) {
    return { confidence: 0, escalate: true, escalateReasonKey: 'bot.escalate.sensitiveTopic' };
  }

  const discountMatch = lower.match(DISCOUNT_PATTERN);
  if (discountMatch) {
    const requestedPct = Number(discountMatch[1]);
    if (requestedPct > config.allowedDiscountMaxPct) {
      const confidence = 0.72;
      return {
        replyKey: 'bot.reply.discountCapped',
        replyParams: { maxPct: config.allowedDiscountMaxPct },
        confidence,
        escalate: confidence < config.escalationConfidenceThreshold,
        escalateReasonKey: confidence < config.escalationConfidenceThreshold ? 'bot.escalate.lowConfidence' : undefined,
      };
    }
    const confidence = 0.9;
    return {
      replyKey: 'bot.reply.discountApproved',
      replyParams: { pct: requestedPct },
      confidence,
      escalate: confidence < config.escalationConfidenceThreshold,
      escalateReasonKey: confidence < config.escalationConfidenceThreshold ? 'bot.escalate.lowConfidence' : undefined,
    };
  }

  const confidence = lower.length > 0 ? 0.55 : 0;
  return {
    replyKey: 'bot.reply.generic',
    confidence,
    escalate: confidence < config.escalationConfidenceThreshold,
    escalateReasonKey: confidence < config.escalationConfidenceThreshold ? 'bot.escalate.lowConfidence' : undefined,
  };
}

/** One business hour to respond before a reply counts as SLA-breached —
 *  measured with the shared, pause-fair `businessMinutesSince` clock. */
const SLA_MINUTES = 60;

const startOfMonth = () => {
  const d = new Date();
  return new Date(d.getFullYear(), d.getMonth(), 1).getTime();
};
const startOfPrevMonth = () => {
  const d = new Date();
  return new Date(d.getFullYear(), d.getMonth() - 1, 1).getTime();
};

/** Safe percentage change that doesn't blow up when the base is zero. */
const delta = (current: number, previous: number): number =>
  previous === 0 ? (current > 0 ? 1 : 0) : (current - previous) / previous;

/* ------------------------------------------------------------- Quotations */

/** Equipment base price already covers this many stops (G+3); every stop
 *  above it costs the drive type's own per-floor increment. */
const BASE_STOPS_INCLUDED = 4;

const FINISH_TIER_MULTIPLIER: Record<Quotation['finishTier'], number> = {
  standard: 1,
  premium: 1.15,
  luxury: 1.35,
};

/** Base price assumes this capacity; each person above it is a real cost
 *  driver (a bigger car, a stronger machine) the formula can't ignore. */
const CAPACITY_BASELINE_PERSONS = 6;
const CAPACITY_COST_PCT_PER_PERSON = 0.06;

const INSTALLATION_COST_PER_STOP = 12_000;
const TRANSPORT_COST_FLAT = 25_000;
const CIVIL_WORK_PCT_OF_EQUIPMENT = 0.1;

/** A government-announced GST change takes effect on its own date, not the
 *  moment an Admin schedules it — every price computed on or after that
 *  date uses the new rate automatically, with no manual step at midnight
 *  and no mutation of the configured record (screen 070's own edge case). */
/** The GST rate that applied on a given calendar day (`yyyy-mm-dd`), so a document is never restated at a rate that came later. */
function gstRateOn(day: string): number {
  const scheduled = pricingConfig.scheduledGstChange;
  return scheduled && day >= scheduled.effectiveDate.slice(0, 10) ? scheduled.newRatePct : pricingConfig.gstRatePct;
}

function effectiveGstRatePct(pricing: PricingConfig): number {
  const scheduled = pricing.scheduledGstChange;
  if (scheduled && new Date(scheduled.effectiveDate).getTime() <= Date.now()) {
    return scheduled.newRatePct;
  }
  return pricing.gstRatePct;
}

/** The one place a quote's price is computed — screens 061/062/065/067 all
 *  route through this, so a discount or spec change can never produce a
 *  number the margin floor didn't actually see. Every line is rounded to
 *  the rupee, then the total is the sum of the rounded lines, so the
 *  displayed breakdown always matches a sum-of-parts check exactly. */
function computeQuotationCost(spec: QuotationSpecInput, pricing: PricingConfig, marginOverridePct?: number): QuotationCostBreakdown {
  const basePrice = pricing.driveTypeBasePrice[spec.driveType];
  const perFloorPct = pricing.perFloorIncrementPct[spec.driveType];
  const extraStops = Math.max(0, spec.stopsCount - BASE_STOPS_INCLUDED);
  const perFloorCostDelta = Math.round(basePrice * perFloorPct);
  const capacityMultiplier = 1 + Math.max(0, spec.capacityPersons - CAPACITY_BASELINE_PERSONS) * CAPACITY_COST_PCT_PER_PERSON;
  const equipmentCost = Math.round(basePrice * FINISH_TIER_MULTIPLIER[spec.finishTier] * capacityMultiplier) + perFloorCostDelta * extraStops;
  const civilWorkEstimate = Math.round(equipmentCost * CIVIL_WORK_PCT_OF_EQUIPMENT);
  const installationLaborCost = INSTALLATION_COST_PER_STOP * spec.stopsCount;
  const transportCost = TRANSPORT_COST_FLAT;

  const baseCost = equipmentCost + civilWorkEstimate + installationLaborCost + transportCost;
  const marginPct = marginOverridePct ?? pricing.minimumMarginFloorPct + 5;
  const sellBeforeTax = Math.round(baseCost / (1 - marginPct / 100));
  const marginAmount = sellBeforeTax - baseCost;
  const gstRatePct = effectiveGstRatePct(pricing);
  const gstAmount = Math.round(sellBeforeTax * (gstRatePct / 100));
  const finalPrice = sellBeforeTax + gstAmount;

  return {
    equipmentCost,
    civilWorkEstimate,
    installationLaborCost,
    transportCost,
    perFloorCostDelta,
    gstPercent: gstRatePct,
    gstAmount,
    marginPct,
    marginAmount,
    finalPrice,
  };
}

const PRICE_BANDS: { key: string; max: number }[] = [
  { key: 'under10L', max: 1_000_000 },
  { key: '10to25L', max: 2_500_000 },
  { key: '25to50L', max: 5_000_000 },
  { key: 'above50L', max: Infinity },
];
function priceBandOf(price: number): string {
  return PRICE_BANDS.find((b) => price <= b.max)?.key ?? 'above50L';
}

const LOW_SAMPLE_THRESHOLD = 3;
function winLossStat(key: string, group: Quotation[]): QuotationWinLossStat {
  const leadsForGroup = group.map((q) => resolveLead(q.leadId)).filter((l): l is Lead => !!l);
  const decided = leadsForGroup.filter((l) => l.stage === 'won' || l.stage === 'lost');
  const won = decided.filter((l) => l.stage === 'won').length;
  return {
    key,
    quotesCount: group.length,
    wonCount: won,
    winRatePct: decided.length ? won / decided.length : 0,
    lowSample: decided.length < LOW_SAMPLE_THRESHOLD,
    quotationIds: group.map((q) => q.id),
  };
}

/** Explainable, not opaque: every non-residential building type (office,
 *  retail, hospital, hotel, industrial, institutional) is "commercial" —
 *  the split screen 069 needs so one large commercial deal never skews a
 *  blended residential price-band average. */
function buildingSegmentOf(lead: Lead | null): 'residential' | 'commercial' | 'unknown' {
  const type = lead?.spec?.buildingType;
  if (!type) return 'unknown';
  return type.startsWith('residential_') ? 'residential' : 'commercial';
}

function pushToMap<K>(map: Map<K, Quotation[]>, key: K, q: Quotation) {
  const list = map.get(key);
  if (list) list.push(q);
  else map.set(key, [q]);
}

/** The one place an approved discount turns into a real quotation version —
 *  shared by the manual approval path and the urgent-and-safe auto-approve
 *  path, so both produce exactly the same, real, superseding record. */
function applyApprovedDiscount(request: DiscountRequest, approverId: string, reasonKey: string) {
  const quotation = byId(quotations, request.quotationId);
  if (!quotation) return;
  const cost = computeQuotationCost(
    {
      driveType: quotation.driveType,
      capacityPersons: quotation.capacityPersons,
      capacityKg: quotation.capacityKg,
      stopsCount: quotation.stopsCount,
      travelHeightM: quotation.travelHeightM,
      finishTier: quotation.finishTier,
      customConfiguration: quotation.customConfiguration,
    },
    pricingConfig,
    Math.max(0.1, request.resultingMarginPct),
  );
  quotationCounter += 1;
  const now = new Date().toISOString();
  const approverName = approverId === 'system-auto' ? 'Automation' : nameOf(approverId);
  const version: Quotation = {
    ...quotation,
    id: `q-new-${quotationCounter}`,
    code: `AIEC-Q-${quotationCounter}`,
    version: quotation.version + 1,
    supersedesQuotationId: quotation.id,
    status: 'draft',
    cost,
    viewedAt: undefined,
    acceptedAt: undefined,
    sentAt: undefined,
    deliveryResults: [],
    createdBy: approverName,
    createdAt: now,
    createdReasonKey: reasonKey,
    createdReasonNote: request.reasonNote,
  };
  quotations.unshift(version);
  // A prior version with a scheduled send still pending is superseded right
  // away too — see the identical rule in createQuotationVersion.
  const hadPendingScheduledSend = Boolean(quotation.scheduledSendAt) && !quotation.sentAt;
  if (quotation.status === 'sent' || quotation.status === 'viewed' || hadPendingScheduledSend) {
    patchInPlace(quotations, quotation.id, { status: 'superseded' as const, scheduledSendAt: undefined });
    if (hadPendingScheduledSend) {
      pushTimelineEvent({
        leadId: quotation.leadId,
        kind: 'communication_failed',
        actorName: 'Automation',
        at: now,
        detail: `Scheduled send for ${quotation.code} v${quotation.version} cancelled automatically — superseded by v${version.version} before it went out`,
      });
    }
  }
  pushTimelineEvent({ leadId: quotation.leadId, kind: 'quote_created', actorName: approverName, at: now, detail: `Quotation ${version.code} v${version.version} — discount approved` });
}

/** An urgent request stays safely inside a slimmer secondary ceiling —
 *  a real margin buffer above the hard floor, not the floor itself — gets
 *  approved immediately rather than waiting on an Admin who may be
 *  unavailable right when the customer is on the phone. */
const URGENT_AUTO_APPROVE_BUFFER_PCT = 3;


/* ============================================ Manager layer: follow-up engine
 *
 * The app's own manager. Every minute (the AppShell heartbeat) it:
 *   1. runs the automations that used to wait for somebody's click,
 *   2. re-derives every dated promise from `commitmentRules` and records it
 *      as a Commitment — opening, closing, re-owning or re-dating as the
 *      source records say,
 *   3. walks each open one up its ladder: nudge the owner before due, tell
 *      them at due, tell whoever they report to after `escalateAfter`, and
 *      raise an Alert for Admin after twice that.
 * Levels only ever move forward, so running it every minute never repeats
 * a message. Written as a function of (data, now) so the same logic can move
 * onto a server scheduler when there is a backend — until then it runs only
 * while somebody has the app open, which BUILD_README calls out plainly.
 */

const commitments: Commitment[] = [];
const commitmentByKey = new Map<string, Commitment>();
let commitmentCounter = 0;
const workNotifications: WorkNotification[] = [];
let workNotificationCounter = 0;

/** The name automated sends carry as their sender. */
const ASSISTANT_ACTOR = 'AIEC Assistant';

function commitmentSources(now: number): CommitmentSources {
  return {
    now,
    users,
    leads,
    deals,
    payments,
    jobs,
    purchaseOrders: supplierPurchaseOrders,
    suppliers,
    quotations,
    dealTerms: dealTermsRecords,
    discountRequests,
    counterOffers,
    alerts,
    followUpTasks,
    catalogPriceChanges,
    orderRatings: supplierOrderRatings,
    agreementVersions: supplierAgreementVersions,
    supplierThreads,
    supplierMessages,
    supplierRetentions,
    deliverySchedules,
    shipmentLegs,
    deliveryConfirmations,
    siteCheckIns,
    jobSafetyTests,
    jobIssues,
    materialLogs: (ensureMaterialSeeds(), materialLogs),
    handoffNotes: (ensureTeamSeeds(), jobHandoffs).map((h) => ({ ...h, ownerId: handoffOwnerOf(byId(jobs, h.jobId) as Job, h) })),
    leadSignOffs: leadSignOffsWaiting(),
    qcAssignments: (ensureQcSeeds(), qcAssignments),
    qcWaiting: qcWaitingJobs(),
    qcCertificateWaiting: qcCertificateWaiting(),
    snags: (ensureSnagSeeds(), reworkRequests),
    handoverWaiting: handoverSignals().waiting,
    walkthroughs: walkthroughSignals(),
    warranties: warrantyRegistrations,
    completions: completionSignals(),
    applications: partnerApplications,
    tierDisputes: (tcEnsure(Date.now()), tierDisputes),
    tierReviews,
    certRenewals: certRenewalSignals(Date.now()),
    exits: exitSignals(),
    handoverReviews: handoverSignals().reviews,
    qcMechChecks,
    qcFindings,
    deliveryChecklists,
    delayCases,
    discrepancyReports,
    deliveryPartners,
    supplierPayments,
    invoiceGates: supplierPurchaseOrders
      .filter((po) => po.status === 'sent' && !!po.supplierId && (po.lineItems ?? []).length > 0)
      .map((po) => ({ po, deliveredAt: paymentDeliveredAt(po) }))
      .filter((x): x is { po: SupplierPurchaseOrder; deliveredAt: string } => !!x.deliveredAt)
      .map(({ po, deliveredAt }) => ({ poId: po.id, supplierId: po.supplierId!, deliveredAt, gate: invoiceGateOfPo(po) })),
    invoiceMismatches: supplierInvoices
      .filter((i) => !!i.mismatchNotifiedAt)
      .map((i) => ({
        invoiceId: i.id,
        poId: i.poId,
        supplierId: i.supplierId,
        invoiceNumber: i.invoiceNumber,
        notifiedAt: i.mismatchNotifiedAt!,
        stillMismatched: i.status === 'open' && evaluateInvoice(i).status === 'mismatch',
        resolvedAt: i.rejectedAt ?? i.events.filter((e) => e.kind === 'adjustment_accepted').map((e) => e.at).sort().pop(),
      })),
    supplierDisputes,
    reconciliationExceptions: reconExceptions,
    bankFeed,
    advanceRecoveries,
    retentionsReady: retentionItemsOf(now)
      .filter((r) => r.bulkOk && r.job?.completedAt)
      .map((r) => ({ retentionId: r.id, poCode: r.poCode, supplierName: r.supplierName, amount: r.amount, readyAt: r.job!.completedAt! })),
    gstPeriods: gstPeriodsOwed(now),
    gstStatusChecks: gstStatusChecksOwed(),
    pausedDealIds: new Set(paymentReminderPauses.filter((p) => p.paused).map((p) => p.dealId)),
  };
}

/** The last three closed months that had any tax activity, and whether each has gone to the accountant. */
function gstPeriodsOwed(now: number): { period: string; handedOver: boolean; handedOverAt?: string }[] {
  ensureGstHandovers(now);
  const docs = gstDocumentsOf(now);
  return [1, 2, 3]
    .map((n) => shiftPeriod(periodOf(now), -n))
    .filter((period) => docs.some((d) => docPeriod(d.date) === period))
    .map((period) => {
      const h = gstHandovers.find((x) => x.period === period);
      return { period, handedOver: !!h, handedOverAt: h?.handedOverAt };
    });
}

/** Trading suppliers with a GSTIN whose standing has to be looked at again a month after the last look. */
function gstStatusChecksOwed(): { supplierId: string; name: string; lastCheckedAt: string | null; since: string }[] {
  const trade = gstTradeSupplierIds();
  return suppliers
    .filter((sp) => trade.has(sp.id) && !!sp.gstin)
    .map((sp) => {
      const last = latestGstCheck(sp.id);
      const first = [...supplierInvoices.filter((i) => i.supplierId === sp.id).map((i) => i.submittedAt), ...supplierPurchaseOrders.filter((po) => po.supplierId === sp.id && po.sentAt).map((po) => po.sentAt!)].sort()[0];
      return { supplierId: sp.id, name: sp.name, lastCheckedAt: last?.checkedAt ?? null, since: first ?? new Date().toISOString() };
    });
}

function putCommitment(next: Commitment): Commitment {
  const index = commitments.findIndex((c) => c.id === next.id);
  if (index === -1) commitments.push(next);
  else commitments[index] = next;
  commitmentByKey.set(next.key, next);
  return next;
}

function notifyWork(userId: string, commitment: Commitment, kind: WorkNotification['kind'], at: string): void {
  workNotificationCounter += 1;
  workNotifications.push({ id: `wn-${workNotificationCounter}`, userId, commitmentId: commitment.id, kind, at, isDemo: true });
}

/** Everything the engine can see right now, recorded as Commitments. */
function syncCommitments(now: number): void {
  const at = new Date(now).toISOString();
  const seen = new Set<string>();
  for (const ob of collectObligations(commitmentSources(now))) {
    seen.add(ob.key);
    const existing = commitmentByKey.get(ob.key);
    const derived = {
      kind: ob.kind,
      ownerUserId: ob.ownerUserId,
      subject: ob.subject,
      titleKey: ob.titleKey,
      titleParams: ob.titleParams,
      amount: ob.amount,
      dueAt: ob.dueAt,
      paused: ob.paused,
      actionRoute: ob.actionRoute,
      oversightRoute: ob.oversightRoute,
    };
    if (!existing) {
      // History is recorded only when the source says when it was done —
      // reliability is never computed from a guessed completion time.
      if (ob.state === 'cancelled' || (ob.state === 'done' && !ob.completedAt)) continue;
      commitmentCounter += 1;
      putCommitment({
        id: `cm-${commitmentCounter}`,
        key: ob.key,
        ...derived,
        status: ob.state,
        escalationLevel: 0,
        createdAt: at,
        completedAt: ob.state === 'done' ? ob.completedAt : undefined,
        isDemo: true,
      });
      continue;
    }
    if (ob.state !== 'open') {
      if (existing.status === 'open') {
        putCommitment({ ...existing, ...derived, status: ob.state, completedAt: ob.state === 'done' ? (ob.completedAt ?? at) : undefined });
      }
      continue;
    }
    // Open. A new owner or a new due date is a new promise: the ladder
    // restarts so the person now holding it hears about it themselves.
    const repromised = existing.status !== 'open' || existing.ownerUserId !== ob.ownerUserId || existing.dueAt !== ob.dueAt;
    putCommitment({
      ...existing,
      ...derived,
      status: 'open',
      completedAt: undefined,
      escalationLevel: repromised ? 0 : existing.escalationLevel,
      escalatedToUserId: repromised ? undefined : existing.escalatedToUserId,
    });
  }
  // A subject that disappeared entirely (merged lead, deleted draft) can't
  // be owed any more.
  for (const commitment of commitments) {
    if (commitment.status === 'open' && !seen.has(commitment.key)) putCommitment({ ...commitment, status: 'cancelled' });
  }
}

/** Who hears when this owner's promise runs late: their manager, or — for
 *  Admin — their named backup, if the business has chosen one. */
function escalationRecipientFor(ownerUserId: string): string | undefined {
  const owner = byId(users, ownerUserId);
  if (!owner) return users.find((u) => u.role === 'admin')?.id;
  if (owner.role === 'admin') return owner.backupUserId;
  return owner.reportsTo ?? users.find((u) => u.role === 'admin' && u.status === 'active')?.id;
}

function commitmentLabel(c: Commitment): string {
  return c.titleParams.code ?? c.titleParams.site ?? c.subject.id;
}

/** Moves every open, un-paused commitment up to the rung `now` has earned. */
function advanceEscalations(now: number): { notifications: number; alerts: number } {
  const at = new Date(now).toISOString();
  let notifications = 0;
  let alertsRaised = 0;
  for (const commitment of [...commitments]) {
    if (commitment.status !== 'open' || commitment.paused) continue;
    const rule = RULE_BY_KIND[commitment.kind];
    const owner = byId(users, commitment.ownerUserId);
    const target = targetEscalationLevel(rule, commitment.dueAt, now, owner?.role === 'admin');
    if (target <= commitment.escalationLevel) continue;
    let escalatedToUserId = commitment.escalatedToUserId;
    for (let level = commitment.escalationLevel + 1; level <= target; level += 1) {
      // Catching up on something already late: a "coming up" heads-up for
      // it would be noise, so the owner hears "overdue" and nothing else.
      if (level === 1 && target >= 2) continue;
      if (level === 1 || level === 2) {
        notifyWork(commitment.ownerUserId, commitment, level === 1 ? 'nudge' : 'overdue', at);
        notifications += 1;
        logAutomatedAction({
          sourceKey: level === 1 ? 'followup.nudge' : 'followup.overdue',
          triggeringCondition: `${commitment.kind} ${commitmentLabel(commitment)} ${level === 1 ? 'is coming due' : 'passed its due time'}`,
          actionTaken: `Told ${nameOf(commitment.ownerUserId)}`,
          affectedRecordId: commitment.id,
          affectedRecordType: 'commitment',
          subjectLabel: commitmentLabel(commitment),
        });
      } else if (level === 3) {
        const recipient = escalationRecipientFor(commitment.ownerUserId);
        if (recipient && recipient !== commitment.ownerUserId) {
          escalatedToUserId = recipient;
          notifyWork(recipient, commitment, 'escalated', at);
          notifications += 1;
          logAutomatedAction({
            sourceKey: 'followup.escalate',
            triggeringCondition: `${commitment.kind} ${commitmentLabel(commitment)} still open ${Math.round(rule.escalateAfter / 3_600_000)}h past due`,
            actionTaken: `Escalated from ${nameOf(commitment.ownerUserId)} to ${nameOf(recipient)}`,
            affectedRecordId: commitment.id,
            affectedRecordType: 'commitment',
            subjectLabel: commitmentLabel(commitment),
          });
        }
      } else if (level === 4) {
        const daysLate = Math.max(1, Math.floor((now - new Date(commitment.dueAt).getTime()) / 86_400_000));
        const alert = raiseAlert({
          titleKey: 'work.alert.stuck',
          context: `${commitmentLabel(commitment)} — ${nameOf(commitment.ownerUserId)}, ${daysLate}d past due`,
          severity: 'medium',
          category: rule.alertCategory,
          relatedId: commitment.id,
          sourceRoute: commitment.oversightRoute,
        });
        alertsRaised += 1;
        logAutomatedAction({
          sourceKey: 'followup.alert',
          triggeringCondition: `${commitment.kind} ${commitmentLabel(commitment)} still open ${Math.round((2 * rule.escalateAfter) / 3_600_000)}h past due`,
          actionTaken: `Raised ${alert.code} for Admin`,
          affectedRecordId: commitment.id,
          affectedRecordType: 'commitment',
          subjectLabel: commitmentLabel(commitment),
        });
      }
    }
    putCommitment({ ...commitment, escalationLevel: target as EscalationLevel, escalatedToUserId, lastActionAt: at });
  }
  return { notifications, alerts: alertsRaised };
}

/** Quotes someone scheduled for later (068) actually go out when their time
 *  comes — previously the schedule was stored and nothing ever sent it. */
function sendDueScheduledQuotations(now: number): void {
  for (const quotation of [...quotations]) {
    if (!quotation.scheduledSendAt || quotation.sentAt || quotation.status === 'superseded') continue;
    if (new Date(quotation.scheduledSendAt).getTime() > now) continue;
    const sent = executeQuotationSend(quotation, quotation.deliveryChannels, quotation.coverMessage ?? '');
    logAutomatedAction({
      sourceKey: 'quotation.scheduled_send',
      triggeringCondition: `${quotation.code} v${quotation.version} reached its scheduled send time`,
      actionTaken: `Sent on ${sent.deliveryChannels.join(' + ') || 'no reachable channel'}`,
      affectedRecordId: quotation.id,
      affectedRecordType: 'quotation',
      subjectLabel: quotation.code,
    });
  }
}

function runFollowUpEngineSync(now: number): FollowUpEngineRun {
  const actionsBefore = automatedActionLog.length;
  reconcileFollowUpTasks();
  runPaymentReminders(ASSISTANT_ACTOR, now);
  sendDueScheduledQuotations(now);
  autoDraftDuePurchaseOrders();
  detectProductionStalls(now);
  settleRetentions(now);
  syncPartnerFeeds(now);
  syncSupplierPayments(now);
  executeSupplierPayments(now);
  syncPaymentAnomalies(now);
  syncInvoiceMismatches(now);
  syncGstCompliance(now);
  syncSupplierDisputes(now);
  syncSupplierReviewFlags(now);
  syncReconciliation(now);
  sendDueSos(now);
  syncTechnicianClashes(now);
  syncRecruitmentIntake(now);
  syncPartnerExits(now);
  syncAssessmentAlerts(now);
  syncCertifications(now);
  syncPartnerInterviews(now);
  syncVerification(now);
  syncOffers(now);
  syncSafetyAlerts(true, now);
  syncIssueAlerts(true, now);
  syncMaterialDeviations(true, now);
  syncTeamAlerts(true, now);
  syncQcAssignments(true, now);
  syncQcMechAlerts(now);
  syncQcElecAlerts(now);
  syncSnagAlerts(now);
  syncWarrantyReminders(now);
  syncLeadDelegations(now);
  for (const j of jobs) syncIssueHold(j);
  syncSopHandoff();
  syncAdvanceExposure(now);
  advanceShipments(now);
  // 105: a delivery running late is noticed, and one that caught up is cleared, without anyone looking.
  syncDelayCases(now);
  for (const deal of deals) {
    if (payments.some((p) => p.dealId === deal.id && p.status === 'paid' && !invoices.some((inv) => inv.paymentId === p.id))) {
      ensureStageInvoices(deal.id, deal, resolveLead(deal.leadId));
    }
  }
  syncCommitments(now);
  const { notifications, alerts: alertsRaised } = advanceEscalations(now);
  // Alerts the ladder just raised are themselves owed an acknowledgement.
  if (alertsRaised > 0) syncCommitments(now);
  return {
    at: new Date(now).toISOString(),
    openCommitments: commitments.filter((c) => c.status === 'open').length,
    notificationsSent: notifications,
    alertsRaised,
    automatedActions: automatedActionLog.length - actionsBefore,
  };
}

/** End of the reader's local day — "due today" means today on their clock. */
function endOfToday(now: number): number {
  const end = new Date(now);
  end.setHours(23, 59, 59, 999);
  return end.getTime();
}

const MY_WORK_HORIZON_DAYS = 7;

function toWorkItem(commitment: Commitment, now: number): WorkItem {
  const due = new Date(commitment.dueAt).getTime();
  return {
    commitment,
    dueState: due < now ? 'overdue' : due <= endOfToday(now) ? 'due_today' : 'upcoming',
    ownerName: nameOf(commitment.ownerUserId),
    escalatedToName: commitment.escalatedToUserId ? nameOf(commitment.escalatedToUserId) : undefined,
    quickAction: RULE_BY_KIND[commitment.kind].quickAction,
  };
}

const byDueThenAmount = (a: Commitment, b: Commitment) =>
  a.dueAt === b.dueAt ? (b.amount ?? 0) - (a.amount ?? 0) : a.dueAt < b.dueAt ? -1 : 1;

function completeFollowUpTaskSync(id: string, actorName: string) {
  const now = new Date().toISOString();
  const task = patchInPlace(followUpTasks, id, { status: 'done', completedAt: now });
  pushTimelineEvent({ leadId: task.leadId, kind: 'task_completed', actorName, at: now, detail: task.title });
  return task;
}

/**
 * The one write path for a sent PO's fulfilment status (095) — the board,
 * the supplier's own updates, Admin's on-behalf updates and the assistant's
 * one-tap "acknowledge" / "confirm received" all come through here, so a PO
 * has one true status. Forward and backward (rework) both allowed; every
 * change is an append-only event.
 */
function movePoLinesSync(
  poId: string,
  lineIds: string[] | 'all',
  toStage: PoFulfilmentStage,
  actor: User,
  note?: string,
  /** Set by the on-site checklist (103): whoever stood at the tailgate may say
   *  "delivered", because the checklist itself is the evidence. */
  checklistId?: string,
): SupplierPurchaseOrder {
  const po = byId(supplierPurchaseOrders, poId);
  if (!po) throw new RepositoryError('not_found');
  if (po.status !== 'sent') throw new RepositoryError('not_sent');
  const supplier = po.supplierId ? byId(suppliers, po.supplierId) : null;
  const isAdmin = actor.role === 'admin';
  const verifiedOnSite = !!checklistId && toStage === 'delivered';
  if (!isAdmin && !verifiedOnSite) {
    if (actor.role !== 'supplier' || !supplier || supplierUserFor(supplier)?.id !== actor.id) throw new RepositoryError('forbidden');
    if (!SUPPLIER_SETTABLE_STAGES.includes(toStage)) throw new RepositoryError('forbidden_stage');
  }
  const lines = po.lineItems ?? [];
  const targets = lines.filter((l) => (lineIds === 'all' || lineIds.includes(l.id)) && lineStageOf(po, l) !== toStage);
  if (targets.length === 0) return po;
  // A supplier can't reopen a part AIEC has already received.
  if (!isAdmin && targets.some((l) => lineStageOf(po, l) === 'delivered')) throw new RepositoryError('forbidden_stage');
  const backward = targets.some((l) => stageIndex(lineStageOf(po, l)) > stageIndex(toStage));
  // Admin recording a supplier-side stage is standing in for the supplier.
  const onBehalf = isAdmin && toStage !== 'delivered';
  if ((backward || onBehalf) && !note?.trim()) throw new RepositoryError('note_required');

  const now = new Date().toISOString();
  const byFromStage = new Map<PoFulfilmentStage, string[]>();
  for (const line of targets) {
    const from = lineStageOf(po, line);
    byFromStage.set(from, [...(byFromStage.get(from) ?? []), line.id]);
  }
  const events = [...(po.statusEvents ?? [])];
  for (const [fromStage, ids] of byFromStage) {
    events.push({
      id: `${po.id}-e${events.length + 1}`,
      lineItemIds: ids,
      fromStage,
      toStage,
      at: now,
      byName: actor.name,
      byRole: isAdmin ? 'admin' : actor.role === 'technician' ? 'technician' : 'supplier',
      onBehalf,
      note: note?.trim() || undefined,
      checklistId,
    });
  }
  const targetIds = new Set(targets.map((l) => l.id));
  const nextLines = lines.map((l) =>
    targetIds.has(l.id)
      ? { ...l, fulfilmentStage: toStage, stageEnteredAt: now }
      : { ...l, fulfilmentStage: lineStageOf(po, l), stageEnteredAt: lineStageEnteredAt(po, l) },
  );
  const allDelivered = nextLines.every((l) => l.fulfilmentStage === 'delivered');
  const anyPastSent = nextLines.some((l) => l.fulfilmentStage !== 'sent');
  // Fully delivered for the first time: the order gets its rating (097) —
  // timeliness is objective; defects and Admin's judgement follow.
  if (allDelivered && !po.receivedAt) {
    createOrderRating(po, now);
    // 100: hold back the retention share until the installation is handed over.
    holdRetention(po, now);
  }
  // Entering production opens (or, after rework, reopens) the line's
  // manufacturer production record (096) — the same status, seen closer up.
  if (toStage === 'in_production' && supplier?.isManufacturer) {
    for (const line of targets) syncProductionOnEnter(po, line, actor, note, now);
  }
  return patchInPlace(supplierPurchaseOrders, poId, {
    lineItems: nextLines,
    statusEvents: events,
    // The fields the manager layer and 092 already read stay in step.
    acknowledgedAt: po.acknowledgedAt ?? (anyPastSent ? now : undefined),
    acknowledgedBy: po.acknowledgedBy ?? (anyPastSent ? actor.name : undefined),
    receivedAt: allDelivered ? (po.receivedAt ?? now) : undefined,
    receivedBy: allDelivered ? (po.receivedBy ?? actor.name) : undefined,
  });
}

function acknowledgePurchaseOrderSync(poId: string, byUserId: string) {
  const po = byId(supplierPurchaseOrders, poId);
  if (!po) throw new RepositoryError('not_found');
  if (po.acknowledgedAt) return po;
  const actor = catalogActor(byUserId);
  const sentLines = (po.lineItems ?? []).filter((l) => lineStageOf(po, l) === 'sent').map((l) => l.id);
  // Admin acknowledging for a supplier without a login is on their behalf.
  return movePoLinesSync(poId, sentLines, 'acknowledged', actor, actor.role === 'admin' ? 'Acknowledged by phone on the supplier’s behalf' : undefined);
}

/* ============================================= Supplier catalog (093) */

function catalogActor(userId: string): User {
  const actor = byId(users, userId);
  if (!actor) throw new RepositoryError('not_found');
  return actor;
}

/** A supplier edits only their own catalog; Admin edits any. */
function assertCatalogAccess(actor: User, supplierId: string): Supplier {
  const supplier = byId(suppliers, supplierId);
  if (!supplier) throw new RepositoryError('not_found');
  if (actor.role === 'admin') return supplier;
  if (actor.role === 'supplier' && supplierUserFor(supplier)?.id === actor.id) return supplier;
  throw new RepositoryError('forbidden');
}

function pushCatalogPriceChange(input: Omit<CatalogPriceChange, 'id' | 'isDemo'>): CatalogPriceChange {
  catalogPriceChangeCounter += 1;
  const change: CatalogPriceChange = { ...input, id: `cpc-new-${catalogPriceChangeCounter}`, isDemo: true };
  catalogPriceChanges.push(change);
  return change;
}

/** A newer ask replaces an older one still waiting — never two in the queue. */
function supersedePendingChange(item: SupplierCatalogItem): void {
  if (!item.pendingPriceChangeId) return;
  const pending = byId(catalogPriceChanges, item.pendingPriceChangeId);
  if (pending?.status === 'pending') patchInPlace(catalogPriceChanges, pending.id, { status: 'superseded' });
}

/** 091's category chips follow what a supplier actually lists live. */
function ensureSupplierCategory(supplierId: string, category: string): void {
  const supplier = byId(suppliers, supplierId);
  if (supplier && !supplier.categories.includes(category)) {
    patchInPlace(suppliers, supplierId, { categories: [...supplier.categories, category] });
  }
}

/** Refuses what can't be right, flags what looks wrong. */
function checkAgainstCatalog(entry: CatalogEntryInput, excludeItemId?: string) {
  return checkCatalogEntry(entry, categoryReferencePrices(supplierCatalogItems.filter((i) => i.id !== excludeItemId)));
}

/**
 * The one write path for a catalog listing, single or bulk.
 *
 * - Admin's own edits go live — Admin is the reviewer.
 * - A supplier's price change beyond the configured threshold, or anything
 *   the sanity check flagged, waits: the item's other details go live, the
 *   live price stays put until Admin approves. A flagged *new* listing
 *   waits as a whole (`pending_review`) and can't be drafted onto a PO.
 * - A bulk upload's flagged rows always wait, whoever uploads them.
 */
function saveCatalogEntrySync(
  supplier: Supplier,
  entry: CatalogEntryInput,
  existing: SupplierCatalogItem | null,
  actor: User,
  source: CatalogPriceChangeSource,
): CatalogSaveResult {
  const check = checkAgainstCatalog(entry, existing?.id);
  if (check.errors.length > 0) throw new RepositoryError('invalid_entry');
  const now = new Date().toISOString();
  const isAdmin = actor.role === 'admin';
  const flagged = check.warnings;
  const flaggedNeedsReview = flagged.length > 0 && (!isAdmin || source === 'bulk_upload');
  const details = {
    description: entry.description.trim(),
    specification: entry.specification.trim(),
    driveTypes: entry.driveTypes as DriveType[],
    leadTimeDays: entry.leadTimeDays,
    updatedAt: now,
  };

  // A brand-new listing, or a flagged one not yet cleared (re-checked fresh).
  if (!existing || existing.status === 'pending_review') {
    if (existing) supersedePendingChange(existing);
    const itemId = existing?.id ?? `sci-new-${(catalogItemCounter += 1)}`;
    const change = pushCatalogPriceChange({
      itemId,
      supplierId: supplier.id,
      fromPrice: null,
      toPrice: entry.unitPrice,
      source,
      requestedBy: actor.name,
      requestedAt: now,
      status: flaggedNeedsReview ? 'pending' : 'applied',
      reviewReasonKeys: flaggedNeedsReview ? flagged : undefined,
    });
    const fields = {
      ...details,
      unitPrice: entry.unitPrice,
      status: flaggedNeedsReview ? ('pending_review' as const) : ('active' as const),
      pendingPrice: undefined,
      pendingPriceChangeId: flaggedNeedsReview ? change.id : undefined,
    };
    const item = existing
      ? patchInPlace(supplierCatalogItems, existing.id, fields)
      : (() => {
          const created: SupplierCatalogItem = { id: itemId, supplierId: supplier.id, category: entry.category.trim(), ...fields, isDemo: true };
          supplierCatalogItems.push(created);
          return created;
        })();
    if (!flaggedNeedsReview) ensureSupplierCategory(supplier.id, item.category);
    return { item, outcome: flaggedNeedsReview ? 'item_pending_review' : 'saved' };
  }

  if (entry.unitPrice === existing.unitPrice) {
    // A supplier re-stating the live price withdraws their own waiting ask;
    // Admin editing other details leaves the supplier's ask for review.
    if (isAdmin) {
      return { item: patchInPlace(supplierCatalogItems, existing.id, details), outcome: 'saved' };
    }
    supersedePendingChange(existing);
    const item = patchInPlace(supplierCatalogItems, existing.id, { ...details, pendingPrice: undefined, pendingPriceChangeId: undefined });
    return { item, outcome: 'saved' };
  }

  // Same ask as the one already waiting — only the other details changed.
  if (!isAdmin && existing.pendingPrice === entry.unitPrice && existing.pendingPriceChangeId) {
    return { item: patchInPlace(supplierCatalogItems, existing.id, details), outcome: 'price_pending_review' };
  }

  const reasons = [...(flaggedNeedsReview ? flagged : [])];
  if (!isAdmin && isMaterialPriceChange(existing.unitPrice, entry.unitPrice, catalogSettings.priceReviewThresholdPct)) {
    reasons.push('over_threshold');
  }
  supersedePendingChange(existing);
  const waits = reasons.length > 0;
  const change = pushCatalogPriceChange({
    itemId: existing.id,
    supplierId: supplier.id,
    fromPrice: existing.unitPrice,
    toPrice: entry.unitPrice,
    source,
    requestedBy: actor.name,
    requestedAt: now,
    status: waits ? 'pending' : 'applied',
    reviewReasonKeys: waits ? reasons : undefined,
  });
  const item = patchInPlace(
    supplierCatalogItems,
    existing.id,
    waits
      ? { ...details, pendingPrice: entry.unitPrice, pendingPriceChangeId: change.id }
      : { ...details, unitPrice: entry.unitPrice, pendingPrice: undefined, pendingPriceChangeId: undefined },
  );
  return { item, outcome: waits ? 'price_pending_review' : 'saved' };
}

interface BulkPlanRow {
  row: CatalogBulkPreviewRow;
  entry: CatalogEntryInput;
  existing: SupplierCatalogItem | null;
}

/** The same verdicts `applyCatalogBulkUpload` then acts on — preview never lies. */
function planCatalogBulkUpload(supplier: Supplier, csvText: string, actor: User): BulkPlanRow[] {
  const own = supplierCatalogItems.filter((i) => i.supplierId === supplier.id && i.status !== 'rejected');
  const seen = new Set<string>();
  return parseCatalogCsv(csvText).map(({ rowNumber, entry }) => {
    const key = catalogMatchKey(entry.category, entry.description);
    const existing = own.find((i) => catalogMatchKey(i.category, i.description) === key) ?? null;
    const check = checkAgainstCatalog(entry, existing?.id);
    const issues: string[] = [...check.errors];
    if (seen.has(key)) issues.push('duplicate_in_upload');
    // Bringing a discontinued part back is a deliberate reactivation, not
    // something a spreadsheet row should do silently.
    if (existing?.status === 'discontinued') issues.push('item_discontinued');
    seen.add(key);
    const unchanged =
      existing !== null &&
      existing.status === 'active' &&
      existing.unitPrice === entry.unitPrice &&
      existing.leadTimeDays === entry.leadTimeDays &&
      existing.specification === entry.specification.trim() &&
      existing.driveTypes.join('|') === entry.driveTypes.join('|');
    let verdict: CatalogBulkPreviewRow['verdict'] = 'ok';
    if (issues.length > 0) verdict = 'invalid';
    else if (check.warnings.length > 0) {
      verdict = 'review';
      issues.push(...check.warnings);
    } else if (
      existing &&
      actor.role !== 'admin' &&
      existing.unitPrice !== entry.unitPrice &&
      isMaterialPriceChange(existing.unitPrice, entry.unitPrice, catalogSettings.priceReviewThresholdPct)
    ) {
      verdict = 'review';
      issues.push('over_threshold');
    }
    return {
      entry,
      existing,
      row: {
        rowNumber,
        category: entry.category,
        description: entry.description,
        unitPrice: entry.unitPrice,
        leadTimeDays: entry.leadTimeDays,
        action: existing ? (unchanged ? 'unchanged' : 'update') : 'create',
        verdict,
        issues,
        currentPrice: existing?.unitPrice,
      },
    };
  });
}

function lowestLivePriceByCategory(): Map<string, number> {
  const lowest = new Map<string, number>();
  for (const item of supplierCatalogItems) {
    if (item.status !== 'active') continue;
    const current = lowest.get(item.category);
    if (current === undefined || item.unitPrice < current) lowest.set(item.category, item.unitPrice);
  }
  return lowest;
}

function inFlightPoCountFor(item: SupplierCatalogItem): number {
  return supplierPurchaseOrders.filter(
    (po) =>
      po.supplierId === item.supplierId &&
      po.status !== 'triggered' &&
      po.status !== 'failed' &&
      !po.receivedAt &&
      (po.lineItems ?? []).some((line) => line.category === item.category),
  ).length;
}

const pctOver = (price: number, base: number | null | undefined) =>
  base ? Math.round(((price - base) / base) * 1000) / 10 : null;


/* ===================================== Manufacturer production (096) */

const productionIdFor = (lineItemId: string) => `prod-${lineItemId}`;

function newProductionRecord(po: SupplierPurchaseOrder, line: PurchaseOrderLineItem, at: string): ProductionRecord {
  const stages = stagesForCategory(line.category);
  const record: ProductionRecord = {
    id: productionIdFor(line.id),
    poId: po.id,
    lineItemId: line.id,
    supplierId: po.supplierId ?? '',
    stages,
    currentStage: stages[0],
    stageEnteredAt: at,
    startedAt: at,
    evidence: [],
    events: [],
    isDemo: true,
  };
  productionRecords.push(record);
  return record;
}

/** A line entering "in production": start its record, or — if production
 *  had finished and the line came back for rework — reopen it at quality
 *  testing with the reason, never a silent stall. */
function syncProductionOnEnter(po: SupplierPurchaseOrder, line: PurchaseOrderLineItem, actor: User, note: string | undefined, at: string): void {
  const existing = byId(productionRecords, productionIdFor(line.id));
  if (!existing) {
    newProductionRecord(po, line, at);
    return;
  }
  if (existing.currentStage !== 'complete') return;
  const reopenAt: ProductionStage = existing.stages.includes('quality_testing') ? 'quality_testing' : existing.stages[0];
  patchInPlace(productionRecords, existing.id, {
    currentStage: reopenAt,
    stageEnteredAt: at,
    completedAt: undefined,
    events: [
      ...existing.events,
      { id: `pe-${existing.id}-${existing.events.length + 1}`, kind: 'regressed', fromStage: 'complete', toStage: reopenAt, at, byName: actor.name, byRole: actor.role === 'admin' ? 'admin' : 'supplier', reason: note },
    ],
  });
}

/** The manufacturer's own login, or Admin — anyone else is refused. */
function assertProductionAccess(record: ProductionRecord, actor: User): void {
  if (actor.role === 'admin') return;
  const supplier = byId(suppliers, record.supplierId);
  if (actor.role === 'supplier' && supplier && supplierUserFor(supplier)?.id === actor.id) return;
  throw new RepositoryError('forbidden');
}

function lineFor(record: ProductionRecord) {
  const po = byId(supplierPurchaseOrders, record.poId);
  const line = po?.lineItems?.find((l) => l.id === record.lineItemId);
  return { po, line };
}

function productionEvent(record: ProductionRecord, actor: User, fields: Omit<ProductionRecord['events'][number], 'id' | 'at' | 'byName' | 'byRole'>, at: string) {
  return { id: `pe-${record.id}-${record.events.length + 1}-${(productionCounter += 1)}`, at, byName: actor.name, byRole: actor.role === 'admin' ? ('admin' as const) : ('supplier' as const), ...fields };
}

/** One record's sign-off; returns the updated record. */
function advanceOne(record: ProductionRecord, actor: User, note: string | undefined, at: string, viaBatch: boolean): ProductionRecord {
  const next = nextStage(record);
  if (!next) throw new RepositoryError('already_complete');
  if (EVIDENCE_REQUIRED_STAGES.includes(record.currentStage) && !record.evidence.some((e) => e.stage === record.currentStage)) {
    throw new RepositoryError('evidence_required');
  }
  const updated = patchInPlace(productionRecords, record.id, {
    currentStage: next,
    stageEnteredAt: at,
    completedAt: next === 'complete' ? at : undefined,
    events: [...record.events, productionEvent(record, actor, { kind: 'advanced', fromStage: record.currentStage, toStage: next, reason: note?.trim() || undefined, viaBatch }, at)],
  });
  // Production done is the line's "ready to ship" — one true status (095).
  if (next === 'complete') {
    const { po, line } = lineFor(record);
    if (po && line && stageIndex(lineStageOf(po, line)) < stageIndex('ready_to_ship')) {
      movePoLinesSync(po.id, [line.id], 'ready_to_ship', actor, actor.role === 'admin' ? (note?.trim() || 'Production completed') : undefined);
    }
  }
  return updated;
}

/** Stalls surface in the Alerts dashboard by themselves (heartbeat), judged
 *  against the manufacturer's own usual pace — and clear themselves once
 *  production moves on. */
function detectProductionStalls(now: number): void {
  for (const record of productionRecords) {
    const { po, line } = lineFor(record);
    if (!po || !line || po.status !== 'sent') continue;
    const stall = assessStall(record, productionRecords, now);
    const open = alerts.find((a) => a.relatedId === record.id && a.titleKey === 'production.alert.stalled' && a.status !== 'resolved');
    if (stall.stalled && !open) {
      const alert = raiseAlert({
        titleKey: 'production.alert.stalled',
        context: `${po.code} · ${line.description} · ${record.currentStage.replace(/_/g, ' ')} for ${stall.daysInStage}d (usually ${stall.expectedDays}d)`,
        severity: 'medium',
        category: 'supplier',
        relatedId: record.id,
        sourceRoute: `/orders/production/${record.id}`,
      });
      logAutomatedAction({
        sourceKey: 'production.stall_alert',
        triggeringCondition: `${line.description} on ${po.code} passed ×1.5 its manufacturer's usual ${record.currentStage} time`,
        actionTaken: `Raised ${alert.code}`,
        affectedRecordId: record.id,
        affectedRecordType: 'purchase_order',
        subjectLabel: po.code,
      });
    } else if (!stall.stalled && open) {
      patchInPlace(alerts, open.id, {
        status: 'resolved',
        resolvedAt: new Date(now).toISOString(),
        resolvedBy: 'system',
        resolutionNote: `Production moved on to ${record.currentStage.replace(/_/g, ' ')}.`,
      });
    }
  }
}


/* =============================== Supplier rating & quality scorecard (097) */

/* ============================================== Shipment tracking (102) */

interface ShipmentViewer {
  actor: User;
  supplierId: string | null;
}

function shipmentViewerOf(byUserId: string): ShipmentViewer {
  const actor = catalogActor(byUserId);
  if (!['admin', 'supplier', 'customer', 'technician'].includes(actor.role)) throw new RepositoryError('forbidden');
  if (actor.role === 'supplier') {
    const own = suppliers.find((sp) => supplierUserFor(sp)?.id === actor.id);
    if (!own) throw new RepositoryError('forbidden');
    return { actor, supplierId: own.id };
  }
  return { actor, supplierId: null };
}

function legVisibleTo(leg: ShipmentLeg, viewer: ShipmentViewer): boolean {
  const { actor } = viewer;
  if (actor.role === 'admin') return true;
  if (actor.role === 'supplier') return leg.supplierId === viewer.supplierId;
  if (actor.role === 'customer') return byId(deals, leg.dealId)?.customerId === actor.id;
  // A technician follows the deliveries for the sites they're installing.
  return jobs.some((j) => j.dealId === leg.dealId && j.technicianId === actor.id && j.status !== 'completed');
}

function shipmentSite(dealId: string): { lat: number; lng: number; siteName: string } | null {
  const deal = byId(deals, dealId);
  const lead = deal ? resolveLead(deal.leadId) : null;
  return lead ? { lat: lead.location.lat, lng: lead.location.lng, siteName: lead.siteName } : null;
}

const routeOfLeg = (leg: ShipmentLeg) => {
  const site = shipmentSite(leg.dealId);
  return routeFor(leg.origin, site ?? leg.origin);
};

function shipmentLabelOf(leg: ShipmentLeg): string {
  const po = byId(supplierPurchaseOrders, leg.poId);
  const names = (po?.lineItems ?? []).filter((l) => leg.lineItemIds.includes(l.id)).map((l) => l.description.toLowerCase());
  return names.length ? names.join(', ') : 'delivery';
}

/** A milestone message to the customer through the Communication Engine.
 *  Once per milestone, however often it runs, and never to someone who has
 *  opted out. */
function notifyCustomerOfMilestone(legId: string, milestone: ShipmentMilestone): void {
  const leg = byId(shipmentLegs, legId);
  const event = leg?.milestones.find((e) => e.milestone === milestone);
  if (!leg || !event || event.customerNotifiedAt || event.customerNotifySkipped) return;
  const deal = byId(deals, leg.dealId);
  const lead = deal ? resolveLead(deal.leadId) : null;
  const po = byId(supplierPurchaseOrders, leg.poId);
  const mark = (patch: Partial<ShipmentMilestoneEvent>) =>
    patchInPlace(shipmentLegs, leg.id, { milestones: leg.milestones.map((e) => (e.milestone === milestone ? { ...e, ...patch } : e)) });
  if (!lead) {
    mark({ customerNotifySkipped: 'no_contact' });
    return;
  }
  const language = lead.preferredLanguage ?? 'en';
  const groupId = `tpl-ship-${milestone === 'in_transit' ? 'transit' : milestone}`;
  const template = templateInGroup(groupId, language) ?? templateInGroup(groupId, 'en');
  if (!template) return;
  if (isOptedOutSync(lead.contactPhone, template.channel)) {
    mark({ customerNotifySkipped: 'opted_out' });
    return;
  }
  const now = new Date().toISOString();
  const body = renderTemplateBody(template.body, {
    customerName: lead.contactName,
    buildingName: lead.siteName,
    shipmentLabel: shipmentLabelOf(leg),
    etaTime: formatTime(roundToQuarter(leg.etaAt).toISOString(), language),
  });
  let conversation = conversations.find((c) => c.leadId === lead.id) ?? null;
  if (!conversation) {
    conversationCounter += 1;
    conversation = { id: `conv-new-${conversationCounter}`, leadId: lead.id, lastMessageAt: now, isDemo: true };
    conversations.push(conversation);
  }
  messageCounter += 1;
  commMessages.push({ id: `cm-new-${messageCounter}`, conversationId: conversation.id, channel: template.channel, sender: 'bot', body, templateGroupId: groupId, status: 'sent', at: now, handled: true });
  patchInPlace(conversations, conversation.id, { lastMessageAt: now });
  mark({ customerNotifiedAt: now });
  logAutomatedAction({
    sourceKey: 'shipment.customer_notified',
    triggeringCondition: `${shipmentLabelOf(leg)} on ${po?.code ?? leg.poId} is ${milestone.replace('_', ' ')}`,
    actionTaken: `Messaged ${lead.contactName} on ${template.channel}`,
    affectedRecordId: leg.poId,
    affectedRecordType: 'purchase_order',
    subjectLabel: po?.code ?? leg.poId,
  });
}

function shipmentViewOf(leg: ShipmentLeg, viewer: ShipmentViewer, now: number): ShipmentView {
  const isCustomer = viewer.actor.role === 'customer';
  const site = shipmentSite(leg.dealId);
  const route = routeOfLeg(leg);
  const snap = legSnapshotOf(leg, route, now);
  const timeline = timelineOf(leg, route, now);
  const po = byId(supplierPurchaseOrders, leg.poId);
  const siblings = shipmentLegs.filter((l) => l.poId === leg.poId).sort((a, b) => (a.dispatchedAt < b.dispatchedAt ? -1 : 1));
  const supplier = byId(suppliers, leg.supplierId);
  const schedule = scheduleOfPo(leg.poId);
  const booked = schedule?.status === 'scheduled' && schedule.date && schedule.window ? { date: schedule.date, window: schedule.window } : null;
  const etaDay = dateKey(new Date(leg.etaAt));
  const isAdmin = viewer.actor.role === 'admin';
  const canUpdate = !snap.arrived && (leg.source === 'manual' || snap.feed === 'lost') && (isAdmin || (viewer.actor.role === 'supplier' && viewer.supplierId === leg.supplierId && !leg.partnerId));
  return {
    legId: leg.id,
    poId: leg.poId,
    poCode: po?.code ?? leg.poId,
    dealId: leg.dealId,
    siteName: site?.siteName ?? '',
    destination: site ? { lat: site.lat, lng: site.lng } : { lat: leg.origin.lat, lng: leg.origin.lng },
    origin: leg.origin,
    lines: (po?.lineItems ?? []).filter((l) => leg.lineItemIds.includes(l.id)).map((l) => ({ id: l.id, description: l.description })),
    legNumber: siblings.findIndex((l) => l.id === leg.id) + 1,
    legCount: siblings.length,
    supplierId: isCustomer ? null : leg.supplierId,
    supplierName: isCustomer ? null : (supplier?.name ?? null),
    partnerId: isCustomer ? null : (leg.partnerId ?? null),
    partnerName: isCustomer ? null : (leg.partnerId ? (byId(deliveryPartners, leg.partnerId)?.name ?? null) : null),
    vehicleLabel: isCustomer ? null : leg.vehicleLabel,
    driverName: isCustomer ? null : leg.driverName,
    driverPhone: isCustomer ? null : (leg.driverPhone ?? null),
    source: leg.source,
    feed: snap.feed,
    position: snap.position,
    fixAt: snap.fixAt,
    progress: snap.progress,
    remainingKm: snap.remainingKm,
    dispatchedAt: leg.dispatchedAt,
    etaAt: leg.etaAt,
    minutesToEta: snap.minutesToEta,
    milestone: snap.milestone,
    arrived: snap.arrived,
    timeline: timeline.map((e) => ({
      milestone: e.milestone,
      reachedAt: e.reachedAt,
      source: e.source,
      byName: isCustomer ? undefined : e.byName,
      note: isCustomer ? undefined : e.note,
      customerNotified: !!e.customerNotifiedAt,
    })),
    route,
    travelled: snap.feed === 'manual' ? [] : travelledRoute(route, snap.progress),
    booked,
    etaOutsideWindow: !!booked && !snap.arrived && (booked.date !== etaDay || !etaInsideWindow(leg.etaAt, WINDOW_HOURS[booked.window])),
    canUpdate,
  };
}

/** The heartbeat's shipment pass: a live vehicle's milestones are written down
 *  as it reaches them (each messaging the customer once), a technician hears
 *  when it's nearby, and a feed that has been silent for too long is put in
 *  front of Admin. Idempotent throughout. */
function advanceShipments(now: number): void {
  for (const original of [...shipmentLegs]) {
    const route = routeOfLeg(original);
    const po = byId(supplierPurchaseOrders, original.poId);
    let leg = original;
    if (leg.source === 'live_gps') {
      const fresh = timelineOf(leg, route, now).filter((e) => e.reachedAt && !e.persisted && e.source === 'gps');
      if (fresh.length > 0) {
        leg = patchInPlace(shipmentLegs, leg.id, { milestones: [...leg.milestones, ...fresh.map((e) => ({ milestone: e.milestone, at: e.reachedAt!, source: 'gps' as const }))] });
        for (const e of fresh) {
          notifyCustomerOfMilestone(leg.id, e.milestone);
          if (e.milestone === 'nearby' && po) notifyTechnicianOfDelivery(po, new Date(now).toISOString(), `${shipmentLabelOf(leg)} on ${po.code} is nearby`);
        }
      }
    }
    const arrived = leg.milestones.some((e) => e.milestone === 'arrived');
    const open = alerts.find((a) => a.relatedId === leg.id && a.titleKey === 'shipmentTracking.alert.feedLost' && a.status !== 'resolved');
    const silent = leg.source === 'live_gps' && !!leg.feedLostAt && !arrived && now - new Date(leg.feedLostAt).getTime() >= FEED_LOST_ALERT_AFTER;
    if (silent && !open) {
      const last = legSnapshotOf(leg, route, now).position;
      const alert = raiseAlert({
        titleKey: 'shipmentTracking.alert.feedLost',
        context: `${po?.code ?? leg.poId} · ${leg.vehicleLabel}`,
        severity: 'medium',
        category: 'supplier',
        relatedId: leg.id,
        sourceRoute: `/shipments?leg=${leg.id}`,
        location: last ?? undefined,
      });
      logAutomatedAction({
        sourceKey: 'shipment.feed_lost',
        triggeringCondition: `${leg.vehicleLabel} stopped reporting its location`,
        actionTaken: `Raised ${alert.code}`,
        affectedRecordId: leg.id,
        affectedRecordType: 'purchase_order',
        subjectLabel: po?.code ?? leg.poId,
      });
    } else if (open && arrived) {
      patchInPlace(alerts, open.id, { status: 'resolved', resolvedAt: new Date(now).toISOString(), resolvedBy: 'system', resolutionNote: 'The shipment has arrived.' });
    }
  }
}

/* ========================================= Site delivery checklist (103) */

/** A technician checks in deliveries for the sites they're installing; Admin
 *  for any. Nobody else stands at a tailgate for AIEC. */
function checklistActorOf(byUserId: string): User {
  const actor = catalogActor(byUserId);
  if (actor.role !== 'admin' && actor.role !== 'technician') throw new RepositoryError('forbidden');
  return actor;
}

function checklistDealVisible(dealId: string, actor: User): boolean {
  if (actor.role === 'admin') return true;
  return jobs.some((j) => j.dealId === dealId && j.technicianId === actor.id && j.status !== 'completed');
}

function checklistOrThrow(checklistId: string, actor: User): DeliveryChecklist {
  const checklist = byId(deliveryChecklists, checklistId);
  if (!checklist || !checklistDealVisible(checklist.dealId, actor)) throw new RepositoryError('not_found');
  return checklist;
}

const reportOfChecklist = (checklistId: string) => discrepancyReports.find((r) => r.checklistId === checklistId) ?? null;

function checklistViewOf(c: DeliveryChecklist): DeliveryChecklistView {
  const po = byId(supplierPurchaseOrders, c.poId);
  const leg = c.legId ? byId(shipmentLegs, c.legId) : undefined;
  return {
    ...c,
    poCode: po?.code ?? c.poId,
    siteName: shipmentSite(c.dealId)?.siteName ?? '',
    address: resolveLead(byId(deals, c.dealId)?.leadId ?? '')?.address ?? null,
    supplierName: byId(suppliers, c.supplierId)?.name ?? '',
    vehicleLabel: leg?.vehicleLabel ?? null,
    report: reportOfChecklist(c.id),
    poFullyDelivered: !!po?.receivedAt,
  };
}

/** Everything that shipped and hasn't been verified on site, grouped the way it
 *  travelled: one vehicle's load, or the remainder that has no vehicle of its own. */
function checklistArrivals(actor: User): ChecklistArrival[] {
  const out: ChecklistArrival[] = [];
  const open = deliveryChecklists.filter((c) => c.status === 'in_progress');
  for (const po of supplierPurchaseOrders) {
    if (po.status !== 'sent' || !po.supplierId || !checklistDealVisible(po.dealId, actor)) continue;
    const shipped = (po.lineItems ?? []).filter((l) => lineStageOf(po, l) === 'shipped');
    if (shipped.length === 0) continue;
    const site = shipmentSite(po.dealId);
    const checkedLegs = new Set(deliveryChecklists.filter((c) => c.poId === po.id && c.status === 'completed' && c.legId).map((c) => c.legId));
    const claimed = new Set<string>();
    const make = (leg: ShipmentLeg | null, lines: typeof shipped): ChecklistArrival => ({
      key: `${po.id}:${leg?.id ?? 'loose'}`,
      poId: po.id,
      poCode: po.code,
      dealId: po.dealId,
      siteName: site?.siteName ?? '',
      address: resolveLead(byId(deals, po.dealId)?.leadId ?? '')?.address ?? null,
      supplierName: byId(suppliers, po.supplierId!)?.name ?? '',
      legId: leg?.id ?? null,
      vehicleLabel: leg?.vehicleLabel ?? null,
      legMilestone: leg ? legSnapshotOf(leg, routeOfLeg(leg), Date.now()).milestone : null,
      etaAt: leg?.etaAt ?? null,
      lines: lines.map((l) => ({ id: l.id, description: l.description, quantity: l.quantity })),
      checklistId: open.find((c) => c.poId === po.id && (c.legId ?? null) === (leg?.id ?? null))?.id ?? null,
    });
    for (const leg of shipmentLegs.filter((l) => l.poId === po.id)) {
      if (checkedLegs.has(leg.id)) continue;
      const lines = shipped.filter((l) => leg.lineItemIds.includes(l.id));
      if (lines.length === 0) continue;
      lines.forEach((l) => claimed.add(l.id));
      out.push(make(leg, lines));
    }
    const rest = shipped.filter((l) => !claimed.has(l.id));
    if (rest.length > 0) out.push(make(null, rest));
  }
  const rank = (a: ChecklistArrival) => (a.checklistId ? 0 : a.legMilestone === 'arrived' ? 1 : a.legMilestone === 'nearby' ? 2 : a.legId ? 3 : 4);
  return out.sort((a, b) => rank(a) - rank(b) || ((a.etaAt ?? '9999') < (b.etaAt ?? '9999') ? -1 : 1));
}

/** Keeps the delivery's one report in step with what's been found. Raised the
 *  moment something is wrong; withdrawn if every item is corrected before close. */
function syncDiscrepancyReport(checklist: DeliveryChecklist, actor: User): void {
  const po = byId(supplierPurchaseOrders, checklist.poId);
  const wrong = checklist.items.filter((i) => i.verdict === 'discrepancy');
  const items = wrong.map((i) => ({
    lineItemId: i.lineItemId,
    description: i.description,
    kinds: i.kinds,
    expectedQty: i.expectedQty,
    receivedQty: i.receivedQty ?? i.expectedQty,
    note: i.note,
    photoCount: i.photos.length,
    // Kept on the report so its cost still reads the same after the order is edited (110).
    category: (po?.lineItems ?? []).find((l) => l.id === i.lineItemId)?.category,
    value: ((po?.lineItems ?? []).find((l) => l.id === i.lineItemId)?.agreedUnitPrice ?? 0) * ((po?.lineItems ?? []).find((l) => l.id === i.lineItemId)?.quantity ?? 1),
  }));
  const existingReport = reportOfChecklist(checklist.id);
  let report: DeliveryDiscrepancyReport;
  const now = new Date().toISOString();
  if (!existingReport) {
    if (items.length === 0) return;
    discrepancyCounter += 1;
    report = {
      id: `ddr-new-${discrepancyCounter}`,
      code: `AIEC-DR-${5000 + discrepancyCounter}`,
      poId: checklist.poId,
      dealId: checklist.dealId,
      supplierId: checklist.supplierId,
      checklistId: checklist.id,
      items,
      status: 'open',
      resolution: 'reported',
      possibleCauses: [],
      rush: false,
      events: [{ id: `ddr-new-${discrepancyCounter}-e1`, kind: 'raised', at: now, byName: actor.name }],
      createdAt: now,
      createdByName: actor.name,
      isDemo: true,
    };
    discrepancyReports.push(report);
  } else {
    report = patchInPlace(discrepancyReports, existingReport.id, { items, status: items.length > 0 ? (existingReport.status === 'resolved' ? 'resolved' : 'open') : 'withdrawn' });
  }
  const alertOf = () => alerts.find((a) => a.relatedId === report!.id && a.titleKey === 'deliveryChecklist.alert.discrepancy' && a.status !== 'resolved');
  if (report.status === 'open') {
    // Wrong or wrong-spec parts stop an installation; a short count usually just delays it.
    const stops = wrong.some((i) => i.kinds.includes('damaged') || i.kinds.includes('wrong_spec'));
    raiseAlert({
      titleKey: 'deliveryChecklist.alert.discrepancy',
      context: `${po?.code ?? checklist.poId} · ${shipmentSite(checklist.dealId)?.siteName ?? ''} · ${report.code}`,
      severity: stops ? 'high' : 'medium',
      category: 'quality',
      relatedId: report.id,
      sourceRoute: `/damaged-parts?report=${report.id}`,
    });
  } else {
    const open = alertOf();
    if (open) patchInPlace(alerts, open.id, { status: 'resolved', resolvedAt: now, resolvedBy: actor.name, resolutionNote: 'Every item was corrected before the checklist closed.' });
  }
}

/** The real purchase orders for a deal: the ones with parts on them. A bare "triggered" or
 *  "failed" placeholder from deal closure carries nothing to receive. */
const dealOrderedPos = (dealId: string) => supplierPurchaseOrders.filter((p) => p.dealId === dealId && (p.lineItems ?? []).length > 0);

/** All of a deal's parts are on site and none of them is in question. */
function dealMaterialsOnSite(dealId: string): boolean {
  const pos = dealOrderedPos(dealId);
  if (pos.length === 0 || !pos.every((p) => p.status === 'sent' && p.receivedAt)) return false;
  return !discrepancyReports.some((r) => r.dealId === dealId && r.status === 'open');
}

/* ========================================== Delivery confirmation (104) */

function confirmationActorOf(byUserId: string): User {
  const actor = catalogActor(byUserId);
  if (actor.role !== 'admin' && actor.role !== 'technician' && actor.role !== 'customer') throw new RepositoryError('forbidden');
  return actor;
}

/** A customer sees their own deals' confirmations, once signed; AIEC's own people see the rest. */
function confirmationVisibleTo(c: DeliveryConfirmation, actor: User): boolean {
  if (actor.role === 'customer') return c.status === 'signed' && byId(deals, c.dealId)?.customerId === actor.id;
  return checklistDealVisible(c.dealId, actor);
}

function createDeliveryConfirmation(checklist: DeliveryChecklist): DeliveryConfirmation {
  confirmationCounter += 1;
  const report = reportOfChecklist(checklist.id);
  const created: DeliveryConfirmation = {
    id: `dcf-new-${confirmationCounter}`,
    code: `AIEC-DC-${5000 + confirmationCounter}`,
    checklistId: checklist.id,
    poId: checklist.poId,
    dealId: checklist.dealId,
    supplierId: checklist.supplierId,
    legId: checklist.legId,
    status: 'awaiting_signature',
    // Frozen here: the checklist itself never changes, and what is signed is what it said.
    items: checklist.items.map((i) => ({
      lineItemId: i.lineItemId,
      description: i.description,
      expectedQty: i.expectedQty,
      receivedQty: i.verdict === 'not_arrived' ? 0 : (i.receivedQty ?? i.expectedQty),
      verdict: i.verdict === 'pending' ? 'not_arrived' : i.verdict,
      kinds: i.kinds,
      photoCount: i.photos.length,
      note: i.note,
    })),
    createdAt: checklist.completedAt ?? new Date().toISOString(),
    signatures: [],
    reportIds: report && report.status === 'open' ? [report.id] : [],
    isDemo: true,
  };
  deliveryConfirmations.push(created);
  return created;
}

function confirmationViewOf(c: DeliveryConfirmation, actor: User): DeliveryConfirmationView {
  const po = byId(supplierPurchaseOrders, c.poId);
  const checklist = byId(deliveryChecklists, c.checklistId);
  const leg = c.legId ? byId(shipmentLegs, c.legId) : undefined;
  const isCustomer = actor.role === 'customer';
  return {
    ...c,
    poCode: po?.code ?? c.poId,
    siteName: shipmentSite(c.dealId)?.siteName ?? '',
    address: resolveLead(byId(deals, c.dealId)?.leadId ?? '')?.address ?? null,
    supplierName: isCustomer ? null : (byId(suppliers, c.supplierId)?.name ?? null),
    vehicleLabel: isCustomer ? null : (leg?.vehicleLabel ?? null),
    receiver: checklist?.receivedBy ?? null,
    reports: c.reportIds.map((id) => byId(discrepancyReports, id)).filter((r): r is DeliveryDiscrepancyReport => !!r).map((r) => ({ id: r.id, code: r.code, status: r.status, itemCount: r.items.length })),
    poFullyDelivered: !!po?.receivedAt,
    canSign: c.status === 'awaiting_signature' && actor.role !== 'customer',
    // The customer's copy leaves out what only AIEC needs: internal notes on the parts.
    ...(isCustomer ? { items: c.items.map((i) => ({ ...i, note: undefined })), recordedByName: undefined } : {}),
  };
}

/** A confirmation signed after the parts they cover were all delivered, and every
 *  other one for the deal signed too, is what "materials received" means. */
function dealMaterialsConfirmed(dealId: string, includingId: string): boolean {
  const pos = dealOrderedPos(dealId);
  if (pos.length === 0 || !pos.every((p) => p.status === 'sent' && p.receivedAt)) return false;
  return deliveryConfirmations.filter((c) => c.dealId === dealId).every((c) => c.status === 'signed' || c.id === includingId);
}

/** When the parts for a deal were confirmed on site, if a signed confirmation says so. */
function materialsConfirmedAt(dealId: string): string | null {
  return deliveryConfirmations.find((c) => c.dealId === dealId && c.status === 'signed' && c.materialsComplete)?.signedAt ?? null;
}

const MATERIALS_MILESTONE = 'job.step.materialsReceived';

/** A payment stage that falls due on "materials received" is due the day that is
 *  confirmed. Never re-fired once the installation job has already recorded the step,
 *  and never touching a stage anyone has already paid or disputed. */
function anchorMaterialPayments(dealId: string, at: string): string[] {
  const primaryJob = jobs.find((j) => j.dealId === dealId);
  const step = primaryJob?.steps.find((s) => s.labelKey === MATERIALS_MILESTONE);
  if (step && step.status === 'complete' && step.completedAt) return [];
  const schedule = paymentSchedules.find((s) => s.dealId === dealId && s.activated);
  if (!schedule) return [];
  const anchored: string[] = [];
  for (const stage of schedule.stages) {
    if (stage.dueTrigger !== 'milestone' || stage.triggerMilestone !== MATERIALS_MILESTONE) continue;
    for (const payment of payments.filter((p) => p.dealId === dealId && p.stage === stage.stage && p.status === 'due')) {
      patchInPlace(payments, payment.id, { dueDate: at });
      anchored.push(payment.id);
      logAutomatedAction({
        sourceKey: 'delivery.payment_due',
        triggeringCondition: `Delivery of the parts for ${shipmentSite(dealId)?.siteName ?? dealId} was signed for`,
        actionTaken: `Made ${payment.code} due on ${at.slice(0, 10)}`,
        affectedRecordId: payment.id,
        affectedRecordType: 'payment',
        subjectLabel: payment.code,
      });
    }
  }
  return anchored;
}

const looksLikeSignature = (dataUrl: string) => /^data:image\/png;base64,[A-Za-z0-9+/=]{60,}$/.test(dataUrl);

/* ==================================== Delivery delay escalation (105) */

/** A late-running delivery, judged live from what we are held to and what the tracker says. */
function delayFactsOf(po: SupplierPurchaseOrder, now: number): DelayFacts | null {
  if (po.status !== 'sent' || po.receivedAt || !po.supplierId || isOrphanedPo(po)) return null;
  const supplier = byId(suppliers, po.supplierId) ?? undefined;
  const estimate = assessDelay(po, supplier, supplierPurchaseOrders, now);
  const schedule = scheduleOfPo(po.id);
  const booked = schedule?.status === 'scheduled' && schedule.date && schedule.window ? windowEndsAt(schedule.date, schedule.window) : null;
  const expectedAt = booked ?? promisedDeliveryOf(po) ?? null;
  const lines = po.lineItems ?? [];
  const shipped = lines.filter((l) => lineStageOf(po, l) === 'shipped');
  const unshipped = lines.filter((l) => lineStageOf(po, l) !== 'shipped' && lineStageOf(po, l) !== 'delivered');
  // Every vehicle still carrying something for this order, and how far each can be trusted.
  let uncertain = false;
  const legEtas: number[] = [];
  for (const leg of shipmentLegs.filter((l) => l.poId === po.id && l.lineItemIds.some((id) => shipped.some((s) => s.id === id)))) {
    const snap = legSnapshotOf(leg, routeOfLeg(leg), now);
    if (snap.arrived) continue;
    legEtas.push(new Date(leg.etaAt).getTime());
    const lastWord = Math.max(new Date(leg.dispatchedAt).getTime(), ...leg.milestones.map((e) => new Date(e.at).getTime()));
    if (snap.feed === 'lost' || (snap.feed === 'manual' && now - lastWord > MANUAL_UPDATE_EVERY)) uncertain = true;
  }
  const projected = estimate.projectedDelivery ? new Date(estimate.projectedDelivery).getTime() : now;
  const trackerOnly = legEtas.length > 0 && unshipped.length === 0;
  const currentEta = new Date(trackerOnly ? Math.max(...legEtas) : Math.max(projected, ...legEtas)).toISOString();
  const job = pendingJobFor(po.dealId, schedule);
  return {
    expectedAt,
    expectedSource: booked ? 'booked' : 'promised',
    currentEta,
    etaSource: trackerOnly ? 'tracker' : 'estimate',
    uncertain,
    estimateAtRisk: estimate.risk !== 'on_track' && !trackerOnly,
    installStart: job && !job.startedAt ? job.scheduledFor : null,
  };
}

function delayAlertFor(caseId: string) {
  return alerts.find((a) => a.relatedId === caseId && a.titleKey === 'deliveryDelay.alert.delayed' && a.status !== 'resolved');
}

/** The heartbeat's half: opens a case the first time a delivery goes wrong, raises an alert once it is
 *  actually late, and closes both on its own the moment the supplier catches up. Idempotent. */
function syncDelayCases(now: number): void {
  const at = new Date(now).toISOString();
  for (const po of supplierPurchaseOrders) {
    const open = delayCases.find((c) => c.poId === po.id && c.status === 'open');
    const facts = delayFactsOf(po, now);
    const verdict = facts ? judgeDelay(facts, now) : null;
    const site = shipmentSite(po.dealId)?.siteName ?? '';
    if (facts && verdict?.severity) {
      const gap = Math.max(0, verdict.gapHours ?? 0);
      let current = open;
      if (!current) {
        delayCounter += 1;
        current = { id: `ddc-new-${delayCounter}`, poId: po.id, dealId: po.dealId, supplierId: po.supplierId!, status: 'open', openedAt: at, worstSeverity: verdict.severity, peakGapHours: gap, isDemo: true };
        delayCases.push(current);
        logAutomatedAction({
          sourceKey: 'delivery.delay_opened',
          triggeringCondition: `${po.code} for ${site} is ${verdict.severity === 'watch' ? 'trending late' : 'running late'}`,
          actionTaken: 'Opened a delivery delay case',
          affectedRecordId: po.id,
          affectedRecordType: 'purchase_order',
          subjectLabel: po.code,
        });
      }
      const worst = SEVERITY_ORDER[verdict.severity] > SEVERITY_ORDER[current.worstSeverity] ? verdict.severity : current.worstSeverity;
      current = patchInPlace(delayCases, current.id, {
        worstSeverity: worst,
        peakGapHours: Math.max(current.peakGapHours, gap),
        lateSince: current.lateSince ?? (verdict.severity !== 'watch' ? at : undefined),
      });
      // A watch is for Admin's eyes on this screen; an alert is for a delivery that is genuinely late.
      if (verdict.severity !== 'watch') {
        raiseAlert({
          titleKey: 'deliveryDelay.alert.delayed',
          context: `${po.code} · ${site} · ${Math.max(1, gap)} h late`,
          severity: verdict.severity === 'critical' ? 'high' : 'medium',
          category: 'supplier',
          relatedId: current.id,
          sourceRoute: `/delivery-delays?case=${current.id}`,
        });
      }
    } else if (open) {
      // Caught up, or delivered: the good news is kept, the alert clears itself.
      patchInPlace(delayCases, open.id, { status: 'recovered', recoveredAt: at, recoveredEta: po.receivedAt ?? facts?.currentEta ?? at });
      const alert = delayAlertFor(open.id);
      if (alert) patchInPlace(alerts, alert.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: po.receivedAt ? 'The delivery arrived.' : 'The delivery is back on track.' });
      logAutomatedAction({
        sourceKey: 'delivery.delay_recovered',
        triggeringCondition: `${po.code} is ${po.receivedAt ? 'delivered' : 'back on track'}`,
        actionTaken: 'Closed the delay case and cleared its alert',
        affectedRecordId: po.id,
        affectedRecordType: 'purchase_order',
        subjectLabel: po.code,
      });
    }
  }
}
const SEVERITY_ORDER: Record<DelaySeverity, number> = { watch: 1, late: 2, critical: 3 };

function delayCaseOrThrow(caseId: string): DeliveryDelayCase {
  const found = byId(delayCases, caseId);
  if (!found) throw new RepositoryError('not_found');
  return found;
}

/** The exact message a customer would get for these orders, in their own language. */
function delayMessageFor(c: DeliveryDelayCase, facts: DelayFacts | null): { channel: CommChannel; body: string; lead: Lead | null; template: CommTemplate | undefined } {
  const lead = resolveLead(byId(deals, c.dealId)?.leadId ?? '');
  const language = lead?.preferredLanguage ?? 'en';
  const groupId = c.rootCause === 'external_event' ? 'tpl-delay-external' : 'tpl-delay-notice';
  const template = templateInGroup(groupId, language) ?? templateInGroup(groupId, 'en');
  const po = byId(supplierPurchaseOrders, c.poId);
  const etaIso = facts?.currentEta ?? c.recoveredEta ?? new Date().toISOString();
  const original = c.promiseMovedFrom ?? facts?.expectedAt ?? po?.expectedDeliveryDate ?? etaIso;
  const body = template
    ? renderTemplateBody(template.body, {
        customerName: lead?.contactName,
        buildingName: lead?.siteName,
        shipmentLabel: (po?.lineItems ?? []).map((l) => l.description.toLowerCase()).slice(0, 2).join(', ') || 'delivery',
        // Late by hours on the same day: the date alone would say nothing, so say the time too.
        etaDate: original.slice(0, 10) === etaIso.slice(0, 10) ? formatDateTime(etaIso, language) : formatDate(etaIso, language),
        originalDate: original.slice(0, 10) === etaIso.slice(0, 10) ? formatDateTime(original, language) : formatDate(original, language),
        delayReason: c.externalLabel,
      })
    : '';
  return { channel: template?.channel ?? 'whatsapp', body, lead, template };
}

function delayRowOf(c: DeliveryDelayCase, now: number): DelayRow {
  const po = byId(supplierPurchaseOrders, c.poId)!;
  const supplier = byId(suppliers, c.supplierId);
  const deal = byId(deals, c.dealId);
  const lead = deal ? resolveLead(deal.leadId) : null;
  const facts = delayFactsOf(po, now);
  const verdict = facts ? judgeDelay(facts, now) : null;
  const job = pendingJobFor(po.dealId, scheduleOfPo(po.id));
  const message = delayMessageFor(c, facts);
  const thread = supplierThreads.find((t) => t.supplierId === c.supplierId && t.relatedPoId === c.poId);
  const stage = poStageOf(po);
  const etaNow = facts?.currentEta ?? c.recoveredEta ?? c.openedAt;
  return {
    caseId: c.id,
    status: c.status,
    poId: po.id,
    poCode: po.code,
    dealId: c.dealId,
    // A historical deal may have no lead on file; its own code still says which job this is.
    siteName: shipmentSite(c.dealId)?.siteName ?? deal?.code ?? c.dealId,
    customerName: lead?.contactName ?? '',
    supplierId: c.supplierId,
    supplierName: supplier?.name ?? '',
    supplierHasLogin: !!supplier && !!supplierUserFor(supplier),
    dealValue: deal?.agreedPrice || deal?.quotedPrice || 0,
    stage,
    lineSummary: (po.lineItems ?? []).map((l) => l.description).join(', '),
    severity: c.status === 'open' ? (verdict?.severity ?? null) : null,
    worstSeverity: c.worstSeverity,
    gapHours: verdict?.gapHours ?? null,
    peakGapHours: c.peakGapHours,
    expectedAt: facts?.expectedAt ?? null,
    expectedSource: facts?.expectedSource ?? 'promised',
    currentEta: etaNow,
    etaSource: facts?.etaSource ?? 'estimate',
    uncertain: facts?.uncertain ?? false,
    impact: verdict?.impact ?? 'none',
    installStart: facts?.installStart ?? null,
    installCode: job && !job.startedAt ? job.code : null,
    openedAt: c.openedAt,
    recoveredAt: c.recoveredAt ?? null,
    delivered: !!po.receivedAt,
    rootCause: c.rootCause ?? null,
    rootCauseNote: c.rootCauseNote ?? null,
    externalLabel: c.externalLabel ?? null,
    promiseMovedFrom: c.promiseMovedFrom ?? null,
    contactedSupplierAt: c.contactedSupplierAt ?? null,
    customerNotifiedAt: c.customerNotifiedAt ?? null,
    customerNotifiedEta: c.customerNotifiedEta ?? null,
    notifyStale: !!c.customerNotifiedAt && c.status === 'open' && etaMovedSince(c.customerNotifiedEta, etaNow),
    escalatedAt: c.escalatedAt ?? null,
    customerOptedOut: !!lead && !!message.template && isOptedOutSync(lead.contactPhone, message.template.channel),
    customerPreview: message.body,
    threadId: thread?.id ?? null,
  };
}

/* ================================ Damaged / missing parts report (108) */

function reportActorOf(byUserId: string): User {
  const actor = catalogActor(byUserId);
  if (actor.role !== 'admin' && actor.role !== 'technician') throw new RepositoryError('forbidden');
  return actor;
}

function reportOrThrow(reportId: string, actor: User): DeliveryDiscrepancyReport {
  const r = byId(discrepancyReports, reportId);
  if (!r || !checklistDealVisible(r.dealId, actor)) throw new RepositoryError('not_found');
  return r;
}

const reportChecklist = (r: DeliveryDiscrepancyReport) => byId(deliveryChecklists, r.checklistId);

function reportEvent(r: DeliveryDiscrepancyReport, kind: ReportEvent['kind'], byName: string, note?: string): ReportEvent[] {
  return [...r.events, { id: `${r.id}-e${r.events.length + 1}`, kind, at: new Date().toISOString(), byName, note }];
}

function reportSummary(r: DeliveryDiscrepancyReport): string {
  const po = byId(supplierPurchaseOrders, r.poId);
  const word: Record<string, string> = { damaged: 'damaged', count: 'count does not match', wrong_spec: 'wrong model or spec' };
  const parts = r.items.map((i) => `${i.description}: ${i.kinds.map((k) => word[k]).join(', ')} (expected ${i.expectedQty}, received ${i.receivedQty})${i.note ? `, “${i.note}”` : ''}`);
  return `Delivery problem on ${po?.code ?? r.poId} (${r.code}) at ${shipmentSite(r.dealId)?.siteName ?? r.dealId}. ${parts.join('. ')}.`;
}

function reportPhotoNames(r: DeliveryDiscrepancyReport): string[] {
  const checklist = reportChecklist(r);
  return r.items.flatMap((i) => (checklist?.items.find((c) => c.lineItemId === i.lineItemId)?.photos ?? []).map((p) => p.fileName));
}

/** Puts the report, with its evidence, into the order's own thread with the supplier. A supplier with no
 *  login cannot read an app message, so that one is left for Admin to phone or email and log. */
function routeReportToSupplier(r: DeliveryDiscrepancyReport, actor: User, channel: SupplierMessageChannel, follow?: string): { threadId: string } {
  const supplier = byId(suppliers, r.supplierId);
  if (!supplier) throw new RepositoryError('not_found');
  if (channel === 'in_app' && !supplierUserFor(supplier)) throw new RepositoryError('no_portal');
  const thread = ensureSupplierThread(supplier.id, r.poId);
  const at = new Date().toISOString();
  const names = reportPhotoNames(r);
  pushSupplierMessage(thread, {
    author: 'aiec',
    authorName: actor.name,
    authorUserId: actor.id,
    body: `${follow ?? reportSummary(r)}${r.rush ? ` URGENT: a replacement is needed${r.neededBy ? ` by ${r.neededBy.slice(0, 10)}` : ' as soon as possible'}, to protect a booked installation.` : ''} Photographs attached. Please confirm how and when you will replace or credit it.`,
    channel,
    at,
    loggedBy: channel === 'in_app' ? undefined : actor.name,
    expectsReply: true,
    poRef: r.poId,
    attachmentName: names[0],
    evidenceNames: names,
    urgent: r.rush || undefined,
    readAt: channel === 'in_app' ? undefined : at,
  });
  patchInPlace(discrepancyReports, r.id, { routedToSupplierAt: r.routedToSupplierAt ?? at, events: reportEvent(byId(discrepancyReports, r.id)!, 'routed', actor.name) });
  return { threadId: thread.id };
}

/** Whose it is, once Admin has said, becomes a defect on the order's rating (097): only the supplier's own
 *  marks down its quality, but transport and installation causes are still recorded. Never logged twice. */
function syncReportDefect(r: DeliveryDiscrepancyReport): void {
  if (!r.attribution) return;
  const rating = supplierOrderRatings.find((x) => x.poId === r.poId);
  if (!rating) return;
  const existing = rating.defects.find((d) => d.sourceReportId === r.id);
  if (existing) {
    if (existing.attribution === r.attribution) return;
    patchInPlace(supplierOrderRatings, rating.id, {
      defects: rating.defects.map((d) => (d.id === existing.id ? { ...d, attribution: r.attribution!, attributedBefore: d.attributedBefore ?? d.attribution, reattributedBy: r.attributedByName, reattributedAt: r.attributedAt, reattributionNote: r.attributionNote } : d)),
    });
  } else {
    ratingCounter += 1;
    patchInPlace(supplierOrderRatings, rating.id, {
      defects: [...rating.defects, { id: `${rating.id}-d-new-${ratingCounter}`, note: `${r.code}: ${r.items.map((i) => i.description).join(', ')}`, loggedBy: r.attributedByName ?? 'AIEC', loggedAt: r.attributedAt ?? new Date().toISOString(), attribution: r.attribution, sourceReportId: r.id }],
    });
  }
  recomputeSupplierMetrics(rating.supplierId);
}

function reportViewOf(r: DeliveryDiscrepancyReport, actor: User, now: number): DiscrepancyReportView {
  const po = byId(supplierPurchaseOrders, r.poId);
  const checklist = reportChecklist(r);
  const supplier = byId(suppliers, r.supplierId);
  const deal = byId(deals, r.dealId);
  const lead = deal ? resolveLead(deal.leadId) : null;
  const job = pendingJobFor(r.dealId);
  const installStart = job && !job.startedAt ? job.scheduledFor : null;
  const items: ReportItemView[] = r.items.map((i) => {
    const line = (po?.lineItems ?? []).find((l) => l.id === i.lineItemId);
    return {
      lineItemId: i.lineItemId,
      description: i.description,
      kinds: i.kinds,
      expectedQty: i.expectedQty,
      receivedQty: i.receivedQty,
      note: i.note ?? null,
      photos: (checklist?.items.find((c) => c.lineItemId === i.lineItemId)?.photos ?? []).map((p) => ({ id: p.id, fileName: p.fileName, previewUrl: p.previewUrl ?? null })),
      value: (line?.agreedUnitPrice ?? 0) * (line?.quantity ?? 1),
    };
  });
  const thread = supplierThreads.find((t) => t.supplierId === r.supplierId && t.relatedPoId === r.poId);
  const template = templateInGroup('tpl-parts-notice', lead?.preferredLanguage ?? 'en') ?? templateInGroup('tpl-parts-notice', 'en');
  const language = lead?.preferredLanguage ?? 'en';
  const original = po ? (promisedDeliveryOf(po) ?? checklist?.completedAt ?? r.createdAt) : r.createdAt;
  const etaForNote = r.replacementEta ?? installStart ?? original;
  const impact = r.status === 'open' ? impactLevel(installStart, r.replacementEta ?? null) : 'none';
  return {
    id: r.id,
    code: r.code,
    status: r.status,
    resolution: r.resolution,
    poId: r.poId,
    poCode: po?.code ?? r.poId,
    dealId: r.dealId,
    siteName: lead?.siteName ?? deal?.code ?? r.dealId,
    customerName: lead?.contactName ?? '',
    supplierId: r.supplierId,
    supplierName: supplier?.name ?? '',
    supplierHasLogin: !!supplier && !!supplierUserFor(supplier),
    checklistId: r.checklistId,
    checklistCompleted: checklist ? checklist.status === 'completed' : true,
    items,
    affectedValue: items.reduce((sum, i) => sum + i.value, 0),
    possibleCauses: r.possibleCauses,
    causeNote: r.causeNote ?? null,
    rush: r.rush,
    neededBy: r.neededBy ?? null,
    attribution: r.attribution ?? null,
    attributionNote: r.attributionNote ?? null,
    attributedByName: r.attributedByName ?? null,
    attributedAt: r.attributedAt ?? null,
    replacementEta: r.replacementEta ?? null,
    creditAmount: r.creditAmount ?? null,
    routedToSupplierAt: r.routedToSupplierAt ?? null,
    customerNotifiedAt: r.customerNotifiedAt ?? null,
    threadId: thread?.id ?? null,
    reporterName: r.createdByName,
    createdAt: r.createdAt,
    events: r.events,
    impact: { level: impact, installStart, installCode: job && !job.startedAt ? job.code : null, replacementEta: r.replacementEta ?? null },
    needsJudgement: !r.attribution && r.status === 'open',
    customerPreview: template
      ? renderTemplateBody(template.body, {
          customerName: lead?.contactName,
          buildingName: lead?.siteName,
          partsLabel: r.items.map((i) => i.description.toLowerCase()).join(', '),
          etaDate: formatDate(etaForNote, language),
        })
      : '',
    customerOptedOut: !!lead && !!template && isOptedOutSync(lead.contactPhone, template.channel),
    canJudge: actor.role === 'admin' && checklist?.status === 'completed' && r.status === 'open',
    canEditDetails: r.status === 'open',
  };
  void now;
}

/* ============================================ Delivery partners (109) */

const deliveryPartners: DeliveryPartner[] = seedDeliveryPartners.map((p) => ({ ...p, lanes: [...p.lanes], events: [...p.events] }));
const partnerTripRecords: PartnerTripRecord[] = [...seedPartnerTrips];
let partnerCounter = 100;
let partnerEventCounter = 100;
let partnerLaneCounter = 100;

const PARTNER_HISTORY_DAYS = 180;

const partnerOrThrow = (partnerId: string): DeliveryPartner => {
  const partner = byId(deliveryPartners, partnerId);
  if (!partner) throw new RepositoryError('not_found');
  return partner;
};

function partnerEvents(p: DeliveryPartner, kind: PartnerEvent['kind'], byName: string, note?: string): PartnerEvent[] {
  partnerEventCounter += 1;
  return [...p.events, { id: `dpe-new-${partnerEventCounter}`, kind, at: new Date().toISOString(), byName, note: note?.trim() || undefined }];
}

const cityOfDeal = (dealId: string): string => resolveLead(byId(deals, dealId)?.leadId ?? '')?.city ?? '';

/** Every finished trip a partner has made: what they did before AIEC tracked it, and what they have delivered since. */
function partnerTrips(partnerId: string): { facts: TripFacts; laneLabel: string }[] {
  const past = partnerTripRecords.filter((r) => r.partnerId === partnerId).map((r) => ({ facts: tripOfRecord(r), laneLabel: r.laneLabel }));
  const since = shipmentLegs
    .filter((l) => l.partnerId === partnerId)
    .flatMap((l) => {
      const arrived = l.milestones.find((m) => m.milestone === 'arrived');
      if (!arrived) return [];
      const po = byId(supplierPurchaseOrders, l.poId);
      const facts: TripFacts = {
        id: l.id,
        partnerId,
        poCode: po?.code ?? l.poId,
        siteName: shipmentSite(l.dealId)?.siteName ?? '',
        promisedAt: (po && promisedDeliveryOf(po)) || l.etaAt,
        dispatchedAt: l.dispatchedAt,
        etaAt: l.etaAt,
        arrivedAt: arrived.at,
        origin: 'leg',
        // A delay Admin has put down to an event outside anyone's control is nobody's fault.
        externalEvent: delayCases.some((c) => c.poId === l.poId && c.rootCause === 'external_event'),
      };
      return [{ facts, laneLabel: `${byId(suppliers, l.supplierId)?.city ?? ''} → ${cityOfDeal(l.dealId)}` }];
    });
  return [...past, ...since];
}

function partnerRowOf(p: DeliveryPartner, now: number): PartnerRow {
  const trips = partnerTrips(p.id);
  const stats = statsFor(trips.map((t) => t.facts));
  const views: PartnerTripView[] = [...trips]
    .sort((a, b) => (a.facts.arrivedAt < b.facts.arrivedAt ? 1 : -1))
    .slice(0, 10)
    .map(({ facts, laneLabel }) => {
      const late = latenessOf(facts);
      return {
        id: facts.id,
        poCode: facts.poCode,
        siteName: facts.siteName,
        laneLabel,
        arrivedAt: facts.arrivedAt,
        lateMin: Math.max(0, Math.round((new Date(facts.arrivedAt).getTime() - new Date(facts.etaAt).getTime()) / 60_000)),
        onTime: carriedOnTime(facts),
        responsibility: late.responsibility,
        supplierMin: late.supplierMin,
        partnerMin: late.partnerMin,
      };
    });
  const inFlight = shipmentLegs
    .filter((l) => l.partnerId === p.id && !l.milestones.some((m) => m.milestone === 'arrived'))
    .map((l) => ({
      legId: l.id,
      poCode: byId(supplierPurchaseOrders, l.poId)?.code ?? l.poId,
      siteName: shipmentSite(l.dealId)?.siteName ?? '',
      feed: legSnapshotOf(l, routeOfLeg(l), now).feed,
    }));
  return {
    id: p.id,
    name: p.name,
    contactName: p.contactName,
    phone: p.phone,
    email: p.email ?? null,
    serviceAreas: p.serviceAreas,
    liveTrackingSupported: p.liveTrackingSupported,
    feedStatus: p.feedStatus,
    feedBrokenSince: p.feedBrokenSince ?? null,
    trackingMode: trackingModeOf(p),
    status: p.status,
    rateCardRef: p.rateCardRef,
    rateCardEffectiveFrom: p.rateCardEffectiveFrom,
    lanes: p.lanes,
    stats,
    trips: views,
    inFlight,
    events: [...p.events].sort((a, b) => (a.at < b.at ? 1 : -1)),
    createdAt: p.createdAt,
  };
}

/** Whose fault each late delivery was, over the last half year: the carrier's own transit, or the supplier handing over too late. */
function partnerDelayAnalysis(now: number): DelayAnalysis {
  const since = now - PARTNER_HISTORY_DAYS * 86_400_000;
  const late: LateDeliveryView[] = [];
  const totals: Record<Responsibility, number> = { partner: 0, supplier: 0, shared: 0, external: 0 };
  let deliveries = 0;
  for (const partner of deliveryPartners) {
    for (const { facts } of partnerTrips(partner.id)) {
      if (new Date(facts.arrivedAt).getTime() < since) continue;
      deliveries += 1;
      const l = latenessOf(facts);
      if (!l.responsibility) continue;
      totals[l.responsibility] += 1;
      late.push({ id: facts.id, partnerId: partner.id, partnerName: partner.name, poCode: facts.poCode, siteName: facts.siteName, arrivedAt: facts.arrivedAt, lateMin: l.lateMin, supplierMin: l.supplierMin, partnerMin: l.partnerMin, responsibility: l.responsibility });
    }
  }
  return { late: late.sort((a, b) => (a.arrivedAt < b.arrivedAt ? 1 : -1)), totals, deliveries };
}

/** Sent orders with lines ready to go and not yet on a vehicle, with the carriers that can and cannot take them. */
function bookablePos(): BookablePo[] {
  const onALeg = new Set(shipmentLegs.flatMap((l) => l.lineItemIds));
  const out: BookablePo[] = [];
  for (const po of supplierPurchaseOrders) {
    if (po.status !== 'sent' || !po.supplierId) continue;
    // Parts for a deal that was lost or cancelled are not going anywhere (106).
    const dealStatus = byId(deals, po.dealId)?.status;
    if (dealStatus === 'lost' || dealStatus === 'cancelled') continue;
    const lines = (po.lineItems ?? []).filter((l) => lineStageOf(po, l) === 'ready_to_ship' && !onALeg.has(l.id));
    if (lines.length === 0) continue;
    const supplier = byId(suppliers, po.supplierId);
    const site = shipmentSite(po.dealId);
    if (!supplier || !site) continue;
    const siteCity = cityOfDeal(po.dealId);
    const originCity = supplier.city ?? '';
    const eligible: PartnerOption[] = [];
    const unavailable: BookablePo['unavailable'] = [];
    for (const partner of deliveryPartners) {
      const why = unavailableFor(partner, siteCity);
      if (why) {
        unavailable.push({ partnerId: partner.id, name: partner.name, reason: why });
        continue;
      }
      const lane = laneFor(partner, originCity, siteCity);
      eligible.push({
        partnerId: partner.id,
        name: partner.name,
        trackingMode: trackingModeOf(partner),
        ratePerTrip: lane?.ratePerTrip ?? null,
        distanceKm: lane?.distanceKm ?? null,
        transitDays: lane?.transitDays ?? null,
        stats: statsFor(partnerTrips(partner.id).map((t) => t.facts)),
      });
    }
    // The proven first (a newcomer counts as neutral), the cheaper among equals, a lane with no price last.
    eligible.sort((a, b) => b.stats.score - a.stats.score || (a.ratePerTrip ?? Infinity) - (b.ratePerTrip ?? Infinity));
    out.push({ poId: po.id, poCode: po.code, supplierName: supplier.name, siteName: site.siteName, siteCity, originCity, lines: lines.map((l) => ({ id: l.id, description: l.description })), eligible, unavailable });
  }
  return out;
}

/** The one place a carrier's broken live integration becomes something a delivery can live with: in-flight live
 *  legs fall back to milestones together and return together when it is fixed. Idempotent; the heartbeat runs it. */
function syncPartnerFeeds(now: number): void {
  const at = new Date(now).toISOString();
  for (const partner of deliveryPartners) {
    const inFlight = shipmentLegs.filter((l) => l.partnerId === partner.id && !l.milestones.some((m) => m.milestone === 'arrived'));
    const openAlert = alerts.find((a) => a.relatedId === partner.id && a.titleKey === 'deliveryPartners.alert.feedDown' && a.status !== 'resolved');
    if (partner.feedStatus === 'outage') {
      const affected = inFlight.filter((l) => l.source === 'live_gps' && !l.feedLostAt);
      for (const leg of affected) {
        const brokenAt = partner.feedBrokenSince && partner.feedBrokenSince > leg.dispatchedAt ? partner.feedBrokenSince : at;
        patchInPlace(shipmentLegs, leg.id, { feedLostAt: brokenAt, feedLostReason: 'partner_outage' });
        logAutomatedAction({
          sourceKey: 'partner.feed_fallback',
          triggeringCondition: `${partner.name}'s live tracking is down`,
          actionTaken: `Moved ${byId(supplierPurchaseOrders, leg.poId)?.code ?? leg.poId} to milestone updates until it is back`,
          affectedRecordId: leg.id,
          affectedRecordType: 'purchase_order',
          subjectLabel: partner.name,
        });
      }
      if (inFlight.some((l) => l.source === 'live_gps') && !openAlert) {
        raiseAlert({
          titleKey: 'deliveryPartners.alert.feedDown',
          context: `${partner.name} · ${inFlight.length}`,
          severity: 'medium',
          category: 'supplier',
          relatedId: partner.id,
          sourceRoute: `/delivery-partners?partner=${partner.id}`,
        });
      }
    } else {
      for (const leg of inFlight.filter((l) => l.feedLostReason === 'partner_outage')) {
        patchInPlace(shipmentLegs, leg.id, { feedLostAt: undefined, feedLostReason: undefined });
        logAutomatedAction({
          sourceKey: 'partner.feed_restored',
          triggeringCondition: `${partner.name}'s live tracking is back`,
          actionTaken: `Returned ${byId(supplierPurchaseOrders, leg.poId)?.code ?? leg.poId} to live tracking`,
          affectedRecordId: leg.id,
          affectedRecordType: 'purchase_order',
          subjectLabel: partner.name,
        });
      }
    }
    if (partner.feedStatus === 'connected' && openAlert) {
      patchInPlace(alerts, openAlert.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'Their live tracking is back.' });
    }
  }
}

function validatePartnerInput(input: PartnerInput): PartnerInput {
  const name = input.name.trim();
  const contactName = input.contactName.trim();
  const phone = input.phone.replace(/[\s-]/g, '');
  const areas = [...new Set(input.serviceAreas.map((a) => a.trim()).filter(Boolean))];
  if (name.length < 3 || contactName.length < 2) throw new RepositoryError('invalid_input');
  if (!/^\+?\d{10,13}$/.test(phone)) throw new RepositoryError('invalid_phone');
  if (areas.length === 0) throw new RepositoryError('area_required');
  if (input.rateCardRef.trim().length < 2) throw new RepositoryError('rate_card_required');
  return { ...input, name, contactName, phone, serviceAreas: areas, rateCardRef: input.rateCardRef.trim(), email: input.email?.trim() || undefined };
}

/* ============================================ Delivery analytics (110) */

let disruptionCounter = 100;
const DAY_MS = 86_400_000;
const dayKeyOf = (ms: number) => new Date(ms).toISOString().slice(0, 10);

/** Everything Admin has annotated, plus outside-event delays already tagged in 105 that Admin has not written up. */
function disruptionWindows(now: number): (DeliveryDisruption & { source: 'admin' | 'delay_alerts' })[] {
  const own = deliveryDisruptions.map((d) => ({ ...d, source: 'admin' as const }));
  const byLabel = new Map<string, { from: number; to: number }>();
  for (const c of delayCases) {
    if (c.rootCause !== 'external_event' || !c.externalLabel) continue;
    const from = new Date(c.openedAt).getTime();
    const to = c.recoveredAt ? new Date(c.recoveredAt).getTime() : now;
    const prev = byLabel.get(c.externalLabel);
    byLabel.set(c.externalLabel, { from: Math.min(prev?.from ?? from, from), to: Math.max(prev?.to ?? to, to) });
  }
  const derived = [...byLabel.entries()]
    .filter(([label]) => !own.some((d) => d.label.trim().toLowerCase() === label.trim().toLowerCase()))
    .map(([label, w], i) => ({
      id: `dis-alert-${i}`,
      label,
      startsOn: dayKeyOf(w.from),
      endsOn: dayKeyOf(w.to),
      createdByName: 'Delay alerts',
      createdAt: new Date(w.from).toISOString(),
      isDemo: true,
      source: 'delay_alerts' as const,
    }));
  return [...own, ...derived];
}

interface AnalyticsTrip {
  city: string;
  hours: number;
  arrivedAt: string;
}

/** Every finished trip to a city: carriers' own, and vehicles a supplier sent itself. */
function analyticsTrips(): AnalyticsTrip[] {
  const out: AnalyticsTrip[] = [];
  for (const r of partnerTripRecords) {
    const city = r.laneLabel.split('→')[1]?.trim();
    if (city) out.push({ city, hours: (new Date(r.arrivedAt).getTime() - new Date(r.dispatchedAt).getTime()) / 3_600_000, arrivedAt: r.arrivedAt });
  }
  for (const leg of shipmentLegs) {
    const arrived = leg.milestones.find((m) => m.milestone === 'arrived');
    const city = cityOfDeal(leg.dealId);
    if (arrived && city) out.push({ city, hours: (new Date(arrived.at).getTime() - new Date(leg.dispatchedAt).getTime()) / 3_600_000, arrivedAt: arrived.at });
  }
  return out;
}

const sameOrder = (r: DeliveryDiscrepancyReport, rating: SupplierOrderRating) => r.poId === rating.poId || r.poId === rating.orderCode;

interface IncidentFact {
  key: string;
  at: string;
  supplierId: string;
  supplierFault: boolean;
  categories: string[];
}

/** One incident, once: a report, or a defect an old rating logged by hand for an order no report covers. */
function incidentFacts(): IncidentFact[] {
  const facts: IncidentFact[] = discrepancyReports
    .filter((r) => r.status !== 'withdrawn')
    .map((r) => ({ key: r.id, at: r.createdAt, supplierId: r.supplierId, supplierFault: r.attribution === 'supplier', categories: [...new Set(r.items.map((i) => i.category ?? '').filter(Boolean))] }));
  for (const rating of supplierOrderRatings) {
    // A report already speaks for its order: its defects (however they were logged) are the same incident.
    if (discrepancyReports.some((r) => r.status !== 'withdrawn' && sameOrder(r, rating))) continue;
    for (const d of rating.defects) {
      if (d.sourceReportId) continue;
      facts.push({ key: d.id, at: d.loggedAt, supplierId: rating.supplierId, supplierFault: d.attribution === 'supplier', categories: [] });
    }
  }
  return facts;
}

const reportValue = (r: DeliveryDiscrepancyReport): number =>
  r.items.reduce((sum, i) => {
    if (i.value !== undefined) return sum + i.value;
    const line = (byId(supplierPurchaseOrders, r.poId)?.lineItems ?? []).find((l) => l.id === i.lineItemId);
    return sum + (line?.agreedUnitPrice ?? 0) * (line?.quantity ?? 1);
  }, 0);

function costRowOf(r: DeliveryDiscrepancyReport): IncidentCostRowView {
  const cost = costOf({ value: reportValue(r), attribution: r.attribution ?? null, resolution: r.resolution, creditAmount: r.creditAmount, scheduleDelayDays: r.scheduleDelayDays, status: r.status });
  return {
    reportId: r.id,
    code: r.code,
    supplierName: byId(suppliers, r.supplierId)?.name ?? '',
    category: r.items.find((i) => i.category)?.category ?? null,
    at: r.createdAt,
    attribution: r.attribution ?? null,
    status: r.status === 'resolved' ? 'resolved' : 'open',
    parts: cost.parts,
    rework: cost.rework,
    schedule: cost.schedule,
    total: cost.total,
    exposure: cost.exposure,
  };
}

function kpiOf(value: number | null, previous: number | null, betterWhen: 'higher' | 'lower', flatBelow: number, pct = false): KpiFigure {
  const t = trendOf(value, previous, betterWhen, flatBelow);
  // A percentage against nothing is meaningless, so a zero base reads as "nothing earlier to compare".
  const delta = t.delta === null || (pct && !previous) ? null : pct ? Math.round((t.delta / (previous as number)) * 100) : Math.round(t.delta * 10) / 10;
  return { value, previous, direction: delta === null ? 'flat' : t.direction, tone: delta === null ? 'neutral' : t.tone, delta };
}

function computeDeliveryAnalytics(months: AnalyticsMonths, now: number): DeliveryAnalytics {
  const keys = monthKeys(months, now);
  const from = windowStart(months, now);
  const prior = previousWindow(months, now);
  const windows = disruptionWindows(now);
  const inWin = (iso: string) => new Date(iso).getTime() >= from && new Date(iso).getTime() <= now;
  const inPrev = (iso: string) => new Date(iso).getTime() >= prior.from && new Date(iso).getTime() < prior.to;

  /* ------------------------------ on time: suppliers */
  const supplierFacts = (supplierId: string | null): DeliveryFact[] =>
    supplierOrderRatings
      .filter((r) => supplierId === null || r.supplierId === supplierId)
      .map((r) => ({ at: r.deliveredAt, onTime: r.timelinessDays <= 0, setAside: inDisruption(r.deliveredAt, windows) || (r.timelinessDays > 0 && r.delayCause === 'external_event') }));
  const partnerFacts = (partnerId: string | null): DeliveryFact[] =>
    deliveryPartners
      .filter((p) => partnerId === null || p.id === partnerId)
      .flatMap((p) => partnerTrips(p.id))
      .map(({ facts }) => ({ at: facts.arrivedAt, onTime: carriedOnTime(facts), setAside: inDisruption(facts.arrivedAt, windows) || (!!facts.externalEvent && !carriedOnTime(facts)) }));

  const rowOf = (id: string, name: string, kind: 'supplier' | 'partner', facts: DeliveryFact[]): OnTimeRowView => {
    const cur = facts.filter((f) => inWin(f.at));
    const prev = facts.filter((f) => inPrev(f.at));
    const keep = (xs: DeliveryFact[]) => xs.filter((f) => !f.setAside);
    return {
      id,
      name,
      kind,
      deliveries: cur.length,
      rated: cur.length >= MIN_SAMPLE,
      onTimePct: pctOf(cur.filter((f) => f.onTime).length, cur.length),
      onTimePctExcl: pctOf(keep(cur).filter((f) => f.onTime).length, keep(cur).length),
      previousPct: pctOf(prev.filter((f) => f.onTime).length, prev.length),
      previousPctExcl: pctOf(keep(prev).filter((f) => f.onTime).length, keep(prev).length),
      setAside: cur.length - keep(cur).length,
      buckets: bucketsOf(facts, keys),
    };
  };
  const suppliersRows = suppliers
    .map((sp) => rowOf(sp.id, sp.name, 'supplier', supplierFacts(sp.id)))
    .filter((r) => r.deliveries > 0)
    .sort((a, b) => (b.onTimePct ?? -1) - (a.onTimePct ?? -1));
  const partnerRows = deliveryPartners
    .map((p) => rowOf(p.id, p.name, 'partner', partnerFacts(p.id)))
    .filter((r) => r.deliveries > 0)
    .sort((a, b) => (b.onTimePct ?? -1) - (a.onTimePct ?? -1));

  /* ------------------------------ transit by region */
  const trips = analyticsTrips();
  const curTrips = trips.filter((t) => inWin(t.arrivedAt));
  const prevTrips = trips.filter((t) => inPrev(t.arrivedAt));
  const cities = new Map<string, string>();
  for (const t of curTrips) cities.set(t.city.toLowerCase(), t.city);
  const regions: TransitRegionView[] = [...cities.entries()].map(([key, city]) => {
    const here = curTrips.filter((t) => t.city.toLowerCase() === key);
    const before = prevTrips.filter((t) => t.city.toLowerCase() === key);
    return {
      city,
      summary: transitSummary(here.map((t) => t.hours)),
      previousAvgHours: before.length >= MIN_SAMPLE ? transitSummary(before.map((t) => t.hours)).avgHours : null,
      lastArrivedAt: here.map((t) => t.arrivedAt).sort().pop() ?? null,
    };
  });
  regions.sort((a, b) => Number(a.summary.emerging) - Number(b.summary.emerging) || b.summary.trips - a.summary.trips);
  const transitNow = transitSummary(curTrips.map((t) => t.hours));
  const transitBefore = transitSummary(prevTrips.map((t) => t.hours));

  /* ------------------------------ incidents */
  const incidents = incidentFacts();
  const incWin = incidents.filter((i) => inWin(i.at));
  const incPrev = incidents.filter((i) => inPrev(i.at));
  const ratingsWin = supplierOrderRatings.filter((r) => inWin(r.deliveredAt));
  const ratingsPrev = supplierOrderRatings.filter((r) => inPrev(r.deliveredAt));
  const per100 = (n: number, d: number) => (d === 0 ? null : Math.round((n / d) * 1000) / 10);
  const incidentRow = (id: string, name: string, mine: IncidentFact[], deliveries: number | null): IncidentRowView => {
    const recent = mine.filter((i) => inLast(i.at, RISING_WINDOW_DAYS, now)).length;
    const before = mine.filter((i) => inPriorWindow(i.at, RISING_WINDOW_DAYS, now)).length;
    return {
      id,
      name,
      incidents: mine.filter((i) => inWin(i.at)).length,
      supplierFault: mine.filter((i) => inWin(i.at) && i.supplierFault).length,
      deliveries,
      per100: deliveries === null ? null : per100(mine.filter((i) => inWin(i.at)).length, deliveries),
      recent,
      prior: before,
      rising: isRising(recent, before),
      emerging: mine.length < MIN_RISING_INCIDENTS + 1,
    };
  };
  const incidentSuppliers = suppliers
    .map((sp) => incidentRow(sp.id, sp.name, incidents.filter((i) => i.supplierId === sp.id), ratingsWin.filter((r) => r.supplierId === sp.id).length))
    .filter((r) => r.incidents > 0 || r.recent > 0 || r.prior > 0)
    .sort((a, b) => Number(b.rising) - Number(a.rising) || b.incidents - a.incidents);
  const cats = [...new Set(incidents.flatMap((i) => i.categories))];
  const incidentCategories = cats
    .map((c) => incidentRow(c, c, incidents.filter((i) => i.categories.includes(c)), null))
    .sort((a, b) => Number(b.rising) - Number(a.rising) || b.incidents - a.incidents);
  const incidentMonths: IncidentMonthView[] = keys.map((key) => ({ key, incidents: incidents.filter((i) => monthKey(i.at) === key).length, deliveries: supplierOrderRatings.filter((r) => monthKey(r.deliveredAt) === key).length }));

  /* ------------------------------ cost: one incident, one cost */
  const costRows = discrepancyReports.filter((r) => r.status !== 'withdrawn' && inWin(r.createdAt)).map(costRowOf).sort((a, b) => (a.at < b.at ? 1 : -1));
  const costPrev = discrepancyReports.filter((r) => r.status !== 'withdrawn' && inPrev(r.createdAt)).map(costRowOf).reduce((n, r) => n + r.total, 0);
  const sum = (k: 'parts' | 'rework' | 'schedule' | 'total' | 'exposure') => costRows.reduce((n, r) => n + r[k], 0);
  // Retention already paused or withheld over these same faults is a different ledger: shown, never added to the cost.
  const faultyOrders = new Set(discrepancyReports.filter((r) => r.status !== 'withdrawn' && r.attribution === 'supplier' && inWin(r.createdAt)).map((r) => r.poId));
  const retentionHeld = supplierRetentions
    .filter((ret) => (ret.status === 'paused' || ret.status === 'withheld') && (faultyOrders.has(ret.poId) || faultyOrders.has(byId(supplierPurchaseOrders, ret.poId)?.code ?? '')))
    .reduce((n, ret) => n + ret.amount, 0);

  const windowsView: DisruptionView[] = windows.map((w) => {
    const startMs = new Date(`${w.startsOn}T00:00:00`).getTime();
    const endMs = new Date(`${w.endsOn}T00:00:00`).getTime() + DAY_MS;
    const affected = supplierOrderRatings.filter((r) => new Date(r.deliveredAt).getTime() >= startMs && new Date(r.deliveredAt).getTime() < endMs).length;
    return { id: w.id, label: w.label, note: w.note ?? null, startsOn: w.startsOn, endsOn: w.endsOn, source: w.source, deliveriesAffected: affected };
  });

  return {
    months: keys,
    overall: rowOf('all', '', 'supplier', supplierFacts(null)),
    suppliers: suppliersRows,
    partners: partnerRows,
    overallPartners: rowOf('all', '', 'partner', partnerFacts(null)),
    transitKpi: kpiOf(transitNow.emerging ? null : transitNow.avgHours, transitBefore.emerging ? null : transitBefore.avgHours, 'lower', 0.5, true),
    transit: regions,
    incidentKpi: kpiOf(per100(incWin.length, ratingsWin.length), per100(incPrev.length, ratingsPrev.length), 'lower', 0.5),
    incidentMonths,
    incidentSuppliers,
    incidentCategories,
    costKpi: kpiOf(sum('total'), costPrev, 'lower', 1, true),
    cost: { parts: sum('parts'), rework: sum('rework'), schedule: sum('schedule'), total: sum('total'), exposure: sum('exposure'), retentionHeld, incidents: costRows.length, rows: costRows, rates: { schedulePerDay: SCHEDULE_DELAY_COST_PER_DAY, revisit: REVISIT_COST } },
    disruptions: windowsView,
  };
}

/* ============================================ Supplier payments (111) */

const supplierPayments: SupplierPayment[] = seedSupplierPayments.map((p) => ({ ...p, events: [...p.events] }));
let supplierPaymentCounter = 100;

const paymentOrThrow = (paymentId: string): SupplierPayment => {
  const payment = byId(supplierPayments, paymentId);
  if (!payment) throw new RepositoryError('not_found');
  return payment;
};

function paymentEvents(p: SupplierPayment, kind: SupplierPaymentEvent['kind'], byName: string, note?: string): SupplierPaymentEvent[] {
  return [...p.events, { id: `${p.id}-e${p.events.length + 1}`, kind, at: new Date().toISOString(), byName, note: note?.trim() || undefined }];
}

/** When an order counts as delivered for payment: received (103) and, where a confirmation exists, signed (104). */
function paymentDeliveredAt(po: SupplierPurchaseOrder): string | null {
  if (!po.receivedAt) return null;
  const confirmations = deliveryConfirmations.filter((c) => c.poId === po.id);
  if (confirmations.length === 0) return po.receivedAt;
  if (confirmations.some((c) => c.status !== 'signed' || !c.signedAt)) return null;
  return confirmations.map((c) => c.signedAt!).sort().pop() ?? po.receivedAt;
}

/** A payment appears the moment its configured milestone genuinely fires, never before, and only once. Idempotent. */
function syncSupplierPayments(now: number): void {
  for (const po of supplierPurchaseOrders) {
    if (po.status !== 'sent' || !po.supplierId || !po.paymentTerms) continue;
    const total = poTotalOf(po.lineItems ?? []);
    if (total <= 0) continue;
    const retention = supplierRetentions.find((r) => r.poId === po.id && r.status === 'released');
    const milestones = firedMilestones({
      total,
      paymentTerms: po.paymentTerms,
      netDays: po.agreementTerms?.paymentTermsDays ?? null,
      sentAt: po.sentAt,
      acknowledgedAt: po.acknowledgedAt,
      deliveredAt: paymentDeliveredAt(po),
      retentionReleased: retention ? { amount: retention.amount, at: retention.decidedAt ?? retention.heldAt } : null,
      now,
    });
    for (const m of milestones) {
      if (supplierPayments.some((p) => p.poId === po.id && p.part === m.part)) continue;
      supplierPaymentCounter += 1;
      const created: SupplierPayment = {
        id: `spay-new-${supplierPaymentCounter}`,
        code: `AIEC-SP-${3100 + supplierPaymentCounter}`,
        poId: po.id,
        supplierId: po.supplierId,
        dealId: po.dealId,
        part: m.part,
        trigger: m.trigger,
        amount: m.amount,
        triggeredAt: m.firedAt,
        dueAt: m.dueAt,
        status: 'pending_approval',
        events: [],
        isDemo: true,
      };
      created.events = [{ id: `${created.id}-e1`, kind: 'triggered', at: m.firedAt, byName: 'AIEC Assistant' }];
      // A retention that falls due while a related dispute is still open is held on its own (112): the earlier
      // portions that already released correctly are not touched, and Admin decides when it goes.
      const disputed = m.part === 'retention' && (openReportsOnPo(po.id).length > 0 || openDisputesOnPo(po.id).length > 0 || supplierOrderRatings.some((r) => r.poId === po.id && r.dispute?.status === 'open'));
      if (disputed) {
        created.status = 'held';
        created.heldAuto = 'related_dispute';
        created.heldAt = new Date(now).toISOString();
        created.heldByName = 'AIEC Assistant';
        created.events.push({ id: `${created.id}-e2`, kind: 'held', at: created.heldAt, byName: 'AIEC Assistant' });
      }
      supplierPayments.push(created);
      logAutomatedAction({
        sourceKey: 'supplier_payment.due',
        triggeringCondition: `The ${m.part} milestone on ${po.code} fired`,
        actionTaken: disputed ? `Queued ${created.code} (${formatINR(m.amount)}) already held: a related dispute is still open` : `Queued ${created.code} (${formatINR(m.amount)}) for Admin's approval`,
        affectedRecordId: created.id,
        affectedRecordType: 'purchase_order',
        subjectLabel: po.code,
      });
    }
  }
}

/** Approved payments whose reversal window has closed are made. The one place money would actually move. */
function executeSupplierPayments(now: number): void {
  for (const p of [...supplierPayments]) {
    if (p.status !== 'approved' || !p.reversibleUntil || new Date(p.reversibleUntil).getTime() > now) continue;
    const at = new Date(now).toISOString();
    patchInPlace(supplierPayments, p.id, { status: 'executed', executedAt: at, bankReference: bankReferenceFor(p.code), events: paymentEvents(p, 'executed', 'AIEC Assistant') });
    logAutomatedAction({
      sourceKey: 'supplier_payment.executed',
      triggeringCondition: `The reversal window on ${p.code} closed with the approval standing`,
      actionTaken: `Made ${formatINR(p.amount)} to ${byId(suppliers, p.supplierId)?.name ?? 'the supplier'}`,
      affectedRecordId: p.id,
      affectedRecordType: 'purchase_order',
      subjectLabel: p.code,
    });
  }
}

/** Open reports on an order. Reports from before delivery checks were kept here name the order by its code. */
function openReportsOnPo(poId: string): DeliveryDiscrepancyReport[] {
  const code = byId(supplierPurchaseOrders, poId)?.code;
  return discrepancyReports.filter((d) => d.status === 'open' && (d.poId === poId || (!!code && d.poId === code)));
}

function paymentFlags(p: SupplierPayment): PaymentFlag[] {
  const supplier = byId(suppliers, p.supplierId);
  const kinds: HoldFlagKind[] = [];
  // A delivery balance is paid against a clean three-way match, never an unverified invoice (113). A portion Admin released
  // early, with a reason (112), is that decision and is flagged as such instead.
  const po = byId(supplierPurchaseOrders, p.poId);
  const gate = p.part === 'balance' && p.origin !== 'override' && po && (p.status === 'pending_approval' || p.status === 'held') ? invoiceGateOfPo(po) : 'ok';
  if (!supplier || !isSupplierEligibleForPO(supplier)) kinds.push('supplier_blocked');
  if (openReportsOnPo(p.poId).length > 0) kinds.push('open_report');
  if (openDisputesOnPo(p.poId).length > 0) kinds.push('supplier_dispute');
  const dealStatus = byId(deals, p.dealId)?.status;
  if (dealStatus === 'lost' || dealStatus === 'cancelled') kinds.push('orphaned');
  if (supplierOrderRatings.some((r) => r.poId === p.poId && r.dispute?.status === 'open')) kinds.push('rating_dispute');
  if (p.amount > ROUTINE_LIMIT) kinds.push('high_value');
  if (p.origin === 'override') kinds.push('early_release');
  const flags = FLAG_ORDER.filter((k) => kinds.includes(k)).map((k) => flagOf(k));
  return gate === 'ok' ? flags : [flagOf('invoice_unmatched', gate), ...flags];
}

function paymentEvidence(p: SupplierPayment): PaymentEvidence[] {
  const po = byId(supplierPurchaseOrders, p.poId);
  if (!po) return [];
  const item = (kind: PaymentEvidence['kind'], at: string | null | undefined, by?: string | null, ref?: string | null, route?: string | null): PaymentEvidence => ({ kind, at: at ?? null, by: by ?? null, ref: ref ?? null, route: route ?? null });
  const out: PaymentEvidence[] = [];
  // Released ahead of its milestone: the only honest evidence is that decision. The milestone itself has not happened.
  if (p.origin === 'override') return [item('manual_override', p.triggeredAt, p.events[0]?.byName ?? null, p.overrideReason ?? null, `/supplier-payment-release?po=${po.id}`)];
  if (p.part === 'upfront') {
    out.push(item('po_sent', po.sentAt, po.sentBy, po.code, '/orders'));
    if (p.trigger === 'on_acknowledge') out.push(item('acknowledged', po.acknowledgedAt, po.acknowledgedBy, null, '/orders'));
  } else if (p.part === 'balance') {
    out.push(item('delivery_received', po.receivedAt, po.receivedBy, po.code, `/delivery-checklist?poId=${po.id}`));
    for (const inv of supplierInvoices.filter((x) => x.poId === po.id && x.status === 'open' && evaluateInvoice(x).status === 'matched')) out.push(item('invoice_matched', inv.submittedAt, inv.submittedByName, inv.invoiceNumber, `/supplier-invoices?invoice=${inv.id}`));
    for (const c of deliveryConfirmations.filter((x) => x.poId === po.id && x.status === 'signed')) out.push(item('delivery_signed', c.signedAt, c.signatures[0]?.name ?? null, c.code, `/delivery-confirmation?confirmation=${c.id}`));
    if (po.paymentTerms?.termType === 'net') out.push(item('net_elapsed', p.dueAt, null, po.agreementTerms ? `${po.agreementTerms.paymentTermsDays}` : null));
  } else {
    const retention = supplierRetentions.find((r) => r.poId === po.id);
    out.push(item('retention_released', retention?.decidedAt, retention?.decidedBy === 'system' ? null : (retention?.decidedBy ?? null), retention ? `${retention.pct}%` : null, '/admin/suppliers/payment-terms'));
    const handover = jobs.filter((j) => j.dealId === po.dealId && j.status === 'completed' && j.completedAt).sort((a, b) => (a.completedAt! < b.completedAt! ? -1 : 1))[0];
    if (handover) out.push(item('installation_handover', handover.completedAt, null, handover.code));
  }
  return out;
}

function paymentViewOf(p: SupplierPayment, now: number): SupplierPaymentView {
  const po = byId(supplierPurchaseOrders, p.poId);
  const supplier = byId(suppliers, p.supplierId);
  const flags = paymentFlags(p);
  return {
    id: p.id,
    code: p.code,
    poId: p.poId,
    poCode: po?.code ?? p.poId,
    supplierId: p.supplierId,
    supplierName: supplier?.name ?? '',
    dealId: p.dealId,
    siteName: shipmentSite(p.dealId)?.siteName ?? '',
    part: p.part,
    trigger: p.trigger,
    amount: p.amount,
    poTotal: po ? poTotalOf(po.lineItems ?? []) : 0,
    paidOnOrder: supplierPayments.filter((x) => x.poId === p.poId && x.id !== p.id && (x.status === 'executed' || x.status === 'approved')).reduce((n, x) => n + x.amount, 0),
    status: p.status,
    triggeredAt: p.triggeredAt,
    dueAt: p.dueAt,
    overdueDays: overdueDays(p, now),
    evidence: paymentEvidence(p),
    flags,
    reports: openReportsOnPo(p.poId).map((d) => ({ id: d.id, code: d.code, itemCount: d.items.length, rush: d.rush, resolution: d.resolution })),
    routine: isRoutine(flags, p.amount),
    heldReason: p.heldReason ?? null,
    heldAuto: !!p.heldAuto,
    heldAt: p.heldAt ?? null,
    heldByName: p.heldByName ?? null,
    approvedAt: p.approvedAt ?? null,
    approvedByName: p.approvedByName ?? null,
    reversibleUntil: p.reversibleUntil ?? null,
    executedAt: p.executedAt ?? null,
    bankReference: p.bankReference ?? null,
    events: p.events,
  };
}

function approvePaymentNow(p: SupplierPayment, actor: User, acknowledged: boolean, now: number): SupplierPayment {
  if (p.status !== 'pending_approval') throw new RepositoryError('invalid_state');
  const gate = approvalGate(paymentFlags(p), acknowledged);
  if (gate === 'blocked') throw new RepositoryError(paymentFlags(p).find((f) => f.severity === 'block')?.kind ?? 'supplier_blocked');
  if (gate === 'needs_acknowledgement') throw new RepositoryError('flags_unacknowledged');
  return patchInPlace(supplierPayments, p.id, {
    status: 'approved',
    approvedAt: new Date(now).toISOString(),
    approvedByName: actor.name,
    reversibleUntil: new Date(now + REVERSAL_WINDOW).toISOString(),
    events: paymentEvents(p, 'approved', actor.name),
  });
}

/* ============================== Milestone-linked payment release (112) */

const paymentTotalOf = (po: SupplierPurchaseOrder) => poTotalOf(po.lineItems ?? []);

/** What is realistically expected for delivery: the promise, or later if a vehicle is on the road with a later ETA. */
function expectedDeliveryFor(po: SupplierPurchaseOrder, now: number): string | null {
  if (po.receivedAt) return po.receivedAt;
  const promised = promisedDeliveryOf(po);
  const etas = shipmentLegs.filter((l) => l.poId === po.id && !l.milestones.some((m) => m.milestone === 'arrived')).map((l) => l.etaAt);
  const latest = [promised, ...etas].filter((x): x is string => !!x).sort().pop();
  if (!latest) return null;
  // Never "expected" in the past: a late delivery is expected now at the earliest.
  return new Date(Math.max(new Date(latest).getTime(), now)).toISOString();
}

function chainFactsOf(po: SupplierPurchaseOrder, now: number) {
  const terms = po.paymentTerms!;
  const total = paymentTotalOf(po);
  const netDays = po.agreementTerms?.paymentTermsDays ?? null;
  const parts = paymentSchedule(total, terms, netDays);
  const retention = supplierRetentions.find((r) => r.poId === po.id);
  const released = retention && retention.status === 'released' ? retention : null;
  const deliveredAt = paymentDeliveredAt(po);
  const isNet = terms.termType === 'net' && netDays !== null;
  const mine = supplierPayments.filter((p) => p.poId === po.id);
  const allPaid = parts.every((part) => mine.some((p) => p.part === part.kind && p.status === 'executed'));
  const facts: ChainNodeFacts = {
    sentAt: po.sentAt,
    acknowledgedAt: po.acknowledgedAt,
    deliveredAt,
    receivedNotSigned: !!po.receivedAt && !deliveredAt,
    netDueAt: isNet && deliveredAt ? new Date(new Date(deliveredAt).getTime() + netDays! * 86_400_000).toISOString() : null,
    retention: released ? { at: released.decidedAt ?? released.heldAt, by: released.decidedBy && released.decidedBy !== 'system' ? released.decidedBy : null } : null,
    finishedAt: allPaid ? (mine.map((p) => p.executedAt ?? '').sort().pop() || null) : null,
    upfrontTrigger: (parts.find((p) => p.kind === 'upfront')?.trigger as 'on_send' | 'on_acknowledge' | undefined) ?? null,
    isNet,
    hasRetention: parts.some((p) => p.kind === 'retention'),
  };
  return { terms, total, netDays, parts, retention, facts, mine, now };
}

function paymentChainOf(po: SupplierPurchaseOrder, focusPaymentId: string | null, now: number): PaymentChainView {
  const { terms, total, netDays, parts, retention, facts, mine } = chainFactsOf(po, now);
  const supplier = byId(suppliers, po.supplierId ?? '');
  const anomalies = chainAnomalies(facts);
  const kinds = chainKinds(facts);
  const expectedDelivery = expectedDeliveryFor(po, now);
  const job = pendingJobFor(po.dealId);

  const expectedOf = (kind: ChainNodeKind): string | null => {
    if (kind === 'acknowledged') return po.sentAt ? new Date(Math.max(new Date(po.sentAt).getTime() + ACK_EXPECTED_AFTER, now)).toISOString() : null;
    if (kind === 'delivery_confirmed') return expectedDelivery;
    if (kind === 'net_period') return expectedDelivery && netDays !== null ? new Date(new Date(expectedDelivery).getTime() + netDays * 86_400_000).toISOString() : null;
    if (kind === 'retention_release') return job?.scheduledFor ? new Date(Math.max(new Date(job.scheduledFor).getTime() + HANDOVER_AFTER_START, now)).toISOString() : null;
    return null;
  };

  const doneKinds = kinds.filter((k) => !!firedAtOf(k, facts));
  let currentSet = false;
  const nodes: PaymentChainNodeView[] = kinds.map((kind) => {
    const fired = firedAtOf(kind, facts);
    const outOfOrder = kind === 'retention_release' && anomalies.includes('retention_before_delivery_confirmed');
    let state: ChainNodeState = fired ? 'done' : 'upcoming';
    if (outOfOrder) state = 'anomaly';
    else if (!fired && !currentSet) {
      state = 'current';
      currentSet = true;
    }
    const ref =
      kind === 'delivery_confirmed'
        ? (deliveryConfirmations.find((c) => c.poId === po.id && c.status === 'signed')?.code ?? null)
        : kind === 'net_period' && netDays !== null
          ? String(netDays)
          : null;
    const route = kind === 'delivery_confirmed' ? `/delivery-confirmation` : kind === 'retention_release' ? '/admin/suppliers/payment-terms' : kind === 'po_issued' || kind === 'acknowledged' ? '/orders' : null;
    const byName = kind === 'po_issued' ? (po.sentBy ?? null) : kind === 'acknowledged' ? (po.acknowledgedBy ?? null) : kind === 'delivery_confirmed' ? (po.receivedBy ?? null) : (fired?.by ?? null);
    return { kind, state, at: fired?.at ?? null, expectedAt: fired ? null : expectedOf(kind), source: fired?.source ?? null, byName, ref, route };
  });
  void doneKinds;

  const partViews: PaymentSplitPartView[] = parts.map((part) => {
    const kind = part.kind as SupplierPaymentPart;
    const payment = mine.find((p) => p.part === kind) ?? null;
    const pct = splitOf(total, terms).find((x) => x.part === kind)?.pct ?? 0;
    const state: SplitPartState = !payment ? 'not_due' : payment.status === 'pending_approval' ? 'pending' : payment.status === 'held' ? 'held' : payment.status === 'approved' ? 'approved' : 'paid';
    const locked = state === 'approved' || state === 'paid' || (kind === 'retention' && !!retention && retention.status === 'released');
    const expectedFor: Record<SupplierPaymentPart, string | null> = {
      upfront: part.trigger === 'on_send' ? (po.sentAt ?? null) : expectedOf('acknowledged'),
      balance: terms.termType === 'net' && netDays !== null ? expectedOf('net_period') : expectedDelivery,
      retention: expectedOf('retention_release'),
    };
    return {
      part: kind,
      pct,
      amount: payment ? payment.amount : part.amount,
      trigger: part.trigger,
      paymentId: payment?.id ?? null,
      paymentCode: payment?.code ?? null,
      state,
      dueAt: payment ? payment.dueAt : expectedFor[kind],
      dueIsExpected: !payment,
      editable: !locked && part.amount > 0,
      origin: payment?.origin ?? null,
      overrideReason: payment?.overrideReason ?? null,
      heldAuto: !!payment?.heldAuto,
      canReleaseEarly: !payment && kind !== 'retention' && part.amount > 0 && po.status === 'sent',
    };
  });

  const timeline: PaymentTimelineEntry[] = [];
  for (const n of nodes) {
    if (n.at) timeline.push({ id: `node-${n.kind}`, kind: n.kind, at: n.at, source: n.source ?? 'event', byName: n.byName, note: null, part: null });
  }
  for (const p of mine) {
    for (const e of p.events) {
      const manual = e.byName !== 'AIEC Assistant';
      // The milestone's own "triggered" is already a node above, unless a person forced it ahead of time.
      if (e.kind === 'triggered' && p.origin !== 'override') continue;
      const kind: ChainTimelineKind = e.kind === 'triggered' ? 'early_release' : e.kind === 'held' && !manual ? 'auto_held' : e.kind;
      timeline.push({ id: e.id, kind, at: e.at, source: manual ? 'manual' : 'system', byName: manual ? e.byName : null, note: e.kind === 'triggered' ? (p.overrideReason ?? null) : (e.note ?? null), part: p.part });
    }
  }
  for (const d of terms.deviations ?? []) timeline.push({ id: d.id, kind: 'split_changed', at: d.at, source: 'manual', byName: d.byName, note: d.reason, part: null });
  timeline.sort((a, b) => (a.at < b.at ? -1 : a.at > b.at ? 1 : 0));

  return {
    poId: po.id,
    poCode: po.code,
    supplierId: po.supplierId ?? '',
    supplierName: supplier?.name ?? '',
    siteName: shipmentSite(po.dealId)?.siteName ?? '',
    total,
    paid: mine.filter((p) => p.status === 'executed' || p.status === 'approved').reduce((n, p) => n + p.amount, 0),
    termType: terms.termType,
    tier: terms.tier,
    custom: terms.custom || (terms.deviations?.length ?? 0) > 0,
    upfrontPct: terms.upfrontPct,
    retentionPct: terms.retentionPct,
    netDays,
    nodes,
    parts: partViews,
    anomalies,
    deviations: terms.deviations ?? [],
    timeline,
    focusPaymentId,
  };
}

/* ============================== GST compliance (116) */

const supplierGstChecks: SupplierGstCheck[] = seedSupplierGstChecks.map((c) => ({ ...c }));
let gstCheckCounter = 100;
const gstHandovers: GstPeriodHandover[] = [];
let gstHandoverCounter = 0;
let gstHandoversSeeded = false;

const GST_ALERT = 'gstCompliance.alert.supplierRisk';
const docPeriod = (iso: string): string => (iso.length === 10 ? iso.slice(0, 7) : periodOf(iso));

function latestGstCheck(supplierId: string): SupplierGstCheck | null {
  return supplierGstChecks.filter((c) => c.supplierId === supplierId).sort((a, b) => (a.checkedAt < b.checkedAt ? 1 : -1))[0] ?? null;
}

/** The suppliers AIEC actually trades with: an invoice from them, or an order sent to them. */
function gstTradeSupplierIds(): Set<string> {
  const ids = new Set<string>();
  for (const i of supplierInvoices) ids.add(i.supplierId);
  for (const po of supplierPurchaseOrders) if (po.status === 'sent' && po.supplierId) ids.add(po.supplierId);
  return ids;
}

function gstRiskOf(supplier: Supplier, now: number): SupplierRisk {
  const check = latestGstCheck(supplier.id);
  return supplierRisk(supplier.gstin, check ? { standing: check.standing, lastReturnPeriod: check.lastReturnPeriod, effectiveFrom: check.effectiveFrom, checkedAt: check.checkedAt } : null, now);
}

/** Customer invoices are made from paid stages on demand, so the tax reading makes sure every paid stage has its one. */
function backfillCustomerInvoices(): void {
  for (const deal of deals) {
    if (payments.some((p) => p.dealId === deal.id && (p.status === 'paid' || (p.status === 'disputed' && p.preDisputeStatus === 'paid')) && !invoices.some((inv) => inv.paymentId === p.id))) {
      ensureStageInvoices(deal.id, deal, resolveLead(deal.leadId));
    }
  }
}

/** Every tax document AIEC has, both sides, each at the rate written on it. The consolidated final invoice restates its stage
 *  invoices and a superseded invoice is replaced by its reissue, so neither counts again. */
function gstDocumentsOf(now: number): GstDocument[] {
  backfillCustomerInvoices();
  const out: GstDocument[] = [];
  for (const inv of invoices) {
    if (inv.type === 'final' || invoices.some((o) => o.supersedesInvoiceId === inv.id)) continue;
    const supply = supplyType(inv.customerGstin, inv.aiecGstin);
    out.push({
      id: inv.id,
      side: 'output',
      isCreditNote: inv.type === 'credit_note',
      code: inv.code,
      party: inv.customerName,
      ref: byId(deals, inv.dealId)?.code ?? inv.dealId,
      date: inv.issuedAt,
      ratePct: inv.gstPercent,
      taxable: inv.taxableValue,
      gst: inv.gstAmount,
      split: splitTax(inv.gstAmount, supply),
      supply,
      credit: null,
      supplierId: null,
      route: `/deals/${inv.dealId}/invoices`,
    });
  }
  const risks = new Map<string, SupplierRisk>();
  for (const inv of supplierInvoices) {
    if (inv.status !== 'open') continue;
    const supplier = byId(suppliers, inv.supplierId);
    if (!supplier) continue;
    if (!risks.has(supplier.id)) risks.set(supplier.id, gstRiskOf(supplier, now));
    const taxable = inv.lines.reduce((n, l) => n + l.quantity * l.unitPrice, 0);
    const gst = gstOn(taxable, inv.gstPercent);
    const supply = supplyType(supplier.gstin, AIEC_GSTIN);
    out.push({
      id: inv.id,
      side: 'input',
      isCreditNote: false,
      code: inv.invoiceNumber,
      party: supplier.name,
      ref: byId(supplierPurchaseOrders, inv.poId)?.code ?? inv.poId,
      date: inv.invoiceDate,
      ratePct: inv.gstPercent,
      taxable,
      gst,
      split: splitTax(gst, supply),
      supply,
      credit: creditStatus(inv.invoiceDate, evaluateInvoice(inv).status === 'matched', risks.get(supplier.id)!),
      supplierId: supplier.id,
      route: `/supplier-invoices?invoice=${inv.id}`,
    });
  }
  return out;
}

const signedGst = (d: GstDocument, n: number) => (d.isCreditNote ? -n : n);

function gstSideOf(docs: GstDocument[]): GstSide {
  const byRate = new Map<number, GstRateBucket>();
  let split = ZERO_SPLIT;
  let taxable = 0;
  let gst = 0;
  for (const d of docs) {
    const t = signedGst(d, d.taxable);
    const g = signedGst(d, d.gst);
    taxable += t;
    gst += g;
    split = addSplit(split, { cgst: signedGst(d, d.split.cgst), sgst: signedGst(d, d.split.sgst), igst: signedGst(d, d.split.igst) });
    const b = byRate.get(d.ratePct) ?? { ratePct: d.ratePct, taxable: 0, gst: 0 };
    b.taxable += t;
    b.gst += g;
    byRate.set(d.ratePct, b);
  }
  return { taxable, gst, split, count: docs.length, byRate: [...byRate.values()].sort((a, b) => b.ratePct - a.ratePct) };
}

function gstFiguresOf(docs: GstDocument[], period: string) {
  const inPeriod = docs.filter((d) => docPeriod(d.date) === period);
  const out = inPeriod.filter((d) => d.side === 'output');
  const inp = inPeriod.filter((d) => d.side === 'input');
  const sumCredit = (c: CreditStatus) => inp.filter((d) => d.credit === c).reduce((n, d) => n + d.gst, 0);
  const output = { ...gstSideOf(out), creditNotes: out.filter((d) => d.isCreditNote).reduce((n, d) => n + d.gst, 0) };
  const input = { ...gstSideOf(inp), claimable: sumCredit('claimable'), pendingMatch: sumCredit('pending_match'), atRisk: sumCredit('at_risk') };
  return { inPeriod, output, input, net: output.gst - input.claimable };
}

/** The two months just closed have already gone to the accountant; the demo starts from there. Later months are Admin's to hand over. */
function ensureGstHandovers(now: number): void {
  if (gstHandoversSeeded) return;
  gstHandoversSeeded = true;
  const docs = gstDocumentsOf(now);
  for (const period of [shiftPeriod(periodOf(now), -2), shiftPeriod(periodOf(now), -1)]) {
    if (gstHandovers.some((h) => h.period === period)) continue;
    const f = gstFiguresOf(docs, period);
    if (f.inPeriod.length === 0) continue;
    gstHandoverCounter += 1;
    gstHandovers.push({ id: `gsh-${gstHandoverCounter}`, period, handedOverAt: new Date(handoverDueAt(period)).toISOString(), byName: 'Prashant Vasant Wable', outputGst: f.output.gst, inputClaimable: f.input.claimable, atRisk: f.input.atRisk, isDemo: true });
  }
}

function gstCheckViewOf(c: SupplierGstCheck): SupplierGstCheckView {
  return { id: c.id, gstin: c.gstin, standing: c.standing, lastReturnPeriod: c.lastReturnPeriod, effectiveFrom: c.effectiveFrom ?? null, checkedAt: c.checkedAt, checkedByName: c.checkedByName, note: c.note ?? null };
}

function gstSupplierViews(docs: GstDocument[], period: string, now: number): SupplierGstView[] {
  const handed = new Set(gstHandovers.map((h) => h.period));
  const trade = gstTradeSupplierIds();
  const weight: Record<SupplierRiskKind, number> = { restricted: 0, filing_late: 1, no_gstin: 2, invalid_gstin: 3, unverified: 4, ok: 5 };
  return suppliers
    .filter((sp) => trade.has(sp.id) || supplierGstChecks.some((c) => c.supplierId === sp.id))
    .map((sp): SupplierGstView => {
      const risk = gstRiskOf(sp, now);
      const check = latestGstCheck(sp.id);
      const mine = docs.filter((d) => d.side === 'input' && d.supplierId === sp.id);
      return {
        supplierId: sp.id,
        name: sp.name,
        gstin: sp.gstin ?? null,
        risk: risk.kind,
        riskSince: risk.since,
        stale: risk.stale,
        current: check ? gstCheckViewOf(check) : null,
        history: supplierGstChecks.filter((c) => c.supplierId === sp.id).sort((a, b) => (a.checkedAt < b.checkedAt ? 1 : -1)).map(gstCheckViewOf),
        inputThisPeriod: mine.filter((d) => docPeriod(d.date) === period).reduce((n, d) => n + d.gst, 0),
        atRisk: mine.filter((d) => d.credit === 'at_risk').reduce((n, d) => n + d.gst, 0),
        alreadyHandedOver: mine.filter((d) => d.credit === 'at_risk' && handed.has(docPeriod(d.date))).reduce((n, d) => n + d.gst, 0),
      };
    })
    .sort((a, b) => weight[a.risk] - weight[b.risk] || Number(b.stale) - Number(a.stale) || a.name.localeCompare(b.name));
}

function gstComplianceOf(periodIn: string | null, now: number): GstComplianceView {
  ensureGstHandovers(now);
  const docs = gstDocumentsOf(now);
  const period = periodIn && /^\d{4}-\d{2}$/.test(periodIn) ? periodIn : periodOf(now);
  const f = gstFiguresOf(docs, period);
  const prevPeriod = shiftPeriod(period, -1);
  const pf = gstFiguresOf(docs, prevPeriod);
  const suppliersView = gstSupplierViews(docs, period, now);
  const snap = gstHandovers.find((h) => h.period === period);
  const known = [...new Set([...docs.map((d) => docPeriod(d.date)), ...recentPeriods(now, 6)])];
  return {
    period,
    periods: [...new Set([...recentPeriods(now, 6), ...known.filter((p) => p <= periodOf(now))])].sort().reverse().slice(0, 12),
    aiecGstin: AIEC_GSTIN,
    output: f.output,
    input: f.input,
    net: f.net,
    previous: pf.inPeriod.length > 0 ? { outputGst: pf.output.gst, claimable: pf.input.claimable, net: pf.net } : null,
    suppliers: suppliersView,
    documents: f.inPeriod.sort((a, b) => (a.date < b.date ? 1 : -1)),
    handover: snap
      ? { at: snap.handedOverAt, byName: snap.byName, note: snap.note ?? null, outputGst: snap.outputGst, inputClaimable: snap.inputClaimable, changed: snap.outputGst !== f.output.gst || snap.inputClaimable !== f.input.claimable, outputDelta: f.output.gst - snap.outputGst, inputDelta: f.input.claimable - snap.inputClaimable }
      : null,
    exposure: {
      atRisk: suppliersView.reduce((n, sp) => n + sp.atRisk, 0),
      alreadyHandedOver: suppliersView.reduce((n, sp) => n + sp.alreadyHandedOver, 0),
      suppliersAffected: suppliersView.filter((sp) => sp.atRisk > 0).length,
      suppliersToCheck: suppliersView.filter((sp) => sp.risk !== 'ok' || sp.stale).length,
    },
  };
}

/** A supplier whose standing puts credit already assumed in doubt is put in front of Admin once, and the alert clears itself
 *  when the doubt does. Idempotent: the heartbeat calls it every minute. */
function syncGstCompliance(now: number): void {
  ensureGstHandovers(now);
  const docs = gstDocumentsOf(now);
  const views = gstSupplierViews(docs, periodOf(now), now);
  const at = new Date(now).toISOString();
  for (const v of views) {
    const open = alerts.find((a) => a.relatedId === v.supplierId && a.titleKey === GST_ALERT && a.status !== 'resolved');
    if (v.atRisk > 0 && !open) {
      raiseAlert({
        titleKey: GST_ALERT,
        context: `${v.name} · ${formatINR(v.atRisk)}${v.alreadyHandedOver > 0 ? ` (${formatINR(v.alreadyHandedOver)} already claimed)` : ''}`,
        severity: v.alreadyHandedOver > 0 ? 'high' : 'medium',
        category: 'payment',
        relatedId: v.supplierId,
        sourceRoute: `/gst-compliance?supplier=${v.supplierId}`,
      });
      logAutomatedAction({
        sourceKey: 'gst.supplier_risk',
        triggeringCondition: `${v.name}'s GST standing puts ${formatINR(v.atRisk)} of input credit in doubt`,
        actionTaken: 'Raised an alert for Admin and the accountant',
        affectedRecordId: v.supplierId,
        affectedRecordType: 'other',
        subjectLabel: v.name,
      });
    } else if (v.atRisk === 0 && open) {
      patchInPlace(alerts, open.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'The supplier’s GST standing no longer puts credit in doubt.' });
    }
  }
}

/* ============================== Advance payment & retention (118) */

const advanceRecoveries: AdvanceRecovery[] = [];
let recoveryCounter = 0;
const ADVANCE_ALERT = 'advanceRetention.alert.exposure';

const recoveryEvents = (r: AdvanceRecovery, kind: AdvanceRecovery['events'][number]['kind'], byName: string, extra: { amount?: number; note?: string } = {}) => [
  ...r.events,
  { id: `${r.id}-e${r.events.length + 1}`, kind, at: new Date().toISOString(), byName, amount: extra.amount, note: extra.note?.trim() || undefined },
];

function recoveryViewOf(r: AdvanceRecovery): AdvanceRecoveryView {
  return { id: r.id, code: r.code, status: r.status, amount: r.amount, recoveredAmount: r.recoveredAmount, writtenOffAmount: r.writtenOffAmount, reason: r.reason, startedByName: r.startedByName, startedAt: r.startedAt, events: r.events };
}

/** Advances paid and not yet backed by a delivery: money out before the goods came. */
function advanceItemsOf(now: number): AdvanceItemView[] {
  const out: AdvanceItemView[] = [];
  for (const p of supplierPayments) {
    if (p.part !== 'upfront' || p.status !== 'executed') continue;
    const po = byId(supplierPurchaseOrders, p.poId);
    if (!po || paymentDeliveredAt(po)) continue;
    const recovery = advanceRecoveries.find((r) => r.paymentId === p.id);
    // A recovery that has been closed (money back, or written off) is settled: it lives on in Payment History.
    if (recovery && recovery.status !== 'open') continue;
    const entry = historyEntryOf(p);
    if (entry.netAmount <= 0) continue;
    const reading = readAdvance({ delivered: false, promisedAt: promisedDeliveryOf(po) ?? null, dealGone: isOrphanedPo(po), recoveryOpen: !!recovery }, now);
    const paidAt = p.executedAt ?? p.approvedAt ?? p.triggeredAt;
    out.push({
      id: p.id,
      code: p.code,
      poId: po.id,
      poCode: po.code,
      supplierId: p.supplierId,
      supplierName: byId(suppliers, p.supplierId)?.name ?? '',
      siteName: shipmentSite(po.dealId)?.siteName ?? '',
      outstanding: entry.netAmount,
      paidAmount: p.amount,
      paidAt,
      ageDays: Math.max(0, Math.floor((now - new Date(paidAt).getTime()) / 86_400_000)),
      promisedAt: promisedDeliveryOf(po) ?? null,
      daysPastPromise: reading.daysPastPromise,
      state: reading.state,
      recommendRecovery: reading.recommendRecovery,
      stage: poStageOf(po),
      recovery: recovery ? recoveryViewOf(recovery) : null,
    });
  }
  return out.sort((a, b) => Number(b.recommendRecovery) - Number(a.recommendRecovery) || b.daysPastPromise - a.daysPastPromise || b.ageDays - a.ageDays);
}

function retentionItemsOf(now: number): RetentionItemView[] {
  return supplierRetentions
    .filter((r) => r.status === 'held' || r.status === 'paused')
    .map((r): RetentionItemView => {
      const po = byId(supplierPurchaseOrders, r.poId);
      const reading = readRetention(r.status, r.heldAt, jobs.filter((j) => j.dealId === r.dealId));
      const rating = supplierOrderRatings.find((x) => x.poId === r.poId);
      const holds: RetentionHold[] = [];
      if (r.status === 'paused' || rating?.defects.some((d) => d.attribution === 'supplier')) holds.push('defect');
      if (openReportsOnPo(r.poId).length > 0) holds.push('open_report');
      if (openDisputesOnPo(r.poId).length > 0) holds.push('open_dispute');
      const age = Math.max(0, Math.floor((now - new Date(r.heldAt).getTime()) / 86_400_000));
      return {
        id: r.id,
        poId: r.poId,
        poCode: po?.code ?? r.poId,
        supplierId: r.supplierId,
        supplierName: byId(suppliers, r.supplierId)?.name ?? '',
        siteName: po ? (shipmentSite(po.dealId)?.siteName ?? reading.job?.siteName ?? '') : (reading.job?.siteName ?? ''),
        amount: r.amount,
        pct: r.pct,
        heldAt: r.heldAt,
        ageDays: age,
        status: r.status,
        readiness: reading.readiness,
        progress: reading.progress,
        job: reading.job,
        holds,
        bulkOk: batchSkipReason(r.status, reading.readiness, holds) === null,
        reviewDue: now - new Date(r.heldAt).getTime() >= RETENTION_REVIEW_AFTER && reading.readiness !== 'ready',
      };
    })
    .sort((a, b) => Number(b.bulkOk) - Number(a.bulkOk) || b.ageDays - a.ageDays);
}

/** An advance that is late, stalled or for a deal that is gone is a financial risk Admin must see on the alerts board. Idempotent. */
function syncAdvanceExposure(now: number): void {
  const at = new Date(now).toISOString();
  const items = advanceItemsOf(now);
  for (const a of items) {
    const open = alerts.find((x) => x.relatedId === a.id && x.titleKey === ADVANCE_ALERT && x.status !== 'resolved');
    const risky = a.state === 'late' || a.state === 'stalled' || a.state === 'deal_gone';
    if (risky && !open) {
      raiseAlert({
        titleKey: ADVANCE_ALERT,
        context: `${a.supplierName} · ${a.poCode} · ${formatINR(a.outstanding)} out for ${a.ageDays} days`,
        severity: a.state === 'late' ? 'medium' : 'high',
        category: 'payment',
        relatedId: a.id,
        sourceRoute: `/advance-retention?advance=${a.id}`,
      });
      logAutomatedAction({
        sourceKey: 'advance.exposure',
        triggeringCondition: `The advance ${a.code} is still out with no delivery`,
        actionTaken: 'Raised an alert so the exposure is seen',
        affectedRecordId: a.id,
        affectedRecordType: 'purchase_order',
        subjectLabel: a.poCode,
      });
    } else if (!risky && open) {
      patchInPlace(alerts, open.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'The advance is no longer exposed.' });
    }
  }
  // An alert for an advance that has since been delivered or closed goes too.
  for (const open of alerts.filter((x) => x.titleKey === ADVANCE_ALERT && x.status !== 'resolved')) {
    if (!items.some((i) => i.id === open.relatedId)) patchInPlace(alerts, open.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'The advance is settled.' });
  }
}

function advanceRecoveryOrThrow(id: string): AdvanceRecovery {
  const r = byId(advanceRecoveries, id);
  if (!r) throw new RepositoryError('not_found');
  return r;
}

/* ============================== Supplier dispute resolution (117) */

const supplierDisputes: SupplierDispute[] = seedSupplierDisputes.map((d) => ({ ...d, decisions: d.decisions.map((x) => ({ ...x })), events: [...d.events], processFlag: d.processFlag ? { ...d.processFlag } : undefined }));
let disputeCounter = 6100;
let disputeEventCounter = 0;
const DISPUTE_HALT_ALERT = 'supplierDispute.alert.haltThreat';

const openDisputesOnPo = (poId: string) => supplierDisputes.filter((d) => d.status === 'open' && d.poId === poId);
const disputeEvent = (d: SupplierDispute, kind: SupplierDisputeEvent['kind'], byName: string, note?: string): SupplierDisputeEvent[] => {
  disputeEventCounter += 1;
  return [...d.events, { id: `${d.id}-e${d.events.length + 1}-${disputeEventCounter}`, kind, at: new Date().toISOString(), byName, note: note?.trim() || undefined }];
};
const given = (d: SupplierDispute) => d.decisions.reduce((n, x) => n + x.amount, 0);

/** A decided dispute the supplier can still contest. */
const disputeCanReopen = (d: SupplierDispute, now: number): boolean => d.status === 'resolved' && now - new Date(d.decisions[d.decisions.length - 1]?.at ?? d.raisedAt).getTime() <= REOPEN_WINDOW;

function disputeRowOf(d: SupplierDispute, now: number): SupplierDisputeRow {
  const po = byId(supplierPurchaseOrders, d.poId);
  const sla = slaOf(d.status, d.roundStartedAt, d.threatensHalt, now);
  return {
    id: d.id,
    code: d.code,
    supplierId: d.supplierId,
    supplierName: byId(suppliers, d.supplierId)?.name ?? '',
    poId: d.poId,
    poCode: po?.code ?? d.poId,
    siteName: po ? (shipmentSite(po.dealId)?.siteName ?? '') : '',
    kind: d.kind,
    position: d.position,
    claimedAmount: d.claimedAmount,
    status: d.status,
    round: d.round,
    raisedAt: d.raisedAt,
    dueAt: dueAtOf(d.roundStartedAt, d.threatensHalt),
    sla: sla.state,
    slaSeverity: sla.severity,
    threatensHalt: d.threatensHalt,
    lastDecision: d.decisions[d.decisions.length - 1]?.decision ?? null,
    processFlagOpen: d.processFlag?.status === 'open',
  };
}

/** Which real correction a "for the supplier" decision would make on this dispute's target. */
function disputeEffectOf(d: SupplierDispute): DisputeEffect {
  if (d.kind === 'retention_timing') return 'retention_release';
  if (d.kind === 'invoice') return 'invoice_accept';
  const p = d.paymentId ? byId(supplierPayments, d.paymentId) : undefined;
  return p && (p.status === 'pending_approval' || p.status === 'held') ? 'payment_amount' : 'payment_adjustment';
}

function disputeViewOf(d: SupplierDispute, now: number): SupplierDisputeView {
  const row = disputeRowOf(d, now);
  const po = byId(supplierPurchaseOrders, d.poId);
  const supplier = byId(suppliers, d.supplierId);
  const payment = d.paymentId ? byId(supplierPayments, d.paymentId) : undefined;
  const retention = d.retentionId ? byId(supplierRetentions, d.retentionId) : undefined;
  const invoice = d.invoiceId ? byId(supplierInvoices, d.invoiceId) : undefined;
  const entry = payment ? historyEntryOf(payment) : null;
  const detail = payment ? historyDetailOf(payment, { supplierId: null }) : null;
  const rating = po ? supplierOrderRatings.find((r) => r.poId === po.id) : undefined;
  const others = supplierDisputes.filter((x) => x.supplierId === d.supplierId && x.id !== d.id);
  const decided = others.filter((x) => x.status === 'resolved');
  const last = (x: SupplierDispute) => x.decisions[x.decisions.length - 1]?.decision;
  const facts = { kind: d.kind, claimed: d.claimedAmount, alreadyGiven: given(d) };
  return {
    ...row,
    supplierPosition: d.position,
    raisedByName: d.raisedByName,
    raisedByRole: d.raisedByRole,
    targetLabel: payment ? payment.code : retention ? formatINR(retention.amount) : (invoice?.invoiceNumber ?? ''),
    evidence: {
      poTotal: po ? paymentTotalOf(po) : 0,
      basis: detail?.basis ?? null,
      payment: payment && entry ? { id: payment.id, code: payment.code, part: payment.part, amount: payment.amount, netAmount: entry.netAmount, status: payment.status, paidAt: payment.executedAt ?? null, bankReference: payment.bankReference ?? null } : null,
      adjustments: detail?.adjustments ?? [],
      retention: retention ? { id: retention.id, amount: retention.amount, pct: retention.pct, status: retention.status, heldAt: retention.heldAt, pausedAt: retention.pausedAt ?? null, decidedAt: retention.decidedAt ?? null } : null,
      invoices: supplierInvoices.filter((i) => i.poId === d.poId && i.status === 'open').map((i) => ({ id: i.id, number: i.invoiceNumber, date: i.invoiceDate, subtotal: i.lines.reduce((n, l) => n + l.quantity * l.unitPrice, 0), status: evaluateInvoice(i).status })),
      rejectedInvoices: supplierInvoices.filter((i) => i.poId === d.poId && i.status === 'rejected').map((i) => ({ id: i.id, number: i.invoiceNumber, reason: i.rejectedReason ?? null })),
      openReports: po ? openReportsOnPo(po.id).map((r) => ({ id: r.id, code: r.code, status: r.status })) : [],
      defects: rating?.defects.length ?? 0,
      deliveredLines: po ? (po.lineItems ?? []).map((l) => ({ description: l.description, ordered: l.quantity, accepted: acceptedQtyOf(po, l) })) : [],
    },
    relationship: {
      onTimeRate: supplier?.onTimeRate ?? null,
      qualityScore: supplier?.qualityScore ?? null,
      ratedOrders: supplierOrderRatings.filter((r) => r.supplierId === d.supplierId).length,
      agreementState: agreementStateFor(d.supplierId, now).status,
      tier: supplier?.paymentTier ?? 'new',
      openOrders: supplierPurchaseOrders.filter((x) => x.supplierId === d.supplierId && x.status === 'sent' && !x.receivedAt).length,
      orderValue: supplier?.totalOrderValue ?? 0,
      alternatives: suppliers.filter((x) => x.id !== d.supplierId && x.status === 'active' && x.kycStatus === 'approved' && x.categories.some((c) => supplier?.categories.includes(c))).length,
      priorDisputes: { total: decided.length, supplierFavor: decided.filter((x) => last(x) === 'supplier_favor').length, partial: decided.filter((x) => last(x) === 'partial').length, upheld: decided.filter((x) => last(x) === 'uphold').length },
      otherOpenDisputes: others.filter((x) => x.status === 'open').length,
    },
    decisions: d.decisions.map((x) => ({ ...x })),
    events: d.events,
    processFlag: d.processFlag ?? null,
    effect: disputeEffectOf(d),
    alreadyGiven: given(d),
    maxAmount: maxAmountOf(facts),
    canPartial: canPartial(d.kind),
    canReopen: disputeCanReopen(d, now),
  };
}

/** A supplier who says it may stop taking orders is a relationship risk Admin must not miss: one alert while it is open. Idempotent. */
function syncSupplierDisputes(now: number): void {
  const at = new Date(now).toISOString();
  for (const d of supplierDisputes) {
    const open = alerts.find((a) => a.relatedId === d.id && a.titleKey === DISPUTE_HALT_ALERT && a.status !== 'resolved');
    if (d.status === 'open' && d.threatensHalt && !open) {
      raiseAlert({
        titleKey: DISPUTE_HALT_ALERT,
        context: `${d.code} · ${byId(suppliers, d.supplierId)?.name ?? ''}`,
        severity: 'high',
        category: 'supplier',
        relatedId: d.id,
        sourceRoute: `/supplier-disputes?dispute=${d.id}`,
      });
      logAutomatedAction({
        sourceKey: 'supplier_dispute.halt_threat',
        triggeringCondition: `${byId(suppliers, d.supplierId)?.name ?? 'A supplier'} said it may stop taking orders over ${d.code}`,
        actionTaken: 'Raised an alert so the relationship risk is seen with the dispute',
        affectedRecordId: d.id,
        affectedRecordType: 'other',
        subjectLabel: d.code,
      });
    } else if ((d.status === 'resolved' || !d.threatensHalt) && open) {
      patchInPlace(alerts, open.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'The dispute was decided.' });
    }
  }
}

/** Tells the supplier in the order's thread, when they have a login. */
function disputeMessage(d: SupplierDispute, author: 'aiec' | 'supplier', authorName: string, authorUserId: string | undefined, body: string): void {
  const supplier = byId(suppliers, d.supplierId);
  const po = byId(supplierPurchaseOrders, d.poId);
  if (!supplier || !po) return;
  if (author === 'aiec' && !supplierUserFor(supplier)) return;
  pushSupplierMessage(ensureSupplierThread(supplier.id, po.id), { author, authorName, authorUserId, body, channel: 'in_app', at: new Date().toISOString(), expectsReply: false, poRef: po.id });
}

const DECISION_WORDS: Record<SupplierDisputeDecision, string> = { uphold: 'AIEC has upheld the original', supplier_favor: 'AIEC has decided in your favour', partial: 'AIEC has adjusted in part' };

/** One technician's row on 024's leaderboard. Everything that shows a technician's quality reads this, so the number they see on
 *  their own home is the one Admin is judging them on. */
function technicianScoreOf(u: User): TechnicianScore {
  const own = jobs.filter((j) => j.technicianId === u.id);
  const done = own.filter((j) => j.status === 'completed');
  return {
    userId: u.id,
    name: u.name,
    jobsCompleted: done.length,
    onTimeRate: done.length ? 0.8 + (u.id.charCodeAt(u.id.length - 1) % 3) * 0.06 : 0,
    qcPassRate: 0.85 + (u.id.charCodeAt(u.id.length - 1) % 4) * 0.035,
    avgDaysPerJob: 16 + (u.id.charCodeAt(u.id.length - 1) % 5),
    rating: u.rating ?? 0,
  };
}

/* ============================== Technician home (121) */

const fieldSosAttempts: FieldSosAttempt[] = [];
let fieldSosCounter = 0;
const SOS_ALERT = 'alerts.type.fieldSos';
const CLASH_ALERT = 'alerts.type.scheduleClash';

/** An SOS whose window has closed is sent, by whoever's clock reaches it first: the phone that pressed it need not stay open. */
function sendDueSos(now: number): void {
  for (const a of fieldSosAttempts) {
    if (a.status !== 'pending' || new Date(a.sendsAt).getTime() > now) continue;
    const who = byId(users, a.userId);
    const job = a.jobId ? byId(jobs, a.jobId) : null;
    const alert = raiseAlert({
      titleKey: SOS_ALERT,
      context: `${who?.name ?? ''} · ${job ? `${job.code} · ${job.siteName}` : (who?.city ?? '')}`,
      severity: 'critical',
      category: 'safety',
      relatedId: a.id,
      sourceRoute: '/admin/escalations',
      location: a.location,
    });
    patchInPlace(fieldSosAttempts, a.id, { status: 'sent', alertId: alert.id });
    logAutomatedAction({
      sourceKey: 'field_sos.sent',
      triggeringCondition: `${who?.name ?? 'A field worker'} pressed SOS and did not cancel within the window`,
      actionTaken: 'Raised a critical safety alert for Admin, with the location it was pressed at',
      affectedRecordId: alert.id,
      affectedRecordType: 'alert',
      subjectLabel: who?.name ?? '',
    });
  }
}

/** Two jobs booked for the same day for one technician is a scheduling mistake, not something the technician can fix: Admin is told
 *  once per technician and day, and it clears itself when the bookings are apart again. */
function syncTechnicianClashes(now: number): void {
  const at = new Date(now).toISOString();
  const live = new Set<string>();
  for (const u of users) {
    if (u.role !== 'technician') continue;
    for (const c of clashesOf(jobs.filter((j) => isOnJob(j, u.id)))) {
      const key = `clash:${u.id}:${c.date}`;
      live.add(key);
      if (alerts.some((a) => a.relatedId === key && a.titleKey === CLASH_ALERT && a.status !== 'resolved')) continue;
      raiseAlert({ titleKey: CLASH_ALERT, context: `${u.name} · ${c.jobIds.map((id) => byId(jobs, id)?.code ?? id).join(' + ')} · ${c.date}`, severity: 'medium', category: 'staffing', relatedId: key, sourceRoute: '/admin/routes' });
      logAutomatedAction({
        sourceKey: 'technician.schedule_clash',
        triggeringCondition: `${u.name} is booked on two jobs on ${c.date}`,
        actionTaken: 'Raised an alert so the bookings can be moved apart',
        affectedRecordId: key,
        affectedRecordType: 'other',
        subjectLabel: u.name,
      });
    }
  }
  for (const a of alerts) {
    if (a.titleKey === CLASH_ALERT && a.status !== 'resolved' && !live.has(a.relatedId ?? '')) patchInPlace(alerts, a.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'The bookings are no longer on the same day.' });
  }
}

function fieldSosViewOf(a: FieldSosAttempt): FieldSosView {
  const alert = a.alertId ? byId(alerts, a.alertId) : null;
  return { id: a.id, status: a.status, startedAt: a.startedAt, sendsAt: a.sendsAt, alertStatus: alert ? alert.status : null };
}

const SPEC_FIELDS = ['driveType', 'capacityPersons', 'capacityKg', 'stopsCount', 'travelHeightM', 'finishTier'] as const;

/** The configuration that was sold: the deal's accepted quotation, latest version, and no other source. A technician installs
 *  exactly this, so a survey estimate or an earlier draft can never stand in for it. */
function lockedSpecOf(leadId: string): JobSpecView | null {
  // The accepted version. While a change is being drafted the accepted one is marked superseded but is still what is contracted, so the
  // newest version that was ever accepted stands until its replacement is accepted.
  const everAccepted = quotations.filter((q) => q.leadId === leadId && !!q.acceptedAt);
  const accepted = everAccepted.filter((q) => q.status === 'accepted').sort((a, b) => b.version - a.version)[0] ?? everAccepted.sort((a, b) => b.version - a.version)[0];
  if (!accepted) return null;
  const before = accepted.supersedesQuotationId ? byId(quotations, accepted.supersedesQuotationId) : undefined;
  return {
    quotationId: accepted.id,
    quotationCode: accepted.code,
    version: accepted.version,
    acceptedAt: accepted.acceptedAt ?? accepted.createdAt,
    driveType: accepted.driveType,
    capacityPersons: accepted.capacityPersons,
    capacityKg: accepted.capacityKg,
    stopsCount: accepted.stopsCount,
    travelHeightM: accepted.travelHeightM,
    finishTier: accepted.finishTier,
    customConfiguration: accepted.customConfiguration,
    overrideNote: accepted.specOverrideNote ?? null,
    revision: before ? { fromVersion: before.version, changed: SPEC_FIELDS.filter((f) => before[f] !== accepted[f]) } : null,
  };
}

/** What has actually reached the site for a deal, read from the delivery records: a part is "on site" only once the delivery check
 *  accepted it and the receiving was signed, so a technician never turns up expecting parts the system does not know arrived. */
function jobMaterialsOf(dealId: string): TechnicianJobDetail['materials'] {
  const pos = supplierPurchaseOrders.filter((po) => po.dealId === dealId && po.status === 'sent' && (po.lineItems ?? []).length > 0);
  const lines: JobMaterialView[] = [];
  for (const po of pos) {
    const held = heldLineIds(discrepancyReports, po.id);
    const hasChecks = deliveryChecklists.some((c) => c.poId === po.id);
    const unsigned = deliveryConfirmations.some((c) => c.poId === po.id && c.status !== 'signed');
    for (const line of po.lineItems ?? []) {
      const stage = lineStageOf(po, line);
      const leg = shipmentLegs.find((l) => l.poId === po.id && l.lineItemIds.includes(line.id) && !l.milestones.some((m) => m.milestone === 'arrived'));
      let state: JobMaterialView['state'];
      let expectedAt: string | null = null;
      if (held.includes(line.id)) state = 'issue';
      else if (stage === 'delivered') state = hasChecks && unsigned ? 'awaiting_signature' : 'on_site';
      else if (stage === 'shipped') {
        state = 'in_transit';
        expectedAt = leg?.etaAt ?? promisedDeliveryOf(po);
      } else {
        state = 'preparing';
        expectedAt = promisedDeliveryOf(po);
      }
      lines.push({ id: line.id, poCode: po.code, category: line.category, description: line.description, quantity: line.quantity, state, expectedAt });
    }
  }
  return { lines, onSite: lines.filter((l) => l.state === 'on_site').length, total: lines.length, noOrders: pos.length === 0, materialsConfirmedAt: materialsConfirmedAt(dealId) };
}

/* ============================== Site check-in / check-out (125) */

const siteCheckIns: SiteCheckIn[] = seedSiteCheckIns.map((v) => ({ ...v }));
let siteCheckInCounter = 100;

/** The steps of this person's own that are not done on a job under way: what leaving now would leave open. */
function siteOpenStepsOf(job: Job, userId: string): SiteOpenStep[] {
  if (job.status !== 'in_progress') return [];
  const own = ownStepIds(job, userId);
  const defs = sopVersionOf(job).steps;
  return job.steps
    .filter((st) => st.status !== 'complete' && (own === null || own.includes(st.id)))
    .map((st) => ({ id: st.id, labelKey: st.labelKey, safetyCritical: !!defs.find((d) => d.id === st.id)?.safetyCritical, current: st.status === 'current' }));
}

function siteVisitViewOf(v: SiteCheckIn, now: number): SiteVisitView {
  return {
    id: v.id,
    userId: v.userId,
    name: v.userName,
    checkInAt: v.checkInAt,
    checkOutAt: v.checkOutAt ?? null,
    minutes: visitMinutes(v, now),
    verdict: v.checkInVerdict,
    driftM: v.checkInDriftM,
    accuracyM: v.checkInAccuracyM,
    reason: v.checkInReason ?? null,
    kind: v.checkOutKind ?? null,
    leave: v.checkOutAt && v.leaveReason ? { reason: v.leaveReason, note: v.leaveNote ?? null, openSteps: (v.openStepIds ?? []).length } : null,
    stale: isStale(v, now),
  };
}

/** How long completed installations have taken on site: what expectations for the next one can honestly be built on. */
function typicalInstallTime(): SiteTimeView['typical'] {
  const done = jobs.filter((j) => j.status === 'completed');
  const totals = done
    .map((j) => siteCheckIns.filter((v) => v.jobId === j.id))
    .filter((list) => list.length > 0)
    .map((list) => ({ minutes: list.reduce((sum, v) => sum + visitMinutes(v, Date.now()), 0), days: new Set(list.map((v) => dayKey(v.checkInAt))).size }));
  if (totals.length < MIN_TYPICAL_JOBS) return null;
  return { jobs: totals.length, medianMinutes: medianOf(totals.map((t) => t.minutes)) ?? 0, medianDays: medianOf(totals.map((t) => t.days)) ?? 0 };
}

function siteTimeViewOf(job: Job, userId: string, now: number): SiteTimeView {
  const viewer = byId(users, userId);
  const role = roleOf(job, userId);
  const all = siteCheckIns.filter((v) => v.jobId === job.id);
  const own = all.filter((v) => v.userId === userId);
  const open = own.find((v) => !v.checkOutAt);
  const elsewhere = siteCheckIns.find((v) => v.userId === userId && !v.checkOutAt && v.jobId !== job.id);
  const elsewhereJob = elsewhere ? byId(jobs, elsewhere.jobId) : null;
  const lead = resolveLead(byId(deals, job.dealId)?.leadId ?? '');
  const radiusM = radiusFor(lead?.id);
  const problem: SiteTimeView['problem'] = open ? 'already_checked_in' : elsewhere ? 'checked_in_elsewhere' : (jobVisitProblem(job, now) as SiteTimeView['problem']);
  const listed = viewer?.role === 'admin' ? all : own;
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, address: job.address, status: job.status, location: job.location, scheduledFor: job.scheduledFor, radiusM, largeSite: radiusM > 150 },
    role,
    mine: open ? siteVisitViewOf(open, now) : null,
    elsewhere: elsewhere && elsewhereJob ? { jobId: elsewhereJob.id, code: elsewhereJob.code, siteName: elsewhereJob.siteName } : null,
    problem,
    visits: [...listed].sort((a, b) => b.checkInAt.localeCompare(a.checkInAt)).map((v) => siteVisitViewOf(v, now)),
    team: peopleOn(job).map((id): SitePersonView => {
      const t = timeOf(all, id, now);
      return { userId: id, name: byId(users, id)?.name ?? '', role: roleOf(job, id) ?? 'assistant', onSiteNow: t.onSiteNow, since: t.since, minutes: t.minutes, days: t.days, lastLeftAt: t.lastLeftAt, unconfirmed: t.unconfirmed };
    }),
    days: daysOf(all, now).map((d) => ({ date: d.date, minutes: d.minutes, people: d.people.map((p) => ({ userId: p.userId, name: byId(users, p.userId)?.name ?? '', minutes: p.minutes })) })),
    totals: { minutes: all.reduce((sum, v) => sum + visitMinutes(v, now), 0), days: new Set(all.filter((v) => v.checkOutAt || !isStale(v, now)).map((v) => dayKey(v.checkInAt))).size, unconfirmed: all.filter((v) => isStale(v, now)).length },
    openSteps: siteOpenStepsOf(job, userId),
    typical: typicalInstallTime(),
  };
}

/** Whoever asks must be on the job (or Admin, who reads the whole job). */
function siteActor(jobId: string, userId: string, forWrite: boolean): { job: Job; user: User } {
  const user = byId(users, userId);
  const job = byId(jobs, jobId);
  if (!user) throw new RepositoryError('forbidden');
  if (!job) throw new RepositoryError('not_found');
  if (user.role === 'admin' && !forWrite) return { job, user };
  if (user.role !== 'technician' || !isOnJob(job, userId)) throw new RepositoryError('forbidden');
  return { job, user };
}

/** A time the phone says something happened is believable only if it is not in the future and reads as a date. */
function siteTimeOrThrow(at: string | undefined, now: number): string {
  if (!at) return new Date(now).toISOString();
  const t = new Date(at).getTime();
  if (Number.isNaN(t)) throw new RepositoryError('captured_invalid');
  if (t > now + 60_000) throw new RepositoryError('captured_in_future');
  return new Date(t).toISOString();
}

/* ============================== Safety compliance checklist (126) */

const jobSafetyTests: JobSafetyTest[] = seedJobSafetyTests.map((t) => ({ ...t, attempts: t.attempts.map((a) => ({ ...a })), holds: t.holds.map((h) => ({ ...h })) }));
const safetyStateItems: SafetyStateItem[] = seedSafetyStateItems.map((i) => ({ ...i }));
const preInspectionSummaries: PreInspectionSummary[] = [];
let safetyCounter = 100;

const SAFETY_REVIEW_WINDOW = hours(24);
/** A job's state, the way the contract (075) finds it. */
const jobStateOf = (job: Job): string | null => {
  const lead = resolveLead(byId(deals, job.dealId)?.leadId ?? '');
  return lead ? deriveStateFromCity(lead.city) : null;
};

interface SafetyEntry {
  id: string;
  kind: 'device' | 'trial' | 'state';
  def: (typeof SAFETY_ITEMS)[number] | null;
  stateItem: SafetyStateItem | null;
}

/** The checks that apply to this job: the standard ones for its configuration, and the state's own that Admin has added. A state item
 *  added after a job reached quality check is not asked of it retroactively. */
function safetyEntriesOf(job: Job): SafetyEntry[] {
  const standard = safetyItemsForSpec(sopSpecOf(job)).map<SafetyEntry>((d) => ({ id: d.id, kind: d.kind, def: d, stateItem: null }));
  const state = jobStateOf(job);
  const beforeQc = job.status === 'scheduled' || job.status === 'materials_pending' || job.status === 'in_progress';
  const own = safetyStateItems
    .filter((i) => state !== null && i.state === state && (i.active ? beforeQc || jobSafetyTests.some((t) => t.jobId === job.id && t.itemId === i.id) : jobSafetyTests.some((t) => t.jobId === job.id && t.itemId === i.id)))
    .map<SafetyEntry>((i) => ({ id: i.id, kind: 'state', def: null, stateItem: i }));
  return [...standard, ...own];
}

const safetyTestOf = (jobId: string, itemId: string) => jobSafetyTests.find((t) => t.jobId === jobId && t.itemId === itemId);

/** Everything on the checklist that is not yet passed or accepted: what stops the job reaching quality check. */
function safetyBlocking(job: Job): string[] {
  const entries = safetyEntriesOf(job);
  return safetyReadiness(entries.map((e) => e.id), jobSafetyTests.filter((t) => t.jobId === job.id)).open;
}

function safetyItemViewOf(job: Job, entry: SafetyEntry, userId: string, all: SafetyEntry[]): SafetyItemView {
  const t = safetyTestOf(job.id, entry.id);
  const state = safetyState(t);
  const version = sopVersionOf(job);
  const slots = (entry.def?.slots ?? []).flatMap((slotId) => {
    const step = job.steps.find((x) => x.id === slotId.split('.')[0]);
    const def = version.steps.flatMap((d) => d.slots).find((sl) => sl.id === slotId);
    if (!step || !def) return [];
    return [{ id: slotId, labelKey: def.labelKey, kind: def.kind, stepId: step.id, proof: activeProofOf(step, slotId), excepted: !!exceptionOf(step, slotId) }];
  });
  const missing = slots.filter((sl) => !sl.proof && !sl.excepted).map((sl) => sl.id);
  const unmet = (entry.def?.dependsOn ?? []).filter((id) => all.some((e) => e.id === id) && !isCleared(safetyState(safetyTestOf(job.id, id))));
  const own = ownStepIds(job, userId);
  const isAdmin = byId(users, userId)?.role === 'admin';
  const mine = !isAdmin && isOnJob(job, userId) && (own === null || (entry.def ? own.includes(entry.def.stepId) : false) || (entry.kind === 'state' && own === null));
  const requiresReading = !!entry.stateItem?.requiresReading;
  const problem = resultProblem(t, 'pass', {}, { missingSlots: missing, unmetDeps: unmet, requiresReading });
  return {
    id: entry.id,
    kind: entry.kind,
    label: entry.stateItem?.label ?? null,
    method: entry.stateItem?.method ?? null,
    stepId: entry.def?.stepId ?? null,
    state: state as SafetyItemState,
    attempts: (t?.attempts ?? []).map((a) => ({ ...a })),
    fails: failCount(t),
    slots,
    missingSlotIds: missing,
    waitingFor: unmet,
    requiresReading,
    hold: t?.holds.find((h) => !h.releasedAt) ?? null,
    disagreement: t?.disagreement ?? null,
    override: t?.override ?? null,
    canRecord: mine && job.status === 'in_progress',
    passProblem: problem === 'evidence_missing' || problem === 'depends_on' || problem === 'reading_required' ? problem : null,
  };
}

function safetyViewOf(job: Job, userId: string): SafetyChecklistView {
  const entries = safetyEntriesOf(job);
  const items = entries.map((e) => safetyItemViewOf(job, e, userId, entries));
  const cleared = items.filter((i) => isCleared(i.state)).length;
  const state = jobStateOf(job);
  const configured = state ? safetyStateItems.filter((i) => i.active && i.state === state).length : 0;
  const user = byId(users, userId);
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, status: job.status, role: roleOf(job, userId) },
    items,
    progress: { cleared, total: items.length },
    blocksQc: cleared < items.length,
    state: { name: state, fallback: configured === 0, configured },
    summaries: preInspectionSummaries.filter((x) => x.jobId === job.id).sort((a, b) => b.version - a.version).map((x) => ({ id: x.id, version: x.version, generatedAt: x.generatedAt, generatedByName: x.generatedByName, ready: x.ready })),
    isAdmin: user?.role === 'admin',
    readOnly: job.status !== 'in_progress',
  };
}

/** Whoever asks must be on the job, or Admin. Admin reads everything and never records a technician's test. */
function safetyActor(jobId: string, userId: string, mode: 'read' | 'technician' | 'admin'): { job: Job; user: User } {
  const user = byId(users, userId);
  const job = byId(jobs, jobId);
  if (!user) throw new RepositoryError('forbidden');
  if (!job) throw new RepositoryError('not_found');
  if (mode === 'admin') {
    if (user.role !== 'admin') throw new RepositoryError('forbidden');
    return { job, user };
  }
  if (user.role === 'admin' && mode === 'read') return { job, user };
  if (user.role !== 'technician' || !isOnJob(job, userId)) throw new RepositoryError('forbidden');
  return { job, user };
}

/** A check waiting on Admin (a fundamental fault, repeated failures) or a technician's disagreement is Admin's to review: one alert each,
 *  raised once and cleared by the same rule when it is released or decided. */
function syncSafetyAlerts(automated: boolean, now: number): void {
  const at = new Date(now).toISOString();
  const live = new Set<string>();
  for (const t of jobSafetyTests) {
    const job = byId(jobs, t.jobId);
    if (!job) continue;
    const hold = t.holds.find((h) => !h.releasedAt);
    const dis = t.disagreement && !t.disagreement.resolution ? t.disagreement : undefined;
    const label = t.itemId;
    const specs: { key: string; titleKey: string; severity: 'high' | 'critical'; on: boolean; context: string }[] = [
      { key: `safety:${t.id}:hold`, titleKey: hold?.reason === 'too_many_fails' ? 'safetyChecklist.alert.repeatedFailure' : 'safetyChecklist.alert.rework', severity: hold?.reason === 'too_many_fails' ? 'critical' : 'high', on: !!hold, context: `${job.code} · ${job.siteName} · ${label}` },
      { key: `safety:${t.id}:review`, titleKey: 'safetyChecklist.alert.disagreement', severity: 'high', on: !!dis, context: `${job.code} · ${job.siteName} · ${label}: ${dis?.note ?? ''}` },
    ];
    for (const sp of specs) {
      if (!sp.on) continue;
      live.add(sp.key);
      if (alerts.some((a) => a.relatedId === sp.key && a.status !== 'resolved')) continue;
      raiseAlert({ titleKey: sp.titleKey, context: sp.context, severity: sp.severity, category: 'safety', relatedId: sp.key, sourceRoute: `/safety-checklist/${job.id}` });
      if (automated) {
        logAutomatedAction({ sourceKey: 'safety.review_raised', triggeringCondition: `A safety check on ${job.code} is waiting for Admin`, actionTaken: 'Raised an alert so it is reviewed', affectedRecordId: t.id, affectedRecordType: 'other', subjectLabel: job.code });
      }
    }
  }
  for (const a of alerts) {
    if (a.relatedId?.startsWith('safety:') && a.status !== 'resolved' && !live.has(a.relatedId)) patchInPlace(alerts, a.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'Reviewed.' });
  }
}

function safetyTestFor(job: Job, itemId: string): JobSafetyTest {
  const existing = safetyTestOf(job.id, itemId);
  if (existing) return existing;
  safetyCounter += 1;
  const created: JobSafetyTest = { id: `jst-new-${safetyCounter}`, jobId: job.id, itemId, attempts: [], holds: [], isDemo: true };
  jobSafetyTests.push(created);
  return created;
}

function safetyEntryOrThrow(job: Job, itemId: string): SafetyEntry {
  const entry = safetyEntriesOf(job).find((e) => e.id === itemId);
  if (!entry) throw new RepositoryError('not_found');
  return entry;
}

/** The readiness summary as it would read now, or as a stored one read when it was made. */
function preInspectionViewOf(job: Job, stored?: PreInspectionSummary): PreInspectionSummaryView {
  const lead = resolveLead(byId(deals, job.dealId)?.leadId ?? '');
  if (stored) {
    return {
      id: stored.id,
      job: { code: job.code, siteName: job.siteName, address: `${job.address}${lead ? `, ${lead.city}` : ''}` },
      version: stored.version,
      generatedAt: stored.generatedAt,
      generatedByName: stored.generatedByName,
      ready: stored.ready,
      state: stored.state,
      stateFallback: stored.stateFallback,
      lines: stored.lines.map((l) => ({ ...l, state: l.state as SafetyItemState })),
    };
  }
  const entries = safetyEntriesOf(job);
  const state = jobStateOf(job);
  const lines = entries.map((e) => {
    const t = safetyTestOf(job.id, e.id);
    return { itemId: e.id, label: e.stateItem?.label ?? null, labelKey: e.def ? `safetyChecklist.item.${e.id}.label` : null, state: safetyState(t) as SafetyItemState, attempts: t?.attempts.length ?? 0, fixes: (t?.attempts ?? []).filter((a) => a.fix).length, lastResult: t?.attempts.length ? t.attempts[t.attempts.length - 1].result : null, overriddenBy: t?.override ? `${t.override.engineerName} (${t.override.byName})` : null };
  });
  const configured = state ? safetyStateItems.filter((i) => i.active && i.state === state).length : 0;
  return {
    id: null,
    job: { code: job.code, siteName: job.siteName, address: `${job.address}${lead ? `, ${lead.city}` : ''}` },
    version: null,
    generatedAt: null,
    generatedByName: null,
    ready: lines.every((l) => l.state === 'passed' || l.state === 'overridden'),
    state,
    stateFallback: configured === 0,
    lines,
  };
}

/* ============================== Issue / blocker reports (127) */

const jobIssues: JobIssue[] = seedJobIssues.map((i) => ({ ...i, evidence: i.evidence.map((e) => ({ ...e })), events: i.events.map((e) => ({ ...e })) }));
const issuePatternReviews: IssuePatternReview[] = [];
let issueCounter = 100;
/** `heldBy` on a job that a report paused, so nothing else's hold (a payments hold, 089) is ever released by a report being closed. */
const ISSUE_HOLD = 'issue-report';

const issueEvent = (kind: JobIssueEvent['kind'], by: { id: string; name: string; role: JobIssueEvent['byRole'] }, note?: string, extra: Partial<JobIssueEvent> = {}): JobIssueEvent => {
  issueCounter += 1;
  return { id: `ise-new-${issueCounter}`, kind, at: new Date().toISOString(), byUserId: by.id, byName: by.name, byRole: by.role, ...(note ? { note } : {}), ...extra };
};
const actorOf = (u: User) => ({ id: u.id, name: u.name, role: (u.role === 'admin' ? 'admin' : 'technician') as 'admin' | 'technician' });

/** A job is on hold for as long as one of its reports pauses the work, and goes back to where it was when the last one is closed. A hold
 *  someone else put on it (payments, 089) is never touched; a report that is still open after that hold lifts re-applies the pause. */
function syncIssueHold(job: Job, reason?: string): Job {
  const pausing = jobIssues.filter((i) => i.jobId === job.id && i.status === 'open' && pausesWork(i.severity));
  if (pausing.length > 0) {
    if (job.status === 'on_hold' || job.status === 'completed' || job.status === 'handover_pending') return job;
    const first = [...pausing].sort((a, b) => a.createdAt.localeCompare(b.createdAt))[0];
    return patchInPlace(jobs, job.id, { status: 'on_hold' as const, resumeStatus: job.status, holdReason: reason ?? `${first.code}: ${first.description}`, heldBy: ISSUE_HOLD, heldAt: new Date().toISOString() });
  }
  if (job.status === 'on_hold' && job.heldBy === ISSUE_HOLD) {
    return patchInPlace(jobs, job.id, { status: job.resumeStatus ?? ('in_progress' as const), resumeStatus: undefined, holdReason: undefined, heldBy: undefined, heldAt: undefined });
  }
  return job;
}

function issueViewOf(i: JobIssue, userId: string, now: number): JobIssueView {
  const job = byId(jobs, i.jobId);
  const user = byId(users, userId);
  const role = user?.role === 'admin' ? 'admin' : 'technician';
  const step = job?.steps.find((x) => x.id === i.stepId);
  return {
    id: i.id,
    code: i.code,
    jobId: i.jobId,
    jobCode: job?.code ?? '',
    siteName: job?.siteName ?? '',
    category: i.category,
    severity: i.severity,
    description: i.description,
    stepId: i.stepId ?? null,
    stepLabelKey: step?.labelKey ?? null,
    sopGap: i.sopGap,
    evidence: i.evidence,
    status: i.status,
    groupId: i.groupId,
    groupSize: jobIssues.filter((x) => x.groupId === i.groupId).length,
    reportedByUserId: i.reportedByUserId,
    reportedByName: i.reportedByName,
    createdAt: i.createdAt,
    resolution: i.resolution ?? null,
    events: i.events,
    mine: i.reportedByUserId === userId,
    canResolve: i.status === 'open' && canResolve(i, role, userId),
    canReopen: canReopen(i, role, now) && (role === 'admin' || i.reportedByUserId === userId),
  };
}

function jobIssuesViewOf(job: Job, userId: string, now: number): JobIssuesView {
  const list = jobIssues.filter((i) => i.jobId === job.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  const open = list.filter((i) => i.status === 'open' && pausesWork(i.severity));
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, status: job.status, role: roleOf(job, userId) },
    issues: list.map((i) => issueViewOf(i, userId, now)),
    steps: job.steps.map((x) => ({ id: x.id, labelKey: x.labelKey })),
    adminPhone: users.find((u) => u.role === 'admin')?.phone ?? null,
    blocked: { ms: blockedMs(list, now), open: open.length, since: open.length ? open.map((i) => i.createdAt).sort()[0] : null },
    paused: job.status === 'on_hold' && job.heldBy === ISSUE_HOLD,
    canReport: job.status !== 'completed' && job.status !== 'handover_pending',
  };
}

/** Whoever asks must be on the job (or Admin, who sees every job). */
function issueActor(jobId: string, userId: string, forWrite: boolean): { job: Job; user: User } {
  const user = byId(users, userId);
  const job = byId(jobs, jobId);
  if (!user) throw new RepositoryError('forbidden');
  if (!job) throw new RepositoryError('not_found');
  if (user.role === 'admin') return { job, user };
  if (user.role !== 'technician' || !isOnJob(job, userId)) throw new RepositoryError('forbidden');
  void forWrite;
  return { job, user };
}

function issueOrThrow(id: string): JobIssue {
  const found = byId(jobIssues, id);
  if (!found) throw new RepositoryError('not_found');
  return found;
}

/** One alert while a report pauses work (safety is critical, in the same escalation path as an SOS), cleared when it is closed; and
 *  one when a step keeps being reported as a problem with the procedure. */
function syncIssueAlerts(automated: boolean, now: number): void {
  const at = new Date(now).toISOString();
  const live = new Set<string>();
  for (const i of jobIssues) {
    if (i.status !== 'open' || !pausesWork(i.severity)) continue;
    const job = byId(jobs, i.jobId);
    if (!job) continue;
    const key = `issue:${i.id}`;
    live.add(key);
    const titleKey = i.severity === 'safety' ? 'issueReport.alert.safety' : 'issueReport.alert.blocking';
    const existing = alerts.find((a) => a.relatedId === key && a.status !== 'resolved');
    if (existing && existing.titleKey === titleKey) continue;
    if (existing) patchInPlace(alerts, existing.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'Severity changed.' });
    raiseAlert({ titleKey, context: `${job.code} · ${job.siteName} · ${i.reportedByName}: ${i.description}`, severity: i.severity === 'safety' ? 'critical' : 'high', category: i.severity === 'safety' ? 'safety' : i.category === 'parts' ? 'supplier' : 'quality', relatedId: key, sourceRoute: `/job-issues/${job.id}?issue=${i.id}`, location: job.location });
  }
  for (const p of patternsOf(jobIssues, issuePatternReviews, now)) {
    const key = `issuepattern:${p.stepId}`;
    if (!p.needsReview) continue;
    live.add(key);
    if (alerts.some((a) => a.relatedId === key && a.status !== 'resolved')) continue;
    raiseAlert({ titleKey: 'issueReport.alert.pattern', context: `${p.stepId} · ${p.reports} reports on ${p.jobs} jobs`, severity: 'medium', category: 'quality', relatedId: key, sourceRoute: '/job-issues?tab=patterns' });
    if (automated) logAutomatedAction({ sourceKey: 'issues.pattern', triggeringCondition: `Step ${p.stepId} has been reported as a problem with the procedure ${p.reports} times on ${p.jobs} jobs`, actionTaken: 'Raised an alert so the procedure is reviewed', affectedRecordId: p.stepId, affectedRecordType: 'other', subjectLabel: p.stepId });
  }
  for (const a of alerts) {
    if ((a.relatedId?.startsWith('issue:') || a.relatedId?.startsWith('issuepattern:')) && a.status !== 'resolved' && !live.has(a.relatedId)) patchInPlace(alerts, a.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'Closed.' });
  }
}

/* ============================== As-installed material log (128) */

const materialLogs: JobMaterialLog[] = [];
let materialSeeded = false;
let materialUseCounter = 0;
/** Which supplier's parts keep being replaced: this many supplier-fault deviations on this many jobs in this many days is a pattern. */
const MATERIAL_PATTERN = { deviations: 3, jobs: 2, days: 90 };

/** The plan a job is logged against: the deal's order lines. Only the prices are kept from a technician. */
function materialPlanOf(job: Job, withPrices: boolean): MaterialPlanLine[] {
  const pos = supplierPurchaseOrders.filter((po) => po.dealId === job.dealId && po.status === 'sent' && (po.lineItems ?? []).length > 0);
  const view = jobMaterialsOf(job.dealId);
  return view.lines.map((l) => {
    const po = pos.find((p) => p.code === l.poCode);
    const line = po?.lineItems?.find((x) => x.id === l.id);
    return { id: l.id, poCode: l.poCode, supplierId: po?.supplierId ?? null, supplierName: po?.supplierId ? (byId(suppliers, po.supplierId)?.name ?? null) : null, category: l.category, description: l.description, quantity: l.quantity, state: l.state, unitPrice: withPrices ? (line?.agreedUnitPrice ?? 0) : null };
  });
}

/** A few finished jobs come with their record, so the board and the warranty feed are not empty on a fresh start. Built from the deal's own lines. */
function ensureMaterialSeeds(): void {
  if (materialSeeded) return;
  materialSeeded = true;
  const at = (daysBack: number) => new Date(Date.now() - daysBack * 86_400_000).toISOString();
  const rowFor = (job: Job, l: MaterialPlanLine, over: Partial<JobMaterialUse> = {}): JobMaterialUse => {
    materialUseCounter += 1;
    const traced = identifierKind(l.category);
    return {
      id: `mu-seed-${materialUseCounter}`,
      source: 'delivered',
      lineItemId: l.id,
      poCode: l.poCode,
      ...(l.supplierId ? { supplierId: l.supplierId } : {}),
      category: l.category,
      description: l.description,
      plannedQty: l.quantity,
      usedQty: l.quantity,
      leftoverQty: 0,
      identifiers: traced === 'none' ? [] : Array.from({ length: traced === 'batch' ? 1 : l.quantity }, (_, n) => (traced === 'batch' ? { batch: `B-${job.code.slice(-4)}-${n + 1}`, legible: true } : { serial: `SN-${job.code.slice(-4)}-${l.id.slice(-2).toUpperCase()}${n + 1}`, legible: true })),
      ...(l.state !== 'on_site' ? { deliveryUnconfirmed: true } : {}),
      ...over,
    };
  };
  const make = (jobId: string, status: 'draft' | 'confirmed', ago: number, build: (job: Job, plan: MaterialPlanLine[]) => JobMaterialUse[]) => {
    const job = byId(jobs, jobId);
    if (!job) return;
    const plan = materialPlanOf(job, false);
    if (plan.length === 0) return;
    const by = byId(users, job.technicianId ?? '')?.name ?? 'Technician';
    materialLogs.push({ jobId, uses: build(job, plan), status, savedAt: at(ago), savedByName: by, ...(status === 'confirmed' ? { confirmedAt: at(ago), confirmedByName: by } : {}), reopened: [], isDemo: true });
  };
  make('j-7', 'confirmed', 5, (job, plan) => plan.map((l) => rowFor(job, l)));
  make('j-2', 'confirmed', 3, (job, plan) =>
    plan.map((l) => {
      if (l.category === 'door_operator') return rowFor(job, l, { usedQty: 0, leftoverQty: 1, leftoverAction: 'return_to_supplier', identifiers: [], deviation: { kind: 'defective_replaced', reason: 'Motor seized on first power-up; returned to the supplier.' } });
      if (l.category === 'controller') return rowFor(job, l, { usedQty: 0, leftoverQty: 1, leftoverAction: 'return_to_pool', identifiers: [], deviation: { kind: 'wrong_part_supplied', reason: 'Wrong phase rating for this drive; kept aside for a compatible job.' } });
      if (l.category === 'ropes') return rowFor(job, l, { identifiers: [{ legible: false, note: 'Tag rubbed off on the reel.' }] });
      return rowFor(job, l);
    }),
  );
  make('j-5', 'confirmed', 40, (job, plan) => plan.map((l) => (l.category === 'door_operator' ? rowFor(job, l, { usedQty: 0, leftoverQty: 1, leftoverAction: 'scrap', identifiers: [], deviation: { kind: 'defective_replaced', reason: 'Limit switch failed bench test; replaced from the supplier’s spare.' } }) : rowFor(job, l))));
  // What replaced a part that was not used was bought locally the same day, so the lift still has one of everything.
  const bought = (jobId: string, category: string) => {
    const log = materialLogs.find((x) => x.jobId === jobId);
    const replaced = log?.uses.find((u) => u.category === category && u.lineItemId && u.usedQty === 0);
    if (!log || !replaced?.lineItemId) return;
    materialUseCounter += 1;
    log.uses.push({ id: `mu-seed-${materialUseCounter}`, source: 'local_purchase', category, description: `${replaced.description} (local purchase)`, plannedQty: 0, usedQty: 1, leftoverQty: 0, deviation: { kind: 'substitute', reason: 'Bought locally the same day so the job was not held up.', replacesLineItemId: replaced.lineItemId }, identifiers: [{ serial: `LP-${jobId.toUpperCase()}-${category.slice(0, 3).toUpperCase()}`, legible: true }], unitCost: category === 'controller' ? 42_000 : 18_500 });
  };
  bought('j-2', 'door_operator');
  bought('j-2', 'controller');
  bought('j-5', 'door_operator');
  // j-1 is under way: a part of it written down, not yet confirmed.
  make('j-1', 'draft', 0.2, (job, plan) => plan.filter((l) => l.category === 'traction_machine').map((l) => rowFor(job, l)));
}

function materialActor(jobId: string, userId: string): { job: Job; user: User; role: 'lead' | 'assistant' | null } {
  ensureMaterialSeeds();
  const user = byId(users, userId);
  const job = byId(jobs, jobId);
  if (!user) throw new RepositoryError('forbidden');
  if (!job) throw new RepositoryError('not_found');
  if (user.role === 'admin') return { job, user, role: null };
  if (user.role !== 'technician' || !isOnJob(job, userId)) throw new RepositoryError('forbidden');
  return { job, user, role: roleOf(job, userId) };
}

const materialStarted = (job: Job) => job.status === 'in_progress' || job.status === 'qc_pending' || job.status === 'handover_pending' || job.status === 'completed' || (job.status === 'on_hold' && !!job.startedAt);

/** Leftovers other jobs marked as reusable, nearest first: what could be used here instead of ordering again. */
function materialPoolOf(forJob: Job | null): MaterialPoolItem[] {
  const out: MaterialPoolItem[] = [];
  for (const log of materialLogs) {
    if (log.status !== 'confirmed' || (forJob && log.jobId === forJob.id)) continue;
    const from = byId(jobs, log.jobId);
    if (!from) continue;
    for (const u of log.uses) {
      if (u.leftoverAction !== 'return_to_pool' || u.leftoverQty <= 0) continue;
      out.push({ jobId: from.id, jobCode: from.code, siteName: from.siteName, category: u.category, description: u.description, quantity: u.leftoverQty, distanceKm: forJob ? Math.round(haversineKm(forJob.location, from.location) * 10) / 10 : null, at: log.confirmedAt ?? log.savedAt });
    }
  }
  return out.sort((a, b) => (a.distanceKm ?? 0) - (b.distanceKm ?? 0) || b.at.localeCompare(a.at));
}

function materialLogViewOf(job: Job, userId: string): MaterialLogView {
  const user = byId(users, userId);
  const isAdmin = user?.role === 'admin';
  const role = isAdmin ? null : roleOf(job, userId);
  const log = materialLogs.find((l) => l.jobId === job.id);
  const planned = materialPlanOf(job, !!isAdmin);
  const status: MaterialLogView['status'] = log ? log.status : 'none';
  const lockedReason: MaterialLogView['lockedReason'] = isAdmin ? 'admin' : role !== 'lead' ? 'assistant' : status === 'confirmed' ? 'confirmed' : !materialStarted(job) ? 'not_started' : null;
  const priceOf = (id: string) => planned.find((p) => p.id === id)?.unitPrice ?? 0;
  const uses = log?.uses ?? [];
  const plannedCost = planned.reduce((sum, p) => sum + p.quantity * (p.unitPrice ?? 0), 0);
  const leftover = leftoverValue(uses, priceOf);
  const extras = extrasCost(uses);
  const usedPlanned = uses.filter((u) => u.lineItemId).reduce((sum, u) => sum + u.usedQty * priceOf(u.lineItemId as string), 0);
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, status: job.status, role },
    planned,
    uses: uses.map((u) => ({ ...u, identifiers: u.identifiers.map((i) => ({ ...i })), ...(u.deviation ? { deviation: { ...u.deviation } } : {}) })),
    status,
    savedAt: log?.savedAt ?? null,
    savedByName: log?.savedByName ?? null,
    confirmedAt: log?.confirmedAt ?? null,
    confirmedByName: log?.confirmedByName ?? null,
    reopened: (log?.reopened ?? []).map((r) => ({ ...r })),
    canEdit: lockedReason === null,
    lockedReason,
    canReopen: !!isAdmin && status === 'confirmed',
    pool: isAdmin ? materialPoolOf(job) : materialPoolOf(job),
    costs: isAdmin ? { planned: plannedCost, asInstalled: usedPlanned + extras, leftoverValue: leftover, extras } : null,
  };
}

/** Supplier-fault deviations on confirmed logs within the window, per supplier: the input to that supplier's quality picture. */
function materialPatternsOf(now: number): MaterialSupplierPattern[] {
  const since = now - MATERIAL_PATTERN.days * 86_400_000;
  const by = new Map<string, { deviations: number; jobs: Set<string>; lastAt: string; kinds: Map<MaterialDeviationKind, number> }>();
  for (const log of materialLogs) {
    if (log.status !== 'confirmed') continue;
    const when = log.confirmedAt ?? log.savedAt;
    if (new Date(when).getTime() < since) continue;
    for (const u of log.uses) {
      if (!u.lineItemId || !u.supplierId || !u.deviation || !isSupplierFault(u.deviation.kind)) continue;
      const cur = by.get(u.supplierId) ?? { deviations: 0, jobs: new Set<string>(), lastAt: when, kinds: new Map<MaterialDeviationKind, number>() };
      cur.deviations += 1;
      cur.jobs.add(log.jobId);
      if (when > cur.lastAt) cur.lastAt = when;
      cur.kinds.set(u.deviation.kind, (cur.kinds.get(u.deviation.kind) ?? 0) + 1);
      by.set(u.supplierId, cur);
    }
  }
  return [...by.entries()]
    .map(([supplierId, v]): MaterialSupplierPattern => ({ supplierId, supplierName: byId(suppliers, supplierId)?.name ?? supplierId, deviations: v.deviations, jobs: v.jobs.size, lastAt: v.lastAt, kinds: [...v.kinds.entries()].map(([kind, count]) => ({ kind, count })), needsReview: v.deviations >= MATERIAL_PATTERN.deviations && v.jobs.size >= MATERIAL_PATTERN.jobs }))
    .sort((a, b) => b.deviations - a.deviations);
}

/** One alert per supplier whose parts keep being replaced, pointing at that supplier's scorecard; it clears itself when the pattern ages out. */
function syncMaterialDeviations(automated: boolean, now: number): void {
  ensureMaterialSeeds();
  const at = new Date(now).toISOString();
  const live = new Set<string>();
  for (const p of materialPatternsOf(now)) {
    if (!p.needsReview) continue;
    const key = `matdev:${p.supplierId}`;
    live.add(key);
    if (alerts.some((a) => a.relatedId === key && a.status !== 'resolved')) continue;
    raiseAlert({ titleKey: 'materialLog.alert.pattern', context: `${p.supplierName}: ${p.deviations} parts replaced on ${p.jobs} jobs in ${MATERIAL_PATTERN.days} days`, severity: 'medium', category: 'supplier', relatedId: key, sourceRoute: `/scorecard?supplierId=${p.supplierId}` });
    if (automated) logAutomatedAction({ sourceKey: 'materials.supplier_pattern', triggeringCondition: `${p.supplierName}'s parts were replaced ${p.deviations} times across ${p.jobs} jobs`, actionTaken: 'Raised an alert pointing at the supplier’s scorecard', affectedRecordId: p.supplierId, affectedRecordType: 'other', subjectLabel: p.supplierName });
  }
  for (const a of alerts) if (a.relatedId?.startsWith('matdev:') && a.status !== 'resolved' && !live.has(a.relatedId)) patchInPlace(alerts, a.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'No longer a pattern.' });
}

/* ============================== Installation progress timeline (129) */

interface TimelineCore {
  steps: { def: InstallSopStepDef; step: JobStep }[];
  stepsDone: number;
  stepsTotal: number;
  current: InstallSopPhase | null;
  estimate: Estimate;
  planned: PlannedDuration;
  stoppedNow: boolean;
  blocked: number;
  openStops: JobIssue[];
}

/** Who may follow this job's timeline, and in which words: a customer only for a deal of their own. */
function timelineActor(jobId: string, userId: string): { job: Job; user: User; audience: TimelineAudience } {
  const user = byId(users, userId);
  const job = byId(jobs, jobId);
  if (!user) throw new RepositoryError('forbidden');
  if (!job) throw new RepositoryError('not_found');
  if (user.role === 'admin') return { job, user, audience: 'staff' };
  if (user.role === 'technician') {
    if (!isOnJob(job, userId)) throw new RepositoryError('forbidden');
    return { job, user, audience: 'staff' };
  }
  if (user.role === 'customer') {
    if (byId(deals, job.dealId)?.customerId !== user.id) throw new RepositoryError('forbidden');
    return { job, user, audience: 'customer' };
  }
  throw new RepositoryError('forbidden');
}

/** The one reading of how far a job is and when it will be done, shared by the timeline and the list, so they can never disagree. */
function timelineCoreOf(job: Job, now: number): TimelineCore {
  const spec = sopSpecOf(job);
  const steps = sopVersionOf(job).steps.flatMap((def) => {
    const step = job.steps.find((x) => x.id === def.id);
    return step && stepApplies(def, spec) ? [{ def, step }] : [];
  });
  const stepsDone = steps.filter((x) => isDone(x.step)).length;
  const own = jobIssues.filter((i) => i.jobId === job.id);
  const openStops = own.filter((i) => i.status === 'open' && pausesWork(i.severity));
  const stoppedNow = openStops.length > 0 || job.status === 'on_hold';
  const blocked = blockedMs(own, now);
  const finished = jobs.filter((j) => j.status === 'completed' && j.id !== job.id);
  const planned = plannedDuration(finished);
  // A report that has just stopped the work is expected to take its resolve target to clear: the date moves the moment it is logged, and
  // only moves further (day by day) once that time has passed with it still open.
  const stopAllowanceMs = openStops.reduce((max, i) => Math.max(max, RESOLVE_TARGET[i.severity as 'blocking' | 'safety'] - (now - new Date(i.createdAt).getTime())), 0);
  const estimate = estimateOf({ now, scheduledFor: job.scheduledFor, startedAt: job.startedAt, completedAt: job.completedAt, stepsTotal: steps.length, stepsDone, plannedMs: planned.ms, blockedMs: blocked, stoppedNow, stopAllowanceMs });
  const firstOpen = steps.find((x) => !isDone(x.step));
  const currentStep = steps.find((x) => x.step.status === 'current') ?? firstOpen;
  return { steps, stepsDone, stepsTotal: steps.length, current: currentStep ? currentStep.def.phase : null, estimate, planned, stoppedNow, blocked, openStops };
}

function timelineViewOf(job: Job, user: User, audience: TimelineAudience, now: number): InstallTimelineView {
  const core = timelineCoreOf(job, now);
  const staff = audience === 'staff';
  const own = jobIssues.filter((i) => i.jobId === job.id);
  const hidden = audience === 'customer' && !!job.customerTimelineHidden;
  const iso = (ms: number) => new Date(ms).toISOString();
  const start = job.startedAt ? new Date(job.startedAt).getTime() : new Date(job.scheduledFor).getTime();
  const totalSteps = Math.max(1, core.stepsTotal);
  const remainingAll = core.steps.filter((x) => !isDone(x.step)).length;

  let throughDone = 0;
  let throughRemaining = 0;
  const milestones: TimelineMilestone[] = PHASES.flatMap((phase) => {
    const inPhase = core.steps.filter((x) => x.def.phase === phase);
    if (inPhase.length === 0) return [];
    const done = inPhase.filter((x) => isDone(x.step));
    throughDone += inPhase.length;
    throughRemaining += inPhase.length - done.length;
    const allDone = done.length === inPhase.length;
    const doneAt = allDone ? (inPhase.map((x) => x.step.completedAt).filter((x): x is string => !!x).sort().pop() ?? null) : null;
    const originalAt = start + core.planned.ms * (throughDone / totalSteps);
    const expectedMs = allDone ? null : stageExpectedAt(now, core.estimate.currentAt, throughRemaining, remainingAll);
    const compareTo = doneAt ? new Date(doneAt).getTime() : (expectedMs ?? originalAt);
    const slipDays = Math.round((compareTo - originalAt) / 86_400_000);
    const stops = core.openStops.filter((i) => (i.stepId ? inPhase.some((x) => x.def.id === i.stepId) : phase === core.current));
    return [
      {
        phase,
        status: allDone ? ('done' as const) : phase === core.current ? ('current' as const) : ('upcoming' as const),
        blocked: !allDone && stops.length > 0,
        stepsDone: done.length,
        stepsTotal: inPhase.length,
        evidenceCount: inPhase.reduce((sum, x) => sum + x.step.evidenceCount, 0),
        doneAt,
        expectedAt: expectedMs === null ? null : iso(expectedMs),
        originalAt: iso(originalAt),
        slipDays,
        steps: staff ? inPhase.map((x): TimelineStepView => ({ id: x.step.id, labelKey: x.step.labelKey, status: x.step.status, completedAt: x.step.completedAt ?? null, completedByName: x.step.completedByName ?? null, evidenceCount: x.step.evidenceCount, safetyCritical: x.def.safetyCritical, notApplicable: !!x.step.notApplicable })) : [],
        issues: staff ? own.filter((i) => (i.stepId ? inPhase.some((x) => x.def.id === i.stepId) : false)).map((i): TimelineIssueView => ({ id: i.id, code: i.code, category: i.category, severity: i.severity, status: i.status, createdAt: i.createdAt, resolvedAt: i.resolution?.at ?? null })) : [],
      },
    ];
  });

  // What made it later, in the words of a cause, never the report itself.
  const reasons: InstallTimelineView['reasons'] = [];
  const push = (code: TimelineDelayReason, open: boolean) => {
    const existing = reasons.find((r) => r.code === code);
    if (existing) existing.open = existing.open || open;
    else reasons.push({ code, open });
  };
  for (const i of own) if (pausesWork(i.severity)) push(REASON_OF[i.category], i.status === 'open');
  if (job.status === 'materials_pending' && new Date(job.scheduledFor).getTime() <= now) push('materials_pending', true);
  if (job.status === 'on_hold' && core.openStops.length === 0) push('hold', true);
  if (core.estimate.slipped && core.estimate.pace > 1.15 && !job.completedAt) push('pace', true);

  const stamps = [job.startedAt, ...job.steps.map((x) => x.completedAt), ...job.steps.flatMap((x) => (x.evidence ?? []).map((e) => e.capturedAt)), ...own.map((i) => i.createdAt), ...own.map((i) => i.resolution?.at)].filter((x): x is string => !!x).map((x) => new Date(x).getTime());
  const lastAt = stamps.length ? Math.max(...stamps) : null;
  const lastDone = core.steps.filter((x) => x.step.completedAt).sort((a, b) => (b.step.completedAt ?? '').localeCompare(a.step.completedAt ?? ''))[0];
  const lastPhaseDone = lastDone ? core.steps.filter((x) => x.def.phase === lastDone.def.phase).every((x) => isDone(x.step)) : false;
  const nextStarted = core.steps.some((x) => x.def.phase === core.current && !isDone(x.step) && x.step.evidenceCount > 0) || milestones.some((m) => m.phase === core.current && m.stepsDone > 0);
  const freshness = freshnessOf({ status: job.status, lastAt, now, stoppedNow: core.stoppedNow, nextStarted, justCompletedStage: lastPhaseDone && !!lastDone && lastDone.def.phase !== core.current });

  const events: TimelineEvent[] = staff
    ? [
        ...(job.startedAt ? [{ id: 'started', at: job.startedAt, kind: 'started' as const, labelKey: null, byName: null, code: null, severity: null }] : []),
        ...core.steps.filter((x) => x.step.completedAt).map((x) => ({ id: `step-${x.step.id}`, at: x.step.completedAt as string, kind: 'step_done' as const, labelKey: x.step.labelKey, byName: x.step.completedByName ?? null, code: null, severity: null })),
        ...own.flatMap((i) => [
          { id: `iss-${i.id}`, at: i.createdAt, kind: 'issue_reported' as const, labelKey: null, byName: i.reportedByName, code: i.code, severity: i.severity },
          ...(i.resolution ? [{ id: `res-${i.id}`, at: i.resolution.at, kind: 'issue_resolved' as const, labelKey: null, byName: i.resolution.byName, code: i.code, severity: i.severity }] : []),
        ]),
        ...(job.completedAt ? [{ id: 'completed', at: job.completedAt, kind: 'completed' as const, labelKey: null, byName: null, code: null, severity: null }] : []),
      ]
        .sort((a, b) => b.at.localeCompare(a.at))
        .slice(0, 30)
    : [];

  const team: TimelineTeamMember[] = staff
    ? peopleOn(job).map((uid): TimelineTeamMember => {
        const person = byId(users, uid);
        const ownIds = ownStepIds(job, uid);
        const mine = ownIds === null ? null : core.steps.filter((x) => ownIds.includes(x.step.id));
        return {
          userId: uid,
          name: person?.name ?? uid,
          role: roleOf(job, uid) ?? 'assistant',
          owned: mine === null ? null : mine.length,
          ownedDone: mine === null ? core.stepsDone : mine.filter((x) => isDone(x.step)).length,
          completedByThem: core.steps.filter((x) => stepFinisherName(job, x.step) === person?.name && !!person?.name).length,
          onSiteNow: siteCheckIns.some((v) => v.jobId === job.id && v.userId === uid && !v.checkOutAt),
        };
      })
    : [];

  return {
    audience,
    job: { id: job.id, code: job.code, siteName: job.siteName, status: job.status, scheduledFor: job.scheduledFor, startedAt: job.startedAt ?? null, completedAt: job.completedAt ?? null },
    hiddenFromCustomer: !!job.customerTimelineHidden,
    progress: { stepsDone: core.stepsDone, stepsTotal: core.stepsTotal, percent: core.stepsTotal ? Math.round((core.stepsDone / core.stepsTotal) * 100) : 0 },
    current: core.current,
    milestones: hidden ? [] : milestones,
    estimate: hidden
      ? null
      : {
          originalAt: iso(core.estimate.originalAt),
          currentAt: iso(core.estimate.currentAt),
          slipDays: core.estimate.slipDays,
          slipped: core.estimate.slipped,
          atLeast: core.estimate.atLeast && !job.completedAt,
          basis: core.planned.basis,
          plannedDays: Math.round(core.planned.ms / 86_400_000),
          pace: staff ? Math.round(core.estimate.pace * 100) / 100 : null,
        },
    reasons: hidden ? [] : reasons,
    freshness,
    lastUpdateAt: lastAt === null ? null : iso(lastAt),
    blockedMs: staff ? core.blocked : 0,
    events,
    team,
    canToggleVisibility: user.role === 'admin',
  };
}

/* ============================== Technician team coordination (130) */

const jobHandoffs: JobHandoffNote[] = [];
const jobTeamMessages: JobTeamMessage[] = [];
let teamSeeded = false;
let teamCounter = 100;
const TEAM_TEXT_MAX = 1000;
const HANDOFF_MIN = 15;
const DELEGATION_MAX_DAYS = 30;

function ensureTeamSeeds(): void {
  if (teamSeeded) return;
  teamSeeded = true;
  const job = byId(jobs, 'j-1');
  if (!job) return;
  const ago = (h: number) => new Date(Date.now() - h * 3_600_000).toISOString();
  const msg = (id: string, authorId: string, text: string, h: number): JobTeamMessage => ({ id, jobId: 'j-1', authorId, authorName: byId(users, authorId)?.name ?? authorId, text, createdAt: ago(h), kind: 'message', readBy: [authorId], isDemo: true });
  jobTeamMessages.push(
    msg('tm-seed-1', 'u-tech-1', 'Rails are aligned. I will start on the machine mount after lunch.', 30),
    msg('tm-seed-2', 'u-tech-2', 'Understood. I have the door sensor kit with me for tomorrow.', 29),
    msg('tm-seed-3', 'u-tech-1', 'The society says no drilling after 5 pm. Plan the noisy work for the morning.', 6),
  );
  jobHandoffs.push({ id: 'ho-seed-1', jobId: 'j-1', fromUserId: 'u-tech-2', fromName: byId(users, 'u-tech-2')?.name ?? '', toUserId: 'u-tech-1', toName: byId(users, 'u-tech-1')?.name ?? '', text: 'Left the door sensor wiring half done at the fifth floor landing. The cable is marked with red tape, and the gate key is with the watchman.', openStepIds: ['s6', 's7'], createdAt: ago(5), acknowledgedBy: [], isDemo: true });
}

/** Who may see this team: anyone on the job, and Admin. A customer or supplier never does. */
function teamActor(jobId: string, userId: string): { job: Job; user: User; isAdmin: boolean } {
  ensureTeamSeeds();
  const user = byId(users, userId);
  const job = byId(jobs, jobId);
  if (!user) throw new RepositoryError('forbidden');
  if (!job) throw new RepositoryError('not_found');
  if (user.role === 'admin') return { job, user, isAdmin: true };
  if (user.role !== 'technician' || !isOnJob(job, userId)) throw new RepositoryError('forbidden');
  return { job, user, isAdmin: false };
}

/** The lead, or whoever holds the lead's authority for these days, or Admin. */
function teamManager(jobId: string, userId: string): { job: Job; user: User; isAdmin: boolean } {
  const a = teamActor(jobId, userId);
  if (!a.isAdmin && !leadIdsOf(a.job).includes(userId)) throw new RepositoryError('not_lead');
  return a;
}

const teamEvent = (kind: JobTeamEventKind, byName: string, subjectName?: string, note?: string): JobTeamEvent => {
  teamCounter += 1;
  return { id: `te-${teamCounter}`, at: new Date().toISOString(), kind, byName, ...(subjectName ? { subjectName } : {}), ...(note ? { note } : {}) };
};
const logTeam = (job: Job, e: JobTeamEvent, patch: Partial<Job> = {}): Job => patchInPlace(jobs, job.id, { ...patch, teamLog: [...(job.teamLog ?? []), e] });

/** The crew as it stands, with the lead first and a lead entry for whoever leads. */
function crewOf(job: Job): JobCrewMember[] {
  const crew = (job.crew ?? []).map((c) => ({ ...c, stepIds: [...c.stepIds] }));
  if (job.technicianId && !crew.some((c) => c.userId === job.technicianId)) crew.unshift({ userId: job.technicianId, role: 'lead', stepIds: [] });
  return crew;
}

function jobTeamViewOf(job: Job, viewerId: string, now: number): JobTeamView {
  const viewer = byId(users, viewerId) as User;
  const isAdmin = viewer.role === 'admin';
  const version = sopVersionOf(job);
  const spec = sopSpecOf(job);
  const steps = version.steps.flatMap((def) => {
    const st = job.steps.find((x) => x.id === def.id);
    return st && stepApplies(def, spec) ? [{ def, st }] : [];
  });
  const crew = crewOf(job);
  const ownerOf = (stepId: string): string | null => crew.find((c) => c.role === 'assistant' && c.stepIds.includes(stepId))?.userId ?? null;
  const deleg = delegationActive(job.leadDelegation, now) ? job.leadDelegation : null;
  const members: TeamMemberView[] = crew.map((c) => {
    const u = byId(users, c.userId);
    const isLead = c.userId === job.technicianId;
    const mine = isLead ? null : steps.filter((x) => c.stepIds.includes(x.st.id));
    const visit = siteCheckIns.find((v) => v.jobId === job.id && v.userId === c.userId && !v.checkOutAt);
    const current = (mine ?? steps).find((x) => x.st.status === 'current');
    return {
      userId: c.userId,
      name: u?.name ?? c.userId,
      phone: viewer.role === 'technician' || isAdmin ? (u?.phone ?? null) : null,
      role: isLead ? 'lead' : 'assistant',
      delegated: !isLead && !!deleg && deleg.toUserId === c.userId,
      responsibility: c.responsibility ?? null,
      steps: (mine ?? []).map((x) => ({ id: x.st.id, labelKey: x.st.labelKey, status: x.st.status })),
      owned: mine === null ? null : mine.length,
      ownedDone: (mine ?? steps).filter((x) => isDone(x.st)).length,
      completedByThem: steps.filter((x) => stepFinisherName(job, x.st) === u?.name && !!u?.name).length,
      currentStepLabelKey: current?.st.labelKey ?? null,
      onSiteSince: visit?.checkInAt ?? null,
      isMe: c.userId === viewerId,
    };
  });
  const multi = peopleOn(job).length > 1;
  const readiness = qcReadiness(version.steps, job.steps, spec);
  const problem = job.status !== 'in_progress' ? (job.status === 'on_hold' ? 'job_on_hold' : 'read_only') : !readiness.ready ? 'not_ready' : null;
  const lead = byId(users, job.technicianId ?? '');
  const seen = (m: JobTeamMessage) => m.readBy.includes(viewerId);
  const msgs = jobTeamMessages.filter((m) => m.jobId === job.id).sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  const disagreementIssue = [...jobIssues].filter((i) => i.jobId === job.id && i.teamDisagreement).sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0];
  const stepLabel = (id: string) => job.steps.find((x) => x.id === id)?.labelKey ?? id;
  const role: JobTeamView['viewer']['role'] = isAdmin ? 'admin' : (roleOf(job, viewerId) ?? 'assistant');
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, status: job.status, scheduledFor: job.scheduledFor, startedAt: job.startedAt ?? null },
    viewer: { userId: viewerId, role, holdsLead: !isAdmin && leadIdsOf(job, now).includes(viewerId) },
    lead: { userId: job.technicianId ?? '', name: lead?.name ?? '' },
    delegation: job.leadDelegation && !job.leadDelegation.revokedAt && new Date(`${job.leadDelegation.until}T23:59:59`).getTime() >= now ? { ...job.leadDelegation } : null,
    members,
    steps: steps.map((x) => ({ id: x.st.id, labelKey: x.st.labelKey, status: x.st.status, ownerId: ownerOf(x.st.id) })),
    progress: { done: steps.filter((x) => isDone(x.st)).length, total: steps.length },
    signOff: { needed: multi, ready: readiness.ready, signedOff: job.leadSignOff ? { at: job.leadSignOff.at, byName: job.leadSignOff.byName } : null, awaitingLead: multi && readiness.ready && !job.leadSignOff && job.status === 'in_progress', problem },
    handoffs: jobHandoffs
      .filter((h) => h.jobId === job.id)
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
      .map((h): TeamHandoffView => ({
        id: h.id,
        fromUserId: h.fromUserId,
        fromName: h.fromName,
        toUserId: h.toUserId ?? null,
        toName: h.toName ?? null,
        text: h.text,
        openSteps: h.openStepIds.map((id) => ({ id, labelKey: stepLabel(id) })),
        createdAt: h.createdAt,
        acknowledgedBy: h.acknowledgedBy.map((a) => ({ ...a })),
        mine: h.fromUserId === viewerId,
        waitingForMe: !isAdmin && h.fromUserId !== viewerId && (h.toUserId ? h.toUserId === viewerId : true) && !h.acknowledgedBy.some((a) => a.userId === viewerId),
      })),
    messages: msgs.map((m): TeamMessageView => ({ id: m.id, authorId: m.authorId, authorName: m.authorName, text: m.text, createdAt: m.createdAt, kind: m.kind, issueId: m.issueId ?? null, mine: m.authorId === viewerId, unread: !seen(m) })),
    unread: msgs.filter((m) => !seen(m)).length,
    log: [...(job.teamLog ?? [])].reverse(),
    addable: isAdmin
      ? users
          .filter((u) => u.role === 'technician' && u.status === 'active' && acceptsNewWork(u.id) && trainingClear(u.id) && !isOnJob(job, u.id))
          .map((u) => ({ id: u.id, name: u.name, otherJobsToday: jobs.filter((j) => j.id !== job.id && isOnJob(j, u.id) && (j.status === 'in_progress' || dayKey(j.scheduledFor) === dayKey(now))).length }))
      : [],
    disagreement: disagreementIssue ? { issueId: disagreementIssue.id, code: disagreementIssue.code, at: disagreementIssue.createdAt, resolved: disagreementIssue.status === 'resolved' } : null,
    canWrite: true,
    canManage: isAdmin || leadIdsOf(job, now).includes(viewerId),
    canAdmin: isAdmin,
  };
}

/** A shared reading of who is waiting on a handoff note, for the follow-up engine. */
function handoffOwnerOf(job: Job, h: JobHandoffNote): string | null {
  if (h.toUserId) return h.toUserId;
  const others = peopleOn(job).filter((id) => id !== h.fromUserId);
  return leadIdsOf(job).find((id) => others.includes(id)) ?? others[0] ?? null;
}

/** An alert while a team disagreement stands, cleared when its report is closed: Admin sees a team that cannot agree, not a silent delay. */
function syncTeamAlerts(automated: boolean, now: number): void {
  ensureTeamSeeds();
  const at = new Date(now).toISOString();
  const live = new Set<string>();
  for (const i of jobIssues) {
    if (!i.teamDisagreement || i.status !== 'open') continue;
    const job = byId(jobs, i.jobId);
    if (!job) continue;
    const key = `disagree:${i.id}`;
    live.add(key);
    if (alerts.some((a) => a.relatedId === key && a.status !== 'resolved')) continue;
    raiseAlert({ titleKey: 'jobTeam.alert.disagreement', context: `${job.code} · ${job.siteName}: ${i.description}`, severity: 'medium', category: 'quality', relatedId: key, sourceRoute: `/job-issues/${job.id}?issue=${i.id}`, location: job.location });
    if (automated) logAutomatedAction({ sourceKey: 'team.disagreement', triggeringCondition: `The team on ${job.code} flagged that they could not agree`, actionTaken: 'Raised an alert so Admin can settle it', affectedRecordId: i.id, affectedRecordType: 'other', subjectLabel: job.code });
  }
  for (const a of alerts) if (a.relatedId?.startsWith('disagree:') && a.status !== 'resolved' && !live.has(a.relatedId)) patchInPlace(alerts, a.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'Closed.' });
}

/** The lead's authority handed over for a few days lapses by itself on the day after: recorded so the team's history says so. */
function syncLeadDelegations(now: number): void {
  for (const j of jobs) {
    const d = j.leadDelegation;
    if (!d || d.revokedAt) continue;
    if (new Date(`${d.until}T23:59:59`).getTime() < now) {
      const ended = { ...d, revokedAt: new Date(now).toISOString() };
      logTeam(j, teamEvent('delegation_ended', 'AIEC', d.toName, 'The days it was given for have passed.'), { leadDelegation: ended });
      logAutomatedAction({ sourceKey: 'team.delegation_ended', triggeringCondition: `The lead's authority on ${j.code} was given to ${d.toName} until ${d.until}`, actionTaken: 'Returned it to the lead', affectedRecordId: j.id, affectedRecordType: 'other', subjectLabel: j.code });
    }
  }
}

/** Jobs whose checklist is all done with more than one person on them, waiting for the lead to say so. */
function leadSignOffsWaiting(): { jobId: string; ownerId: string; doneAt: string }[] {
  return jobs.flatMap((j) => {
    if (j.status !== 'in_progress' || peopleOn(j).length < 2 || j.leadSignOff) return [];
    const version = sopVersionOf(j);
    if (!qcReadiness(version.steps, j.steps, sopSpecOf(j)).ready) return [];
    const doneAt = j.steps.map((s) => s.completedAt).filter((x): x is string => !!x).sort().pop();
    return doneAt && j.technicianId ? [{ jobId: j.id, ownerId: (leadIdsOf(j).length > 1 ? leadIdsOf(j)[1] : j.technicianId) as string, doneAt }] : [];
  });
}

/* ============================== QC inspector assignment (131) */

const qcAssignments: QcAssignment[] = [];
const inspectorOff: InspectorUnavailability[] = [];
let qcSeeded = false;
let qcCounter = 100;
const QC_EXCEPTION_NOTE_MIN = 20;
const QC_REASON_MIN = 8;

function ensureQcSeeds(): void {
  if (qcSeeded) return;
  qcSeeded = true;
  const anand = byId(users, 'u-tech-5');
  const ago = (d: number) => new Date(Date.now() - d * 86_400_000);
  const done = (jobId: string, daysBack: number): void => {
    const job = byId(jobs, jobId);
    if (!job || !anand) return;
    const day = qcDay(ago(daysBack).getTime());
    qcAssignments.push({ id: `qca-seed-${jobId}`, jobId, inspectorId: anand.id, inspectorName: anand.name, mode: 'inspector', status: 'completed', scheduledDate: day, window: 'morning', customerAgreedAt: ago(daysBack + 2).toISOString(), assignedAt: ago(daysBack + 3).toISOString(), assignedByName: 'Prashant Vasant Wable', notifiedAt: ago(daysBack + 3).toISOString(), previous: [], events: [{ id: `qce-seed-${jobId}`, at: ago(daysBack + 3).toISOString(), kind: 'assigned', byName: 'Prashant Vasant Wable' }], isDemo: true });
  };
  done('j-5', 36);
  done('j-7', 7);
  // The customer at j-2 would like the visit tomorrow morning, and the one qualified, independent inspector is away that morning.
  const tomorrow = nextWorkingDayKey(1);
  const j2 = byId(jobs, 'j-2');
  if (j2 && anand) {
    patchInPlace(jobs, j2.id, { qcPreference: { dates: [tomorrow], window: 'morning', note: 'The society office is open only in the mornings.', recordedByName: 'Prashant Vasant Wable', at: new Date().toISOString() } });
    inspectorOff.push({ id: 'iu-seed-1', userId: anand.id, date: tomorrow, window: 'all', reason: 'Quality check at another society in Nashik', setByName: anand.name, at: new Date().toISOString() });
  }
}

function nextWorkingDayKey(minDaysAhead: number): string {
  let key = qcAddDays(qcDay(Date.now()), minDaysAhead);
  while (!isWorkingDay(key)) key = qcAddDays(key, 1);
  return key;
}
const qcAddDays = (key: string, n: number) => qcDay(new Date(`${key}T12:00:00`).getTime() + n * 86_400_000);

const qcActive = (a: QcAssignment) => a.status === 'assigned' || a.status === 'scheduled' || a.status === 'in_progress';
const qcOf = (jobId: string): QcAssignment | undefined => qcAssignments.filter((a) => a.jobId === jobId && a.status !== 'cancelled').sort((a, b) => b.assignedAt.localeCompare(a.assignedAt))[0];

/** When the checklist and its safety checks were finished, which is when the job first waited for a quality check. */
function qcReadyAtOf(job: Job): string | null {
  const stamps = [job.leadSignOff?.at, ...job.steps.map((s) => s.completedAt)].filter((x): x is string => !!x).sort();
  return stamps.length ? stamps[stamps.length - 1] : null;
}

function qcReadinessOf(job: Job): QcReadinessView {
  const version = sopVersionOf(job);
  const spec = sopSpecOf(job);
  const r = qcReadiness(version.steps, job.steps, spec);
  const safetyOpen = safetyBlocking(job).length;
  const beyond = job.status === 'qc_pending' || job.status === 'handover_pending' || job.status === 'completed';
  return {
    ready: job.status === 'qc_pending',
    jobStatus: job.status,
    installationOpen: beyond ? 0 : r.open.length + r.short.length,
    safetyOpen: beyond ? 0 : safetyOpen,
    awaitingLead: !beyond && peopleOn(job).length > 1 && r.ready && !job.leadSignOff,
    onHold: job.status === 'on_hold',
    readyAt: beyond ? qcReadyAtOf(job) : null,
  };
}

function involvementFactsOf(job: Job): InvolvementFacts {
  return {
    leadId: job.technicianId,
    crewIds: (job.crew ?? []).map((c) => c.userId),
    checkedInIds: [...new Set(siteCheckIns.filter((v) => v.jobId === job.id).map((v) => v.userId))],
    finishedByNames: job.steps.map((s) => s.completedByName).filter((x): x is string => !!x),
    removedNames: (job.teamLog ?? []).filter((e) => e.kind === 'reassigned' && e.subjectName).map((e) => e.subjectName as string),
  };
}

function inspectorBusyFacts(userId: string, exceptAssignmentId?: string): BusyFacts {
  return {
    visits: qcAssignments.filter((a) => a.inspectorId === userId && qcActive(a) && a.scheduledDate && a.window && a.id !== exceptAssignmentId).map((a) => ({ date: a.scheduledDate as string, window: a.window as QcWindow })),
    unavailable: inspectorOff.filter((u) => u.userId === userId).map((u) => ({ date: u.date, window: u.window })),
    installDays: jobs.filter((j) => isOnJob(j, userId) && (j.status === 'scheduled' || j.status === 'materials_pending')).map((j) => qcDay(new Date(j.scheduledFor).getTime())),
  };
}

function qcAssignmentViewOf(a: QcAssignment): QcAssignmentView {
  return {
    id: a.id,
    jobId: a.jobId,
    inspectorId: a.inspectorId,
    inspectorName: a.inspectorName,
    mode: a.mode,
    exceptionGaps: a.exceptionGaps ?? [],
    exceptionNote: a.exceptionNote ?? null,
    status: a.status,
    scheduledDate: a.scheduledDate ?? null,
    window: a.window ?? null,
    customerAgreed: !!a.customerAgreedAt,
    conflict: a.conflict && !a.conflict.clearedAt ? { ...a.conflict, involvement: [...a.conflict.involvement] } : null,
    assignedAt: a.assignedAt,
    assignedByName: a.assignedByName,
    notifiedAt: a.notifiedAt ?? null,
    previous: a.previous.map((p) => ({ ...p })),
    events: a.events.map((e) => ({ ...e })),
  };
}

function qcCandidatesOf(job: Job, now: number): QcCandidateView[] {
  const facts = involvementFactsOf(job);
  const weekAgo = qcDay(now - 7 * 86_400_000);
  const weekAhead = qcDay(now + 7 * 86_400_000);
  return users
    .filter((u) => u.role === 'technician')
    .map((u): QcCandidateView => {
      const e = eligibilityOf({ id: u.id, name: u.name, role: u.role, status: u.status, skills: u.skills }, facts);
      const busy = inspectorBusyFacts(u.id);
      const pref = job.qcPreference;
      return {
        userId: u.id,
        name: u.name,
        phone: u.phone,
        skills: normalizeSkills(u.skills),
        eligible: e.eligible,
        problems: e.problems,
        missing: e.missing,
        involvement: e.involvement,
        qcThisWeek: qcAssignments.filter((a) => a.inspectorId === u.id && qcActive(a) && a.scheduledDate && a.scheduledDate >= weekAgo && a.scheduledDate <= weekAhead).length,
        installJobs: jobs.filter((j) => isOnJob(j, u.id) && j.status !== 'completed').length,
        distanceKm: u.location ? Math.round(haversineKm(u.location, job.location) * 10) / 10 : null,
        onPreferred: (pref?.dates ?? []).flatMap((date) => WINDOWS.filter((w) => pref?.window === 'any' || pref?.window === w).map((window) => ({ date, window, busy: busyBecause(busy, date, window) }))),
      };
    })
    .sort((a, b) => Number(b.eligible) - Number(a.eligible) || (a.distanceKm ?? 999) - (b.distanceKm ?? 999));
}

function qcBriefingOf(job: Job): QcBriefingView {
  const version = sopVersionOf(job);
  const spec = sopSpecOf(job);
  const steps = version.steps.flatMap((def) => {
    const st = job.steps.find((x) => x.id === def.id);
    return st && stepApplies(def, spec)
      ? [{ id: st.id, labelKey: st.labelKey, status: st.status, completedAt: st.completedAt ?? null, completedByName: st.completedByName ?? null, notApplicable: !!st.notApplicable, safetyCritical: def.safetyCritical, evidence: (st.evidence ?? []).map((e) => ({ id: e.id, slotId: e.slotId, kind: e.kind, previewUrl: e.previewUrl, capturedAt: e.capturedAt, byName: e.byName })) }]
      : [];
  });
  const entries = safetyEntriesOf(job);
  const log = materialLogs.find((l) => l.jobId === job.id);
  return {
    steps,
    safety: { open: safetyBlocking(job).length, total: entries.length },
    issues: jobIssues.filter((i) => i.jobId === job.id).map((i) => ({ code: i.code, category: i.category, severity: i.severity, status: i.status })),
    materials: { status: log ? log.status : 'none', parts: (log?.status === 'confirmed' ? log.uses.filter((u) => u.usedQty > 0) : []).map((u) => ({ description: u.description, quantity: u.usedQty, source: u.source, identifiers: u.identifiers.map((i) => ({ value: i.legible ? (i.serial ?? i.batch ?? null) : null, legible: i.legible })), substituted: u.deviation?.kind === 'substitute' })) },
    team: peopleOn(job).map((id) => ({ name: byId(users, id)?.name ?? id, role: id === job.technicianId ? ('lead' as const) : ('assistant' as const) })),
    site: { address: job.address, location: job.location },
  };
}

function qcJobDetailOf(job: Job, userId: string, now: number): QcJobDetail {
  const user = byId(users, userId) as User;
  const isAdmin = user.role === 'admin';
  const a = qcOf(job.id);
  const viewer: QcJobDetail['viewer'] = isAdmin ? 'admin' : a && a.inspectorId === userId ? 'inspector' : 'other';
  const readiness = qcReadinessOf(job);
  const candidates = isAdmin ? qcCandidatesOf(job, now) : [];
  const eligible = candidates.filter((c) => c.eligible);
  const pref = job.qcPreference;
  const suggestions = isAdmin
    ? suggestSlots({ today: qcDay(now), now, inspectors: (a && qcActive(a) ? [{ id: a.inspectorId, busy: inspectorBusyFacts(a.inspectorId, a.id) }] : eligible.map((c) => ({ id: c.userId, busy: inspectorBusyFacts(c.userId) }))), preferred: pref ? { dates: pref.dates, window: pref.window } : undefined })
    : [];
  const canWork = isAdmin && readiness.ready;
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, address: job.address, status: job.status, scheduledFor: job.scheduledFor },
    viewer,
    readiness,
    assignment: a ? qcAssignmentViewOf(a) : null,
    preference: pref ? { ...pref, dates: [...pref.dates] } : null,
    candidates,
    exceptionAdvised: isAdmin && readiness.ready && !(a && qcActive(a)) && eligible.length === 0,
    suggestions,
    briefing: isAdmin || viewer === 'inspector' ? qcBriefingOf(job) : null,
    myUnavailable: inspectorOff.filter((u) => u.userId === userId).map((u) => ({ ...u })),
    canAssign: canWork && !(a && qcActive(a)),
    canSchedule: canWork && !!a && (a.status === 'assigned' || a.status === 'scheduled'),
  };
}

function qcActor(jobId: string, userId: string): { job: Job; user: User; isAdmin: boolean } {
  ensureQcSeeds();
  const user = byId(users, userId);
  const job = byId(jobs, jobId);
  if (!user) throw new RepositoryError('forbidden');
  if (!job) throw new RepositoryError('not_found');
  if (user.role === 'admin') return { job, user, isAdmin: true };
  const a = qcOf(job.id);
  if (user.role !== 'technician' || !a || a.inspectorId !== userId) throw new RepositoryError('forbidden');
  return { job, user, isAdmin: false };
}

const qcEvent = (kind: QcEventKind, byName: string, note?: string): QcAssignmentEvent => {
  qcCounter += 1;
  return { id: `qce-${qcCounter}`, at: new Date().toISOString(), kind, byName, ...(note ? { note } : {}) };
};

/** Tells the inspector, the way every other obligation is told: the visit is a commitment of theirs, and the nudge lands in their inbox. */
function notifyQcInspector(a: QcAssignment, reason: string): void {
  const now = Date.now();
  syncCommitments(now);
  const c = commitments.find((x) => x.kind === 'qc_visit' && x.subject.id === a.id && x.status === 'open');
  const owner = byId(users, a.inspectorId);
  if (!c || !owner) return;
  notifyWork(owner.id, c, 'nudge', new Date(now).toISOString());
  a.notifiedAt = new Date(now).toISOString();
  const job = byId(jobs, a.jobId);
  logAutomatedAction({ sourceKey: 'qc.inspector_notified', triggeringCondition: reason, actionTaken: `Told ${owner.name} about the quality check, with the job's evidence on file`, affectedRecordId: a.id, affectedRecordType: 'other', subjectLabel: job?.code ?? a.jobId });
}

/** The concern is checked on every beat, so an inspector who later turns out to have been on the installation is caught, not only one who says so. */
function syncQcAssignments(automated: boolean, now: number): void {
  ensureQcSeeds();
  const at = new Date(now).toISOString();
  const live = new Set<string>();
  for (const a of qcAssignments) {
    if (!qcActive(a)) continue;
    const job = byId(jobs, a.jobId);
    if (!job) continue;
    if (a.mode === 'inspector' && !a.conflict) {
      const inv = involvementOf(a.inspectorId, a.inspectorName, involvementFactsOf(job));
      if (inv.length > 0) {
        a.conflict = { kind: 'was_on_installation', involvement: inv, flaggedAt: at, byName: 'AIEC' };
        a.events.push(qcEvent('conflict_flagged', 'AIEC', inv.join(', ')));
        if (automated) logAutomatedAction({ sourceKey: 'qc.independence', triggeringCondition: `${a.inspectorName} was found to have taken part in the installation of ${job.code}`, actionTaken: 'Flagged it so Admin can reconsider the assignment', affectedRecordId: a.id, affectedRecordType: 'other', subjectLabel: job.code });
      }
    }
    if (a.conflict && !a.conflict.clearedAt) {
      const key = `qcconf:${job.id}`;
      live.add(key);
      if (!alerts.some((x) => x.relatedId === key && x.status !== 'resolved')) raiseAlert({ titleKey: 'qcAssignment.alert.conflict', context: `${job.code} · ${job.siteName}: ${a.inspectorName}`, severity: 'medium', category: 'quality', relatedId: key, sourceRoute: `/qc-assignments/${job.id}`, location: job.location });
    }
  }
  for (const al of alerts) if (al.relatedId?.startsWith('qcconf:') && al.status !== 'resolved' && !live.has(al.relatedId)) patchInPlace(alerts, al.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'Settled.' });
}

/** Jobs waiting for a quality check, for the follow-up engine. */
function qcWaitingJobs(): { jobId: string; readyAt: string; assigned: boolean }[] {
  return jobs.filter((j) => j.status === 'qc_pending').map((j) => ({ jobId: j.id, readyAt: qcReadyAtOf(j) ?? new Date().toISOString(), assigned: !!qcOf(j.id) }));
}

function qcRequireReady(job: Job): void {
  if (job.status !== 'qc_pending') throw new RepositoryError(job.status === 'completed' || job.status === 'handover_pending' ? 'already_checked' : 'not_ready');
}

/** Whether this person may be named: someone short of a tag only as a documented exception, someone who took part in the installation never. */
function qcNamable(job: Job, person: User, exceptionNote: string | undefined): { mode: 'inspector' | 'admin_exception'; gaps: string[] } {
  const e = eligibilityOf({ id: person.id, name: person.name, role: person.role, status: person.status, skills: person.skills }, involvementFactsOf(job));
  if (e.problems.includes('not_active')) throw new RepositoryError('not_active');
  if (e.problems.includes('not_independent')) throw new RepositoryError('not_independent');
  if (e.problems.includes('missing_skill')) {
    if ((exceptionNote ?? '').trim().length < QC_EXCEPTION_NOTE_MIN) throw new RepositoryError('exception_note_required');
    return { mode: 'admin_exception', gaps: e.missing };
  }
  return { mode: 'inspector', gaps: [] };
}

/* ============================== QC mechanical check (132) */

const qcMechChecks: QcMechCheck[] = [];
const qcFindings: QcFinding[] = [];
const reworkRequests: ReworkRequest[] = [];
let snagCounter = 100;
let snagSeeded = false;
const snagEvent = (kind: SnagEvent['kind'], byName: string, note?: string, at = new Date().toISOString()): SnagEvent => ({ id: `sge-${++snagCounter}`, at, kind, byName, ...(note?.trim() ? { note: note.trim() } : {}) });

/** A failed check is a snag. Failing the same item again updates the one already open rather than listing the same finding twice. */
function raiseChecklistSnag(job: Job, source: 'qc_mechanical' | 'qc_electrical', itemId: string, note: string, evidence: JobEvidence[], byName: string, at: string): void {
  const existing = reworkRequests.find((r) => r.jobId === job.id && r.source === source && r.itemId === itemId && sgIsOpen(r.status));
  if (existing) {
    existing.note = note;
    existing.evidence = evidence.map((e) => ({ ...e }));
    // A retest that failed again puts it back with whoever is fixing it, to be fixed properly.
    if (existing.status === 'ready_for_retest') existing.status = existing.ownerId ? 'assigned' : 'open';
    existing.events.push(snagEvent('failed_again', byName, note, at));
    return;
  }
  snagCounter += 1;
  reworkRequests.push({ id: `rw-${snagCounter}`, code: `SNAG-${snagCounter}`, jobId: job.id, source, itemId, note, evidence: evidence.map((e) => ({ ...e })), raisedByName: byName, raisedAt: at, severity: sgSeverityOfSource(source), status: 'open', events: [snagEvent('raised', byName, note, at)], isDemo: true });
}

/** A re-test that passes is QC's own verification of the snags on that item. */
function verifyChecklistSnags(job: Job, source: 'qc_mechanical' | 'qc_electrical', itemId: string, byName: string, at: string): void {
  for (const r of reworkRequests) {
    if (r.jobId !== job.id || r.source !== source || r.itemId !== itemId || !sgIsOpen(r.status)) continue;
    Object.assign(r, { status: 'verified' as const, verifiedAt: at, verifiedByName: byName });
    r.events.push(snagEvent('verified', byName, 'Re-test passed', at));
  }
}
let mechCounter = 100;

/** Who may open this check: the assigned inspector (Admin, when Admin holds the role), Admin to review, and the lead to explain a difference. */
function mechActor(jobId: string, userId: string): { job: Job; user: User; viewer: QcMechView['viewer']; assignment: QcAssignment | undefined } {
  ensureQcSeeds();
  const user = byId(users, userId);
  const job = byId(jobs, jobId);
  if (!user) throw new RepositoryError('forbidden');
  if (!job) throw new RepositoryError('not_found');
  const assignment = qcOf(job.id);
  if (user.role === 'admin') return { job, user, viewer: 'admin', assignment };
  if (user.role === 'technician' && assignment && assignment.inspectorId === userId) return { job, user, viewer: 'inspector', assignment };
  if (user.role === 'technician' && leadIdsOf(job).includes(userId)) return { job, user, viewer: 'lead', assignment };
  throw new RepositoryError('forbidden');
}

const mechCheckOf = (jobId: string): QcMechCheck => {
  let c = qcMechChecks.find((x) => x.jobId === jobId);
  if (!c) {
    c = { jobId, attempts: {}, isDemo: true };
    qcMechChecks.push(c);
  }
  return c;
};

function mechFloorsOf(job: Job): number {
  const deal = byId(deals, job.dealId);
  const lead = deal ? resolveLead(deal.leadId) : null;
  return Math.max(2, Math.min(lead?.spec?.floors ?? 4, 40));
}

const mediaToEvidence = (m: SopMediaInput, id: string, slotId: string, user: User): JobEvidence => ({ id, slotId, kind: m.kind, fileName: m.fileName, previewUrl: m.previewUrl, ...(m.mediaUrl ? { mediaUrl: m.mediaUrl } : {}), mimeType: m.mimeType, sizeBytes: m.sizeBytes, ...(m.durationS !== undefined ? { durationS: m.durationS } : {}), capturedAt: m.capturedAt, ...(m.location ? { location: m.location } : {}), byUserId: user.id, byName: user.name });

function mechViewOf(job: Job, _userId: string, viewer: QcMechView['viewer'], assignment: QcAssignment | undefined): QcMechView {
  const check = mechCheckOf(job.id);
  const floors = mechFloorsOf(job);
  const items: QcMechItemView[] = MECH_ITEMS.map((id) => {
    const attempts = check.attempts[id] ?? [];
    const rework = [...reworkRequests].reverse().find((r) => r.jobId === job.id && r.source === 'qc_mechanical' && r.itemId === id && sgIsOpen(r.status));
    return {
      id,
      state: itemState(attempts),
      attempts: attempts.map((a): QcMechAttemptView => ({ id: a.id, n: a.n, verdict: a.verdict, suggested: a.suggested, overrideReason: a.overrideReason ?? null, measures: a.measures.map((m) => ({ ...m })), floors: a.floors.map((f) => ({ ...f })), rubric: a.rubric ?? null, note: a.note ?? null, evidence: a.evidence.map((e) => ({ id: e.id, kind: e.kind, previewUrl: e.previewUrl, ...(e.mediaUrl ? { mediaUrl: e.mediaUrl } : {}), capturedAt: e.capturedAt })), at: a.at, byName: a.byName, review: a.review ? { ...a.review } : null })),
      reference: INSTALL_STEPS[id].flatMap((sid) => {
        const st = job.steps.find((x) => x.id === sid);
        return st ? [{ stepId: st.id, labelKey: st.labelKey, completedAt: st.completedAt ?? null, completedByName: st.completedByName ?? null, photos: (st.evidence ?? []).map((e) => ({ id: e.id, previewUrl: e.previewUrl, capturedAt: e.capturedAt })) }] : [];
      }),
      findings: qcFindings.filter((f) => f.jobId === job.id && f.itemId === id).map((f): QcFindingView => ({ id: f.id, itemId: f.itemId, description: f.description, raisedByName: f.raisedByName, raisedAt: f.raisedAt, explanation: f.explanation ? { ...f.explanation } : null, accepted: !!f.acceptedAt })),
      rework: rework ? { id: rework.id, status: rework.status } : null,
    };
  });
  const cleared = items.filter((i) => isMechCleared(i.state)).length;
  const openFindings = qcFindings.filter((f) => f.jobId === job.id && !f.acceptedAt).length;
  const activeAssignment = !!assignment && qcActive(assignment);
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, status: job.status },
    viewer,
    assignment: assignment ? { inspectorName: assignment.inspectorName, status: assignment.status, mode: assignment.mode } : null,
    floors,
    items,
    progress: { cleared, total: items.length },
    signOff: { problem: mechSignOffProblem(items.map((i) => i.state), openFindings), signedOff: check.signedOff ? { at: check.signedOff.at, byName: check.signedOff.byName } : null },
    canRecord: viewer === 'inspector' && activeAssignment && job.status === 'qc_pending' && !check.signedOff,
    canReview: viewer === 'admin',
    canExplain: viewer === 'lead' || viewer === 'admin',
  };
}

/** A fail is an alert until it is put right; the rework screen (136) takes it from there. Cleared when the item passes. */
function syncQcMechAlerts(now: number): void {
  const at = new Date(now).toISOString();
  const live = new Set<string>();
  for (const c of qcMechChecks) {
    const job = byId(jobs, c.jobId);
    if (!job) continue;
    for (const id of MECH_ITEMS) {
      if (itemState(c.attempts[id]) !== 'fail') continue;
      const key = `qcfail:${c.jobId}:${id}`;
      live.add(key);
      if (!alerts.some((a) => a.relatedId === key && a.status !== 'resolved')) raiseAlert({ titleKey: 'qcMech.alert.fail', context: `${job.code} · ${job.siteName}: ${id}`, severity: 'high', category: 'quality', relatedId: key, sourceRoute: `/qc-mechanical/${c.jobId}`, location: job.location });
    }
  }
  for (const a of alerts) if (a.relatedId?.startsWith('qcfail:') && a.status !== 'resolved' && !live.has(a.relatedId)) patchInPlace(alerts, a.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'Put right.' });
}

/* ============================== QC electrical & safety check (133) */

const qcElecChecks: QcElecCheck[] = [];
const elecCheckOf = (jobId: string): QcElecCheck => {
  let c = qcElecChecks.find((x) => x.jobId === jobId);
  if (!c) {
    c = { jobId, attempts: {}, isDemo: true };
    qcElecChecks.push(c);
  }
  return c;
};

function elecViewOf(job: Job, viewer: QcMechView['viewer'], assignment: QcAssignment | undefined): QcElecView {
  const check = elecCheckOf(job.id);
  const items: QcElecItemView[] = ELEC_ITEMS.map((id) => {
    const attempts = check.attempts[id] ?? [];
    const rework = [...reworkRequests].reverse().find((r) => r.jobId === job.id && r.source === 'qc_electrical' && r.itemId === id && sgIsOpen(r.status));
    return {
      id,
      state: elecStateOf(attempts),
      attempts: attempts.map((a): QcElecAttemptView => ({ id: a.id, n: a.n, verdict: a.verdict, suggested: a.suggested, measures: a.measures.map((m) => ({ ...m })), checks: a.checks.map((c) => ({ ...c })), intermittent: a.intermittent, note: a.note ?? null, evidence: a.evidence.map((e) => ({ id: e.id, kind: e.kind, previewUrl: e.previewUrl, ...(e.mediaUrl ? { mediaUrl: e.mediaUrl } : {}), capturedAt: e.capturedAt })), at: a.at, byName: a.byName })),
      reference: elecDef(id).installSteps.flatMap((sid) => {
        const st = job.steps.find((x) => x.id === sid);
        return st ? [{ stepId: st.id, labelKey: st.labelKey, completedAt: st.completedAt ?? null, completedByName: st.completedByName ?? null, photos: (st.evidence ?? []).map((e) => ({ id: e.id, previewUrl: e.previewUrl, capturedAt: e.capturedAt })) }] : [];
      }),
      rework: rework ? { id: rework.id, status: rework.status } : null,
    };
  });
  const cleared = items.filter((i) => i.state === 'pass').length;
  const failing = items.filter((i) => i.state === 'fail').map((i) => i.id);
  const open = items.filter((i) => i.state === 'not_checked').map((i) => i.id);
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, status: job.status },
    viewer,
    assignment: assignment ? { inspectorName: assignment.inspectorName, status: assignment.status, mode: assignment.mode } : null,
    items,
    progress: { cleared, total: items.length },
    hardBlock: { blocked: !check.signedOff, failing, open },
    signOff: { problem: elecSignOffProblem(items.map((i) => i.state)), signedOff: check.signedOff ? { at: check.signedOff.at, byName: check.signedOff.byName } : null },
    mechanicalSignedOff: !!mechCheckOf(job.id).signedOff,
    canRecord: viewer === 'inspector' && !!assignment && qcActive(assignment) && job.status === 'qc_pending' && !check.signedOff,
  };
}

/** A failed safety-critical check is an alert until a re-test passes; there is no way to wave it through. */
function syncQcElecAlerts(now: number): void {
  const at = new Date(now).toISOString();
  const live = new Set<string>();
  for (const c of qcElecChecks) {
    const job = byId(jobs, c.jobId);
    if (!job) continue;
    for (const id of ELEC_ITEMS) {
      if (elecStateOf(c.attempts[id]) !== 'fail') continue;
      const key = `qcelecfail:${c.jobId}:${id}`;
      live.add(key);
      if (!alerts.some((a) => a.relatedId === key && a.status !== 'resolved')) raiseAlert({ titleKey: 'qcElec.alert.fail', context: `${job.code} · ${job.siteName}: ${id}`, severity: 'high', category: 'safety', relatedId: key, sourceRoute: `/qc-electrical/${c.jobId}`, location: job.location });
    }
  }
  for (const a of alerts) if (a.relatedId?.startsWith('qcelecfail:') && a.status !== 'resolved' && !live.has(a.relatedId)) patchInPlace(alerts, a.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'Re-tested and passed.' });
}

/** Whether this job's safety verification has been passed in full: the one thing the compliance certification (134) waits for. */
const qcElectricalCleared = (jobId: string): boolean => !!elecCheckOf(jobId).signedOff;

/* ============================== Compliance certification (134) */

const complianceCertificates: ComplianceCertificate[] = [];
const stateGuidance: StateInspectionGuidance[] = seedStateGuidance.map((g) => ({ ...g, steps: [...g.steps] }));
let complianceSeeded = false;
let complianceCounter = 100;

const emptyPackage = (at: string): CertificatePackage => ({
  builtAt: at,
  installation: { stepsDone: 0, stepsTotal: 0, completedAt: null, leadName: null, teamCount: 0 },
  mechanical: { signedOff: null, items: [] },
  electrical: { signedOff: null, items: [] },
  trials: [],
  safety: { ready: false, state: null, lines: [] },
  parts: [],
  partsConfirmedAt: null,
});

const guidanceOf = (state: string | null) => {
  const g = state ? stateGuidance.find((x) => x.state === state) : undefined;
  return { state, fallback: !g, authority: g?.authority ?? null, steps: g ? [...g.steps] : [], note: g?.note ?? null, updatedByName: g?.updatedByName ?? null, updatedAt: g?.updatedAt ?? null };
};

/** A job that finished before digital checks were kept has one historic certificate and nothing to build a package from. */
function ensureComplianceSeeds(): void {
  if (complianceSeeded) return;
  complianceSeeded = true;
  const job = byId(jobs, 'j-5');
  const spec = job ? lockedSpecOf(byId(deals, job.dealId)?.leadId ?? '') : null;
  if (!job || !spec) return;
  const at = new Date(Date.now() - 34 * 86_400_000).toISOString();
  const state = jobStateOf(job);
  const g = guidanceOf(state);
  complianceCertificates.push({
    id: 'cc-seed-j-5',
    code: `CERT-${job.code}`,
    jobId: job.id,
    version: 1,
    driveType: spec.driveType,
    quotationCode: spec.quotationCode,
    primary: { id: certStandardFor(spec.driveType) ?? 'IS_14665' },
    basis: 'drive_type',
    additional: [],
    state,
    guidance: { state: g.state, fallback: g.fallback, authority: g.authority, steps: g.steps, note: g.note },
    package: emptyPackage(at),
    issuedAt: at,
    issuedByName: 'Prashant Vasant Wable',
    historic: true,
    isDemo: true,
  });
}

const certsOf = (jobId: string): ComplianceCertificate[] => (ensureComplianceSeeds(), complianceCertificates.filter((c) => c.jobId === jobId).sort((a, b) => b.version - a.version));
const currentCertOf = (jobId: string): ComplianceCertificate | undefined => certsOf(jobId).find((c) => !c.supersededBy);

/** What the package holds now, read from the records the checks already keep. Nothing is stored until a certificate freezes it. */
function certPackageOf(job: Job, at: string): CertificatePackage {
  const mech = mechCheckOf(job.id);
  const elec = elecCheckOf(job.id);
  ensureMaterialSeeds();
  const log = materialLogs.find((l) => l.jobId === job.id && l.status === 'confirmed');
  const pre = preInspectionViewOf(job);
  const steps = job.steps.filter((x) => !x.notApplicable);
  const last = <T,>(l: T[] | undefined): T | undefined => (l && l.length ? l[l.length - 1] : undefined);
  const trial = (id: 'trial_no_load' | 'trial_full_load') => {
    const passed = (elec.attempts[id] ?? []).filter((a) => a.verdict === 'pass').pop();
    const m = (k: string) => passed?.measures.find((x) => x.key === k)?.value ?? null;
    return { id, at: passed?.at ?? null, runs: m('runs'), loadPct: m('load_pct'), evidence: passed?.evidence.length ?? 0 };
  };
  return {
    builtAt: at,
    installation: { stepsDone: steps.filter((x) => x.status === 'complete').length, stepsTotal: steps.length, completedAt: job.completedAt ?? steps.map((x) => x.completedAt).filter((x): x is string => !!x).sort().pop() ?? null, leadName: byId(users, job.technicianId ?? '')?.name ?? null, teamCount: (job.crew ?? []).length || (job.technicianId ? 1 : 0) },
    mechanical: { signedOff: mech.signedOff ? { at: mech.signedOff.at, byName: mech.signedOff.byName } : null, items: MECH_ITEMS.map((id) => ({ id, state: itemState(mech.attempts[id]), attempts: (mech.attempts[id] ?? []).length, fails: (mech.attempts[id] ?? []).filter((a) => a.verdict === 'fail').length, evidence: last(mech.attempts[id])?.evidence.length ?? 0 })) },
    electrical: { signedOff: elec.signedOff ? { at: elec.signedOff.at, byName: elec.signedOff.byName } : null, items: ELEC_ITEMS.map((id) => ({ id, state: elecStateOf(elec.attempts[id]), attempts: (elec.attempts[id] ?? []).length, fails: (elec.attempts[id] ?? []).filter((a) => a.verdict === 'fail').length, evidence: last(elec.attempts[id])?.evidence.length ?? 0, measures: (last(elec.attempts[id])?.measures ?? []).map((m) => ({ ...m })) })) },
    trials: [trial('trial_no_load'), trial('trial_full_load')],
    safety: { ready: pre.ready, state: pre.state, lines: pre.lines.map((l) => ({ ...l })) },
    parts: (log?.uses ?? []).filter((u) => u.usedQty > 0).map((u) => ({ category: u.category, description: u.description, quantity: u.usedQty, identifiers: u.identifiers.length, substituted: u.deviation?.kind === 'substitute' })),
    partsConfirmedAt: log?.confirmedAt ?? null,
  };
}

function certReadinessOf(job: Job): { ready: boolean; problems: ReturnType<typeof certReadiness>; openRework: number } {
  const openRework = (ensureSnagSeeds(), reworkRequests).filter((r) => r.jobId === job.id && sgIsOpen(r.status) && (r.source !== 'snag' || r.severity === 'safety_critical')).length;
  const hasSpec = !!lockedSpecOf(byId(deals, job.dealId)?.leadId ?? '');
  const mechanicalSigned = !!mechCheckOf(job.id).signedOff;
  const electricalSigned = qcElectricalCleared(job.id);
  const beforeRecords = !mechanicalSigned && !electricalSigned && (job.status === 'completed' || job.status === 'handover_pending');
  const problems = certReadiness({ hasSpec, mechanicalSigned, electricalSigned, openRework, beforeRecords });
  return { ready: problems.length === 0, problems, openRework };
}

function certViewOf(c: ComplianceCertificate): ComplianceCertificateView {
  const replaced = c.supersededBy ? certsOf(c.jobId).find((x) => x.id === c.supersededBy) : undefined;
  const before = c.supersedes ? complianceCertificates.find((x) => x.id === c.supersedes) : undefined;
  return {
    id: c.id,
    code: c.code,
    version: c.version,
    status: c.supersededBy ? 'superseded' : 'current',
    driveType: c.driveType,
    quotationCode: c.quotationCode,
    primary: { ...c.primary },
    basis: c.basis,
    overrideReason: c.overrideReason ?? null,
    additional: c.additional.map((a) => ({ ...a })),
    state: c.state,
    guidance: { ...c.guidance, steps: [...c.guidance.steps] },
    package: c.package,
    issuedAt: c.issuedAt,
    issuedByName: c.issuedByName,
    historic: !!c.historic,
    supersedes: before ? { id: before.id, code: before.code } : null,
    supersededBy: replaced ? { id: replaced.id, code: replaced.code, at: replaced.issuedAt, reason: c.voidReason ?? '' } : null,
  };
}

function complianceViewOf(job: Job, viewer: 'admin' | 'inspector'): ComplianceView {
  const spec = lockedSpecOf(byId(deals, job.dealId)?.leadId ?? '');
  const readiness = certReadinessOf(job);
  const history = certsOf(job.id).map(certViewOf);
  const current = history.find((h) => h.status === 'current') ?? null;
  const state = jobStateOf(job);
  const lead = resolveLead(byId(deals, job.dealId)?.leadId ?? '');
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, address: `${job.address}${lead ? `, ${lead.city}` : ''}`, status: job.status },
    viewer,
    driveType: spec?.driveType ?? null,
    quotationCode: spec?.quotationCode ?? null,
    autoStandard: certStandardFor(spec?.driveType ?? null),
    readiness,
    package: current ? current.package : certPackageOf(job, new Date().toISOString()),
    current,
    history,
    guidance: guidanceOf(state),
    canIssue: viewer === 'admin' && !current && readiness.ready,
    canReissue: viewer === 'admin' && !!current && !current.historic,
    canEditGuidance: viewer === 'admin' && state !== null,
  };
}

function complianceActor(jobId: string, userId: string, write: boolean): { job: Job; user: User; viewer: 'admin' | 'inspector' } {
  const a = mechActor(jobId, userId);
  if (a.viewer === 'lead') throw new RepositoryError('forbidden');
  if (write && a.viewer !== 'admin') throw new RepositoryError('forbidden');
  return { job: a.job, user: a.user, viewer: a.viewer };
}

/** Jobs with both quality checks signed off, for the commitment: the certificate is Admin's to issue within a day of the later sign-off. */
function qcCertificateWaiting(): { jobId: string; readyAt: string; issued: boolean }[] {
  ensureComplianceSeeds();
  return qcMechChecks.flatMap((m) => {
    const e = qcElecChecks.find((x) => x.jobId === m.jobId);
    if (!m.signedOff || !e?.signedOff) return [];
    const readyAt = m.signedOff.at > e.signedOff.at ? m.signedOff.at : e.signedOff.at;
    return [{ jobId: m.jobId, readyAt, issued: !!currentCertOf(m.jobId) }];
  });
}

/* ============================== Defect / snag list (135) */

/** A few snags so the list is not empty: open findings on the job waiting for quality check, and a closed history on a finished one. */
function ensureSnagSeeds(): void {
  if (snagSeeded) return;
  snagSeeded = true;
  const ago = (d: number) => new Date(Date.now() - d * 86_400_000).toISOString();
  const add = (jobId: string, title: string, note: string, severity: SnagSeverity, daysBack: number, extra: Partial<ReworkRequest>): ReworkRequest | null => {
    const job = byId(jobs, jobId);
    if (!job) return null;
    snagCounter += 1;
    const at = ago(daysBack);
    const r: ReworkRequest = { id: `rw-seed-${snagCounter}`, code: `SNAG-${snagCounter}`, jobId, source: 'snag', itemId: 'manual', title, note, evidence: [], raisedByName: 'Anand Deshpande', raisedAt: at, severity, status: 'open', events: [snagEvent('raised', 'Anand Deshpande', note, at)], isDemo: true, ...extra };
    reworkRequests.push(r);
    return r;
  };
  const lead = byId(jobs, 'j-2')?.technicianId;
  const leadName = byId(users, lead ?? '')?.name;
  add('j-2', 'Scratch on the cabin’s rear panel', 'A long scratch across the lower half of the rear cabin panel, visible in normal light.', 'cosmetic', 1, {});
  const trim = add('j-2', 'Trim strip misaligned at the 2nd floor landing', 'The landing trim strip sits about 3 mm proud of the door frame along its whole length.', 'cosmetic', 1, {});
  const trim2 = add('j-2', 'Trim strip chipped at the 3rd floor landing', 'A chip out of the lower corner of the landing trim strip. Same finish as the 2nd floor strip.', 'cosmetic', 1, {});
  if (trim && trim2) {
    for (const m of [trim, trim2]) Object.assign(m, { groupId: 'grp-seed-1', groupPrimaryId: trim.id, groupNote: 'Both strips came from one damaged batch of trim: replacing the batch fixes both.' });
    trim.events.push(snagEvent('linked', 'Anand Deshpande', trim.groupNote, ago(1)));
    trim2.events.push(snagEvent('linked', 'Anand Deshpande', trim.groupNote, ago(1)));
  }
  if (lead && leadName) {
    const slow = add('j-2', 'Car door closes slower than the agreed speed', 'The car door takes about twice as long to close as the other doors on this job. It works, but it is noticeable.', 'functional', 2, { status: 'assigned', ownerId: lead, ownerName: leadName, assignedAt: ago(1) });
    if (slow) {
      slow.dueAt = new Date(new Date(slow.assignedAt as string).getTime() + REWORK_DUE.functional).toISOString();
      slow.events.push(snagEvent('assigned', 'Prashant Vasant Wable', leadName, ago(1)));
    }
  }
  const done = (title: string, note: string, severity: SnagSeverity, status: 'verified' | 'waived', daysBack: number) => {
    const r = add('j-7', title, note, severity, daysBack + 3, { status, ownerId: byId(jobs, 'j-7')?.technicianId, ownerName: byId(users, byId(jobs, 'j-7')?.technicianId ?? '')?.name });
    if (!r) return;
    if (status === 'verified') {
      Object.assign(r, { verifiedAt: ago(daysBack), verifiedByName: 'Anand Deshpande' });
      r.events.push(snagEvent('ready_for_retest', r.ownerName ?? 'Technician', 'Put right', ago(daysBack + 1)), snagEvent('verified', 'Anand Deshpande', 'Checked on site', ago(daysBack)));
    } else {
      Object.assign(r, { waiver: { by: 'Mr. Kulkarni (customer)', note: 'The customer saw it and is content to leave it as it is.', recordedByName: 'Anand Deshpande', at: ago(daysBack) } });
      r.events.push(snagEvent('waived', 'Anand Deshpande', 'The customer is content to leave it as it is.', ago(daysBack)));
    }
  };
  done('Uneven gap on the car door panel', 'The gap between the door panels is wider at the top than at the bottom.', 'functional', 'verified', 6);
  done('Small paint mark near the call button', 'A dab of paint on the landing wall beside the call button.', 'cosmetic', 'verified', 5);
  done('Faint ripple in the cabin floor finish', 'A faint ripple in the finish, only visible at a low angle.', 'cosmetic', 'waived', 5);
}

type SnagRole = 'admin' | 'inspector' | 'owner' | 'lead' | 'crew';

/** What this person is to this snag's job: Admin, the assigned QC inspector, the person fixing it, or someone else on the job. */
function snagRoleOf(job: Job, snag: ReworkRequest | null, userId: string): SnagRole | null {
  const u = byId(users, userId);
  if (!u) return null;
  if (u.role === 'admin') return 'admin';
  if (u.role !== 'technician') return null;
  if (qcOf(job.id)?.inspectorId === userId) return 'inspector';
  if (snag?.ownerId === userId) return 'owner';
  if (leadIdsOf(job).includes(userId)) return 'lead';
  if (isOnJob(job, userId)) return 'crew';
  return null;
}

function snagRowOf(r: ReworkRequest, now: number): SnagRowView {
  const job = byId(jobs, r.jobId) as Job;
  const pausedForQc = r.status === 'ready_for_retest' || r.status === 'disputed';
  return {
    id: r.id,
    code: r.code,
    jobId: r.jobId,
    jobCode: job.code,
    siteName: job.siteName,
    source: r.source,
    itemId: r.itemId,
    itemLabelKey: r.source === 'qc_mechanical' ? `qcMech.item.${r.itemId}` : r.source === 'qc_electrical' ? `qcElec.item.${r.itemId}` : null,
    title: r.title ?? null,
    severity: r.severity,
    status: r.status,
    ownerId: r.ownerId ?? null,
    ownerName: r.ownerName ?? null,
    dueAt: r.dueAt ?? null,
    overdue: !!r.dueAt && sgIsOpen(r.status) && !pausedForQc && new Date(r.dueAt).getTime() < now,
    raisedAt: r.raisedAt,
    raisedByName: r.raisedByName,
    evidenceCount: r.evidence.length,
    groupSize: r.groupId ? reworkRequests.filter((x) => x.groupId === r.groupId).length : 1,
    blocking: sgBlocks(r),
  };
}

function snagDetailOf(r: ReworkRequest, userId: string, now: number): SnagDetailView {
  const job = byId(jobs, r.jobId) as Job;
  const role = snagRoleOf(job, r, userId);
  const open = sgIsOpen(r.status);
  const qc = role === 'admin' || role === 'inspector';
  const via = r.resolvedVia ? byId(reworkRequests, r.resolvedVia) : undefined;
  const decisions: DisputeDecision[] = r.source === 'snag' && r.severity !== 'safety_critical' ? ['finding_stands', 'retest_ordered', 'finding_withdrawn'] : ['finding_stands', 'retest_ordered'];
  return {
    ...snagRowOf(r, now),
    note: r.note,
    evidence: r.evidence.map((e) => ({ id: e.id, kind: e.kind, previewUrl: e.previewUrl, ...(e.mediaUrl ? { mediaUrl: e.mediaUrl } : {}), capturedAt: e.capturedAt })),
    events: r.events.map((e) => ({ ...e })),
    group: r.groupId ? reworkRequests.filter((x) => x.groupId === r.groupId).map((x) => ({ id: x.id, code: x.code, title: x.title ?? null, status: x.status, primary: x.id === x.groupPrimaryId })) : [],
    groupNote: r.groupNote ?? null,
    dispute: r.dispute ? { ...r.dispute, ...(r.dispute.decision ? { decision: { ...r.dispute.decision } } : {}) } : null,
    waiver: r.waiver ? { ...r.waiver } : null,
    verifiedAt: r.verifiedAt ?? null,
    verifiedByName: r.verifiedByName ?? null,
    resolvedVia: via ? { id: via.id, code: via.code } : null,
    recheckRoute: r.source === 'qc_mechanical' ? `/qc-mechanical/${r.jobId}` : r.source === 'qc_electrical' ? `/qc-electrical/${r.jobId}` : null,
    actions: {
      assign: role === 'admin' && open && (r.status === 'open' || r.status === 'assigned' || r.status === 'in_progress'),
      regrade: role === 'admin' && open,
      link: qc && open && r.source === 'snag' && r.status !== 'disputed',
      dispute: (role === 'owner' || role === 'lead') && open && r.status !== 'disputed',
      decide: role === 'admin' && r.status === 'disputed',
      waive: qc && open && r.severity === 'cosmetic' && r.status !== 'disputed',
      verify: qc && r.source === 'snag' && r.status === 'ready_for_retest' && r.fixedById !== userId,
      decisions,
    },
  };
}

/** Everything the list shows this person: Admin everything, a technician the snags on jobs they inspect, lead or work on. */
function snagsVisibleTo(userId: string): ReworkRequest[] {
  ensureSnagSeeds();
  return reworkRequests.filter((r) => {
    const job = byId(jobs, r.jobId);
    return !!job && snagRoleOf(job, r, userId) !== null;
  });
}

function snagBoardOf(userId: string, jobId: string | undefined, now: number): SnagBoardView {
  const user = byId(users, userId);
  if (!user || (user.role !== 'admin' && user.role !== 'technician')) throw new RepositoryError('forbidden');
  let visible = snagsVisibleTo(userId);
  if (jobId) {
    const job = byId(jobs, jobId);
    if (!job) throw new RepositoryError('not_found');
    if (snagRoleOf(job, null, userId) === null && !visible.some((r) => r.jobId === jobId)) throw new RepositoryError('forbidden');
    visible = visible.filter((r) => r.jobId === jobId);
  }
  const rank = (r: ReworkRequest) => (sgIsOpen(r.status) ? 0 : 1);
  const rows = [...visible].sort((a, b) => rank(a) - rank(b) || sgRank(a.severity) - sgRank(b.severity) || b.raisedAt.localeCompare(a.raisedAt)).map((r) => snagRowOf(r, now));
  const jobIds = new Set(visible.map((r) => r.jobId));
  for (const j of jobs) {
    if ((j.status === 'qc_pending' || j.status === 'handover_pending') && (user.role === 'admin' || qcOf(j.id)?.inspectorId === userId) && (!jobId || j.id === jobId)) jobIds.add(j.id);
  }
  return {
    viewer: user.role === 'admin' ? 'admin' : jobs.some((j) => qcOf(j.id)?.inspectorId === userId) ? 'inspector' : 'technician',
    rows,
    totals: { open: rows.filter((r) => sgIsOpen(r.status)).length, blocking: rows.filter((r) => r.blocking).length, pendingVerification: rows.filter((r) => r.status === 'ready_for_retest').length, disputed: rows.filter((r) => r.status === 'disputed').length, closed: rows.filter((r) => !sgIsOpen(r.status)).length },
    jobs: [...jobIds].flatMap((id) => {
      const j = byId(jobs, id);
      if (!j) return [];
      const mine = rows.filter((r) => r.jobId === id);
      const role = snagRoleOf(j, null, userId);
      return [{ id: j.id, code: j.code, siteName: j.siteName, status: j.status, open: mine.filter((r) => sgIsOpen(r.status)).length, blocking: mine.filter((r) => r.blocking).length, canAdd: (role === 'admin' || role === 'inspector') && (j.status === 'qc_pending' || j.status === 'handover_pending') }];
    }),
    technicians: user.role === 'admin' ? users.filter((u) => u.role === 'technician' && u.status === 'active').map((u) => ({ id: u.id, name: u.name })) : [],
  };
}

function snagOf(snagId: string, userId: string, need: 'read' | 'qc' | 'admin'): { r: ReworkRequest; job: Job; user: User; role: SnagRole } {
  ensureSnagSeeds();
  const r = byId(reworkRequests, snagId);
  const user = byId(users, userId);
  if (!r) throw new RepositoryError('not_found');
  if (!user) throw new RepositoryError('forbidden');
  const job = byId(jobs, r.jobId) as Job;
  const role = snagRoleOf(job, r, userId);
  if (!role) throw new RepositoryError('forbidden');
  if (need === 'admin' && role !== 'admin') throw new RepositoryError('forbidden');
  if (need === 'qc' && role !== 'admin' && role !== 'inspector') throw new RepositoryError('forbidden');
  return { r, job, user, role };
}

/** Safety-critical findings raised on the list are an alert until they are put right; checklist ones already have theirs. */
function syncSnagAlerts(now: number): void {
  const at = new Date(now).toISOString();
  const live = new Set<string>();
  for (const r of reworkRequests) {
    if (r.source === 'qc_electrical' || !sgBlocks(r)) continue;
    const job = byId(jobs, r.jobId);
    if (!job) continue;
    const key = `snag:${r.id}`;
    live.add(key);
    if (!alerts.some((a) => a.relatedId === key && a.status !== 'resolved')) raiseAlert({ titleKey: 'snagList.alert.safety', context: `${job.code} · ${job.siteName}: ${r.title ?? r.code}`, severity: 'high', category: 'safety', relatedId: key, sourceRoute: `/snags/${r.jobId}?snag=${r.id}`, location: job.location });
  }
  for (const a of alerts) if (a.relatedId?.startsWith('snag:') && a.status !== 'resolved' && !live.has(a.relatedId)) patchInPlace(alerts, a.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'Put right.' });
}

/** Whether anything on this job stops handover: the one answer the handover screens read. */
const snagBlockingOf = (jobId: string): number => (ensureSnagSeeds(), reworkRequests).filter((r) => r.jobId === jobId && sgBlocks(r)).length;

/* ============================== Rework assignment (136) */

const reworkOf = (r: ReworkRequest) => r.rework ?? (r.rework = { rounds: [], parts: [], scope: [] });
/** A snag linked to others is put right once, at its root: the whole open group moves together. */
const reworkGroupOf = (r: ReworkRequest): ReworkRequest[] => (r.groupId ? reworkRequests.filter((x) => x.groupId === r.groupId && sgIsOpen(x.status) && x.status !== 'disputed') : [r]);

function reworkViewOf(r: ReworkRequest, userId: string, now: number): ReworkView {
  const job = byId(jobs, r.jobId) as Job;
  const detail = snagDetailOf(r, userId, now);
  const role: SnagRole = snagRoleOf(job, r, userId) ?? 'crew';
  const rw = r.rework ?? { rounds: [], parts: [], scope: [] };
  const roundView = (x: ReworkRound): ReworkRoundView => ({ n: x.n, startedAt: x.startedAt, startedByName: x.startedByName, completedAt: x.completedAt ?? null, notes: x.notes ?? null, evidence: x.evidence.map((e) => ({ id: e.id, kind: e.kind, previewUrl: e.previewUrl, ...(e.mediaUrl ? { mediaUrl: e.mediaUrl } : {}), capturedAt: e.capturedAt })) });
  const rounds = rw.rounds.map(roundView);
  const working = r.status === 'assigned' || r.status === 'in_progress';
  const isOwner = role === 'owner';
  return {
    snag: detail,
    job: { id: job.id, code: job.code, siteName: job.siteName, address: job.address, location: job.location, status: job.status },
    viewer: role === 'crew' ? 'crew' : role,
    urgency: rwUrgency(r.severity),
    rounds,
    currentRound: rounds.find((x) => !x.completedAt) ?? null,
    parts: rw.parts.map((p): ReworkPartView => {
      const po = p.poId ? byId(supplierPurchaseOrders, p.poId) : undefined;
      const line = po?.lineItems?.[0];
      return { id: p.id, description: p.description, quantity: p.quantity, note: p.note ?? null, requestedByName: p.requestedByName, requestedAt: p.requestedAt, status: rwPartStatus(p, po ? { status: po.status, lineDelivered: line?.fulfilmentStage === 'delivered' || !!po.receivedAt, lineShipped: line?.fulfilmentStage === 'shipped' } : null), poCode: po?.code ?? null, orderedByName: p.orderedByName ?? null };
    }),
    scope: rw.scope.map((x) => ({ ...x })),
    technicians: role === 'admin' ? users.filter((u) => u.role === 'technician' && u.status === 'active').map((u) => ({ id: u.id, name: u.name, openRework: reworkRequests.filter((x) => x.ownerId === u.id && (x.status === 'assigned' || x.status === 'in_progress')).length })) : [],
    actions: {
      assign: role === 'admin' && r.status === 'open' && !r.ownerId,
      reassign: role === 'admin' && working && !!r.ownerId,
      start: isOwner && r.status === 'assigned',
      complete: isOwner && r.status === 'in_progress',
      handBack: isOwner && working,
      escalate: (isOwner || role === 'admin') && sgIsOpen(r.status) && r.status !== 'disputed' && r.status !== 'ready_for_retest',
      requestPart: isOwner && working,
      orderPart: role === 'admin' && rw.parts.some((p) => !p.poId),
    },
  };
}

function reworkOwnerOf(snagId: string, userId: string): { r: ReworkRequest; user: User } {
  const { r, user, role } = snagOf(snagId, userId, 'read');
  if (role !== 'owner') throw new RepositoryError('not_owner');
  return { r, user };
}

/** What Admin can order for a rework: a live listing of a supplier that can be sent an order now, one per supplier and category. */
function reworkPartOptions(): ReworkPartOption[] {
  const out: ReworkPartOption[] = [];
  for (const supplier of suppliers) {
    if (!isSupplierEligibleForPO(supplier) || !canIssueNewPo(agreementStateFor(supplier.id).status)) continue;
    for (const category of new Set(supplierCatalogItems.filter((c) => c.supplierId === supplier.id && c.status === 'active').map((c) => c.category))) {
      const item = liveCatalogItemFor(supplier.id, category);
      if (item) out.push({ itemId: item.id, supplierId: supplier.id, supplierName: supplier.name, category, description: item.description, unitPrice: item.unitPrice, leadTimeDays: item.leadTimeDays });
    }
  }
  return out.sort((a, b) => a.category.localeCompare(b.category) || a.unitPrice - b.unitPrice);
}

/* ============================== Final handover checklist (137) */

const handoverRecords: HandoverReadiness[] = [];
const handoverRecordOf = (jobId: string): HandoverReadiness => {
  let r = handoverRecords.find((x) => x.jobId === jobId);
  if (!r) {
    r = { jobId, docs: {}, issues: [], corrections: [], confirmations: [], isDemo: true };
    handoverRecords.push(r);
  }
  return r;
};

/** What the customer's package is now: the accepted configuration, the as-installed parts log and the AMC pricing in force. */
function handoverBasisOf(job: Job): HoDocBasis | null {
  const spec = lockedSpecOf(byId(deals, job.dealId)?.leadId ?? '');
  if (!spec) return null;
  ensureMaterialSeeds();
  const log = materialLogs.find((l) => l.jobId === job.id && l.status === 'confirmed');
  return { quotationCode: spec.quotationCode, version: spec.version, finishTier: spec.finishTier, driveType: spec.driveType, materialsConfirmedAt: log?.confirmedAt ?? null, pricingUpdatedAt: pricingConfig.updatedAt };
}

function handoverGateOf(job: Job) {
  ensureSnagSeeds();
  const rec = handoverRecordOf(job.id);
  const basis = handoverBasisOf(job);
  const mech = mechCheckOf(job.id).signedOff;
  const elec = elecCheckOf(job.id).signedOff;
  const cert = currentCertOf(job.id);
  const mine = reworkRequests.filter((r) => r.jobId === job.id);
  const open = mine.filter((r) => sgIsOpen(r.status));
  const docs: HandoverDocView[] = HO_DOC_KINDS.map((kind) => {
    const confirmed = rec.docs[kind] ?? null;
    const block = hoBlockOf(kind, { hasSpec: !!basis, materialsConfirmed: !!basis?.materialsConfirmedAt, amcTiers: pricingConfig.amcTiers.length });
    const issues = rec.issues.filter((i) => i.kind === kind);
    const state = basis ? hoDocState({ block, confirmed, openIssue: issues.some((i) => !i.resolvedAt), now: basis, kind }) : 'blocked';
    return {
      kind,
      state,
      blockedBy: block,
      current: basis,
      confirmedAt: confirmed?.confirmedAt ?? null,
      confirmedByName: confirmed?.confirmedByName ?? null,
      issues: issues.map((i) => ({ id: i.id, text: i.text, raisedByName: i.raisedByName, at: i.at, resolvedAt: i.resolvedAt ?? null, resolvedByName: i.resolvedByName ?? null, resolution: i.resolution ?? null })),
      corrections: rec.corrections.filter((c) => c.kind === kind).map((c) => ({ id: c.id, note: c.note, byName: c.byName, at: c.at })),
    };
  });
  const reviewOpen = !!rec.adminReview && !rec.adminReview.completedAt;
  const problems = hoReadiness({ checksSigned: !!mech && !!elec, openSnags: open.length, certificateIssued: !!cert && !cert.historic, docStates: docs.map((d) => d.state), reviewOpen });
  const last = rec.confirmations[rec.confirmations.length - 1];
  // Jobs that finished before this gate existed have nothing to confirm: they are simply past it.
  const legacy = (job.status === 'handover_pending' || job.status === 'completed') && rec.confirmations.length === 0;
  // A confirmation only stands while nothing has come up since: a new snag, a documentation issue, a reissued certificate or an added review
  // needs a fresh Ready for Handover, even if it has already been put right.
  const cameUp = last ? [...mine.map((r) => r.raisedAt), ...rec.issues.map((i) => i.at), rec.adminReview?.addedAt, cert?.issuedAt].some((t) => !!t && t > last.at) : false;
  const status: HandoverChecklistView['status'] = legacy ? 'confirmed' : last && problems.length === 0 && !cameUp && job.status !== 'qc_pending' ? 'confirmed' : last ? 'reopened' : problems.length === 0 ? 'ready' : 'blocked';
  // The time everything became clear, for the commitment: the latest thing that had to be done.
  const stamps = [cert?.issuedAt, mech?.at, elec?.at, rec.adminReview?.completedAt, ...Object.values(rec.docs).map((d) => d?.confirmedAt), ...rec.issues.map((i) => i.resolvedAt), ...mine.map((r) => r.verifiedAt ?? r.waiver?.at)].filter((x): x is string => !!x).sort();
  return { rec, basis, mech, elec, cert, mine, open, docs, reviewOpen, problems, last, legacy, status, clearAt: stamps[stamps.length - 1] ?? null };
}

function handoverViewOf(job: Job, viewer: 'admin' | 'inspector'): HandoverChecklistView {
  const g = handoverGateOf(job);
  const count = (sv: string) => g.open.filter((r) => r.severity === sv).length;
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, address: job.address, status: job.status },
    viewer,
    checks: { mechanical: g.mech ? { at: g.mech.at, byName: g.mech.byName } : null, electrical: g.elec ? { at: g.elec.at, byName: g.elec.byName } : null },
    snags: { open: g.open.length, safetyCritical: count('safety_critical'), functional: count('functional'), cosmetic: count('cosmetic'), pendingVerification: g.open.filter((r) => r.status === 'ready_for_retest').length, disputed: g.open.filter((r) => r.status === 'disputed').length, resolved: g.mine.filter((r) => r.status === 'verified' || r.status === 'withdrawn').length, waived: g.mine.filter((r) => r.status === 'waived').length },
    certificate: g.cert ? { code: g.cert.code, version: g.cert.version, issuedAt: g.cert.issuedAt, historic: !!g.cert.historic } : null,
    docs: g.docs,
    adminReview: g.rec.adminReview ? { ...g.rec.adminReview } : null,
    readiness: { ready: g.problems.length === 0, problems: g.problems },
    status: g.status,
    confirmed: g.last && g.status === 'confirmed' ? { at: g.last.at, byName: g.last.byName } : null,
    history: g.rec.confirmations.map((c) => ({ at: c.at, byName: c.byName })),
    canConfirm: g.problems.length === 0 && (job.status === 'qc_pending' || g.status === 'reopened') && !g.legacy,
    canEditDocs: job.status === 'qc_pending' || job.status === 'handover_pending',
    canRequestReview: viewer === 'admin' && !g.rec.adminReview && !g.last && job.status === 'qc_pending',
    canCompleteReview: viewer === 'admin' && g.reviewOpen,
  };
}

function handoverActor(jobId: string, userId: string): { job: Job; user: User; viewer: 'admin' | 'inspector'; assignment: QcAssignment | undefined } {
  const a = mechActor(jobId, userId);
  if (a.viewer === 'lead') throw new RepositoryError('forbidden');
  return { job: a.job, user: a.user, viewer: a.viewer, assignment: a.assignment };
}

/** The structural unlock for the customer walkthrough (138): Ready for Handover was said and nothing has come up since, or the job was past the gate before it existed. */
const handoverUnlocked = (jobId: string): boolean => {
  const job = byId(jobs, jobId);
  if (!job) return false;
  const g = handoverGateOf(job);
  return g.status === 'confirmed';
};

/** Jobs whose gate is clear but not yet confirmed, and admin reviews waiting: what the commitments read. */
function handoverSignals(): { waiting: { jobId: string; readyAt: string; ownerId: string | null; confirmed: boolean }[]; reviews: { jobId: string; addedAt: string; reason: string; done: boolean; doneAt?: string }[] } {
  ensureComplianceSeeds();
  const waiting: { jobId: string; readyAt: string; ownerId: string | null; confirmed: boolean }[] = [];
  const reviews: { jobId: string; addedAt: string; reason: string; done: boolean; doneAt?: string }[] = [];
  for (const job of jobs) {
    if (job.status !== 'qc_pending' && job.status !== 'handover_pending') continue;
    const g = handoverGateOf(job);
    if (g.legacy) continue;
    if (g.problems.length === 0 || g.last) waiting.push({ jobId: job.id, readyAt: g.clearAt ?? new Date().toISOString(), ownerId: qcOf(job.id)?.inspectorId ?? null, confirmed: g.status === 'confirmed' });
    if (g.rec.adminReview) reviews.push({ jobId: job.id, addedAt: g.rec.adminReview.addedAt, reason: g.rec.adminReview.reason, done: !!g.rec.adminReview.completedAt, ...(g.rec.adminReview.completedAt ? { doneAt: g.rec.adminReview.completedAt } : {}) });
  }
  return { waiting, reviews };
}

/* ============================== Customer handover walkthrough (138) */

const walkthroughs: HandoverWalkthrough[] = [];
let walkthroughCounter = 100;
const walkthroughOf = (jobId: string): HandoverWalkthrough => {
  let w = walkthroughs.find((x) => x.jobId === jobId);
  if (!w) {
    w = { jobId, script: {}, documents: {}, followUps: [], events: [], isDemo: true };
    walkthroughs.push(w);
  }
  return w;
};
const wtEvent = (w: HandoverWalkthrough, kind: string, byName: string, note?: string) => {
  walkthroughCounter += 1;
  w.events.push({ id: `wte-${walkthroughCounter}`, at: new Date().toISOString(), kind, byName, ...(note?.trim() ? { note: note.trim() } : {}) });
};

type WtRole = 'admin' | 'conductor' | 'customer';
function walkthroughActor(jobId: string, userId: string): { job: Job; user: User; role: WtRole } {
  const user = byId(users, userId);
  const job = byId(jobs, jobId);
  if (!user) throw new RepositoryError('forbidden');
  if (!job) throw new RepositoryError('not_found');
  if (user.role === 'admin') return { job, user, role: 'admin' };
  if (user.role === 'customer' && byId(deals, job.dealId)?.customerId === user.id) return { job, user, role: 'customer' };
  if (user.role === 'technician' && (isOnJob(job, userId) || qcOf(job.id)?.inspectorId === userId)) return { job, user, role: 'conductor' };
  throw new RepositoryError('forbidden');
}

const walkthroughStatusOf = (job: Job, w: HandoverWalkthrough): WalkthroughView['status'] =>
  !handoverUnlocked(job.id) ? 'locked' : w.signoff ? 'signed_off' : w.conducted ? 'conducted' : w.mode && w.conductorId ? 'arranged' : 'not_started';

function walkthroughViewOf(job: Job, role: WtRole): WalkthroughView {
  const w = walkthroughOf(job.id);
  const status = walkthroughStatusOf(job, w);
  const unlocked = status !== 'locked';
  const customerId = byId(deals, job.dealId)?.customerId;
  const gate = handoverGateOf(job);
  const powerBackup = !!sopSpecOf(job)?.powerBackup;
  const items = wtScriptFor(powerBackup);
  const script = items.map((i) => ({ id: i.id, group: i.group, mandatory: i.mandatory, done: w.script[i.id] ? { ...w.script[i.id] } : null }));
  const documents = WT_DOCS.map((kind) => ({ kind, ready: kind === 'emergency_contacts' ? true : gate.docs.find((d) => d.kind === kind)?.state === 'ready', provided: w.documents[kind] ? { ...w.documents[kind]! } : null }));
  const staff = role !== 'customer';
  const open = !w.conducted;
  const scriptOpen = script.filter((i) => i.mandatory && !i.done).length;
  const docsOpen = documents.filter((d) => !d.provided).length;
  const conductorPool = [...users.filter((u) => u.role === 'admin' && u.status === 'active'), ...users.filter((u) => u.role === 'technician' && u.status === 'active' && isOnJob(job, u.id))];
  const signoffDue = w.conducted && !w.signoff ? new Date(new Date(w.conducted.at).getTime() + (w.mode === 'in_person' ? WT_SIGNOFF_PRESENT : WT_SIGNOFF_REMOTE)).toISOString() : null;
  const canSignOnDevice = staff && status === 'conducted' && w.mode === 'in_person';
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, address: job.address, status: job.status },
    viewer: role,
    customerName: customerId ? (byId(users, customerId)?.name ?? '') : '',
    status,
    mode: w.mode ?? null,
    scheduledFor: w.scheduledFor ? { ...w.scheduledFor } : null,
    conductor: w.conductorId ? { id: w.conductorId, name: w.conductorName ?? '' } : null,
    representative: w.representative ? { ...w.representative } : null,
    script,
    documents,
    conducted: w.conducted ? { ...w.conducted } : null,
    signoff: w.signoff ? { at: w.signoff.at, signerName: w.signoff.signerName, mode: w.signoff.mode, recordedByName: w.signoff.recordedByName, note: w.signoff.note ?? null, signature: staff ? (w.signoff.signature ?? null) : null } : null,
    signoffDue,
    amc: w.amc ? { ...w.amc } : null,
    amcTiers: pricingConfig.amcTiers.map((t) => ({ ...t })),
    feedback: w.feedback ? { ...w.feedback } : null,
    negativeSignal: staff && !!w.feedback && wtIsNegative(w.feedback.score),
    followUps: w.followUps.map((f) => ({ ...f, ...(f.answer ? { answer: { ...f.answer } } : {}) })),
    events: staff ? w.events.map((e) => ({ ...e })) : [],
    conductors: staff ? conductorPool.map((u) => ({ id: u.id, name: u.name })) : [],
    actions: {
      arrange: staff && unlocked && open,
      tick: staff && unlocked && open && !!w.mode,
      provide: staff && unlocked && open && !!w.mode,
      conduct: staff && unlocked && open && !!w.mode && !!w.conductorId,
      sign: role === 'customer' && status === 'conducted',
      signOnDevice: canSignOnDevice,
      amc: unlocked && !!w.conducted,
      feedback: unlocked && !!w.signoff && !w.feedback && (role === 'customer' || w.signoff.mode === 'on_device'),
      ask: unlocked,
      answer: role === 'admin' && w.followUps.some((f) => !f.answer),
    },
    conductProblem: wtConductProblem({ arranged: !!w.mode && !!w.conductorId, scriptOpen, docsOpen }),
  };
}

/** What the commitments read: who owes the next step of each handover walkthrough. */
function walkthroughSignals(): { jobId: string; unlockedAt: string; leadId: string | null; customerId: string | null; w: HandoverWalkthrough }[] {
  return jobs
    .filter((j) => (j.status === 'handover_pending' || j.status === 'completed') && handoverUnlocked(j.id) && handoverRecordOf(j.id).confirmations.length > 0)
    .map((j) => ({ jobId: j.id, unlockedAt: handoverRecordOf(j.id).confirmations[handoverRecordOf(j.id).confirmations.length - 1].at, leadId: j.technicianId ?? null, customerId: byId(deals, j.dealId)?.customerId ?? null, w: walkthroughOf(j.id) }));
}

/* ============================== Warranty & AMC registration (139) */

const warrantyRegistrations: WarrantyRegistration[] = [];
let warrantyCounter = 100;

type WrRole = 'admin' | 'customer';
function warrantyActor(jobId: string, userId: string): { job: Job; user: User; role: WrRole } {
  const user = byId(users, userId);
  const job = byId(jobs, jobId);
  if (!user) throw new RepositoryError('forbidden');
  if (!job) throw new RepositoryError('not_found');
  if (user.role === 'admin') return { job, user, role: 'admin' };
  if (user.role === 'customer' && byId(deals, job.dealId)?.customerId === user.id) return { job, user, role: 'customer' };
  throw new RepositoryError('forbidden');
}

const registrationOf = (jobId: string) => warrantyRegistrations.find((r) => r.jobId === jobId);
const handoverDayOf = (job: Job): string | null => {
  const c = walkthroughOf(job.id).conducted;
  return c && handoverUnlocked(job.id) ? qcDay(new Date(c.at).getTime()) : null;
};

/** The manufacturer's warranty on each part actually installed, read from the agreement it was bought under; the service warranty is AIEC's own. */
function warrantyTermsOf(job: Job, startsOn: string): WarrantyRegistration['terms'] | null {
  const basis = handoverBasisOf(job);
  if (!basis) return null;
  ensureMaterialSeeds();
  const log = materialLogs.find((l) => l.jobId === job.id && l.status === 'confirmed');
  const parts = (log?.uses ?? [])
    .filter((u) => u.usedQty > 0)
    .map((u) => {
      const po = u.poCode ? supplierPurchaseOrders.find((p) => p.code === u.poCode) : undefined;
      const supplierId = u.supplierId ?? po?.supplierId;
      const fromPo = po?.agreementTerms ? byId(supplierAgreementVersions, po.agreementTerms.agreementVersionId)?.terms.warrantyMonths : undefined;
      const months = fromPo ?? (supplierId ? versionInForce(versionsOf(supplierAgreementVersions, supplierId), Date.now())?.terms.warrantyMonths : undefined) ?? null;
      return { category: u.category, description: u.description, quantity: u.usedQty, substituted: u.deviation?.kind === 'substitute', supplierName: supplierId ? (byId(suppliers, supplierId)?.name ?? null) : null, poCode: u.poCode ?? null, months, endsOn: months !== null ? wrEndOfTerm(startsOn, months) : null };
    });
  return { basis: { quotationCode: basis.quotationCode, version: basis.version, finishTier: basis.finishTier, driveType: basis.driveType, materialsConfirmedAt: basis.materialsConfirmedAt }, parts, service: { months: WR_SERVICE_MONTHS, endsOn: wrEndOfTerm(startsOn, WR_SERVICE_MONTHS) } };
}

const amcTiersView = () => pricingConfig.amcTiers.map((t) => ({ tier: t.tier, annualPrice: t.annualPrice, responseTimeHours: t.responseTimeHours, includedVisits: WR_VISITS[t.tier] }));

function warrantyViewOf(job: Job, role: WrRole, now: number): WarrantyView {
  const reg = registrationOf(job.id);
  const startsOn = reg?.startsOn ?? handoverDayOf(job);
  const terms = reg ? reg.terms : startsOn ? warrantyTermsOf(job, startsOn) : null;
  const customerId = byId(deals, job.dealId)?.customerId;
  const amcBegins = terms ? wrAddDays(terms.service.endsOn, 1) : null;
  const amc = reg?.amc ? { ...reg.amc, terms: reg.amc.terms.map((t) => ({ ...t })), begins: amcBegins ?? '' } : null;
  const last = reg?.amc?.terms[reg.amc.terms.length - 1];
  const renewFrom = reg?.amc?.status === 'active' && last ? wrAddDays(last.endsOn, -WR_RENEW_DAYS[0]) : null;
  const today = qcDay(now);
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, address: job.address, status: job.status },
    viewer: role,
    customerName: customerId ? (byId(users, customerId)?.name ?? '') : '',
    status: reg ? 'registered' : startsOn && terms ? 'ready' : 'not_ready',
    startsOn,
    terms: terms ? { basis: { ...terms.basis }, parts: terms.parts.map((p) => ({ ...p })), service: { ...terms.service } } : null,
    frozen: !!reg,
    amcTiers: amcTiersView(),
    walkthroughAmc: walkthroughOf(job.id).amc ? { ...walkthroughOf(job.id).amc! } : null,
    registration: reg ? { registeredAt: reg.registeredAt, registeredByName: reg.registeredByName, registeredByRole: reg.registeredByRole } : null,
    amc,
    amcBegins,
    reminders: (reg?.reminders ?? []).map((r) => ({ id: r.id, kind: r.kind, dueAt: r.dueAt, sentAt: r.sentAt ?? null, skipped: r.skipped ?? null })),
    actions: {
      register: !reg && !!startsOn && !!terms,
      enrol: !!reg && reg.amc?.status !== 'active',
      customize: role === 'admin',
      renew: !!reg && reg.amc?.status === 'active' && !!renewFrom && today >= renewFrom,
    },
    renewFrom,
  };
}

function buildAmc(input: { tier: WrTierId; extraVisits: number; note?: string }, serviceEnd: string, by: string, at: string): NonNullable<WarrantyRegistration['amc']> {
  const tier = pricingConfig.amcTiers.find((t) => t.tier === input.tier)!;
  const start = wrAddDays(serviceEnd, 1);
  const price = wrAmcPrice(tier, input.tier, input.extraVisits);
  return { status: 'active', tier: input.tier, annualPrice: tier.annualPrice, responseTimeHours: tier.responseTimeHours, includedVisits: WR_VISITS[input.tier], extraVisits: input.extraVisits, ...(input.note?.trim() ? { note: input.note.trim() } : {}), decidedAt: at, decidedByName: by, terms: [{ n: 1, startsOn: start, endsOn: wrEndOfTerm(start, 12), price, addedByName: by, at }] };
}

function planReminders(reg: WarrantyRegistration): void {
  const existing = new Set(reg.reminders.filter((r) => !r.skipped).map((r) => `${r.kind}:${r.dueAt}`));
  const last = reg.amc?.terms[reg.amc.terms.length - 1];
  for (const d of wrReminderPlan({ registeredAt: reg.registeredAt, serviceEnd: reg.terms.service.endsOn, amc: reg.amc ? { status: reg.amc.status, ...(last ? { endsOn: last.endsOn } : {}) } : null })) {
    if (existing.has(`${d.kind}:${d.dueAt}`)) continue;
    warrantyCounter += 1;
    reg.reminders.push({ id: `wrm-${warrantyCounter}`, kind: d.kind, dueAt: d.dueAt });
  }
}

/** Says something to the customer through the Communication Engine, in their language, unless they opted out. One message per reminder, ever. */
function syncWarrantyReminders(now: number): void {
  const at = new Date(now).toISOString();
  for (const reg of warrantyRegistrations) {
    const job = byId(jobs, reg.jobId);
    const lead = job ? resolveLead(byId(deals, job.dealId)?.leadId ?? '') : null;
    for (const r of reg.reminders) {
      if (r.sentAt || r.skipped || r.dueAt > at) continue;
      const active = reg.amc?.status === 'active';
      if (r.kind !== 'amc_renewal' && active) {
        r.skipped = 'enrolled';
        continue;
      }
      if (!job || !lead) {
        r.skipped = 'no_contact';
        continue;
      }
      const groupId = r.kind === 'amc_renewal' ? 'tpl-amc-renewal' : r.kind === 'warranty_ending' ? 'tpl-warranty-ending' : 'tpl-amc-reconsider';
      const language = lead.preferredLanguage ?? 'en';
      const template = templateInGroup(groupId, language) ?? templateInGroup(groupId, 'en');
      if (!template) continue;
      if (isOptedOutSync(lead.contactPhone, template.channel)) {
        r.skipped = 'opted_out';
        continue;
      }
      const endDate = r.kind === 'amc_renewal' ? (reg.amc?.terms[reg.amc.terms.length - 1]?.endsOn ?? '') : reg.terms.service.endsOn;
      const body = renderTemplateBody(template.body, { customerName: lead.contactName, buildingName: lead.siteName, endDate: endDate ? formatDate(`${endDate}T12:00:00Z`, language) : '' });
      let conversation = conversations.find((c) => c.leadId === lead.id) ?? null;
      if (!conversation) {
        conversationCounter += 1;
        conversation = { id: `conv-new-${conversationCounter}`, leadId: lead.id, lastMessageAt: at, isDemo: true };
        conversations.push(conversation);
      }
      messageCounter += 1;
      commMessages.push({ id: `cm-new-${messageCounter}`, conversationId: conversation.id, channel: template.channel, sender: 'bot', body, templateGroupId: groupId, status: 'sent', at, handled: true });
      patchInPlace(conversations, conversation.id, { lastMessageAt: at });
      r.sentAt = at;
      logAutomatedAction({ sourceKey: 'warranty.reminder', triggeringCondition: `${r.kind.replace('_', ' ')} for ${job.code} came due`, actionTaken: `Messaged ${lead.contactName} on ${template.channel}`, affectedRecordId: job.id, affectedRecordType: 'other', subjectLabel: job.code });
    }
  }
}

/** Who finished a step. Steps finished before names were kept have none: on a job with no assistants they were the lead's. */
function stepFinisherName(job: Job, st: Job['steps'][number]): string | null {
  if (st.completedByName) return st.completedByName;
  if (st.status !== 'complete' || !job.technicianId) return null;
  const alone = !(job.crew ?? []).some((c) => c.role === 'assistant');
  return alone ? nameOf(job.technicianId) : null;
}

/* ============================== Recruitment: the applicant's full details (142) */

const partnerApplications: PartnerApplication[] = seedPartnerApplications.map((a) => ({ ...a, form: JSON.parse(JSON.stringify(a.form)) as ApplicationForm, events: a.events.map((e) => ({ ...e })), messages: a.messages.map((m) => ({ ...m, params: { ...m.params } })), ...(a.screening ? { screening: JSON.parse(JSON.stringify(a.screening)) as ApplicationScreening } : {}), ...(a.interview ? { interview: JSON.parse(JSON.stringify(a.interview)) as PartnerInterview } : {}), ...(a.verification ? { verification: JSON.parse(JSON.stringify(a.verification)) as PartnerVerification } : {}), ...(a.offer ? { offer: JSON.parse(JSON.stringify(a.offer)) as PartnerOffer } : {}), ...(a.waitlist ? { waitlist: { ...a.waitlist } } : {}) }));
/** A form can be changed by its applicant until screening has decided it; an asked-for correction reopens it. */
const apLocked = (status: PartnerApplication['status']): boolean => status === 'approved' || status === 'rejected' || status === 'withdrawn';
let applicationCounter = 100;
let applicationEventCounter = 0;
let applicationRefCounter = 0;

const applicationEvent = (kind: PartnerApplication['events'][number]['kind'], byName: string, note?: string): PartnerApplication['events'][number] => {
  applicationEventCounter += 1;
  return { id: `apev-${applicationEventCounter}`, at: new Date().toISOString(), kind, byName, ...(note ? { note } : {}) };
};

/** The applicant is whoever holds their own link's key; Admin is a signed-in Admin. Nobody else sees an application. */
function applicationFor(applicationId: string, access: ApplicationAccess): { app: PartnerApplication; viewer: 'applicant' | 'admin'; admin: User | null } {
  const app = byId(partnerApplications, applicationId);
  if (!app) throw new RepositoryError('not_found');
  if (access.userId) {
    const u = byId(users, access.userId);
    if (u?.role === 'admin') return { app, viewer: 'admin', admin: u };
    throw new RepositoryError('forbidden');
  }
  if (!access.key || access.key !== app.accessKey) throw new RepositoryError('invalid_link');
  return { app, viewer: 'applicant', admin: null };
}

function applicationViewOf(app: PartnerApplication, viewer: 'applicant' | 'admin'): PartnerApplicationView {
  const interest = byId(recruitmentInterests, app.interestId);
  const sections = apSections(app.role, app.form);
  const form = JSON.parse(JSON.stringify(app.form)) as ApplicationForm;
  if (viewer === 'admin') {
    form.identity.aadhaarNumber = apMask(form.identity.aadhaarNumber);
    form.identity.panNumber = apMask(form.identity.panNumber);
  }
  return {
    id: app.id,
    code: app.code,
    role: app.role,
    status: app.status,
    viewer,
    locked: apLocked(app.status),
    form,
    sections: sections.map((s) => ({ ...s, missing: [...s.missing] })),
    progress: apProgress(sections),
    canSubmit: apSubmitProblem(app.role, app.form) === null,
    outstanding: apOutstanding(app.form),
    zones: zones.filter((z) => z.status === 'active').map((z) => ({ id: z.id, name: z.name })),
    source: interest ? { ...interest.source } : { channel: 'website' },
    interestedAt: interest?.interestedAt ?? app.startedAt,
    startedAt: app.startedAt,
    submittedAt: app.submittedAt ?? null,
    updatedAt: app.updatedAt,
    events: app.events.map((e) => ({ ...e })),
    messages: app.messages.map((m) => ({ ...m, params: { ...m.params } })),
    infoRequest: app.status === 'info_requested' && app.screening?.infoRequest ? { sections: [...app.screening.infoRequest.sections], note: app.screening.infoRequest.note, at: app.screening.infoRequest.at } : null,
    offer: app.offer && (app.offer.status === 'sent' || app.offer.status === 'signed') ? { status: app.offer.status } : null,
    interview: app.status === 'approved' ? { phase: ivPhaseOf(app.interview, Date.now()), slot: app.interview?.slot && app.interview.status === 'scheduled' ? { start: app.interview.slot.start, end: app.interview.slot.end, mode: app.interview.slot.mode } : null, canSelfServe: ivSelfServe(app.interview, Date.now()) } : null,
  };
}

/* ============================== Recruitment: applicant screening and scoring (143) */

const scoringConfig: { weights: Weights; updatedAt: string | null; updatedByName: string | null } = { weights: { ...SCREEN_DEFAULT_WEIGHTS }, updatedAt: null, updatedByName: null };
let screeningMessageCounter = 0;

function screeningAdmin(userId: string): User {
  const u = byId(users, userId);
  if (!u || u.role !== 'admin') throw new RepositoryError('not_admin');
  return u;
}

/** How much AIEC needs what this person offers where they offer it: read from the coverage that exists now, never typed in. */
function screeningNeedOf(app: PartnerApplication): { need: number; detail: Record<string, number | string> } {
  if (app.role === 'supplier') {
    const cats = app.form.experience.skills;
    if (cats.length === 0) return { need: 0, detail: { basis: 'supplier', categories: 0 } };
    const supply = (c: string) => suppliers.filter((x) => x.status === 'active' && x.categories.includes(c)).length;
    const needOf = (n: number) => (n === 0 ? 100 : n === 1 ? 70 : n === 2 ? 40 : 15);
    const best = cats.map((c) => ({ c, n: supply(c) })).sort((a, b) => a.n - b.n)[0];
    return { need: needOf(best.n), detail: { basis: 'supplier', category: best.c, suppliers: best.n } };
  }
  const active = zones.filter((z) => z.status === 'active');
  const raw = (z: GeoZone) => z.leadCount / Math.max(0.5, z.assignedUserIds.length);
  const top = Math.max(0, ...active.map(raw));
  const chosen = active.filter((z) => app.form.territory.zoneIds.includes(z.id)).sort((a, b) => raw(b) - raw(a));
  if (chosen.length === 0) return { need: 0, detail: { basis: 'zone', zones: 0 } };
  const best = chosen[0];
  return { need: top === 0 ? 50 : Math.round((100 * raw(best)) / top), detail: { basis: 'zone', zone: best.name, leads: best.leadCount, people: best.assignedUserIds.length } };
}

/** The score as it stands: live while the application is open, exactly as decided once it is not. */
function screeningScoreOf(app: PartnerApplication, weights: Weights, now: Date): { rows: ScreeningFactorView[]; score: number; adjustment: number; effective: number; frozen: boolean } {
  const decision = app.screening?.decision;
  if (decision) {
    return { rows: decision.rows.map((r) => ({ ...r, detail: {} })), score: decision.score, adjustment: decision.effective - decision.score, effective: decision.effective, frozen: true };
  }
  const { need, detail } = screeningNeedOf(app);
  const sections = apSections(app.role, app.form, now);
  const { score, rows } = scoreWith(factorValues({ role: app.role, form: app.form, sections, need, needDetail: detail, now }), weights);
  const adjustment = app.screening?.adjustment?.points ?? 0;
  return { rows, score, adjustment, effective: clampScreen(score + adjustment), frozen: false };
}

function screeningRowOf(app: PartnerApplication, weights: Weights, now: Date): ScreeningRowView {
  const sc = screeningScoreOf(app, weights, now);
  const interest = byId(recruitmentInterests, app.interestId);
  const sinceIso = app.status === 'info_requested' ? app.screening?.infoRequest?.at : app.submittedAt;
  const waitingDays = sinceIso ? Math.max(0, Math.floor((now.getTime() - new Date(sinceIso).getTime()) / 86_400_000)) : 0;
  const byContribution = [...sc.rows].sort((a, b) => b.contribution - a.contribution);
  const byValue = [...sc.rows].filter((r) => r.weight >= 10).sort((a, b) => a.value - b.value);
  return {
    id: app.id,
    code: app.code,
    name: app.form.personal.fullName,
    role: app.role,
    status: app.status,
    channel: interest?.source.channel ?? 'website',
    city: app.form.personal.city,
    submittedAt: app.submittedAt ?? null,
    waitingDays,
    overdue: app.status === 'submitted' && !!app.submittedAt && now.getTime() - new Date(app.submittedAt).getTime() > SCREEN_DUE,
    score: sc.score,
    adjustment: sc.adjustment,
    effective: sc.effective,
    frozen: sc.frozen,
    outstanding: apOutstanding(app.form).length,
    topFactor: byContribution[0].key,
    weakFactor: (byValue[0] ?? byContribution[byContribution.length - 1]).key,
  };
}

const screeningOrder = (a: ScreeningRowView, b: ScreeningRowView): number => b.effective - a.effective || (a.submittedAt ?? '').localeCompare(b.submittedAt ?? '');

/** The open queue, best first, under a given weighting. */
function screeningQueueIds(weights: Weights, now: Date): string[] {
  return partnerApplications
    .filter((a) => a.status === 'submitted')
    .map((a) => screeningRowOf(a, weights, now))
    .sort(screeningOrder)
    .map((r) => r.id);
}

function screeningDetailOf(app: PartnerApplication, now: Date): ScreeningDetailView {
  const sc = screeningScoreOf(app, scoringConfig.weights, now);
  const ids = screeningQueueIds(scoringConfig.weights, now);
  const at = ids.indexOf(app.id);
  return {
    application: applicationViewOf(app, 'admin'),
    rows: sc.rows,
    score: sc.score,
    adjustment: app.screening?.adjustment ? { ...app.screening.adjustment } : null,
    effective: sc.effective,
    frozen: sc.frozen,
    decision: app.screening?.decision ? { ...app.screening.decision, rows: app.screening.decision.rows.map((r) => ({ ...r })) } : null,
    infoRequest: app.screening?.infoRequest ? { ...app.screening.infoRequest, sections: [...app.screening.infoRequest.sections] } : null,
    outcome: app.screening?.outcome ? { ...app.screening.outcome } : null,
    place: at >= 0 ? at + 1 : null,
    queueSize: ids.length,
    canDecide: app.status === 'submitted' || app.status === 'info_requested',
    nextId: at >= 0 ? (ids[at + 1] ?? ids.find((x) => x !== app.id) ?? null) : (ids[0] ?? null),
  };
}

function screeningMessage(app: PartnerApplication, kind: PartnerApplication['messages'][number]['kind'], templateKey: string, byName: string, note?: string, extra: Record<string, string> = {}): void {
  screeningMessageCounter += 1;
  app.messages.push({ id: `apm-${screeningMessageCounter}`, at: new Date().toISOString(), kind, templateKey, params: { name: app.form.personal.fullName.split(' ')[0] ?? '', ...extra }, ...(note?.trim() ? { note: note.trim() } : {}), byName });
}

/** What a decision freezes: the score, its breakdown and any adjustment, so the reason can still be read when the weights have moved on. */
function freezeDecision(app: PartnerApplication, status: 'approved' | 'rejected', byName: string, now: Date, extra: { reasonKey?: string; note?: string }): void {
  const sc = screeningScoreOf(app, scoringConfig.weights, now);
  const screening: ApplicationScreening = app.screening ?? {};
  screening.decision = { status, at: now.toISOString(), byName, score: sc.score, effective: sc.effective, rows: sc.rows.map((r): ScreeningFactorRow => ({ key: r.key, weight: r.weight, value: r.value, contribution: r.contribution })), ...(extra.reasonKey ? { reasonKey: extra.reasonKey } : {}), ...(extra.note?.trim() ? { note: extra.note.trim() } : {}) };
  app.screening = screening;
  app.status = status;
  app.updatedAt = now.toISOString();
}

function screeningApp(applicationId: string): PartnerApplication {
  const app = byId(partnerApplications, applicationId);
  if (!app) throw new RepositoryError('not_found');
  return app;
}

function screeningFeedbackOf() {
  const rated = partnerApplications
    .filter((a) => a.status === 'approved' && a.screening?.outcome && a.screening.decision)
    .map((a) => ({ rating: (a.screening as ApplicationScreening).outcome!.rating, values: Object.fromEntries((a.screening as ApplicationScreening).decision!.rows.map((r) => [r.key, r.value])) as Record<Factor, number> }));
  return { rated: rated.length, ...screeningFeedback(rated) };
}

/* ============================== Recruitment: the public front door (141) */

const recruitmentInterests: RecruitmentInterest[] = seedRecruitmentInterests.map((x) => ({ ...x, source: { ...x.source }, touches: x.touches.map((t) => ({ ...t })) }));
let recruitmentCounter = 100;
const RECRUIT_SURGE_ALERT = 'alerts.type.recruitmentSurge';

const recruitmentLastDay = (now: number): number => recruitmentInterests.filter((i) => new Date(i.interestedAt).getTime() > now - INTAKE_WINDOW).length;

/** One alert while a day's intake is a surge, so the person who plans screening hears of it before a backlog forms; it clears itself. */
function syncRecruitmentIntake(now: number): void {
  const at = new Date(now).toISOString();
  const count = recruitmentLastDay(now);
  const surge = count >= INTAKE_SURGE_PER_DAY;
  const open = alerts.find((a) => a.titleKey === RECRUIT_SURGE_ALERT && a.status !== 'resolved');
  if (surge && !open) {
    raiseAlert({ titleKey: RECRUIT_SURGE_ALERT, context: `${count} new interests in the last day`, severity: 'medium', category: 'staffing', relatedId: 'recruit:surge', sourceRoute: '/admin/escalations' });
    logAutomatedAction({ sourceKey: 'recruitment.surge', triggeringCondition: `${count} people showed interest in a day, past the surge line`, actionTaken: 'Raised an alert and told new applicants to expect a longer first reply', affectedRecordId: 'recruit:surge', affectedRecordType: 'other', subjectLabel: 'Recruitment intake' });
  }
  if (!surge && open) patchInPlace(alerts, open.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'Intake is back to a normal day.' });
}

/* ============================== Recruitment: interview scheduling (144) */

const interviewAvailability: InterviewAvailability = JSON.parse(JSON.stringify(IV_DEFAULT_AVAILABILITY)) as InterviewAvailability;
let interviewEventCounter = 0;

const ivEvent = (kind: PartnerInterview['events'][number]['kind'], byName: string, note?: string): PartnerInterview['events'][number] => {
  interviewEventCounter += 1;
  return { id: `ivev-${interviewEventCounter}`, at: new Date().toISOString(), kind, byName, ...(note ? { note } : {}) };
};

function ivAdmin(userId: string): User {
  const u = byId(users, userId);
  if (!u || u.role !== 'admin') throw new RepositoryError('not_admin');
  return u;
}
function ivApp(applicationId: string): PartnerApplication {
  const app = byId(partnerApplications, applicationId);
  if (!app) throw new RepositoryError('not_found');
  return app;
}
/** Everyone else's confirmed times: what a new slot must not overlap. */
const ivBusy = (exceptAppId?: string): IvBusy[] => partnerApplications.filter((a) => a.id !== exceptAppId && a.interview?.status === 'scheduled' && a.interview.slot).map((a) => ({ start: (a.interview as PartnerInterview).slot!.start, end: (a.interview as PartnerInterview).slot!.end }));
const ivMessage = (app: PartnerApplication, kind: PartnerApplication['messages'][number]['kind'], key: string, byName: string, extra: Record<string, string> = {}, note?: string) => screeningMessage(app, kind, `interview.message.${key}`, byName, note, extra);
const ivLocal = (iso: string): string => {
  const d = new Date(iso);
  const p = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
};

function ivRowOf(app: PartnerApplication, now: number): InterviewRowView {
  const i = app.interview;
  const phase = ivPhaseOf(i, now);
  const decidedAt = app.screening?.decision?.at ?? null;
  const since = phase === 'to_arrange' ? decidedAt : i?.invitedAt;
  return {
    id: app.id,
    code: app.code,
    name: app.form.personal.fullName,
    role: app.role,
    phase,
    score: app.screening?.decision?.effective ?? null,
    approvedAt: decidedAt,
    slot: i?.slot && (i.status === 'scheduled' || i.status === 'completed') ? { start: i.slot.start, end: i.slot.end, mode: i.slot.mode } : null,
    modes: i ? [...i.modes] : [],
    misses: i?.misses ?? 0,
    reschedules: i?.reschedules ?? 0,
    conflict: !!i && i.status === 'scheduled' && !!i.slot && !i.moveRequest && i.slot.chosenBy === 'applicant' && !ivFits(interviewAvailability, i.slot.start, i.slot.end) && now < new Date(i.slot.start).getTime(),
    signal: ivSignal(i).level,
    waitingDays: since ? Math.max(0, Math.floor((now - new Date(since).getTime()) / 86_400_000)) : 0,
  };
}

const IV_RANK: Record<IvPhase, number> = { needs_outcome: 0, move_requested: 1, scheduled: 2, invited: 3, to_arrange: 4, missed: 5, completed: 6, skipped: 7, cancelled: 8 };

function ivDetailOf(app: PartnerApplication, now: number): InterviewDetailView {
  const row = ivRowOf(app, now);
  return {
    row,
    applicant: { name: app.form.personal.fullName, phone: app.form.personal.phone, city: app.form.personal.city, languages: [...app.form.personal.languages], years: app.form.experience.years },
    interview: app.interview ? (JSON.parse(JSON.stringify(app.interview)) as PartnerInterview) : null,
    signal: ivSignal(app.interview),
    slots: ivSlots(interviewAvailability, ivBusy(app.id), now).slice(0, 12),
    canInvite: row.phase === 'to_arrange' || row.phase === 'cancelled' || row.phase === 'missed',
    canSkip: row.phase === 'to_arrange' || row.phase === 'invited' || row.phase === 'cancelled' || row.phase === 'missed',
  };
}

function ivApplicantViewOf(app: PartnerApplication, now: number): InterviewApplicantView {
  const i = app.interview;
  const open = ivSelfServe(i, now);
  const slot = i?.slot && i.status === 'scheduled' ? i.slot : null;
  const phase = ivPhaseOf(i, now);
  return {
    applicationId: app.id,
    code: app.code,
    name: app.form.personal.fullName,
    phase,
    modes: i ? [...i.modes] : [],
    slot: slot ? { start: slot.start, end: slot.end, mode: slot.mode } : null,
    details: slot && i ? { ...(slot.mode === 'video' && i.details.videoLink ? { videoLink: i.details.videoLink } : {}), ...(slot.mode === 'in_person' && i.details.place ? { place: i.details.place } : {}) } : {},
    phone: app.form.personal.phone,
    moveRequest: i?.moveRequest ? { reason: i.moveRequest.reason, at: i.moveRequest.at } : null,
    misses: i?.misses ?? 0,
    maxMisses: IV_MAX_MISSES,
    canSelfServe: open,
    slots: open ? ivSlots(interviewAvailability, ivBusy(app.id), now) : [],
    calendarFile: slot ? ivIcs({ uid: `${app.code}-${slot.start}`, start: slot.start, end: slot.end, summary: 'AIEC interview', description: `Interview with AIEC (${slot.mode}).`, ...(slot.mode === 'in_person' && i?.details.place ? { location: i.details.place } : {}) }) : null,
  };
}

const INTERVIEW_MODE_LIST: InterviewMode[] = ['phone', 'video', 'in_person'];

function ivDetailsProblem(modes: InterviewMode[], details: { videoLink?: string; place?: string }): 'modes_required' | 'link_required' | 'place_required' | null {
  if (modes.length === 0) return 'modes_required';
  if (modes.includes('video') && !/^https?:\/\/\S+\.\S+/.test((details.videoLink ?? '').trim())) return 'link_required';
  if (modes.includes('in_person') && (details.place ?? '').replace(/[^\p{L}\p{N}]/gu, '').length < 5) return 'place_required';
  return null;
}

/** The automatic part: each confirmed time gets its reminders once, and an invitation nobody answers is nudged once. Everything is a message on the applicant's own link. */
function syncPartnerInterviews(now: number): void {
  for (const app of partnerApplications) {
    const i = app.interview;
    if (!i || app.status !== 'approved') continue;
    if (i.status === 'scheduled' && i.slot) {
      const start = new Date(i.slot.start).getTime();
      for (const r of IV_REMINDERS) {
        const key = `applicant:${r.key}:${i.slot.start}`;
        if (now < start - r.before || now >= start || i.remindersSent.includes(key)) continue;
        // A time confirmed after the reminder's moment was just told to them: no second message straight after.
        if (new Date(i.slot.chosenAt).getTime() > start - r.before) {
          i.remindersSent.push(key);
          continue;
        }
        i.remindersSent.push(key);
        ivMessage(app, 'interview_reminder', 'reminder', 'AIEC', { at: i.slot.start, mode: i.slot.mode });
        i.events.push(ivEvent('reminder', 'AIEC', r.key));
        logAutomatedAction({ sourceKey: 'interview.reminder', triggeringCondition: `${r.key} before the interview with ${app.form.personal.fullName}`, actionTaken: 'Reminded the applicant on their own application link', affectedRecordId: app.id, affectedRecordType: 'other', subjectLabel: app.code });
      }
    }
    if (i.status === 'invited' && now - new Date(i.invitedAt).getTime() >= IV_INVITE_WAIT && !i.events.some((e) => e.kind === 'nudged')) {
      ivMessage(app, 'interview_nudge', 'nudge', 'AIEC');
      i.events.push(ivEvent('nudged', 'AIEC'));
      logAutomatedAction({ sourceKey: 'interview.nudge', triggeringCondition: `${app.form.personal.fullName} has not chosen an interview time after the waiting period`, actionTaken: 'Sent one gentle reminder on their application link', affectedRecordId: app.id, affectedRecordType: 'other', subjectLabel: app.code });
    }
  }
}

/* ============================== Recruitment: background and document verification (145) */

const verificationService: VerificationServiceView = { status: 'up', changedAt: null, changedByName: null };
let verificationEventCounter = 0;
const VERIFY_ALERT_FAILED = 'verification.alert.failed';
const VERIFY_ALERT_LAPSED = 'verification.alert.lapsed';

const vfEvent = (kind: PartnerVerification['events'][number]['kind'], byName: string, item?: string, note?: string): PartnerVerification['events'][number] => {
  verificationEventCounter += 1;
  return { id: `vfev-${verificationEventCounter}`, at: new Date().toISOString(), kind, byName, ...(item ? { item } : {}), ...(note ? { note } : {}) };
};
const vfOf = (app: PartnerApplication): PartnerVerification => {
  if (!app.verification) app.verification = { records: {}, autoSent: [], events: [] };
  return app.verification;
};
function vfAdmin(userId: string): User {
  const u = byId(users, userId);
  if (!u || u.role !== 'admin') throw new RepositoryError('not_admin');
  return u;
}
function vfApp(applicationId: string): PartnerApplication {
  const app = byId(partnerApplications, applicationId);
  if (!app) throw new RepositoryError('not_found');
  if (app.status !== 'approved') throw new RepositoryError('not_approved');
  return app;
}
/** Moved forward long ago and never touched is history, not a pending job (the same cutoff the interview step and the commitments use). */
const vfLive = (app: PartnerApplication, now: number): boolean => app.status === 'approved' && (!!app.interview || !!app.verification || now - new Date(app.screening?.decision?.at ?? 0).getTime() < IV_ARRANGE_DUE * 10);

function vfFacts(app: PartnerApplication, item: RequiredItem): VerificationItemView['facts'] {
  const f = app.form;
  if (item.kind === 'identity') {
    const pan = f.identity.panNumber.trim();
    const aad = f.identity.aadhaarNumber.trim();
    return pan ? { type: 'pan', number: apMask(pan), doc: !!f.identity.panDoc } : aad ? { type: 'aadhaar', number: apMask(aad), doc: !!f.identity.aadhaarDoc } : { type: 'none', number: '', doc: false };
  }
  if (item.kind === 'registration') return { type: 'gstin', number: f.identity.gstin.trim(), doc: !!f.identity.gstDoc };
  if (item.kind === 'reference') {
    const refs = f.references;
    return { total: refs.length, verified: refs.filter((r) => r.outcome?.status === 'verified').length, unreachable: refs.filter((r) => r.outcome?.status === 'unreachable').length, declined: refs.filter((r) => r.outcome?.status === 'declined').length, unchecked: refs.filter((r) => !r.outcome).length, none: f.noReferences };
  }
  if (item.kind === 'skill') return { skill: item.skill ?? '' };
  return {};
}

function vfRowOf(app: PartnerApplication, now: number): VerificationRowView {
  const g = vfGate(vfRequired(app.role, app.form), app.verification, now);
  const dues = g.conditional.map((c) => c.dueAt).sort();
  const decidedAt = app.screening?.decision?.at ?? null;
  return {
    id: app.id,
    code: app.code,
    name: app.form.personal.fullName,
    role: app.role,
    gate: g.state,
    passed: g.passed,
    total: g.total,
    failed: g.failed.length,
    lapsed: g.lapsed.length,
    conditionalDue: dues[0] ?? null,
    approvedAt: decidedAt,
    waitingDays: decidedAt ? Math.max(0, Math.floor((now - new Date(decidedAt).getTime()) / 86_400_000)) : 0,
    interviewSignal: ivSignal(app.interview).level,
  };
}

function vfDetailOf(app: PartnerApplication, now: number): VerificationDetailView {
  const required = vfRequired(app.role, app.form);
  const v = app.verification;
  const sig = ivSignal(app.interview);
  return {
    row: vfRowOf(app, now),
    applicant: { name: app.form.personal.fullName, phone: app.form.personal.phone, city: app.form.personal.city },
    items: required.map((it): VerificationItemView => ({ key: it.key, kind: it.kind, ...(it.skill ? { skill: it.skill } : {}), thirdParty: it.thirdParty, canBeConditional: it.canBeConditional, state: vfItemState(v?.records[it.key], now), record: v?.records[it.key] ? (JSON.parse(JSON.stringify(v.records[it.key])) as VerificationRecord) : null, facts: vfFacts(app, it) })),
    gate: vfGate(required, v, now),
    interview: { signal: sig.level, concerns: sig.concerns.map((c) => ({ ...c })), outcome: app.interview?.completed?.outcome ?? null },
    service: { ...verificationService },
    events: (v?.events ?? []).map((e) => ({ ...e })),
  };
}

function vfRecord(app: PartnerApplication, key: string, rec: Omit<VerificationRecord, 'history'>): void {
  const v = vfOf(app);
  const prior = v.records[key];
  v.records[key] = { ...rec, history: [...(prior ? [...prior.history, { at: prior.at, status: prior.status, method: prior.method, byName: prior.byName, ...(prior.note ? { note: prior.note } : {}), ...(prior.conditional ? { dueAt: prior.conditional.dueAt } : {}) }] : [])] };
}

function vfAlert(relatedId: string, titleKey: string, context: string, severity: 'medium' | 'high', app: PartnerApplication, want: boolean, at: string): void {
  const open = alerts.find((a) => a.relatedId === relatedId && a.titleKey === titleKey && a.status !== 'resolved');
  if (want && !open) raiseAlert({ titleKey, context, severity, category: 'staffing', relatedId, sourceRoute: `/verification/${app.id}` });
  if (!want && open) patchInPlace(alerts, open.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'The item is no longer open.' });
}

/** Sends identity to the ID service as soon as someone is moved forward (when it is up), and keeps the alerts for failed and lapsed items true. */
function syncVerification(now: number): void {
  const at = new Date(now).toISOString();
  for (const app of partnerApplications) {
    if (!vfLive(app, now)) continue;
    const required = vfRequired(app.role, app.form);
    const v = vfOf(app);
    if (verificationService.status === 'up') {
      for (const it of required.filter((x) => x.thirdParty)) {
        if (v.records[it.key] || v.autoSent.includes(it.key)) continue;
        v.autoSent.push(it.key);
        const r = vfServiceCheck(app.role, app.form);
        if (r.result === 'inconclusive') {
          v.events.push(vfEvent('service_check', 'AIEC', it.key, `inconclusive:${r.detail}`));
        } else {
          vfRecord(app, it.key, { status: r.result === 'passed' ? 'passed' : 'failed', method: 'third_party', at, byName: 'AIEC', reference: `IDV-${app.code.slice(-4)}-${Math.abs(it.key.length * 7919) % 9999}`, note: r.detail });
          v.events.push(vfEvent('service_check', 'AIEC', it.key, r.result));
        }
        logAutomatedAction({ sourceKey: 'verification.service_check', triggeringCondition: `${app.form.personal.fullName} moved forward; ${it.key} can be answered by the ID service`, actionTaken: r.result === 'inconclusive' ? 'Sent to the ID service: it could not decide, left for Admin to check by hand' : `Sent to the ID service: ${r.result}`, affectedRecordId: app.id, affectedRecordType: 'other', subjectLabel: app.code });
      }
    }
    for (const it of required) {
      const st = vfItemState(v.records[it.key], now);
      vfAlert(`verif:${app.id}:${it.key}:failed`, VERIFY_ALERT_FAILED, `${app.form.personal.fullName}: ${it.key} failed verification`, 'medium', app, st === 'failed', at);
      vfAlert(`verif:${app.id}:${it.key}:lapsed`, VERIFY_ALERT_LAPSED, `${app.form.personal.fullName}: the allowance for ${it.key} has passed its deadline`, 'high', app, st === 'lapsed', at);
      if (st === 'lapsed' && !v.events.some((e) => e.kind === 'lapsed' && e.item === it.key && e.at >= (v.records[it.key]?.at ?? ''))) v.events.push(vfEvent('lapsed', 'AIEC', it.key));
    }
  }
}

/* ============================== Recruitment: offer and onboarding agreement (146) */

const agreementTemplates: PartnerAgreementTemplate[] = (['surveyor', 'technician', 'supplier'] as const).map((role) => ({ id: `pat-${role}-1`, role, version: 1, effectiveFrom: '2026-01-01', terms: ofDefaultTerms(role), wording: 'v1' as const, changeNote: 'First standard terms.', createdByName: 'Prashant Vasant Wable', createdAt: '2026-01-01T00:00:00.000Z', isDemo: true }));
let offerCounter = 0;
let offerEventCounter = 0;
const OFFER_REQUEST_ALERT = 'agreement.alert.request';

const ofEvent = (kind: PartnerOffer['events'][number]['kind'], byName: string, note?: string): PartnerOffer['events'][number] => {
  offerEventCounter += 1;
  return { id: `ofev-${offerEventCounter}`, at: new Date().toISOString(), kind, byName, ...(note ? { note } : {}) };
};
function ofAdmin(userId: string): User {
  const u = byId(users, userId);
  if (!u || u.role !== 'admin') throw new RepositoryError('not_admin');
  return u;
}
function ofApp(applicationId: string): PartnerApplication {
  const app = byId(partnerApplications, applicationId);
  if (!app) throw new RepositoryError('not_found');
  if (app.status !== 'approved') throw new RepositoryError('not_approved');
  return app;
}
const templateInForce = (role: PartnerApplication['role'], now: number): PartnerAgreementTemplate => agreementTemplates.filter((t) => t.role === role && new Date(`${t.effectiveFrom}T00:00:00`).getTime() <= now).sort((a, b) => b.version - a.version)[0];
const ofDefs = (role: PartnerApplication['role']) => ofTermDefs[role].map((d) => ({ ...d, standard: Number((ofDefaultTerms(role) as Record<string, unknown>)[d.key]) }));
const ofInterviewOpen = (app: PartnerApplication): boolean => !!app.interview && ['invited', 'scheduled', 'missed'].includes(app.interview.status);
const ofGateOf = (app: PartnerApplication, now: number) => vfGate(vfRequired(app.role, app.form), app.verification, now);

function ofStage(app: PartnerApplication, now: number): OfferStage {
  const o = app.offer;
  if (o && o.status !== 'withdrawn') return o.status;
  if (app.waitlist) return 'waitlisted';
  if (ofInterviewOpen(app)) return 'interview_open';
  if (ofGateOf(app, now).state === 'blocked') return 'verifying';
  return o ? 'withdrawn' : 'to_prepare';
}

function ofRowOf(app: PartnerApplication, now: number): OfferRowView {
  const o = app.offer;
  return {
    id: app.id,
    code: app.code,
    name: app.form.personal.fullName,
    role: app.role,
    stage: ofStage(app, now),
    gate: ofGateOf(app, now).state,
    signal: ivSignal(app.interview).level,
    templateVersion: o?.templateVersion ?? null,
    capability: o ? ofCapability(o) : 'none',
    daysSinceSent: o?.sentAt ? Math.floor((now - new Date(o.sentAt).getTime()) / 86_400_000) : null,
    openRequest: !!o?.requests.some((r) => !r.response),
    approvedAt: app.screening?.decision?.at ?? null,
  };
}

/** A phone number already belonging to someone else cannot become a second account (a pending supplier from onboarding may be activated). */
function ofPhoneTaken(app: PartnerApplication): boolean {
  const u = users.find((x) => x.phone === app.form.personal.phone);
  return !!u && !(app.role === 'supplier' && u.role === 'supplier' && u.status === 'pending_approval');
}

function ofDetailOf(app: PartnerApplication, now: number): OfferDetailView {
  const row = ofRowOf(app, now);
  const tpl = templateInForce(app.role, now);
  const o = app.offer ?? null;
  const sig = ivSignal(app.interview);
  const base: AgreementTerms = o ? ofBinding(o) : { ...tpl.terms, ...(app.role !== 'supplier' ? { territoryZoneIds: app.form.territory.zoneIds.filter((z) => zones.some((x) => x.id === z && x.status === 'active')) } : {}) };
  const stage = row.stage;
  return {
    row,
    applicant: { name: app.form.personal.fullName, phone: app.form.personal.phone, city: app.form.personal.city, languages: [...app.form.personal.languages] },
    gate: ofGateOf(app, now),
    signal: sig,
    interviewOutcome: app.interview?.completed?.outcome ?? (app.interview?.status === 'skipped' ? 'skipped' : null),
    template: { id: tpl.id, version: tpl.version, effectiveFrom: tpl.effectiveFrom, newerExists: !!o && o.status !== 'signed' && o.templateVersion < tpl.version },
    offer: o ? (JSON.parse(JSON.stringify(o)) as PartnerOffer) : null,
    terms: base,
    clauses: ofClauses(app.role),
    zones: zones.filter((z) => z.status === 'active').map((z) => ({ id: z.id, name: z.name })),
    termDefs: ofDefs(app.role),
    canPrepare: stage === 'to_prepare' || stage === 'draft' || stage === 'withdrawn',
    blockedBy: stage === 'interview_open' ? 'interview_open' : stage === 'waitlisted' ? 'waitlisted' : stage === 'verifying' ? 'verifying' : stage === 'signed' ? 'signed' : stage === 'sent' ? 'sent' : null,
    needsOverride: sig.level === 'block',
    phoneTaken: ofPhoneTaken(app),
  };
}

function ofApplicantViewOf(app: PartnerApplication): OfferApplicantView {
  const o = app.offer;
  const act = o?.activation;
  return {
    applicationId: app.id,
    code: app.code,
    name: app.form.personal.fullName,
    role: app.role,
    status: !o || o.status === 'draft' ? 'none' : o.status,
    documentNo: o && o.status !== 'draft' ? o.documentNo : null,
    templateVersion: o && o.status !== 'draft' ? o.templateVersion : null,
    wording: 'v1',
    terms: o && o.status !== 'draft' ? ofBinding(o) : {},
    addendum: o?.addendum ? JSON.parse(JSON.stringify(o.addendum)) : null,
    clauses: ofClauses(app.role),
    zoneNames: o && o.status !== 'draft' ? (ofBinding(o).territoryZoneIds ?? []).map((z) => zones.find((x) => x.id === z)?.name ?? z) : [],
    requests: o ? o.requests.map((r) => ({ ...r })) : [],
    signature: o?.signature ? { at: o.signature.at, signerName: o.signature.signerName, method: o.signature.method, language: o.signature.language, data: o.signature.data } : null,
    activation: act ? { at: act.at, capability: ofCapability(o as PartnerOffer) as 'basic' | 'full', steps: JSON.parse(JSON.stringify(act.steps)) } : null,
    sentAt: o?.sentAt ?? null,
  };
}

/** The one event that makes someone a partner: an active account (and for a supplier the firm and its agreement), with payouts still waiting on the remaining steps. */
function ofActivate(app: PartnerApplication, offer: PartnerOffer, at: string): void {
  const f = app.form;
  const terms = ofBinding(offer);
  const lang = f.personal.languages[0] ?? 'en';
  let supplierId: string | undefined;
  let userId: string;
  if (app.role === 'supplier') {
    const gstin = f.identity.gstin.trim().toUpperCase();
    let supplier = suppliers.find((x) => x.gstin?.toUpperCase() === gstin);
    if (!supplier) {
      supplierCounter += 1;
      supplier = { id: `sp-new-${supplierCounter}`, name: f.personal.fullName, status: 'active', kycStatus: 'approved', kycReviewedBy: 'AIEC verification', kycReviewedAt: at, city: f.personal.city, gstin, contactName: f.personal.fullName, contactPhone: f.personal.phone, categories: [...f.experience.skills], driveTypeSpecialties: [], regionsServed: [], onTimeRate: 0, qualityScore: 0, avgLeadTimeDays: 0, openOrders: 0, totalOrderValue: 0, rating: 0, invitedBy: 'Recruitment', invitedAt: at, isDemo: true };
      suppliers.push(supplier);
    } else patchInPlace(suppliers, supplier.id, { status: 'active' as const, kycStatus: 'approved' as const, kycReviewedBy: 'AIEC verification', kycReviewedAt: at });
    supplierId = supplier.id;
    const existing = users.find((u) => u.phone === f.personal.phone);
    if (existing) {
      patchInPlace(users, existing.id, { status: 'active' as const, joinedAt: at });
      userId = existing.id;
    } else {
      userCounter += 1;
      userId = `u-sup-new-${userCounter}`;
      users.push({ id: userId, role: 'supplier', name: f.personal.fullName, phone: f.personal.phone, status: 'active', preferredLanguage: lang, themePreference: 'light', isDemo: true, city: f.personal.city, companyName: supplier.name, gstin, joinedAt: at });
    }
    const hadAgreement = versionsOf(supplierAgreementVersions, supplier.id).length > 0;
    if (!hadAgreement) {
      agreementCounter += 1;
      supplierAgreementVersions.push({ id: `sag-new-${agreementCounter}`, supplierId: supplier.id, version: 1, kind: 'initial', terms: { deliverySlaDays: terms.deliverySlaDays ?? 14, paymentTermsDays: terms.paymentTermsDays ?? 30, minQualityScore: terms.minQualityScore ?? 3.5, qualityStandards: terms.qualityStandards ?? '', warrantyMonths: terms.warrantyMonths ?? 12 }, effectiveFrom: at.slice(0, 10), expiresOn: new Date(new Date(at).getTime() + 365 * 86_400_000).toISOString().slice(0, 10), documentName: `${offer.documentNo}.html`, warrantyPassThrough: true, recordedBy: 'Partner agreement', recordedAt: at, acknowledgedBy: f.personal.fullName, acknowledgedAt: at, isDemo: true });
    }
  } else {
    tcEnsure(Date.parse(at));
    userCounter += 1;
    userId = `u-${app.role === 'surveyor' ? 'srv' : 'tech'}-new-${userCounter}`;
    const skills = app.role === 'technician' ? Object.entries(app.verification?.records ?? {}).filter(([k, r]) => k.startsWith('skill:') && r.status !== 'failed').map(([k]) => k.slice(6)) : undefined;
    users.push({ id: userId, role: app.role, name: f.personal.fullName, phone: f.personal.phone, status: 'active', preferredLanguage: lang, themePreference: 'light', isDemo: true, city: f.personal.city, joinedAt: at, ...(skills ? { skills } : {}) });
    tcInitial(userId, app.role, at);
    // They can now receive leads in the areas the agreement names.
    for (const zid of terms.territoryZoneIds ?? []) {
      const z = byId(zones, zid);
      if (z && z.status === 'active' && !z.assignedUserIds.includes(userId)) patchInPlace(zones, zid, { assignedUserIds: [...z.assignedUserIds, userId] });
    }
  }
  offer.activation = { at, userId, ...(supplierId ? { supplierId } : {}), steps: Object.fromEntries(ofSteps[app.role].map((k) => [k, { done: false }])) };
  offer.events.push(ofEvent('activated', 'AIEC', userId));
  logAutomatedAction({ sourceKey: 'partner.activated', triggeringCondition: `${f.personal.fullName} signed the ${app.role} agreement ${offer.documentNo}`, actionTaken: `Activated the account for basic access; payouts wait for ${ofSteps[app.role].join(' and ')}`, affectedRecordId: app.id, affectedRecordType: 'other', subjectLabel: app.code });
}

/** One gentle nudge for an offer left unsigned, and an alert while a partner's question about a term is unanswered. */
function syncOffers(now: number): void {
  const at = new Date(now).toISOString();
  for (const app of partnerApplications) {
    const o = app.offer;
    if (!o || o.status !== 'sent') continue;
    if (o.sentAt && !o.nudgedAt && now - new Date(o.sentAt).getTime() >= OF_SIGN_WAIT) {
      o.nudgedAt = at;
      o.events.push(ofEvent('nudged', 'AIEC'));
      screeningMessage(app, 'offer_nudge', 'agreement.message.nudge', 'AIEC');
      logAutomatedAction({ sourceKey: 'offer.nudge', triggeringCondition: `${app.form.personal.fullName} has not signed the agreement after the waiting period`, actionTaken: 'Sent one gentle reminder on their application link', affectedRecordId: app.id, affectedRecordType: 'other', subjectLabel: app.code });
    }
  }
  for (const app of partnerApplications) {
    const open = app.offer?.requests.find((r) => !r.response);
    const rel = `offerreq:${app.id}`;
    const alert = alerts.find((a) => a.relatedId === rel && a.titleKey === OFFER_REQUEST_ALERT && a.status !== 'resolved');
    if (open && app.offer?.status === 'sent' && !alert) raiseAlert({ titleKey: OFFER_REQUEST_ALERT, context: `${app.form.personal.fullName} asked about a term in their agreement`, severity: 'medium', category: 'staffing', relatedId: rel, sourceRoute: `/offers/${app.id}` });
    if ((!open || app.offer?.status !== 'sent') && alert) patchInPlace(alerts, alert.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'The question was answered.' });
  }
}

/* ============================== Recruitment: the pipeline overview (147) */

interface RdEntry {
  key: string;
  name: string;
  role: RecruitmentInterest['role'];
  at: string;
  channel: RecruitmentInterest['source']['channel'];
  app?: PartnerApplication;
}

/** Everyone who has shown interest, with the application that came of it (some applications have no interest on record, and still count). */
function rdEntries(): RdEntry[] {
  const out: RdEntry[] = [];
  const claimed = new Set<string>();
  for (const i of recruitmentInterests) {
    if (i.status === 'withdrawn') continue;
    const app = partnerApplications.find((a) => a.interestId === i.id);
    if (app) claimed.add(app.id);
    out.push({ key: i.id, name: i.name, role: i.role, at: i.interestedAt, channel: i.source.channel, app });
  }
  for (const a of partnerApplications) {
    if (claimed.has(a.id)) continue;
    out.push({ key: a.id, name: a.form.personal.fullName, role: a.role, at: a.startedAt, channel: byId(recruitmentInterests, a.interestId)?.source.channel ?? 'website', app: a });
  }
  return out;
}

function rdNowStage(e: RdEntry, now: number): RdNowStage | null {
  const a = e.app;
  if (!a) return 'interested';
  if (a.status === 'draft') return 'form';
  if (a.status === 'submitted' || a.status === 'info_requested') return 'screening';
  if (a.status !== 'approved') return null;
  if (a.offer?.status === 'signed') return 'activated';
  if (a.waitlist) return 'waitlisted';
  if (ofInterviewOpen(a)) return 'interviewing';
  if (ofGateOf(a, now).state === 'blocked' && !(a.offer && a.offer.status !== 'withdrawn')) return 'verifying';
  return 'offer';
}

const rdReached = (e: RdEntry, now: number) => {
  const a = e.app;
  const applied = !!a && (!!a.submittedAt || a.status !== 'draft');
  const forward = a?.status === 'approved';
  const offered = !!a?.offer && (a.offer.status === 'sent' || a.offer.status === 'signed');
  return { interested: true, applied, forward, verified: forward && (offered || ofGateOf(a as PartnerApplication, now).state !== 'blocked'), offered, activated: a?.offer?.status === 'signed' };
};

const rdDays = (from?: string, to?: string): number | null => (from && to ? Math.max(0, (new Date(to).getTime() - new Date(from).getTime()) / 86_400_000) : null);
const rdRoute = (stage: RdNowStage | RdRecruitStage, id: string): string => (stage === 'interested' ? '' : stage === 'form' || stage === 'applied' || stage === 'forward' ? `/applications/${id}` : stage === 'screening' ? `/screening?app=${id}` : stage === 'interviewing' ? `/interviews/${id}` : stage === 'verifying' || stage === 'verified' ? `/verification/${id}` : `/offers/${id}`);

function rdBuild(period: RdPeriod, now: number): RecruitmentDashboardView {
  const all = rdEntries();
  const span = period * 86_400_000;
  const within = (iso: string | undefined, from: number, to: number) => !!iso && new Date(iso).getTime() > from && new Date(iso).getTime() <= to;
  const cohort = (from: number, to: number) => (period === 0 ? all : all.filter((e) => within(e.at, from, to)));
  const cur = cohort(now - span, now);
  const prev = period === 0 ? [] : cohort(now - 2 * span, now - span);
  const names = (zoneIds: string[]) => zoneIds.map((z) => byId(zones, z)?.name ?? z);

  const reachedCount = (list: RdEntry[]): Record<RdRecruitStage, number> => {
    const r = { interested: 0, applied: 0, forward: 0, verified: 0, offered: 0, activated: 0 };
    for (const e of list) {
      const f = rdReached(e, now);
      for (const k of RD_FUNNEL) if (f[k]) r[k] += 1;
    }
    return r;
  };
  const counts = reachedCount(cur);
  const rows = rdFunnelOf(counts);
  const timeline = (k: RdRecruitStage, e: RdEntry): number | null => {
    const a = e.app;
    if (!a) return null;
    if (k === 'applied') return rdDays(e.at, a.submittedAt);
    if (k === 'forward') return rdDays(a.submittedAt, a.screening?.decision?.at);
    if (k === 'verified') return rdDays(a.screening?.decision?.at, Object.values(a.verification?.records ?? {}).map((r) => r.at).sort().pop());
    if (k === 'offered') return rdDays(Object.values(a.verification?.records ?? {}).map((r) => r.at).sort().pop() ?? a.screening?.decision?.at, a.offer?.sentAt);
    if (k === 'activated') return rdDays(a.offer?.sentAt, a.offer?.signature?.at);
    return null;
  };
  const funnel = rows.map((r) => ({ ...r, avgDays: (() => { const xs = cur.filter((e) => rdReached(e, now)[r.stage]).map((e) => timeline(r.stage, e)).filter((x): x is number => x !== null); const m = xs.length >= 3 ? rdMedian(xs) : null; return m === null ? null : Math.round(m * 10) / 10; })() }));
  const flagged = funnel.find((r) => r.flagged);
  const flaggedDetail = flagged ? { stage: flagged.stage, from: counts[RD_FUNNEL[RD_FUNNEL.indexOf(flagged.stage) - 1]], kept: flagged.reached } : null;

  const nowCounts = Object.fromEntries(RD_NOW.map((k) => [k, 0])) as Record<RdNowStage, number>;
  const personNow = Object.fromEntries(RD_NOW.map((k) => [k, [] as DashboardPerson[]])) as Record<RdNowStage, DashboardPerson[]>;
  const personReach = Object.fromEntries(RD_FUNNEL.map((k) => [k, [] as DashboardPerson[]])) as Record<RdRecruitStage, DashboardPerson[]>;
  for (const e of cur) {
    const st = rdNowStage(e, now);
    const id = e.app?.id ?? e.key;
    if (st) {
      nowCounts[st] += 1;
      personNow[st].push({ id, name: e.name, role: e.role, since: e.app?.updatedAt ?? e.at, route: rdRoute(st, id) });
    }
    const f = rdReached(e, now);
    for (const k of RD_FUNNEL) if (f[k]) personReach[k].push({ id, name: e.name, role: e.role, since: e.at, route: rdRoute(k, id) });
  }
  for (const list of [...Object.values(personNow), ...Object.values(personReach)]) list.sort((a, b) => b.since.localeCompare(a.since));
  for (const k of RD_NOW) personNow[k] = personNow[k].slice(0, 50);
  for (const k of RD_FUNNEL) personReach[k] = personReach[k].slice(0, 50);

  const signedIn = (from: number, to: number) => all.filter((e) => within(e.app?.offer?.signature?.at, from, to) || (period === 0 && e.app?.offer?.signature));
  const fullAt = (e: RdEntry) => { const o = e.app?.offer; return o?.activation && Object.values(o.activation.steps).every((x) => x.done) ? Object.values(o.activation.steps).map((x) => x.at ?? '').sort().pop() || o.activation.at : undefined; };
  const act = signedIn(now - span, now);
  const toAct = act.map((e) => rdDays(e.at, e.app?.offer?.signature?.at)).filter((x): x is number => x !== null);
  const toFull = act.map((e) => rdDays(e.at, fullAt(e))).filter((x): x is number => x !== null);
  const appliedIn = (from: number, to: number) => all.filter((e) => (period === 0 ? !!e.app?.submittedAt : within(e.app?.submittedAt, from, to)));
  const decided = cur.filter((e) => e.app?.screening?.decision);
  const approvedN = decided.filter((e) => e.app?.screening?.decision?.status === 'approved').length;
  const oneDecimal = (x: number | null) => (x === null ? null : Math.round(x * 10) / 10);
  const lastSigned = (period === 0 ? [] : signedIn(now - 2 * span, now - span));

  // Territory: the same coverage numbers the territories screen reads (leads and people per zone), against who is on their way.
  const active = zones.filter((z) => z.status === 'active');
  const rawNeed = (z: GeoZone) => z.leadCount / Math.max(0.5, z.assignedUserIds.length);
  const top = Math.max(0, ...active.map(rawNeed));
  const inPipeline = (e: RdEntry) => !!e.app && ['submitted', 'info_requested', 'approved'].includes(e.app.status) && e.app.offer?.status !== 'signed';
  const territories = active.map((z) => {
    const need = top === 0 ? 50 : Math.round((100 * rawNeed(z)) / top);
    const room = rdRoom(z.leadCount, z.assignedUserIds.length);
    const pipeline = all.filter((e) => inPipeline(e) && e.role !== 'supplier' && e.app?.form.territory.zoneIds.includes(z.id)).length;
    return { zoneId: z.id, name: z.name, points: z.points.map((p) => ({ ...p })), leads: z.leadCount, people: z.assignedUserIds.length, need, room, pipeline, signal: rdSignalOf(need, pipeline, room) };
  });

  const channels = [...new Set(cur.map((e) => e.channel))].map((channel) => {
    const list = cur.filter((e) => e.channel === channel);
    const f = list.map((e) => rdReached(e, now));
    return { channel, interested: list.length, applied: f.filter((x) => x.applied).length, activated: f.filter((x) => x.activated).length };
  }).sort((a, b) => b.interested - a.interested);

  const roomFor = (zoneIds: string[]) => zoneIds.filter((z) => territories.some((t) => t.zoneId === z && t.room > 0)).length;
  const suggestWaitlist = all
    .filter((e) => e.role === 'surveyor' && e.app && rdNowStage(e, now) === 'offer' && e.app.form.territory.zoneIds.length > 0 && roomFor(e.app.form.territory.zoneIds) === 0)
    .map((e) => ({ id: (e.app as PartnerApplication).id, name: e.name, zones: names((e.app as PartnerApplication).form.territory.zoneIds) }));
  const waitlist = partnerApplications
    .filter((a) => a.waitlist && a.offer?.status !== 'signed')
    .map((a) => ({ id: a.id, code: a.code, name: a.form.personal.fullName, role: a.role, at: (a.waitlist as NonNullable<typeof a.waitlist>).at, reason: (a.waitlist as NonNullable<typeof a.waitlist>).reason, byName: (a.waitlist as NonNullable<typeof a.waitlist>).byName, zones: names(a.form.territory.zoneIds) }));

  return {
    period,
    funnel,
    flaggedDetail,
    now: nowCounts,
    exits: { rejected: cur.filter((e) => e.app?.status === 'rejected').length, withdrawn: cur.filter((e) => e.app?.status === 'withdrawn').length },
    kpis: {
      timeToActivate: { median: oneDecimal(rdMedian(toAct)), n: toAct.length },
      timeToFull: { median: oneDecimal(rdMedian(toFull)), n: toFull.length },
      waitingOnAdmin: partnerApplications.filter((a) => a.status === 'submitted').length + partnerApplications.filter((a) => a.status === 'approved' && ofStage(a, now) === 'to_prepare').length + partnerApplications.filter((a) => a.offer?.requests.some((r) => !r.response) && a.offer.status === 'sent').length,
      overdueScreening: partnerApplications.filter((a) => a.status === 'submitted' && !!a.submittedAt && now - new Date(a.submittedAt).getTime() > SCREEN_DUE).length,
      approvalRate: decided.length >= RD_SMALL ? Math.round((approvedN / decided.length) * 100) : null,
      interested: { value: cur.length, trend: period === 0 ? null : rdTrend(cur.length, prev.length) },
      applied: { value: appliedIn(now - span, now).length, trend: period === 0 ? null : rdTrend(appliedIn(now - span, now).length, appliedIn(now - 2 * span, now - span).length) },
      activated: { value: act.length, trend: period === 0 ? null : rdTrend(act.length, lastSigned.length) },
    },
    territories,
    channels,
    suggestWaitlist,
    waitlist,
    people: { reach: personReach, now: personNow },
  };
}

/* ============================== Partner tier and category assignment (148) */

const tierCriteria: TierCriteriaVersion[] = (['surveyor', 'technician'] as const).map((role) => ({ id: `tcv-${role}-1`, role, version: 1, effectiveFrom: '2026-01-01', tiers: JSON.parse(JSON.stringify(TIER_DEFAULT_CRITERIA[role])) as TierCriteriaVersion['tiers'], changeNote: 'First criteria.', createdByName: 'Prashant Vasant Wable', createdAt: '2026-01-01T00:00:00.000Z', isDemo: true }));
const partnerTiers: PartnerTierEntry[] = [];
const tierDeferrals: TierDeferral[] = [];
const tierDisputes: TierDispute[] = [];
const tierReviews: TierReview[] = [];
let tierCounter = 0;
let tierSeeded = false;

const tcToday = (now: number) => { const d = new Date(now); const p = (n: number) => String(n).padStart(2, '0'); return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`; };
const tcInForce = (role: 'surveyor' | 'technician', now: number): TierCriteriaVersion => tierCriteria.filter((c) => c.role === role && c.effectiveFrom <= tcToday(now)).sort((a, b) => b.version - a.version)[0];
const tcPartnerRole = (id: string): TierRole | null => {
  const u = byId(users, id);
  if (u && (u.role === 'surveyor' || u.role === 'technician')) return u.role;
  return byId(suppliers, id) ? 'supplier' : null;
};

function tcMetrics(id: string, now: number): Metrics {
  const m: Metrics = { monthsActive: 0, wonDeals: 0, completedInstalls: 0, verifiedSkills: 0, qcPassRate: 0, openSafetyIssues: 0, ratedOrders: 0, score: 0 };
  const sup = byId(suppliers, id);
  if (sup) {
    const { score, rated } = supplierScoreNow(id);
    m.ratedOrders = rated;
    m.score = Math.round((score ?? 0) * 100);
    return m;
  }
  const u = byId(users, id);
  if (!u) return m;
  m.monthsActive = u.joinedAt ? Math.max(0, Math.floor((now - new Date(u.joinedAt).getTime()) / (30 * 86_400_000))) : 0;
  if (u.role === 'surveyor') m.wonDeals = deals.filter((d) => d.status === 'won' && resolveLead(d.leadId)?.originalSurveyorId === id).length;
  if (u.role === 'technician') {
    m.completedInstalls = jobs.filter((j) => j.status === 'completed' && (j.technicianId === id || (j.crew ?? []).some((c) => c.userId === id))).length;
    m.verifiedSkills = normalizeSkills(u.skills).length;
    m.qcPassRate = Math.round(technicianScoreOf(u).qcPassRate * 100);
    m.openSafetyIssues = reworkRequests.filter((r) => r.severity === 'safety_critical' && !['verified', 'waived', 'withdrawn'].includes(r.status) && (r.ownerId === id || byId(jobs, r.jobId)?.technicianId === id)).length;
  }
  return m;
}

/** A serious defect traced to their work lately: a promotion's timing is then Admin's documented call, not a mechanical rule. */
function tcIncidents(id: string, now: number): { code: string; severity: string; at: string }[] {
  return reworkRequests
    .filter((r) => r.severity === 'safety_critical' && now - new Date(r.raisedAt).getTime() < TIER_INCIDENT_WINDOW && (byId(jobs, r.jobId)?.technicianId === id || (byId(jobs, r.jobId)?.crew ?? []).some((c) => c.userId === id)))
    .map((r) => ({ code: r.code, severity: r.severity, at: r.raisedAt }));
}

function tcEnsure(now: number): void {
  if (tierSeeded) return;
  tierSeeded = true;
  const at = new Date(now).toISOString();
  for (const u of users) {
    if ((u.role !== 'surveyor' && u.role !== 'technician') || u.status !== 'active') continue;
    if (partnerTiers.some((e) => e.userId === u.id)) continue;
    const role = u.role;
    const v = tcInForce(role, now);
    const m = tcMetrics(u.id, now);
    // People already working unrestricted keep working: no existing technician is made a trainee by an assessment they never saw.
    const idx = Math.max(tierEligible(v.tiers, m), role === 'technician' ? 1 : 0);
    tierCounter += 1;
    partnerTiers.push({ id: `pte-${tierCounter}`, userId: u.id, role, tier: TIER_IDS_OF[role][idx], fromTier: null, effectiveFrom: (u.joinedAt ?? at).slice(0, 10), kind: 'initial', reason: 'Starting tier, read from the criteria as they stood when tiers were introduced.', byName: 'AIEC', at: u.joinedAt ?? at, criteriaVersion: v.version, met: tierEvaluate(v.tiers[idx].criteria, m), isDemo: true });
  }
  // A little history so the screen has something to read: one earlier promotion and one open question about a tier.
  const t2 = byId(users, 'u-tech-2');
  if (t2) {
    const first = partnerTiers.find((e) => e.userId === 'u-tech-2');
    if (first) {
      first.tier = 'trainee';
      first.fromTier = null;
      tierCounter += 1;
      const when = new Date(now - 100 * 86_400_000).toISOString();
      const v = tcInForce('technician', now);
      partnerTiers.push({ id: `pte-${tierCounter}`, userId: 'u-tech-2', role: 'technician', tier: 'certified', fromTier: 'trainee', effectiveFrom: when.slice(0, 10), kind: 'promotion', reason: 'Completed his first installations without rework and his skills were checked.', byName: 'Prashant Vasant Wable', at: when, criteriaVersion: v.version, met: tierEvaluate(v.tiers[1].criteria, tcMetrics('u-tech-2', now)), isDemo: true });
    }
  }
  if (byId(users, 'u-tech-3')) {
    tierCounter += 1;
    tierDisputes.push({ id: `td-${tierCounter}`, userId: 'u-tech-3', grounds: 'I have finished more installations than the record shows, so I think I already meet the next tier.', raisedAt: new Date(now - 36 * 3_600_000).toISOString(), raisedByName: 'Prashant Vasant Wable', criteriaVersion: 1, tierAtRaise: partnerTiers.find((e) => e.userId === 'u-tech-3')?.tier ?? 'certified', status: 'open', isDemo: true });
  }
}

function tcCurrentEntry(id: string, now: number): { current: PartnerTierEntry | null; pending: PartnerTierEntry | null } {
  const today = tcToday(now);
  const list = partnerTiers.filter((e) => e.userId === id).sort((a, b) => (a.effectiveFrom + a.at).localeCompare(b.effectiveFrom + b.at));
  const live = list.filter((e) => e.effectiveFrom <= today);
  const later = list.filter((e) => e.effectiveFrom > today);
  return { current: live[live.length - 1] ?? null, pending: later[later.length - 1] ?? null };
}

/** The tier in force for a partner right now: what commission and lead authority read. A surveyor with no record is on the first tier; a technician on the second (they already work unrestricted). */
function tierNow(id: string, now = Date.now()): string {
  const sup = byId(suppliers, id);
  if (sup) return tierOf(sup);
  tcEnsure(now);
  const role = tcPartnerRole(id);
  return tcCurrentEntry(id, now).current?.tier ?? (role === 'technician' ? 'certified' : 'new');
}
const tcEffectsOf = (role: 'surveyor' | 'technician', tier: string, now: number): TierEffects => tcInForce(role, now).tiers.find((t) => t.id === tier)?.effects ?? {};

/** A surveyor's conversion share: what their signed agreement says (146), plus what their tier adds. */
function surveyorConversionPct(userId: string): number {
  const offer = partnerApplications.find((a) => a.offer?.activation?.userId === userId)?.offer;
  const base = offer?.status === 'signed' ? ofBinding(offer).conversionPct ?? TIER_BASE_PCT : TIER_BASE_PCT;
  const plus = byId(users, userId)?.role === 'surveyor' ? tcEffectsOf('surveyor', tierNow(userId), Date.now()).commissionPlusPct ?? 0 : 0;
  return Math.round((base + plus) * 100) / 100;
}
const tcCanLead = (userId: string): boolean => (byId(users, userId)?.role === 'technician' ? tcEffectsOf('technician', tierNow(userId), Date.now()).canLead !== false : true);

/** A newly activated field partner starts on the tier their record already earns: a technician with no installations is a trainee until the criteria say otherwise. */
function tcInitial(userId: string, role: 'surveyor' | 'technician', at: string): void {
  const now = Date.parse(at);
  const v = tcInForce(role, now);
  const m = tcMetrics(userId, now);
  const idx = tierEligible(v.tiers, m);
  tierCounter += 1;
  partnerTiers.push({ id: `pte-${tierCounter}`, userId, role, tier: TIER_IDS_OF[role][idx], fromTier: null, effectiveFrom: at.slice(0, 10), kind: 'initial', reason: 'Starting tier when the agreement was signed.', byName: 'AIEC', at, criteriaVersion: v.version, met: tierEvaluate(v.tiers[idx].criteria, m), isDemo: true });
}

function tcRowOf(id: string, now: number): PartnerTierRowView {
  tcEnsure(now);
  const role = tcPartnerRole(id) as TierRole;
  const name = byId(users, id)?.name ?? byId(suppliers, id)?.name ?? id;
  const defer = tierDeferrals.find((d) => d.userId === id && d.until >= tcToday(now));
  const review = tierReviews.some((r) => r.userId === id && !r.resolved);
  const disputeOpen = tierDisputes.some((d) => d.userId === id && d.status === 'open');
  if (role === 'supplier') {
    const sup = byId(suppliers, id) as Supplier;
    const { score, rated } = supplierScoreNow(id);
    const tier = tierOf(sup);
    const grad = graduationFor(tier, score ?? 0, rated);
    const last = supplierTermsHistory.filter((c) => c.supplierId === id && c.kind === 'tier').sort((a, b) => b.at.localeCompare(a.at))[0];
    return { id, name, role, tier, since: last?.at ?? sup.invitedAt ?? '', eligibleTier: grad ?? tier, promotionDue: !!grad && !defer, incident: false, deferred: !!defer, reviewDue: false, disputeOpen, pending: null };
  }
  const v = tcInForce(role, now);
  const m = tcMetrics(id, now);
  const { current, pending } = tcCurrentEntry(id, now);
  const cur = current?.tier ?? (role === 'technician' ? 'certified' : 'new');
  const idx = tierEligible(v.tiers, m);
  const incident = tcIncidents(id, now).length > 0;
  return { id, name, role, tier: cur, since: current?.effectiveFrom ?? '', eligibleTier: TIER_IDS_OF[role][idx], promotionDue: idx > tierIndexOf(role, cur) && !defer && !pending, incident, deferred: !!defer, reviewDue: review, disputeOpen, pending: pending ? { tier: pending.tier, effectiveFrom: pending.effectiveFrom } : null };
}

function tcDetailOf(id: string, now: number): PartnerTierDetailView {
  const row = tcRowOf(id, now);
  const role = row.role;
  const m = tcMetrics(id, now);
  const sup = byId(suppliers, id);
  const u = byId(users, id);
  let ladder: TierLadderRowView[];
  let criteria: PartnerTierDetailView['criteria'];
  if (role === 'supplier') {
    const crit = tierSupplierCriteria();
    ladder = TIER_IDS_OF.supplier.map((tid, i): TierLadderRowView => { const r = i === 0 ? [] : tierEvaluate(crit, m); return { id: tid, criteria: r, met: r.every((x) => x.ok), effects: {}, current: tid === row.tier, eligible: tid === row.eligibleTier }; });
    criteria = { version: 1, effectiveFrom: '2026-01-01', owner: 'supplier_terms' };
  } else {
    const v = tcInForce(role, now);
    ladder = v.tiers.map((t): TierLadderRowView => { const r = tierEvaluate(t.criteria, m); return { id: t.id, criteria: r, met: r.every((x) => x.ok), effects: { ...t.effects }, current: t.id === row.tier, eligible: t.id === row.eligibleTier }; });
    criteria = { version: v.version, effectiveFrom: v.effectiveFrom, owner: 'tiers' };
  }
  const history: TierHistoryItem[] = role === 'supplier'
    ? supplierTermsHistory.filter((c) => c.supplierId === id && c.kind === 'tier').map((c) => ({ id: c.id, at: c.at, from: c.fromTier ?? null, to: c.toTier as string, kind: 'supplier_terms' as const, reason: c.reason, byName: c.by, effectiveFrom: c.at.slice(0, 10), criteriaVersion: null, met: [], incidentAcknowledged: false }))
    : partnerTiers.filter((e) => e.userId === id).map((e) => ({ id: e.id, at: e.at, from: e.fromTier, to: e.tier, kind: e.kind, reason: e.reason, byName: e.byName, effectiveFrom: e.effectiveFrom, criteriaVersion: e.criteriaVersion, met: e.met.map((x) => ({ ...x })), incidentAcknowledged: !!e.incidentAcknowledged }));
  history.sort((a, b) => b.at.localeCompare(a.at));
  const defer = tierDeferrals.find((d) => d.userId === id && d.until >= tcToday(now));
  return {
    row,
    partner: { name: row.name, phone: u?.phone ?? sup?.contactPhone ?? '', city: u?.city ?? sup?.city ?? '', joinedAt: u?.joinedAt ?? sup?.invitedAt ?? null },
    metrics: m,
    ladder,
    criteria,
    paymentDefaults: sup ? effectiveSettings(sup, paymentTermsConfig).settings : null,
    history,
    deferral: defer ? { ...defer } : null,
    incidents: role === 'supplier' ? [] : tcIncidents(id, now),
    review: tierReviews.find((r) => r.userId === id && !r.resolved) ?? null,
    disputes: tierDisputes.filter((d) => d.userId === id).map((d) => ({ ...d, decision: d.decision ? { ...d.decision } : undefined })).sort((a, b) => b.raisedAt.localeCompare(a.raisedAt)),
  };
}

/** One path for every tier change, field partners and suppliers alike: the criteria are read the same way and the reason is always kept. */
function tcAssign(id: string, input: { tier: string; reason: string; effectiveFrom: string; exception?: boolean; incidentAcknowledged?: boolean; kind?: PartnerTierEntry['kind'] }, byName: string, now: number): void {
  const role = tcPartnerRole(id);
  if (!role) throw new RepositoryError('not_found');
  if (input.reason.replace(/[^\p{L}\p{N}]/gu, '').length < TIER_REASON_MIN) throw new RepositoryError('reason_required');
  if (!TIER_IDS_OF[role].includes(input.tier)) throw new RepositoryError('tier_required');
  const today = tcToday(now);
  const limit = tcToday(now + TIER_EFFECTIVE_MAX_DAYS * 86_400_000);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(input.effectiveFrom) || input.effectiveFrom < today || input.effectiveFrom > limit || (role === 'supplier' && input.effectiveFrom !== today)) throw new RepositoryError('effective_invalid');
  const row = tcRowOf(id, now);
  if (row.tier === input.tier && !row.pending) throw new RepositoryError('same_tier');
  const dir = tierDirection(role, row.tier, input.tier);
  const m = tcMetrics(id, now);
  const at = new Date(now).toISOString();
  if (role === 'supplier') {
    const sup = byId(suppliers, id) as Supplier;
    const { score, rated } = supplierScoreNow(id);
    if (dir === 'up' && !input.exception && graduationFor(tierOf(sup), score ?? 0, rated) !== input.tier) throw new RepositoryError('criteria_not_met');
    recordTermsChange({ supplierId: id, kind: 'tier', fromTier: tierOf(sup), toTier: input.tier as SupplierTrustTier, reason: input.reason.trim(), scoreAtChange: score, ratedOrdersAtChange: rated, by: byName, at });
    patchInPlace(suppliers, id, { paymentTier: input.tier as SupplierTrustTier });
    return;
  }
  const v = tcInForce(role, now);
  const idx = tierIndexOf(role, input.tier);
  const all = v.tiers.slice(1, idx + 1).flatMap((t) => tierEvaluate(t.criteria, m));
  const metCriteria = dir === 'up' ? all.every((r) => r.ok) : true;
  if (dir === 'up' && !metCriteria && !input.exception) throw new RepositoryError('criteria_not_met');
  const incident = tcIncidents(id, now).length > 0;
  if (dir === 'up' && incident && !input.incidentAcknowledged) throw new RepositoryError('incident_ack_required');
  tierCounter += 1;
  partnerTiers.push({ id: `pte-${tierCounter}`, userId: id, role, tier: input.tier, fromTier: row.tier, effectiveFrom: input.effectiveFrom, kind: input.kind ?? (dir === 'down' ? 'demotion' : metCriteria ? 'promotion' : 'exception'), reason: input.reason.trim(), byName, at, criteriaVersion: v.version, met: tierEvaluate(v.tiers[idx].criteria, m), ...(incident && input.incidentAcknowledged ? { incidentAcknowledged: true } : {}), isDemo: true });
  if (dir === 'up') for (let i = tierDeferrals.length - 1; i >= 0; i -= 1) if (tierDeferrals[i].userId === id) tierDeferrals.splice(i, 1);
}

/* ============================== Partner directory (149) */

const partnerTerritoryChanges: PartnerTerritoryChange[] = [];
let territoryChangeCounter = 0;
const PD_REASON_MIN = 15;

/** An exit under way shows on the directory row: still active, but being handed on. */
const exitingOf = (id: string): { lastDay: string; kind: ExitKind } | null => { const e = partnerExits.find((x) => x.partnerId === id && x.status === 'in_progress'); return e ? { lastDay: e.lastDay, kind: e.kind } : null; };
const pdStatusOf = (s: string): DirectoryStatus => (s === 'active' ? 'active' : s === 'suspended' ? 'deactivated' : s === 'rejected' ? 'rejected' : 'pending');
const pdPhoneKey = (phone: string | undefined) => (phone ?? '').replace(/\D/g, '').slice(-10);

/** One directory record per role a person holds; nothing here is stored, every figure is read from the record the role's own screen keeps. */
function pdRolesOf(now: number): { phone: string; name: string; role: DirectoryRoleView }[] {
  tcEnsure(now);
  const out: { phone: string; name: string; role: DirectoryRoleView }[] = [];
  for (const u of users) {
    if (u.role !== 'surveyor' && u.role !== 'technician') continue;
    const app = partnerApplications.find((a) => a.offer?.activation?.userId === u.id);
    const base = { partnerId: u.id, status: pdStatusOf(u.status), tier: tierNow(u.id, now), city: u.city ?? '', joinedAt: u.joinedAt ?? null, applicationId: app?.id ?? null, exiting: exitingOf(u.id) };
    if (u.role === 'surveyor') {
      const mine = leads.filter((l) => l.surveyorId === u.id);
      out.push({ phone: u.phone, name: u.name, role: { ...base, type: 'surveyor', territory: zones.filter((z) => z.assignedUserIds.includes(u.id)).map((z) => ({ kind: 'zone' as const, value: z.name })), perf: { leads: mine.length, won: deals.filter((d) => d.status === 'won' && resolveLead(d.leadId)?.originalSurveyorId === u.id).length }, inFlight: mine.filter((l) => l.stage !== 'won' && l.stage !== 'lost').length, profileRoute: `/admin/tracking/surveyor/${u.id}` } });
    } else {
      const own = jobs.filter((j) => j.technicianId === u.id || (j.crew ?? []).some((c) => c.userId === u.id));
      const sc = technicianScoreOf(u);
      out.push({ phone: u.phone, name: u.name, role: { ...base, type: 'technician', territory: normalizeSkills(u.skills).map((v) => ({ kind: 'skill' as const, value: v })), perf: { jobsCompleted: sc.jobsCompleted, qcPassRate: sc.jobsCompleted ? Math.round(sc.qcPassRate * 100) : null }, inFlight: own.filter((j) => j.status !== 'completed').length, profileRoute: `/admin/tracking/technician/${u.id}` } });
    }
  }
  for (const sup of suppliers) {
    if (sup.mergedIntoSupplierId) continue;
    const portal = supplierUserFor(sup);
    const { score, rated } = supplierScoreNow(sup.id);
    const open = supplierPurchaseOrders.filter((po) => po.supplierId === sup.id && po.status === 'sent' && poStageOf(po) !== 'delivered').length;
    out.push({ phone: portal?.phone ?? sup.contactPhone ?? '', name: sup.name, role: { type: 'supplier', partnerId: sup.id, status: pdStatusOf(sup.status), tier: tierOf(sup), city: sup.city, joinedAt: portal?.joinedAt ?? sup.invitedAt ?? null, applicationId: partnerApplications.find((a) => a.offer?.activation?.supplierId === sup.id)?.id ?? null, exiting: exitingOf(sup.id), territory: sup.categories.map((v) => ({ kind: 'category' as const, value: v })), perf: { score: score === null ? null : Math.round(score * 100), rated, onTimeRate: rated ? Math.round(sup.onTimeRate * 100) : null }, inFlight: open, profileRoute: `/scorecard?supplierId=${sup.id}` } });
  }
  return out;
}

function pdRows(now: number): PartnerDirectoryRowView[] {
  const byKey = new Map<string, PartnerDirectoryRowView>();
  for (const r of pdRolesOf(now)) {
    const key = pdPhoneKey(r.phone) ? `p:${pdPhoneKey(r.phone)}` : `r:${r.role.partnerId}`;
    const row = byKey.get(key) ?? { key, name: r.name, phone: r.phone, city: r.role.city, roles: [] };
    row.roles.push(r.role);
    byKey.set(key, row);
  }
  return [...byKey.values()];
}

const pdHaystack = (row: PartnerDirectoryRowView) => [row.name, row.phone, pdPhoneKey(row.phone), row.city, ...row.roles.flatMap((r) => [r.partnerId, r.type, r.city, r.tier, ...r.territory.map((t) => t.value)])].join(' ').toLowerCase();

function pdFilter(rows: PartnerDirectoryRowView[], f: PartnerDirectoryFilter, skip?: 'type' | 'status'): PartnerDirectoryRowView[] {
  const tokens = (f.query ?? '').toLowerCase().split(/\s+/).filter(Boolean);
  const zone = f.zoneId ? byId(zones, f.zoneId)?.name : undefined;
  const [tierType, tierId] = (f.tier ?? '').split(':');
  return rows.filter((row) => {
    if (tokens.length && !tokens.every((t) => pdHaystack(row).includes(t))) return false;
    return row.roles.some((r) => (skip === 'type' || !f.type || f.type === 'all' || r.type === f.type) && (skip === 'status' || !f.status || f.status === 'all' || r.status === f.status) && (!tierId || (r.type === tierType && r.tier === tierId)) && (!zone || r.territory.some((t) => t.kind === 'zone' && t.value === zone)));
  });
}

function pdProfile(key: string, now: number): PartnerDirectoryProfileView {
  const row = pdRows(now).find((r) => r.key === key);
  if (!row) throw new RepositoryError('not_found');
  const surveyor = row.roles.find((r) => r.type === 'surveyor');
  const ids = row.roles.map((r) => r.partnerId);
  return {
    row,
    zoneOptions: surveyor ? zones.filter((z) => z.status === 'active').map((z) => ({ id: z.id, name: z.name, assigned: z.assignedUserIds.includes(surveyor.partnerId) })) : [],
    changes: partnerTerritoryChanges.filter((c) => ids.includes(c.partnerId)).sort((a, b) => b.at.localeCompare(a.at)).slice(0, 5),
  };
}

/* ============================== Training module library (151) */

const trainingModules: TrainingModule[] = seedTrainingModules.map((x) => ({ ...x, versions: x.versions.map((v) => ({ ...v })) }));
const trainingProgress: TrainingProgress[] = seedTrainingProgress.map((x) => ({ ...x }));
const trainingLessons: TrainingLesson[] = seedTrainingLessons;
const assessments: Assessment[] = seedAssessments.map((a) => ({ ...a, cooldownHours: [...a.cooldownHours] as [number, number, number], questions: a.questions.map((x) => ({ ...x, correct: [...x.correct] })) }));
const assessmentAttempts: AssessmentAttempt[] = seedAssessmentAttempts.map((a) => ({ ...a, questionIds: [...a.questionIds], answers: a.answers.map((x) => ({ questionId: x.questionId, selected: [...x.selected] })) }));
const certBadges: CertificationBadge[] = seedCertBadges.map((b) => ({ ...b }));
let assessmentAttemptCounter = 100;
let certCounter = 1100;
const certPrefs: CertificationPref[] = [];
const lessonProgress: TrainingLessonProgress[] = seedTrainingLessonProgress.map((x) => ({ ...x, checks: x.checks.map((c) => ({ ...c, attempts: c.attempts.map((a) => ({ ...a })) })) }));

/** One person across every role they hold (149 groups them the same way, by phone): what they have done in one account counts in another. */
function tnPersonOf(userId: string): { name: string; roles: TrainingRole[]; userIds: string[] } | null {
  const u = byId(users, userId);
  if (!u || (u.role !== 'surveyor' && u.role !== 'technician' && u.role !== 'supplier')) return null;
  const key = pdPhoneKey(u.phone);
  const same = key ? users.filter((x) => pdPhoneKey(x.phone) === key && (x.role === 'surveyor' || x.role === 'technician' || x.role === 'supplier') && x.status !== 'rejected') : [u];
  const roles = new Set<TrainingRole>(same.filter((x) => x.status === 'active' || x.id === userId).map((x) => x.role as TrainingRole));
  for (const sup of suppliers) if (!sup.mergedIntoSupplierId && sup.status === 'active' && key && pdPhoneKey(supplierUserFor(sup)?.phone ?? sup.contactPhone) === key) roles.add('supplier');
  return { name: u.name, roles: [...roles], userIds: same.map((x) => x.id) };
}

function tnProgressOf(userIds: string[], moduleId: string): TrainingProgress | undefined {
  const mine = trainingProgress.filter((p) => p.moduleId === moduleId && userIds.includes(p.userId));
  return mine.filter((p) => p.status === 'completed').sort((a, b) => b.version - a.version)[0] ?? mine[0];
}

function tnStatusFn(userIds: string[], now: number) {
  return (id: string): ModuleStatus => { const m = byId(trainingModules, id); return m ? tnStatus(m, tnProgressOf(userIds, id), now) : 'not_started'; };
}

function tnViewOf(m: TrainingModule, person: { roles: TrainingRole[]; userIds: string[] }, now: number): TrainingModuleView {
  const p = tnProgressOf(person.userIds, m.id);
  const status = tnStatusFn(person.userIds, now);
  const st = status(m.id);
  const v = tnCurrentVersion(m, now);
  const locked = tnLockedBy(m, trainingModules, status);
  return {
    id: m.id, code: m.code, topic: m.topic, order: m.order, required: tnRequired(m, person.roles), forMe: tnRelevant(m, person.roles), forRoles: [...m.relevantFor], minutes: m.minutes, lessons: m.lessons, offlineKb: m.offlineKb,
    version: v.version, changeKey: v.version > 1 ? v.changeKey ?? null : null, status: st, updatedSince: tnUpdated(m, p, now), lessonsDone: p?.lessonsDone ?? 0, percent: tnPercent(m, p, st),
    completedAt: p?.status === 'completed' ? p.completedAt ?? null : null, completedVersion: p?.status === 'completed' ? p.version : null,
    lockedBy: locked.map((x) => ({ id: x.id, code: x.code })), gatesJobAssignment: m.gatesJobAssignment && tnRequired(m, ['technician']),
    hasContent: trainingLessons.some((l) => l.moduleId === m.id),
    assessment: asSummaryOf(m, person.userIds, now),
  };
}

/* ---- lessons (152) */

/** What one person has recorded on one lesson: the finished record first, else the latest. People who hold two roles (one phone) share their work. */
function tnLessonRowOf(userIds: string[], lessonId: string): TrainingLessonProgress | undefined {
  const mine = lessonProgress.filter((p) => p.lessonId === lessonId && userIds.includes(p.userId));
  return mine.filter((p) => p.completedAt).sort((a, b) => b.version - a.version)[0] ?? mine.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))[0];
}

function tnLessonViewOf(l: TrainingLesson, m: TrainingModule, userIds: string[], states: Record<string, 'done' | 'current' | 'locked'>, now: number): LessonView {
  const own = tnLessonRowOf(userIds, l.id);
  const mod = tnProgressOf(userIds, m.id);
  const counts = tnStatus(m, mod, now) === 'completed';
  const state = states[l.id] ?? 'locked';
  const cleared = state === 'done' ? l.checks.map((c) => c.id) : lsCleared(own);
  const total = lsDuration(l);
  const done = state === 'done';
  const clamped = lsClamp(l, cleared, own?.positionS ?? 0, own?.furthestS ?? 0);
  return {
    id: l.id, moduleId: l.moduleId, order: l.order, durationS: total,
    scenes: l.scenes.map((x, i) => ({ id: x.id, durationS: x.durationS, startS: lsSceneStart(l, i), visual: x.visual })),
    checks: l.checks.map((c) => ({ id: c.id, afterScene: c.afterScene, atS: lsCheckAt(l, c), kind: c.kind, options: c.options, cleared: cleared.includes(c.id), attempts: own?.checks.find((r) => r.checkId === c.id)?.attempts.length ?? 0 })),
    points: l.points, state, updated: lsUpdated(l, own, mod, counts), changedInVersion: l.changedInVersion,
    // A finished lesson opens at its start for a replay; one in hand resumes exactly where it was left.
    positionS: done ? 0 : clamped.positionS, furthestS: done ? total : clamped.furthestS, allowedS: done ? total : lsAllowed(l, cleared),
    completedAt: done ? own?.completedAt ?? mod?.completedAt ?? null : null,
  };
}

function tnModuleLessonsOf(m: TrainingModule, person: { roles: TrainingRole[]; userIds: string[] }, now: number): ModuleLessonsView {
  const lessons = trainingLessons.filter((l) => l.moduleId === m.id).sort((a, b) => a.order - b.order);
  const mod = tnProgressOf(person.userIds, m.id);
  const counts = tnStatus(m, mod, now) === 'completed';
  const states = lsStates(lessons, (l) => lsDone(l, tnLessonRowOf(person.userIds, l.id), mod, counts));
  const done = lessons.filter((l) => states[l.id] === 'done').length;
  const st = tnStatus(m, mod, now);
  const v = tnCurrentVersion(m, now);
  return {
    module: { id: m.id, code: m.code, topic: m.topic, version: v.version, status: st, minutes: m.minutes, required: tnRequired(m, person.roles), gatesJobAssignment: m.gatesJobAssignment && tnRequired(m, ['technician']), changeKey: v.version > 1 ? v.changeKey ?? null : null, assessment: asSummaryOf(m, person.userIds, now) },
    lessons: lessons.map((l) => tnLessonViewOf(l, m, person.userIds, states, now)),
    lessonsDone: done,
    percent: lessons.length ? Math.round((done / lessons.length) * 100) : 0,
    moduleDone: lessons.length > 0 && done === lessons.length && st !== 'update_needed' && st !== 'not_started',
    at: new Date(now).toISOString(),
  };
}

/** A lesson can be opened by someone the module is shown to, once what it builds on is done. */
function tnLessonAccess(lessonId: string, userId: string, now: number) {
  const person = tnPersonOf(userId);
  if (!person) throw new RepositoryError('forbidden');
  const l = byId(trainingLessons, lessonId);
  const m = l ? byId(trainingModules, l.moduleId) : undefined;
  if (!l || !m) throw new RepositoryError('not_found');
  const status = tnStatusFn(person.userIds, now);
  const problem = tnStartProblem(m, person.roles, tnLockedBy(m, trainingModules, status));
  if (problem) throw new RepositoryError(problem);
  const view = tnModuleLessonsOf(m, person, now);
  const lv = view.lessons.find((x) => x.id === lessonId) as LessonView;
  if (lv.state === 'locked') throw new RepositoryError('locked');
  return { person, l, m, lv, view };
}

/** The person's own working row for a lesson, created when they begin it (on the version in force now, so a retake is recorded as one). */
function tnLessonRowForWrite(userId: string, l: TrainingLesson, version: number, at: string): TrainingLessonProgress {
  let row = lessonProgress.find((p) => p.userId === userId && p.lessonId === l.id);
  if (!row) {
    row = { userId, lessonId: l.id, moduleId: l.moduleId, version, positionS: 0, furthestS: 0, checks: [], startedAt: at, updatedAt: at };
    lessonProgress.push(row);
  } else if (row.completedAt && row.version < l.changedInVersion) {
    // A lesson that has changed since it was finished begins afresh: what was finished stays in the history of the version it was taken on.
    row.version = version; row.completedAt = undefined; row.positionS = 0; row.furthestS = 0; row.checks = []; row.startedAt = at;
  } else if (!row.completedAt) row.version = version;
  return row;
}

/** Brings the module's own progress row in line with its lessons: how many are done, and finished only when all are. */
function tnSyncModuleProgress(m: TrainingModule, userId: string, person: { roles: TrainingRole[]; userIds: string[] }, now: number): void {
  const lessons = trainingLessons.filter((l) => l.moduleId === m.id);
  if (lessons.length === 0) return;
  const at = new Date(now).toISOString();
  const version = tnCurrentVersion(m, now).version;
  const view = tnModuleLessonsOf(m, person, now);
  const own = trainingProgress.find((p) => p.userId === userId && p.moduleId === m.id);
  const allDone = view.lessonsDone === lessons.length;
  if (own) {
    if (own.status === 'completed' && tnStatus(m, own, now) === 'completed') return;
    Object.assign(own, allDone ? { status: 'completed', version, lessonsDone: lessons.length, completedAt: at } : { status: 'in_progress', version, lessonsDone: view.lessonsDone, completedAt: undefined });
  } else trainingProgress.push({ userId, moduleId: m.id, status: allDone ? 'completed' : 'in_progress', startedAt: at, ...(allDone ? { completedAt: at } : {}), version, lessonsDone: view.lessonsDone });
}

/* ---- assessments (154) */

const asOf = (moduleId: string) => assessments.find((a) => a.moduleId === moduleId);
const ASSESSMENT_ALERT = 'assessment.alert.struggling';

/** The person's current certification for a module: the newest one that still counts for the module as it reads now and has not run out. */
function asBadgeOf(userIds: string[], m: TrainingModule, now: number): CertificationBadge | undefined {
  const min = tnCurrentVersion(m, now).minVersion;
  return certBadges.filter((b) => b.moduleId === m.id && userIds.includes(b.userId) && asBadgeValid(b, min) && (!b.expiresAt || Date.parse(b.expiresAt) > now)).sort((a, b) => b.issuedAt.localeCompare(a.issuedAt))[0];
}

/** A certification close to its end (or whose module is still current but whose badge ran out) can be renewed by passing the test again. */
function asRenewable(b: CertificationBadge | undefined, now: number): boolean {
  return !!b && !!b.expiresAt && Date.parse(b.expiresAt) - now <= AS_RENEW_DAYS * 86_400_000;
}

/** True when the module has no test, or the test is passed. */
function asCertified(userIds: string[], moduleId: string, now: number): boolean {
  const a = asOf(moduleId);
  const m = byId(trainingModules, moduleId);
  if (!a || !m) return true;
  return !!asBadgeOf(userIds, m, now);
}

const asAttemptsOf = (userIds: string[], assessmentId: string, version: number) => assessmentAttempts.filter((x) => x.assessmentId === assessmentId && userIds.includes(x.userId) && x.version === version);

function asStateOf(m: TrainingModule, a: Assessment, userIds: string[], now: number): { state: AssessmentStateName; cooldownUntil: string | null; failed: number; attempts: AssessmentAttempt[]; renewable: boolean } {
  const version = tnCurrentVersion(m, now).version;
  const attempts = asAttemptsOf(userIds, a.id, version);
  const failed = asFailsSince(attempts);
  const submitted = attempts.filter((x) => x.status === 'submitted').sort((x, y) => (y.submittedAt ?? '').localeCompare(x.submittedAt ?? ''));
  const cooldownUntil = asCooldownUntil(submitted[0]?.submittedAt ?? null, a.cooldownHours, failed);
  const badge = asBadgeOf(userIds, m, now);
  const renewable = asRenewable(badge, now);
  if (badge) return { state: 'certified', cooldownUntil: cooldownUntil && Date.parse(cooldownUntil) > now ? cooldownUntil : null, failed, attempts, renewable };
  if (tnStatus(m, tnProgressOf(userIds, m.id), now) !== 'completed') return { state: 'locked', cooldownUntil: null, failed, attempts, renewable: false };
  if (attempts.some((x) => x.status === 'in_progress')) return { state: 'in_progress', cooldownUntil: null, failed, attempts, renewable: false };
  if (cooldownUntil && Date.parse(cooldownUntil) > now) return { state: 'cooldown', cooldownUntil, failed, attempts, renewable: false };
  return { state: 'to_take', cooldownUntil: null, failed, attempts, renewable: false };
}

function asSummaryOf(m: TrainingModule, userIds: string[], now: number): TrainingModuleView['assessment'] {
  const a = asOf(m.id);
  if (!a) return null;
  const st = asStateOf(m, a, userIds, now);
  const badge = asBadgeOf(userIds, m, now);
  // A badge that ran out is no longer "certified": the state above is then to-take, and the renewal says why.
  const lapsed = !badge && certBadges.some((b) => b.moduleId === m.id && userIds.includes(b.userId) && b.expiresAt && Date.parse(b.expiresAt) <= now && asBadgeValid(b, tnCurrentVersion(m, now).minVersion));
  return { state: st.state, passPercent: a.passPercent, cooldownUntil: st.cooldownUntil, renewal: lapsed ? 'expired' : st.renewable ? 'due_soon' : 'none', expiresAt: badge?.expiresAt ?? null };
}

function asResultOf(att: AssessmentAttempt, a: Assessment, m: TrainingModule, person: { roles: TrainingRole[]; userIds: string[] }, now: number): AssessmentResultView {
  const questions = att.questionIds.map((id) => a.questions.find((q) => q.id === id)).filter((q): q is NonNullable<typeof q> => !!q);
  const scored = asScore(questions, att.answers);
  const badge = certBadges.find((b) => b.attemptId === att.id);
  const review: AssessmentReviewRow[] = scored.perQuestion.map((r) => {
    const q = questions.find((x) => x.id === r.questionId) as (typeof questions)[number];
    return { questionId: q.id, kind: q.kind, options: q.options, selected: r.selected, correct: r.correct, correctAnswer: [...q.correct] };
  });
  const failed = asFailsSince(asAttemptsOf(person.userIds, a.id, att.version));
  const next = att.passed ? null : asCooldownUntil(att.submittedAt ?? null, a.cooldownHours, failed);
  const technician = person.roles.includes('technician');
  return {
    attemptId: att.id, moduleId: m.id, moduleCode: m.code, version: att.version, attemptNumber: att.attemptNumber, score: att.score ?? scored.score, correctCount: att.correctCount ?? scored.correctCount, total: scored.total, passPercent: att.passPercent ?? a.passPercent,
    passed: !!att.passed, submittedAt: att.submittedAt ?? att.updatedAt, review, badge: badge ? { id: badge.id, issuedAt: badge.issuedAt } : null, nextAttemptAt: next, coaching: asStruggling(failed, !!asBadgeOf(person.userIds, m, now)),
    gatesJobAssignment: m.gatesJobAssignment && tnRequired(m, ['technician']), jobGateCleared: technician ? trainingClear(att.userId, now) : null,
  };
}

function asView(m: TrainingModule, a: Assessment, person: { roles: TrainingRole[]; userIds: string[] }, now: number): AssessmentView {
  const st = asStateOf(m, a, person.userIds, now);
  const version = tnCurrentVersion(m, now).version;
  const submitted = st.attempts.filter((x) => x.status === 'submitted').sort((x, y) => (y.submittedAt ?? '').localeCompare(x.submittedAt ?? ''));
  const open = st.attempts.find((x) => x.status === 'in_progress');
  const badge = asBadgeOf(person.userIds, m, now);
  const all = assessmentAttempts.filter((x) => x.assessmentId === a.id && person.userIds.includes(x.userId));
  return {
    assessmentId: a.id, moduleId: m.id, moduleCode: m.code, topic: m.topic, version, passPercent: a.passPercent, cooldownHours: [...a.cooldownHours] as [number, number, number], questionCount: asQuestions(a, version).length, state: st.state,
    attemptsThisVersion: st.attempts.filter((x) => x.status === 'submitted').length, failedThisVersion: st.failed, nextAttemptNumber: all.length + 1, cooldownUntil: st.cooldownUntil,
    badge: badge ? { id: badge.id, issuedAt: badge.issuedAt, score: badge.score, version: badge.version, expiresAt: badge.expiresAt, code: badge.code } : null,
    canRenew: st.renewable, validMonths: a.validMonths, renewal: asSummaryOf(m, person.userIds, now)?.renewal ?? 'none',
    lastExpiredAt: certBadges.filter((b) => b.moduleId === m.id && person.userIds.includes(b.userId) && b.expiresAt && Date.parse(b.expiresAt) <= now).map((b) => b.expiresAt as string).sort().pop() ?? null,
    history: all.filter((x) => x.status === 'submitted').sort((x, y) => (x.submittedAt ?? '').localeCompare(y.submittedAt ?? '')).map((x) => ({ attemptNumber: x.attemptNumber, score: x.score ?? 0, passed: !!x.passed, submittedAt: x.submittedAt ?? x.updatedAt, version: x.version })),
    last: submitted[0] ? asResultOf(submitted[0], a, m, person, now) : null,
    draft: open ? { attemptId: open.id, answers: open.answers.map((x) => ({ questionId: x.questionId, selected: [...x.selected] })), startedAt: open.startedAt } : null,
    gatesJobAssignment: m.gatesJobAssignment && tnRequired(m, ['technician']), coaching: asStruggling(st.failed, st.state === 'certified'),
  };
}

function asAccess(moduleId: string, userId: string, now: number) {
  const person = tnPersonOf(userId);
  if (!person) throw new RepositoryError('forbidden');
  const m = byId(trainingModules, moduleId);
  const a = asOf(moduleId);
  if (!m) throw new RepositoryError('not_found');
  if (!a) throw new RepositoryError('no_assessment');
  const problem = tnStartProblem(m, person.roles, tnLockedBy(m, trainingModules, tnStatusFn(person.userIds, now)));
  if (problem) throw new RepositoryError(problem);
  return { person, m, a };
}

function asAttemptViewOf(att: AssessmentAttempt, a: Assessment, m: TrainingModule): AssessmentAttemptView {
  return {
    attemptId: att.id, assessmentId: a.id, moduleId: m.id, moduleCode: m.code, version: att.version, attemptNumber: att.attemptNumber, passPercent: a.passPercent,
    questions: att.questionIds.map((id) => a.questions.find((q) => q.id === id)).filter((q): q is NonNullable<typeof q> => !!q).map((q) => ({ id: q.id, kind: q.kind, options: q.options })),
    answers: att.answers.map((x) => ({ questionId: x.questionId, selected: [...x.selected] })), startedAt: att.startedAt,
  };
}

/** One medium staffing alert per person who has failed a test several times without passing, so a conversation (coaching) happens; it clears itself when they pass. */
function syncAssessmentAlerts(now: number): void {
  for (const a of assessments) {
    const m = byId(trainingModules, a.moduleId);
    if (!m) continue;
    const version = tnCurrentVersion(m, now).version;
    const byUser = new Map<string, AssessmentAttempt[]>();
    for (const at of assessmentAttempts) if (at.assessmentId === a.id && at.version === version) byUser.set(at.userId, [...(byUser.get(at.userId) ?? []), at]);
    for (const [userId, list] of byUser) {
      const person = tnPersonOf(userId);
      if (!person) continue;
      const rel = `assess:${a.id}:${userId}`;
      const struggling = asStruggling(asFailsSince(list), !!asBadgeOf(person.userIds, m, now));
      const open = alerts.find((x) => x.relatedId === rel && x.titleKey === ASSESSMENT_ALERT && x.status !== 'resolved');
      if (struggling && !open) {
        raiseAlert({ titleKey: ASSESSMENT_ALERT, context: `${person.name} has not passed ${m.code} after ${asFailsSince(list)} attempts`, severity: 'medium', category: 'staffing', relatedId: rel, sourceRoute: `/assessment?partner=${userId}` });
        logAutomatedAction({ sourceKey: 'assessment.coaching_flag', triggeringCondition: `${person.name} failed ${m.code}'s test ${asFailsSince(list)} times without passing`, actionTaken: 'Told Admin this may be a coaching opportunity', affectedRecordId: a.id, affectedRecordType: 'other' });
      } else if (!struggling && open) {
        patchInPlace(alerts, open.id, { status: 'resolved', resolvedAt: new Date(now).toISOString(), resolvedBy: 'system', resolutionNote: 'They passed, or the content changed.' });
      }
    }
  }
}

function asLapsedOf(a: Assessment, now: number): AssessmentOverviewRow['lapsed'] {
  const out: AssessmentOverviewRow['lapsed'] = [];
  const seen = new Set<string>();
  for (const b of [...certBadges].filter((x) => x.assessmentId === a.id).sort((x, y) => y.issuedAt.localeCompare(x.issuedAt))) {
    if (seen.has(b.userId)) continue;
    seen.add(b.userId);
    const user = byId(users, b.userId);
    if (!user || user.status !== 'active' || !b.expiresAt || Date.parse(b.expiresAt) > now) continue;
    out.push({ userId: b.userId, name: user.name, endedAt: b.expiresAt, openJobs: jobs.filter((j) => j.status !== 'completed' && (j.technicianId === b.userId || (j.crew ?? []).some((c) => c.userId === b.userId))).length });
  }
  return out;
}

function asOverviewRow(a: Assessment, now: number): AssessmentOverviewRow {
  const m = byId(trainingModules, a.moduleId) as TrainingModule;
  const version = tnCurrentVersion(m, now).version;
  const attempts = assessmentAttempts.filter((x) => x.assessmentId === a.id && x.version === version && x.status === 'submitted');
  const people = new Map<string, AssessmentAttempt[]>();
  for (const x of attempts) people.set(x.userId, [...(people.get(x.userId) ?? []), x]);
  const struggling: AssessmentOverviewRow['struggling'] = [];
  for (const [userId, list] of people) {
    const person = tnPersonOf(userId);
    if (!person) continue;
    const fails = asFailsSince(list);
    if (asStruggling(fails, !!asBadgeOf(person.userIds, m, now))) struggling.push({ userId, name: person.name, fails, lastAt: list.map((x) => x.submittedAt ?? '').sort().pop() ?? '' });
  }
  return {
    assessmentId: a.id, moduleId: m.id, moduleCode: m.code, version, passPercent: a.passPercent, cooldownHours: [...a.cooldownHours] as [number, number, number], validMonths: a.validMonths, questionCount: asQuestions(a, version).length,
    lapsed: asLapsedOf(a, now),
    attempts: attempts.length, passes: attempts.filter((x) => x.passed).length, certified: new Set(certBadges.filter((b) => b.assessmentId === a.id && asBadgeValid(b, tnCurrentVersion(m, now).minVersion)).map((b) => b.userId)).size, struggling,
  };
}

/* ---- certification badges and progress (155) */

const CERT_ALERT = 'certifications.alert.lapsedOnJob';
const CERT_CHASE_DAYS = 60;
const CERT_RECENT_DAYS = 90;
const CERT_COHORT_MIN = 3;
const CERT_TOP = 5;

/** The newest certification of each module a person holds (older ones are the history of renewals). */
function certLatestOf(userIds: string[]): CertificationBadge[] {
  const out = new Map<string, CertificationBadge>();
  for (const b of [...certBadges].filter((x) => userIds.includes(x.userId)).sort((a, c) => c.issuedAt.localeCompare(a.issuedAt))) if (!out.has(b.moduleId)) out.set(b.moduleId, b);
  return [...out.values()];
}

function certStatusOf(b: CertificationBadge, now: number) {
  const m = byId(trainingModules, b.moduleId);
  return asBadgeStatus(b, { minVersion: m ? tnCurrentVersion(m, now).minVersion : 1, retired: m?.status === 'retired', now });
}

/** What the commitment engine reads: each time-limited certification, and whether a newer one has replaced it. */
function certRenewalSignals(now: number): { badgeId: string; userId: string; moduleId: string; moduleCode: string; expiresAt: string; renewed: boolean; ownerActive: boolean }[] {
  const out: { badgeId: string; userId: string; moduleId: string; moduleCode: string; expiresAt: string; renewed: boolean; ownerActive: boolean }[] = [];
  for (const b of certBadges) {
    if (!b.expiresAt) continue;
    const m = byId(trainingModules, b.moduleId);
    const user = byId(users, b.userId);
    if (!m || !user || m.status === 'retired') continue;
    const renewed = certBadges.some((x) => x.userId === b.userId && x.moduleId === b.moduleId && x.issuedAt > b.issuedAt);
    // A lapse nobody has renewed for two months is history, not something to keep chasing.
    if (now - Date.parse(b.expiresAt) > CERT_CHASE_DAYS * 86_400_000) continue;
    out.push({ badgeId: b.id, userId: b.userId, moduleId: b.moduleId, moduleCode: m.code, expiresAt: b.expiresAt, renewed, ownerActive: user.status === 'active' });
  }
  return out;
}

const certShort = (name: string) => { const p = name.trim().split(/\s+/); return p.length > 1 ? `${p[0]} ${p[p.length - 1][0]}.` : p[0]; };

function certBadgeViewOf(b: CertificationBadge, latest: boolean, now: number): CertBadgeView {
  const m = byId(trainingModules, b.moduleId) as TrainingModule;
  const status = certStatusOf(b, now);
  return {
    id: b.id, code: b.code, moduleId: m.id, moduleCode: m.code, topic: m.topic, version: b.version, score: b.score, issuedAt: b.issuedAt, expiresAt: b.expiresAt, status, daysLeft: asDaysLeft(b.expiresAt, now),
    latest, renewable: latest && (status === 'expiring' || status === 'expired') && m.status !== 'retired', gatesJobAssignment: m.gatesJobAssignment && tnRequired(m, ['technician']), renewedFromId: b.renewedFromId ?? null, earlierStandard: status === 'superseded' || status === 'retired',
  };
}

function certStandingOf(userId: string, now: number): CertStanding | null {
  const me = byId(users, userId);
  if (!me || (me.role !== 'surveyor' && me.role !== 'technician' && me.role !== 'supplier')) return null;
  const count = (id: string) => certLatestOf([id]).filter((b) => asCounts(certStatusOf(b, now))).length;
  const recent = (id: string) => certLatestOf([id]).filter((b) => asCounts(certStatusOf(b, now)) && now - Date.parse(b.issuedAt) <= CERT_RECENT_DAYS * 86_400_000).length;
  const cohort = users.filter((u) => u.role === me.role && (u.status === 'active' || u.id === userId));
  const scored = cohort.map((u) => ({ u, n: count(u.id) })).sort((a, b) => b.n - a.n || a.u.name.localeCompare(b.u.name));
  let rank = 0;
  const ranked = scored.map((x, i) => { if (i === 0 || x.n < scored[i - 1].n) rank = i + 1; return { ...x, rank }; });
  const mine = ranked.find((x) => x.u.id === userId);
  if (!mine) return null;
  const rowOf = (x: (typeof ranked)[number]): CertStandingRow => ({ rank: x.rank, name: x.u.id === userId || !certPrefs.some((p) => p.userId === x.u.id && p.hidden) ? certShort(x.u.name) : null, certifications: x.n, recent: recent(x.u.id), self: x.u.id === userId, pinned: false });
  const top = ranked.slice(0, CERT_TOP);
  const rows = top.some((x) => x.u.id === userId) ? top.map(rowOf) : [...top.map(rowOf), { ...rowOf(mine), pinned: true }];
  return { cohort: me.role as CertStanding['cohort'], total: cohort.length, rank: mine.rank, mine: mine.n, rows, enough: cohort.length >= CERT_COHORT_MIN };
}

function certNextSteps(person: { roles: TrainingRole[]; userIds: string[] }, now: number): CertNextStep[] {
  const status = tnStatusFn(person.userIds, now);
  const out: (CertNextStep & { rankKey: number; order: number })[] = [];
  for (const m of trainingModules) {
    if (m.status !== 'published' || !tnRequired(m, person.roles) || !asOf(m.id)) continue;
    const gating = m.gatesJobAssignment && tnRequired(m, ['technician']);
    const latest = certLatestOf(person.userIds).find((b) => b.moduleId === m.id);
    const st = latest ? certStatusOf(latest, now) : null;
    const base = { moduleId: m.id, moduleCode: m.code, expiresAt: latest?.expiresAt ?? null, order: m.order };
    if (latest && st === 'valid') continue;
    if (latest && (st === 'expired' || st === 'expiring')) { out.push({ ...base, kind: 'renew', because: st === 'expired' ? (gating ? 'blocks_jobs' : 'expired') : 'expiring', route: `/assessment/${m.id}`, rankKey: st === 'expired' ? (gating ? 0 : 1) : 2 }); continue; }
    if (tnLockedBy(m, trainingModules, status).length > 0) continue;
    if (status(m.id) === 'completed') out.push({ ...base, kind: 'test', because: gating ? 'blocks_jobs' : 'required', route: `/assessment/${m.id}`, rankKey: gating ? 0 : 3 });
    else if (trainingLessons.some((l) => l.moduleId === m.id)) out.push({ ...base, kind: 'lessons', because: gating ? 'blocks_jobs' : 'required', route: `/training/${m.id}`, rankKey: gating ? 0 : 4 });
  }
  return out.sort((a, b) => a.rankKey - b.rankKey || a.order - b.order).slice(0, 4).map(({ rankKey, order, ...rest }) => rest);
}

/** A certification that lapsed while its holder is on a job: the job finishes, new ones wait, and Admin is told so it is a decision, not a surprise (155). */
function syncCertifications(now: number): void {
  const open = (userId: string) => jobs.filter((j) => j.status !== 'completed' && (j.technicianId === userId || (j.crew ?? []).some((c) => c.userId === userId)));
  for (const b of certBadges) {
    const m = byId(trainingModules, b.moduleId);
    const user = byId(users, b.userId);
    if (!m || !user || !b.expiresAt) continue;
    const rel = `certlapse:${b.id}`;
    const existing = alerts.find((x) => x.relatedId === rel && x.titleKey === CERT_ALERT && x.status !== 'resolved');
    const renewed = certBadges.some((x) => x.userId === b.userId && x.moduleId === b.moduleId && x.issuedAt > b.issuedAt);
    const lapsed = Date.parse(b.expiresAt) <= now && !renewed && m.gatesJobAssignment && tnRequired(m, ['technician']) && user.status === 'active';
    const onJobs = lapsed ? open(b.userId) : [];
    if (lapsed && onJobs.length > 0 && !existing) {
      raiseAlert({ titleKey: CERT_ALERT, context: `${user.name}'s ${m.code} certification lapsed while on ${onJobs.map((j) => j.code).join(', ')}`, severity: 'medium', category: 'staffing', relatedId: rel, sourceRoute: `/assessment?partner=${b.userId}` });
      logAutomatedAction({ sourceKey: 'certification.lapsed', triggeringCondition: `${user.name}'s ${m.code} certification ended while they hold open work`, actionTaken: 'Told Admin: the current work can finish, new work needing it is held', affectedRecordId: b.id, affectedRecordType: 'other' });
    } else if (existing && (!lapsed || onJobs.length === 0)) {
      patchInPlace(alerts, existing.id, { status: 'resolved', resolvedAt: new Date(now).toISOString(), resolvedBy: 'system', resolutionNote: 'Renewed, or no work in hand.' });
    }
  }
}

/** Whether a person may be put on a job: for a technician, every gating safety module must be done. Anyone else is not held by it. */
function trainingClear(userId: string, now = Date.now()): boolean {
  const person = tnPersonOf(userId);
  if (!person) return true;
  return tnJobGate(trainingModules, person.roles, tnStatusFn(person.userIds, now), (id) => asCertified(person.userIds, id, now)).cleared;
}

/* ============================== SOP document repository (153) */

const sopCategories: SopCategory[] = [];
const sopReferences: SopReferenceDocument[] = [];
const sopBookmarks: SopBookmark[] = [];

const spText = (key: string, extra: Partial<SopText> = {}): SopText => ({ key, ...extra });
const spStr = (v: unknown) => JSON.stringify(v);

const SP_PHASES = ['preparation', 'rails', 'machine', 'car', 'wiring', 'safety', 'final'] as const;
const spApplies = (a: InstallSopStepDef['appliesWhen']): SopText | null => (!a ? null : a.field === 'powerBackup' ? spText('sopRepo.applies.powerBackup') : spText('sopRepo.applies.automaticDoor'));

function spInstallItem(st: InstallSopStepDef): SopItemView {
  return {
    id: st.id, label: spText(st.labelKey), detail: null, standard: null, mandatory: !st.canBeNotApplicable, needsPhoto: st.slots.some((x) => x.kind === 'photo'), needsVideo: st.slots.some((x) => x.kind === 'video'),
    safetyCritical: st.safetyCritical, evidence: st.slots.map((x) => spText(x.labelKey)), appliesWhen: spApplies(st.appliesWhen),
  };
}

function spDeliveryItem(st: DeliverySopStep): SopItemView {
  const pick = (a?: string, hi?: string, mr?: string): SopText | null => (a ? { en: a, ...(hi ? { hi } : {}), ...(mr ? { mr } : {}) } : null);
  return { id: st.id, label: pick(st.label, st.labelHi, st.labelMr) as SopText, detail: pick(st.hint, st.hintHi, st.hintMr), standard: null, mandatory: st.mandatory, needsPhoto: st.needsPhoto, needsVideo: false, safetyCritical: false, evidence: [], appliesWhen: null };
}

function spSafetyItem(def: (typeof SAFETY_ITEMS)[number], slotLabel: (slotId: string) => SopText | null): SopItemView {
  return {
    id: def.id, label: spText(`safetyChecklist.item.${def.id}.label`), detail: spText(`safetyChecklist.item.${def.id}.method`), standard: spText(`safetyChecklist.item.${def.id}.standard`), mandatory: true,
    needsPhoto: def.slots.length > 0, needsVideo: false, safetyCritical: true, evidence: def.slots.map(slotLabel).filter((x): x is SopText => !!x), appliesWhen: spApplies(def.appliesWhen),
  };
}

const spFingerprint = (it: SopItemView) => spStr([it.label, it.detail, it.standard, it.mandatory, it.needsPhoto, it.needsVideo, it.safetyCritical, it.evidence, it.appliesWhen]);

interface SpRawVersion {
  version: number;
  effectiveFrom: string;
  changeNote: SopText | null;
  publishedByName: string | null;
  publishedAt: string | null;
  sections: SopSectionView[];
}

/** Turns one document's raw versions into the reader's: which is in force, which is announced, and what moved against the one before. */
function spVersionsOf(raw: SpRawVersion[], now: number): SopDocVersionView[] {
  const ordered = [...raw].sort((a, b) => a.version - b.version);
  const plain = ordered.map((v) => ({ version: v.version, effectiveFrom: v.effectiveFrom }));
  return ordered.map((v, i) => {
    const items = v.sections.flatMap((s) => s.items);
    const prev = i > 0 ? ordered[i - 1].sections.flatMap((s) => s.items) : null;
    const d = prev ? sopDiff(prev.map((x) => ({ id: x.id, fingerprint: spFingerprint(x) })), items.map((x) => ({ id: x.id, fingerprint: spFingerprint(x) }))) : { added: [], removed: [], changed: [] };
    return {
      version: v.version, effectiveFrom: v.effectiveFrom, changeNote: v.changeNote, publishedByName: v.publishedByName, publishedAt: v.publishedAt, state: sopStateOf({ version: v.version, effectiveFrom: v.effectiveFrom }, plain, now),
      sections: v.sections, itemCount: items.length, changes: prev ? { added: d.added.length, removed: d.removed.length, changed: d.changed.length } : null, changedIds: d,
    };
  });
}

function spDocument(id: string, source: SopSource, categoryId: string, title: SopText, summary: SopText | null, raw: SpRawVersion[], extra: Partial<SopDocumentView>, userId: string, now: number): SopDocumentView {
  const versions = spVersionsOf(raw, now);
  const plain = raw.map((v) => ({ version: v.version, effectiveFrom: v.effectiveFrom }));
  const cur = sopCurrent(plain, now) ?? plain[0];
  const up = sopUpcoming(plain, now);
  return {
    id, source, categoryId, title, summary, currentVersion: cur.version, effectiveDate: cur.effectiveFrom, upcoming: up ? { version: up.version, effectiveFrom: up.effectiveFrom } : null, versions,
    bookmarked: sopBookmarks.some((b) => b.userId === userId && b.docId === id), referenceOnly: false, governedBy: { route: null, nameKey: 'sopRepo.governed.reference' }, builtIn: false, editable: false, downloadAvailable: true, ...extra,
  };
}

function spCategoryName(c: SopCategory): SopText {
  return { en: c.name, ...(c.nameHi ? { hi: c.nameHi } : {}), ...(c.nameMr ? { mr: c.nameMr } : {}) };
}

/** Every document, derived from the governed templates on each read (nothing is copied, so a version here can never differ from the one being enforced). */
function spLibraryOf(userId: string, isAdmin: boolean, now: number): SopLibraryView {
  const docs: SopDocumentView[] = [];
  // Installation procedure (123): every published version, step ids stable across them.
  docs.push(spDocument('sop-installation', 'installation', 'installation', spText('sopRepo.doc.installation'), spText('sopRepo.summary.installation'), installSopVersions.map((v) => ({
    version: v.version, effectiveFrom: v.effectiveFrom, changeNote: { en: v.changeNote }, publishedByName: v.publishedByName, publishedAt: v.publishedAt,
    sections: SP_PHASES.map((ph) => ({ id: ph, title: spText(`installTimeline.milestone.${ph}`), items: v.steps.filter((st) => st.phase === ph).map(spInstallItem) })).filter((sec) => sec.items.length > 0),
  })), { governedBy: { route: null, nameKey: 'sopRepo.governed.installation' } }, userId, now));
  // Delivery procedure (107): the master template and one per part category.
  for (const tpl of deliverySops) {
    const isAll = tpl.category === 'all';
    docs.push(spDocument(`sop-delivery-${tpl.id}`, 'delivery', 'delivery', isAll ? spText('sopRepo.doc.deliveryAll') : spText('sopRepo.doc.deliveryCategory', { paramKeys: { category: `partCategory.${tpl.category}` } }), spText(isAll ? 'sopRepo.summary.deliveryAll' : 'sopRepo.summary.deliveryCategory'), tpl.versions.map((v) => ({
      version: v.version, effectiveFrom: v.effectiveFrom, changeNote: { en: v.changeNote }, publishedByName: v.createdByName, publishedAt: v.createdAt, sections: [{ id: 'steps', title: null, items: v.steps.map(spDeliveryItem) }],
    })), { governedBy: { route: '/delivery-sop', nameKey: 'sopRepo.governed.delivery' } }, userId, now));
  }
  // Built-in standards: the safety checks (126) and the two quality checks (132, 133). They live in the app's own rules, so they have one fixed version.
  const builtIn = (sections: SopSectionView[]): SpRawVersion[] => [{ version: 1, effectiveFrom: SOP_SINCE, changeNote: spText('sopRepo.builtInNote'), publishedByName: null, publishedAt: null, sections }];
  const installNow = installVersionInForce(installSopVersions, now) ?? installSopVersions[installSopVersions.length - 1];
  const slotLabel = (slotId: string): SopText | null => { for (const st of installNow.steps) { const sl = st.slots.find((x) => x.id === slotId); if (sl) return spText(sl.labelKey); } return null; };
  docs.push(spDocument('sop-safety', 'safety', 'safety', spText('sopRepo.doc.safety'), spText('sopRepo.summary.safety'), builtIn([{ id: 'checks', title: null, items: SAFETY_ITEMS.map((d) => spSafetyItem(d, slotLabel)) }]), { builtIn: true, governedBy: { route: null, nameKey: 'sopRepo.governed.safety' } }, userId, now));
  const qcItem = (ns: string, id: string): SopItemView => ({ id, label: spText(`${ns}.item.${id}`), detail: spText(`${ns}.itemHint.${id}`), standard: null, mandatory: true, needsPhoto: false, needsVideo: false, safetyCritical: ns === 'qcElec', evidence: [], appliesWhen: null });
  docs.push(spDocument('sop-quality-mechanical', 'quality', 'quality', spText('sopRepo.doc.qualityMechanical'), spText('sopRepo.summary.qualityMechanical'), builtIn([{ id: 'checks', title: null, items: MECH_ITEMS.map((id) => qcItem('qcMech', id)) }]), { builtIn: true, governedBy: { route: null, nameKey: 'sopRepo.governed.quality' } }, userId, now));
  docs.push(spDocument('sop-quality-electrical', 'quality', 'quality', spText('sopRepo.doc.qualityElectrical'), spText('sopRepo.summary.qualityElectrical'), builtIn([{ id: 'checks', title: null, items: ELEC_ITEMS.map((id) => qcItem('qcElec', id)) }]), { builtIn: true, governedBy: { route: null, nameKey: 'sopRepo.governed.quality' } }, userId, now));
  // Reference documents Admin wrote for categories with no enforced checklist behind them yet.
  for (const r of sopReferences) {
    const title: SopText = { en: r.title, ...(r.titleHi ? { hi: r.titleHi } : {}), ...(r.titleMr ? { mr: r.titleMr } : {}) };
    docs.push(spDocument(r.id, 'reference', r.categoryId, title, null, r.versions.map((v) => ({
      version: v.version, effectiveFrom: v.effectiveFrom, changeNote: { en: v.changeNote }, publishedByName: v.publishedByName, publishedAt: v.publishedAt,
      sections: [{ id: 'steps', title: null, items: v.items.map((it, i) => ({ id: `i${i + 1}`, label: { en: it.en, ...(it.hi ? { hi: it.hi } : {}), ...(it.mr ? { mr: it.mr } : {}) }, detail: null, standard: null, mandatory: false, needsPhoto: false, needsVideo: false, safetyCritical: false, evidence: [], appliesWhen: null })) }],
    })), { referenceOnly: true, editable: isAdmin, governedBy: { route: null, nameKey: 'sopRepo.governed.reference' } }, userId, now));
  }
  const categories = [
    ...SOP_BUILT_IN.map((id) => ({ id: id as string, name: spText(`sopRepo.category.${id}`) as SopText, builtIn: true })),
    ...sopCategories.map((c) => ({ id: c.id, name: spCategoryName(c), builtIn: false })),
  ].map((c) => ({ ...c, count: docs.filter((d) => d.categoryId === c.id).length }));
  return { docs, categories, canEdit: isAdmin, at: new Date(now).toISOString() };
}

function spReader(userId: string): User {
  const u = byId(users, userId);
  if (!u || (u.role !== 'admin' && u.role !== 'technician')) throw new RepositoryError('forbidden');
  return u;
}

/* ============================== Partner deactivation and exit (150) */

const partnerExits: PartnerExit[] = [];
let exitCounter = 0;
const EXIT_STUCK_ALERT = 'partnerExit.alert.stuck';
const EXIT_VIOLATION_ALERT = 'partnerExit.alert.violation';
const exLetters = (s: string) => s.replace(/[^\p{L}\p{N}]/gu, '').length;

/** The exit under way for a partner, if any: from the first step until access, work and money are all done. */
const exitUnderWay = (partnerId: string): PartnerExit | undefined => partnerExits.find((e) => e.partnerId === partnerId && e.status === 'in_progress');
const exitLatest = (partnerId: string): PartnerExit | undefined => [...partnerExits].filter((e) => e.partnerId === partnerId).sort((a, b) => b.startedAt.localeCompare(a.startedAt))[0];
/** Someone on their way out is not given new work. */
const acceptsNewWork = (id: string): boolean => !exitUnderWay(id);

function exPartner(id: string): { type: 'surveyor' | 'technician' | 'supplier'; name: string; phone: string; city: string; status: DirectoryStatus; user?: User; supplier?: Supplier } {
  const u = byId(users, id);
  if (u && (u.role === 'surveyor' || u.role === 'technician')) return { type: u.role, name: u.name, phone: u.phone, city: u.city ?? '', status: pdStatusOf(u.status), user: u };
  const sup = byId(suppliers, id);
  if (sup) return { type: 'supplier', name: sup.name, phone: supplierUserFor(sup)?.phone ?? sup.contactPhone ?? '', city: sup.city, status: pdStatusOf(sup.status), supplier: sup };
  throw new RepositoryError('not_found');
}

const exBlockers = (kind: ExitKind, workOpen: number, finishing: number, settlement: 'none' | 'proposed' | 'agreed' | 'disputed' | 'paid'): ExitBlocker[] => exBlockersOf({ kind, workOpen, finishing, settlement });

function exWorkOf(exit: PartnerExit | undefined, partnerId: string, type: 'surveyor' | 'technician' | 'supplier'): ExitWorkItem[] {
  const decided = (t: ExitItemType, id: string): ExitAction | null => [...(exit?.actions ?? [])].reverse().find((a) => a.itemType === t && a.itemId === id) ?? null;
  const out: ExitWorkItem[] = [];
  if (type === 'surveyor') {
    for (const l of leads.filter((x) => x.surveyorId === partnerId && x.stage !== 'won' && x.stage !== 'lost')) out.push({ type: 'lead', id: l.id, label: l.code, detail: l.builderName, route: `/admin/leads/${l.id}`, done: decided('lead', l.id), open: true, finishing: false });
  } else if (type === 'technician') {
    for (const j of jobs.filter((x) => x.status !== 'completed' && isOnJob(x, partnerId))) out.push({ type: 'job', id: j.id, label: j.code, detail: j.siteName, route: `/job-team/${j.id}`, done: decided('job', j.id), open: true, finishing: false });
  } else {
    for (const po of supplierPurchaseOrders.filter((x) => x.supplierId === partnerId && x.status !== 'failed' && !(x.status === 'sent' && poStageOf(x) === 'delivered'))) {
      const done = decided('order', po.id);
      const finishing = done?.action === 'finish_first';
      const settled = !!done && (done.action === 'alternate_sourcing' || done.action === 'cancelled');
      out.push({ type: 'order', id: po.id, label: po.code, detail: po.status, route: '/orders', done, open: !settled, finishing });
    }
  }
  return out;
}

/** What the partner is owed, read from the commission ledger (surveyors, technicians) or the supplier payment records, never typed in. */
function exSettlementOf(partnerId: string, type: 'surveyor' | 'technician' | 'supplier'): ExitPreviewView {
  const lines: ExitSettlementLine[] = [];
  const held: ExitHeldLine[] = [];
  if (type === 'supplier') {
    for (const p of supplierPayments.filter((x) => x.supplierId === partnerId && x.status !== 'executed')) lines.push({ kind: 'payment_owed', ref: p.id, label: p.code, amount: p.amount });
    for (const r of supplierRetentions.filter((x) => x.supplierId === partnerId && (x.status === 'held' || x.status === 'paused'))) held.push({ kind: 'retention_held', ref: r.id, label: byId(supplierPurchaseOrders, r.poId)?.code ?? r.poId, amount: r.amount });
    for (const a of advanceRecoveries.filter((x) => x.supplierId === partnerId && x.status === 'open')) lines.push({ kind: 'advance_recoverable', ref: a.id, label: a.code, amount: -Math.max(0, a.amount - a.recoveredAmount - a.writtenOffAmount) });
  } else {
    for (const c of commissions.filter((x) => x.userId === partnerId)) {
      if (c.status === 'approved') lines.push({ kind: 'commission_payable', ref: c.id, label: c.reasonKey, amount: c.amount });
      else if (c.status === 'projected') held.push({ kind: 'commission_pending', ref: c.id, label: c.reasonKey, amount: c.amount });
    }
  }
  return { lines, held, amount: lines.reduce((n, l) => n + l.amount, 0) };
}

const exTotal = (s: ExitSettlement) => s.amount + (s.adjustment?.amount ?? 0);

/** A supplier's money is paid through the payment queue (111), so its settlement reads as paid once every owed payment there has been made. */
function exRefreshPaid(exit: PartnerExit, now: number): void {
  const s = exit.settlement;
  if (!s || s.paid || s.status === 'disputed' || exit.partnerType !== 'supplier') return;
  const owed = s.lines.filter((l) => l.kind === 'payment_owed');
  if (s.status === 'agreed' && !s.withheld && owed.length > 0 && owed.every((l) => byId(supplierPayments, l.ref)?.status === 'executed')) {
    s.status = 'paid';
    s.paid = { at: new Date(now).toISOString(), byName: 'AIEC', reference: 'supplier-payments', amount: owed.reduce((n, l) => n + l.amount, 0) };
  }
}

function exViewOf(partnerId: string, now: number): PartnerExitView {
  const info = exPartner(partnerId);
  const exit = exitLatest(partnerId);
  const live = exit && exit.status === 'in_progress' ? exit : undefined;
  if (live) exRefreshPaid(live, now);
  const work = exWorkOf(live, partnerId, info.type);
  const workOpen = work.filter((w) => w.open && !w.finishing).length;
  const finishing = work.filter((w) => w.open && w.finishing).length;
  const settleState = !live?.settlement ? 'none' : live.settlement.status;
  const blockers = live ? exBlockers(live.kind, workOpen, finishing, settleState) : [];
  const paidOrNothing = !!live?.settlement && (live.settlement.status === 'paid' || (live.settlement.status === 'agreed' && !live.settlement.withheld && exTotal(live.settlement) <= 0));
  let stage: ExitStage = 'plan';
  if (live) {
    if (live.kind === 'involuntary' && !live.accessRevoked) stage = 'access';
    else if (workOpen + finishing > 0) stage = 'work';
    else if (!live.settlement || live.settlement.status === 'proposed' || live.settlement.status === 'disputed' || !paidOrNothing) stage = 'settlement';
    else if (!live.accessRevoked) stage = 'access';
    else stage = live.interview ? 'done' : 'interview';
  } else if (exit?.status === 'completed') stage = exit.interview ? 'done' : 'interview';
  const targets: ExitTargetsView = {
    surveyors: users.filter((u) => u.role === 'surveyor' && u.status === 'active' && u.id !== partnerId && acceptsNewWork(u.id)).map((u) => ({ id: u.id, name: u.name, openLeads: leads.filter((l) => l.surveyorId === u.id && l.stage !== 'won' && l.stage !== 'lost').length })),
    technicians: users.filter((u) => u.role === 'technician' && u.status === 'active' && u.id !== partnerId && acceptsNewWork(u.id) && trainingClear(u.id)).map((u) => ({ id: u.id, name: u.name, openJobs: jobs.filter((j) => j.status !== 'completed' && isOnJob(j, u.id)).length, canLead: tcCanLead(u.id) })),
    suppliers: suppliers.filter((x) => x.status === 'active' && x.id !== partnerId && !x.mergedIntoSupplierId && acceptsNewWork(x.id)).map((x) => ({ id: x.id, name: x.name })),
  };
  return {
    partner: { id: partnerId, type: info.type, name: info.name, phone: info.phone, city: info.city, status: info.status, tier: info.type === 'supplier' ? tierOf(info.supplier as Supplier) : tierNow(partnerId, now) },
    exit: exit ? JSON.parse(JSON.stringify(exit)) as PartnerExit : null,
    work,
    workOpen,
    finishing,
    targets,
    preview: exSettlementOf(partnerId, info.type),
    blockers,
    stage,
    canEndAccess: !!live && !live.accessRevoked && blockers.length === 0,
  };
}

const exRowOf = (e: PartnerExit, now: number): ExitRowView => {
  const v = exViewOf(e.partnerId, now);
  const own = v.exit?.id === e.id;
  return { id: e.id, code: e.code, partnerId: e.partnerId, partnerName: e.partnerName, partnerType: e.partnerType, kind: e.kind, reason: e.reason, lastDay: e.lastDay, stage: own ? v.stage : e.status === 'completed' ? 'done' : 'plan', status: e.status, workOpen: own ? v.workOpen : 0, blockers: own ? v.blockers : [], amount: e.settlement ? exTotal(e.settlement) : null, startedAt: e.startedAt, completedAt: e.completedAt ?? null };
};

function exEvent(exit: PartnerExit, kind: string, byName: string, detail?: string): void {
  exit.events.push({ kind, at: new Date().toISOString(), byName, ...(detail ? { detail } : {}) });
}

function exOpenExit(partnerId: string): PartnerExit {
  const e = exitUnderWay(partnerId);
  if (!e) throw new RepositoryError('not_open');
  return e;
}

/** Ending access is the last switch: the account stops signing in, no new work reaches it, and a supplier is closed to new orders. */
function exEndAccess(exit: PartnerExit, byName: string, first: boolean, now: number): void {
  const at = new Date(now).toISOString();
  exit.accessRevoked = { at, byName, first };
  exEvent(exit, 'access_ended', byName, first ? 'first' : undefined);
  if (exit.partnerType === 'supplier') {
    const sup = byId(suppliers, exit.partnerId);
    if (sup) {
      patchInPlace(suppliers, sup.id, { status: 'suspended' as const, suspendedReason: `Exit ${exit.code}`, suspendedBy: byName, suspendedAt: at });
      const portal = supplierUserFor(sup);
      if (portal) patchInPlace(users, portal.id, { status: 'suspended' as const });
    }
  } else {
    patchInPlace(users, exit.partnerId, { status: 'suspended' as const, onDuty: false });
    for (const z of zones.filter((x) => x.assignedUserIds.includes(exit.partnerId))) patchInPlace(zones, z.id, { assignedUserIds: z.assignedUserIds.filter((x) => x !== exit.partnerId) });
  }
}

function exMaybeComplete(exit: PartnerExit, now: number): boolean {
  if (exit.status !== 'in_progress' || !exit.accessRevoked || !exit.settlement) return false;
  const v = exViewOf(exit.partnerId, now);
  const s = exit.settlement;
  const settled = s.status === 'paid' || (s.status === 'agreed' && !s.withheld && exTotal(s) <= 0);
  if (v.workOpen + v.finishing > 0 || !settled) return false;
  exit.status = 'completed';
  exit.completedAt = new Date(now).toISOString();
  exEvent(exit, 'completed', 'AIEC');
  return true;
}

/** The heartbeat's part: supplier payments that have been made, exits whose last step just closed, and a last day that has arrived with something still open. */
function syncPartnerExits(now: number): void {
  const today = tcToday(now);
  for (const exit of partnerExits) {
    if (exit.status !== 'in_progress') {
      const a = alerts.filter((x) => (x.relatedId === `exit:${exit.id}`) && x.status !== 'resolved');
      for (const x of a) patchInPlace(alerts, x.id, { status: 'resolved', resolvedAt: new Date(now).toISOString(), resolvedBy: 'system', resolutionNote: 'The exit is closed.' });
      continue;
    }
    exRefreshPaid(exit, now);
    const v = exViewOf(exit.partnerId, now);
    if (exit.kind === 'voluntary' && !exit.accessRevoked) {
      const stuckRel = `exit:${exit.id}`;
      const stuck = alerts.find((a) => a.relatedId === stuckRel && a.titleKey === EXIT_STUCK_ALERT && a.status !== 'resolved');
      if (today >= exit.lastDay && v.blockers.length === 0) {
        exEndAccess(exit, 'AIEC', false, now);
        logAutomatedAction({ sourceKey: 'partner_exit.access_ended', triggeringCondition: `${exit.partnerName}'s last day (${exit.lastDay}) arrived with work handed on and the settlement confirmed`, actionTaken: 'Ended their access', affectedRecordId: exit.id, affectedRecordType: 'other' });
        if (stuck) patchInPlace(alerts, stuck.id, { status: 'resolved', resolvedAt: new Date(now).toISOString(), resolvedBy: 'system', resolutionNote: 'Nothing is blocking the exit any more.' });
      } else if (today >= exit.lastDay && v.blockers.length > 0 && !stuck) {
        raiseAlert({ titleKey: EXIT_STUCK_ALERT, context: `${exit.partnerName}'s last day has come but the exit is not ready`, severity: 'medium', category: 'staffing', relatedId: stuckRel, sourceRoute: `/partner-exit/${exit.partnerId}` });
      }
    }
    if (exMaybeComplete(exit, now)) logAutomatedAction({ sourceKey: 'partner_exit.completed', triggeringCondition: `${exit.partnerName}'s exit has no work, money or access left open`, actionTaken: 'Closed the exit', affectedRecordId: exit.id, affectedRecordType: 'other' });
  }
}

/** What the follow-up engine reads: each exit with how much work is still in hand. */
function exitSignals(): { exit: PartnerExit; workOpen: number; finishing: number }[] {
  return partnerExits.filter((e) => e.status === 'in_progress').map((e) => {
    const w = exWorkOf(e, e.partnerId, e.partnerType);
    return { exit: e, workOpen: w.filter((x) => x.open && !x.finishing).length, finishing: w.filter((x) => x.open && x.finishing).length };
  });
}

/* ============================== Handover completion certificate (140) */

const handoverCompletions: HandoverCompletion[] = [];
let finalPayoutCounter = 0;
let judgementCounter = 0;
let certificateCounter = 0;
const COMPLETION_REASONS = { converted: 'commission.reason.leadConverted', install: 'commission.reason.installationCompleted', closed: 'commission.reason.dealClosed', qc: 'commission.reason.qcCompleted' } as const;

const completionOf = (jobId: string) => handoverCompletions.find((c) => c.jobId === jobId);

function completionActor(jobId: string, userId: string): { job: Job; user: User; role: WrRole } {
  return warrantyActor(jobId, userId);
}

type PlannedLine = Omit<FinalPayoutLine, 'id' | 'commissionId'> & { existingId: string | null };
interface PayoutPlan {
  lines: PlannedLine[];
  pools: HandoverCompletion['payout']['pools'];
  basis: CompletionPayoutBasis;
  notPaid: { userId: string; name: string }[];
  team: HandoverCompletion['team'];
}
type CompletionPayoutBasis = 'time' | 'steps' | 'equal';

/**
 * Who is paid what from this one event, worked out from the work each person actually recorded: the original surveyor's conversion commission
 * (the one 077 already recorded), the closer of a reassigned lead, every installer by time on site (the lead keeps a bonus on top), and the
 * independent quality inspector(s) by results recorded. Someone who left the job midway keeps what they did; someone with no recorded work on it is listed, not paid.
 */
function payoutPlanOf(job: Job, now: number): PayoutPlan {
  const deal = byId(deals, job.dealId);
  const lead = deal ? resolveLead(deal.leadId) : null;
  const value = deal ? deal.agreedPrice || deal.quotedPrice : 0;
  const lines: PlannedLine[] = [];
  const team = new Map<string, HandoverCompletion['team'][number]>();
  const touch = (userId: string, role: FinalPayoutLine['role'], more: Partial<Pick<HandoverCompletion['team'][number], 'minutes' | 'steps' | 'results'>> = {}) => {
    const cur = team.get(userId) ?? { userId, name: nameOf(userId), roles: [], minutes: 0, steps: 0, results: 0 };
    if (!cur.roles.includes(role)) cur.roles.push(role);
    cur.minutes += more.minutes ?? 0;
    cur.steps += more.steps ?? 0;
    cur.results += more.results ?? 0;
    team.set(userId, cur);
  };
  const existing = (userId: string, reasonKey: string) => commissions.find((c) => c.userId === userId && c.reasonKey === reasonKey && c.dealId === deal?.id && (!c.jobId || c.jobId === job.id) && c.status !== 'forfeited');

  if (deal && lead?.originalSurveyorId) {
    const e = existing(lead.originalSurveyorId, COMPLETION_REASONS.converted);
    lines.push({ userId: lead.originalSurveyorId, name: nameOf(lead.originalSurveyorId), role: 'surveyor', reasonKey: COMPLETION_REASONS.converted, basis: e ? 'existing' : 'percent', amount: e ? e.amount : Math.round(value * (surveyorConversionPct(lead.originalSurveyorId) / 100)), existingId: e?.id ?? null });
    touch(lead.originalSurveyorId, 'surveyor');
  }
  if (deal && lead && lead.surveyorId && lead.surveyorId !== lead.originalSurveyorId) {
    const e = existing(lead.surveyorId, COMPLETION_REASONS.closed);
    lines.push({ userId: lead.surveyorId, name: nameOf(lead.surveyorId), role: 'sales', reasonKey: COMPLETION_REASONS.closed, basis: e ? 'existing' : 'percent', amount: e ? e.amount : fpSalesClose(value), existingId: e?.id ?? null });
    touch(lead.surveyorId, 'sales');
  }

  // The installers: everyone who was on the job at any point, by what they did.
  const sessions = siteCheckIns.filter((s) => s.jobId === job.id);
  const onJob = new Set<string>([...(job.technicianId ? [job.technicianId] : []), ...(job.crew ?? []).map((c) => c.userId), ...sessions.map((s) => s.userId)]);
  for (const st of job.steps) {
    const who = st.status === 'complete' && st.completedByName ? users.find((u) => u.role === 'technician' && u.name === st.completedByName) : undefined;
    if (who) onJob.add(who.id);
  }
  const contributors: FpContributor[] = [...onJob]
    .map((id) => byId(users, id))
    .filter((u): u is User => !!u && u.role === 'technician')
    .map((u) => ({ userId: u.id, name: u.name, isLead: u.id === job.technicianId, minutes: timeOf(sessions, u.id, now).minutes, steps: job.steps.filter((st) => st.status === 'complete' && !st.notApplicable && stepFinisherName(job, st) === u.name).length }));
  const pool = fpInstallPool(value);
  const crew = fpCrewShares(pool, contributors);
  const current = new Set<string>([...(job.technicianId ? [job.technicianId] : []), ...(job.crew ?? []).map((c) => c.userId)]);
  for (const l of crew.lines) {
    const c = contributors.find((x) => x.userId === l.userId) as FpContributor;
    const e = existing(l.userId, COMPLETION_REASONS.install);
    lines.push({
      userId: l.userId,
      name: c.name,
      role: c.isLead ? 'technician_lead' : 'technician',
      reasonKey: COMPLETION_REASONS.install,
      basis: e ? 'existing' : crew.basis,
      amount: e ? e.amount : l.amount,
      share: l.share,
      minutes: c.minutes,
      steps: c.steps,
      ...(l.leadBonus > 0 ? { leadBonus: l.leadBonus } : {}),
      ...(current.has(l.userId) ? {} : { leftEarly: true }),
      existingId: e?.id ?? null,
    });
    touch(l.userId, c.isLead ? 'technician_lead' : 'technician', { minutes: c.minutes, steps: c.steps });
  }
  for (const id of crew.notPaid) touch(id, 'technician', { minutes: 0, steps: 0 });

  // The independent inspector(s): by the results each recorded.
  const counts = new Map<string, number>();
  for (const a of [...Object.values(mechCheckOf(job.id).attempts), ...Object.values(elecCheckOf(job.id).attempts)].flat()) {
    if (a && byId(users, a.byUserId)?.role === 'technician') counts.set(a.byUserId, (counts.get(a.byUserId) ?? 0) + 1);
  }
  const assigned = qcOf(job.id)?.inspectorId;
  if (counts.size === 0 && assigned && byId(users, assigned)?.role === 'technician') counts.set(assigned, 0);
  const qc = fpQcShares(FP_QC_FEE, [...counts.entries()].map(([userId, results]) => ({ userId, name: nameOf(userId), results })));
  for (const q of qc) {
    const e = existing(q.userId, COMPLETION_REASONS.qc);
    lines.push({ userId: q.userId, name: nameOf(q.userId), role: 'qc_inspector', reasonKey: COMPLETION_REASONS.qc, basis: e ? 'existing' : 'fixed', amount: e ? e.amount : q.amount, results: counts.get(q.userId) ?? 0, existingId: e?.id ?? null });
    touch(q.userId, 'qc_inspector', { results: counts.get(q.userId) ?? 0 });
  }
  return {
    lines,
    pools: { installation: pool, qc: qc.length > 0 ? FP_QC_FEE : 0, salesClose: lines.find((l) => l.role === 'sales')?.amount ?? 0 },
    basis: crew.basis,
    notPaid: crew.notPaid.map((id) => ({ userId: id, name: nameOf(id) })),
    team: [...team.values()],
  };
}

const latestOf = (xs: (string | undefined | null)[]): string | null => xs.filter((x): x is string => !!x).sort().pop() ?? null;

/** The project's life in nine milestones, read from the records each stage kept. Nothing here is typed in by anyone. */
function completionSummaryOf(job: Job, now: number): HandoverCompletion['summary'] {
  const deal = byId(deals, job.dealId);
  const lead = deal ? resolveLead(deal.leadId) : null;
  const spec = lead ? lockedSpecOf(lead.id) : null;
  const visits = lead ? siteVisits.filter((v) => v.leadId === lead.id && v.status === 'verified').sort((a, b) => a.checkInAt.localeCompare(b.checkInAt)) : [];
  const sig = contractSignatures.find((s) => s.dealId === job.dealId && !!s.aiecCountersignedAt);
  const contract = contracts.filter((c) => c.dealId === job.dealId).sort((a, b) => b.version - a.version)[0];
  const confirmations = deliveryConfirmations.filter((c) => c.dealId === job.dealId && c.status === 'signed');
  const mech = mechCheckOf(job.id).signedOff;
  const elec = elecCheckOf(job.id).signedOff;
  const cert = currentCertOf(job.id);
  const walk = walkthroughOf(job.id);
  const reg = registrationOf(job.id);
  const sessions = siteCheckIns.filter((s) => s.jobId === job.id);
  const done = job.steps.filter((s) => s.status === 'complete' && !s.notApplicable);
  const lastStep = latestOf(job.steps.map((s) => s.completedAt));
  const first = job.startedAt ?? sessions.map((s) => s.checkInAt).sort()[0] ?? null;
  const milestones: CompletionMilestone[] = [
    { id: 'survey', at: visits[0]?.checkInAt ?? null, ref: null, byName: visits[0]?.surveyorName ?? (lead ? nameOf(lead.originalSurveyorId) : null), facts: { visits: visits.length } },
    { id: 'quotation', at: spec?.acceptedAt ?? null, ref: spec ? `${spec.quotationCode} v${spec.version}` : null, byName: null, facts: { value: deal ? deal.agreedPrice || deal.quotedPrice : 0 } },
    { id: 'contract', at: sig?.aiecCountersignedAt ?? deal?.closedAt ?? null, ref: contract ? `v${contract.version}` : null, byName: sig?.aiecCountersignedBy ?? null, facts: {} },
    { id: 'delivery', at: latestOf(confirmations.map((c) => c.signedAt ?? c.createdAt)), ref: null, byName: null, facts: { count: confirmations.length } },
    { id: 'installation', at: lastStep, ref: job.code, byName: job.technicianId ? nameOf(job.technicianId) : null, facts: { steps: done.length, people: new Set(sessions.map((s) => s.userId)).size || 1, days: first && lastStep ? Math.max(1, Math.round((new Date(lastStep).getTime() - new Date(first).getTime()) / 86_400_000) + 1) : 1 } },
    { id: 'qc', at: latestOf([mech?.at, elec?.at]), ref: null, byName: elec?.byName ?? mech?.byName ?? null, facts: {} },
    { id: 'compliance', at: cert?.issuedAt ?? null, ref: cert?.code ?? null, byName: cert?.issuedByName ?? null, facts: { standard: cert ? (cert.primary.id === 'other' ? (cert.primary.label ?? cert.primary.id) : cert.primary.id) : '' } },
    { id: 'handover', at: walk.conducted?.at ?? null, ref: null, byName: walk.conducted?.byName ?? null, facts: { signed: walk.signoff ? 1 : 0 } },
    { id: 'warranty', at: reg?.registeredAt ?? null, ref: null, byName: reg?.registeredByName ?? null, facts: { parts: reg?.terms.parts.length ?? 0 } },
  ];
  void now;
  return {
    customerName: deal?.customerId ? (byId(users, deal.customerId)?.name ?? '') : (lead?.contactName ?? ''),
    siteName: job.siteName,
    address: job.address,
    city: lead?.city ?? '',
    jobCode: job.code,
    dealCode: deal?.code ?? '',
    value: deal ? deal.agreedPrice || deal.quotedPrice : 0,
    driveType: spec?.driveType ?? '',
    finishTier: spec?.finishTier ?? '',
    capacityPersons: spec?.capacityPersons ?? null,
    stops: spec?.stopsCount ?? null,
    milestones,
    compliance: cert ? { code: cert.code, standard: cert.primary.id === 'other' ? (cert.primary.label ?? cert.primary.id) : cert.primary.id, state: cert.state, issuedAt: cert.issuedAt } : null,
    warranty: reg ? { startsOn: reg.startsOn, serviceEndsOn: reg.terms.service.endsOn, partsCount: reg.terms.parts.length, amc: reg.amc ? { status: reg.amc.status, tier: reg.amc.tier ?? null, endsOn: reg.amc.terms[reg.amc.terms.length - 1]?.endsOn ?? null } : null } : null,
  };
}

function completionDocumentsOf(job: Job, role: WrRole): CompletionDocument[] {
  const s = completionSummaryOf(job, Date.now());
  const m = (id: CompletionMilestone['id']) => s.milestones.find((x) => x.id === id) as CompletionMilestone;
  const staff = role === 'admin';
  const docs: CompletionDocument[] = [
    { id: 'quotation', ref: m('quotation').ref, at: m('quotation').at, route: null },
    { id: 'contract', ref: m('contract').ref, at: m('contract').at, route: null },
    { id: 'delivery', ref: null, at: m('delivery').at, route: '/delivery-confirmation' },
    { id: 'installation', ref: job.code, at: m('installation').at, route: `/installation-timeline/${job.id}` },
    { id: 'compliance', ref: s.compliance?.code ?? null, at: s.compliance?.issuedAt ?? null, route: staff ? `/compliance/${job.id}` : null },
    { id: 'walkthrough', ref: null, at: m('handover').at, route: `/handover-walkthrough/${job.id}` },
    { id: 'warranty', ref: null, at: m('warranty').at, route: `/warranty/${job.id}` },
  ];
  if (staff) {
    docs.splice(4, 0, { id: 'safety', ref: null, at: null, route: `/safety-checklist/${job.id}` }, { id: 'materials', ref: null, at: null, route: `/material-usage/${job.id}` });
    docs.splice(7, 0, { id: 'handover_checklist', ref: null, at: null, route: `/handover-checklist/${job.id}` });
  }
  return docs;
}

function completionViewOf(job: Job, role: WrRole, now: number): CompletionView {
  const rec = completionOf(job.id);
  const walk = walkthroughOf(job.id);
  const reg = registrationOf(job.id);
  const readiness = coReadiness({ unlocked: handoverUnlocked(job.id), conducted: walk.conducted ? { at: walk.conducted.at } : null, mode: walk.mode, signedOff: !!walk.signoff, warrantyRegistered: !!reg }, now);
  const status: CompletionView['status'] = rec ? 'issued' : readiness.problems.length === 0 || readiness.canWaiveSignoff ? 'ready' : 'not_ready';
  const staff = role === 'admin';
  const plan = rec ? null : staff ? payoutPlanOf(job, now) : null;
  const summary = rec ? rec.summary : completionSummaryOf(job, now);
  const last = reg?.amc?.terms[reg.amc.terms.length - 1];
  const lineView = (l: FinalPayoutLine): CompletionPayoutLineView => {
    const e = byId(commissions, l.commissionId);
    return { ...l, status: e?.status ?? 'approved', currentAmount: e?.amount ?? l.amount, held: !!e?.heldBy };
  };
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, address: job.address, status: job.status },
    viewer: role,
    status,
    readiness: { problems: readiness.problems, canWaiveSignoff: readiness.canWaiveSignoff, signoffDueAt: walk.conducted ? coSignoffDue(walk.conducted.at, walk.mode) : null },
    issued: !!rec,
    certificateNo: rec?.certificateNo ?? null,
    issuedAt: rec?.issuedAt ?? null,
    issuedByName: rec?.issuedByName ?? null,
    signoffWaived: rec?.signoffWaived && staff ? { ...rec.signoffWaived } : null,
    summary,
    team: (rec ? rec.team : (plan ?? payoutPlanOf(job, now)).team).map((x) => (staff ? { ...x } : { ...x, minutes: 0, steps: 0, results: 0 })),
    documents: completionDocumentsOf(job, role),
    ongoing: { warrantyEndsOn: reg?.terms.service.endsOn ?? null, amcStatus: reg?.amc?.status ?? null, amcEndsOn: last?.endsOn ?? null },
    payout: !staff
      ? null
      : rec
        ? { triggered: true, triggeredAt: rec.payout.triggeredAt, basis: 'time', lines: rec.payout.lines.map(lineView), pools: { ...rec.payout.pools }, notPaid: [] }
        : { triggered: false, triggeredAt: null, basis: (plan as PayoutPlan).basis, lines: (plan as PayoutPlan).lines.map((l, i) => ({ ...l, id: `prev-${i}`, commissionId: l.existingId ?? '', status: (l.existingId ? byId(commissions, l.existingId)?.status : undefined) ?? 'projected', currentAmount: l.amount, held: false })), pools: { ...(plan as PayoutPlan).pools }, notPaid: (plan as PayoutPlan).notPaid },
    judgements: staff && rec ? rec.judgements.map((j) => ({ ...j, changes: j.changes.map((c) => ({ ...c, before: { ...c.before }, after: { ...c.after } })) })) : [],
    actions: { issue: staff && !rec && status === 'ready' && job.status === 'handover_pending', judge: staff && !!rec },
  };
}

/** What the commitments read: a project that has everything it needs and is waiting for Admin to issue its certificate. */
function completionSignals(): { jobId: string; readyAt: string; issued: boolean; issuedAt?: string }[] {
  return walkthroughSignals().flatMap((x) => {
    const reg = registrationOf(x.jobId);
    const w = x.w;
    const job = byId(jobs, x.jobId);
    if (!job || !w.conducted || !w.signoff || !reg) return [];
    const rec = completionOf(x.jobId);
    return [{ jobId: x.jobId, readyAt: [w.conducted.at, w.signoff.at, reg.registeredAt].sort().pop() as string, issued: !!rec, ...(rec ? { issuedAt: rec.issuedAt } : {}) }];
  });
}

/** One message to the customer through the Communication Engine, in their language, unless they opted out. */
function messageLeadFromTemplate(lead: Lead, groupId: string, fields: Record<string, string>, at: string): CommChannel | null {
  const language = lead.preferredLanguage ?? 'en';
  const template = templateInGroup(groupId, language) ?? templateInGroup(groupId, 'en');
  if (!template || isOptedOutSync(lead.contactPhone, template.channel)) return null;
  let conversation = conversations.find((c) => c.leadId === lead.id) ?? null;
  if (!conversation) {
    conversationCounter += 1;
    conversation = { id: `conv-new-${conversationCounter}`, leadId: lead.id, lastMessageAt: at, isDemo: true };
    conversations.push(conversation);
  }
  messageCounter += 1;
  commMessages.push({ id: `cm-new-${messageCounter}`, conversationId: conversation.id, channel: template.channel, sender: 'bot', body: renderTemplateBody(template.body, { customerName: lead.contactName, buildingName: lead.siteName, ...fields }), templateGroupId: groupId, status: 'sent', at, handled: true });
  patchInPlace(conversations, conversation.id, { lastMessageAt: at });
  return template.channel;
}

/* ============================== Installation SOP (123) */

const installSopVersions: InstallSopVersion[] = seedInstallSopVersions.map((v) => ({ ...v, steps: v.steps.map((st) => ({ ...st, slots: st.slots.map((sl) => ({ ...sl })), dependsOn: [...st.dependsOn] })) }));
let sopEvidenceCounter = 0;
/** A photo is a data URL held in memory: a cap keeps one absurd file from swelling the whole session. */
const SOP_PHOTO_MAX = 6_000_000;

/** What the sold configuration says about the two things that decide which parts of the procedure apply. */
function sopSpecOf(job: Job): SpecFacts {
  const deal = byId(deals, job.dealId);
  const spec = (deal ? resolveLead(deal.leadId) : null)?.spec;
  return spec ? { powerBackup: spec.powerBackup, doorType: spec.doorType } : null;
}

/** The procedure a job is done under: the version it was pinned to when it started, else the one in force now. */
function sopVersionOf(job: Job): InstallSopVersion {
  const pinned = job.sopVersion ? installSopVersions.find((v) => v.version === job.sopVersion) : undefined;
  return pinned ?? installVersionInForce(installSopVersions, Date.now()) ?? installSopVersions[installSopVersions.length - 1];
}

const sopMaterialsConfirmed = (job: Job): boolean => {
  const m = jobMaterialsOf(job.dealId);
  return m.total === 0 || m.onSite === m.total;
};

/** Steps not done are `upcoming`, except the one in hand. A blocked one (a QC failure) stays blocked until it is redone. */
function withCurrent(steps: JobStep[], defs: InstallSopStepDef[], prefer: string | null): JobStep[] {
  const open = (id: string | null) => !!id && !isDone(steps.find((x) => x.id === id));
  const currentNow = steps.find((x) => x.status === 'current')?.id ?? null;
  const pick = open(prefer) ? prefer : open(currentNow) ? currentNow : suggestedNext(defs, steps);
  return steps.map((x) => (isDone(x) ? x : x.status === 'blocked' && x.id !== pick ? x : { ...x, status: x.id === pick ? ('current' as const) : ('upcoming' as const) }));
}

/** The delivery confirmation (104) is the evidence for "materials received": it satisfies that step, and it is never ticked twice. */
function syncSopMaterialsStep(job: Job): Job {
  if (job.status !== 'in_progress') return job;
  const version = sopVersionOf(job);
  const def = version.steps.find((d) => d.satisfiedByDelivery);
  const step = def ? job.steps.find((x) => x.id === def.id) : undefined;
  if (!def || !step || isDone(step) || unmetDependencies(def, job.steps).length > 0 || !materialsConfirmedAt(job.dealId)) return job;
  const steps = withCurrent(job.steps.map((x) => (x.id === def.id ? { ...x, status: 'complete' as const, completedAt: materialsConfirmedAt(job.dealId) as string, completedByName: 'Delivery confirmation' } : x)), version.steps, null);
  logAutomatedAction({
    sourceKey: 'installation.materials_step_satisfied',
    triggeringCondition: `The delivery confirmation for ${job.siteName} was signed`,
    actionTaken: `Marked "materials received" done on ${job.code}, so it is not ticked a second time`,
    affectedRecordId: job.id,
    affectedRecordType: 'other',
    subjectLabel: job.code,
  });
  return patchInPlace(jobs, job.id, { steps });
}

function installationSopViewOf(jobIn: Job, userId: string): InstallationSopView {
  const job = syncSopMaterialsStep(jobIn);
  const role = roleOf(job, userId) ?? 'lead';
  const own = ownStepIds(job, userId);
  const version = sopVersionOf(job);
  const spec = sopSpecOf(job);
  const facts = { materialsConfirmed: sopMaterialsConfirmed(job) };
  const inProgress = job.status === 'in_progress';
  const leadName = job.technicianId ? (byId(users, job.technicianId)?.name ?? '') : '';
  const readOnly = !inProgress && job.status !== 'scheduled' && job.status !== 'materials_pending';
  const steps: SopStepView[] = version.steps.flatMap((def) => {
    const step = job.steps.find((x) => x.id === def.id);
    if (!step) return [];
    const mine = own === null || own.includes(def.id);
    const done = isDone(step);
    const unmet = unmetDependencies(def, job.steps);
    let problem: SopStepView['problem'] = null;
    if (!done) {
      if (!mine) problem = 'not_yours';
      else if (!inProgress) problem = readOnly ? 'read_only' : 'not_started';
      else problem = completionProblem(def, job.steps, spec, facts) as SopStepView['problem'];
    }
    const missing = missingSlots(def, step, spec).map((sl) => sl.id);
    return [
      {
        id: def.id,
        labelKey: def.labelKey,
        phase: def.phase,
        safetyCritical: def.safetyCritical,
        status: step.status,
        done,
        notApplicable: step.notApplicable ?? null,
        applies: stepApplies(def, spec),
        slots: slotsFor(def, spec).map((sl) => {
          const ex = exceptionOf(step, sl.id);
          return { id: sl.id, labelKey: sl.labelKey, required: sl.required, kind: sl.kind, photo: activeProofOf(step, sl.id), history: historyOf(step, sl.id), exception: ex ? { ...ex, acknowledged: exceptionAcknowledged(job.id, def.id, sl.id) } : null };
        }),
        otherFindings: historyOf(step, FINDING_SLOT),
        problem,
        dependsOn: [...def.dependsOn],
        waitingFor: unmet.map((id) => version.steps.find((d) => d.id === id)?.labelKey ?? id),
        missingSlotIds: missing,
        canNotApplicable: !done && mine && inProgress && !naProblem(def, step, spec, 'x'.repeat(20)),
        legacyEvidence: step.evidence === undefined && step.evidenceCount > 0,
        satisfiedByDelivery: !!def.satisfiedByDelivery,
        completedAt: step.completedAt ?? null,
        completedByName: step.completedByName ?? null,
        owner: { isYou: mine, name: mine ? '' : leadName },
      },
    ];
  });
  const readiness = qcReadiness(version.steps, job.steps, spec);
  const awaitingAdmin = sopAwaitingAdmin(job, version);
  const materials = jobMaterialsOf(job.dealId);
  const early = dayKey(job.scheduledFor) > dayKey(Date.now());
  const startProblem: InstallationSopView['startProblem'] = job.status === 'on_hold' ? 'on_hold' : job.status === 'materials_pending' || (job.status === 'scheduled' && materials.total > 0 && materials.onSite < materials.total) ? 'materials_not_confirmed' : job.status === 'scheduled' && early ? 'not_scheduled_yet' : null;
  return {
    job: { id: job.id, code: job.code, siteName: job.siteName, status: job.status, role, scheduledFor: job.scheduledFor, startedAt: job.startedAt ?? null, holdReason: job.holdReason ?? null },
    version: { version: version.version, effectiveFrom: version.effectiveFrom, changeNote: version.changeNote },
    steps,
    progress: { done: steps.filter((x) => x.done).length, total: steps.length },
    currentStepId: steps.find((x) => x.status === 'current')?.id ?? null,
    qcReady: readiness.ready && awaitingAdmin.length === 0 && (job.status === 'qc_pending' || job.status === 'handover_pending' || job.status === 'completed'),
    awaitingAdmin,
    safetyOpen: safetyBlocking(job).length,
    findings: job.steps.reduce((n, x) => n + (x.evidence ?? []).filter((e) => e.finding).length, 0),
    canStart: job.status === 'scheduled' && startProblem === null,
    startProblem: job.status === 'scheduled' || job.status === 'materials_pending' || job.status === 'on_hold' ? startProblem : null,
    readOnly,
  };
}

/** The job, the person acting and their part of it. Only someone on the job may act, and an assistant only on their own steps. */
function sopActor(jobId: string, technicianId: string, stepId?: string): { job: Job; user: User; def: InstallSopStepDef | null } {
  const user = byId(users, technicianId);
  const job = byId(jobs, jobId);
  if (!user || user.role !== 'technician') throw new RepositoryError('forbidden');
  if (!job) throw new RepositoryError('not_found');
  if (!isOnJob(job, technicianId)) throw new RepositoryError('forbidden');
  if (!stepId) return { job, user, def: null };
  const def = sopVersionOf(job).steps.find((d) => d.id === stepId);
  if (!def || !job.steps.some((x) => x.id === stepId)) throw new RepositoryError('not_found');
  const own = ownStepIds(job, technicianId);
  if (own !== null && !own.includes(stepId)) throw new RepositoryError('not_yours');
  return { job, user, def };
}

/** Work goes in only while the job is in progress; a job with QC, on hold or finished is read-only here. */
function sopWorkable(job: Job): Job {
  const current = syncSopMaterialsStep(job);
  if (current.status === 'scheduled' || current.status === 'materials_pending') throw new RepositoryError('not_started');
  if (current.status !== 'in_progress') throw new RepositoryError(current.status === 'on_hold' ? 'job_on_hold' : 'read_only');
  return current;
}

/** Everything done, with all its evidence: the job is handed to QC. */
function sopFinishIfDone(jobIn: Job, version: InstallSopVersion, actorId?: string): Job {
  let job = jobIn;
  if (job.status !== 'in_progress') return job;
  if (!qcReadiness(version.steps, job.steps, sopSpecOf(job)).ready) return job;
  // With more than one person on the job, the lead has the last word (130): finishing the last step as the lead is that word, and anyone else
  // finishing it leaves the job waiting for the lead's sign-off.
  if (peopleOn(job).length > 1 && !job.leadSignOff) {
    if (!actorId || !leadIdsOf(job).includes(actorId)) return job;
    job = patchInPlace(jobs, job.id, { leadSignOff: { at: new Date().toISOString(), byUserId: actorId, byName: byId(users, actorId)?.name ?? '' } });
  }
  // Evidence that could not be captured on a safety-critical step is Admin's to accept before the job is handed to QC.
  if (sopAwaitingAdmin(job, version).length > 0) return job;
  // A safety check not passed (or accepted by Admin with a named engineer) stops the job here, with no way round for a technician alone.
  if (safetyBlocking(job).length > 0) return job;
  return patchInPlace(jobs, job.id, { status: 'qc_pending' as const });
}

/** Whether Admin has seen the exception: the alert raised for it was acknowledged or resolved. */
function exceptionAcknowledged(jobId: string, stepId: string, slotId: string): boolean {
  const key = exceptionKey(jobId, stepId, slotId);
  const a = alerts.find((x) => x.relatedId === key);
  return !a || a.status !== 'open';
}

/** Safety-critical exceptions Admin has not yet acknowledged. */
function sopAwaitingAdmin(job: Job, version: InstallSopVersion): { stepId: string; slotId: string }[] {
  return version.steps.flatMap((def) => {
    if (!def.safetyCritical) return [];
    const step = job.steps.find((x) => x.id === def.id);
    return (step?.evidenceExceptions ?? []).filter((e) => !exceptionAcknowledged(job.id, def.id, e.slotId)).map((e) => ({ stepId: def.id, slotId: e.slotId }));
  });
}

/** A job whose checklist is complete but for Admin's acknowledgement moves to QC the moment that is given, without anyone re-opening it. */
function syncSopHandoff(): void {
  for (const job of jobs) {
    if (job.status !== 'in_progress') continue;
    const version = sopVersionOf(job);
    const after = sopFinishIfDone(job, version);
    if (after.status === 'qc_pending') {
      logAutomatedAction({
        sourceKey: 'installation.qc_handoff',
        triggeringCondition: `The last thing holding ${job.code} back (an evidence exception or a safety check) was cleared`,
        actionTaken: 'Handed the finished installation checklist to quality check',
        affectedRecordId: job.id,
        affectedRecordType: 'other',
        subjectLabel: job.code,
      });
    }
  }
}

function technicianJobViewOf(job: Job, userId: string, clashCodes: string[]): TechnicianJobView {
  const role = roleOf(job, userId) ?? 'lead';
  const own = ownStepIds(job, userId);
  const steps = own ? job.steps.filter((st) => own.includes(st.id)) : job.steps;
  const currentAt = steps.findIndex((st) => st.status !== 'complete');
  const deal = byId(deals, job.dealId);
  const lead = deal ? resolveLead(deal.leadId) : null;
  const customer = deal?.customerId ? byId(users, deal.customerId)?.name : undefined;
  const teamOf = (id: string) => ({ name: byId(users, id)?.name ?? '', role: (id === job.technicianId ? 'lead' : 'assistant') as 'lead' | 'assistant' });
  return {
    id: job.id,
    code: job.code,
    siteName: job.siteName,
    address: job.address,
    location: job.location,
    customerName: customer ?? lead?.contactName ?? null,
    status: job.status,
    scheduledFor: job.scheduledFor,
    startedAt: job.startedAt ?? null,
    role,
    leadName: role === 'assistant' && job.technicianId ? (byId(users, job.technicianId)?.name ?? null) : null,
    teammates: peopleOn(job).filter((id) => id !== userId).map(teamOf),
    myTasks: own ? steps.map((st) => ({ id: st.id, labelKey: st.labelKey, status: st.status })) : [],
    stage: currentAt === -1 ? null : { labelKey: steps[currentAt].labelKey, index: currentAt + 1, total: steps.length },
    progress: { done: steps.filter((st) => st.status === 'complete').length, total: steps.length },
    action: actionOf(job.status),
    holdReason: job.holdReason ?? null,
    clashesWith: clashCodes,
  };
}

/* ============================== Auto-reconciliation (120) */

const bankTransactions: BankTransaction[] = seedBankTransactions.map((b) => ({ ...b }));
let bankFeed: BankFeed = { status: 'connected', since: new Date(Date.now() - 6 * 3_600_000).toISOString(), lastStatementAt: new Date(Date.now() - 3 * 3_600_000).toISOString() };
const reconRuns: ReconciliationRun[] = [];
const reconExceptions: ReconException[] = [];
let reconRunCounter = 0;
let reconExceptionCounter = 0;
let reconSeeded = false;
const RECON_FEED_ALERT = 'reconciliation.alert.noBank';

const bankSideOf = (b: BankTransaction): BankSideView => ({ id: b.id, postedAt: b.postedAt, direction: b.direction, amount: b.amount, reference: b.reference, narration: b.narration, counterparty: b.counterparty });

/** What the app recorded as money moving: every executed supplier payment, every amount received from a customer (a financing
 *  partner's disbursement across several stages is the one bank credit it really was) and every refund paid back. */
function ledgerEntriesOf(): LedgerSideView[] {
  const out: LedgerSideView[] = [];
  for (const p of supplierPayments) {
    if (p.status !== 'executed' || !p.executedAt) continue;
    out.push({ id: `supplier_payment:${p.id}`, kind: 'supplier_payment', codes: [p.code], direction: 'out', amount: p.amount, date: p.executedAt, reference: p.bankReference ?? null, counterparty: byId(suppliers, p.supplierId)?.name ?? '', route: `/supplier-payment-history?payment=${p.id}` });
  }
  const financing = new Map<string, LedgerSideView>();
  const who = (dealId: string) => {
    const deal = byId(deals, dealId);
    const lead = deal ? resolveLead(deal.leadId) : null;
    return lead?.builderName || lead?.contactName || '';
  };
  for (const p of payments) {
    const received = p.amountReceived ?? (p.status === 'paid' ? p.amount : 0);
    const date = p.lastReceivedAt ?? p.paidAt;
    if (received > 0 && date) {
      if (p.method === 'financing') {
        const key = `${p.dealId}:${date.slice(0, 10)}`;
        const cur = financing.get(key);
        if (cur) {
          cur.amount += received;
          cur.codes.push(p.code);
        } else financing.set(key, { id: `customer_receipt:${p.id}`, kind: 'customer_receipt', codes: [p.code], direction: 'in', amount: received, date, reference: null, counterparty: 'Financing partner', route: '/payments/history' });
      } else {
        out.push({ id: `customer_receipt:${p.id}`, kind: 'customer_receipt', codes: [p.code], direction: 'in', amount: received, date, reference: p.gatewayTransactionRef ?? p.manualReferenceNumber ?? null, counterparty: who(p.dealId), route: '/payments/history' });
      }
    }
    if ((p.resolutionType === 'full_refund' || p.resolutionType === 'partial_refund') && (p.resolutionAmount ?? 0) > 0 && !p.refundRoutedToFinancingPartner && p.resolvedAt) {
      out.push({ id: `customer_refund:${p.id}`, kind: 'customer_refund', codes: [p.code], direction: 'out', amount: p.resolutionAmount as number, date: p.resolvedAt, reference: null, counterparty: who(p.dealId), route: '/admin/analytics/collections/disputes' });
    }
  }
  return [...out, ...financing.values()];
}

/** Compares the statement with the records over the window ending at `at`. Never called with a feed that is down. */
function currentReconciliation(at: number) {
  const from = at - RECON_WINDOW;
  const bank = bankTransactions.filter((b) => new Date(b.postedAt).getTime() >= from && new Date(b.postedAt).getTime() <= at);
  const ledger = ledgerEntriesOf().filter((l) => new Date(l.date).getTime() >= from && new Date(l.date).getTime() <= at);
  const bankLines: BankLine[] = bank.map((b) => ({ id: b.id, postedAt: b.postedAt, direction: b.direction, amount: b.amount, reference: b.reference, narration: b.narration, counterparty: b.counterparty }));
  const ledgerLines: LedgerLine[] = ledger.map((l) => ({ id: l.id, direction: l.direction, amount: l.amount, date: l.date, reference: l.reference, counterparty: l.counterparty }));
  return { from, outcome: reconcile(bankLines, ledgerLines, at), ledger };
}

function runReconciliationAt(at: number, trigger: 'scheduled' | 'manual', byName: string, feed: { up: boolean; reason?: BankFeed['reason'] }): ReconciliationRun {
  reconRunCounter += 1;
  const id = `rrun-${reconRunCounter}`;
  const iso = new Date(at).toISOString();
  const base = { id, code: `AIEC-RC-${5000 + reconRunCounter}`, runAt: iso, trigger, byName, windowFrom: new Date(at - RECON_WINDOW).toISOString(), windowTo: iso, isDemo: true };
  if (!feed.up) {
    // Comparing against nothing would read as "all matched". It is reported as not run, and nothing about the exceptions changes.
    const run: ReconciliationRun = { ...base, status: 'could_not_run', matchedCount: 0, matchedAmount: 0, explainedCount: 0, pendingCount: 0, matched: [], unmatched: [], feedReason: feed.reason };
    reconRuns.push(run);
    return run;
  }
  const { from, outcome } = currentReconciliation(at);
  const seen = new Set<string>();
  for (const raw of outcome.exceptions) {
    seen.add(raw.key);
    const existing = reconExceptions.find((e) => e.key === raw.key);
    if (existing) {
      patchInPlace(reconExceptions, existing.id, { lastSeenRunId: id, ...(existing.status === 'open' ? { amount: raw.amount, difference: raw.difference } : {}) });
    } else {
      reconExceptionCounter += 1;
      reconExceptions.push({ id: `rex-${reconExceptionCounter}`, key: raw.key, kind: raw.kind, direction: raw.direction, amount: raw.amount, difference: raw.difference, bankTxnId: raw.bankId, ledgerId: raw.ledgerId, reference: raw.reference, counterparty: raw.counterparty, occurredAt: raw.occurredAt, firstSeenAt: iso, firstSeenRunId: id, lastSeenRunId: id, status: 'open', isDemo: true });
    }
  }
  // What was open and is now in step (a payment the bank has since shown) closes itself. An older one the window no longer reaches stays open.
  for (const e of reconExceptions) {
    if (e.status === 'open' && !seen.has(e.key) && new Date(e.occurredAt).getTime() >= from) patchInPlace(reconExceptions, e.id, { status: 'cleared', clearedAt: iso });
  }
  const now_ = reconExceptions.filter((e) => seen.has(e.key));
  const open = now_.filter((e) => e.status === 'open');
  const clean = outcome.matches.filter((m) => Math.abs(m.difference) <= 1);
  const ledgerById = new Map(ledgerEntriesOf().map((l) => [l.id, l]));
  const run: ReconciliationRun = {
    ...base,
    status: runStatusOf(open),
    matchedCount: clean.length,
    matchedAmount: clean.reduce((n, m) => n + (ledgerById.get(m.ledgerId)?.amount ?? 0), 0),
    explainedCount: now_.filter((e) => e.status === 'reconciled').length,
    pendingCount: outcome.pending.length,
    matched: clean,
    unmatched: open.map((e) => ({ exceptionId: e.id, kind: e.kind, direction: e.direction, amount: e.amount, reference: e.reference, date: e.occurredAt, counterparty: e.counterparty })),
  };
  reconRuns.push(run);
  return run;
}

/** The last week of daily runs, as the schedule would have made them, so the log is not empty on day one. One of those days the
 *  bank connection was down. */
function ensureReconSeeded(now: number): void {
  if (reconSeeded) return;
  reconSeeded = true;
  for (let k = 7; k >= 1; k -= 1) {
    runReconciliationAt(latestSlot(now - k * DAY_MS), 'scheduled', ASSISTANT_ACTOR, k === 3 ? { up: false, reason: 'outage' } : { up: true });
  }
}

/** Runs the daily reconciliation when it is due, tries again as soon as a connection that was down is back, and keeps the alerts
 *  in step. Idempotent: the heartbeat calls it every minute. */
function syncReconciliation(now: number): void {
  ensureReconSeeded(now);
  const last = reconRuns[reconRuns.length - 1];
  const up = bankFeed.status === 'connected';
  const daily = !last || new Date(last.runAt).getTime() < latestSlot(now);
  const restored = !!last && last.status === 'could_not_run' && up;
  if (daily || restored) {
    const run = runReconciliationAt(now, 'scheduled', ASSISTANT_ACTOR, { up, reason: bankFeed.reason });
    if (up) bankFeed = { ...bankFeed, lastStatementAt: new Date(now).toISOString() };
    logAutomatedAction({
      sourceKey: run.status === 'could_not_run' ? 'reconciliation.could_not_run' : 'reconciliation.run',
      triggeringCondition: restored ? 'The bank connection came back after a run could not be made' : 'The daily reconciliation was due',
      actionTaken: run.status === 'could_not_run' ? 'Recorded that no bank data was available, so nothing was compared' : `Compared the bank statement with the records: ${run.matchedCount} matched, ${run.unmatched.length} to look at`,
      affectedRecordId: run.id,
      affectedRecordType: 'other',
      subjectLabel: run.code,
    });
  }
  syncReconciliationAlerts(now);
}

function syncReconciliationAlerts(now: number): void {
  const at = new Date(now).toISOString();
  for (const e of reconExceptions) {
    const sev = severityOf(e.kind, e.amount, e.difference);
    const titleKey = `reconciliation.alert.${e.kind}`;
    const open = alerts.find((a) => a.relatedId === e.id && a.titleKey === titleKey && a.status !== 'resolved');
    // A small expected difference is on the screen and in the work list; it is not an alarm.
    if (e.status === 'open' && sev !== 'low' && !open) {
      raiseAlert({ titleKey, context: `${formatINR(e.amount)} · ${e.counterparty}`, severity: sev === 'critical' ? 'critical' : 'high', category: 'payment', relatedId: e.id, sourceRoute: `/reconciliation?exception=${e.id}` });
      logAutomatedAction({
        sourceKey: 'reconciliation.exception',
        triggeringCondition: `The bank statement and the records disagree: ${e.kind.replace(/_/g, ' ')} of ${formatINR(e.amount)}`,
        actionTaken: sev === 'critical' ? 'Raised a critical alert: it looks like a payment recorded or made twice' : 'Raised an alert so the mismatch is seen with the other exceptions',
        affectedRecordId: e.id,
        affectedRecordType: 'other',
        subjectLabel: e.counterparty,
      });
    } else if (e.status !== 'open' && open) {
      patchInPlace(alerts, open.id, { status: 'resolved', resolvedAt: at, resolvedBy: e.status === 'reconciled' ? (e.reconciled?.byName ?? 'Admin') : 'system', resolutionNote: e.status === 'reconciled' ? 'Explained by hand.' : 'The records caught up with the statement.' });
    }
  }
  const last = reconRuns[reconRuns.length - 1];
  const feedOpen = alerts.find((a) => a.relatedId === 'bank-feed' && a.titleKey === RECON_FEED_ALERT && a.status !== 'resolved');
  if (last?.status === 'could_not_run' && bankFeed.status === 'unavailable' && !feedOpen) {
    raiseAlert({ titleKey: RECON_FEED_ALERT, context: 'Reconciliation', severity: 'medium', category: 'payment', relatedId: 'bank-feed', sourceRoute: '/reconciliation' });
  } else if ((bankFeed.status === 'connected' || last?.status !== 'could_not_run') && feedOpen) {
    patchInPlace(alerts, feedOpen.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'The bank connection is back.' });
  }
}

function reconExceptionView(e: ReconException, now: number, ledger: Map<string, LedgerSideView>): ReconExceptionView {
  const bank = e.bankTxnId ? byId(bankTransactions, e.bankTxnId) : null;
  return {
    id: e.id,
    kind: e.kind,
    severity: severityOf(e.kind, e.amount, e.difference),
    direction: e.direction,
    amount: e.amount,
    difference: e.difference,
    reference: e.reference,
    counterparty: e.counterparty,
    occurredAt: e.occurredAt,
    firstSeenAt: e.firstSeenAt,
    ageDays: Math.max(0, Math.floor((now - new Date(e.firstSeenAt).getTime()) / DAY_MS)),
    status: e.status,
    bank: bank ? bankSideOf(bank) : null,
    ledger: e.ledgerId ? (ledger.get(e.ledgerId) ?? null) : null,
    canReconcileAs: e.status === 'open' ? reasonsFor(e) : [],
    reconciled: e.reconciled ?? null,
    clearedAt: e.clearedAt ?? null,
    firstSeenRunCode: reconRuns.find((r) => r.id === e.firstSeenRunId)?.code ?? '',
  };
}

const SEVERITY_RANK = { critical: 0, high: 1, low: 2 } as const;

function reconRunRow(r: ReconciliationRun): ReconRunRow {
  return { id: r.id, code: r.code, runAt: r.runAt, trigger: r.trigger, byName: r.byName, status: r.status, matchedCount: r.matchedCount, unmatchedCount: r.unmatched.length, explainedCount: r.explainedCount, pendingCount: r.pendingCount, feedReason: r.feedReason ?? null };
}

/* ============================== Supplier payment analytics (119) */

const spendNotes: SupplierSpendNote[] = [];
let spendNoteCounter = 0;
const REVIEW_ALERT = 'supplierPaymentAnalytics.alert.review';

const spendNoteView = (n: SupplierSpendNote): SpendNoteView => ({ id: n.id, month: n.month, label: n.label, note: n.note ?? null, byName: n.createdByName, at: n.createdAt });

/** Every figure is read off the payments, retentions and disputes already recorded; none of it is stored. */
function computeSupplierPaymentAnalytics(months: AnalyticsMonths, now: number): SupplierPaymentAnalytics {
  const keys = monthKeys(months, now);
  const from = windowStart(months, now);
  const before = previousWindow(months, now);
  const neutral = (k: KpiFigure): KpiFigure => ({ ...k, tone: 'neutral' });
  const paidAtOf = (p: SupplierPayment) => new Date(p.executedAt as string).getTime();
  const paid = supplierPayments.filter((p) => p.status === 'executed' && p.executedAt);
  const inWindow = paid.filter((p) => paidAtOf(p) >= from && paidAtOf(p) <= now);
  const inBefore = paid.filter((p) => paidAtOf(p) >= before.from && paidAtOf(p) < before.to);
  const net = (p: SupplierPayment) => historyEntryOf(p).netAmount;
  const supplierName = (id: string) => byId(suppliers, id)?.name ?? id;

  /* ---- spend */
  const monthTotals = keys.map((key) => {
    const rows = inWindow.filter((p) => monthKey(p.executedAt as string) === key);
    return { key, total: rows.reduce((n, p) => n + net(p), 0), rows };
  });
  const spendMonths: SpendMonthView[] = monthTotals.map((m) => {
    const reading = spikeOf(m.key, monthTotals);
    let spike: SpendMonthView['spike'] = null;
    if (reading) {
      const perPo = new Map<string, { amount: number; top: SupplierPayment }>();
      for (const p of m.rows) {
        const cur = perPo.get(p.poId);
        perPo.set(p.poId, { amount: (cur?.amount ?? 0) + net(p), top: cur && net(cur.top) >= net(p) ? cur.top : p });
      }
      const big = [...perPo.entries()].sort((a, b) => b[1].amount - a[1].amount)[0];
      spike = {
        ratio: reading.ratio,
        typical: Math.round(reading.typical),
        largest: big
          ? { paymentCode: big[1].top.code, poCode: byId(supplierPurchaseOrders, big[0])?.code ?? big[0], supplierName: supplierName(big[1].top.supplierId), amount: big[1].amount, sharePct: Math.round((big[1].amount / m.total) * 100) }
          : null,
        oneOrder: !!big && oneOrderExplains(big[1].amount, m.total),
      };
    }
    const note = spendNotes.find((n) => n.month === m.key);
    return { key: m.key, total: m.total, payments: m.rows.length, spike, note: note ? spendNoteView(note) : null };
  });
  const spendTotal = monthTotals.reduce((n, m) => n + m.total, 0);
  const spendBefore = inBefore.reduce((n, p) => n + net(p), 0);
  const typicalMonth = median(monthTotals.filter((m) => m.total > 0).map((m) => m.total));

  const rowsFor = (group: (p: SupplierPayment) => Record<string, number>, nameOf: (id: string) => string): SpendRowView[] => {
    const now_: Record<string, { total: number; byMonth: number[]; payments: number }> = {};
    for (const p of inWindow) {
      const idx = keys.indexOf(monthKey(p.executedAt as string));
      for (const [id, amount] of Object.entries(group(p))) {
        const r = (now_[id] ??= { total: 0, byMonth: keys.map(() => 0), payments: 0 });
        r.total += amount;
        if (idx >= 0) r.byMonth[idx] += amount;
        r.payments += 1;
      }
    }
    const prior: Record<string, number> = {};
    for (const p of inBefore) for (const [id, amount] of Object.entries(group(p))) prior[id] = (prior[id] ?? 0) + amount;
    return Object.entries(now_)
      .map(([id, r]) => ({ id, name: nameOf(id), total: r.total, sharePct: spendTotal > 0 ? Math.round((r.total / spendTotal) * 100) : 0, previous: prior[id] ?? 0, changePct: prior[id] ? Math.round(((r.total - prior[id]) / prior[id]) * 100) : null, byMonth: r.byMonth, payments: r.payments }))
      .sort((a, b) => b.total - a.total);
  };
  const categoryOf = (p: SupplierPayment): Record<string, number> => {
    const po = byId(supplierPurchaseOrders, p.poId);
    return allocateByLines(net(p), (po?.lineItems ?? []).map((l) => ({ category: l.category, value: l.agreedUnitPrice * l.quantity })));
  };

  /* ---- speed: from the milestone firing to the money leaving */
  const paidCount = (supplierId: string) => paid.filter((p) => p.supplierId === supplierId).length;
  const facts = (list: SupplierPayment[]) => list.map((p) => ({ p, d: daysToPay(p.triggeredAt, p.executedAt as string), settling: !isRatedSupplier(paidCount(p.supplierId)) }));
  const nowFacts = facts(inWindow);
  const beforeFacts = facts(inBefore);
  const avgOf = (list: { d: number }[]) => oneDecimal(average(list.map((f) => f.d)));
  const pctWithin = (list: { d: number }[]) => (list.length === 0 ? null : Math.round((list.filter((f) => withinTarget(f.d)).length / list.length) * 100));
  const speedMonths: PaySpeedMonthView[] = keys.map((key) => {
    const list = nowFacts.filter((f) => monthKey(f.p.executedAt as string) === key);
    return { key, avgDays: avgOf(list), avgDaysExcl: avgOf(list.filter((f) => !f.settling)), count: list.length };
  });
  const speedSuppliers: PaySpeedRowView[] = [...new Set(nowFacts.map((f) => f.p.supplierId))]
    .map((id) => {
      const list = nowFacts.filter((f) => f.p.supplierId === id);
      return { id, name: supplierName(id), payments: list.length, avgDays: avgOf(list), withinTargetPct: pctWithin(list), rated: isRatedSupplier(paidCount(id)) };
    })
    .sort((a, b) => (b.avgDays ?? 0) - (a.avgDays ?? 0));
  const slowest: SlowPaymentView[] = [...nowFacts]
    .sort((a, b) => b.d - a.d)
    .slice(0, 5)
    .map((f) => ({ id: f.p.id, code: f.p.code, poCode: byId(supplierPurchaseOrders, f.p.poId)?.code ?? f.p.poId, supplierName: supplierName(f.p.supplierId), amount: net(f.p), days: oneDecimal(f.d) ?? 0, paidAt: f.p.executedAt as string, settling: f.settling }));
  const queue = supplierPayments.filter((p) => p.status === 'pending_approval' || p.status === 'approved');
  const waitingAges = queue.map((p) => (now - new Date(p.triggeredAt).getTime()) / DAY_MS);
  const speed: SupplierPaymentAnalytics['speed'] = {
    kpi: kpiOf(avgOf(nowFacts), avgOf(beforeFacts), 'lower', 0.2),
    kpiExcl: kpiOf(avgOf(nowFacts.filter((f) => !f.settling)), avgOf(beforeFacts.filter((f) => !f.settling)), 'lower', 0.2),
    medianDays: oneDecimal(median(nowFacts.map((f) => f.d))),
    withinTargetPct: pctWithin(nowFacts),
    targetDays: PAYMENT_TARGET_DAYS,
    payments: nowFacts.length,
    settling: nowFacts.filter((f) => f.settling).length,
    months: speedMonths,
    suppliers: speedSuppliers,
    slowest,
    waiting: {
      count: queue.length,
      amount: queue.reduce((n, p) => n + p.amount, 0),
      oldestDays: waitingAges.length ? Math.floor(Math.max(...waitingAges)) : null,
      overTarget: queue.filter((p) => p.status === 'pending_approval' && now - new Date(p.triggeredAt).getTime() > PAYMENT_TARGET).length,
      heldCount: supplierPayments.filter((p) => p.status === 'held').length,
    },
  };

  /* ---- retention: held against released over time */
  const inMonth = (iso: string | undefined, key: string) => !!iso && monthKey(iso) === key;
  const retentionMonths: RetentionMonthView[] = keys.map((key) => ({
    key,
    held: heldAt(supplierRetentions, endOfMonth(key, now)),
    released: supplierRetentions.filter((r) => r.status === 'released' && inMonth(r.decidedAt, key)).reduce((n, r) => n + r.amount, 0),
    withheld: supplierRetentions.filter((r) => r.status === 'withheld' && inMonth(r.decidedAt, key)).reduce((n, r) => n + r.amount, 0),
  }));
  const holding = supplierRetentions.filter((r) => r.status === 'held' || r.status === 'paused');
  const heldNow = holding.reduce((n, r) => n + r.amount, 0);
  const retention: SupplierPaymentAnalytics['retention'] = {
    kpi: neutral(kpiOf(heldNow, heldAt(supplierRetentions, from - 1), 'lower', 0.5, true)),
    heldNow,
    heldCount: holding.length,
    pausedNow: supplierRetentions.filter((r) => r.status === 'paused').reduce((n, r) => n + r.amount, 0),
    releasedInWindow: retentionMonths.reduce((n, m) => n + m.released, 0),
    withheldInWindow: retentionMonths.reduce((n, m) => n + m.withheld, 0),
    oldestHeldDays: holding.length ? Math.floor(Math.max(...holding.map((r) => (now - new Date(r.heldAt).getTime()) / DAY_MS))) : null,
    months: retentionMonths,
  };

  /* ---- disputes: how often, and how long they take to settle */
  const raisedIn = (d: SupplierDispute, a: number, b: number) => new Date(d.raisedAt).getTime() >= a && new Date(d.raisedAt).getTime() < b;
  const decidedAt = (d: SupplierDispute) => (d.status === 'resolved' && d.decisions.length ? d.decisions[d.decisions.length - 1].at : null);
  const resolvedIn = (d: SupplierDispute, a: number, b: number) => {
    const at = decidedAt(d);
    return !!at && new Date(at).getTime() >= a && new Date(at).getTime() < b;
  };
  const resolutionDaysOf = (d: SupplierDispute) => (new Date(decidedAt(d) as string).getTime() - new Date(d.raisedAt).getTime()) / DAY_MS;
  const ordersIn = (supplierId: string | null, a: number, b: number) => {
    const ids = new Set<string>();
    for (const po of supplierPurchaseOrders) if (po.supplierId && (!supplierId || po.supplierId === supplierId) && po.sentAt && new Date(po.sentAt).getTime() >= a && new Date(po.sentAt).getTime() < b) ids.add(po.id);
    for (const p of paid) if ((!supplierId || p.supplierId === supplierId) && paidAtOf(p) >= a && paidAtOf(p) < b) ids.add(p.poId);
    for (const d of supplierDisputes) if ((!supplierId || d.supplierId === supplierId) && raisedIn(d, a, b)) ids.add(d.poId);
    return ids.size;
  };
  const supplierIds = [...new Set([...supplierDisputes.map((d) => d.supplierId), ...nowFacts.map((f) => f.p.supplierId)])];
  const disputeFacts = supplierIds.map((id) => {
    const mine = supplierDisputes.filter((d) => d.supplierId === id);
    const raised = mine.filter((d) => raisedIn(d, from, now + 1));
    const open = mine.filter((d) => d.status === 'open');
    const resolved = mine.filter((d) => resolvedIn(d, from, now + 1));
    return {
      id,
      orders: ordersIn(id, from, now + 1),
      disputes: raised.length,
      raised,
      open,
      resolved,
      facts: {
        orders: ordersIn(id, from, now + 1),
        disputes: raised.length,
        openThreatensHalt: open.some((d) => d.threatensHalt),
        openAgesDays: open.map((d) => (now - new Date(d.roundStartedAt).getTime()) / DAY_MS).sort((a, b) => b - a),
        resolutionDays: resolved.map(resolutionDaysOf),
        maxRound: Math.max(1, ...[...raised, ...open].map((d) => d.round)),
      },
    };
  });
  const disputeRows: DisputeAnalyticsRowView[] = disputeFacts
    .filter((r) => r.orders > 0 || r.disputes > 0 || r.open.length > 0)
    .map((r) => {
      const others = fleetRate(disputeFacts.filter((o) => o.id !== r.id).map((o) => ({ orders: o.orders, disputes: o.disputes })));
      const latest = [...r.raised, ...r.open].sort((a, b) => b.raisedAt.localeCompare(a.raisedAt))[0];
      return {
        id: r.id,
        name: supplierName(r.id),
        orders: r.orders,
        disputes: r.disputes,
        ratePct: ratePct(r.disputes, r.orders),
        open: r.open.length,
        resolved: r.resolved.length,
        avgResolutionDays: oneDecimal(average(r.facts.resolutionDays)),
        maxRound: r.facts.maxRound,
        rated: r.orders >= 3,
        reasons: reviewReasons(r.facts, others),
        latestDisputeId: latest?.id ?? null,
      };
    })
    .sort((a, b) => b.reasons.length - a.reasons.length || (b.ratePct ?? 0) - (a.ratePct ?? 0));
  const disputesNow = supplierDisputes.filter((d) => raisedIn(d, from, now + 1)).length;
  const disputesBefore = supplierDisputes.filter((d) => raisedIn(d, before.from, before.to)).length;
  const ordersNow = ordersIn(null, from, now + 1);
  const ordersBefore = ordersIn(null, before.from, before.to);
  const resolutionNow = oneDecimal(average(supplierDisputes.filter((d) => resolvedIn(d, from, now + 1)).map(resolutionDaysOf)));
  const resolutionBefore = oneDecimal(average(supplierDisputes.filter((d) => resolvedIn(d, before.from, before.to)).map(resolutionDaysOf)));
  const disputes: SupplierPaymentAnalytics['disputes'] = {
    kpi: kpiOf(ratePct(disputesNow, ordersNow), ratePct(disputesBefore, ordersBefore), 'lower', 0.5),
    resolutionKpi: kpiOf(resolutionNow, resolutionBefore, 'lower', 0.2),
    disputes: disputesNow,
    orders: ordersNow,
    open: supplierDisputes.filter((d) => d.status === 'open').length,
    ratePct: ratePct(disputesNow, ordersNow),
    avgResolutionDays: resolutionNow,
    targetDays: Math.round(DISPUTE_TARGET / DAY_MS),
    suppliers: disputeRows,
    reviewCount: disputeRows.filter((r) => r.reasons.length > 0).length,
    processFlags: supplierDisputes.filter((d) => d.processFlag?.status === 'open').length,
  };

  return {
    months: keys,
    spend: {
      kpi: neutral(kpiOf(spendTotal, spendBefore, 'lower', 0.5, true)),
      total: spendTotal,
      typicalMonth: typicalMonth === null ? null : Math.round(typicalMonth),
      byMonth: spendMonths,
      suppliers: rowsFor((p) => ({ [p.supplierId]: net(p) }), supplierName),
      categories: rowsFor(categoryOf, (id) => id),
    },
    speed,
    retention,
    disputes,
    notes: spendNotes.map(spendNoteView).sort((a, b) => b.month.localeCompare(a.month)),
  };
}

/** A relationship worth a review, on the screen and as one alert, so the suspend/review consideration in 091 is not left to
 *  someone remembering to look. It resolves itself when the reasons clear. A stated intention to halt already has its own (117). */
function syncSupplierReviewFlags(now: number): void {
  const at = new Date(now).toISOString();
  const flagged = new Map(computeSupplierPaymentAnalytics(6, now).disputes.suppliers.map((r) => [r.id, alertingReasons(r.reasons)]));
  for (const [supplierId, reasons] of flagged) {
    const open = alerts.find((a) => a.relatedId === supplierId && a.titleKey === REVIEW_ALERT && a.status !== 'resolved');
    if (reasons.length > 0 && !open) {
      const name = byId(suppliers, supplierId)?.name ?? '';
      raiseAlert({ titleKey: REVIEW_ALERT, context: name, severity: 'medium', category: 'supplier', relatedId: supplierId, sourceRoute: `/supplier-payment-analytics?tab=disputes&supplier=${supplierId}` });
      logAutomatedAction({
        sourceKey: 'supplier_payment_analytics.review_flag',
        triggeringCondition: `${name}'s disputes stand out against the other suppliers (${reasons.join(', ')})`,
        actionTaken: 'Raised an alert suggesting a review of the supplier relationship',
        affectedRecordId: supplierId,
        affectedRecordType: 'other',
        subjectLabel: name,
      });
    } else if (reasons.length === 0 && open) {
      patchInPlace(alerts, open.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'The disputes no longer stand out.' });
    }
  }
  for (const a of alerts.filter((x) => x.titleKey === REVIEW_ALERT && x.status !== 'resolved' && !flagged.has(x.relatedId ?? ''))) {
    patchInPlace(alerts, a.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'The disputes no longer stand out.' });
  }
}

/* ============================== Supplier payment history (115) */

const supplierPaymentAdjustments: SupplierPaymentAdjustment[] = seedSupplierPaymentAdjustments.map((a) => ({ ...a }));
const supplierPaymentQueries: SupplierPaymentQuery[] = [];
let paymentAdjustmentCounter = 100;
let paymentQueryCounter = 0;

const adjustmentDelta = (a: SupplierPaymentAdjustment) => (a.direction === 'credit' ? -a.amount : a.amount);

/** Adds a correction beside an executed payment and tells a supplier with a login in the order's thread. Never edits the payment. */
function pushPaymentAdjustment(p: SupplierPayment, direction: 'credit' | 'top_up', amount: number, reason: string, actor: User): SupplierPaymentAdjustment {
  const at = new Date().toISOString();
  paymentAdjustmentCounter += 1;
  const created: SupplierPaymentAdjustment = { id: `spadj-new-${paymentAdjustmentCounter}`, paymentId: p.id, direction, amount, reason, byName: actor.name, at, isDemo: true };
  supplierPaymentAdjustments.push(created);
  const po = byId(supplierPurchaseOrders, p.poId);
  const supplier = byId(suppliers, p.supplierId);
  if (po && supplier && supplierUserFor(supplier)) {
    pushSupplierMessage(ensureSupplierThread(supplier.id, po.id), {
      author: 'aiec',
      authorName: actor.name,
      authorUserId: actor.id,
      body: `${direction === 'credit' ? 'Credit' : 'Additional payment'} of ${formatINR(amount)} recorded against payment ${p.code} for ${po.code}: ${reason}`,
      channel: 'in_app',
      at,
      expectsReply: false,
      poRef: po.id,
    });
  }
  return created;
}

function historyEntryOf(p: SupplierPayment): PaymentHistoryEntry {
  const po = byId(supplierPurchaseOrders, p.poId);
  const adj = supplierPaymentAdjustments.filter((a) => a.paymentId === p.id);
  const total = adj.reduce((n, a) => n + adjustmentDelta(a), 0);
  return {
    id: p.id,
    code: p.code,
    poId: p.poId,
    poCode: po?.code ?? p.poId,
    supplierId: p.supplierId,
    supplierName: byId(suppliers, p.supplierId)?.name ?? '',
    siteName: po ? (shipmentSite(po.dealId)?.siteName ?? '') : '',
    part: p.part,
    trigger: p.trigger,
    amount: p.amount,
    adjustmentsTotal: total,
    netAmount: p.amount + total,
    paidAt: p.executedAt ?? p.approvedAt ?? p.triggeredAt,
    bankReference: p.bankReference ?? null,
    adjustmentCount: adj.length,
    queried: supplierPaymentQueries.some((q) => q.paymentId === p.id),
    invoiceNumbers: supplierInvoices.filter((i) => i.poId === p.poId && i.status === 'open').map((i) => i.invoiceNumber),
  };
}

function historyDetailOf(p: SupplierPayment, viewer: { supplierId: string | null }): PaymentHistoryDetail {
  const entry = historyEntryOf(p);
  const po = byId(supplierPurchaseOrders, p.poId);
  let basis: PaymentHistoryBasis = { poTotal: 0, pct: null, expected: null, reconciles: null, difference: 0, termType: null, tier: null, netDays: null, custom: false };
  if (po) {
    const total = paymentTotalOf(po);
    basis = { ...basis, poTotal: total };
    if (po.paymentTerms && total > 0) {
      const facts = chainFactsOf(po, Date.now());
      const expected = facts.parts.find((x) => x.kind === p.part)?.amount ?? null;
      basis = {
        poTotal: total,
        pct: splitOf(total, po.paymentTerms).find((x) => x.part === p.part)?.pct ?? null,
        expected,
        reconciles: expected === null ? null : Math.abs(expected - p.amount) <= 1,
        difference: expected === null ? 0 : p.amount - expected,
        termType: po.paymentTerms.termType,
        tier: po.paymentTerms.tier,
        netDays: facts.netDays,
        custom: po.paymentTerms.custom || (po.paymentTerms.deviations?.length ?? 0) > 0,
      };
    }
  }
  return {
    ...entry,
    basis,
    invoices: supplierInvoices
      .filter((i) => i.poId === p.poId && i.status === 'open')
      .map((i) => ({ id: i.id, number: i.invoiceNumber, date: i.invoiceDate, subtotal: i.lines.reduce((n, l) => n + l.quantity * l.unitPrice, 0), status: evaluateInvoice(i).status })),
    adjustments: supplierPaymentAdjustments
      .filter((a) => a.paymentId === p.id)
      .sort((a, b) => (a.at < b.at ? -1 : 1))
      .map((a) => ({ id: a.id, direction: a.direction, amount: a.amount, reason: a.reason, byName: a.byName, at: a.at })),
    queries: supplierPaymentQueries.filter((q) => q.paymentId === p.id).map((q) => ({ id: q.id, note: q.note, byName: q.byName, at: q.at })),
    events: p.events,
    evidence: paymentEvidence(p),
    approvedByName: p.approvedByName ?? null,
    disputes: supplierDisputes.filter((d) => d.paymentId === p.id).sort((a, b) => (a.raisedAt < b.raisedAt ? 1 : -1)).map((d) => ({ id: d.id, code: d.code, status: d.status, lastDecision: d.decisions[d.decisions.length - 1]?.decision ?? null, round: d.round, canReopen: disputeCanReopen(d, Date.now()) })),
    canDispute: !!viewer.supplierId && viewer.supplierId === p.supplierId && !supplierDisputes.some((d) => d.status === 'open' && d.paymentId === p.id),
    canAdjust: !viewer.supplierId,
    canQuery: !!viewer.supplierId && viewer.supplierId === p.supplierId,
  };
}

/** Executed payments visible to the viewer and matching the filter, newest first. */
function historyMatching(filter: PaymentHistoryFilter, viewer: { supplierId: string | null }): PaymentHistoryEntry[] {
  const q = filter.query?.trim().toLowerCase();
  return supplierPayments
    .filter((p) => p.status === 'executed' && (viewer.supplierId ? p.supplierId === viewer.supplierId : !filter.supplierId || p.supplierId === filter.supplierId))
    .filter((p) => !filter.part || p.part === filter.part)
    .map(historyEntryOf)
    .filter((e) => {
      const day = dateKey(new Date(e.paidAt));
      if (filter.from && day < filter.from) return false;
      if (filter.to && day > filter.to) return false;
      return !q || [e.poCode, e.code, e.bankReference ?? '', e.siteName, ...e.invoiceNumbers].some((v) => v.toLowerCase().includes(q));
    })
    .sort((a, b) => (a.paidAt < b.paidAt ? 1 : a.paidAt > b.paidAt ? -1 : a.code < b.code ? 1 : -1));
}

function executedPaymentOrThrow(paymentId: string, viewer: { supplierId: string | null }): SupplierPayment {
  const p = byId(supplierPayments, paymentId);
  if (!p || p.status !== 'executed') throw new RepositoryError('not_found');
  if (viewer.supplierId && p.supplierId !== viewer.supplierId) throw new RepositoryError('not_found');
  return p;
}

/* ============================== Supplier payment schedule (114) */

/** Every unpaid part of every live sent order, as the payment it already is or the one its milestone trajectory expects.
 *  Recomputed on each read, so a delayed delivery moves its balance and a cancelled deal takes its unfired parts away. */
function supplierScheduleOf(now: number): { items: SupplierPaymentScheduleItem[]; dropped: SupplierPaymentSchedule['dropped'] } {
  const items: SupplierPaymentScheduleItem[] = [];
  const dropped: SupplierPaymentSchedule['dropped'] = [];
  for (const po of supplierPurchaseOrders) {
    if (po.status !== 'sent' || !po.supplierId || !po.paymentTerms || paymentTotalOf(po) <= 0) continue;
    const supplier = byId(suppliers, po.supplierId);
    const chain = paymentChainOf(po, null, now);
    const orphaned = isOrphanedPo(po);
    const promised = promisedDeliveryOf(po);
    const plannedOf = (part: SupplierPaymentPart): string | null => {
      if (part === 'balance') return promised ? (chain.netDays !== null && chain.termType === 'net' ? new Date(new Date(promised).getTime() + chain.netDays * 86_400_000).toISOString() : promised) : null;
      if (part === 'upfront' && po.sentAt && chain.parts.find((x) => x.part === 'upfront')?.trigger === 'on_acknowledge') return new Date(new Date(po.sentAt).getTime() + ACK_EXPECTED_AFTER).toISOString();
      return null;
    };
    const waitingOnOf = (part: SupplierPaymentPart, trigger: SupplierPaymentTrigger): ChainNodeKind | null =>
      part === 'upfront' ? (trigger === 'on_acknowledge' ? 'acknowledged' : null) : part === 'balance' ? (chain.termType === 'net' ? 'net_period' : 'delivery_confirmed') : 'retention_release';
    let droppedAmount = 0;
    for (const part of chain.parts) {
      if (part.state === 'paid' || part.amount <= 0) continue;
      if (part.state === 'not_due' && orphaned) {
        droppedAmount += part.amount;
        continue;
      }
      const payment = part.paymentId ? byId(supplierPayments, part.paymentId) : undefined;
      const flags = payment ? paymentFlags(payment).map((f) => f) : [];
      const state: ScheduleState = !payment
        ? 'expected'
        : payment.status === 'approved'
          ? 'approved'
          : payment.status === 'held'
            ? 'held'
            : flags.some((f) => f.severity === 'block')
              ? 'waiting'
              : 'owed';
      const planned = payment ? null : plannedOf(part.part);
      items.push({
        id: `${po.id}:${part.part}`,
        poId: po.id,
        poCode: po.code,
        supplierId: po.supplierId,
        supplierName: supplier?.name ?? '',
        siteName: chain.siteName,
        part: part.part,
        trigger: part.trigger,
        amount: part.amount,
        paymentId: part.paymentId,
        paymentCode: part.paymentCode,
        state,
        date: part.dueAt ? dateKey(new Date(part.dueAt)) : null,
        isExpected: !payment,
        plannedAt: planned,
        slipDays: payment ? 0 : slipDaysOf(planned, part.dueAt),
        overdueDays: payment ? overdueDays(payment, now) : 0,
        waitingOn: payment ? null : waitingOnOf(part.part, part.trigger),
        flags: flags.map((f) => f.kind),
        origin: part.origin,
      });
    }
    if (droppedAmount > 0) dropped.push({ poId: po.id, poCode: po.code, supplierName: supplier?.name ?? '', amount: droppedAmount });
  }
  return { items, dropped };
}

/** An out-of-order milestone is never processed quietly: Admin is told once, and told again if it recurs. */
function syncPaymentAnomalies(now: number): void {
  for (const po of supplierPurchaseOrders) {
    if (po.status !== 'sent' || !po.supplierId || !po.paymentTerms) continue;
    const anomalies = chainAnomalies(chainFactsOf(po, now).facts);
    const open = alerts.find((a) => a.relatedId === po.id && a.titleKey === 'supplierPaymentRelease.alert.outOfSequence' && a.status !== 'resolved');
    if (anomalies.length > 0 && !open) {
      const alert = raiseAlert({
        titleKey: 'supplierPaymentRelease.alert.outOfSequence',
        context: `${po.code} · ${byId(suppliers, po.supplierId)?.name ?? ''}`,
        severity: 'high',
        category: 'payment',
        relatedId: po.id,
        sourceRoute: `/supplier-payment-release?po=${po.id}`,
      });
      logAutomatedAction({
        sourceKey: 'supplier_payment.out_of_sequence',
        triggeringCondition: `A milestone on ${po.code} fired out of order`,
        actionTaken: `Held the release and raised ${alert.code} for review`,
        affectedRecordId: po.id,
        affectedRecordType: 'purchase_order',
        subjectLabel: po.code,
      });
    } else if (anomalies.length === 0 && open) {
      patchInPlace(alerts, open.id, { status: 'resolved', resolvedAt: new Date(now).toISOString(), resolvedBy: 'system', resolutionNote: 'The events are back in order.' });
    }
  }
}

function chainPoOrThrow(poId: string): SupplierPurchaseOrder {
  const po = byId(supplierPurchaseOrders, poId);
  if (!po || po.status !== 'sent' || !po.supplierId || !po.paymentTerms) throw new RepositoryError('not_found');
  return po;
}

/* ============================== Supplier invoice matching (113) */

const supplierInvoices: SupplierInvoice[] = seedSupplierInvoices.map((i) => ({ ...i, lines: i.lines.map((l) => ({ ...l })), events: [...i.events] }));
let supplierInvoiceCounter = 100;

/** What the delivery checks accepted for an order line: arrived and fine, or arrived short (a count problem).
 *  Damaged or wrong-spec parts are not accepted until they are replaced. */
function acceptedQtyOf(po: SupplierPurchaseOrder, line: PurchaseOrderLineItem): number {
  const items = deliveryChecklists.filter((c) => c.poId === po.id && c.status === 'completed').flatMap((c) => c.items.filter((i) => i.lineItemId === line.id));
  if (items.length === 0) return lineStageOf(po, line) === 'delivered' ? line.quantity : 0;
  return items.reduce((n, i) => {
    if (i.verdict === 'ok') return n + (i.receivedQty ?? i.expectedQty);
    if (i.verdict === 'discrepancy') return n + (i.kinds.includes('damaged') || i.kinds.includes('wrong_spec') ? 0 : (i.receivedQty ?? 0));
    return n;
  }, 0);
}

function evaluateInvoice(inv: SupplierInvoice): { lines: SupplierInvoiceLineView[]; status: InvoiceMatchStatus } {
  const po = byId(supplierPurchaseOrders, inv.poId);
  const earlier = supplierInvoices.filter((o) => o.poId === inv.poId && o.id !== inv.id && o.status === 'open' && o.submittedAt < inv.submittedAt);
  const lines = inv.lines.map((l, index): SupplierInvoiceLineView => {
    const poLine = l.lineItemId ? (po?.lineItems ?? []).find((x) => x.id === l.lineItemId) : undefined;
    const billedElsewhere = l.lineItemId ? earlier.flatMap((o) => o.lines).filter((x) => x.lineItemId === l.lineItemId).reduce((n, x) => n + x.quantity, 0) : 0;
    const delivered = po && poLine ? acceptedQtyOf(po, poLine) : 0;
    const m = matchLine({ order: poLine ? { quantity: poLine.quantity, price: poLine.agreedUnitPrice } : null, delivered, billedElsewhere, invoiced: { quantity: l.quantity, unitPrice: l.unitPrice, adjustmentPrice: l.adjustment?.toPrice } });
    const applicable =
      m.priceCheck === 'fail' && po
        ? catalogPriceChanges
            .filter((c) => explainsInvoicePrice(c, inv.supplierId, po.sentAt, l.unitPrice))
            .map((c) => ({ id: c.id, toPrice: c.toPrice, requestedAt: c.requestedAt, requestedBy: c.requestedBy }))
        : [];
    return {
      index,
      lineItemId: l.lineItemId,
      description: l.description,
      orderedQty: poLine?.quantity ?? null,
      orderedPrice: poLine?.agreedUnitPrice ?? null,
      deliveredQty: delivered,
      billedElsewhere,
      invoicedQty: l.quantity,
      invoicedPrice: l.unitPrice,
      verdict: m.verdict,
      issues: m.issues,
      quantityCheck: m.quantityCheck,
      priceCheck: m.priceCheck,
      priceGap: m.priceGap,
      unlocked: m.unlocked,
      adjustment: l.adjustment ?? null,
      applicableChanges: applicable,
    };
  });
  return { lines, status: inv.status === 'rejected' ? 'rejected' : overallOf(lines.map((l) => l.verdict)) };
}

/** Whether an order's payment can proceed on the invoices submitted for it. */
function invoiceGateOfPo(po: SupplierPurchaseOrder): InvoiceGate {
  const open = supplierInvoices.filter((i) => i.poId === po.id && i.status === 'open');
  const evaluated = open.map((i) => ({ i, e: evaluateInvoice(i) }));
  const lines: GateLine[] = (po.lineItems ?? []).map((pl) => ({
    ordered: pl.quantity,
    unlocked: evaluated.flatMap(({ i, e }) => i.lines.map((l, idx) => ({ l, v: e.lines[idx] }))).filter(({ l, v }) => l.lineItemId === pl.id && v.unlocked).reduce((n, { l }) => n + l.quantity, 0),
  }));
  return gateOf(open.length > 0, evaluated.some(({ e }) => e.status === 'mismatch'), evaluated.some(({ e }) => e.status === 'awaiting_delivery'), lines);
}

function invoiceViewOf(inv: SupplierInvoice): SupplierInvoiceView {
  const po = byId(supplierPurchaseOrders, inv.poId);
  const e = evaluateInvoice(inv);
  return {
    id: inv.id,
    code: inv.code,
    poId: inv.poId,
    poCode: po?.code ?? inv.poId,
    supplierId: inv.supplierId,
    supplierName: byId(suppliers, inv.supplierId)?.name ?? '',
    siteName: po ? (shipmentSite(po.dealId)?.siteName ?? '') : '',
    invoiceNumber: inv.invoiceNumber,
    invoiceDate: inv.invoiceDate,
    documentName: inv.documentName ?? null,
    submittedAt: inv.submittedAt,
    submittedByName: inv.submittedByName,
    submittedByRole: inv.submittedByRole,
    status: e.status,
    subtotal: inv.lines.reduce((n, l) => n + l.quantity * l.unitPrice, 0),
    lines: e.lines,
    rejectedReason: inv.rejectedReason ?? null,
    rejectedByName: inv.rejectedByName ?? null,
    withdrawn: !!inv.withdrawnBySupplier,
    gate: po ? invoiceGateOfPo(po) : 'no_invoice',
    events: inv.events,
  };
}

function invoiceEvents(inv: SupplierInvoice, kind: SupplierInvoiceEvent['kind'], byName: string, note?: string): SupplierInvoiceEvent[] {
  return [...inv.events, { id: `${inv.id}-e${inv.events.length + 1}`, kind, at: new Date().toISOString(), byName, note: note?.trim() || undefined }];
}

/** Tells the supplier in the order's thread (when they have a login) and Admin by alert. Once per invoice, never repeatedly:
 *  a mismatch routes to reconciliation instead of proceeding on an unverified invoice. */
function syncInvoiceMismatches(now: number): void {
  const at = new Date(now).toISOString();
  for (const inv of [...supplierInvoices]) {
    if (inv.status !== 'open') continue;
    const status = evaluateInvoice(inv).status;
    const alert = alerts.find((a) => a.relatedId === inv.id && a.titleKey === 'supplierInvoiceMatching.alert.mismatch' && a.status !== 'resolved');
    if (status === 'mismatch' && !inv.mismatchNotifiedAt) {
      const po = byId(supplierPurchaseOrders, inv.poId);
      const supplier = byId(suppliers, inv.supplierId);
      const view = invoiceViewOf(inv);
      const bad = view.lines.filter((l) => l.verdict === 'mismatch');
      raiseAlert({
        titleKey: 'supplierInvoiceMatching.alert.mismatch',
        context: `${inv.code} · ${po?.code ?? ''} · ${supplier?.name ?? ''}`,
        severity: 'medium',
        category: 'payment',
        relatedId: inv.id,
        sourceRoute: `/supplier-invoices?invoice=${inv.id}`,
      });
      if (po && supplier && supplierUserFor(supplier)) {
        pushSupplierMessage(ensureSupplierThread(supplier.id, po.id), {
          author: 'aiec',
          authorName: 'AIEC Assistant',
          body: `Invoice ${inv.invoiceNumber} for ${po.code} does not match the order: ${bad.map((l) => `${l.description} (${l.issues.join(', ').replace(/_/g, ' ')})`).join('; ')}. Please send a corrected invoice, or tell us the basis for the difference.`,
          channel: 'in_app',
          at,
          expectsReply: true,
          poRef: po.id,
        });
      }
      patchInPlace(supplierInvoices, inv.id, { mismatchNotifiedAt: at, events: invoiceEvents(inv, 'mismatch_notified', 'AIEC Assistant') });
      logAutomatedAction({
        sourceKey: 'supplier_invoice.mismatch',
        triggeringCondition: `Invoice ${inv.invoiceNumber} did not match ${po?.code ?? 'the order'}`,
        actionTaken: `Held its payment, raised an alert${supplier && supplierUserFor(supplier) ? ' and told the supplier' : ''}`,
        affectedRecordId: inv.id,
        affectedRecordType: 'purchase_order',
        subjectLabel: inv.code,
      });
    } else if (status !== 'mismatch' && alert) {
      patchInPlace(alerts, alert.id, { status: 'resolved', resolvedAt: at, resolvedBy: 'system', resolutionNote: 'The invoice now matches.' });
    }
  }
}

/* ============================================ Delivery SOP (107) */

function sopTemplateViewOf(t: DeliverySopTemplate, now: number): SopTemplateView {
  const inForce = sopVersionInForce(t, now);
  const inFlight = deliveryChecklists.filter(
    (c) => c.status === 'in_progress' && c.items.some((i) => (i.sopVersions ?? []).some((v) => v.templateId === t.id && inForce && v.version < inForce.version)),
  ).length;
  return {
    id: t.id,
    category: t.category,
    name: t.name,
    versions: [...t.versions].sort((a, b) => b.version - a.version).map((v) => ({ ...v, status: statusOf(t, v, now) })),
    activeVersion: inForce?.version ?? null,
    inFlight,
  };
}

/* ================================================== Stock in transit (106) */

/** Parts ordered for a deal that was lost or cancelled (or is gone) after the order went out. */
function poDealState(po: SupplierPurchaseOrder): 'live' | 'lost' | 'cancelled' {
  // A deal with no record at all is history from before deals were kept here, not a cancellation.
  const deal = byId(deals, po.dealId);
  return deal?.status === 'lost' ? 'lost' : deal?.status === 'cancelled' ? 'cancelled' : 'live';
}
const isOrphanedPo = (po: SupplierPurchaseOrder) => po.status === 'sent' && poDealState(po) !== 'live';

/** When one part is expected on site: its vehicle's ETA once it is on the road, otherwise the order's
 *  stage-by-stage estimate, otherwise the date promised. */
function lineArrival(po: SupplierPurchaseOrder, line: PurchaseOrderLineItem, now: number): { at: string; source: TransitLine['arrivalSource']; vehicle: string | null } {
  if (lineStageOf(po, line) === 'shipped') {
    const leg = shipmentLegs.find((l) => l.poId === po.id && l.lineItemIds.includes(line.id) && !legSnapshotOf(l, routeOfLeg(l), now).arrived);
    if (leg) return { at: leg.etaAt, source: 'tracker', vehicle: leg.vehicleLabel };
  }
  const supplier = po.supplierId ? byId(suppliers, po.supplierId) : undefined;
  const estimate = assessDelay(po, supplier ?? undefined, supplierPurchaseOrders, now);
  if (estimate.projectedDelivery) return { at: estimate.projectedDelivery, source: 'estimate', vehicle: null };
  return { at: promisedDeliveryOf(po) ?? new Date(now).toISOString(), source: 'promised', vehicle: null };
}

function transitLinesOf(now: number): TransitLine[] {
  const out: TransitLine[] = [];
  for (const po of supplierPurchaseOrders) {
    if (po.status !== 'sent' || po.receivedAt || !po.supplierId || isOrphanedPo(po)) continue;
    const deal = byId(deals, po.dealId);
    const lead = deal ? resolveLead(deal.leadId) : null;
    const facts = delayFactsOf(po, now);
    const severity = facts ? judgeDelay(facts, now).severity : null;
    for (const line of po.lineItems ?? []) {
      const stage = lineStageOf(po, line);
      if (stage === 'delivered') continue;
      const arrival = lineArrival(po, line, now);
      out.push({
        key: `${po.id}:${line.id}`,
        poId: po.id,
        poCode: po.code,
        dealId: po.dealId,
        siteName: lead?.siteName ?? deal?.code ?? po.dealId,
        customerName: lead?.contactName ?? '',
        supplierId: po.supplierId,
        supplierName: byId(suppliers, po.supplierId)?.name ?? '',
        lineId: line.id,
        description: line.description,
        category: line.category,
        quantity: line.quantity,
        value: line.agreedUnitPrice * line.quantity,
        stage,
        onTheRoad: stage === 'shipped',
        arrivalAt: arrival.at,
        arrivalSource: arrival.source,
        weekStart: weekStartOf(arrival.at),
        window: windowOf(arrival.at, now),
        delaySeverity: severity,
        vehicleLabel: arrival.vehicle,
      });
    }
  }
  return out.sort((a, b) => (a.arrivalAt < b.arrivalAt ? -1 : 1));
}

function transitTotalsOf(lines: TransitLine[]): TransitTotals {
  return {
    value: lines.reduce((sum, l) => sum + l.value, 0),
    onTheRoadValue: lines.filter((l) => l.onTheRoad).reduce((sum, l) => sum + l.value, 0),
    notShippedValue: lines.filter((l) => !l.onTheRoad).reduce((sum, l) => sum + l.value, 0),
    atRiskValue: lines.filter((l) => l.delaySeverity).reduce((sum, l) => sum + l.value, 0),
    lineCount: lines.length,
    orderCount: new Set(lines.map((l) => l.poId)).size,
    dealCount: new Set(lines.map((l) => l.dealId)).size,
  };
}

/** For each deal with parts still to arrive or an installation waiting on them: when it can really start. */
function capacityDeals(lines: TransitLine[], now: number): CapacityDealRow[] {
  const dealIds = new Set<string>(lines.map((l) => l.dealId));
  for (const job of jobs) {
    if (!job.startedAt && (job.status === 'materials_pending' || job.status === 'scheduled') && supplierPurchaseOrders.some((p) => p.dealId === job.dealId && p.status === 'sent')) dealIds.add(job.dealId);
  }
  const rows: CapacityDealRow[] = [];
  for (const dealId of dealIds) {
    const deal = byId(deals, dealId);
    if (!deal || deal.status !== 'won') continue;
    const remaining = lines.filter((l) => l.dealId === dealId);
    // Something still unordered: nothing can be promised yet.
    const unordered = supplierPurchaseOrders.some((p) => p.dealId === dealId && (p.lineItems ?? []).length > 0 && p.status !== 'sent');
    const readyBy = remaining.length ? remaining.map((l) => l.arrivalAt).sort().pop()! : null;
    const job = pendingJobFor(dealId);
    const installStart = job && !job.startedAt ? job.scheduledFor : null;
    const lead = resolveLead(deal.leadId);
    rows.push({
      dealId,
      siteName: lead?.siteName ?? deal.code,
      customerName: lead?.contactName ?? '',
      readyBy,
      confidence: remaining.length === 0 ? 'confirmed' : remaining.every((l) => l.arrivalSource === 'tracker') ? 'tracker' : 'estimate',
      installStart,
      installCode: job && !job.startedAt ? job.code : null,
      status: readinessStatus(readyBy, installStart, unordered, now),
      partCount: remaining.length,
    });
  }
  // Conflicts first: an installation booked before its parts is the thing to fix.
  const rank: Record<ReadinessStatus, number> = { conflict: 0, unordered: 1, no_job: 2, on_track: 3, ready: 4 };
  return rows.sort((a, b) => rank[a.status] - rank[b.status] || ((a.readyBy ?? '') < (b.readyBy ?? '') ? -1 : 1));
}

function orphanRows(): OrphanRow[] {
  return supplierPurchaseOrders
    .filter((po) => isOrphanedPo(po) && !po.receivedAt)
    .map((po): OrphanRow => {
      const deal = byId(deals, po.dealId);
      const state = poDealState(po) as 'lost' | 'cancelled';
      const supplier = po.supplierId ? byId(suppliers, po.supplierId) : null;
      return {
        poId: po.id,
        poCode: po.code,
        dealId: po.dealId,
        dealCode: deal?.code ?? po.dealId,
        dealStatus: state,
        siteName: deal ? (resolveLead(deal.leadId)?.siteName ?? deal.code) : po.dealId,
        supplierName: supplier?.name ?? '',
        supplierHasLogin: !!supplier && !!supplierUserFor(supplier),
        value: (po.lineItems ?? []).reduce((sum, l) => sum + l.agreedUnitPrice * l.quantity, 0),
        stage: poStageOf(po),
        lineSummary: (po.lineItems ?? []).map((l) => l.description).join(', '),
        resolution: po.orphanResolution ?? null,
      };
    })
    .sort((a, b) => Number(!!a.resolution) - Number(!!b.resolution));
}

/* ============================================ Delivery scheduling (101) */

const availabilityOf = (supplierId: string) => dispatchAvailability.find((a) => a.supplierId === supplierId) ?? null;
const readinessOf = (dealId: string) => siteReadinessRecords.find((r) => r.dealId === dealId) ?? emptyReadiness(dealId);
const scheduleOfPo = (poId: string) => deliverySchedules.find((s) => s.poId === poId);

function deliveryPoOrThrow(poId: string): SupplierPurchaseOrder {
  const po = byId(supplierPurchaseOrders, poId);
  if (!po || po.status !== 'sent' || !po.supplierId) throw new RepositoryError('not_found');
  return po;
}

function siteOfDeal(dealId: string): { siteName: string; address: string | null } {
  const deal = byId(deals, dealId);
  const lead = deal ? resolveLead(deal.leadId) : null;
  return { siteName: lead?.siteName ?? '', address: lead ? `${lead.address}, ${lead.city}` : null };
}

/** The installation job this deal's deliveries are holding up. */
function pendingJobFor(dealId: string, schedule?: DeliverySchedule): Job | undefined {
  const linked = schedule?.jobId ? byId(jobs, schedule.jobId) : undefined;
  if (linked) return linked;
  return jobs.filter((j) => j.dealId === dealId && !j.startedAt && (j.status === 'materials_pending' || j.status === 'scheduled')).sort((a, b) => (a.scheduledFor < b.scheduledFor ? -1 : 1))[0];
}

/**
 * Confirming a date is what puts the installation on the technician's
 * calendar: the deal's pending job can't start before its last delivery
 * lands, so it moves with the deliveries (or is created if there isn't one).
 * The technician then hears about it through the manager layer.
 */
function syncInstallationJob(dealId: string, at: string): Job | null {
  const booked = deliverySchedules.filter((s) => s.dealId === dealId && s.status === 'scheduled' && s.date && !byId(supplierPurchaseOrders, s.poId)?.receivedAt);
  if (booked.length === 0) return null;
  const lastDelivery = booked.map((s) => s.date!).sort().pop()!;
  const start = new Date(parseKey(addDaysKey(lastDelivery, 1)).setHours(9, 0, 0, 0)).toISOString();
  let job = pendingJobFor(dealId, booked[0]);
  const deal = byId(deals, dealId);
  const lead = deal ? resolveLead(deal.leadId) : null;
  if (!job) {
    // An install already under way (or finished) doesn't get a second job.
    if (jobs.some((j) => j.dealId === dealId)) return null;
    jobCounter += 1;
    job = { id: `j-new-${jobCounter}`, code: `AIEC-J-${3200 + jobCounter}`, dealId, status: 'materials_pending', siteName: lead?.siteName ?? '', address: lead?.address ?? '', location: lead?.location ?? { lat: 0, lng: 0 }, scheduledFor: start, steps: installSteps(0), isDemo: true };
    jobs.push(job);
    logAutomatedAction({
      sourceKey: 'delivery.job_synced',
      triggeringCondition: `A delivery was confirmed for ${lead?.siteName ?? dealId}`,
      actionTaken: `Created installation job ${job.code} for ${start.slice(0, 10)}`,
      affectedRecordId: job.id,
      affectedRecordType: 'other',
      subjectLabel: job.code,
    });
    return job;
  }
  const moves = job.status === 'materials_pending' ? job.scheduledFor !== start : start > job.scheduledFor;
  if (moves) {
    job = patchInPlace(jobs, job.id, { scheduledFor: start });
    logAutomatedAction({
      sourceKey: 'delivery.job_synced',
      triggeringCondition: `The last delivery for ${lead?.siteName ?? dealId} is now booked for ${lastDelivery}`,
      actionTaken: `Moved installation job ${job.code} to ${start.slice(0, 10)}`,
      affectedRecordId: job.id,
      affectedRecordType: 'other',
      subjectLabel: job.code,
    });
  }
  void at;
  return job;
}

/** Tells the technician (through the assistant) a delivery they'll receive
 *  has been confirmed or moved. Returns whether a technician was reached. */
function notifyTechnicianOfDelivery(po: SupplierPurchaseOrder, at: string, reason = `Delivery ${po.code} was booked or moved`): boolean {
  syncCommitments(new Date(at).getTime());
  const commitment = commitments.find((c) => c.kind === 'delivery_receive' && c.subject.id === po.id && c.status === 'open');
  const owner = commitment ? byId(users, commitment.ownerUserId) : null;
  if (!commitment || owner?.role !== 'technician') return false;
  notifyWork(owner.id, commitment, 'nudge', at);
  logAutomatedAction({
    sourceKey: 'delivery.technician_notified',
    triggeringCondition: reason,
    actionTaken: `Told ${owner.name} to receive it`,
    affectedRecordId: po.id,
    affectedRecordType: 'purchase_order',
    subjectLabel: po.code,
  });
  return true;
}

function deliveryCardFor(po: SupplierPurchaseOrder, now: number): DeliveryCard {
  const supplier = byId(suppliers, po.supplierId!)!;
  const schedule = scheduleOfPo(po.id) ?? null;
  const readiness = readinessOf(po.dealId);
  const confirmed = readinessConfirmed(readiness);
  const delivered = !!po.receivedAt || poStageOf(po) === 'delivered';
  const status: DeliveryStatus = delivered ? 'delivered' : schedule?.status === 'attempt_failed' ? 'attempt_failed' : schedule ? 'scheduled' : 'unscheduled';
  const promised = promisedDeliveryOf(po);
  const conflicts = sequenceConflicts(deliverySchedules);
  const pre = schedule?.dependsOnPoId ? byId(supplierPurchaseOrders, schedule.dependsOnPoId) : undefined;
  const preSchedule = pre ? scheduleOfPo(pre.id) : undefined;
  const job = pendingJobFor(po.dealId, schedule ?? undefined);
  const tech = job?.technicianId ? byId(users, job.technicianId) : undefined;
  const others = deliverySchedules.filter((s) => s.supplierId === po.supplierId && s.poId !== po.id);
  const booked = status === 'scheduled' && schedule?.date && schedule.window;
  const bookedState = booked ? slotState(availabilityOf(supplier.id), others, schedule!.date!, schedule!.window!, now) : 'free';
  const lines = po.lineItems ?? [];
  const { siteName, address } = siteOfDeal(po.dealId);
  return {
    poId: po.id,
    poCode: po.code,
    dealId: po.dealId,
    siteName,
    address,
    supplier: { id: supplier.id, name: supplier.name, hasAvailability: !!availabilityOf(supplier.id) },
    poStage: poStageOf(po),
    lineSummary: lines.map((l) => l.description).join(' · '),
    totalAmount: poTotalOf(lines),
    promisedDelivery: promised,
    status,
    schedule,
    laterThanPromise: !!(booked && laterThanPromise(schedule!.date!, promised)),
    readiness,
    readinessConfirmed: confirmed,
    readinessLost: status === 'scheduled' && !confirmed,
    outsideSupplierWindows: bookedState === 'off_day' || bookedState === 'window_not_offered' || bookedState === 'blackout',
    dependsOn: pre
      ? { poId: pre.id, poCode: pre.code, date: preSchedule?.status === 'scheduled' ? (preSchedule.date ?? null) : null, window: preSchedule?.status === 'scheduled' ? (preSchedule.window ?? null) : null, delivered: !!pre.receivedAt }
      : null,
    dependents: deliverySchedules.filter((s) => s.dependsOnPoId === po.id).map((s) => ({ poId: s.poId, poCode: byId(supplierPurchaseOrders, s.poId)?.code ?? s.poId })),
    sequenceConflict: conflicts.has(po.id),
    technician: tech ? { id: tech.id, name: tech.name } : null,
    jobCode: job?.code ?? null,
    siblingPos: supplierPurchaseOrders.filter((p) => p.dealId === po.dealId && p.id !== po.id && p.status === 'sent').map((p) => ({ poId: p.id, poCode: p.code })),
  };
}

/** Everything that must hold before a slot is booked, for either side. */
function assertBookable(po: SupplierPurchaseOrder, date: string, window: DeliveryWindow, dependsOnPoId: string | null | undefined, now: number): void {
  const availability = availabilityOf(po.supplierId!);
  if (!availability) throw new RepositoryError('no_availability');
  const others = deliverySchedules.filter((s) => s.supplierId === po.supplierId && s.poId !== po.id);
  // The supplier's own real windows — never a date they can't meet.
  if (slotState(availability, others, date, window, now) !== 'free') throw new RepositoryError('slot_unavailable');
  if (!dependsOnPoId) return;
  const pre = byId(supplierPurchaseOrders, dependsOnPoId);
  if (!pre || pre.dealId !== po.dealId || pre.id === po.id || pre.status !== 'sent') throw new RepositoryError('invalid_input');
  if (wouldCycle(deliverySchedules, po.id, dependsOnPoId)) throw new RepositoryError('dependency_cycle');
  if (pre.receivedAt) return;
  const preSchedule = scheduleOfPo(pre.id);
  if (preSchedule?.status !== 'scheduled' || !preSchedule.date || !preSchedule.window) throw new RepositoryError('prerequisite_not_scheduled');
  if (!sequenceOk({ date, window }, { date: preSchedule.date, window: preSchedule.window })) throw new RepositoryError('sequence_conflict');
}

/** Only AIEC's or the site's delay moves the supplier's promise. A supplier's
 *  own stays measured against the original — 097 sees it. */
function movePromiseIfSiteCaused(po: SupplierPurchaseOrder, date: string, cause: DeliveryRescheduleCause): string | undefined {
  if (!PROMISE_MOVING_CAUSES.includes(cause)) return undefined;
  const promised = promisedDeliveryOf(po);
  if (!promised || !laterThanPromise(date, promised)) return undefined;
  patchInPlace(supplierPurchaseOrders, po.id, { expectedDeliveryDate: endOfDayIso(date) });
  return promised;
}

function deliveryEvent(fields: Omit<DeliveryEvent, 'id'>): DeliveryEvent {
  deliveryCounter += 1;
  return { id: `dev-${deliveryCounter}`, ...fields };
}

function finishDeliveryBooking(po: SupplierPurchaseOrder, schedule: DeliverySchedule, at: string): DeliveryScheduleResult {
  const job = syncInstallationJob(po.dealId, at);
  const linked = job && schedule.jobId !== job.id ? patchInPlace(deliverySchedules, schedule.id, { jobId: job.id }) : schedule;
  const notified = notifyTechnicianOfDelivery(po, at);
  const conflicts = [...sequenceConflicts(deliverySchedules)].map((id) => byId(supplierPurchaseOrders, id)?.code ?? id);
  return { schedule: linked, conflicts, technicianNotified: notified, jobCode: job?.code ?? null };
}

/* ======================================= Supplier payment terms (100) */

function holdRetention(po: SupplierPurchaseOrder, at: string): void {
  const pct = po.paymentTerms?.retentionPct ?? 0;
  if (!po.supplierId || pct <= 0 || supplierRetentions.some((r) => r.poId === po.id)) return;
  paymentTermsCounter += 1;
  supplierRetentions.push({
    id: `ret-new-${paymentTermsCounter}`,
    poId: po.id,
    supplierId: po.supplierId,
    dealId: po.dealId,
    pct,
    amount: Math.round((poTotalOf(po.lineItems ?? []) * pct) / 100),
    heldAt: at,
    status: 'held',
    isDemo: true,
  });
}

/** The heartbeat's retention pass: release at handover, pause on a
 *  supplier defect. Idempotent — only a `held` retention is ever touched. */
function settleRetentions(now: number): void {
  for (const r of [...supplierRetentions]) {
    const rating = supplierOrderRatings.find((x) => x.poId === r.poId);
    const action = retentionAction(r, jobs.filter((j) => j.dealId === r.dealId), rating);
    if (action.kind === 'none') continue;
    // A part still in question on this order (108) keeps its retention held: the supplier is not paid over an open fault.
    if (action.kind === 'release' && (openReportsOnPo(r.poId).length > 0 || openDisputesOnPo(r.poId).length > 0)) continue;
    // Unless Admin turned automatic release on, a retention that is ready comes up for release (118) and stays held until then.
    if (action.kind === 'release' && !paymentTermsConfig.autoReleaseRetention) continue;
    const po = byId(supplierPurchaseOrders, r.poId);
    const at = new Date(now).toISOString();
    if (action.kind === 'release') {
      patchInPlace(supplierRetentions, r.id, { status: 'released', decidedAt: at, decidedBy: 'system', decisionReason: 'handover' });
    } else {
      patchInPlace(supplierRetentions, r.id, { status: 'paused', pausedAt: at });
    }
    logAutomatedAction({
      sourceKey: action.kind === 'release' ? 'retention.released' : 'retention.paused',
      triggeringCondition:
        action.kind === 'release'
          ? `Installation handed over on the deal ${po?.code ?? r.poId} supplied`
          : `A supplier-attributed defect was logged on ${po?.code ?? r.poId}`,
      actionTaken: action.kind === 'release' ? `Released retention of ${formatINR(r.amount)}` : `Paused retention of ${formatINR(r.amount)} for Admin's decision`,
      affectedRecordId: r.poId,
      affectedRecordType: 'purchase_order',
      subjectLabel: po?.code ?? r.poId,
    });
  }
}

function supplierScoreNow(supplierId: string): { score: number | null; rated: number } {
  const supplier = byId(suppliers, supplierId);
  const rated = supplierOrderRatings.filter((r) => r.supplierId === supplierId).length;
  return { score: supplier && rated > 0 ? Math.round(computeSupplierPerformanceScore(supplier) * 100) / 100 : null, rated };
}

function recordTermsChange(change: Omit<SupplierTermsChange, 'id' | 'isDemo'>): void {
  paymentTermsCounter += 1;
  supplierTermsHistory.push({ id: `stc-new-${paymentTermsCounter}`, isDemo: true, ...change });
}

function createOrderRating(po: SupplierPurchaseOrder, deliveredAt: string): void {
  if (!po.supplierId || supplierOrderRatings.some((r) => r.poId === po.id)) return;
  const deal = byId(deals, po.dealId);
  // Held to the promised date — Admin's own, or the agreed SLA (098).
  const expected = promisedDeliveryOf(po) ?? deliveredAt;
  ratingCounter += 1;
  supplierOrderRatings.push({
    id: `rt-new-${ratingCounter}`,
    supplierId: po.supplierId,
    poId: po.id,
    orderCode: po.code,
    siteName: deal ? (resolveLead(deal.leadId)?.siteName ?? '') : '',
    expectedDeliveryDate: expected,
    deliveredAt,
    timelinessDays: Math.round((new Date(deliveredAt).getTime() - new Date(expected).getTime()) / 86_400_000),
    // 105: why it was late, when someone said, so the scorecard can tell a supplier's fault from a flood.
    delayCause: [...delayCases].reverse().find((c) => c.poId === po.id && c.rootCause)?.rootCause,
    defects: [],
    isDemo: true,
  });
  // 108: a report Admin already attributed becomes a defect on the rating the moment it exists.
  for (const r of discrepancyReports.filter((x) => x.poId === po.id && x.attribution)) syncReportDefect(r);
  recomputeSupplierMetrics(po.supplierId);
}

/* ------------------------------------------ Supplier threads (099) helpers */

/** Admin sees every supplier thread; a supplier only their own. */
function threadViewer(byUserId: string): { actor: User; supplierId: string | null } {
  const actor = catalogActor(byUserId);
  if (actor.role === 'admin') return { actor, supplierId: null };
  if (actor.role !== 'supplier') throw new RepositoryError('forbidden');
  const own = suppliers.find((sp) => supplierUserFor(sp)?.id === actor.id);
  if (!own) throw new RepositoryError('forbidden');
  return { actor, supplierId: own.id };
}

/** One thread per (supplier, PO), and one general thread per supplier. */
function ensureSupplierThread(supplierId: string, poId?: string): SupplierThread {
  const existing = supplierThreads.find((th) => th.supplierId === supplierId && (th.relatedPoId ?? null) === (poId ?? null));
  if (existing) return existing;
  if (poId && byId(supplierPurchaseOrders, poId)?.supplierId !== supplierId) throw new RepositoryError('invalid_input');
  supplierMessageCounter += 1;
  const created: SupplierThread = { id: `sth-new-${supplierMessageCounter}`, supplierId, relatedPoId: poId, createdAt: new Date().toISOString(), isDemo: true };
  supplierThreads.push(created);
  return created;
}

function pushSupplierMessage(thread: SupplierThread, fields: Omit<SupplierMessage, 'id' | 'threadId' | 'isDemo'>): SupplierMessage {
  if (fields.poRef && byId(supplierPurchaseOrders, fields.poRef)?.supplierId !== thread.supplierId) throw new RepositoryError('invalid_input');
  supplierMessageCounter += 1;
  const created: SupplierMessage = { id: `smsg-new-${supplierMessageCounter}`, threadId: thread.id, isDemo: true, ...fields };
  supplierMessages.push(created);
  return created;
}

/** A PO's stage changes, one per move (a five-line move is one event). */
function uniquePoStageEvents(po: SupplierPurchaseOrder): { id: string; at: string; toStage: PoFulfilmentStage }[] {
  const seen = new Set<string>();
  const out: { id: string; at: string; toStage: PoFulfilmentStage }[] = [];
  for (const e of [...(po.statusEvents ?? [])].sort((a, b) => (a.at < b.at ? -1 : 1))) {
    const key = `${e.at}|${e.toStage}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ id: `${po.id}-${e.id}`, at: e.at, toStage: e.toStage });
  }
  return out;
}

function threadSummary(thread: SupplierThread, viewerSide: SupplierMessageAuthor, now: number): SupplierThreadSummary {
  const messages = supplierMessages.filter((msg) => msg.threadId === thread.id).sort(byMessageAt);
  const waiting = awaitingReply(messages);
  const po = thread.relatedPoId ? byId(supplierPurchaseOrders, thread.relatedPoId) : null;
  return {
    threadId: thread.id,
    supplierId: thread.supplierId,
    supplierName: byId(suppliers, thread.supplierId)?.name ?? '',
    poId: thread.relatedPoId ?? null,
    poCode: po?.code ?? null,
    lastMessage: messages[messages.length - 1] ?? null,
    unreadCount: messages.filter((msg) => msg.author !== viewerSide && !msg.readAt).length,
    awaiting: waiting ? { from: waiting.from, since: waiting.since, overdue: isUnanswered(waiting, now) } : null,
    lastSupplierResponseAt: lastSupplierResponseAt(messages),
  };
}

function adminOnly(byUserId: string): User {
  const actor = catalogActor(byUserId);
  if (actor.role !== 'admin') throw new RepositoryError('forbidden');
  return actor;
}

function ratingOrThrow(ratingId: string): SupplierOrderRating {
  const rating = byId(supplierOrderRatings, ratingId);
  if (!rating) throw new RepositoryError('not_found');
  return rating;
}

export const memoryRepository: Repository = {
  /* ------------------------------------------------------------- Users */
  listUsers: (filter) =>
    simulateRead(() =>
      users.filter(
        (u) =>
          (!filter?.role || u.role === filter.role) &&
          (!filter?.status || u.status === filter.status),
      ),
    ),

  getUser: (id) => simulateRead(() => byId(users, id)),

  updateUser: (id, patch) => simulateWrite(() => patchInPlace(users, id, patch) as User),

  /* ------------------------------------------------------------- Leads */
  listLeads: (filter?: LeadFilter) =>
    simulateRead(() => {
      const q = filter?.query?.trim().toLowerCase();
      const matched = leads
        // A merged-away duplicate stays a real, directly-fetchable record
        // (for audit) but never resurfaces in a list as if it were still active.
        .filter((l) => !l.duplicateOfLeadId)
        .filter((l) => !filter?.stage || filter.stage.includes(l.stage))
        .filter((l) => !filter?.surveyorId || l.surveyorId === filter.surveyorId)
        .filter((l) => !filter?.city || l.city === filter.city)
        .filter((l) => !filter?.source || filter.source.includes(l.source))
        .filter((l) => !filter?.unassignedOnly || !l.surveyorId)
        .filter(
          (l) =>
            !q ||
            l.siteName.toLowerCase().includes(q) ||
            l.builderName.toLowerCase().includes(q) ||
            l.contactName.toLowerCase().includes(q) ||
            l.code.toLowerCase().includes(q) ||
            l.contactPhone.includes(q),
        );

      if (filter?.sort === 'priority') {
        // Equal scores break by recency — a newer opportunity edges ahead of
        // an older one that hasn't moved, a sensible default per the scoring
        // screen's tie-break rule.
        return matched.sort((a, b) => (b.score ?? 0) - (a.score ?? 0) || b.createdAt.localeCompare(a.createdAt));
      }
      if (filter?.sort === 'recent') {
        return matched.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
      }
      // 'stale' (the default): no-recent-activity leads surface first so
      // sales attention never depends on remembering to sort for it.
      return matched.sort((a, b) => a.updatedAt.localeCompare(b.updatedAt));
    }),

  getLead: (id) => simulateRead(() => resolveLead(id)),

  createLead: (draft) =>
    simulateWrite(() => {
      leadCounter += 1;
      const now = new Date().toISOString();
      const lead: Lead = {
        ...draft,
        id: `l-new-${leadCounter}`,
        code: `AIEC-L-0${leadCounter}`,
        originalSurveyorId: draft.surveyorId,
        createdAt: now,
        updatedAt: now,
        stageEnteredAt: now,
        isDemo: true,
      };
      leads.unshift(lead);
      pushTimelineEvent({ leadId: lead.id, kind: 'captured', actorName: nameOf(lead.surveyorId), at: now, detail: lead.siteName });
      return lead;
    }),

  updateLead: (id, patch) =>
    simulateWrite(() => {
      const before = byId(leads, id);
      const now = new Date().toISOString();
      // Entering a new stage resets the clock the SLA alerts measure against.
      const stagePatch = patch.stage && patch.stage !== before?.stage ? { stageEnteredAt: now } : {};
      const updated = patchInPlace(leads, id, { ...patch, ...stagePatch, updatedAt: now });
      if (before && patch.stage && patch.stage !== before.stage) {
        pushTimelineEvent({
          leadId: id,
          kind: 'stage_changed',
          actorName: nameOf(updated.surveyorId),
          at: now,
          fromValue: before.stage,
          toValue: patch.stage,
        });
        // Responsiveness and territory-conversion-rate factors both shift the
        // moment any lead's stage changes — recompute rather than waiting for
        // the next weighting-profile edit to happen to touch this record.
        recomputeActiveScores(scoreWeightingProfile);
      }
      if (patch.notes && patch.notes !== before?.notes) {
        pushTimelineEvent({ leadId: id, kind: 'note_added', actorName: nameOf(updated.surveyorId), at: now, detail: patch.notes });
      }
      return byId(leads, id) ?? updated;
    }),

  listLeadTimeline: (leadId) =>
    simulateRead(() => leadTimeline.filter((e) => e.leadId === leadId).sort((a, b) => a.at.localeCompare(b.at))),

  addLeadNote: (leadId, note, actorName) =>
    simulateWrite(() => pushTimelineEvent({ leadId, kind: 'note_added', actorName, at: new Date().toISOString(), detail: note })),

  sendLeadMessage: (leadId, message, actorName) =>
    simulateWrite(() => pushTimelineEvent({ leadId, kind: 'communication_sent', actorName, at: new Date().toISOString(), detail: message })),

  reassignLead: (leadId, toSurveyorId, reasonNote, actorName) =>
    simulateWrite(() => {
      const lead = byId(leads, leadId);
      if (!lead) throw new RepositoryError('not_found');
      const target = byId(users, toSurveyorId);
      if (!target || target.role !== 'surveyor' || target.status !== 'active' || !acceptsNewWork(target.id)) {
        throw new RepositoryError('ineligible_assignee');
      }
      const fromId = lead.surveyorId;
      const now = new Date().toISOString();
      const updated = patchInPlace(leads, leadId, { surveyorId: toSurveyorId, updatedAt: now });
      pushTimelineEvent({
        leadId,
        kind: 'reassigned',
        actorName,
        at: now,
        detail: reasonNote,
        fromValue: fromId ? nameOf(fromId) : undefined,
        toValue: nameOf(toSurveyorId),
      });
      return updated;
    }),

  bulkReassignLeads: (leadIds, toSurveyorId, reasonNote, actorName) =>
    simulateWrite(() => {
      const target = byId(users, toSurveyorId);
      if (!target || target.role !== 'surveyor' || target.status !== 'active' || !acceptsNewWork(target.id)) {
        throw new RepositoryError('ineligible_assignee');
      }
      const now = new Date().toISOString();
      return leadIds
        .map((id) => byId(leads, id))
        .filter((l): l is Lead => l !== null)
        .map((lead) => {
          const fromId = lead.surveyorId;
          const updated = patchInPlace(leads, lead.id, { surveyorId: toSurveyorId, updatedAt: now });
          pushTimelineEvent({
            leadId: lead.id,
            kind: 'reassigned',
            actorName,
            at: now,
            detail: reasonNote,
            fromValue: fromId ? nameOf(fromId) : undefined,
            toValue: nameOf(toSurveyorId),
          });
          return updated;
        });
    }),

  suggestAssignee: (leadId) =>
    simulateRead(() => {
      const lead = resolveLead(leadId);
      if (!lead) return null;
      const candidates = users.filter((u) => u.role === 'surveyor' && u.status === 'active' && u.onDuty && acceptsNewWork(u.id));
      if (candidates.length === 0) return null;
      let best: { userId: string; name: string; reasonKey: string; score: number } | null = null;
      for (const candidate of candidates) {
        const distanceKm = candidate.location ? haversineKm(lead.location, candidate.location) : 999;
        const workload = leads.filter((l) => l.surveyorId === candidate.id && l.stage !== 'won' && l.stage !== 'lost').length;
        const score = distanceKm + workload * 2;
        if (!best || score < best.score) {
          best = {
            userId: candidate.id,
            name: candidate.name,
            reasonKey: distanceKm <= workload * 2 ? 'assignment.reason.proximity' : 'assignment.reason.workload',
            score,
          };
        }
      }
      return best ? { userId: best.userId, name: best.name, reasonKey: best.reasonKey } : null;
    }),

  listDuplicatePairs: (status) =>
    simulateRead(() =>
      duplicatePairs
        .filter((p) => !status || status.includes(p.status))
        .map((p) => ({ ...p, primary: resolveLead(p.primaryLeadId), secondary: resolveLead(p.secondaryLeadId) }))
        .filter((p): p is DuplicatePair & { primary: Lead; secondary: Lead } => p.primary !== null && p.secondary !== null)
        .sort((a, b) => b.detectedAt.localeCompare(a.detectedAt)),
    ),

  resolveDuplicatePair: (id, decision) =>
    simulateWrite(() => {
      const pair = byId(duplicatePairs, id);
      if (!pair) throw new RepositoryError('not_found');
      if (pair.status !== 'pending') throw new RepositoryError('already_resolved');
      const now = new Date().toISOString();

      if (decision.action === 'not_duplicate') {
        return patchInPlace(duplicatePairs, id, { status: 'not_duplicate', resolvedAt: now, resolvedBy: decision.actorName });
      }

      const primaryId = decision.primaryLeadId ?? pair.primaryLeadId;
      const secondaryId = primaryId === pair.primaryLeadId ? pair.secondaryLeadId : pair.primaryLeadId;
      const primary = resolveLead(primaryId);
      const secondary = resolveLead(secondaryId);
      if (!primary || !secondary) throw new RepositoryError('not_found');

      // The more-advanced stage survives the merge, with a logged reconciliation.
      const survivingStage = rankOf(secondary.stage) > rankOf(primary.stage) ? secondary.stage : primary.stage;
      const now2 = now;
      // Winning clears its own duplicate flag too — it may itself have been
      // flagged against the record it just won against, and a survivor
      // should never still read as "possibly a duplicate" once chosen.
      if (byId(leads, primary.id)) {
        patchInPlace(leads, primary.id, { stage: survivingStage, updatedAt: now2, duplicateOfLeadId: undefined });
      } else {
        // The demo capture-flow candidate isn't in the mutable store yet —
        // winning a merge is what promotes it to a real, persisted lead.
        leads.push({ ...primary, stage: survivingStage, updatedAt: now2, duplicateOfLeadId: undefined });
      }
      // Marked, never deleted — the secondary stays a real, directly-fetchable
      // record (Lead Detail still opens it) so both surveyors' original
      // capture evidence survives; `listLeads` is what hides it from active views.
      if (byId(leads, secondary.id)) {
        patchInPlace(leads, secondary.id, { duplicateOfLeadId: primary.id, updatedAt: now2 });
      }

      pushTimelineEvent({
        leadId: primary.id,
        kind: 'merged',
        actorName: decision.actorName,
        at: now2,
        detail: `Merged with ${secondary.code} (captured by ${nameOf(secondary.originalSurveyorId)}); stage reconciled to ${survivingStage}`,
        fromValue: primary.stage,
        toValue: survivingStage,
      });

      return patchInPlace(duplicatePairs, id, {
        status: 'merged',
        resolvedAt: now2,
        resolvedBy: decision.actorName,
        commissionImpactSummary: `${nameOf(primary.originalSurveyorId)} retains the capture bonus for ${primary.code}; ${nameOf(secondary.originalSurveyorId)}'s duplicate entry earns no further commission.`,
      });
    }),

  getScoreWeightingProfile: () => simulateRead(() => ({ ...scoreWeightingProfile })),

  updateScoreWeightingProfile: (patch) =>
    simulateWrite(() => {
      const before = scoreWeightingProfile;
      const next: ScoreWeightingProfile = { ...before, ...patch, updatedAt: new Date().toISOString() };
      const totalShift =
        Math.abs(next.buildingSize - before.buildingSize) +
        Math.abs(next.constructionReadiness - before.constructionReadiness) +
        Math.abs(next.responsiveness - before.responsiveness) +
        Math.abs(next.territoryHistory - before.territoryHistory);
      scoreWeightingProfile = next;
      recomputeActiveScores(next);
      return { profile: next, reshuffleWarning: totalShift > 0.3 };
    }),

  listFollowUpTasks: (filter) =>
    simulateRead(() => {
      reconcileFollowUpTasks();
      const now = new Date().toISOString();
      return followUpTasks
        .filter((t) => !filter?.status || filter.status.includes(t.status))
        .filter((t) => !filter?.assignedTo || t.assignedTo === filter.assignedTo)
        .sort((a, b) => {
          const aOverdue = a.status === 'open' && a.dueDate < now;
          const bOverdue = b.status === 'open' && b.dueDate < now;
          if (aOverdue !== bOverdue) return aOverdue ? -1 : 1;
          return a.dueDate.localeCompare(b.dueDate);
        });
    }),

  createFollowUpTask: (input) =>
    simulateWrite(() => {
      const task: FollowUpTask = {
        id: `ft-new-${(followUpTaskCounter += 1)}`,
        leadId: input.leadId,
        title: input.title,
        dueDate: input.dueDate,
        assignedTo: input.assignedTo,
        status: 'open',
        source: 'manual',
        createdAt: new Date().toISOString(),
        isDemo: true,
      };
      followUpTasks.unshift(task);
      return task;
    }),

  completeFollowUpTask: (id) =>
    simulateWrite(() => completeFollowUpTaskSync(id, nameOf(byId(leads, byId(followUpTasks, id)?.leadId ?? '')?.surveyorId ?? ''))),

  rescheduleFollowUpTask: (id, newDate, reasonKey) =>
    simulateWrite(() => patchInPlace(followUpTasks, id, { dueDate: newDate, rescheduleReasonKey: reasonKey })),

  bulkRescheduleFollowUpTasks: (ids, newDate, reasonKey) =>
    simulateWrite(() => ids.map((id) => patchInPlace(followUpTasks, id, { dueDate: newDate, rescheduleReasonKey: reasonKey }))),

  bulkReassignFollowUpTasks: (ids, assignedTo) =>
    simulateWrite(() => ids.map((id) => patchInPlace(followUpTasks, id, { assignedTo }))),

  getLeadSourceAttribution: () =>
    simulateRead(() => {
      const sources: LeadSource[] = ['field_survey', 'referral_repeat', 'inbound_website', 'inbound_whatsapp', 'bulk_import'];
      // A referral carries a flat bonus cost; field-capture cost is the
      // surveyor's own conversion incentive; inbound channels are organic.
      const REFERRAL_BONUS = 5_000;
      return sources
        .map<LeadSourceAttribution>((source) => {
          const own = leads.filter((l) => l.source === source);
          const won = own.filter((l) => l.stage === 'won');
          const weekBuckets = new Map<string, number>();
          for (const lead of own) {
            const d = new Date(lead.createdAt);
            const weekStart = new Date(d);
            weekStart.setDate(d.getDate() - d.getDay());
            const key = weekStart.toISOString().slice(0, 10);
            weekBuckets.set(key, (weekBuckets.get(key) ?? 0) + 1);
          }
          const trend = [...weekBuckets.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([t, v]) => ({ t, v }));
          const avgIncentive = won.length ? won.reduce((sum, l) => sum + l.incentiveAmount, 0) / won.length : 0;
          return {
            source,
            leadCount: own.length,
            conversionRate: own.length ? won.length / own.length : 0,
            avgDealValue: won.length ? Math.round(won.reduce((sum, l) => sum + l.estimatedValue, 0) / won.length) : 0,
            costPerConversion:
              source === 'field_survey' && won.length
                ? Math.round(avgIncentive)
                : source === 'referral_repeat' && won.length
                  ? REFERRAL_BONUS
                  : undefined,
            trend,
          };
        })
        .filter((row) => row.leadCount > 0);
    }),

  markLeadLost: (leadId, input) =>
    simulateWrite(() => {
      const lead = byId(leads, leadId);
      if (!lead) throw new RepositoryError('not_found');
      const now = new Date().toISOString();
      const updated = patchInPlace(leads, leadId, {
        stage: 'lost',
        stageEnteredAt: now,
        updatedAt: now,
        lostReason: input.reasonKey,
        lostNote: input.note,
        revisitReminderDate: input.revisitReminderDate,
        markedLostBy: input.actorName,
        markedLostAt: now,
      });
      pushTimelineEvent({ leadId, kind: 'marked_lost', actorName: input.actorName, at: now, detail: input.reasonKey });
      if (input.revisitReminderDate) {
        followUpTasks.unshift({
          id: `ft-new-${(followUpTaskCounter += 1)}`,
          leadId,
          title: `Revisit: ${lead.siteName}`,
          dueDate: input.revisitReminderDate,
          assignedTo: lead.surveyorId,
          status: 'open',
          source: 'auto',
          createdAt: now,
          isDemo: true,
        });
      }
      return updated;
    }),

  bulkMarkLeadsLost: (leadIds, input) =>
    simulateWrite(() => {
      const now = new Date().toISOString();
      return leadIds
        .map((id) => byId(leads, id))
        .filter((l): l is Lead => l !== null)
        .map((lead) => {
          const updated = patchInPlace(leads, lead.id, {
            stage: 'lost',
            stageEnteredAt: now,
            updatedAt: now,
            lostReason: input.reasonKey,
            lostNote: input.note,
            markedLostBy: input.actorName,
            markedLostAt: now,
          });
          pushTimelineEvent({ leadId: lead.id, kind: 'marked_lost', actorName: input.actorName, at: now, detail: input.reasonKey });
          return updated;
        });
    }),

  reopenLead: (leadId, actorName) =>
    simulateWrite(() => {
      const lead = byId(leads, leadId);
      if (!lead) throw new RepositoryError('not_found');
      if (lead.stage !== 'lost') throw new RepositoryError('not_lost');
      const now = new Date().toISOString();
      const updated = patchInPlace(leads, leadId, {
        stage: 'contacted',
        stageEnteredAt: now,
        updatedAt: now,
        lostReason: undefined,
        lostNote: undefined,
        revisitReminderDate: undefined,
        markedLostBy: undefined,
        markedLostAt: undefined,
      });
      pushTimelineEvent({ leadId, kind: 'reopened', actorName, at: now });
      return updated;
    }),

  previewLeadImport: (rows) =>
    simulateRead(() => buildImportPreview(rows)),

  commitLeadImport: (rows, fileName, importedBy) =>
    simulateWrite(() => {
      const preview = buildImportPreview(rows);
      const now = new Date().toISOString();
      const batch: LeadImportBatch = {
        id: `ib-new-${(importBatchCounter += 1)}`,
        fileName,
        importedBy,
        importedAt: now,
        totalRows: rows.length,
        importedRows: preview.validCount,
        rejectedRows: preview.errorCount,
        isDemo: true,
      };
      for (const row of preview.rows) {
        if (row.errors.length > 0) continue;
        leadCounter += 1;
        const v = row.values;
        const lat = Number(v.lat);
        const lng = Number(v.lng);
        const lead: Lead = {
          id: `l-new-${leadCounter}`,
          code: `AIEC-L-0${leadCounter}`,
          stage: 'captured',
          surveyorId: '',
          originalSurveyorId: '',
          source: 'bulk_import',
          builderName: v.builderName ?? '',
          contactName: v.contactName ?? '',
          contactPhone: v.contactPhone ?? '',
          siteName: v.siteName ?? '',
          address: v.address ?? '',
          city: v.city ?? '',
          pincode: v.pincode ?? '',
          location: Number.isFinite(lat) && Number.isFinite(lng) ? { lat, lng } : { lat: 0, lng: 0 },
          photos: [],
          estimatedValue: Number(v.estimatedValue) || 0,
          incentiveAmount: 0,
          incentiveStatus: 'projected',
          createdAt: now,
          updatedAt: now,
          stageEnteredAt: now,
          isDemo: true,
          importBatchId: batch.id,
        };
        leads.push(lead);
        pushTimelineEvent({ leadId: lead.id, kind: 'captured', actorName: importedBy, at: now, detail: `Imported from ${fileName}` });
      }
      importBatches.unshift(batch);
      return batch;
    }),

  listImportBatches: () => simulateRead(() => [...importBatches].sort((a, b) => b.importedAt.localeCompare(a.importedAt))),

  findDuplicateLeads: (candidate) =>
    simulateRead(() => {
      const matches: Array<{ lead: Lead; distanceMetres: number; reason: 'proximity' | 'phone' | 'name' }> = [];
      const candidateName = candidate.siteName.trim().toLowerCase();
      for (const lead of leads) {
        const metres = Math.round(haversineKm(candidate.location, lead.location) * 1000);
        if (candidate.contactPhone && lead.contactPhone === candidate.contactPhone) {
          matches.push({ lead, distanceMetres: metres, reason: 'phone' });
        } else if (metres <= 150) {
          matches.push({ lead, distanceMetres: metres, reason: 'proximity' });
        } else if (candidateName && lead.siteName.trim().toLowerCase() === candidateName) {
          matches.push({ lead, distanceMetres: metres, reason: 'name' });
        }
      }
      return matches.sort((a, b) => a.distanceMetres - b.distanceMetres).slice(0, 5);
    }),

  /* ------------------------------------------------- Deals / jobs / money */
  listDeals: (filter) =>
    simulateRead(() => deals.filter((d) => !filter?.status || filter.status.includes(d.status))),

  getDeal: (id) => simulateRead(() => byId(deals, id)),

  listJobs: (filter) =>
    simulateRead(() =>
      jobs
        .filter((j) => !filter?.technicianId || j.technicianId === filter.technicianId)
        .filter((j) => !filter?.status || filter.status.includes(j.status)),
    ),

  getJob: (id) => simulateRead(() => byId(jobs, id)),

  listPayments: (filter) =>
    simulateRead(() =>
      payments
        .filter((p) => !filter?.dealId || p.dealId === filter.dealId)
        .filter((p) => !filter?.status || filter.status.includes(p.status))
        .sort((a, b) => a.dueDate.localeCompare(b.dueDate)),
    ),

  getPaymentCollectionLines: () =>
    simulateRead(() =>
      payments
        .map((payment) => {
          const deal = byId(deals, payment.dealId);
          const lead = deal ? resolveLead(deal.leadId) : null;
          return {
            payment,
            dealCode: deal?.code ?? payment.code,
            siteName: lead?.siteName ?? '',
            ownerUserId: lead?.surveyorId ?? '',
            ownerName: lead?.surveyorId ? nameOf(lead.surveyorId) : '',
          };
        })
        .sort((a, b) => a.payment.dueDate.localeCompare(b.payment.dueDate)),
    ),

  recordPaymentReceived: (paymentId, input) =>
    simulateWrite(() => {
      const payment = byId(payments, paymentId);
      if (!payment) throw new RepositoryError('not_found');
      const totalReceived = (payment.amountReceived ?? 0) + input.amountReceived;
      const fullyPaid = totalReceived >= payment.amount;
      return patchInPlace(payments, paymentId, {
        amountReceived: totalReceived,
        manualReferenceNumber: input.referenceNumber,
        recordedManuallyBy: input.byUserId,
        method: input.method ?? payment.method,
        status: fullyPaid ? 'paid' : payment.status,
        paidAt: fullyPaid ? new Date().toISOString() : payment.paidAt,
        lastReceivedAt: new Date().toISOString(),
      });
    }),

  disputePayment: (paymentId, reason, byUserId) =>
    simulateWrite(() => {
      const payment = byId(payments, paymentId);
      if (!payment) throw new RepositoryError('not_found');
      return patchInPlace(payments, paymentId, {
        status: 'disputed',
        disputeReason: reason,
        disputedBy: byUserId,
        disputedAt: new Date().toISOString(),
        // Screen 090's own resolution needs to know what to restore on a
        // rejected (or non-full-refund) outcome — never invented, always
        // whatever this stage genuinely was right before the dispute.
        preDisputeStatus: payment.status,
        // A `'paid'` stage's `amountReceived` was allowed to stay unset
        // (status alone said it all) until disputing it moved status away
        // from `'paid'` — every other screen's remaining-balance math reads
        // `amountReceived` directly, so this stops that math from reading
        // a fully-paid, now-disputed stage as if nothing had been received.
        amountReceived: payment.status === 'paid' ? payment.amount : payment.amountReceived,
      });
    }),

  sendPaymentReminder: (paymentId, byName) =>
    simulateWrite(() => {
      const payment = byId(payments, paymentId);
      if (!payment) throw new RepositoryError('not_found');
      const deal = byId(deals, payment.dealId);
      if (!deal) throw new RepositoryError('not_found');
      const lead = resolveLead(deal.leadId);
      if (!lead) throw new RepositoryError('not_found');
      return sendReminderMessage(payment, lead, byName, 'sms', 'tpl-payment-reminder');
    }),

  escalatePayment: (paymentId) =>
    simulateWrite(() => {
      const payment = byId(payments, paymentId);
      if (!payment) throw new RepositoryError('not_found');
      const deal = byId(deals, payment.dealId);
      const daysLate = Math.floor((Date.now() - new Date(payment.dueDate).getTime()) / 86_400_000);
      return raiseAlert({
        titleKey: 'alerts.type.paymentOverdue',
        context: `${deal?.code ?? payment.code} · ${formatINR(remainingBalance(payment))} · ${daysLate} days past due`,
        severity: daysLate > 60 ? 'critical' : daysLate > 30 ? 'high' : 'medium',
        category: 'payment',
        relatedId: paymentId,
        sourceRoute: '/admin/analytics/collections',
      });
    }),

  getPaymentCheckoutView: (paymentId, customerId) =>
    simulateRead(() => {
      const payment = byId(payments, paymentId);
      if (!payment) return null;
      const deal = byId(deals, payment.dealId);
      if (!deal || deal.customerId !== customerId) return null;
      const lead = resolveLead(deal.leadId);
      return {
        payment,
        dealCode: deal.code,
        siteName: lead?.siteName ?? '',
        amountDue: remainingBalance(payment),
      };
    }),

  attemptPaymentGatewayCheckout: (paymentId, customerId, method, isRetry) =>
    simulateWrite(() => {
      const payment = byId(payments, paymentId);
      if (!payment) throw new RepositoryError('not_found');
      const deal = byId(deals, payment.dealId);
      if (!deal || deal.customerId !== customerId) throw new RepositoryError('not_found');
      if (payment.status === 'paid') throw new RepositoryError('already_paid');
      if (method === 'card' && !isRetry) {
        return { outcome: 'failed', payment };
      }
      if (method === 'netbanking') {
        const updated = patchInPlace(payments, payment.id, { status: 'pending', method });
        return { outcome: 'processing', payment: updated };
      }
      gatewayTransactionCounter += 1;
      const updated = patchInPlace(payments, payment.id, {
        status: 'paid',
        paidAt: new Date().toISOString(),
        amountReceived: payment.amount,
        lastReceivedAt: new Date().toISOString(),
        method,
        gatewayTransactionRef: `PAYU-GW-${gatewayTransactionCounter}`,
      });
      return { outcome: 'paid', payment: updated };
    }),

  reconcilePaymentGatewayStatus: (paymentId) =>
    simulateWrite(() => {
      const payment = byId(payments, paymentId);
      if (!payment) throw new RepositoryError('not_found');
      if (payment.status === 'paid') return payment;
      gatewayTransactionCounter += 1;
      return patchInPlace(payments, payment.id, {
        status: 'paid',
        paidAt: new Date().toISOString(),
        amountReceived: payment.amount,
        lastReceivedAt: new Date().toISOString(),
        gatewayTransactionRef: `PAYU-GW-${gatewayTransactionCounter}`,
      });
    }),

  getLoanApplicationView: (dealId, customerId) =>
    simulateRead(() => {
      const deal = byId(deals, dealId);
      if (!deal || deal.customerId !== customerId) return null;
      const lead = resolveLead(deal.leadId);
      const outstandingPayments = payments.filter((p) => p.dealId === dealId && isOutstanding(p)).sort((a, b) => a.dueDate.localeCompare(b.dueDate));
      const remaining = outstandingPayments.reduce((sum, p) => sum + remainingBalance(p), 0);
      const active = loanApplications
        .filter((a) => a.dealId === dealId && a.status !== 'cancelled')
        .sort((a, b) => b.submittedAt.localeCompare(a.submittedAt))[0];
      return {
        dealCode: deal.code,
        siteName: lead?.siteName ?? '',
        remainingBalance: remaining,
        firstRemainingPaymentId: outstandingPayments[0]?.id ?? null,
        activeApplication: active ?? null,
      };
    }),

  getFinancingPartnerRates: (isRetry) =>
    simulateRead(() => {
      if (!isRetry) throw new RepositoryError('partner_unavailable');
      return [...financingPartnerRates];
    }),

  submitLoanApplication: (dealId, customerId, input) =>
    simulateWrite(() => {
      const deal = byId(deals, dealId);
      if (!deal || deal.customerId !== customerId) throw new RepositoryError('not_found');
      loanApplicationCounter += 1;
      const created: LoanApplication = {
        id: `loan-${loanApplicationCounter}`,
        dealId,
        customerId,
        partnerName: FINANCING_PARTNER_NAME,
        precheck: input.precheck,
        requestedAmount: input.requestedAmount,
        tenureMonths: input.tenureMonths,
        interestRatePercent: input.interestRatePercent,
        emiAmount: input.emiAmount,
        totalRepayment: input.totalRepayment,
        status: 'submitted',
        submittedAt: new Date().toISOString(),
        isDemo: true,
      };
      loanApplications.push(created);
      return created;
    }),

  advanceLoanApplication: (applicationId) =>
    simulateWrite(() => {
      const app = byId(loanApplications, applicationId);
      if (!app) throw new RepositoryError('not_found');
      if (app.status === 'submitted') {
        return patchInPlace(loanApplications, app.id, { status: 'under_review', underReviewAt: new Date().toISOString() });
      }
      if (app.status === 'under_review') {
        const approvedAmount = approvedAmountFor(app.precheck.incomeRange, app.requestedAmount);
        return patchInPlace(loanApplications, app.id, { status: 'approved', approvedAmount, approvedAt: new Date().toISOString() });
      }
      if (app.status === 'approved') {
        const disbursedAmountReceived = app.approvedAmount ?? app.requestedAmount;
        settleDealPaymentsWithFinancing(app.dealId, disbursedAmountReceived);
        return patchInPlace(loanApplications, app.id, { status: 'disbursed', disbursedAmountReceived, disbursedAt: new Date().toISOString() });
      }
      return app;
    }),

  cancelLoanApplication: (applicationId, reason, byName) =>
    simulateWrite(() => {
      const app = byId(loanApplications, applicationId);
      if (!app) throw new RepositoryError('not_found');
      if (app.status === 'disbursed') throw new RepositoryError('already_disbursed');
      if (app.status === 'cancelled') return app;
      return patchInPlace(loanApplications, app.id, {
        status: 'cancelled',
        cancelReason: reason.trim(),
        cancelledBy: byName,
        cancelledAt: new Date().toISOString(),
      });
    }),

  listLoanApplicationsForAdmin: () =>
    simulateRead(() => {
      const now = Date.now();
      return loanApplications
        .map((application): LoanApplicationAdminRow => {
          const deal = byId(deals, application.dealId);
          const lead = deal ? resolveLead(deal.leadId) : null;
          const isStuck = application.status === 'approved' && !!application.approvedAt && isBreached(application.approvedAt, LOAN_STUCK_WINDOW, now);
          const disbursementShortfall = application.status === 'disbursed' && application.approvedAmount !== undefined && application.disbursedAmountReceived !== undefined ? Math.max(0, application.approvedAmount - application.disbursedAmountReceived) : 0;
          return {
            application,
            dealCode: deal?.code ?? application.dealId,
            siteName: lead?.siteName ?? '',
            customerName: nameOf(application.customerId),
            isStuck,
            disbursementShortfall,
          };
        })
        .sort((a, b) => b.application.submittedAt.localeCompare(a.application.submittedAt));
    }),

  getLoanPartnerStats: () =>
    simulateRead(() => {
      const byPartner = new Map<string, LoanApplication[]>();
      for (const app of loanApplications) {
        const list = byPartner.get(app.partnerName) ?? [];
        list.push(app);
        byPartner.set(app.partnerName, list);
      }
      return [...byPartner.entries()].map(([partnerName, apps]): LoanPartnerStat => {
        const decided = apps.filter((a) => a.status === 'approved' || a.status === 'disbursed');
        const disbursed = apps.filter((a) => a.status === 'disbursed' && a.disbursedAt);
        const avgDays =
          disbursed.length === 0
            ? null
            : disbursed.reduce((sum, a) => sum + (new Date(a.disbursedAt!).getTime() - new Date(a.submittedAt).getTime()), 0) / disbursed.length / 86_400_000;
        return {
          partnerName,
          totalApplications: apps.length,
          approvedOrDisbursedCount: decided.length,
          approvalRatePercent: apps.length === 0 ? 0 : Math.round((decided.length / apps.length) * 100),
          avgDaysToDisbursement: avgDays === null ? null : Math.round(avgDays * 10) / 10,
        };
      });
    }),

  escalateLoanApplication: (applicationId) =>
    simulateWrite(() => {
      const app = byId(loanApplications, applicationId);
      if (!app) throw new RepositoryError('not_found');
      const deal = byId(deals, app.dealId);
      const daysStuck = app.approvedAt ? Math.floor((Date.now() - new Date(app.approvedAt).getTime()) / 86_400_000) : 0;
      return raiseAlert({
        titleKey: 'alerts.type.loanDisbursementDelayed',
        context: `${deal?.code ?? app.dealId} · ${app.partnerName} · approved ${daysStuck} days ago, not yet disbursed`,
        severity: daysStuck > 14 ? 'critical' : daysStuck > 7 ? 'high' : 'medium',
        category: 'payment',
        relatedId: applicationId,
        sourceRoute: '/admin/analytics/financing',
      });
    }),

  getInvoicesForDeal: (dealId, viewer) =>
    simulateRead(() => {
      const deal = byId(deals, dealId);
      if (!deal) return null;
      if (viewer.role === 'customer' && deal.customerId !== viewer.id) return null;
      const lead = resolveLead(deal.leadId);
      ensureStageInvoices(dealId, deal, lead);
      const dealPayments = payments.filter((p) => p.dealId === dealId);
      const allStagesPaid = dealPayments.length > 0 && dealPayments.every((p) => p.status === 'paid');
      const dealInvoices = invoices.filter((inv) => inv.dealId === dealId).sort((a, b) => a.issuedAt.localeCompare(b.issuedAt));
      const lines: InvoiceLineView[] = dealInvoices.map((invoice) => ({
        invoice,
        isSuperseded: dealInvoices.some((other) => other.supersedesInvoiceId === invoice.id),
      }));
      return {
        dealCode: deal.code,
        siteName: lead?.siteName ?? '',
        customerName: deal.customerId ? nameOf(deal.customerId) : (lead?.contactName ?? ''),
        customerAddress: customerAddressOf(lead),
        customerGstin: deal.customerGstin,
        aiecGstin: AIEC_GSTIN,
        agreedPrice: deal.agreedPrice,
        gstPercent: deal.gstPercent,
        allStagesPaid,
        hasFinalInvoice: dealInvoices.some((inv) => inv.type === 'final' && !dealInvoices.some((other) => other.supersedesInvoiceId === inv.id)),
        invoices: lines,
      };
    }),

  generateFinalInvoice: (dealId, byName) =>
    simulateWrite(() => {
      const deal = byId(deals, dealId);
      if (!deal) throw new RepositoryError('not_found');
      const dealPayments = payments.filter((p) => p.dealId === dealId);
      if (dealPayments.length === 0 || !dealPayments.every((p) => p.status === 'paid')) throw new RepositoryError('stages_unpaid');
      const dealInvoices = invoices.filter((inv) => inv.dealId === dealId);
      const existing = dealInvoices.find((inv) => inv.type === 'final' && !dealInvoices.some((other) => other.supersedesInvoiceId === inv.id));
      if (existing) return existing;
      const lead = resolveLead(deal.leadId);
      const { taxableValue, gstAmount } = splitGst(deal.agreedPrice, deal.gstPercent);
      invoiceCounter += 1;
      const created: Invoice = {
        id: `inv-${invoiceCounter}`,
        code: `AIEC-INV-${4000 + invoiceCounter}`,
        dealId,
        type: 'final',
        customerName: deal.customerId ? nameOf(deal.customerId) : (lead?.contactName ?? ''),
        customerAddress: customerAddressOf(lead),
        customerGstin: deal.customerGstin,
        aiecGstin: AIEC_GSTIN,
        taxableValue,
        gstPercent: deal.gstPercent,
        gstAmount,
        totalAmount: deal.agreedPrice,
        issuedAt: new Date().toISOString(),
        issuedBy: byName,
        isDemo: true,
      };
      invoices.push(created);
      return created;
    }),

  issueCreditNote: (invoiceId, amount, reason, byName) =>
    simulateWrite(() => {
      const original = byId(invoices, invoiceId);
      if (!original) throw new RepositoryError('not_found');
      if (!reason.trim()) throw new RepositoryError('reason_required');
      return createCreditNote(original, amount, reason, byName);
    }),

  reissueInvoice: (invoiceId, reason, byName) =>
    simulateWrite(() => {
      const original = byId(invoices, invoiceId);
      if (!original) throw new RepositoryError('not_found');
      if (!reason.trim()) throw new RepositoryError('reason_required');
      const deal = byId(deals, original.dealId);
      if (!deal) throw new RepositoryError('not_found');
      const lead = resolveLead(deal.leadId);
      invoiceCounter += 1;
      const created: Invoice = {
        ...original,
        id: `inv-${invoiceCounter}`,
        code: `AIEC-INV-${4000 + invoiceCounter}`,
        type: 'reissue',
        customerName: deal.customerId ? nameOf(deal.customerId) : (lead?.contactName ?? ''),
        customerAddress: customerAddressOf(lead),
        customerGstin: deal.customerGstin,
        issuedAt: new Date().toISOString(),
        issuedBy: byName,
        supersedesInvoiceId: original.id,
        reissueReason: reason.trim(),
        referencesInvoiceId: undefined,
        creditNoteReason: undefined,
      };
      invoices.push(created);
      return created;
    }),

  setDealCustomerGstin: (dealId, gstin) =>
    simulateWrite(() => {
      const deal = byId(deals, dealId);
      if (!deal) throw new RepositoryError('not_found');
      return patchInPlace(deals, dealId, { customerGstin: gstin.trim() });
    }),

  getPaymentHistoryForCustomer: (customerId) =>
    simulateRead(() => {
      const customerDeals = deals.filter((d) => d.customerId === customerId);
      const customerPayments = payments.filter((p) => customerDeals.some((d) => d.id === p.dealId));
      for (const deal of customerDeals) {
        ensureStageInvoices(deal.id, deal, resolveLead(deal.leadId));
      }
      const lines = customerPayments
        .filter((p) => receivedAmountOf(p) > 0)
        .map((p) => {
          const deal = customerDeals.find((d) => d.id === p.dealId)!;
          return buildReceiptLine(p, deal, resolveLead(deal.leadId));
        })
        .sort((a, b) => (b.payment.lastReceivedAt ?? b.payment.paidAt ?? '').localeCompare(a.payment.lastReceivedAt ?? a.payment.paidAt ?? ''));
      return {
        totalPaidToDate: lines.reduce((sum, l) => sum + l.receivedAmount, 0),
        totalRemaining: computeTotalReceivable(customerPayments),
        lines,
      };
    }),

  listPaymentHistoryForAdmin: () =>
    simulateRead(() => {
      for (const deal of deals) {
        ensureStageInvoices(deal.id, deal, resolveLead(deal.leadId));
      }
      return payments
        .filter((p) => receivedAmountOf(p) > 0)
        .map((p) => {
          const deal = byId(deals, p.dealId);
          if (!deal) return null;
          return buildReceiptLine(p, deal, resolveLead(deal.leadId));
        })
        .filter((line): line is PaymentReceiptLine => line !== null)
        .sort((a, b) => (b.payment.lastReceivedAt ?? b.payment.paidAt ?? '').localeCompare(a.payment.lastReceivedAt ?? a.payment.paidAt ?? ''));
    }),

  getPaymentReminderConfig: () => simulateRead(() => paymentReminderConfig),

  savePaymentReminderConfig: (steps, sendWindow, editedBy) =>
    simulateWrite(() => {
      const withIds: ReminderRuleStep[] = steps.map((s) => {
        reminderStepCounter += 1;
        return { ...s, id: `rrs-new-${reminderStepCounter}` };
      });
      paymentReminderConfig = {
        ...paymentReminderConfig,
        steps: withIds,
        sendWindowStartHour: sendWindow.startHour,
        sendWindowEndHour: sendWindow.endHour,
        updatedAt: new Date().toISOString(),
        updatedBy: editedBy,
      };
      return paymentReminderConfig;
    }),

  previewReminderTimeline: (paymentId) =>
    simulateRead(() => {
      const payment = byId(payments, paymentId);
      if (!payment) throw new RepositoryError('not_found');
      const deal = byId(deals, payment.dealId);
      if (!deal) throw new RepositoryError('not_found');
      const lead = resolveLead(deal.leadId);
      if (!lead) throw new RepositoryError('not_found');
      return buildReminderTimeline(payment, lead, paymentReminderConfig, Date.now());
    }),

  listPaymentReminderPauses: () =>
    simulateRead(() => {
      const longStandingThresholdMs = 30 * 86_400_000;
      const now = Date.now();
      return paymentReminderPauses
        .filter((p) => p.paused)
        .map((pause) => {
          const deal = byId(deals, pause.dealId);
          const lead = deal ? resolveLead(deal.leadId) : null;
          return {
            pause,
            dealCode: deal?.code ?? pause.dealId,
            siteName: lead?.siteName ?? '',
            isLongStanding: now - new Date(pause.pausedAt).getTime() > longStandingThresholdMs,
          };
        })
        .sort((a, b) => a.pause.pausedAt.localeCompare(b.pause.pausedAt));
    }),

  setDealReminderPause: (dealId, paused, reason, byName) =>
    simulateWrite(() => {
      const deal = byId(deals, dealId);
      if (!deal) throw new RepositoryError('not_found');
      const now = new Date().toISOString();
      const existing = paymentReminderPauses.find((p) => p.dealId === dealId);
      if (paused && !reason?.trim()) throw new RepositoryError('reason_required');
      if (existing) {
        return patchInPlace(paymentReminderPauses, existing.id, paused ? { paused: true, reason: reason!.trim(), pausedBy: byName, pausedAt: now } : { paused: false, resumedBy: byName, resumedAt: now });
      }
      reminderPauseCounter += 1;
      const created: PaymentReminderPause = {
        id: `rrp-new-${reminderPauseCounter}`,
        dealId,
        paused,
        reason: reason?.trim() ?? '',
        pausedBy: byName,
        pausedAt: now,
        isDemo: true,
      };
      paymentReminderPauses.push(created);
      return created;
    }),

  runDueRemindersNow: (byName) => simulateWrite(() => runPaymentReminders(byName)),

  /* --------------------------- Overdue payment escalation (089, Admin) */
  getOverdueEscalationQueue: () =>
    simulateRead(() => {
      const now = Date.now();
      const maxOffset = Math.max(...paymentReminderConfig.steps.map((s) => s.daysOffset));
      const otherPaymentIsFine = (p: Payment) => p.status === 'paid' || (p.status !== 'disputed' && daysOverdue(p, now) <= 0);
      return payments
        .filter((p) => isOutstanding(p) && p.status !== 'disputed' && daysOverdue(p, now) >= maxOffset && !activeDealPause(p.dealId))
        .map((payment): OverdueEscalationRow | null => {
          const deal = byId(deals, payment.dealId);
          if (!deal) return null;
          const lead = resolveLead(deal.leadId);
          if (!lead) return null;
          const otherPayments = payments.filter((p) => p.dealId === deal.id && p.id !== payment.id);
          const goodStanding = otherPayments.length > 0 && otherPayments.some((p) => p.status === 'paid') && otherPayments.every(otherPaymentIsFine);
          const activeJobs = jobs.filter((j) => j.dealId === deal.id && j.status !== 'completed' && j.status !== 'on_hold');
          const safetyStepInProgress = activeJobs.some((j) => j.steps.some((s) => s.status === 'current' && s.requiresEvidence));
          const overdueDays = daysOverdue(payment, now);
          const overdueAmount = remainingBalance(payment);
          return {
            payment,
            dealId: deal.id,
            dealCode: deal.code,
            leadId: lead.id,
            siteName: lead.siteName,
            customerName: deal.customerId ? nameOf(deal.customerId) : lead.contactName,
            overdueAmount,
            overdueDays,
            tier: computeEscalationTier(overdueDays, overdueAmount, goodStanding),
            goodStanding,
            activeJobs,
            safetyStepInProgress,
          };
        })
        .filter((row): row is OverdueEscalationRow => row !== null)
        .sort((a, b) => b.overdueDays - a.overdueDays);
    }),

  sendFormalPaymentNotice: (paymentId, byName) =>
    simulateWrite(() => {
      const payment = byId(payments, paymentId);
      if (!payment) throw new RepositoryError('not_found');
      const deal = byId(deals, payment.dealId);
      if (!deal) throw new RepositoryError('not_found');
      const lead = resolveLead(deal.leadId);
      if (!lead) throw new RepositoryError('not_found');
      const message = sendReminderMessage(payment, lead, byName, 'whatsapp', 'tpl-payment-formal-notice');
      pushTimelineEvent({
        leadId: lead.id,
        kind: 'communication_sent',
        actorName: byName,
        at: new Date().toISOString(),
        detail: `Formal payment notice sent for ${payment.code} (${formatINR(remainingBalance(payment))} overdue)`,
      });
      return message;
    }),

  flagInstallationHold: (dealId, reason, byName) =>
    simulateWrite(() => {
      const deal = byId(deals, dealId);
      if (!deal) throw new RepositoryError('not_found');
      const toHold = jobs.filter((j) => j.dealId === dealId && j.status !== 'completed' && j.status !== 'on_hold');
      if (toHold.length === 0) throw new RepositoryError('invalid_state');
      const now = new Date().toISOString();
      const held = toHold.map((job) => patchInPlace(jobs, job.id, { status: 'on_hold', holdReason: reason, heldBy: byName, heldAt: now }));
      const lead = resolveLead(deal.leadId);
      if (lead) {
        pushTimelineEvent({
          leadId: lead.id,
          kind: 'note_added',
          actorName: byName,
          at: now,
          detail: `Installation paused pending overdue payment — ${reason}`,
        });
      }
      return held;
    }),

  /* ------------------------- Refund & dispute management (090, Admin) */
  getDisputeQueue: () =>
    simulateRead(() => {
      const now = Date.now();
      return payments
        .filter((p) => p.disputedAt)
        .map((payment): PaymentDisputeRow | null => {
          const deal = byId(deals, payment.dealId);
          if (!deal) return null;
          const lead = resolveLead(deal.leadId);
          if (!lead) return null;
          const closure = dealClosures.find((dc) => dc.dealId === deal.id && !dc.voided);
          const supplierAllocated = Boolean(closure?.supplierPoId) && !closure?.supplierPoFailed;
          const commissionPaidOut = (closure?.commissionEntryIds ?? []).some((id) => byId(commissions, id)?.status === 'paid');
          const slaHours = Math.floor((now - new Date(payment.disputedAt!).getTime()) / 3_600_000);
          return {
            payment,
            dealId: deal.id,
            dealCode: deal.code,
            leadId: lead.id,
            siteName: lead.siteName,
            customerName: deal.customerId ? nameOf(deal.customerId) : lead.contactName,
            amountPaid: amountCollectedForDispute(payment),
            slaHours,
            slaBreached: !payment.resolvedAt && isBreached(payment.disputedAt!, DISPUTE_SLA, now),
            isResolved: Boolean(payment.resolvedAt),
            isFinancingPayment: payment.method === 'financing',
            hasDownstreamAllocation: supplierAllocated || commissionPaidOut,
          };
        })
        .filter((row): row is PaymentDisputeRow => row !== null)
        .sort((a, b) => {
          if (a.isResolved !== b.isResolved) return a.isResolved ? 1 : -1;
          return b.slaHours - a.slaHours;
        });
    }),

  resolvePaymentDispute: (paymentId, input) =>
    simulateWrite(() => {
      const payment = byId(payments, paymentId);
      if (!payment) throw new RepositoryError('not_found');
      if (payment.status !== 'disputed') throw new RepositoryError('invalid_state');
      if (!input.note.trim()) throw new RepositoryError('reason_required');
      const deal = byId(deals, payment.dealId);
      if (!deal) throw new RepositoryError('not_found');
      const now = new Date().toISOString();
      let creditNote: Invoice | null = null;

      if (input.resolutionType === 'rejected') {
        patchInPlace(payments, paymentId, {
          status: payment.preDisputeStatus ?? 'due',
          resolutionType: 'rejected',
          resolutionNote: input.note.trim(),
          resolvedBy: input.byName,
          resolvedAt: now,
        });
      } else {
        const available = amountCollectedForDispute(payment);
        const refundAmount = input.resolutionType === 'full_refund' ? available : (input.resolutionAmount ?? 0);
        if (refundAmount <= 0 || refundAmount > available) throw new RepositoryError('invalid_amount');
        const lead = resolveLead(deal.leadId);
        ensureStageInvoices(deal.id, deal, lead);
        const original = invoices.find((inv) => inv.paymentId === payment.id && inv.type === 'stage');
        if (original) creditNote = createCreditNote(original, refundAmount, input.note, input.byName);
        patchInPlace(payments, paymentId, {
          status: input.resolutionType === 'full_refund' ? 'refunded' : (payment.preDisputeStatus ?? 'paid'),
          resolutionType: input.resolutionType,
          resolutionAmount: refundAmount,
          resolutionNote: input.note.trim(),
          resolvedBy: input.byName,
          resolvedAt: now,
          refundRoutedToFinancingPartner: payment.method === 'financing' ? true : undefined,
        });
      }

      const lead = resolveLead(deal.leadId);
      if (lead) {
        pushTimelineEvent({
          leadId: lead.id,
          kind: 'note_added',
          actorName: input.byName,
          at: now,
          detail: `Dispute resolved (${input.resolutionType}) for ${payment.code}: ${input.note.trim()}`,
        });
      }
      return { payment: byId(payments, paymentId)!, creditNote };
    }),

  listSuppliers: () => simulateRead(() => [...suppliers]),

  getSupplier: (id) => simulateRead(() => byId(suppliers, id)),

  /* ------------------- Supplier directory & onboarding (091, Admin) */
  getSupplierDirectory: () =>
    simulateRead(() =>
      suppliers
        // A merged-away duplicate is retired, not deleted — but it never
        // reads as a live, selectable entry in its own right again.
        .filter((s) => !s.mergedIntoSupplierId)
        .map(
          (supplier): SupplierDirectoryRow => ({
            supplier,
            performanceScore: computeSupplierPerformanceScore(supplier),
            eligibleForPO: isSupplierEligibleForPO(supplier),
          }),
        )
        .sort((a, b) => b.performanceScore - a.performanceScore),
    ),

  inviteSupplier: (input, byName) =>
    simulateWrite(() => {
      if (!input.name.trim() || !input.contactPhone.trim()) throw new RepositoryError('invalid_input');
      supplierCounter += 1;
      const created: Supplier = {
        id: `sp-new-${supplierCounter}`,
        name: input.name.trim(),
        status: 'pending_approval',
        kycStatus: 'pending',
        city: input.city.trim(),
        contactName: input.contactName?.trim() || undefined,
        contactPhone: input.contactPhone.trim(),
        categories: input.categories,
        driveTypeSpecialties: input.driveTypeSpecialties,
        regionsServed: input.regionsServed,
        onTimeRate: 0,
        qualityScore: 0,
        avgLeadTimeDays: 0,
        openOrders: 0,
        totalOrderValue: 0,
        rating: 0,
        invitedBy: byName,
        invitedAt: new Date().toISOString(),
        isDemo: true,
      };
      suppliers.push(created);
      return created;
    }),

  setSupplierKycStatus: (supplierId, kycStatus, byName) =>
    simulateWrite(() => {
      const supplier = byId(suppliers, supplierId);
      if (!supplier) throw new RepositoryError('not_found');
      const updated = patchInPlace(suppliers, supplierId, {
        kycStatus,
        // Approving brings the account live in the same step — nothing
        // else in this build ever activates a supplier without it.
        status: kycStatus === 'approved' ? 'active' : supplier.status,
        kycReviewedBy: byName,
        kycReviewedAt: new Date().toISOString(),
      });
      // The supplier's own login account (linked by GSTIN) goes live with the
      // KYC approval — otherwise an approved supplier still couldn't sign in.
      const account = supplierUserFor(updated);
      if (account && kycStatus === 'approved' && account.status !== 'active') patchInPlace(users, account.id, { status: 'active' });
      return updated;
    }),

  submitSupplierOnboarding: (input) =>
    simulateWrite(() => {
      const gstin = input.gstin.trim().toUpperCase();
      const phone = input.signatoryPhone.trim();
      if (!input.companyName.trim() || !gstin || !phone) throw new RepositoryError('invalid_input');
      if (suppliers.some((s) => s.gstin?.toUpperCase() === gstin)) throw new RepositoryError('duplicate_gstin');
      if (users.some((u) => u.phone === phone)) throw new RepositoryError('phone_taken');
      const now = new Date().toISOString();
      supplierCounter += 1;
      const supplier: Supplier = {
        id: `sp-new-${supplierCounter}`,
        name: input.companyName.trim(),
        status: 'pending_approval',
        kycStatus: 'pending',
        city: input.city.trim(),
        gstin,
        contactName: input.signatoryName.trim(),
        contactPhone: phone,
        categories: [],
        driveTypeSpecialties: [],
        regionsServed: [],
        onTimeRate: 0,
        qualityScore: 0,
        avgLeadTimeDays: 0,
        openOrders: 0,
        totalOrderValue: 0,
        rating: 0,
        invitedBy: input.signatoryName.trim(),
        invitedAt: now,
        isDemo: true,
      };
      suppliers.push(supplier);
      userCounter += 1;
      users.push({
        id: `u-sup-new-${userCounter}`,
        role: 'supplier',
        name: input.signatoryName.trim(),
        phone,
        status: 'pending_approval',
        preferredLanguage: 'en',
        themePreference: 'light',
        isDemo: true,
        city: input.city.trim(),
        companyName: supplier.name,
        gstin,
        joinedAt: now,
      });
      return supplier;
    }),

  suspendSupplier: (supplierId, reason, byName) =>
    simulateWrite(() => {
      const supplier = byId(suppliers, supplierId);
      if (!supplier) throw new RepositoryError('not_found');
      if (!reason.trim()) throw new RepositoryError('reason_required');
      return patchInPlace(suppliers, supplierId, {
        status: 'suspended',
        suspendedReason: reason.trim(),
        suspendedBy: byName,
        suspendedAt: new Date().toISOString(),
      });
    }),

  addSupplierSpecialty: (supplierId, specialty) =>
    simulateWrite(() => {
      const supplier = byId(suppliers, supplierId);
      if (!supplier) throw new RepositoryError('not_found');
      const trimmed = specialty.trim();
      if (!trimmed) throw new RepositoryError('invalid_input');
      if (supplier.driveTypeSpecialties.includes(trimmed)) return supplier;
      return patchInPlace(suppliers, supplierId, { driveTypeSpecialties: [...supplier.driveTypeSpecialties, trimmed] });
    }),

  mergeSuppliers: (canonicalId, duplicateId, byName) =>
    simulateWrite(() => {
      if (canonicalId === duplicateId) throw new RepositoryError('invalid_input');
      const canonical = byId(suppliers, canonicalId);
      const duplicate = byId(suppliers, duplicateId);
      if (!canonical || !duplicate) throw new RepositoryError('not_found');
      supplierPurchaseOrders.forEach((po) => {
        if (po.supplierId === duplicateId) patchInPlace(supplierPurchaseOrders, po.id, { supplierId: canonicalId });
      });
      deals.forEach((d) => {
        if (d.supplierId === duplicateId) patchInPlace(deals, d.id, { supplierId: canonicalId });
      });
      const now = new Date().toISOString();
      patchInPlace(suppliers, duplicateId, {
        status: 'suspended',
        mergedIntoSupplierId: canonicalId,
        suspendedReason: `Merged into ${canonical.name} as a duplicate record.`,
        suspendedBy: byName,
        suspendedAt: now,
      });
      return patchInPlace(suppliers, canonicalId, {
        totalOrderValue: canonical.totalOrderValue + duplicate.totalOrderValue,
        openOrders: canonical.openOrders + duplicate.openOrders,
      });
    }),

  /* ------------------- Purchase order generator (092, Admin) */
  getPurchaseOrdersForDeal: (dealId) =>
    simulateRead(() => {
      const deal = byId(deals, dealId);
      if (!deal) return null;
      const lead = resolveLead(deal.leadId);
      const existing = supplierPurchaseOrders.filter((po) => po.dealId === dealId && po.lineItems);
      // Drafting follows 094's rules exactly — the same condition the
      // heartbeat uses, never a second hardcoded one here.
      if (existing.length === 0 && autoPoRules.autoDraftEnabled && poTriggerMet(deal)) {
        draftPurchaseOrdersForDeal(deal);
      }
      const purchaseOrders = supplierPurchaseOrders.filter((po) => po.dealId === dealId && po.lineItems).map(buildPurchaseOrderView);
      const draftHold: PurchaseOrderDealView['draftHold'] =
        purchaseOrders.length > 0 || deal.status !== 'won'
          ? null
          : !autoPoRules.autoDraftEnabled
            ? 'automation_off'
            : !poTriggerMet(deal)
              ? 'awaiting_first_payment'
              : null;
      return {
        draftHold,
        dealId: deal.id,
        dealCode: deal.code,
        siteName: lead?.siteName ?? '',
        purchaseOrders,
        eligibleSuppliers: suppliers.filter(isSupplierEligibleForPO),
      };
    }),

  reassignPurchaseOrderSupplier: (poId, newSupplierId) =>
    simulateWrite(() => {
      const po = byId(supplierPurchaseOrders, poId);
      if (!po) throw new RepositoryError('not_found');
      const newSupplier = byId(suppliers, newSupplierId);
      if (!newSupplier) throw new RepositoryError('not_found');
      const repriced = (po.lineItems ?? []).map((line): PurchaseOrderLineItem => {
        const price = catalogPriceFor(newSupplierId, line.category) ?? 0;
        return { ...line, catalogUnitPriceAtDraft: price, agreedUnitPrice: price };
      });
      return patchInPlace(supplierPurchaseOrders, poId, {
        supplierId: newSupplierId,
        lineItems: repriced,
        approvedBy: undefined,
        approvedAt: undefined,
        // Chosen by hand now, not by 094's ranking — the old "why" no longer applies.
        selection: undefined,
        matchedByRulesVersion: undefined,
      });
    }),

  updatePurchaseOrderLine: (poId, lineItemId, input) =>
    simulateWrite(() => {
      const po = byId(supplierPurchaseOrders, poId);
      if (!po) throw new RepositoryError('not_found');
      const lines = po.lineItems ?? [];
      if (!lines.some((l) => l.id === lineItemId)) throw new RepositoryError('not_found');
      const updatedLines = lines.map((l) => (l.id === lineItemId ? { ...l, ...input } : l));
      return patchInPlace(supplierPurchaseOrders, poId, {
        lineItems: updatedLines,
        // A fresh price edit always asks again, even if it happens to
        // land back within tolerance — the earlier approval was for the
        // earlier number, never silently carried forward onto a new one.
        approvedBy: input.agreedUnitPrice !== undefined ? undefined : po.approvedBy,
        approvedAt: input.agreedUnitPrice !== undefined ? undefined : po.approvedAt,
      });
    }),

  setPurchaseOrderExpectedDelivery: (poId, expectedDeliveryDate) =>
    simulateWrite(() => {
      const po = byId(supplierPurchaseOrders, poId);
      if (!po) throw new RepositoryError('not_found');
      return patchInPlace(supplierPurchaseOrders, poId, { expectedDeliveryDate });
    }),

  approvePurchaseOrderPricing: (poId, byName) =>
    simulateWrite(() => {
      const po = byId(supplierPurchaseOrders, poId);
      if (!po) throw new RepositoryError('not_found');
      if (!purchaseOrderNeedsApproval(po.lineItems ?? [])) throw new RepositoryError('invalid_state');
      return patchInPlace(supplierPurchaseOrders, poId, { approvedBy: byName, approvedAt: new Date().toISOString() });
    }),

  sendPurchaseOrder: (poId, byName) =>
    simulateWrite(() => {
      const po = byId(supplierPurchaseOrders, poId);
      if (!po) throw new RepositoryError('not_found');
      const supplier = po.supplierId ? byId(suppliers, po.supplierId) : null;
      if (!supplier || !isSupplierEligibleForPO(supplier)) throw new RepositoryError('supplier_not_eligible');
      if (purchaseOrderNeedsApproval(po.lineItems ?? []) && !po.approvedAt) throw new RepositoryError('approval_required');
      // A new order goes out only under terms in force (098), and carries
      // them with it — so a later amendment or lapse never changes it.
      const agreement = agreementStateFor(supplier.id);
      if (!agreement.current || !canIssueNewPo(agreement.status)) throw new RepositoryError('agreement_not_in_force');
      const sentAt = new Date().toISOString();
      const agreementTerms = snapshotOf(agreement.current);
      return patchInPlace(supplierPurchaseOrders, poId, {
        status: 'sent',
        sentBy: byName,
        sentAt,
        agreementTerms,
        // How AIEC will pay for it (100), frozen like the agreement terms.
        paymentTerms: snapshotFor(supplier, paymentTermsConfig),
        // Admin's own date stands; otherwise the promise is the agreed SLA.
        expectedDeliveryDate: po.expectedDeliveryDate ?? slaDeliveryDate(sentAt, agreementTerms),
      });
    }),

  /* ------------------------------------------------------- Quotations */
  listQuotations: (filter) =>
    simulateRead(() =>
      quotations
        .filter((q) => !filter?.leadId || q.leadId === filter.leadId)
        .filter((q) => !filter?.status || filter.status.includes(q.status))
        .sort((a, b) => b.createdAt.localeCompare(a.createdAt)),
    ),

  getQuotation: (id) => simulateRead(() => byId(quotations, id)),

  getQuotationForCustomer: (id) =>
    simulateRead(() => {
      const q = byId(quotations, id);
      if (!q) return null;
      const lead = resolveLead(q.leadId);
      const lapsed = !!q.validityDate && new Date(q.validityDate).getTime() < Date.now();
      const effectiveStatus = lapsed && (q.status === 'sent' || q.status === 'viewed') ? 'expired' : q.status;
      return {
        id: q.id,
        code: q.code,
        version: q.version,
        effectiveStatus,
        leadSiteName: lead?.siteName ?? '',
        driveType: q.driveType,
        capacityPersons: q.capacityPersons,
        finishTier: q.finishTier,
        stopsCount: q.stopsCount,
        finalPrice: q.cost.finalPrice,
        gstPercent: q.cost.gstPercent,
        validityDate: q.validityDate,
        sentAt: q.sentAt,
        viewedAt: q.viewedAt,
        acceptedAt: q.acceptedAt,
      };
    }),

  createQuotationDraft: (leadId) =>
    simulateWrite(() => {
      const lead = resolveLead(leadId);
      if (!lead) throw new RepositoryError('not_found');
      const spec = lead.spec;
      const stopsCount = spec ? spec.floors + spec.basements + 1 : 5;
      const driveType: DriveType = stopsCount > 10 ? 'gearless_traction' : spec?.machineRoom === 'mrl' ? 'mrl' : 'geared_traction';
      const finishTier: Quotation['finishTier'] =
        spec?.cabinFinish === 'glass' || spec?.cabinFinish === 'custom' ? 'luxury' : spec?.cabinFinish === 'premium_ss' ? 'premium' : 'standard';
      const specInput: QuotationSpecInput = {
        driveType,
        capacityPersons: spec?.capacityPersons ?? 6,
        capacityKg: spec?.capacityKg ?? 408,
        stopsCount,
        travelHeightM: Math.round(stopsCount * 3 * 10) / 10,
        finishTier,
        customConfiguration: false,
      };
      const cost = computeQuotationCost(specInput, pricingConfig);
      const now = new Date().toISOString();
      quotationCounter += 1;
      const quotation: Quotation = {
        id: `q-new-${quotationCounter}`,
        code: `AIEC-Q-${quotationCounter}`,
        leadId,
        version: 1,
        status: 'draft',
        ...specInput,
        needsSpecializedReview: stopsCount >= 20,
        cost,
        deliveryChannels: [],
        deliveryResults: [],
        createdBy: 'Sales',
        createdAt: now,
        isDemo: true,
      };
      quotations.unshift(quotation);
      pushTimelineEvent({ leadId, kind: 'quote_created', actorName: 'Sales', at: now, detail: `Quotation ${quotation.code} drafted` });
      return quotation;
    }),

  saveQuotationSpec: (id, patch) =>
    simulateWrite(() => {
      const existing = byId(quotations, id);
      if (!existing) throw new RepositoryError('not_found');
      const cost = computeQuotationCost(patch, pricingConfig, existing.cost.marginPct);
      return patchInPlace(quotations, id, {
        ...patch,
        needsSpecializedReview: patch.stopsCount >= 20,
        cost,
      });
    }),

  generateComparisonSet: (leadId, baseSpec, tiers) =>
    simulateWrite(() => {
      const lead = resolveLead(leadId);
      if (!lead) throw new RepositoryError('not_found');
      // Simple, explainable rule — never an opaque heuristic, since trust in
      // the recommendation matters for a premium brand.
      const commercialTypes = ['commercial_office', 'retail', 'industrial'];
      const recommended: Quotation['packageTier'] = lead.spec && commercialTypes.includes(lead.spec.buildingType) ? 'basic' : 'premium';
      const now = new Date().toISOString();
      const comparisonSetId = `cmp-${(quotationCounter += 1)}`;
      const created: Quotation[] = tiers.map((tier) => {
        const finishTier: Quotation['finishTier'] = tier === 'luxury' ? 'luxury' : tier === 'premium' ? 'premium' : 'standard';
        const specInput: QuotationSpecInput = { ...baseSpec, finishTier };
        const cost = computeQuotationCost(specInput, pricingConfig);
        quotationCounter += 1;
        const q: Quotation = {
          id: `q-new-${quotationCounter}`,
          code: `AIEC-Q-${quotationCounter}`,
          leadId,
          version: 1,
          status: 'draft',
          ...specInput,
          needsSpecializedReview: specInput.stopsCount >= 20,
          cost,
          comparisonSetId,
          packageTier: tier,
          recommended: tier === recommended,
          deliveryChannels: [],
          deliveryResults: [],
          createdBy: 'Sales',
          createdAt: now,
          isDemo: true,
        };
        quotations.unshift(q);
        return q;
      });
      pushTimelineEvent({ leadId, kind: 'quote_created', actorName: 'Sales', at: now, detail: `${created.length}-option comparison generated` });
      return created;
    }),

  createQuotationVersion: (supersedesId, patch, reason, createdBy) =>
    simulateWrite(() => {
      const prior = byId(quotations, supersedesId);
      if (!prior) throw new RepositoryError('not_found');
      const specInput: QuotationSpecInput = {
        driveType: patch.driveType ?? prior.driveType,
        capacityPersons: patch.capacityPersons ?? prior.capacityPersons,
        capacityKg: patch.capacityKg ?? prior.capacityKg,
        stopsCount: patch.stopsCount ?? prior.stopsCount,
        travelHeightM: patch.travelHeightM ?? prior.travelHeightM,
        finishTier: patch.finishTier ?? prior.finishTier,
        specOverrideNote: patch.specOverrideNote ?? prior.specOverrideNote,
        customConfiguration: patch.customConfiguration ?? prior.customConfiguration,
      };
      // Always recalculated against current rates — a restored old version
      // never quietly resends stale numbers.
      const cost = computeQuotationCost(specInput, pricingConfig, prior.cost.marginPct);
      const now = new Date().toISOString();
      quotationCounter += 1;
      const version: Quotation = {
        ...prior,
        id: `q-new-${quotationCounter}`,
        code: `AIEC-Q-${quotationCounter}`,
        version: prior.version + 1,
        supersedesQuotationId: prior.id,
        status: 'draft',
        ...specInput,
        needsSpecializedReview: specInput.stopsCount >= 20,
        cost,
        viewedAt: undefined,
        acceptedAt: undefined,
        sentAt: undefined,
        scheduledSendAt: undefined,
        deliveryResults: [],
        createdBy,
        createdAt: now,
        createdReasonKey: reason.key,
        createdReasonNote: reason.note,
      };
      quotations.unshift(version);
      // Only one version per lead can be active/sent at once. A prior version
      // with a scheduled send still pending is superseded right away too — a
      // customer must never receive a stale version just because the clock
      // hadn't reached the scheduled time yet.
      const hadPendingScheduledSend = Boolean(prior.scheduledSendAt) && !prior.sentAt;
      if (prior.status === 'sent' || prior.status === 'viewed' || hadPendingScheduledSend) {
        patchInPlace(quotations, prior.id, { status: 'superseded' as const, scheduledSendAt: undefined });
        if (hadPendingScheduledSend) {
          pushTimelineEvent({
            leadId: prior.leadId,
            kind: 'communication_failed',
            actorName: 'Automation',
            at: now,
            detail: `Scheduled send for ${prior.code} v${prior.version} cancelled automatically — superseded by v${version.version} before it went out`,
          });
        }
      }
      pushTimelineEvent({ leadId: prior.leadId, kind: 'quote_created', actorName: createdBy, at: now, detail: `Quotation ${version.code} v${version.version} — ${reason.key}` });
      return version;
    }),

  listQuotationVersions: (quotationId) =>
    simulateRead(() => {
      const target = byId(quotations, quotationId);
      if (!target) return [];
      let root = target;
      while (root.supersedesQuotationId) {
        const prior = byId(quotations, root.supersedesQuotationId);
        if (!prior) break;
        root = prior;
      }
      const chain: Quotation[] = [root];
      let current = root;
      for (;;) {
        const next = quotations.find((q) => q.supersedesQuotationId === current.id);
        if (!next) break;
        chain.push(next);
        current = next;
      }
      return chain;
    }),

  sendQuotation: (id, input) =>
    simulateWrite(() => {
      const quotation = byId(quotations, id);
      if (!quotation) throw new RepositoryError('not_found');
      if (quotation.status === 'superseded') throw new RepositoryError('quotation_superseded');

      const scheduledTimeMs = input.scheduledSendAt ? new Date(input.scheduledSendAt).getTime() : null;
      if (scheduledTimeMs !== null && scheduledTimeMs > Date.now()) {
        // Not due yet — persist the scheduling intent only. Nothing is
        // delivered and the lead's stage doesn't move until it actually sends.
        return patchInPlace(quotations, id, {
          deliveryChannels: input.channels,
          coverMessage: input.coverMessage,
          scheduledSendAt: input.scheduledSendAt,
        });
      }
      return executeQuotationSend(quotation, input.channels, input.coverMessage);
    }),

  cancelScheduledQuotationSend: (id) =>
    simulateWrite(() => {
      const quotation = byId(quotations, id);
      if (!quotation) throw new RepositoryError('not_found');
      if (!quotation.scheduledSendAt || quotation.sentAt) throw new RepositoryError('not_cancellable');
      const updated = patchInPlace(quotations, id, { scheduledSendAt: undefined });
      pushTimelineEvent({
        leadId: quotation.leadId,
        kind: 'communication_failed',
        actorName: 'Sales',
        at: new Date().toISOString(),
        detail: `Scheduled send for ${quotation.code} v${quotation.version} cancelled by the sales user`,
      });
      return updated;
    }),

  recordQuotationView: (id) =>
    simulateWrite(() => {
      const quotation = byId(quotations, id);
      if (!quotation) throw new RepositoryError('not_found');
      if (quotation.viewedAt) return quotation;
      return patchInPlace(quotations, id, { status: 'viewed' as const, viewedAt: new Date().toISOString() });
    }),

  acceptQuotation: (id) =>
    simulateWrite(() => {
      const quotation = byId(quotations, id);
      if (!quotation) throw new RepositoryError('not_found');
      if (quotation.validityDate && new Date(quotation.validityDate).getTime() < Date.now()) {
        throw new RepositoryError('quotation_expired');
      }
      return patchInPlace(quotations, id, { status: 'accepted' as const, acceptedAt: new Date().toISOString() });
    }),

  requestQuotationChanges: (id, note) =>
    simulateWrite(() => {
      const quotation = byId(quotations, id);
      if (!quotation) throw new RepositoryError('not_found');
      const updated = patchInPlace(quotations, id, { status: 'change_requested' as const });
      pushTimelineEvent({ leadId: quotation.leadId, kind: 'quote_change_requested', actorName: 'Customer', at: new Date().toISOString(), detail: note });
      return updated;
    }),

  adjustQuotationCost: (id, input) =>
    simulateWrite(() => {
      const quotation = byId(quotations, id);
      if (!quotation) throw new RepositoryError('not_found');
      const marginPct = input.marginPct ?? quotation.cost.marginPct;
      if (marginPct < pricingConfig.minimumMarginFloorPct) {
        throw new RepositoryError('below_margin_floor');
      }
      const { equipmentCost, installationLaborCost, transportCost, perFloorCostDelta } = quotation.cost;
      const civilWorkEstimate = input.civilWorkOverride?.amount ?? quotation.cost.civilWorkEstimate;
      const civilWorkAdjustmentNote = input.civilWorkOverride?.note ?? quotation.cost.civilWorkAdjustmentNote;
      const baseCost = equipmentCost + civilWorkEstimate + installationLaborCost + transportCost;
      const sellBeforeTax = Math.round(baseCost / (1 - marginPct / 100));
      const marginAmount = sellBeforeTax - baseCost;
      const gstRatePct = effectiveGstRatePct(pricingConfig);
      const gstAmount = Math.round(sellBeforeTax * (gstRatePct / 100));
      const cost: QuotationCostBreakdown = {
        equipmentCost,
        civilWorkEstimate,
        civilWorkAdjustmentNote,
        installationLaborCost,
        transportCost,
        perFloorCostDelta,
        gstPercent: gstRatePct,
        gstAmount,
        marginPct,
        marginAmount,
        finalPrice: sellBeforeTax + gstAmount,
      };
      return patchInPlace(quotations, id, { cost });
    }),

  /* -------------------------------------------------- Quotation templates */
  listQuotationTemplates: () => simulateRead(() => [...quotationTemplates]),

  saveQuotationTemplate: (template) =>
    simulateWrite(() => {
      if (template.id) {
        const existing = byId(quotationTemplates, template.id);
        if (!existing) throw new RepositoryError('not_found');
        // Edits bump the version — a quote already open with a customer
        // keeps whichever version it was sent with (templateVersionAtSend);
        // only new sends pick up the change.
        return patchInPlace(quotationTemplates, template.id, { ...template, version: existing.version + 1, updatedAt: new Date().toISOString() });
      }
      templateCounter += 1;
      const created: QuotationTemplate = {
        ...template,
        id: `qt-new-${templateCounter}`,
        version: 1,
        updatedAt: new Date().toISOString(),
        isDemo: true,
      };
      quotationTemplates.push(created);
      return created;
    }),

  /* ---------------------------------------------------- Discount approvals */
  listDiscountRequests: (filter) =>
    simulateRead(() =>
      discountRequests
        .filter((r) => !filter?.status || filter.status.includes(r.status))
        .sort((a, b) => b.createdAt.localeCompare(a.createdAt)),
    ),

  requestDiscount: (input) =>
    simulateWrite(() => {
      const quotation = byId(quotations, input.quotationId);
      if (!quotation) throw new RepositoryError('not_found');
      const baseCost = quotation.cost.equipmentCost + quotation.cost.civilWorkEstimate + quotation.cost.installationLaborCost + quotation.cost.transportCost;
      const sellBeforeTax = quotation.cost.finalPrice / (1 + quotation.cost.gstPercent / 100);
      const discountedSell = sellBeforeTax * (1 - input.requestedDiscountPct / 100);
      const resultingMarginPct = discountedSell > 0 ? Math.round(((discountedSell - baseCost) / discountedSell) * 1000) / 10 : 0;
      const priorRejected = discountRequests
        .filter((r) => r.quotationId === input.quotationId && r.requestedByUserId === input.requestedByUserId && r.status === 'rejected')
        .sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0];
      discountRequestCounter += 1;
      // Urgent AND safely inside the buffer above the hard floor: approved
      // immediately rather than left waiting on an Admin who might be
      // offline right when the customer is on the phone.
      const autoApprove = input.urgent && resultingMarginPct >= pricingConfig.minimumMarginFloorPct + URGENT_AUTO_APPROVE_BUFFER_PCT;
      const now = new Date().toISOString();
      const request: DiscountRequest = {
        id: `dr-new-${discountRequestCounter}`,
        quotationId: input.quotationId,
        leadId: quotation.leadId,
        requestedByUserId: input.requestedByUserId,
        requestedDiscountPct: input.requestedDiscountPct,
        reasonNote: input.reasonNote,
        resultingMarginPct,
        urgent: input.urgent,
        status: autoApprove ? 'approved' : 'pending',
        approverId: autoApprove ? 'system-auto' : undefined,
        decidedAt: autoApprove ? now : undefined,
        resubmissionOfId: priorRejected?.id,
        createdAt: now,
        isDemo: true,
      };
      discountRequests.unshift(request);
      if (autoApprove) applyApprovedDiscount(request, 'system-auto', 'quotation.reason.discountApproved');
      return request;
    }),

  decideDiscountRequest: (id, decision) =>
    simulateWrite(() => {
      const request = byId(discountRequests, id);
      if (!request) throw new RepositoryError('not_found');
      const updated = patchInPlace(discountRequests, id, {
        status: decision.status,
        approverId: decision.approverId,
        decidedAt: new Date().toISOString(),
        rejectionReason: decision.rejectionReason,
        counterSuggestionPct: decision.counterSuggestionPct,
      });
      if (decision.status === 'approved') applyApprovedDiscount(request, decision.approverId, 'quotation.reason.discountApproved');
      return updated;
    }),

  /* ---------------------------------------------------- Pricing configuration */
  getPricingConfig: () => simulateRead(() => ({ ...pricingConfig })),

  updatePricingConfig: (patch) =>
    simulateWrite(() => {
      if (patch.minimumMarginFloorPct !== undefined && patch.minimumMarginFloorPct <= 0) {
        throw new RepositoryError('margin_floor_must_be_positive');
      }
      if (patch.driveTypeBasePrice && Object.values(patch.driveTypeBasePrice).some((v) => v <= 0)) {
        throw new RepositoryError('base_price_must_be_positive');
      }
      if (patch.perFloorIncrementPct && Object.values(patch.perFloorIncrementPct).some((v) => v < 0)) {
        throw new RepositoryError('per_floor_increment_must_be_non_negative');
      }
      pricingConfig = { ...pricingConfig, ...patch, updatedAt: new Date().toISOString() };
      return { ...pricingConfig };
    }),

  /* -------------------------------------------------------- Quotation analytics */
  getQuotationAnalytics: (filter) =>
    simulateRead(() => {
      const segment = filter?.segment;
      // Excludes 'draft' (never sent) and 'superseded' (an older version of a
      // chain whose current version is counted instead) — one row per real
      // decision, never a lead's whole version history double-counted.
      const sentOrLater = quotations
        .filter((q) => q.status !== 'draft' && q.status !== 'superseded')
        .filter((q) => !segment || buildingSegmentOf(resolveLead(q.leadId)) === segment);
      const byTier = new Map<string, Quotation[]>();
      const byDrive = new Map<string, Quotation[]>();
      const byBand = new Map<string, Quotation[]>();
      const byTerritory = new Map<string, Quotation[]>();
      for (const q of sentOrLater) {
        const lead = resolveLead(q.leadId);
        pushToMap(byTier, q.packageTier ?? 'standard', q);
        pushToMap(byDrive, q.driveType, q);
        pushToMap(byBand, priceBandOf(q.cost.finalPrice), q);
        pushToMap(byTerritory, lead?.city ?? 'unknown', q);
      }

      const wonDecisionDays: number[] = [];
      const lostDecisionDays: number[] = [];
      for (const q of sentOrLater) {
        const lead = resolveLead(q.leadId);
        if (!lead || !q.sentAt) continue;
        if (lead.stage !== 'won' && lead.stage !== 'lost') continue;
        const days = (new Date(lead.stageEnteredAt).getTime() - new Date(q.sentAt).getTime()) / 86_400_000;
        if (days < 0) continue;
        (lead.stage === 'won' ? wonDecisionDays : lostDecisionDays).push(days);
      }
      const average = (values: number[]) => (values.length ? values.reduce((s, d) => s + d, 0) / values.length : 0);
      const avgDecisionDaysWon = average(wonDecisionDays);
      const avgDecisionDaysLost = average(lostDecisionDays);
      const avgDecisionDays = average([...wonDecisionDays, ...lostDecisionDays]);

      const lostLeads = leads.filter(
        (l) => l.stage === 'lost' && quotations.some((q) => q.leadId === l.id) && (!segment || buildingSegmentOf(l) === segment),
      );
      const lossFactorLeadIds = new Map<string, string[]>();
      for (const l of lostLeads) {
        const key = l.lostReason ?? 'unknown';
        const ids = lossFactorLeadIds.get(key);
        if (ids) ids.push(l.id);
        else lossFactorLeadIds.set(key, [l.id]);
      }
      const commonLossFactors = [...lossFactorLeadIds.entries()]
        .map(([reasonKey, leadIds]) => ({ reasonKey, count: leadIds.length, leadIds }))
        .sort((a, b) => b.count - a.count);

      return {
        byPackageTier: [...byTier.entries()].map(([k, g]) => winLossStat(k, g)),
        byDriveType: [...byDrive.entries()].map(([k, g]) => winLossStat(k, g)),
        byPriceBand: PRICE_BANDS.map((b) => winLossStat(b.key, byBand.get(b.key) ?? [])).filter((s) => s.quotesCount > 0),
        byTerritory: [...byTerritory.entries()].map(([k, g]) => winLossStat(k, g)),
        avgDecisionDays: Math.round(avgDecisionDays * 10) / 10,
        avgDecisionDaysWon: Math.round(avgDecisionDaysWon * 10) / 10,
        avgDecisionDaysLost: Math.round(avgDecisionDaysLost * 10) / 10,
        commonLossFactors,
      };
    }),

  /* -------------------------------------------------------- Auto-negotiation */
  getNegotiationBotConfig: () => simulateRead(() => ({ ...negotiationBotConfig })),

  updateNegotiationBotConfig: (patch) =>
    simulateWrite(() => {
      if (patch.marginBufferPct !== undefined && patch.marginBufferPct < 0) {
        throw new RepositoryError('margin_buffer_must_be_non_negative');
      }
      if (patch.maxNegotiationRounds !== undefined && patch.maxNegotiationRounds < 1) {
        throw new RepositoryError('max_rounds_must_be_at_least_one');
      }
      negotiationBotConfig = { ...negotiationBotConfig, ...patch, updatedAt: new Date().toISOString() };
      return { ...negotiationBotConfig };
    }),

  listActiveNegotiations: () =>
    simulateRead(() =>
      negotiations
        .filter((n) => n.status !== 'closed_won' && n.status !== 'closed_lost')
        .sort((a, b) => b.lastActivityAt.localeCompare(a.lastActivityAt)),
    ),

  takeOverNegotiation: (id, byUserId) =>
    simulateWrite(() => {
      const negotiation = byId(negotiations, id);
      if (!negotiation) throw new RepositoryError('not_found');
      if (negotiation.status === 'closed_won' || negotiation.status === 'closed_lost') {
        throw new RepositoryError('negotiation_already_closed');
      }
      return patchInPlace(negotiations, id, {
        status: 'human_takeover' as const,
        takenOverBy: byUserId,
        takenOverAt: new Date().toISOString(),
        lastEscalationReason: negotiation.lastEscalationReason ?? 'manual_takeover',
        lastActivityAt: new Date().toISOString(),
      });
    }),

  getNegotiationThread: (negotiationId) =>
    simulateRead(() => {
      const negotiation = byId(negotiations, negotiationId);
      if (!negotiation) return null;
      const deal = byId(deals, negotiation.dealId);
      const lead = resolveLead(negotiation.leadId);
      if (!deal || !lead) return null;
      const conversation = conversations.find((c) => c.leadId === negotiation.leadId) ?? null;
      const messages = conversation
        ? commMessages.filter((m) => m.conversationId === conversation.id).sort((a, b) => a.at.localeCompare(b.at))
        : [];
      return { negotiation, deal, lead, conversationId: conversation?.id ?? null, messages };
    }),

  sendNegotiationMessage: (negotiationId, body, agentName) =>
    simulateWrite(() => {
      const negotiation = byId(negotiations, negotiationId);
      if (!negotiation) throw new RepositoryError('not_found');
      if (negotiation.status !== 'human_takeover') throw new RepositoryError('must_take_over_first');
      let conversation = conversations.find((c) => c.leadId === negotiation.leadId) ?? null;
      const now = new Date().toISOString();
      if (!conversation) {
        conversation = { id: `conv-new-${(conversationCounter += 1)}`, leadId: negotiation.leadId, lastMessageAt: now, isDemo: true };
        conversations.push(conversation);
      }
      const message: CommMessage = {
        id: `cm-new-${(messageCounter += 1)}`,
        conversationId: conversation.id,
        channel: 'whatsapp',
        sender: 'agent',
        senderName: agentName,
        body,
        status: 'sent',
        at: now,
        handled: true,
      };
      commMessages.push(message);
      patchInPlace(conversations, conversation.id, { lastMessageAt: now });
      patchInPlace(negotiations, negotiationId, { lastActivityAt: now });
      return message;
    }),

  listCounterOfferQueue: () =>
    simulateRead(() => {
      const pending = [...counterOffers].filter((o) => o.status === 'pending').sort((a, b) => a.createdAt.localeCompare(b.createdAt));
      // Multiple pending asks from the same customer collapse into their
      // latest — the rest count toward `priorAskCount` rather than showing
      // as separate, confusing rows.
      const latestByLead = new Map<string, CounterOffer>();
      const priorCounts = new Map<string, number>();
      for (const offer of pending) {
        const current = latestByLead.get(offer.leadId);
        if (!current || offer.createdAt > current.createdAt) {
          if (current) priorCounts.set(offer.leadId, (priorCounts.get(offer.leadId) ?? 0) + 1);
          latestByLead.set(offer.leadId, offer);
        } else {
          priorCounts.set(offer.leadId, (priorCounts.get(offer.leadId) ?? 0) + 1);
        }
      }
      return Array.from(latestByLead.values())
        .map((offer) => {
          const lead = resolveLead(offer.leadId);
          const deal = byId(deals, offer.dealId);
          if (!lead || !deal) return null;
          return { ...offer, lead, deal, priorAskCount: priorCounts.get(offer.leadId) ?? 0 };
        })
        .filter((item): item is CounterOfferQueueItem => item !== null)
        .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
    }),

  decideCounterOffer: (id, decision) =>
    simulateWrite(() => {
      const offer = byId(counterOffers, id);
      if (!offer) throw new RepositoryError('not_found');
      if (offer.status !== 'pending') throw new RepositoryError('already_decided');
      // The customer's own ask was already vetted against the company floor
      // when it reached this queue; an Admin's own counter-number is new
      // input and gets the same "never below the true floor" check.
      if (decision.status === 'countered' && decision.counterPriceOffered !== undefined) {
        const quotation = currentQuotationForLead(offer.leadId);
        if (quotation) {
          const baseCost = quotation.cost.equipmentCost + quotation.cost.civilWorkEstimate + quotation.cost.installationLaborCost + quotation.cost.transportCost;
          const sellBeforeTax = decision.counterPriceOffered / (1 + quotation.cost.gstPercent / 100);
          const marginPct = sellBeforeTax > 0 ? ((sellBeforeTax - baseCost) / sellBeforeTax) * 100 : 0;
          if (marginPct < pricingConfig.minimumMarginFloorPct) throw new RepositoryError('counter_below_company_floor');
        }
      }
      const now = new Date().toISOString();
      const updated = patchInPlace(counterOffers, id, {
        status: decision.status,
        approverId: decision.approverId,
        decidedAt: now,
        rejectionReason: decision.rejectionReason,
        counterPriceOffered: decision.counterPriceOffered,
      });
      // Any other still-pending ask from the same customer is resolved by
      // this same decision — one governed decision per customer, never a
      // stray duplicate left open once the consolidated item is settled.
      for (const other of counterOffers) {
        if (other.id !== id && other.leadId === offer.leadId && other.status === 'pending') {
          patchInPlace(counterOffers, other.id, { status: 'superseded' as const });
        }
      }
      const negotiation = byId(negotiations, offer.negotiationId);
      if (negotiation) {
        const resolvedPrice =
          decision.status === 'approved'
            ? offer.customerRequestedPrice
            : decision.status === 'countered'
              ? decision.counterPriceOffered ?? negotiation.currentOfferPrice
              : negotiation.currentOfferPrice;
        patchInPlace(negotiations, negotiation.id, { currentOfferPrice: resolvedPrice, lastActivityAt: now });
        // The bot only speaks for itself while it still owns the
        // conversation — once a human has taken over (or it's closed), the
        // record updates silently and whoever is talking reads it live.
        if (negotiation.status === 'bot_active' || negotiation.status === 'escalated') {
          const conversation = conversations.find((c) => c.leadId === negotiation.leadId);
          if (conversation) {
            const bodyText =
              decision.status === 'approved'
                ? `We're able to offer ${formatINRCompact(offer.customerRequestedPrice)}${offer.bundledConcessionNote ? ', including what you asked for' : ''} — let's move ahead.`
                : decision.status === 'countered'
                  ? `We can offer ${formatINRCompact(decision.counterPriceOffered ?? negotiation.currentOfferPrice)} instead — let us know if that works for you.`
                  : `We're not able to go that low, but we'd love to move ahead at ${formatINRCompact(negotiation.currentOfferPrice)}.`;
            commMessages.push({
              id: `cm-new-${(messageCounter += 1)}`,
              conversationId: conversation.id,
              channel: 'whatsapp',
              sender: 'bot',
              body: bodyText,
              status: 'sent',
              at: now,
            });
            patchInPlace(conversations, conversation.id, { lastMessageAt: now });
          }
        }
      }
      return updated;
    }),

  getDealTerms: (dealId) =>
    simulateRead(() => {
      const deal = byId(deals, dealId);
      if (!deal) return null;
      const lead = resolveLead(deal.leadId);
      if (!lead) return null;
      const terms = dealTermsRecords.find((t) => t.dealId === dealId) ?? null;
      const quotation = currentQuotationForLead(deal.leadId);
      const negotiation = negotiations.find((n) => n.dealId === dealId);
      const view: DealTermsView = {
        terms,
        deal,
        lead,
        defaultFinalPrice: deal.agreedPrice || deal.quotedPrice,
        currentQuotationId: quotation?.id ?? null,
        negotiationId: negotiation?.id ?? null,
      };
      return view;
    }),

  saveDealTermsDraft: (dealId, patch) =>
    simulateWrite(() => {
      const deal = byId(deals, dealId);
      if (!deal) throw new RepositoryError('not_found');
      const existing = dealTermsRecords.find((t) => t.dealId === dealId);
      if (existing && existing.status !== 'draft') throw new RepositoryError('cannot_edit_after_confirmation');
      const now = new Date().toISOString();
      if (existing) {
        return patchInPlace(dealTermsRecords, existing.id, {
          paymentStagePlan: patch.paymentStagePlan,
          specialTermsNotes: patch.specialTermsNotes,
          updatedAt: now,
        });
      }
      dealTermsCounter += 1;
      const created: DealTerms = {
        id: `dt-new-${dealTermsCounter}`,
        dealId,
        finalAgreedPrice: deal.agreedPrice || deal.quotedPrice,
        paymentStagePlan: patch.paymentStagePlan,
        specialTermsNotes: patch.specialTermsNotes,
        status: 'draft',
        bothPartyConfirmedFlag: false,
        amendments: [],
        createdAt: now,
        updatedAt: now,
        isDemo: true,
      };
      dealTermsRecords.push(created);
      return created;
    }),

  confirmDealTermsInternal: (dealId, byUserId) =>
    simulateWrite(() => {
      const terms = dealTermsRecords.find((t) => t.dealId === dealId);
      if (!terms) throw new RepositoryError('not_found');
      if (terms.status !== 'draft') throw new RepositoryError('already_confirmed');
      // 'retention' is an additional holdback on top of the price, never
      // part of the 100% the other stages must account for.
      const corePct = terms.paymentStagePlan.filter((s) => s.stage !== 'retention').reduce((sum, s) => sum + s.percentage, 0);
      if (Math.abs(corePct - 100) > 0.01) throw new RepositoryError('payment_stages_must_total_100');
      return patchInPlace(dealTermsRecords, terms.id, {
        status: 'awaiting_customer' as const,
        internalConfirmedBy: byUserId,
        internalConfirmedAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      });
    }),

  confirmDealTermsCustomer: (dealId) =>
    simulateWrite(() => {
      const terms = dealTermsRecords.find((t) => t.dealId === dealId);
      if (!terms) throw new RepositoryError('not_found');
      if (terms.status !== 'awaiting_customer') throw new RepositoryError('not_awaiting_customer');
      const now = new Date().toISOString();
      return patchInPlace(dealTermsRecords, terms.id, {
        status: 'confirmed' as const,
        customerConfirmedAt: now,
        bothPartyConfirmedFlag: true,
        updatedAt: now,
      });
    }),

  amendDealTerms: (dealId, note, byUserId) =>
    simulateWrite(() => {
      const terms = dealTermsRecords.find((t) => t.dealId === dealId);
      if (!terms) throw new RepositoryError('not_found');
      if (terms.status !== 'confirmed') throw new RepositoryError('not_confirmed_yet');
      dealTermsAmendmentCounter += 1;
      const now = new Date().toISOString();
      return patchInPlace(dealTermsRecords, terms.id, {
        amendments: [...terms.amendments, { id: `dta-new-${dealTermsAmendmentCounter}`, note, amendedBy: byUserId, amendedAt: now }],
        updatedAt: now,
      });
    }),

  getContract: (dealId) =>
    simulateRead(() => {
      const deal = byId(deals, dealId);
      if (!deal) return null;
      const lead = resolveLead(deal.leadId);
      if (!lead) return null;
      const dealTerms = dealTermsRecords.find((t) => t.dealId === dealId) ?? null;
      const dealContracts = contracts.filter((c) => c.dealId === dealId).sort((a, b) => a.version - b.version);
      const contract = dealContracts.find((c) => c.status === 'active') ?? null;
      const priorVersions = dealContracts.filter((c) => c.status === 'superseded');
      const view: ContractView = {
        contract,
        priorVersions,
        deal,
        lead,
        dealTerms,
        canGenerate: dealTerms?.bothPartyConfirmedFlag === true,
      };
      return view;
    }),

  generateContract: (dealId, byUserId) =>
    simulateWrite(() => {
      const deal = byId(deals, dealId);
      if (!deal) throw new RepositoryError('not_found');
      const lead = resolveLead(deal.leadId);
      if (!lead) throw new RepositoryError('not_found');
      const dealTerms = dealTermsRecords.find((t) => t.dealId === dealId);
      if (!dealTerms || !dealTerms.bothPartyConfirmedFlag) throw new RepositoryError('deal_terms_not_confirmed');

      const quotation = currentQuotationForLead(lead.id);
      const template = quotation ? selectActiveQuotationTemplate(quotation, lead) : undefined;
      const { clauses, usedStateClauseFallback } = buildContractClauses(lead, dealTerms, quotation, template);

      const current = contracts.filter((c) => c.dealId === dealId).sort((a, b) => b.version - a.version)[0];
      if (current && current.status === 'active') {
        patchInPlace(contracts, current.id, { status: 'superseded' as const });
      }

      contractCounter += 1;
      const created: Contract = {
        id: `ct-new-${contractCounter}`,
        dealId,
        version: (current?.version ?? 0) + 1,
        supersedesContractId: current?.id,
        status: 'active',
        clauses,
        usedStateClauseFallback,
        addenda: [],
        generatedAt: new Date().toISOString(),
        generatedBy: byUserId,
        isDemo: true,
      };
      contracts.push(created);
      return created;
    }),

  addContractAddendum: (contractId, note, byUserId) =>
    simulateWrite(() => {
      const contract = byId(contracts, contractId);
      if (!contract) throw new RepositoryError('not_found');
      const now = new Date().toISOString();
      return patchInPlace(contracts, contractId, {
        addenda: [...contract.addenda, { id: `cta-new-${(contractAddendumCounter += 1)}`, note, addedBy: byUserId, addedAt: now }],
      });
    }),

  getSignature: (dealId) =>
    simulateRead(() => {
      const deal = byId(deals, dealId);
      if (!deal) return null;
      const lead = resolveLead(deal.leadId);
      if (!lead) return null;
      const contract = contracts.find((c) => c.dealId === dealId && c.status === 'active') ?? null;
      const signature = contractSignatures.find((s) => s.dealId === dealId) ?? null;
      const view: SignatureView = { signature, contract, deal, lead, canSign: contract !== null };
      return view;
    }),

  recordCustomerSignature: (dealId, signature) =>
    simulateWrite(() => {
      const deal = byId(deals, dealId);
      if (!deal) throw new RepositoryError('not_found');
      const contract = contracts.find((c) => c.dealId === dealId && c.status === 'active');
      if (!contract) throw new RepositoryError('no_active_contract');
      const existing = contractSignatures.find((s) => s.dealId === dealId);
      const now = new Date().toISOString();
      const patch = {
        status: 'customer_signed' as const,
        customerSignatureMethod: signature.method,
        customerSignatureData: signature.data,
        customerConsentGiven: signature.consentGiven,
        customerOtpVerified: true,
        customerSignedAt: now,
      };
      const record = existing
        ? patchInPlace(contractSignatures, existing.id, patch)
        : (() => {
            contractSignatureCounter += 1;
            const created: ContractSignature = { id: `cs-new-${contractSignatureCounter}`, contractId: contract.id, dealId, isDemo: true, ...patch };
            contractSignatures.push(created);
            return created;
          })();
      // Mutual agreement now has a signed instrument on one side — visible
      // downstream, but not yet the moment the deal is won.
      patchInPlace(deals, dealId, { status: 'approved' as const });
      return record;
    }),

  recordAiecCountersignature: (dealId, byUserId) =>
    simulateWrite(() => {
      const record = contractSignatures.find((s) => s.dealId === dealId);
      if (!record) throw new RepositoryError('not_found');
      if (record.status !== 'customer_signed') throw new RepositoryError('customer_has_not_signed_yet');
      const now = new Date().toISOString();
      const updated = patchInPlace(contractSignatures, record.id, {
        status: 'fully_signed' as const,
        aiecCountersignedBy: byUserId,
        aiecCountersignedAt: now,
      });
      // The one moment this deal becomes formally, legally Closed Won.
      patchInPlace(deals, dealId, { status: 'won' as const, closedAt: now });
      return updated;
    }),

  getDealClosure: (dealId) =>
    simulateRead(() => {
      const deal = byId(deals, dealId);
      if (!deal) return null;
      const lead = resolveLead(deal.leadId);
      if (!lead) return null;
      const dealTerms = dealTermsRecords.find((t) => t.dealId === dealId) ?? null;
      const closure = dealClosures.find((c) => c.dealId === dealId) ?? null;
      const paymentRecords = closure
        ? closure.paymentRecordIds.map((id) => byId(payments, id)).filter((p): p is Payment => p !== null)
        : [];
      const supplierPo = closure?.supplierPoId ? byId(supplierPurchaseOrders, closure.supplierPoId) : null;
      const view: DealClosureView = { closure, deal, lead, dealTerms, paymentRecords, supplierPo, eligibleToClose: deal.status === 'won' };
      return view;
    }),

  triggerDealClosure: (dealId) =>
    simulateWrite(() => {
      const deal = byId(deals, dealId);
      if (!deal) throw new RepositoryError('not_found');
      const existing = dealClosures.find((c) => c.dealId === dealId);
      if (existing) return existing;
      if (deal.status !== 'won') throw new RepositoryError('deal_not_fully_signed');
      const lead = resolveLead(deal.leadId);
      if (!lead) throw new RepositoryError('not_found');
      const dealTerms = dealTermsRecords.find((t) => t.dealId === dealId);

      // Auto-transitions the CRM pipeline stage as part of this same event.
      if (lead.stage !== 'won') {
        patchInPlace(leads, lead.id, { stage: 'won' as const, stageEnteredAt: deal.closedAt ?? new Date().toISOString() });
      }

      const paymentRecordIds = createDealPaymentSchedule(deal, dealTerms);
      const commissionId = createOrReuseLeadConvertedCommission(deal, lead);
      const po = triggerSupplierPo(deal);

      dealClosureCounter += 1;
      const created: DealClosure = {
        id: `dc-new-${dealClosureCounter}`,
        dealId,
        closedAt: deal.closedAt ?? new Date().toISOString(),
        paymentRecordIds,
        supplierPoId: po.id,
        supplierPoFailed: po.failed,
        commissionEntryIds: [commissionId],
        voided: false,
        isDemo: true,
      };
      dealClosures.push(created);
      return created;
    }),

  voidDealClosure: (dealId, reason, byUserId) =>
    simulateWrite(() => {
      const closure = dealClosures.find((c) => c.dealId === dealId);
      if (!closure) throw new RepositoryError('not_found');
      if (closure.voided) throw new RepositoryError('already_voided');
      return patchInPlace(dealClosures, closure.id, {
        voided: true,
        voidReason: reason,
        voidedBy: byUserId,
        voidedAt: new Date().toISOString(),
      });
    }),

  /* ---------------------------------------- Objection/concern script library */
  listObjectionScripts: () => simulateRead(() => objectionScripts.map(buildObjectionScriptListItem)),

  createObjectionScript: (input) =>
    simulateWrite(() => {
      objectionScriptCounter += 1;
      const now = new Date().toISOString();
      const created: ObjectionScript = {
        id: `objs-new-${objectionScriptCounter}`,
        code: `AIEC-OBJ-${objectionScriptCounter}`,
        category: input.category,
        responseText: input.responseText,
        citedStandards: input.citedStandards,
        status: 'suggested',
        sourceNote: input.sourceNote,
        versions: [{ version: 1, responseText: input.responseText, editedBy: input.createdBy, editedAt: now }],
        updatedAt: now,
        updatedBy: input.createdBy,
        isDemo: true,
      };
      objectionScripts.push(created);
      return created;
    }),

  saveObjectionScriptResponse: (id, responseText, editedBy) =>
    simulateWrite(() => {
      const script = byId(objectionScripts, id);
      if (!script) throw new RepositoryError('not_found');
      const now = new Date().toISOString();
      const nextVersion = (script.versions.at(-1)?.version ?? 0) + 1;
      return patchInPlace(objectionScripts, id, {
        responseText,
        updatedAt: now,
        updatedBy: editedBy,
        versions: [...script.versions, { version: nextVersion, responseText, editedBy, editedAt: now }],
      });
    }),

  setObjectionScriptStatus: (id, status) => simulateWrite(() => patchInPlace(objectionScripts, id, { status })),

  /* -------------------------------------------- Competitor battlecards */
  listCompetitors: () => simulateRead(() => [...competitors].sort((a, b) => a.name.localeCompare(b.name))),

  createCompetitor: (input) =>
    simulateWrite(() => {
      competitorCounter += 1;
      const now = new Date().toISOString();
      const created: Competitor = {
        id: `comp-new-${competitorCounter}`,
        code: `AIEC-CMP-${competitorCounter}`,
        name: input.name,
        pricePosition: input.pricePosition,
        priceSummary: input.priceSummary,
        strengths: input.strengths,
        differentiationPoints: input.differentiationPoints,
        internalOnlyFlag: true,
        flaggedForReview: false,
        versions: [
          {
            version: 1,
            priceSummary: input.priceSummary,
            strengths: input.strengths,
            differentiationPoints: input.differentiationPoints,
            editedBy: input.createdBy,
            editedAt: now,
          },
        ],
        lastReviewedAt: now,
        lastReviewedBy: input.createdBy,
        isDemo: true,
      };
      competitors.push(created);
      return created;
    }),

  updateCompetitorPositioning: (id, changes, editedBy) =>
    simulateWrite(() => {
      const competitor = byId(competitors, id);
      if (!competitor) throw new RepositoryError('not_found');
      const now = new Date().toISOString();
      const nextVersion = (competitor.versions.at(-1)?.version ?? 0) + 1;
      return patchInPlace(competitors, id, {
        ...changes,
        flaggedForReview: false,
        flagReason: undefined,
        flaggedBy: undefined,
        flaggedAt: undefined,
        lastReviewedAt: now,
        lastReviewedBy: editedBy,
        versions: [...competitor.versions, { version: nextVersion, ...changes, editedBy, editedAt: now }],
      });
    }),

  flagCompetitorForReview: (id, reason, byName) =>
    simulateWrite(() => {
      const competitor = byId(competitors, id);
      if (!competitor) throw new RepositoryError('not_found');
      return patchInPlace(competitors, id, {
        flaggedForReview: true,
        flagReason: reason,
        flaggedBy: byName,
        flaggedAt: new Date().toISOString(),
      });
    }),

  /* -------------------------------------------------- Won-deal celebration */
  getDealCelebration: (dealId, viewerRole) =>
    simulateRead(() => {
      const deal = byId(deals, dealId);
      if (!deal) return null;
      const lead = resolveLead(deal.leadId);
      if (!lead) return null;
      const celebration = dealCelebrations.find((c) => c.dealId === dealId) ?? null;
      const visible = celebration && viewerRole !== 'admin' ? { ...celebration, feedbackNote: undefined } : celebration;
      return {
        celebration: visible,
        deal,
        lead,
        staffSummaries: buildDealCelebrationStaffSummaries(lead, deal),
        eligible: deal.status === 'won',
      };
    }),

  triggerDealCelebration: (dealId) =>
    simulateWrite(() => {
      const existing = dealCelebrations.find((c) => c.dealId === dealId);
      if (existing) return existing;
      const deal = byId(deals, dealId);
      if (!deal) throw new RepositoryError('not_found');
      if (deal.status !== 'won') throw new RepositoryError('deal_not_fully_signed');
      dealCelebrationCounter += 1;
      const created: DealCelebration = {
        id: `dcel-new-${dealCelebrationCounter}`,
        dealId,
        acknowledged: false,
        createdAt: new Date().toISOString(),
        isDemo: true,
      };
      dealCelebrations.push(created);
      return created;
    }),

  acknowledgeDealCelebration: (dealId, byUserId, feedbackNote) =>
    simulateWrite(() => {
      const celebration = dealCelebrations.find((c) => c.dealId === dealId);
      if (!celebration) throw new RepositoryError('not_found');
      return patchInPlace(dealCelebrations, celebration.id, {
        acknowledged: true,
        acknowledgedBy: byUserId,
        acknowledgedAt: new Date().toISOString(),
        feedbackNote: feedbackNote ?? celebration.feedbackNote,
      });
    }),

  /* -------------------------------------------- Payment schedule setup */
  getPaymentSchedule: (dealId) =>
    simulateRead(() => {
      const deal = byId(deals, dealId);
      if (!deal) return null;
      const lead = resolveLead(deal.leadId);
      if (!lead) return null;
      const dealTerms = dealTermsRecords.find((t) => t.dealId === dealId) ?? null;
      const schedule = paymentSchedules.find((s) => s.dealId === dealId) ?? null;
      const dealValue = deal.agreedPrice || deal.quotedPrice;
      const expectedTotal = expectedPaymentScheduleTotal(dealValue, dealTerms);
      const resolvedStages = schedule ? resolvePaymentScheduleStages(dealId, schedule.stages) : [];
      const reconciledAmount = schedule ? schedule.stages.reduce((sum, s) => sum + s.amount, 0) : 0;
      return {
        schedule,
        resolvedStages,
        deal,
        lead,
        dealTerms,
        dealValue,
        expectedTotal,
        reconciledAmount,
        reconciles: schedule !== null && reconciledAmount === expectedTotal,
        canSetUp: dealTerms?.status === 'confirmed',
      };
    }),

  savePaymentSchedule: (dealId, input, editedBy) =>
    simulateWrite(() => {
      const deal = byId(deals, dealId);
      if (!deal) throw new RepositoryError('not_found');
      const now = new Date().toISOString();
      const stages: PaymentScheduleStage[] = input.stages.map((s) => {
        paymentScheduleStageCounter += 1;
        return { ...s, id: `pss-new-${paymentScheduleStageCounter}`, isDemo: true };
      });
      const existing = paymentSchedules.find((s) => s.dealId === dealId);
      if (existing) {
        return patchInPlace(paymentSchedules, existing.id, {
          scheduleType: input.scheduleType,
          customNote: input.customNote,
          stages,
          // Any further edit reopens the schedule for review.
          activated: false,
          activatedAt: undefined,
          activatedBy: undefined,
          updatedAt: now,
          updatedBy: editedBy,
        });
      }
      paymentScheduleCounter += 1;
      const created: PaymentSchedule = {
        id: `psch-new-${paymentScheduleCounter}`,
        dealId,
        scheduleType: input.scheduleType,
        customNote: input.customNote,
        stages,
        activated: false,
        updatedAt: now,
        updatedBy: editedBy,
        isDemo: true,
      };
      paymentSchedules.push(created);
      return created;
    }),

  activatePaymentSchedule: (dealId, byName) =>
    simulateWrite(() => {
      const deal = byId(deals, dealId);
      if (!deal) throw new RepositoryError('not_found');
      const schedule = paymentSchedules.find((s) => s.dealId === dealId);
      if (!schedule) throw new RepositoryError('not_found');
      const dealTerms = dealTermsRecords.find((t) => t.dealId === dealId) ?? null;
      const dealValue = deal.agreedPrice || deal.quotedPrice;
      const expectedTotal = expectedPaymentScheduleTotal(dealValue, dealTerms);
      const reconciledAmount = schedule.stages.reduce((sum, s) => sum + s.amount, 0);
      if (reconciledAmount !== expectedTotal) throw new RepositoryError('schedule_does_not_reconcile');
      return patchInPlace(paymentSchedules, schedule.id, {
        activated: true,
        activatedAt: new Date().toISOString(),
        activatedBy: byName,
      });
    }),

  /* -------------------------------------------------------- Operations */
  listActivity: (limit = 50) =>
    simulateRead(() =>
      [...activity].sort((a, b) => b.at.localeCompare(a.at)).slice(0, limit),
    ),

  listAlerts: (filter) =>
    simulateRead(() => {
      const order: Record<Alert['severity'], number> = { critical: 0, high: 1, medium: 2, low: 3 };
      return alerts
        .filter((a) => !filter?.status || filter.status.includes(a.status))
        .filter((a) => !filter?.severity || filter.severity.includes(a.severity))
        .sort((a, b) => order[a.severity] - order[b.severity] || b.raisedAt.localeCompare(a.raisedAt));
    }),

  acknowledgeAlert: (id, byUserId) =>
    simulateWrite(() =>
      patchInPlace(alerts, id, { status: 'acknowledged', acknowledgedBy: byUserId }),
    ),

  resolveAlert: (id, byUserId, note) =>
    simulateWrite(() => {
      const alert = byId(alerts, id);
      if (!alert) throw new RepositoryError('not_found');
      if (!note.trim()) throw new RepositoryError('reason_required');
      return patchInPlace(alerts, id, {
        status: 'resolved',
        acknowledgedBy: alert.acknowledgedBy ?? byUserId,
        resolvedBy: byUserId,
        resolvedAt: new Date().toISOString(),
        resolutionNote: note.trim(),
      });
    }),

  /* ------------------------------- Supplier rating & quality scorecard (097) */
  getSupplierScorecard: (supplierId, byUserId) =>
    simulateRead((): SupplierScorecard | null => {
      const actor = catalogActor(byUserId);
      const supplier = byId(suppliers, supplierId);
      if (!supplier) return null;
      if (actor.role === 'supplier' && supplierUserFor(supplier)?.id !== actor.id) return null;
      if (actor.role !== 'admin' && actor.role !== 'supplier') return null;
      const ratings = supplierOrderRatings.filter((r) => r.supplierId === supplierId).sort(byDelivered);
      const windowIds = new Set(ratings.slice(-RATING_WINDOW).map((r) => r.id));
      const earlier = aggregateRatings(ratings.slice(0, -SCORE_DELTA_ORDERS));
      return {
        supplier,
        score: computeSupplierPerformanceScore(supplier),
        previousScore: ratings.length > SCORE_DELTA_ORDERS && earlier ? computeSupplierPerformanceScore({ ...supplier, ...earlier }) : null,
        breakdown: supplierScoreBreakdown(supplier),
        ratedOrders: ratings.length,
        windowSize: RATING_WINDOW,
        ratings: [...ratings].reverse().map(
          (rating): ScoredOrderRating => ({ rating, onTime: isOnTime(rating), quality: orderQuality(rating), orderScore: orderScore(rating, supplier), inWindow: windowIds.has(rating.id) }),
        ),
        contextNotes: scoreContextNotes.filter((n) => n.supplierId === supplierId).sort((a, b) => (a.addedAt < b.addedAt ? 1 : -1)),
        agreedTerms: agreementStateFor(supplierId).current?.terms ?? null,
        deliveryReschedules: (() => {
          const since = new Date(Date.now() - 90 * 86_400_000).toISOString();
          const moved = deliverySchedules.filter((s) => s.supplierId === supplierId).flatMap((s) => s.events).filter((e) => e.kind === 'rescheduled' && e.at > since);
          return { total: moved.length, supplierCaused: moved.filter((e) => e.cause === 'supplier').length };
        })(),
      };
    }),

  logOrderDefect: (ratingId, note, attribution, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const rating = ratingOrThrow(ratingId);
      if (!note.trim()) throw new RepositoryError('invalid_input');
      ratingCounter += 1;
      const updated = patchInPlace(supplierOrderRatings, ratingId, {
        defects: [...rating.defects, { id: `${ratingId}-d-new-${ratingCounter}`, note: note.trim(), loggedBy: actor.name, loggedAt: new Date().toISOString(), attribution }],
      });
      recomputeSupplierMetrics(rating.supplierId);
      return updated;
    }),

  setOrderAdminQuality: (ratingId, quality, note, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const rating = ratingOrThrow(ratingId);
      if (quality !== null && (!Number.isInteger(quality) || quality < 1 || quality > 5)) throw new RepositoryError('invalid_input');
      // Judgement about a supplier's business is never unexplained.
      if (!note.trim()) throw new RepositoryError('reason_required');
      const updated = patchInPlace(supplierOrderRatings, ratingId, {
        adminQuality: quality ?? undefined,
        adminQualityNote: note.trim(),
        adminQualityBy: actor.name,
        adminQualityAt: new Date().toISOString(),
      });
      recomputeSupplierMetrics(rating.supplierId);
      return updated;
    }),

  raiseRatingDispute: (ratingId, reason, byUserId) =>
    simulateWrite(() => {
      const actor = catalogActor(byUserId);
      const rating = ratingOrThrow(ratingId);
      const supplier = byId(suppliers, rating.supplierId);
      if (actor.role !== 'supplier' || !supplier || supplierUserFor(supplier)?.id !== actor.id) throw new RepositoryError('forbidden');
      if (rating.dispute) throw new RepositoryError('already_disputed');
      if (reason.trim().length < 10) throw new RepositoryError('reason_required');
      // Opening a case changes nothing about the score — only a decision does.
      return patchInPlace(supplierOrderRatings, ratingId, {
        dispute: { raisedBy: actor.name, raisedAt: new Date().toISOString(), reason: reason.trim(), status: 'open' },
      });
    }),

  resolveRatingDispute: (ratingId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const rating = ratingOrThrow(ratingId);
      if (rating.dispute?.status !== 'open') throw new RepositoryError('not_open');
      if (!input.note.trim()) throw new RepositoryError('reason_required');
      const now = new Date().toISOString();
      let defects = rating.defects;
      let adminQuality = rating.adminQuality;
      if (input.outcome === 'upheld') {
        for (const move of input.reattribute ?? []) {
          defects = defects.map((d) =>
            d.id === move.defectId && d.attribution !== move.to
              ? { ...d, attribution: move.to, attributedBefore: d.attributedBefore ?? d.attribution, reattributedBy: actor.name, reattributedAt: now, reattributionNote: input.note.trim() }
              : d,
          );
        }
        if (input.adminQuality !== undefined) adminQuality = input.adminQuality ?? undefined;
      }
      const updated = patchInPlace(supplierOrderRatings, ratingId, {
        defects,
        adminQuality,
        dispute: { ...rating.dispute, status: input.outcome, resolvedBy: actor.name, resolvedAt: now, resolutionNote: input.note.trim() },
      });
      recomputeSupplierMetrics(rating.supplierId);
      return updated;
    }),

  addScoreContextNote: (supplierId, note, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      if (!byId(suppliers, supplierId)) throw new RepositoryError('not_found');
      if (note.trim().length < 10) throw new RepositoryError('invalid_input');
      ratingCounter += 1;
      const created: SupplierScoreContextNote = { id: `scn-new-${ratingCounter}`, supplierId, note: note.trim(), addedBy: actor.name, addedAt: new Date().toISOString(), isDemo: true };
      scoreContextNotes.push(created);
      return created;
    }),

  /* ------------------------------------------ Supplier agreement & SLA (098) */
  listSupplierAgreements: (byUserId) =>
    simulateRead((): SupplierAgreementSummary[] => {
      adminOnly(byUserId);
      const now = Date.now();
      const urgency: Record<SupplierAgreementStatus, number> = { lapsed: 0, none: 1, expiring: 2, active: 3 };
      return suppliers
        .map((supplier): SupplierAgreementSummary => {
          const versions = versionsOf(supplierAgreementVersions, supplier.id);
          const state = agreementState(versions, now);
          return {
            supplier,
            status: state.status,
            daysToExpiry: state.daysToExpiry,
            terms: state.current?.terms ?? null,
            awaitingAcknowledgement: versions.some((v) => !v.acknowledgedAt),
            ordersInFlight: supplierPurchaseOrders.filter((po) => po.supplierId === supplier.id && po.status === 'sent' && poStageOf(po) !== 'delivered').length,
          };
        })
        .sort((a, b) => urgency[a.status] - urgency[b.status] || (a.daysToExpiry ?? 0) - (b.daysToExpiry ?? 0) || a.supplier.name.localeCompare(b.supplier.name));
    }),

  getSupplierAgreement: (supplierId, byUserId) =>
    simulateRead((): SupplierAgreementView | null => {
      const actor = catalogActor(byUserId);
      const supplier = byId(suppliers, supplierId);
      if (!supplier) return null;
      if (actor.role === 'supplier' && supplierUserFor(supplier)?.id !== actor.id) return null;
      if (actor.role !== 'admin' && actor.role !== 'supplier') return null;
      const versions = versionsOf(supplierAgreementVersions, supplierId);
      const state = agreementState(versions, Date.now());
      const orders = supplierPurchaseOrders
        .filter((po) => po.supplierId === supplierId && po.status === 'sent' && po.sentAt)
        .map((po): AgreementOrderView => ({
          poId: po.id,
          code: po.code,
          stage: poStageOf(po),
          sentAt: po.sentAt!,
          version: po.agreementTerms?.version ?? null,
          deliverySlaDays: po.agreementTerms?.deliverySlaDays ?? null,
          paymentTermsDays: po.agreementTerms?.paymentTermsDays ?? null,
          promisedDelivery: promisedDeliveryOf(po),
          receivedAt: po.receivedAt ?? null,
          paymentDueDate: supplierPaymentDueDate(po),
          underPriorTerms: !!po.agreementTerms && po.agreementTerms.agreementVersionId !== state.current?.id,
        }));
      const inFlight = orders.filter((o) => o.stage !== 'delivered').sort((a, b) => (a.sentAt < b.sentAt ? 1 : -1));
      const delivered = orders.filter((o) => o.stage === 'delivered').sort((a, b) => ((a.receivedAt ?? '') < (b.receivedAt ?? '') ? 1 : -1)).slice(0, 5);
      return {
        supplier,
        status: state.status,
        current: state.current,
        upcoming: state.upcoming,
        daysToExpiry: state.daysToExpiry,
        renewalOnFile: state.renewalOnFile,
        canIssueNewPo: canIssueNewPo(state.status),
        versions: [...versions].reverse().map((v, i, newestFirst) => ({
          version: v,
          changed: changedTerms(newestFirst[i + 1]?.terms ?? null, v.terms),
          isCurrent: v.id === state.current?.id,
          isUpcoming: new Date(v.effectiveFrom).getTime() > Date.now(),
        })),
        orders: [...inFlight, ...delivered],
      };
    }),

  recordAgreementVersion: (supplierId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const supplier = byId(suppliers, supplierId);
      if (!supplier) throw new RepositoryError('not_found');
      const versions = versionsOf(supplierAgreementVersions, supplierId);
      const last = versions[versions.length - 1];
      // The first version is the initial agreement; everything after it is an
      // amendment or a renewal, and says what changed.
      if ((input.kind === 'initial') !== !last) throw new RepositoryError('invalid_state');
      if (last && (input.reason ?? '').trim().length < 10) throw new RepositoryError('reason_required');
      // AIEC is never the manufacturer of record — no agreement without it.
      if (!input.warrantyPassThrough) throw new RepositoryError('invalid_input');
      if (!input.documentName.trim()) throw new RepositoryError('document_required');
      if (checkTerms(input.terms, input.effectiveFrom, input.expiresOn).length > 0) throw new RepositoryError('invalid_input');
      // A later version can't start before the one it follows.
      if (last && new Date(input.effectiveFrom).getTime() < new Date(last.effectiveFrom).getTime()) throw new RepositoryError('invalid_input');
      agreementCounter += 1;
      const created: SupplierAgreementVersion = {
        id: `sag-new-${agreementCounter}`,
        supplierId,
        version: (last?.version ?? 0) + 1,
        kind: input.kind,
        terms: { ...input.terms, qualityStandards: input.terms.qualityStandards.trim() },
        effectiveFrom: input.effectiveFrom,
        expiresOn: input.expiresOn,
        documentName: input.documentName.trim(),
        reason: input.reason?.trim() || undefined,
        warrantyPassThrough: true,
        recordedBy: actor.name,
        recordedAt: new Date().toISOString(),
        isDemo: true,
      };
      supplierAgreementVersions.push(created);
      return created;
    }),

  /* -------------------------------------------- Shipment tracking (102) */
  getShipmentBoard: (byUserId) =>
    simulateRead((): ShipmentBoard => {
      const viewer = shipmentViewerOf(byUserId);
      const now = Date.now();
      const recent = new Date(now - 3 * 86_400_000).toISOString();
      const shipments = shipmentLegs
        .filter((l) => legVisibleTo(l, viewer))
        .map((l) => shipmentViewOf(l, viewer, now))
        // Arrived a while ago and no longer news.
        .filter((s) => !s.arrived || (s.timeline.find((e) => e.milestone === 'arrived')?.reachedAt ?? '') > recent)
        .sort((a, b) => Number(a.arrived) - Number(b.arrived) || (a.etaAt < b.etaAt ? -1 : 1));
      const canDispatch = viewer.actor.role === 'admin' || viewer.actor.role === 'supplier';
      const onALeg = new Set(shipmentLegs.flatMap((l) => l.lineItemIds));
      const dispatchable: DispatchablePo[] = !canDispatch
        ? []
        : supplierPurchaseOrders
            .filter((po) => po.status === 'sent' && po.supplierId && (!viewer.supplierId || po.supplierId === viewer.supplierId) && shipmentSite(po.dealId))
            .map((po) => ({
              poId: po.id,
              poCode: po.code,
              siteName: shipmentSite(po.dealId)?.siteName ?? '',
              supplierName: byId(suppliers, po.supplierId!)?.name ?? '',
              lines: (po.lineItems ?? []).filter((l) => lineStageOf(po, l) === 'ready_to_ship' && !onALeg.has(l.id)).map((l) => ({ id: l.id, description: l.description })),
            }))
            .filter((p) => p.lines.length > 0);
      return { shipments, dispatchable };
    }),

  dispatchShipment: (poId, input, byUserId) =>
    simulateWrite(() => {
      const viewer = shipmentViewerOf(byUserId);
      if (viewer.actor.role !== 'admin' && viewer.actor.role !== 'supplier') throw new RepositoryError('forbidden');
      const po = deliveryPoOrThrow(poId);
      if (viewer.supplierId && po.supplierId !== viewer.supplierId) throw new RepositoryError('forbidden');
      const supplier = byId(suppliers, po.supplierId!)!;
      const site = shipmentSite(po.dealId);
      if (!site) throw new RepositoryError('no_destination');
      if (input.vehicleLabel.trim().length < 2 || input.driverName.trim().length < 2) throw new RepositoryError('invalid_input');
      if (input.source !== 'live_gps' && input.source !== 'manual') throw new RepositoryError('invalid_input');
      const onALeg = new Set(shipmentLegs.flatMap((l) => l.lineItemIds));
      const lines = (po.lineItems ?? []).filter((l) => input.lineIds.includes(l.id));
      // Only what's really ready, and only what isn't already on a vehicle.
      if (lines.length === 0 || lines.length !== input.lineIds.length || lines.some((l) => lineStageOf(po, l) !== 'ready_to_ship' || onALeg.has(l.id))) throw new RepositoryError('invalid_state');
      const now = Date.now();
      const origin = originFor(supplier.city);
      // Moving the lines to shipped is the one status change; the leg is what it's now tracked by.
      movePoLinesSync(po.id, lines.map((l) => l.id), 'shipped', viewer.actor, viewer.actor.role === 'admin' ? 'Dispatched from the shipment tracker' : undefined);
      shipmentCounter += 1;
      const at = new Date(now).toISOString();
      const leg: ShipmentLeg = {
        id: `shp-new-${shipmentCounter}`,
        poId: po.id,
        dealId: po.dealId,
        supplierId: supplier.id,
        lineItemIds: lines.map((l) => l.id),
        vehicleLabel: input.vehicleLabel.trim(),
        driverName: input.driverName.trim(),
        driverPhone: input.driverPhone?.trim() || undefined,
        source: input.source,
        origin: { name: `${supplier.name}, ${origin.name}`, lat: origin.lat, lng: origin.lng },
        dispatchedAt: at,
        etaAt: estimateEtaAt(origin, site, now),
        milestones: [{ milestone: 'dispatched', at, source: input.source === 'live_gps' ? 'gps' : 'manual', byName: input.source === 'manual' ? viewer.actor.name : undefined }],
        isDemo: true,
      };
      shipmentLegs.push(leg);
      notifyCustomerOfMilestone(leg.id, 'dispatched');
      syncCommitments(now);
      return shipmentViewOf(byId(shipmentLegs, leg.id)!, viewer, now);
    }),

  updateShipmentMilestone: (legId, input, byUserId) =>
    simulateWrite(() => {
      const viewer = shipmentViewerOf(byUserId);
      const leg = byId(shipmentLegs, legId);
      if (!leg || !legVisibleTo(leg, viewer)) throw new RepositoryError('not_found');
      const isAdmin = viewer.actor.role === 'admin';
      if (!isAdmin && !(viewer.actor.role === 'supplier' && viewer.supplierId === leg.supplierId && !leg.partnerId)) throw new RepositoryError('forbidden');
      const now = Date.now();
      const snap = legSnapshotOf(leg, routeOfLeg(leg), now);
      // A live feed is the truth while it works; only a manual leg, or one whose feed has dropped, is updated by hand.
      if (snap.arrived || (leg.source === 'live_gps' && snap.feed !== 'lost')) throw new RepositoryError('invalid_state');
      if (milestoneIndex(input.milestone) <= milestoneIndex(snap.milestone)) throw new RepositoryError('invalid_input');
      // AIEC standing in for the supplier says where the word came from.
      if (isAdmin && (input.note ?? '').trim().length < 4) throw new RepositoryError('reason_required');
      if (input.etaAt && (Number.isNaN(new Date(input.etaAt).getTime()) || (input.milestone !== 'arrived' && new Date(input.etaAt).getTime() < now))) throw new RepositoryError('invalid_input');
      const at = new Date(now).toISOString();
      const note = input.note?.trim() || undefined;
      const updated = patchInPlace(shipmentLegs, leg.id, {
        etaAt: input.etaAt && input.milestone !== 'arrived' ? new Date(input.etaAt).toISOString() : leg.etaAt,
        milestones: [...leg.milestones, { milestone: input.milestone, at, source: 'manual', byName: viewer.actor.name, note }],
      });
      // The supplier's word belongs in their conversation with AIEC, so the whole picture stays in one place.
      const supplier = byId(suppliers, leg.supplierId)!;
      const po = byId(supplierPurchaseOrders, leg.poId)!;
      const text = `Shipment update: ${leg.vehicleLabel} is ${input.milestone.replace('_', ' ')}${note ? `. ${note}` : ''}`;
      pushSupplierMessage(ensureSupplierThread(supplier.id, po.id), {
        author: 'supplier',
        authorName: isAdmin ? supplier.name : viewer.actor.name,
        authorUserId: isAdmin ? undefined : viewer.actor.id,
        body: text,
        channel: isAdmin ? 'phone' : 'in_app',
        at,
        loggedBy: isAdmin ? viewer.actor.name : undefined,
        expectsReply: false,
        poRef: po.id,
        readAt: isAdmin ? at : undefined,
      });
      notifyCustomerOfMilestone(leg.id, input.milestone);
      if (input.milestone === 'nearby') notifyTechnicianOfDelivery(po, at, `${shipmentLabelOf(updated)} on ${po.code} is nearby`);
      advanceShipments(now);
      syncCommitments(now);
      return shipmentViewOf(byId(shipmentLegs, leg.id)!, viewer, now);
    }),

  /* --------------------------------------- Site delivery checklist (103) */
  getDeliveryChecklistBoard: (byUserId) =>
    simulateRead((): DeliveryChecklistBoard => {
      const actor = checklistActorOf(byUserId);
      const recent = new Date(Date.now() - 14 * 86_400_000).toISOString();
      const checklists = deliveryChecklists
        .filter((c) => checklistDealVisible(c.dealId, actor) && (c.status === 'in_progress' || (c.completedAt ?? '') > recent))
        .sort((a, b) => Number(b.status === 'in_progress') - Number(a.status === 'in_progress') || ((b.completedAt ?? b.startedAt) < (a.completedAt ?? a.startedAt) ? -1 : 1))
        .map(checklistViewOf);
      return { arrivals: checklistArrivals(actor), checklists };
    }),

  startDeliveryChecklist: (poId, legId, byUserId) =>
    simulateWrite(() => {
      const actor = checklistActorOf(byUserId);
      const arrival = checklistArrivals(actor).find((a) => a.poId === poId && a.legId === legId);
      if (!arrival) throw new RepositoryError('invalid_state');
      const existing = arrival.checklistId ? byId(deliveryChecklists, arrival.checklistId) : undefined;
      if (existing) return checklistViewOf(existing);
      const po = byId(supplierPurchaseOrders, poId)!;
      checklistCounter += 1;
      const created: DeliveryChecklist = {
        id: `dck-new-${checklistCounter}`,
        poId,
        dealId: po.dealId,
        supplierId: po.supplierId!,
        legId: legId ?? undefined,
        status: 'in_progress',
        startedAt: new Date().toISOString(),
        startedByName: actor.name,
        // Each part is pinned to the procedure in force right now (107) and finishes under it,
        // even if the procedure is amended while the truck is still being unloaded.
        items: arrival.lines.map((l): DeliveryCheckItem => {
          const category = (po.lineItems ?? []).find((x) => x.id === l.id)?.category ?? '';
          const sop = resolveSopSteps(deliverySops, category, Date.now());
          return { lineItemId: l.id, description: l.description, expectedQty: l.quantity, verdict: 'pending', kinds: [], photos: [], category, sopSteps: sop.steps, sopVersions: sop.versions, sopResults: [] };
        }),
        isDemo: true,
      };
      deliveryChecklists.push(created);
      return checklistViewOf(created);
    }),

  saveDeliveryCheckItem: (checklistId, lineItemId, input, byUserId) =>
    simulateWrite(() => {
      const actor = checklistActorOf(byUserId);
      const checklist = checklistOrThrow(checklistId, actor);
      // A finished checklist is what could be verified at that moment. It is never rewritten.
      if (checklist.status !== 'in_progress') throw new RepositoryError('invalid_state');
      const item = checklist.items.find((i) => i.lineItemId === lineItemId);
      if (!item) throw new RepositoryError('not_found');
      const findings = { arrived: input.arrived, receivedQty: input.receivedQty, conditionOk: input.conditionOk, specOk: input.specOk, note: input.note, photoCount: input.photos.length, sopSteps: item.sopSteps, sopResults: input.sopResults };
      const problem = problemWith(findings, item.expectedQty);
      if (problem === 'quantity') throw new RepositoryError('invalid_quantity');
      if (problem === 'photo') throw new RepositoryError('photo_required');
      if (problem === 'note') throw new RepositoryError('note_required');
      if (problem === 'sop_step') throw new RepositoryError('sop_incomplete');
      if (problem === 'sop_photo') throw new RepositoryError('sop_photo_required');
      const now = new Date().toISOString();
      const kept = new Map(item.photos.map((p) => [p.id, p]));
      const photos = input.photos.map((p) => {
        const known = p.id ? kept.get(p.id) : undefined;
        if (known) return known;
        checklistPhotoCounter += 1;
        return { id: `dph-new-${checklistPhotoCounter}`, fileName: p.fileName, previewUrl: p.previewUrl, capturedAt: p.capturedAt };
      });
      const kinds = kindsOf(findings, item.expectedQty);
      const arrived = input.arrived;
      const next: DeliveryCheckItem = {
        ...item,
        verdict: verdictOf(findings, item.expectedQty),
        receivedQty: arrived ? (input.receivedQty ?? item.expectedQty) : 0,
        // A part that isn't there has no condition to speak of.
        conditionOk: arrived && (input.receivedQty ?? item.expectedQty) > 0 ? input.conditionOk !== false : undefined,
        specOk: arrived && (input.receivedQty ?? item.expectedQty) > 0 ? input.specOk !== false : undefined,
        kinds,
        photos: arrived ? photos : [],
        sopResults: arrived && (input.receivedQty ?? item.expectedQty) > 0 ? (item.sopSteps ?? []).map((st) => {
          const r = input.sopResults?.find((x) => x.stepId === st.id);
          checklistPhotoCounter += 1;
          const prior = item.sopResults?.find((x) => x.stepId === st.id)?.photo;
          return { stepId: st.id, done: !!r?.done, photo: r?.photo ? (r.photo.id && prior?.id === r.photo.id ? prior : { id: `dph-new-${checklistPhotoCounter}`, fileName: r.photo.fileName, previewUrl: r.photo.previewUrl, capturedAt: r.photo.capturedAt }) : undefined };
        }) : [],
        note: input.note?.trim() || undefined,
        checkedAt: now,
        checkedByName: actor.name,
      };
      const updated = patchInPlace(deliveryChecklists, checklist.id, { items: checklist.items.map((i) => (i.lineItemId === lineItemId ? next : i)) });
      syncDiscrepancyReport(updated, actor);
      syncCommitments(Date.now());
      return checklistViewOf(updated);
    }),

  completeDeliveryChecklist: (checklistId, input, byUserId) =>
    simulateWrite(() => {
      const actor = checklistActorOf(byUserId);
      const checklist = checklistOrThrow(checklistId, actor);
      if (checklist.status !== 'in_progress') throw new RepositoryError('invalid_state');
      const progress = progressOf(checklist.items);
      if (!progress.complete) throw new RepositoryError(progress.nothingArrived ? 'nothing_arrived' : 'incomplete');
      const receiverName = input.receiver.name.trim();
      if (receiverName.length < 2 || (input.receiver.role !== 'technician' && input.receiver.role !== 'site_contact')) throw new RepositoryError('receiver_required');
      // A site contact's own word is the acknowledgment; only a technician's receipt asks for a second name.
      const ackName = input.receiver.role === 'technician' ? input.siteAckName?.trim() : undefined;
      const po = byId(supplierPurchaseOrders, checklist.poId);
      if (!po) throw new RepositoryError('not_found');
      const now = Date.now();
      const at = new Date(now).toISOString();
      const receiver = { role: input.receiver.role, name: receiverName, phone: input.receiver.phone?.trim() || undefined };
      const receivedLineIds = checklist.items.filter(isReceived).map((i) => i.lineItemId).filter((id) => {
        const line = (po.lineItems ?? []).find((l) => l.id === id);
        return line && lineStageOf(po, line) === 'shipped';
      });
      const wasReceived = !!po.receivedAt;
      const roleWord = receiver.role === 'site_contact' ? 'site contact' : 'technician';
      const moved = receivedLineIds.length > 0 ? movePoLinesSync(po.id, receivedLineIds, 'delivered', actor, `Verified on site by ${receiverName} (${roleWord})`, checklist.id) : po;
      // The one who stood at the tailgate is who received it, not whoever held the phone.
      if (!wasReceived && moved.receivedAt) patchInPlace(supplierPurchaseOrders, po.id, { receivedBy: `${receiverName} (${roleWord})` });

      // The checklist is the authoritative "it arrived": the vehicle's tracker follows it, not the other way round.
      const leg = checklist.legId ? byId(shipmentLegs, checklist.legId) : undefined;
      if (leg && !legSnapshotOf(leg, routeOfLeg(leg), now).arrived) {
        patchInPlace(shipmentLegs, leg.id, { milestones: [...leg.milestones, { milestone: 'arrived' as const, at, source: 'manual' as const, byName: receiverName, note: 'Confirmed on site by checklist' }] });
        notifyCustomerOfMilestone(leg.id, 'arrived');
        advanceShipments(now);
      }

      const done = patchInPlace(deliveryChecklists, checklist.id, {
        status: 'completed',
        completedAt: at,
        receivedBy: receiver,
        siteAck: ackName ? { name: ackName, at } : undefined,
        note: input.note?.trim() || undefined,
        recordedByName: actor.name !== receiverName ? actor.name : undefined,
        completedByUserId: actor.id,
      });
      syncDiscrepancyReport(done, actor);
      // 108: a report goes to the supplier the moment the delivery is closed, with the photos, so nobody has to remember to.
      const raised = reportOfChecklist(done.id);
      if (raised && raised.status === 'open' && !raised.routedToSupplierAt && po.supplierId && supplierUserFor(byId(suppliers, po.supplierId)!)) {
        routeReportToSupplier(raised, actor, 'in_app');
        logAutomatedAction({
          sourceKey: 'discrepancy.routed',
          triggeringCondition: `Delivery ${po.code} closed with ${raised.items.length} part(s) in question`,
          actionTaken: `Sent report ${raised.code}, with photos, to ${byId(suppliers, po.supplierId)?.name ?? 'the supplier'}`,
          affectedRecordId: raised.id,
          affectedRecordType: 'other',
          subjectLabel: raised.code,
        });
      }
      // Ready to be signed: the checklist is the working document, this its clean summary.
      const confirmation = createDeliveryConfirmation(done);

      // Every part on site and none in question: the technician can now really start.
      let jobReady = false;
      if (dealMaterialsOnSite(po.dealId)) {
        const job = pendingJobFor(po.dealId);
        if (job && job.status === 'materials_pending') {
          patchInPlace(jobs, job.id, { status: 'scheduled' });
          jobReady = true;
          logAutomatedAction({
            sourceKey: 'delivery.job_ready',
            triggeringCondition: `Every part for ${shipmentSite(po.dealId)?.siteName ?? po.dealId} is on site`,
            actionTaken: `Moved installation job ${job.code} to scheduled`,
            affectedRecordId: job.id,
            affectedRecordType: 'other',
            subjectLabel: job.code,
          });
        }
      }
      syncCommitments(now);
      return { checklist: checklistViewOf(done), deliveredLineCount: receivedLineIds.length, poFullyDelivered: !!byId(supplierPurchaseOrders, po.id)?.receivedAt, jobReady, confirmationId: confirmation.id };
    }),

  cancelDeliveryChecklist: (checklistId, byUserId) =>
    simulateWrite(() => {
      const actor = checklistActorOf(byUserId);
      const checklist = checklistOrThrow(checklistId, actor);
      if (checklist.status !== 'in_progress') throw new RepositoryError('invalid_state');
      // Nothing left standing that the abandoned checklist raised.
      const emptied = { ...checklist, items: checklist.items.map((i) => ({ ...i, verdict: 'pending' as const, kinds: [] })) };
      syncDiscrepancyReport(emptied, actor);
      deliveryChecklists.splice(deliveryChecklists.indexOf(checklist), 1);
      syncCommitments(Date.now());
    }),

  /* ---------------------------------------- Delivery confirmation (104) */
  getDeliveryConfirmations: (byUserId) =>
    simulateRead((): DeliveryConfirmationView[] => {
      const actor = confirmationActorOf(byUserId);
      const recent = new Date(Date.now() - 180 * 86_400_000).toISOString();
      return deliveryConfirmations
        .filter((c) => confirmationVisibleTo(c, actor) && (c.status === 'awaiting_signature' || (c.signedAt ?? '') > recent))
        .sort((a, b) => Number(b.status === 'awaiting_signature') - Number(a.status === 'awaiting_signature') || ((b.signedAt ?? b.createdAt) < (a.signedAt ?? a.createdAt) ? -1 : 1))
        .map((c) => confirmationViewOf(c, actor));
    }),

  signDeliveryConfirmation: (confirmationId, input, byUserId) =>
    simulateWrite(() => {
      const actor = confirmationActorOf(byUserId);
      if (actor.role === 'customer') throw new RepositoryError('forbidden');
      const confirmation = byId(deliveryConfirmations, confirmationId);
      if (!confirmation || !confirmationVisibleTo(confirmation, actor)) throw new RepositoryError('not_found');
      // Locked once signed: no second signature, no edit.
      if (confirmation.status !== 'awaiting_signature') throw new RepositoryError('invalid_state');
      const checklist = byId(deliveryChecklists, confirmation.checklistId);
      const receiver = checklist?.receivedBy;
      if (!checklist || !receiver) throw new RepositoryError('invalid_state');

      // The one the checklist named as having received it must sign; a second party may.
      const primary = input.signatures.find((s) => s.role === receiver.role);
      const second = input.signatures.find((s) => s !== primary);
      if (!primary || primary.name.trim().length < 2 || !looksLikeSignature(primary.signature)) throw new RepositoryError('signature_required');
      if (input.signatures.length > 2) throw new RepositoryError('invalid_input');
      if (second) {
        if (second.role === receiver.role || (second.role !== 'customer' && second.role !== 'site_contact')) throw new RepositoryError('invalid_input');
        if (second.name.trim().length < 2 || !looksLikeSignature(second.signature)) throw new RepositoryError('signature_required');
      } else if ((input.note ?? '').trim().length < 4) {
        // Signing alone is fine, but it says why.
        throw new RepositoryError('note_required');
      }

      const now = Date.now();
      const capturedMs = input.capturedAt ? new Date(input.capturedAt).getTime() : now;
      const closedMs = new Date(checklist.completedAt ?? confirmation.createdAt).getTime();
      // Drawn after the checklist closed, and never in the future.
      if (Number.isNaN(capturedMs) || capturedMs > now + 60_000 || capturedMs < closedMs) throw new RepositoryError('invalid_input');
      const signedAt = new Date(Math.min(capturedMs, now)).toISOString();
      const delayed = now - capturedMs > 60_000;

      const materialsComplete = dealMaterialsConfirmed(confirmation.dealId, confirmation.id);
      const signed = patchInPlace(deliveryConfirmations, confirmation.id, {
        status: 'signed',
        signatures: [primary, ...(second ? [second] : [])].map((s) => ({ role: s.role, name: s.name.trim(), signature: s.signature, signedAt })),
        note: input.note?.trim() || undefined,
        recordedByName: actor.name !== primary.name.trim() ? actor.name : undefined,
        capturedAt: delayed ? signedAt : undefined,
        signedAt,
        reportsAtSigning: confirmation.reportIds.map((id) => byId(discrepancyReports, id)).filter((r): r is DeliveryDiscrepancyReport => !!r).map((r) => ({ id: r.id, code: r.code, status: r.status })),
        materialsComplete,
      });
      if (materialsComplete) anchorMaterialPayments(confirmation.dealId, signedAt);
      syncCommitments(now);
      return confirmationViewOf(signed, actor);
    }),

  /* ------------------------ Damaged / missing parts report (108) */
  getDiscrepancyReports: (byUserId) =>
    simulateRead((): DiscrepancyReportView[] => {
      const actor = reportActorOf(byUserId);
      const now = Date.now();
      return discrepancyReports
        .filter((r) => r.status !== 'withdrawn' && checklistDealVisible(r.dealId, actor))
        .map((r) => reportViewOf(r, actor, now))
        .sort((a, b) => Number(a.status === 'resolved') - Number(b.status === 'resolved') || Number(b.rush) - Number(a.rush) || (a.createdAt < b.createdAt ? 1 : -1));
    }),

  updateDiscrepancyReport: (reportId, input, byUserId) =>
    simulateWrite(() => {
      const actor = reportActorOf(byUserId);
      const r = reportOrThrow(reportId, actor);
      if (r.status !== 'open') throw new RepositoryError('invalid_state');
      const causes = [...new Set(input.possibleCauses)];
      if (causes.length === 0 && !(input.causeNote ?? '').trim()) throw new RepositoryError('cause_required');
      if (input.rush && input.neededBy && Number.isNaN(new Date(input.neededBy).getTime())) throw new RepositoryError('invalid_input');
      const becameRush = input.rush && !r.rush;
      let updated = patchInPlace(discrepancyReports, r.id, {
        possibleCauses: causes,
        causeNote: input.causeNote?.trim() || undefined,
        rush: input.rush,
        neededBy: input.rush && input.neededBy ? new Date(input.neededBy).toISOString() : undefined,
        events: reportEvent(r, becameRush ? 'rush' : 'details', actor.name, input.causeNote?.trim() || undefined),
      });
      if (becameRush) {
        // A rush is an installation at stake: the alert is raised a level, and a supplier already told hears again, urgently.
        const alert = alerts.find((a) => a.relatedId === r.id && a.titleKey === 'deliveryChecklist.alert.discrepancy' && a.status !== 'resolved');
        if (alert) patchInPlace(alerts, alert.id, { severity: 'critical' });
        const supplier = byId(suppliers, r.supplierId);
        if (updated.routedToSupplierAt && supplier && supplierUserFor(supplier)) {
          routeReportToSupplier(updated, actor, 'in_app', `Update on ${updated.code}: this is now urgent.`);
          updated = byId(discrepancyReports, r.id)!;
        }
      }
      syncCommitments(Date.now());
      return reportViewOf(updated, actor, Date.now());
    }),

  attributeDiscrepancyReport: (reportId, input, byUserId) =>
    simulateWrite(() => {
      const actor = reportActorOf(byUserId);
      if (actor.role !== 'admin') throw new RepositoryError('forbidden');
      const r = reportOrThrow(reportId, actor);
      if (r.status !== 'open') throw new RepositoryError('invalid_state');
      // The delivery is signed for first: what is being judged is what could be verified at that moment.
      { const kept = reportChecklist(r); if (kept && kept.status !== 'completed') throw new RepositoryError('checklist_open'); }
      if (input.note.trim().length < 4) throw new RepositoryError('note_required');
      const at = new Date().toISOString();
      const updated = patchInPlace(discrepancyReports, r.id, {
        attribution: input.attribution,
        attributionNote: input.note.trim(),
        attributedByName: actor.name,
        attributedAt: at,
        events: reportEvent(r, 'attributed', actor.name, input.note.trim()),
      });
      syncReportDefect(updated);
      syncCommitments(Date.now());
      return reportViewOf(updated, actor, Date.now());
    }),

  advanceDiscrepancyResolution: (reportId, input, byUserId) =>
    simulateWrite(() => {
      const actor = reportActorOf(byUserId);
      if (actor.role !== 'admin') throw new RepositoryError('forbidden');
      const r = reportOrThrow(reportId, actor);
      if (r.status !== 'open') throw new RepositoryError('invalid_state');
      { const kept = reportChecklist(r); if (kept && kept.status !== 'completed') throw new RepositoryError('checklist_open'); }
      if (!canMoveTo(r.resolution, input.resolution)) throw new RepositoryError('invalid_transition');
      const now = Date.now();
      const eta = input.replacementEta ? new Date(input.replacementEta).getTime() : null;
      if (eta !== null && (Number.isNaN(eta) || eta < now - 86_400_000)) throw new RepositoryError('invalid_input');
      if (input.resolution === 'replacement_requested' || input.resolution === 'replacement_shipped') {
        // A replacement with no date cannot be planned around.
        if (eta === null && !r.replacementEta) throw new RepositoryError('eta_required');
      }
      let credit: number | undefined;
      if (input.resolution === 'credited') {
        const value = reportViewOf(r, actor, now).affectedValue;
        credit = input.creditAmount;
        if (credit === undefined || !Number.isFinite(credit) || credit <= 0 || credit > value) throw new RepositoryError('credit_invalid');
      }
      const closed = isClosedResolution(input.resolution);
      const at = new Date(now).toISOString();
      const updated = patchInPlace(discrepancyReports, r.id, {
        resolution: input.resolution,
        status: closed ? 'resolved' : 'open',
        replacementEta: eta !== null ? new Date(eta).toISOString() : r.replacementEta,
        creditAmount: credit ?? r.creditAmount,
        // A replacement landing after the installation was due to start is what the schedule cost is reckoned on (110).
        scheduleDelayDays: (() => {
          const job = pendingJobFor(r.dealId);
          const start = job && !job.startedAt ? job.scheduledFor : null;
          const landing = eta !== null ? new Date(eta).toISOString() : r.replacementEta;
          if (!start || !landing) return r.scheduleDelayDays;
          return Math.max(0, Math.ceil((new Date(landing).getTime() - new Date(start).getTime()) / 86_400_000));
        })(),
        events: reportEvent(r, 'resolution', actor.name, `${input.resolution}${input.note?.trim() ? `: ${input.note.trim()}` : ''}`),
      });
      if (closed) {
        const alert = alerts.find((a) => a.relatedId === r.id && a.titleKey === 'deliveryChecklist.alert.discrepancy' && a.status !== 'resolved');
        if (alert) patchInPlace(alerts, alert.id, { status: 'resolved', resolvedAt: at, resolvedBy: actor.name, resolutionNote: input.resolution === 'credited' ? 'Credited by the supplier.' : 'Resolved.' });
        // Nothing left in question on the deal: the installation can be scheduled.
        if (dealMaterialsOnSite(r.dealId)) {
          const job = pendingJobFor(r.dealId);
          if (job && job.status === 'materials_pending') patchInPlace(jobs, job.id, { status: 'scheduled' });
        }
      } else if (input.resolution === 'replacement_requested') {
        // Ask the supplier plainly, in the thread, when the replacement will land.
        const supplier = byId(suppliers, r.supplierId);
        if (supplier && supplierUserFor(supplier)) {
          routeReportToSupplier(updated, actor, 'in_app', `Replacement requested for ${updated.code}: ${updated.items.map((i) => i.description).join(', ')}. We expect it by ${(updated.replacementEta ?? '').slice(0, 10)}.`);
        }
      }
      syncCommitments(now);
      return reportViewOf(byId(discrepancyReports, r.id)!, actor, now);
    }),

  sendReportToSupplier: (reportId, channel, byUserId) =>
    simulateWrite(() => {
      const actor = reportActorOf(byUserId);
      if (actor.role !== 'admin') throw new RepositoryError('forbidden');
      const r = reportOrThrow(reportId, actor);
      if (r.status !== 'open') throw new RepositoryError('invalid_state');
      const routed = routeReportToSupplier(r, actor, channel);
      syncCommitments(Date.now());
      return routed;
    }),

  notifyCustomerOfReport: (reportId, byUserId) =>
    simulateWrite(() => {
      const actor = reportActorOf(byUserId);
      if (actor.role !== 'admin') throw new RepositoryError('forbidden');
      const r = reportOrThrow(reportId, actor);
      if (r.status !== 'open') throw new RepositoryError('invalid_state');
      // An honest updated timeline needs a date in it.
      if (!r.replacementEta) throw new RepositoryError('eta_required');
      const view = reportViewOf(r, actor, Date.now());
      const deal = byId(deals, r.dealId);
      const lead = deal ? resolveLead(deal.leadId) : null;
      const template = templateInGroup('tpl-parts-notice', lead?.preferredLanguage ?? 'en') ?? templateInGroup('tpl-parts-notice', 'en');
      if (!lead || !template) return { notified: false, skipped: 'no_contact' as const };
      if (r.customerNotifiedAt) return { notified: false, skipped: 'already_told' as const };
      if (view.customerOptedOut) return { notified: false, skipped: 'opted_out' as const };
      const at = new Date().toISOString();
      let conversation = conversations.find((cv) => cv.leadId === lead.id) ?? null;
      if (!conversation) {
        conversationCounter += 1;
        conversation = { id: `conv-new-${conversationCounter}`, leadId: lead.id, lastMessageAt: at, isDemo: true };
        conversations.push(conversation);
      }
      messageCounter += 1;
      commMessages.push({ id: `cm-new-${messageCounter}`, conversationId: conversation.id, channel: template.channel, sender: 'agent', body: view.customerPreview, templateGroupId: template.groupId, status: 'sent', at, handled: true });
      patchInPlace(conversations, conversation.id, { lastMessageAt: at });
      patchInPlace(discrepancyReports, r.id, { customerNotifiedAt: at, events: reportEvent(r, 'customer_told', actor.name) });
      return { notified: true };
    }),

  /* --------------------------------------------- Advance payment & retention (118) */
  getAdvanceRetentionBoard: (byUserId) =>
    simulateRead((): AdvanceRetentionBoard => {
      adminOnly(byUserId);
      const now = Date.now();
      syncSupplierPayments(now);
      executeSupplierPayments(now);
      settleRetentions(now);
      syncAdvanceExposure(now);
      const advances = advanceItemsOf(now);
      const retentions = retentionItemsOf(now);
      return {
        advances,
        retentions,
        autoRelease: !!paymentTermsConfig.autoReleaseRetention,
        totals: {
          advanceOut: advances.reduce((n, a) => n + a.outstanding, 0),
          advanceAtRisk: advances.filter((a) => a.state === 'stalled' || a.state === 'deal_gone' || a.state === 'late').reduce((n, a) => n + a.outstanding, 0),
          retentionHeld: retentions.reduce((n, r) => n + r.amount, 0),
          retentionReady: retentions.filter((r) => r.bulkOk).reduce((n, r) => n + r.amount, 0),
        },
      };
    }),

  setAutoReleaseRetention: (on, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      paymentTermsConfig = { ...paymentTermsConfig, autoReleaseRetention: on, updatedBy: actor.name, updatedAt: new Date().toISOString() };
      settleRetentions(Date.now());
      return !!paymentTermsConfig.autoReleaseRetention;
    }),

  releaseRetentionsBatch: (retentionIds, byUserId) =>
    simulateWrite((): ReleaseBatchResult => {
      const actor = adminOnly(byUserId);
      const now = Date.now();
      const items = retentionItemsOf(now);
      const result: ReleaseBatchResult = { released: [], skipped: [] };
      for (const id of [...new Set(retentionIds)]) {
        const item = items.find((x) => x.id === id);
        if (!item) {
          result.skipped.push({ id, reason: byId(supplierRetentions, id) ? 'not_held' : 'not_found' });
          continue;
        }
        const skip = batchSkipReason(item.status, item.readiness, item.holds);
        if (skip) {
          result.skipped.push({ id, reason: skip });
          continue;
        }
        patchInPlace(supplierRetentions, id, { status: 'released', decidedAt: new Date(now).toISOString(), decidedBy: actor.name, decisionReason: 'Released in a batch after QC and handover' });
        result.released.push(id);
      }
      syncSupplierPayments(now);
      syncCommitments(now);
      return result;
    }),

  startAdvanceRecovery: (paymentId, reason, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const item = advanceItemsOf(Date.now()).find((a) => a.id === paymentId);
      const p = byId(supplierPayments, paymentId);
      if (!item || !p) throw new RepositoryError('not_found');
      if (item.recovery) throw new RepositoryError('already_open');
      if (reason.trim().length < RECOVERY_REASON_MIN) throw new RepositoryError('note_required');
      recoveryCounter += 1;
      const at = new Date().toISOString();
      const created: AdvanceRecovery = {
        id: `ar-new-${recoveryCounter}`,
        code: `AIEC-AR-${7000 + recoveryCounter}`,
        paymentId,
        poId: p.poId,
        supplierId: p.supplierId,
        amount: item.outstanding,
        reason: reason.trim(),
        status: 'open',
        startedByName: actor.name,
        startedAt: at,
        recoveredAmount: 0,
        writtenOffAmount: 0,
        events: [],
        isDemo: true,
      };
      created.events = [{ id: `${created.id}-e1`, kind: 'started', at, byName: actor.name, amount: item.outstanding, note: created.reason }];
      advanceRecoveries.push(created);
      const po = byId(supplierPurchaseOrders, p.poId);
      const supplier = byId(suppliers, p.supplierId);
      if (po && supplier && supplierUserFor(supplier)) {
        pushSupplierMessage(ensureSupplierThread(supplier.id, po.id), {
          author: 'aiec',
          authorName: actor.name,
          authorUserId: actor.id,
          body: `Recovery ${created.code}: we paid an advance of ${formatINR(item.outstanding)} on ${po.code} and the order has not been delivered. ${created.reason} Please return the advance or tell us the delivery date.`,
          channel: 'in_app',
          at,
          expectsReply: true,
          poRef: po.id,
        });
      }
      syncAdvanceExposure(Date.now());
      syncCommitments(Date.now());
      return recoveryViewOf(created);
    }),

  recordAdvanceRecovered: (recoveryId, amount, note, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const r = advanceRecoveryOrThrow(recoveryId);
      if (r.status !== 'open') throw new RepositoryError('invalid_state');
      const p = byId(supplierPayments, r.paymentId);
      if (!p) throw new RepositoryError('not_found');
      const outstanding = historyEntryOf(p).netAmount;
      if (!Number.isFinite(amount) || !(amount > 0)) throw new RepositoryError('invalid_amount');
      if (amount > outstanding) throw new RepositoryError('exceeds_payment');
      // What comes back is a credit beside the advance, so Payment History shows the money leaving and returning.
      pushPaymentAdjustment(p, 'credit', amount, `Advance recovery ${r.code}: ${note?.trim() || 'money returned by the supplier'}`, actor);
      const closes = amount >= outstanding;
      patchInPlace(advanceRecoveries, r.id, {
        recoveredAmount: r.recoveredAmount + amount,
        status: closes ? 'recovered' : 'open',
        closedAt: closes ? new Date().toISOString() : undefined,
        events: recoveryEvents(r, 'recovered', actor.name, { amount, note }),
      });
      syncAdvanceExposure(Date.now());
      syncCommitments(Date.now());
      return recoveryViewOf(byId(advanceRecoveries, r.id)!);
    }),

  writeOffAdvance: (recoveryId, note, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const r = advanceRecoveryOrThrow(recoveryId);
      if (r.status !== 'open') throw new RepositoryError('invalid_state');
      if (note.trim().length < RECOVERY_REASON_MIN) throw new RepositoryError('note_required');
      const p = byId(supplierPayments, r.paymentId);
      const remaining = p ? historyEntryOf(p).netAmount : 0;
      patchInPlace(advanceRecoveries, r.id, { status: 'written_off', writtenOffAmount: remaining, closedAt: new Date().toISOString(), events: recoveryEvents(r, 'written_off', actor.name, { amount: remaining, note }) });
      syncAdvanceExposure(Date.now());
      syncCommitments(Date.now());
      return recoveryViewOf(byId(advanceRecoveries, r.id)!);
    }),

  /* --------------------------------------------- Supplier dispute resolution (117) */
  getSupplierDisputeBoard: (byUserId) =>
    simulateRead((): SupplierDisputeBoard => {
      adminOnly(byUserId);
      const now = Date.now();
      syncSupplierDisputes(now);
      const rows = supplierDisputes.map((d) => disputeRowOf(d, now)).sort((a, b) => {
        const rank = (r: SupplierDisputeRow) => (r.status === 'resolved' ? 3 : r.sla === 'overdue' ? (r.threatensHalt ? 0 : 1) : r.threatensHalt ? 1 : 2);
        return rank(a) - rank(b) || (a.status === 'open' ? (a.dueAt < b.dueAt ? -1 : 1) : a.raisedAt < b.raisedAt ? 1 : -1);
      });
      const open = rows.filter((r) => r.status === 'open');
      return {
        rows,
        totals: { open: open.length, overdue: open.filter((r) => r.sla === 'overdue').length, halt: open.filter((r) => r.threatensHalt).length, claimedOpen: open.reduce((n, r) => n + (r.claimedAmount ?? 0), 0), resolved: rows.length - open.length },
      };
    }),

  getSupplierDispute: (disputeId, byUserId) =>
    simulateRead((): SupplierDisputeView => {
      adminOnly(byUserId);
      const d = byId(supplierDisputes, disputeId);
      if (!d) throw new RepositoryError('not_found');
      const now = Date.now();
      syncSupplierDisputes(now);
      return disputeViewOf(d, now);
    }),

  getDisputeTargets: (byUserId) =>
    simulateRead((): DisputeTargets => {
      const viewer = threadViewer(byUserId);
      const mine = (supplierId: string) => !viewer.supplierId || viewer.supplierId === supplierId;
      const poCode = (poId: string) => byId(supplierPurchaseOrders, poId)?.code ?? poId;
      const name = (id: string) => byId(suppliers, id)?.name ?? '';
      return {
        payments: supplierPayments
          .filter((p) => mine(p.supplierId) && p.status !== 'approved')
          .map((p) => ({ id: p.id, code: p.code, poId: p.poId, poCode: poCode(p.poId), supplierId: p.supplierId, supplierName: name(p.supplierId), part: p.part, amount: p.amount, status: p.status })),
        retentions: supplierRetentions
          .filter((r) => mine(r.supplierId) && (r.status === 'held' || r.status === 'paused'))
          .map((r) => ({ id: r.id, poId: r.poId, poCode: poCode(r.poId), supplierId: r.supplierId, supplierName: name(r.supplierId), amount: r.amount, status: r.status })),
        invoices: supplierInvoices
          .filter((i) => mine(i.supplierId) && (i.status === 'rejected' || evaluateInvoice(i).status === 'mismatch'))
          .map((i) => ({ id: i.id, poId: i.poId, poCode: poCode(i.poId), supplierId: i.supplierId, supplierName: name(i.supplierId), number: i.invoiceNumber, status: evaluateInvoice(i).status })),
      };
    }),

  raiseSupplierDispute: (input, byUserId) =>
    simulateWrite(() => {
      const viewer = threadViewer(byUserId);
      const po = byId(supplierPurchaseOrders, input.poId);
      if (!po || !po.supplierId) throw new RepositoryError('not_found');
      if (viewer.supplierId && viewer.supplierId !== po.supplierId) throw new RepositoryError('forbidden');
      if (input.position.trim().length < POSITION_MIN) throw new RepositoryError('position_required');
      if (input.claimedAmount !== undefined && !(input.claimedAmount > 0)) throw new RepositoryError('invalid_amount');
      // The dispute must be about something real on this order, and it must be the supplier's own.
      if (input.kind === 'amount') {
        const p = input.paymentId ? byId(supplierPayments, input.paymentId) : undefined;
        if (!p || p.poId !== po.id) throw new RepositoryError('target_required');
        if (input.claimedAmount === undefined) throw new RepositoryError('amount_required');
      }
      if (input.kind === 'retention_timing') {
        const r = input.retentionId ? byId(supplierRetentions, input.retentionId) : undefined;
        if (!r || r.poId !== po.id || (r.status !== 'held' && r.status !== 'paused')) throw new RepositoryError('target_required');
      }
      if (input.kind === 'invoice') {
        const i = input.invoiceId ? byId(supplierInvoices, input.invoiceId) : undefined;
        if (!i || i.poId !== po.id) throw new RepositoryError('target_required');
      }
      // The same thing disputed twice while the first is still open is the same dispute.
      const target = input.paymentId ?? input.retentionId ?? input.invoiceId;
      if (supplierDisputes.some((d) => d.status === 'open' && (d.paymentId ?? d.retentionId ?? d.invoiceId) === target)) throw new RepositoryError('already_open');
      disputeCounter += 1;
      const now = new Date().toISOString();
      const created: SupplierDispute = {
        id: `sd-new-${disputeCounter}`,
        code: `AIEC-SD-${disputeCounter}`,
        supplierId: po.supplierId,
        poId: po.id,
        kind: input.kind,
        paymentId: input.kind === 'amount' ? input.paymentId : undefined,
        retentionId: input.kind === 'retention_timing' ? input.retentionId : undefined,
        invoiceId: input.kind === 'invoice' ? input.invoiceId : undefined,
        position: input.position.trim(),
        claimedAmount: input.kind === 'amount' ? (input.claimedAmount ?? null) : null,
        threatensHalt: !!input.threatensHalt,
        raisedByRole: viewer.supplierId ? 'supplier' : 'admin',
        raisedByName: viewer.actor.name,
        raisedAt: now,
        status: 'open',
        round: 1,
        roundStartedAt: now,
        decisions: [],
        events: [],
        isDemo: true,
      };
      created.events = [{ id: `${created.id}-e1`, kind: 'raised', at: now, byName: viewer.actor.name, note: created.position }];
      supplierDisputes.push(created);
      if (viewer.supplierId) disputeMessage(created, 'supplier', viewer.actor.name, viewer.actor.id, `Dispute ${created.code} raised: ${created.position}`);
      syncSupplierDisputes(Date.now());
      syncCommitments(Date.now());
      return disputeViewOf(created, Date.now());
    }),

  resolveSupplierDispute: (disputeId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const d = byId(supplierDisputes, disputeId);
      if (!d) throw new RepositoryError('not_found');
      if (d.status !== 'open') throw new RepositoryError('invalid_state');
      const facts = { kind: d.kind, claimed: d.claimedAmount, alreadyGiven: given(d) };
      const amountIn = input.decision === 'uphold' ? 0 : (input.amount ?? 0);
      const problem = decisionProblem({ decision: input.decision, amount: amountIn, note: input.note }, facts);
      if (problem) throw new RepositoryError(problem);
      const note = input.note.trim();
      const at = new Date().toISOString();
      let amount = 0;
      let correction: DisputeCorrection = 'none';
      let correctionRef: string | null = null;
      if (input.decision !== 'uphold') {
        const reason = `Dispute ${d.code} decided ${input.decision === 'partial' ? 'in part' : 'for the supplier'}: ${note}`;
        if (d.kind === 'amount') {
          const p = byId(supplierPayments, d.paymentId ?? '');
          if (!p) throw new RepositoryError('not_found');
          amount = input.decision === 'partial' ? amountIn : (maxAmountOf(facts) ?? amountIn);
          if (p.status === 'executed') {
            correctionRef = pushPaymentAdjustment(p, 'top_up', amount, reason, actor).id;
            correction = 'payment_adjustment';
          } else if (p.status === 'pending_approval' || p.status === 'held') {
            patchInPlace(supplierPayments, p.id, { amount: p.amount + amount, events: paymentEvents(p, 'amount_changed', actor.name, reason) });
            correctionRef = p.id;
            correction = 'payment_amount';
          } else {
            // Approved and still inside its reversal window: it has to be taken back before its amount can change.
            throw new RepositoryError('payment_locked');
          }
        } else if (d.kind === 'retention_timing') {
          const r = byId(supplierRetentions, d.retentionId ?? '');
          if (!r) throw new RepositoryError('not_found');
          if (r.status !== 'held' && r.status !== 'paused') throw new RepositoryError('invalid_state');
          amount = r.amount;
          patchInPlace(supplierRetentions, r.id, { status: 'released', decidedAt: at, decidedBy: actor.name, decisionReason: reason });
          correctionRef = r.id;
          correction = 'retention_released';
        } else {
          const inv = byId(supplierInvoices, d.invoiceId ?? '');
          if (!inv) throw new RepositoryError('not_found');
          let working = inv;
          if (inv.status === 'rejected') {
            working = patchInPlace(supplierInvoices, inv.id, { status: 'open', rejectedReason: undefined, rejectedByName: undefined, rejectedAt: undefined, withdrawnBySupplier: undefined, events: invoiceEvents(inv, 'reinstated', actor.name, reason) });
          }
          const evaluated = evaluateInvoice(working);
          // Only a price difference can be accepted. A quantity that was never delivered is not AIEC's to waive.
          if (evaluated.lines.some((l) => l.issues.some((i) => i !== 'price_differs'))) {
            if (inv.status === 'rejected') patchInPlace(supplierInvoices, inv.id, { status: 'rejected', rejectedReason: inv.rejectedReason, rejectedByName: inv.rejectedByName, rejectedAt: inv.rejectedAt, withdrawnBySupplier: inv.withdrawnBySupplier, events: inv.events });
            throw new RepositoryError('not_actionable');
          }
          const ref = (l: SupplierInvoiceLine): InvoiceAdjustmentRef => ({ changeId: `dispute:${d.code}`, toPrice: l.unitPrice, acceptedBy: actor.name, acceptedAt: at, note });
          patchInPlace(supplierInvoices, working.id, {
            lines: working.lines.map((l, idx) => (evaluated.lines[idx]?.priceCheck === 'fail' ? { ...l, adjustment: ref(l) } : l)),
            events: invoiceEvents(byId(supplierInvoices, working.id)!, 'adjustment_accepted', actor.name, reason),
          });
          correctionRef = working.id;
          correction = 'invoice_accepted';
        }
      }
      const record: SupplierDisputeDecisionRecord = { id: `${d.id}-d${d.decisions.length + 1}`, decision: input.decision, amount, note, byName: actor.name, at, correction, correctionRef };
      patchInPlace(supplierDisputes, d.id, { status: 'resolved', decisions: [...d.decisions, record], events: disputeEvent(d, 'decided', actor.name, note) });
      const after = byId(supplierDisputes, d.id)!;
      disputeMessage(after, 'aiec', actor.name, actor.id, `Dispute ${d.code}: ${DECISION_WORDS[input.decision]}${amount > 0 ? ` (${formatINR(amount)})` : ''}. ${note}`);
      syncSupplierDisputes(Date.now());
      syncInvoiceMismatches(Date.now());
      syncCommitments(Date.now());
      return disputeViewOf(after, Date.now());
    }),

  reopenSupplierDispute: (disputeId, reason, byUserId) =>
    simulateWrite(() => {
      const viewer = threadViewer(byUserId);
      const d = byId(supplierDisputes, disputeId);
      if (!d) throw new RepositoryError('not_found');
      if (viewer.supplierId && viewer.supplierId !== d.supplierId) throw new RepositoryError('not_found');
      if (d.status !== 'resolved') throw new RepositoryError('invalid_state');
      const now = Date.now();
      if (!disputeCanReopen(d, now)) throw new RepositoryError('reopen_window_closed');
      if (reason.trim().length < NOTE_MIN) throw new RepositoryError('note_required');
      const at = new Date(now).toISOString();
      patchInPlace(supplierDisputes, d.id, { status: 'open', round: d.round + 1, roundStartedAt: at, events: disputeEvent(d, 'reopened', viewer.actor.name, reason) });
      const after = byId(supplierDisputes, d.id)!;
      if (viewer.supplierId) disputeMessage(after, 'supplier', viewer.actor.name, viewer.actor.id, `Dispute ${d.code} contested (round ${after.round}): ${reason.trim()}`);
      syncSupplierDisputes(now);
      syncCommitments(now);
      return disputeViewOf(after, now);
    }),

  flagDisputeProcessIssue: (disputeId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const d = byId(supplierDisputes, disputeId);
      if (!d) throw new RepositoryError('not_found');
      if (d.processFlag?.status === 'open') throw new RepositoryError('already_open');
      if (input.note.trim().length < NOTE_MIN) throw new RepositoryError('note_required');
      const at = new Date().toISOString();
      patchInPlace(supplierDisputes, d.id, { processFlag: { area: input.area, note: input.note.trim(), byName: actor.name, at, status: 'open' }, events: disputeEvent(d, 'process_flagged', actor.name, input.note) });
      syncCommitments(Date.now());
      return disputeViewOf(byId(supplierDisputes, d.id)!, Date.now());
    }),

  addressDisputeProcessIssue: (disputeId, note, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const d = byId(supplierDisputes, disputeId);
      if (!d || !d.processFlag) throw new RepositoryError('not_found');
      if (d.processFlag.status !== 'open') throw new RepositoryError('invalid_state');
      if (note.trim().length < NOTE_MIN) throw new RepositoryError('note_required');
      const at = new Date().toISOString();
      patchInPlace(supplierDisputes, d.id, { processFlag: { ...d.processFlag, status: 'addressed', addressedNote: note.trim(), addressedBy: actor.name, addressedAt: at }, events: disputeEvent(d, 'process_addressed', actor.name, note) });
      syncCommitments(Date.now());
      return disputeViewOf(byId(supplierDisputes, d.id)!, Date.now());
    }),

  /* --------------------------------------------- GST compliance (116) */
  getGstCompliance: (period, byUserId) =>
    simulateRead((): GstComplianceView => {
      adminOnly(byUserId);
      const now = Date.now();
      syncGstCompliance(now);
      return gstComplianceOf(period, now);
    }),

  recordSupplierGstCheck: (supplierId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const supplier = byId(suppliers, supplierId);
      if (!supplier) throw new RepositoryError('not_found');
      if (!supplier.gstin) throw new RepositoryError('no_gstin');
      const now = Date.now();
      if (input.lastReturnPeriod !== null && (!/^\d{4}-\d{2}$/.test(input.lastReturnPeriod) || input.lastReturnPeriod > periodOf(now))) throw new RepositoryError('invalid_period');
      if (input.standing !== 'active') {
        if (!input.effectiveFrom || !/^\d{4}-\d{2}-\d{2}$/.test(input.effectiveFrom) || input.effectiveFrom > new Date(now).toISOString().slice(0, 10)) throw new RepositoryError('invalid_date');
      }
      gstCheckCounter += 1;
      supplierGstChecks.push({
        id: `gsc-new-${gstCheckCounter}`,
        supplierId,
        gstin: supplier.gstin,
        standing: input.standing,
        lastReturnPeriod: input.lastReturnPeriod,
        effectiveFrom: input.standing !== 'active' ? input.effectiveFrom : undefined,
        checkedAt: new Date(now).toISOString(),
        checkedByName: actor.name,
        note: input.note?.trim() || undefined,
        isDemo: true,
      });
      syncGstCompliance(now);
      syncCommitments(now);
      const view = gstComplianceOf(null, now).suppliers.find((v) => v.supplierId === supplierId);
      if (!view) throw new RepositoryError('not_found');
      return view;
    }),

  handOverGstPeriod: (period, note, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const now = Date.now();
      if (!/^\d{4}-\d{2}$/.test(period) || period >= periodOf(now)) throw new RepositoryError('period_open');
      ensureGstHandovers(now);
      if (gstHandovers.some((h) => h.period === period)) throw new RepositoryError('already_handed_over');
      const view = gstComplianceOf(period, now);
      if (view.documents.length === 0) throw new RepositoryError('nothing_to_hand_over');
      gstHandoverCounter += 1;
      gstHandovers.push({ id: `gsh-${gstHandoverCounter}`, period, handedOverAt: new Date(now).toISOString(), byName: actor.name, note: note?.trim() || undefined, outputGst: view.output.gst, inputClaimable: view.input.claimable, atRisk: view.input.atRisk, isDemo: true });
      syncCommitments(now);
      return gstComplianceOf(period, now);
    }),

  /* --------------------------------------------- Supplier payment history (115) */
  getSupplierPaymentHistory: (filter, byUserId) =>
    simulateRead((): PaymentHistoryPage => {
      const viewer = threadViewer(byUserId);
      const now = Date.now();
      syncSupplierPayments(now);
      executeSupplierPayments(now);
      const all = historyMatching(filter, viewer);
      const offset = Math.max(0, filter.offset ?? 0);
      const page = filter.limit && filter.limit > 0 ? all.slice(offset, offset + filter.limit) : all.slice(offset);
      const scope = supplierPayments.filter((p) => p.status === 'executed' && (!viewer.supplierId || p.supplierId === viewer.supplierId));
      const seen = new Map<string, string>();
      for (const p of scope) seen.set(p.supplierId, byId(suppliers, p.supplierId)?.name ?? '');
      return {
        entries: page,
        matched: all.length,
        totals: {
          gross: all.reduce((n, e) => n + e.amount, 0),
          adjustments: all.reduce((n, e) => n + e.adjustmentsTotal, 0),
          net: all.reduce((n, e) => n + e.netAmount, 0),
        },
        hasMore: filter.limit && filter.limit > 0 ? offset + filter.limit < all.length : false,
        suppliers: [...seen].map(([id, name]) => ({ id, name })).sort((a, b) => a.name.localeCompare(b.name)),
        viewer: viewer.supplierId ? 'supplier' : 'admin',
      };
    }),

  getSupplierPaymentHistoryEntry: (paymentId, byUserId) =>
    simulateRead((): PaymentHistoryDetail => {
      const viewer = threadViewer(byUserId);
      return historyDetailOf(executedPaymentOrThrow(paymentId, viewer), viewer);
    }),

  recordPaymentAdjustment: (paymentId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const p = executedPaymentOrThrow(paymentId, { supplierId: null });
      if (!Number.isFinite(input.amount) || !(input.amount > 0)) throw new RepositoryError('invalid_amount');
      if (input.reason.trim().length < 8) throw new RepositoryError('note_required');
      const entry = historyEntryOf(p);
      // A credit can only give back what the payment still stands at.
      if (input.direction === 'credit' && input.amount > entry.netAmount) throw new RepositoryError('exceeds_payment');
      pushPaymentAdjustment(p, input.direction, input.amount, input.reason.trim(), actor);
      return historyDetailOf(p, { supplierId: null });
    }),

  queryPayment: (paymentId, note, byUserId) =>
    simulateWrite(() => {
      const viewer = threadViewer(byUserId);
      if (!viewer.supplierId) throw new RepositoryError('forbidden');
      const p = executedPaymentOrThrow(paymentId, viewer);
      if (note.trim().length < 8) throw new RepositoryError('note_required');
      const po = byId(supplierPurchaseOrders, p.poId);
      const at = new Date().toISOString();
      paymentQueryCounter += 1;
      supplierPaymentQueries.push({ id: `spq-${paymentQueryCounter}`, paymentId: p.id, note: note.trim(), byName: viewer.actor.name, at, isDemo: true });
      if (po) {
        pushSupplierMessage(ensureSupplierThread(p.supplierId, po.id), {
          author: 'supplier',
          authorName: viewer.actor.name,
          authorUserId: viewer.actor.id,
          body: `Question about payment ${p.code} (${formatINR(p.amount)}) for ${po.code}: ${note.trim()}`,
          channel: 'in_app',
          at,
          expectsReply: true,
          poRef: po.id,
        });
      }
      syncCommitments(Date.now());
      return historyDetailOf(p, viewer);
    }),

  /* --------------------------------------------- Supplier payment schedule (114) */
  getSupplierPaymentSchedule: (byUserId) =>
    simulateRead((): SupplierPaymentSchedule => {
      adminOnly(byUserId);
      const now = Date.now();
      syncSupplierPayments(now);
      executeSupplierPayments(now);
      const { items, dropped } = supplierScheduleOf(now);
      const seen = new Map<string, string>();
      for (const i of items) seen.set(i.supplierId, i.supplierName);
      return {
        items: items.sort((a, b) => (a.date ?? '9999') < (b.date ?? '9999') ? -1 : (a.date ?? '9999') > (b.date ?? '9999') ? 1 : b.amount - a.amount),
        suppliers: [...seen].map(([id, name]) => ({ id, name })).sort((a, b) => a.name.localeCompare(b.name)),
        dropped,
        totals: outflowTotals(items, now),
      };
    }),

  getUpcomingSupplierOutflows: (byUserId) =>
    simulateRead((): OutflowTotals => {
      adminOnly(byUserId);
      const now = Date.now();
      syncSupplierPayments(now);
      return outflowTotals(supplierScheduleOf(now).items, now);
    }),

  /* --------------------------------------------- Supplier invoice matching (113) */
  getSupplierInvoiceBoard: (byUserId) =>
    simulateRead((): SupplierInvoiceBoard => {
      const viewer = threadViewer(byUserId);
      const now = Date.now();
      syncInvoiceMismatches(now);
      const mine = (supplierId: string) => !viewer.supplierId || viewer.supplierId === supplierId;
      const invoices = supplierInvoices
        .filter((i) => mine(i.supplierId))
        .map(invoiceViewOf)
        .sort((a, b) => Number(b.status === 'mismatch') - Number(a.status === 'mismatch') || (a.submittedAt < b.submittedAt ? 1 : -1));
      const sentPos = supplierPurchaseOrders.filter((po) => po.status === 'sent' && !!po.supplierId && mine(po.supplierId) && (po.lineItems ?? []).length > 0);
      const waiting: WaitingForInvoice[] = sentPos
        .map((po) => ({ po, deliveredAt: paymentDeliveredAt(po), gate: invoiceGateOfPo(po) }))
        .filter((x): x is { po: SupplierPurchaseOrder; deliveredAt: string; gate: InvoiceGate } => !!x.deliveredAt && (x.gate === 'no_invoice' || x.gate === 'incomplete'))
        .map(({ po, deliveredAt, gate }) => ({ poId: po.id, poCode: po.code, supplierId: po.supplierId!, supplierName: byId(suppliers, po.supplierId!)?.name ?? '', siteName: shipmentSite(po.dealId)?.siteName ?? '', deliveredAt, gate }));
      const submittable: SubmittablePo[] = sentPos
        .map((po) => ({
          poId: po.id,
          poCode: po.code,
          siteName: shipmentSite(po.dealId)?.siteName ?? '',
          supplierId: po.supplierId!,
          supplierName: byId(suppliers, po.supplierId!)?.name ?? '',
          lines: (po.lineItems ?? []).map((l) => ({
            id: l.id,
            description: l.description,
            orderedQty: l.quantity,
            orderPrice: l.agreedUnitPrice,
            deliveredQty: acceptedQtyOf(po, l),
            billedQty: supplierInvoices.filter((i) => i.poId === po.id && i.status === 'open').flatMap((i) => i.lines).filter((x) => x.lineItemId === l.id).reduce((n, x) => n + x.quantity, 0),
          })),
        }))
        .filter((p) => p.lines.some((l) => l.billedQty < l.orderedQty));
      return { invoices, waiting, submittable, viewer: viewer.supplierId ? 'supplier' : 'admin' };
    }),

  submitSupplierInvoice: (input, byUserId) =>
    simulateWrite(() => {
      const viewer = threadViewer(byUserId);
      const po = byId(supplierPurchaseOrders, input.poId);
      if (!po || po.status !== 'sent' || !po.supplierId) throw new RepositoryError('not_found');
      if (viewer.supplierId && po.supplierId !== viewer.supplierId) throw new RepositoryError('forbidden');
      const number = input.invoiceNumber.trim();
      if (number.length < 2) throw new RepositoryError('number_required');
      if (!/^\d{4}-\d{2}-\d{2}$/.test(input.invoiceDate) || new Date(input.invoiceDate).getTime() > Date.now() + 86_400_000) throw new RepositoryError('invalid_date');
      if (input.lines.length < INVOICE_MIN_ITEMS || input.lines.some((l) => !(l.quantity > 0) || !(l.unitPrice > 0) || !Number.isFinite(l.quantity) || !Number.isFinite(l.unitPrice) || l.description.trim().length < 2)) throw new RepositoryError('invalid_lines');
      // The same number twice from one supplier is the same invoice sent again, not a new one.
      if (supplierInvoices.some((i) => i.supplierId === po.supplierId && i.status === 'open' && i.invoiceNumber.toLowerCase() === number.toLowerCase())) throw new RepositoryError('duplicate_invoice');
      const now = new Date().toISOString();
      supplierInvoiceCounter += 1;
      const created: SupplierInvoice = {
        id: `sinv-new-${supplierInvoiceCounter}`,
        code: `AIEC-SI-${2100 + supplierInvoiceCounter}`,
        poId: po.id,
        supplierId: po.supplierId,
        invoiceNumber: number,
        invoiceDate: input.invoiceDate,
        gstPercent: gstRateOn(input.invoiceDate),
        documentName: input.documentName?.trim() || undefined,
        lines: input.lines.map((l) => ({ lineItemId: l.lineItemId && (po.lineItems ?? []).some((x) => x.id === l.lineItemId) ? l.lineItemId : null, description: l.description.trim(), quantity: l.quantity, unitPrice: l.unitPrice })),
        submittedAt: now,
        submittedByName: viewer.actor.name,
        submittedByRole: viewer.supplierId ? 'supplier' : 'admin',
        status: 'open',
        events: [],
        isDemo: true,
      };
      created.events = [{ id: `${created.id}-e1`, kind: 'submitted', at: now, byName: viewer.actor.name }];
      supplierInvoices.push(created);
      syncInvoiceMismatches(Date.now());
      syncCommitments(Date.now());
      return invoiceViewOf(byId(supplierInvoices, created.id)!);
    }),

  acceptInvoiceAdjustment: (invoiceId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const inv = byId(supplierInvoices, invoiceId);
      if (!inv) throw new RepositoryError('not_found');
      if (inv.status !== 'open') throw new RepositoryError('invalid_state');
      const line = inv.lines[input.lineIndex];
      if (!line) throw new RepositoryError('not_found');
      const po = byId(supplierPurchaseOrders, inv.poId);
      const change = catalogPriceChanges.find((c) => c.id === input.changeId);
      if (!po || !change || !explainsInvoicePrice(change, inv.supplierId, po.sentAt, line.unitPrice)) throw new RepositoryError('adjustment_invalid');
      const ref: InvoiceAdjustmentRef = { changeId: change.id, toPrice: change.toPrice, acceptedBy: actor.name, acceptedAt: new Date().toISOString(), note: input.note?.trim() || undefined };
      const updated = patchInPlace(supplierInvoices, inv.id, {
        lines: inv.lines.map((l, i) => (i === input.lineIndex ? { ...l, adjustment: ref } : l)),
        events: invoiceEvents(inv, 'adjustment_accepted', actor.name, input.note),
      });
      syncInvoiceMismatches(Date.now());
      syncCommitments(Date.now());
      return invoiceViewOf(updated);
    }),

  rejectSupplierInvoice: (invoiceId, reason, byUserId) =>
    simulateWrite(() => {
      const viewer = threadViewer(byUserId);
      const inv = byId(supplierInvoices, invoiceId);
      if (!inv) throw new RepositoryError('not_found');
      // Admin sends any open invoice back. A supplier may only take back their own, and only while it does not match.
      const own = !!viewer.supplierId && viewer.supplierId === inv.supplierId;
      if (viewer.supplierId ? !own : viewer.actor.role !== 'admin') throw new RepositoryError('forbidden');
      if (inv.status !== 'open') throw new RepositoryError('invalid_state');
      if (own && evaluateInvoice(inv).status !== 'mismatch') throw new RepositoryError('invalid_state');
      if (reason.trim().length < 4) throw new RepositoryError('note_required');
      const at = new Date().toISOString();
      const actor = viewer.actor;
      const updated = patchInPlace(supplierInvoices, inv.id, {
        status: 'rejected',
        rejectedReason: reason.trim(),
        rejectedByName: actor.name,
        rejectedAt: at,
        withdrawnBySupplier: own || undefined,
        events: invoiceEvents(inv, own ? 'withdrawn' : 'rejected', actor.name, reason),
      });
      const po = byId(supplierPurchaseOrders, inv.poId);
      const supplier = byId(suppliers, inv.supplierId);
      if (!own && po && supplier && supplierUserFor(supplier)) {
        pushSupplierMessage(ensureSupplierThread(supplier.id, po.id), {
          author: 'aiec',
          authorName: actor.name,
          authorUserId: actor.id,
          body: `We could not accept invoice ${inv.invoiceNumber} for ${po.code}: ${reason.trim()} Please send a corrected invoice.`,
          channel: 'in_app',
          at,
          expectsReply: true,
          poRef: po.id,
        });
      }
      const alert = alerts.find((a) => a.relatedId === inv.id && a.titleKey === 'supplierInvoiceMatching.alert.mismatch' && a.status !== 'resolved');
      if (alert) patchInPlace(alerts, alert.id, { status: 'resolved', resolvedAt: at, resolvedBy: actor.name, resolutionNote: own ? 'Withdrawn by the supplier to correct it.' : 'Sent back to the supplier.' });
      syncCommitments(Date.now());
      return invoiceViewOf(updated);
    }),

  /* --------------------------------------------- Payment release (112) */
  getSupplierPaymentChains: (byUserId) =>
    simulateRead((): PaymentChainSummary[] => {
      adminOnly(byUserId);
      const now = Date.now();
      syncSupplierPayments(now);
      executeSupplierPayments(now);
      syncPaymentAnomalies(now);
      return supplierPurchaseOrders
        .filter((po) => po.status === 'sent' && !!po.supplierId && !!po.paymentTerms && paymentTotalOf(po) > 0)
        .map((po): PaymentChainSummary => {
          const chain = paymentChainOf(po, null, now);
          const paidParts = chain.parts.filter((p) => p.state === 'paid').length;
          return {
            poId: po.id,
            poCode: po.code,
            supplierName: chain.supplierName,
            siteName: chain.siteName,
            total: chain.total,
            paid: chain.paid,
            custom: chain.custom,
            state: paidParts === chain.parts.length ? 'complete' : chain.paid > 0 || chain.parts.some((p) => p.state !== 'not_due') ? 'in_progress' : 'awaiting',
            anomaly: chain.anomalies.length > 0,
            pending: chain.parts.filter((p) => p.state === 'pending' || p.state === 'held').length,
          };
        })
        .sort((a, b) => Number(b.anomaly) - Number(a.anomaly) || b.pending - a.pending || (a.state === 'complete' ? 1 : 0) - (b.state === 'complete' ? 1 : 0) || (a.poCode < b.poCode ? 1 : -1));
    }),

  getSupplierPaymentChain: (ref, byUserId) =>
    simulateRead((): PaymentChainView => {
      adminOnly(byUserId);
      const now = Date.now();
      syncSupplierPayments(now);
      executeSupplierPayments(now);
      syncPaymentAnomalies(now);
      const payment = ref.paymentId ? byId(supplierPayments, ref.paymentId) : undefined;
      const poId = ref.poId ?? payment?.poId;
      if (!poId) throw new RepositoryError('not_found');
      return paymentChainOf(chainPoOrThrow(poId), payment?.id ?? null, now);
    }),

  adjustPaymentSplit: (poId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const po = chainPoOrThrow(poId);
      const terms = po.paymentTerms!;
      const issues = checkDeviation(terms, { upfrontPct: input.upfrontPct, retentionPct: input.retentionPct }, input.reason);
      if (issues.length > 0) throw new RepositoryError(issues[0]);
      const after = { ...terms, upfrontPct: input.upfrontPct, retentionPct: input.retentionPct };
      if (deviationIncreasesRisk(terms, after) && !input.acknowledgeRisk) throw new RepositoryError('risk_unconfirmed');
      const total = paymentTotalOf(po);
      const netDays = po.agreementTerms?.paymentTermsDays ?? null;
      const before = paymentSchedule(total, terms, netDays);
      const next = paymentSchedule(total, after, netDays);
      const amountOf = (parts: typeof before, kind: string) => parts.find((p) => p.kind === kind)?.amount ?? 0;
      const retention = supplierRetentions.find((r) => r.poId === po.id);
      // A portion already approved or paid is history. Changing what is still open must not rewrite what has gone.
      for (const kind of ['upfront', 'balance', 'retention'] as const) {
        if (amountOf(before, kind) === amountOf(next, kind)) continue;
        const mine = supplierPayments.find((p) => p.poId === po.id && p.part === kind);
        if (mine && (mine.status === 'approved' || mine.status === 'executed')) throw new RepositoryError('part_locked');
        if (kind === 'retention' && retention && retention.status === 'released') throw new RepositoryError('part_locked');
      }
      const now = Date.now();
      const at = new Date(now).toISOString();
      const deviation: PaymentDeviation = {
        id: `dev-${po.id}-${(terms.deviations?.length ?? 0) + 1}`,
        at,
        byName: actor.name,
        reason: input.reason.trim(),
        before: { upfrontPct: terms.upfrontPct, retentionPct: terms.retentionPct },
        after: { upfrontPct: input.upfrontPct, retentionPct: input.retentionPct },
      };
      patchInPlace(supplierPurchaseOrders, po.id, { paymentTerms: { ...after, custom: true, deviations: [...(terms.deviations ?? []), deviation] } });
      // The amounts still open follow the new split; the retention record 100 holds follows too.
      for (const kind of ['upfront', 'balance', 'retention'] as const) {
        const amount = amountOf(next, kind);
        const mine = supplierPayments.find((p) => p.poId === po.id && p.part === kind);
        if (mine && mine.amount !== amount) patchInPlace(supplierPayments, mine.id, { amount, events: paymentEvents(mine, 'amount_changed', actor.name, input.reason) });
      }
      if (retention && retention.status !== 'released' && retention.status !== 'withheld') patchInPlace(supplierRetentions, retention.id, { pct: input.retentionPct, amount: amountOf(next, 'retention') });
      syncCommitments(now);
      return paymentChainOf(byId(supplierPurchaseOrders, po.id)!, null, now);
    }),

  releasePortionEarly: (poId, part, reason, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const po = chainPoOrThrow(poId);
      if (part === 'retention') throw new RepositoryError('invalid_input');
      if (reason.trim().length < DEVIATION_REASON_MIN) throw new RepositoryError('reason_required');
      if (supplierPayments.some((p) => p.poId === po.id && p.part === part)) throw new RepositoryError('already_fired');
      const schedule = paymentSchedule(paymentTotalOf(po), po.paymentTerms!, po.agreementTerms?.paymentTermsDays ?? null).find((p) => p.kind === part);
      if (!schedule || schedule.amount <= 0) throw new RepositoryError('invalid_input');
      const now = Date.now();
      const at = new Date(now).toISOString();
      supplierPaymentCounter += 1;
      const created: SupplierPayment = {
        id: `spay-new-${supplierPaymentCounter}`,
        code: `AIEC-SP-${3100 + supplierPaymentCounter}`,
        poId: po.id,
        supplierId: po.supplierId!,
        dealId: po.dealId,
        part,
        trigger: schedule.trigger,
        amount: schedule.amount,
        triggeredAt: at,
        dueAt: at,
        status: 'pending_approval',
        origin: 'override',
        overrideReason: reason.trim(),
        events: [{ id: `spay-new-${supplierPaymentCounter}-e1`, kind: 'triggered', at, byName: actor.name, note: reason.trim() }],
        isDemo: true,
      };
      supplierPayments.push(created);
      syncCommitments(now);
      return paymentChainOf(po, created.id, now);
    }),

  /* --------------------------------------------- Supplier payments (111) */
  getSupplierPaymentQueue: (byUserId) =>
    simulateRead((): SupplierPaymentQueue => {
      adminOnly(byUserId);
      const now = Date.now();
      syncSupplierPayments(now);
      executeSupplierPayments(now);
      const views = supplierPayments.map((p) => paymentViewOf(p, now));
      const byDue = (a: SupplierPaymentView, b: SupplierPaymentView) => (a.dueAt < b.dueAt ? -1 : 1);
      const pending = views.filter((v) => v.status === 'pending_approval').sort(byDue);
      const toApprove = pending.filter((v) => !v.flags.some((f) => f.severity === 'block'));
      const waiting = pending.filter((v) => v.flags.some((f) => f.severity === 'block'));
      const held = views.filter((v) => v.status === 'held').sort(byDue);
      const cutoff = now - 14 * 86_400_000;
      const recent = views
        .filter((v) => v.status === 'approved' || (v.status === 'executed' && !!v.executedAt && new Date(v.executedAt).getTime() >= cutoff))
        .sort((a, b) => ((a.approvedAt ?? '') < (b.approvedAt ?? '') ? 1 : -1));
      const routine = toApprove.filter((v) => v.routine);
      return {
        toApprove,
        waiting,
        held,
        recent,
        totals: { toApproveAmount: toApprove.reduce((n, v) => n + v.amount, 0), waitingAmount: waiting.reduce((n, v) => n + v.amount, 0), heldAmount: held.reduce((n, v) => n + v.amount, 0), routineCount: routine.length, routineAmount: routine.reduce((n, v) => n + v.amount, 0) },
        limits: { routineLimit: ROUTINE_LIMIT, reversalMinutes: REVERSAL_WINDOW / 60_000 },
      };
    }),

  approveSupplierPayment: (paymentId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const now = Date.now();
      const approved = approvePaymentNow(paymentOrThrow(paymentId), actor, !!input.acknowledgeFlags, now);
      syncCommitments(now);
      return paymentViewOf(approved, now);
    }),

  holdSupplierPayment: (paymentId, reason, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const p = paymentOrThrow(paymentId);
      if (p.status !== 'pending_approval') throw new RepositoryError('invalid_state');
      if (reason.trim().length < HOLD_REASON_MIN) throw new RepositoryError('note_required');
      const now = Date.now();
      const held = patchInPlace(supplierPayments, p.id, { status: 'held', heldReason: reason.trim(), heldAt: new Date(now).toISOString(), heldByName: actor.name, events: paymentEvents(p, 'held', actor.name, reason) });
      syncCommitments(now);
      return paymentViewOf(held, now);
    }),

  releaseSupplierPaymentHold: (paymentId, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const p = paymentOrThrow(paymentId);
      if (p.status !== 'held') throw new RepositoryError('invalid_state');
      const now = Date.now();
      // Back in the queue; the fact it was held is kept on its record.
      const back = patchInPlace(supplierPayments, p.id, { status: 'pending_approval', events: paymentEvents(p, 'hold_released', actor.name) });
      syncCommitments(now);
      return paymentViewOf(back, now);
    }),

  reverseSupplierPaymentApproval: (paymentId, reason, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const p = paymentOrThrow(paymentId);
      const now = Date.now();
      if (p.status === 'executed') throw new RepositoryError('window_closed');
      if (p.status !== 'approved') throw new RepositoryError('invalid_state');
      if (!p.reversibleUntil || new Date(p.reversibleUntil).getTime() <= now) throw new RepositoryError('window_closed');
      if (reason.trim().length < HOLD_REASON_MIN) throw new RepositoryError('note_required');
      const back = patchInPlace(supplierPayments, p.id, { status: 'pending_approval', approvedAt: undefined, approvedByName: undefined, reversibleUntil: undefined, events: paymentEvents(p, 'reversed', actor.name, reason) });
      syncCommitments(now);
      return paymentViewOf(back, now);
    }),

  approveSupplierPaymentsBatch: (paymentIds, byUserId) =>
    simulateWrite((): BatchApproveResult => {
      const actor = adminOnly(byUserId);
      const now = Date.now();
      const approved: string[] = [];
      const skipped: BatchApproveResult['skipped'] = [];
      for (const id of [...new Set(paymentIds)]) {
        const p = byId(supplierPayments, id);
        if (!p) {
          skipped.push({ id, reason: 'not_found' });
          continue;
        }
        if (p.status !== 'pending_approval') {
          skipped.push({ id, reason: 'not_pending' });
          continue;
        }
        // A batch is for the routine only: anything flagged, or large, is looked at by itself.
        if (!isRoutine(paymentFlags(p), p.amount)) {
          skipped.push({ id, reason: 'not_routine' });
          continue;
        }
        approvePaymentNow(p, actor, false, now);
        approved.push(id);
      }
      syncCommitments(now);
      return { approved, skipped };
    }),

  /* --------------------------------- Technician home (121) */
  getTechnicianHome: (technicianId) =>
    simulateRead((): TechnicianHome => {
      const user = byId(users, technicianId);
      if (!user || user.role !== 'technician') throw new RepositoryError('forbidden');
      const now = Date.now();
      sendDueSos(now);
      const mine = jobs.filter((j) => isOnJob(j, technicianId));
      const clashes = clashesOf(mine);
      const clashCodesOf = (j: Job) => {
        const group = clashes.find((c) => c.jobIds.includes(j.id));
        return group ? group.jobIds.filter((id) => id !== j.id).map((id) => byId(jobs, id)?.code ?? id) : [];
      };
      const view = (j: Job) => technicianJobViewOf(j, technicianId, clashCodesOf(j));
      const rank = (j: Job) => (j.status === 'in_progress' ? 0 : j.status === 'qc_pending' || j.status === 'handover_pending' ? 1 : j.status === 'scheduled' || j.status === 'materials_pending' ? 2 : 3);
      const todays = mine
        .filter((j) => bucketOf(j, now) === 'today')
        .sort((a, b) => rank(a) - rank(b) || a.scheduledFor.localeCompare(b.scheduledFor))
        .map(view);
      const upcoming = mine
        .filter((j) => bucketOf(j, now) === 'upcoming')
        .sort((a, b) => a.scheduledFor.localeCompare(b.scheduledFor))
        .map(view);
      const pay = commissions.filter((c) => c.userId === technicianId && (c.status === 'approved' || c.status === 'projected'));
      const score = user.status === 'active' ? technicianScoreOf(user) : null;
      const last = fieldSosAttempts.filter((a) => a.userId === technicianId).sort((a, b) => b.startedAt.localeCompare(a.startedAt))[0];
      return {
        technicianId,
        todays,
        upcoming,
        clashes: clashes.map((c) => ({ date: c.date, codes: c.jobIds.map((id) => byId(jobs, id)?.code ?? id) })),
        stats: {
          completedThisMonth: mine.filter((j) => j.status === 'completed' && !!j.completedAt && sameMonth(j.completedAt, now)).length,
          qualityScore: score ? score.qcPassRate : null,
          pendingPayout: pay.reduce((n, c) => n + c.amount, 0),
          pendingPayoutCount: pay.length,
        },
        sos: last && now - new Date(last.startedAt).getTime() <= SOS_FOLLOW ? fieldSosViewOf(last) : null,
        onDuty: !!user.onDuty,
        checkedIn: (() => {
          const open = siteCheckIns.filter((v) => v.userId === technicianId && !v.checkOutAt).sort((a, b) => b.checkInAt.localeCompare(a.checkInAt))[0];
          const job = open ? byId(jobs, open.jobId) : null;
          return open && job ? { visitId: open.id, jobId: job.id, code: job.code, siteName: job.siteName, since: open.checkInAt, stale: isStale(open, now) } : null;
        })(),
      };
    }),

  getTechnicianJob: (jobId, technicianId) =>
    simulateRead((): TechnicianJobDetail => {
      const user = byId(users, technicianId);
      const job = byId(jobs, jobId);
      if (!user || user.role !== 'technician') throw new RepositoryError('forbidden');
      if (!job) throw new RepositoryError('not_found');
      // A technician sees the jobs they are on and no one else's.
      if (!isOnJob(job, technicianId)) throw new RepositoryError('forbidden');
      const deal = byId(deals, job.dealId);
      const lead = deal ? resolveLead(deal.leadId) : null;
      const customerUser = deal?.customerId ? byId(users, deal.customerId) : undefined;
      const clashes = clashesOf(jobs.filter((j) => isOnJob(j, technicianId)));
      const group = clashes.find((c) => c.jobIds.includes(job.id));
      const notesOf = (leadId: string): JobNoteView[] => {
        const own = leadTimeline
          .filter((e) => e.leadId === leadId && e.kind === 'note_added' && !!e.detail)
          .map<JobNoteView>((e) => ({ id: e.id, source: 'survey', topic: e.topic ?? 'other', text: e.detail as string, at: e.at, byName: e.actorName }));
        const terms = deal ? dealTermsRecords.find((t) => t.dealId === deal.id) : undefined;
        const fromTerms: JobNoteView[] = [];
        if (terms?.specialTermsNotes.trim()) fromTerms.push({ id: `${terms.id}-notes`, source: 'terms', topic: 'other', text: terms.specialTermsNotes, at: terms.updatedAt, byName: 'AIEC' });
        for (const a of terms?.amendments ?? []) fromTerms.push({ id: a.id, source: 'terms', topic: 'other', text: a.note, at: a.amendedAt, byName: a.amendedBy });
        return [...own, ...fromTerms].sort((a, b) => b.at.localeCompare(a.at));
      };
      const notes = lead ? notesOf(lead.id) : [];
      // A customer with earlier installations: contact preferences and site access can sensibly carry over, but only as notes to check.
      const earlier = deal?.customerId
        ? jobs.filter((j) => j.id !== job.id && byId(deals, j.dealId)?.customerId === deal.customerId && j.scheduledFor < job.scheduledFor).sort((a, b) => a.scheduledFor.localeCompare(b.scheduledFor))
        : [];
      const spec = lead?.spec;
      return {
        job: technicianJobViewOf(job, technicianId, group ? group.jobIds.filter((id) => id !== job.id).map((id) => byId(jobs, id)?.code ?? id) : []),
        customer: {
          name: customerUser?.name ?? lead?.contactName ?? null,
          company: lead?.builderName ?? null,
          phone: lead?.contactPhone ?? customerUser?.phone ?? null,
          email: lead?.contactEmail ?? customerUser?.email ?? null,
          preferredLanguage: lead?.preferredLanguage ?? customerUser?.preferredLanguage ?? null,
        },
        site: {
          name: job.siteName,
          address: job.address,
          city: lead?.city ?? null,
          pincode: lead?.pincode ?? null,
          location: job.location,
          shaft: spec ? { widthMm: spec.shaftWidthMm ?? null, depthMm: spec.shaftDepthMm ?? null, pitMm: spec.pitDepthMm ?? null, headroomMm: spec.headroomMm ?? null, floors: spec.floors, machineRoom: spec.machineRoom } : null,
        },
        spec: lead ? lockedSpecOf(lead.id) : null,
        materials: jobMaterialsOf(job.dealId),
        team: peopleOn(job).map<JobTeamMember>((id) => {
          const u = byId(users, id);
          const member = (job.crew ?? []).find((c) => c.userId === id);
          return { userId: id, name: u?.name ?? '', role: id === job.technicianId ? 'lead' : 'assistant', phone: u?.phone ?? '', stepCount: id === job.technicianId ? 0 : (member?.stepIds.length ?? 0), isYou: id === technicianId };
        }),
        onSite: (() => {
          const visits = siteCheckIns.filter((v) => v.jobId === job.id);
          const mineOpen = visits.find((v) => v.userId === technicianId && !v.checkOutAt);
          return {
            now: peopleOn(job).flatMap((id) => {
              const t = timeOf(visits, id, Date.now());
              return t.onSiteNow && t.since ? [{ name: byId(users, id)?.name ?? '', since: t.since }] : [];
            }),
            minutes: visits.reduce((sum, v) => sum + visitMinutes(v, Date.now()), 0),
            days: new Set(visits.filter((v) => v.checkOutAt || !isStale(v, Date.now())).map((v) => dayKey(v.checkInAt))).size,
            mine: mineOpen ? (isStale(mineOpen, Date.now()) ? ('stale' as const) : ('in' as const)) : ('out' as const),
          };
        })(),
        notes,
        repeat: earlier.length
          ? {
              earlierJobs: earlier.map((j) => ({ code: j.code, siteName: j.siteName, status: j.status, at: j.completedAt ?? j.startedAt ?? j.scheduledFor })),
              carried: notes.filter((n) => n.topic === 'access' || n.topic === 'contact'),
            }
          : null,
      };
    }),

  beginFieldSos: (userId, location) =>
    simulateWrite((): FieldSosView => {
      const user = byId(users, userId);
      if (!user || (user.role !== 'technician' && user.role !== 'surveyor')) throw new RepositoryError('forbidden');
      const now = Date.now();
      sendDueSos(now);
      // A second press inside the same emergency is the same emergency: one alert, not a stack of them.
      const recent = fieldSosAttempts.find((a) => a.userId === userId && a.status !== 'cancelled' && now - new Date(a.startedAt).getTime() < SOS_SAME_INCIDENT);
      if (recent) return fieldSosViewOf(recent);
      fieldSosCounter += 1;
      const openJob = jobs.find((j) => isOnJob(j, userId) && isActiveJob(j));
      const created: FieldSosAttempt = {
        id: `sos-${fieldSosCounter}`,
        userId,
        startedAt: new Date(now).toISOString(),
        sendsAt: new Date(now + SOS_CANCEL_WINDOW_MS).toISOString(),
        status: 'pending',
        location: location ?? user.location ?? openJob?.location,
        jobId: openJob?.id,
        isDemo: true,
      };
      fieldSosAttempts.push(created);
      return fieldSosViewOf(created);
    }),

  cancelFieldSos: (attemptId, userId) =>
    simulateWrite((): FieldSosView => {
      const a = byId(fieldSosAttempts, attemptId);
      if (!a) throw new RepositoryError('not_found');
      if (a.userId !== userId) throw new RepositoryError('forbidden');
      const now = Date.now();
      // The window is the window: at the moment it closes the SOS is sent, and it can no longer be taken back.
      sendDueSos(now);
      const current = byId(fieldSosAttempts, attemptId)!;
      if (current.status !== 'pending') throw new RepositoryError(current.status === 'cancelled' ? 'invalid_state' : 'too_late');
      patchInPlace(fieldSosAttempts, a.id, { status: 'cancelled', cancelledAt: new Date(now).toISOString() });
      return fieldSosViewOf(byId(fieldSosAttempts, a.id)!);
    }),

  /* --------------------------------- Installation SOP checklist (123) */
  getInstallationSop: (jobId, technicianId) =>
    simulateRead((): InstallationSopView => {
      const { job } = sopActor(jobId, technicianId);
      return installationSopViewOf(job, technicianId);
    }),

  startInstallation: (jobId, technicianId, capturedAt) =>
    simulateWrite((): InstallationSopView => {
      const { job } = sopActor(jobId, technicianId);
      // Only the lead starts the job: assistants join a job that is already under way.
      if (roleOf(job, technicianId) !== 'lead') throw new RepositoryError('not_yours');
      if (job.status === 'on_hold') throw new RepositoryError('job_on_hold');
      if (job.status !== 'scheduled') throw new RepositoryError(job.status === 'materials_pending' ? 'materials_not_confirmed' : 'invalid_state');
      if (!sopMaterialsConfirmed(job)) throw new RepositoryError('materials_not_confirmed');
      const now = Date.now();
      // Next week's job is not started today.
      if (dayKey(job.scheduledFor) > dayKey(now)) throw new RepositoryError('not_scheduled_yet');
      const at = capturedAt ?? new Date(now).toISOString();
      const bad = capturedAtProblem(at, new Date(new Date(job.scheduledFor).getTime() - 86_400_000).toISOString(), now);
      if (bad) throw new RepositoryError(`captured_${bad}`);
      const version = installVersionInForce(installSopVersions, now) ?? installSopVersions[installSopVersions.length - 1];
      const started = patchInPlace(jobs, job.id, { status: 'in_progress' as const, startedAt: at, sopVersion: version.version, steps: withCurrent(job.steps, version.steps, null) });
      return installationSopViewOf(started, technicianId);
    }),

  attachStepEvidence: (jobId, stepId, slotId, media, technicianId) =>
    simulateWrite((): InstallationSopView => {
      const { job: raw, user, def } = sopActor(jobId, technicianId, stepId);
      const job = sopWorkable(raw);
      const spec = sopSpecOf(job);
      const step = job.steps.find((x) => x.id === stepId) as JobStep;
      if (isDone(step)) throw new RepositoryError('already_done');
      const slot = slotsFor(def as InstallSopStepDef, spec).find((sl) => sl.id === slotId);
      if (!slot && slotId !== FINDING_SLOT) throw new RepositoryError('not_found');
      const problem = evidenceProblem(slot ? slot.kind : null, media);
      if (problem) throw new RepositoryError(problem);
      if (media.previewUrl.length > SOP_PHOTO_MAX) throw new RepositoryError('photo_too_large');
      const bad = capturedAtProblem(media.capturedAt, job.startedAt ?? job.scheduledFor, Date.now());
      if (bad) throw new RepositoryError(`captured_${bad}`);
      sopEvidenceCounter += 1;
      const at = new Date().toISOString();
      const fresh: JobEvidence = {
        id: `ev-new-${sopEvidenceCounter}`,
        slotId,
        kind: media.kind,
        fileName: media.fileName,
        previewUrl: media.previewUrl,
        ...(media.mediaUrl ? { mediaUrl: media.mediaUrl } : {}),
        mimeType: media.mimeType,
        sizeBytes: media.sizeBytes,
        ...(media.durationS !== undefined ? { durationS: media.durationS } : {}),
        capturedAt: media.capturedAt,
        ...(media.location ? { location: media.location } : {}),
        byUserId: user.id,
        byName: user.name,
        ...(media.finding ? { finding: true, note: (media.note ?? '').trim() } : media.note?.trim() ? { note: media.note.trim() } : {}),
      };
      // A retake replaces the proof, it does not remove it: the earlier capture stays in the record, marked as replaced. A finding
      // never replaces anything and is never replaced.
      const prior = (step.evidence ?? []).map((e) => (!fresh.finding && e.slotId === slotId && !e.finding && !e.supersededAt ? { ...e, supersededAt: at } : e));
      const evidence = [...prior, fresh];
      // A capture made instead of an exception answers the exception.
      const exceptions = fresh.finding ? step.evidenceExceptions : (step.evidenceExceptions ?? []).filter((e) => e.slotId !== slotId);
      const steps = job.steps.map((x) => (x.id === stepId ? { ...x, evidence, evidenceCount: evidence.filter((e) => !e.supersededAt).length, ...(exceptions ? { evidenceExceptions: exceptions } : {}) } : x));
      if (!fresh.finding && exceptionOf(step, slotId)) {
        const ex = alerts.find((a) => a.relatedId === exceptionKey(job.id, stepId, slotId) && a.status !== 'resolved');
        if (ex) patchInPlace(alerts, ex.id, { status: 'resolved', resolvedAt: at, resolvedBy: user.name, resolutionNote: 'The capture was made after all.' });
      }
      if (fresh.finding) {
        raiseAlert({
          titleKey: 'installEvidence.alert.finding',
          context: `${job.code} · ${job.siteName} · ${user.name}: ${fresh.note}`,
          severity: (def as InstallSopStepDef).safetyCritical ? 'high' : 'medium',
          category: 'quality',
          relatedId: findingKey(fresh.id),
          sourceRoute: `/admin/tracking/technician/${user.id}`,
        });
      }
      return installationSopViewOf(patchInPlace(jobs, job.id, { steps }), technicianId);
    }),

  recordEvidenceException: (jobId, stepId, slotId, reason, technicianId, capturedAt) =>
    simulateWrite((): InstallationSopView => {
      const { job: raw, user, def } = sopActor(jobId, technicianId, stepId);
      const job = sopWorkable(raw);
      const step = job.steps.find((x) => x.id === stepId) as JobStep;
      if (isDone(step)) throw new RepositoryError('already_done');
      const slot = slotsFor(def as InstallSopStepDef, sopSpecOf(job)).find((sl) => sl.id === slotId);
      if (!slot) throw new RepositoryError('not_found');
      const problem = exceptionProblem(slot, step, reason);
      if (problem) throw new RepositoryError(problem);
      const now = Date.now();
      const at = capturedAt ?? new Date(now).toISOString();
      const bad = capturedAtProblem(at, job.startedAt ?? job.scheduledFor, now);
      if (bad) throw new RepositoryError(`captured_${bad}`);
      const entry: JobEvidenceException = { slotId, reason: reason.trim(), byName: user.name, at };
      const steps = job.steps.map((x) => (x.id === stepId ? { ...x, evidenceExceptions: [...(x.evidenceExceptions ?? []), entry] } : x));
      const safety = (def as InstallSopStepDef).safetyCritical;
      raiseAlert({
        titleKey: safety ? 'installEvidence.alert.exceptionSafety' : 'installEvidence.alert.exception',
        context: `${job.code} · ${job.siteName} · ${user.name}: ${entry.reason}`,
        severity: safety ? 'high' : 'low',
        category: safety ? 'safety' : 'quality',
        relatedId: exceptionKey(job.id, stepId, slotId),
        sourceRoute: `/admin/tracking/technician/${user.id}`,
      });
      const updated = patchInPlace(jobs, job.id, { steps });
      return installationSopViewOf(updated, technicianId);
    }),

  completeSopStep: (jobId, stepId, technicianId, capturedAt) =>
    simulateWrite((): InstallationSopView => {
      const { job: raw, user, def } = sopActor(jobId, technicianId, stepId);
      const job = sopWorkable(raw);
      const version = sopVersionOf(job);
      const problem = completionProblem(def as InstallSopStepDef, job.steps, sopSpecOf(job), { materialsConfirmed: sopMaterialsConfirmed(job) });
      if (problem) throw new RepositoryError(problem);
      const now = Date.now();
      const at = capturedAt ?? new Date(now).toISOString();
      const bad = capturedAtProblem(at, job.startedAt ?? job.scheduledFor, now);
      if (bad) throw new RepositoryError(`captured_${bad}`);
      const done = job.steps.map((x) => (x.id === stepId ? { ...x, status: 'complete' as const, completedAt: at, completedByName: user.name } : x));
      const updated = patchInPlace(jobs, job.id, { steps: withCurrent(done, version.steps, null) });
      return installationSopViewOf(sopFinishIfDone(updated, version, technicianId), technicianId);
    }),

  markStepNotApplicable: (jobId, stepId, reason, technicianId, capturedAt) =>
    simulateWrite((): InstallationSopView => {
      const { job: raw, user, def } = sopActor(jobId, technicianId, stepId);
      const job = sopWorkable(raw);
      const version = sopVersionOf(job);
      const problem = naProblem(def as InstallSopStepDef, job.steps.find((x) => x.id === stepId), sopSpecOf(job), reason);
      if (problem) throw new RepositoryError(problem);
      const now = Date.now();
      const at = capturedAt ?? new Date(now).toISOString();
      const bad = capturedAtProblem(at, job.startedAt ?? job.scheduledFor, now);
      if (bad) throw new RepositoryError(`captured_${bad}`);
      const done = job.steps.map((x) => (x.id === stepId ? { ...x, status: 'complete' as const, completedAt: at, completedByName: user.name, notApplicable: { reason: reason.trim(), byName: user.name, at } } : x));
      const updated = patchInPlace(jobs, job.id, { steps: withCurrent(done, version.steps, null) });
      return installationSopViewOf(sopFinishIfDone(updated, version, technicianId), technicianId);
    }),

  focusSopStep: (jobId, stepId, technicianId) =>
    simulateWrite((): InstallationSopView => {
      const { job: raw, def } = sopActor(jobId, technicianId, stepId);
      const job = sopWorkable(raw);
      const step = job.steps.find((x) => x.id === stepId) as JobStep;
      if (isDone(step)) throw new RepositoryError('already_done');
      // Out of order is fine where the site needs it, but not ahead of what the step stands on.
      if (unmetDependencies(def as InstallSopStepDef, job.steps).length > 0) throw new RepositoryError('depends_on');
      const updated = patchInPlace(jobs, job.id, { steps: withCurrent(job.steps, sopVersionOf(job).steps, stepId) });
      return installationSopViewOf(updated, technicianId);
    }),

  /* --------------------------------- QC electrical & safety check (133) */
  getElectricalCheck: (jobId, userId) =>
    simulateRead((): QcElecView => {
      const { job, viewer, assignment } = mechActor(jobId, userId);
      if (viewer === 'lead') throw new RepositoryError('forbidden');
      return elecViewOf(job, viewer, assignment);
    }),

  recordElectricalResult: (jobId, itemId, input, inspectorId) =>
    simulateWrite((): QcElecView => {
      const { job, user, viewer, assignment } = mechActor(jobId, inspectorId);
      if (viewer !== 'inspector' || !assignment || !qcActive(assignment)) throw new RepositoryError('not_inspector');
      if (job.status !== 'qc_pending') throw new RepositoryError('not_ready');
      const check = elecCheckOf(job.id);
      if (check.signedOff) throw new RepositoryError('invalid_state');
      const reading = { measures: input.measures, checks: input.checks, intermittent: input.intermittent };
      const problem = elecAttemptProblem({ itemId, verdict: input.verdict, reading, note: input.note, evidenceCount: input.evidence.length });
      if (problem) throw new RepositoryError(problem);
      if (input.evidence.length > 6) throw new RepositoryError('too_many_attachments');
      const now = Date.now();
      const at = input.capturedAt ? new Date(input.capturedAt).getTime() : now;
      if (Number.isNaN(at)) throw new RepositoryError('captured_invalid');
      if (at > now + 60_000) throw new RepositoryError('captured_in_future');
      const list = check.attempts[itemId] ?? (check.attempts[itemId] = []);
      const id = input.clientId ? `qea-${input.clientId}` : `qea-${++mechCounter}`;
      if (!list.some((a) => a.id === id)) {
        const evidence = input.evidence.map((m, n) => {
          const bad = evidenceProblem(m.kind, { kind: m.kind, mimeType: m.mimeType, sizeBytes: m.sizeBytes, durationS: m.durationS });
          if (bad) throw new RepositoryError(bad);
          return mediaToEvidence(m, `${id}-ev${n + 1}`, `qc.${itemId}`, user);
        });
        const attempt: QcElecAttempt = { id, n: list.length + 1, verdict: input.verdict, suggested: elecSuggest(itemId, reading), measures: input.measures.map((m) => ({ ...m })), checks: input.checks.map((c) => ({ ...c })), intermittent: input.intermittent, ...(input.note?.trim() ? { note: input.note.trim() } : {}), evidence, at: new Date(at).toISOString(), byUserId: user.id, byName: user.name };
        list.push(attempt);
        if (assignment.status !== 'in_progress') {
          assignment.status = 'in_progress';
          assignment.events.push(qcEvent('scheduled', user.name, 'Inspection started'));
        }
        if (input.verdict === 'fail') raiseChecklistSnag(job, 'qc_electrical', itemId, attempt.note ?? '', evidence, user.name, attempt.at);
        else verifyChecklistSnags(job, 'qc_electrical', itemId, user.name, attempt.at);
        syncQcElecAlerts(now);
      }
      return elecViewOf(job, viewer, assignment);
    }),

  signOffElectrical: (jobId, inspectorId) =>
    simulateWrite((): QcElecView => {
      const { job, user, viewer, assignment } = mechActor(jobId, inspectorId);
      if (viewer !== 'inspector') throw new RepositoryError('not_inspector');
      const check = elecCheckOf(job.id);
      if (check.signedOff) throw new RepositoryError('invalid_state');
      const problem = elecSignOffProblem(ELEC_ITEMS.map((i) => elecStateOf(check.attempts[i])));
      if (problem) throw new RepositoryError(problem);
      check.signedOff = { at: new Date().toISOString(), byUserId: user.id, byName: user.name };
      return elecViewOf(job, viewer, assignment);
    }),

  /* --------------------------------- Recruitment: the applicant's full details (142) */
  startPartnerApplication: (interestId, phone) =>
    simulateWrite(() => {
      const interest = byId(recruitmentInterests, interestId);
      if (!interest || interest.phone !== rcPhone(phone) || interest.role === 'undecided') throw new RepositoryError('not_found');
      const existing = partnerApplications.find((a) => a.interestId === interest.id);
      if (existing) return { applicationId: existing.id, accessKey: existing.accessKey };
      applicationCounter += 1;
      const at = new Date().toISOString();
      const app: PartnerApplication = {
        id: `ap-${applicationCounter}`,
        code: `AIEC-AP-${2000 + applicationCounter}`,
        interestId: interest.id,
        accessKey: `k${Math.random().toString(36).slice(2, 10)}${Math.random().toString(36).slice(2, 10)}`,
        role: interest.role,
        status: 'draft',
        startedAt: at,
        updatedAt: at,
        form: { ...JSON.parse(JSON.stringify(APP_EMPTY)), personal: { ...APP_EMPTY.personal, fullName: interest.name, phone: interest.phone, languages: [interest.language] } },
        events: [applicationEvent('started', interest.name)],
        messages: [],
        isDemo: true,
      };
      partnerApplications.push(app);
      if (interest.status === 'interested') patchInPlace(recruitmentInterests, interest.id, { status: 'started' as const, startedAt: at });
      return { applicationId: app.id, accessKey: app.accessKey };
    }),

  getPartnerApplication: (applicationId, access) =>
    simulateRead((): PartnerApplicationView => {
      const { app, viewer } = applicationFor(applicationId, access);
      return applicationViewOf(app, viewer);
    }),

  savePartnerApplication: (applicationId, key, patch) =>
    simulateWrite((): PartnerApplicationView => {
      const { app } = applicationFor(applicationId, { key });
      if (apLocked(app.status)) throw new RepositoryError('locked');
      const f = app.form;
      // The phone is the applicant's identity on this record: it is set when the interest is made and not changed here.
      if (patch.personal) f.personal = { ...patch.personal, phone: f.personal.phone };
      if (patch.experience) f.experience = { ...patch.experience };
      if (patch.territory) f.territory = { ...patch.territory };
      if (patch.availability) f.availability = { ...patch.availability };
      if (patch.identity) f.identity = { ...patch.identity };
      if (patch.noReferences !== undefined) f.noReferences = patch.noReferences;
      if (patch.references) {
        // A reference keeps what Admin found only while it is still the same person.
        f.references = patch.references.slice(0, 3).map((r): ApplicationReference => {
          applicationRefCounter += 1;
          const before = f.references.find((x) => x.id === r.id);
          const same = before && before.name === r.name && before.phone === r.phone;
          return { id: before ? before.id : `rf-new-${applicationRefCounter}`, name: r.name, phone: r.phone, relationship: r.relationship, organisation: r.organisation, ...(same && before.outcome ? { outcome: before.outcome } : {}) };
        });
      }
      app.updatedAt = new Date().toISOString();
      return applicationViewOf(app, 'applicant');
    }),

  submitPartnerApplication: (applicationId, key) =>
    simulateWrite((): PartnerApplicationView => {
      const { app } = applicationFor(applicationId, { key });
      if (apLocked(app.status)) throw new RepositoryError('locked');
      if (apSubmitProblem(app.role, app.form)) throw new RepositoryError('incomplete');
      const again = app.status === 'submitted';
      const answering = app.status === 'info_requested';
      app.status = 'submitted';
      app.submittedAt = new Date().toISOString();
      app.updatedAt = app.submittedAt;
      app.events.push(applicationEvent(answering ? 'info_answered' : again ? 'resubmitted' : 'submitted', app.form.personal.fullName));
      if (answering && app.screening?.infoRequest) app.screening.infoRequest.answeredAt = app.submittedAt;
      const interest = byId(recruitmentInterests, app.interestId);
      if (interest) patchInPlace(recruitmentInterests, interest.id, { status: 'submitted' as const });
      return applicationViewOf(app, 'applicant');
    }),

  listPartnerApplications: (userId) =>
    simulateRead((): ApplicationBoardView => {
      const u = byId(users, userId);
      if (!u || u.role !== 'admin') throw new RepositoryError('forbidden');
      const rows = partnerApplications
        .map((a) => {
          const interest = byId(recruitmentInterests, a.interestId);
          return { id: a.id, code: a.code, name: a.form.personal.fullName, role: a.role, status: a.status, percent: apProgress(apSections(a.role, a.form)).percent, outstanding: apOutstanding(a.form).length, channel: interest?.source.channel ?? ('website' as const), updatedAt: a.updatedAt, submittedAt: a.submittedAt ?? null };
        })
        .sort((x, y) => (y.submittedAt ?? y.updatedAt).localeCompare(x.submittedAt ?? x.updatedAt));
      return { rows, counts: { draft: rows.filter((r) => r.status === 'draft').length, submitted: rows.filter((r) => r.status === 'submitted').length, outstanding: rows.reduce((n, r) => n + r.outstanding, 0) } };
    }),

  recordReferenceOutcome: (applicationId, referenceId, input, userId) =>
    simulateWrite((): PartnerApplicationView => {
      const { app, admin } = applicationFor(applicationId, { userId });
      const ref = app.form.references.find((r) => r.id === referenceId);
      if (!ref) throw new RepositoryError('not_found');
      if (input.status !== 'verified' && (input.note ?? '').replace(/[^\p{L}\p{N}]/gu, '').length < 8) throw new RepositoryError('note_required');
      ref.outcome = { status: input.status, at: new Date().toISOString(), byName: (admin as User).name, ...(input.note?.trim() ? { note: input.note.trim() } : {}) };
      app.events.push(applicationEvent('reference_outcome', (admin as User).name, `${ref.name}: ${input.status}`));
      return applicationViewOf(app, 'admin');
    }),

  /* --------------------------------- Recruitment: applicant screening and scoring (143) */
  getScreeningQueue: (userId) =>
    simulateRead((): ScreeningQueueView => {
      screeningAdmin(userId);
      const now = new Date();
      const rows = partnerApplications.filter((a) => a.status === 'submitted' || a.status === 'info_requested' || a.status === 'approved' || a.status === 'rejected').map((a) => screeningRowOf(a, scoringConfig.weights, now));
      const queue = rows.filter((r) => r.status === 'submitted').sort(screeningOrder);
      const waiting = rows.filter((r) => r.status === 'info_requested').sort((a, b) => b.waitingDays - a.waitingDays);
      const decidedAt = (id: string) => byId(partnerApplications, id)?.screening?.decision?.at ?? '';
      const decided = rows.filter((r) => r.status === 'approved' || r.status === 'rejected').sort((a, b) => decidedAt(b.id).localeCompare(decidedAt(a.id)));
      const lastDay = recruitmentLastDay(now.getTime());
      return {
        queue,
        waiting,
        decided,
        counts: { queue: queue.length, waiting: waiting.length, approved: decided.filter((r) => r.status === 'approved').length, rejected: decided.filter((r) => r.status === 'rejected').length, overdue: queue.filter((r) => r.overdue).length },
        weights: { ...scoringConfig.weights },
        demand: { level: rcDemandOf(lastDay).level, lastDay },
      };
    }),

  getScreeningDetail: (applicationId, userId) =>
    simulateRead((): ScreeningDetailView => {
      screeningAdmin(userId);
      return screeningDetailOf(screeningApp(applicationId), new Date());
    }),

  decideApplication: (applicationId, input, userId) =>
    simulateWrite((): ScreeningDetailView => {
      const admin = screeningAdmin(userId);
      const app = screeningApp(applicationId);
      const now = new Date();
      if (input.decision === 'approve') {
        if (app.status !== 'submitted') throw new RepositoryError('not_open');
        freezeDecision(app, 'approved', admin.name, now, { note: input.note });
        app.events.push(applicationEvent('approved', admin.name, input.note));
        screeningMessage(app, 'approved', 'screening.message.approved', admin.name, input.note);
      } else if (input.decision === 'reject') {
        if (app.status !== 'submitted' && app.status !== 'info_requested') throw new RepositoryError('not_open');
        if (!(DECLINE_REASONS as readonly string[]).includes(input.reason)) throw new RepositoryError('reason_required');
        freezeDecision(app, 'rejected', admin.name, now, { reasonKey: `screening.decline.${input.reason}`, note: input.note });
        app.events.push(applicationEvent('rejected', admin.name, input.reason));
        screeningMessage(app, 'decline', `screening.message.decline.${input.reason}`, admin.name, input.note);
      } else {
        if (app.status !== 'submitted') throw new RepositoryError('not_open');
        const sections = [...new Set(input.sections)].filter((x) => (APP_SECTIONS as readonly string[]).includes(x));
        if (sections.length === 0) throw new RepositoryError('nothing_selected');
        if (input.note.replace(/[^\p{L}\p{N}]/gu, '').length < 8) throw new RepositoryError('reason_required');
        app.screening = { ...(app.screening ?? {}), infoRequest: { sections, note: input.note.trim(), at: now.toISOString(), byName: admin.name } };
        app.status = 'info_requested';
        app.updatedAt = now.toISOString();
        app.events.push(applicationEvent('info_requested', admin.name, sections.join(', ')));
        screeningMessage(app, 'info_request', 'screening.message.infoRequest', admin.name, input.note);
      }
      return screeningDetailOf(app, now);
    }),

  bulkRejectApplications: (applicationIds, input, userId) =>
    simulateWrite(() => {
      const admin = screeningAdmin(userId);
      if (!(DECLINE_REASONS as readonly string[]).includes(input.reason)) throw new RepositoryError('reason_required');
      const now = new Date();
      let rejected = 0;
      let skipped = 0;
      for (const id of [...new Set(applicationIds)]) {
        const app = byId(partnerApplications, id);
        if (!app || (app.status !== 'submitted' && app.status !== 'info_requested')) {
          skipped += 1;
          continue;
        }
        freezeDecision(app, 'rejected', admin.name, now, { reasonKey: `screening.decline.${input.reason}`, note: input.note });
        app.events.push(applicationEvent('rejected', admin.name, input.reason));
        screeningMessage(app, 'decline', `screening.message.decline.${input.reason}`, admin.name, input.note);
        rejected += 1;
      }
      return { rejected, skipped };
    }),

  setApplicationAdjustment: (applicationId, input, userId) =>
    simulateWrite((): ScreeningDetailView => {
      const admin = screeningAdmin(userId);
      const app = screeningApp(applicationId);
      if (app.status !== 'submitted' && app.status !== 'info_requested') throw new RepositoryError('not_open');
      const now = new Date();
      if (input === null) {
        if (app.screening?.adjustment) {
          delete app.screening.adjustment;
          app.events.push(applicationEvent('adjusted', admin.name, '—'));
        }
      } else {
        const problem = screeningAdjustProblem(input.points, input.reason);
        if (problem) throw new RepositoryError(problem);
        app.screening = { ...(app.screening ?? {}), adjustment: { points: input.points, reason: input.reason.trim(), byName: admin.name, at: now.toISOString() } };
        app.events.push(applicationEvent('adjusted', admin.name, `${input.points > 0 ? '+' : ''}${input.points}`));
      }
      return screeningDetailOf(app, now);
    }),

  getScoringConfig: (userId) =>
    simulateRead((): ScoringConfigView => {
      screeningAdmin(userId);
      const fb = screeningFeedbackOf();
      const now = Date.now();
      return {
        weights: { ...scoringConfig.weights },
        defaults: { ...SCREEN_DEFAULT_WEIGHTS },
        updatedAt: scoringConfig.updatedAt,
        updatedByName: scoringConfig.updatedByName,
        feedback: { rated: fb.rated, enough: fb.enough, perFactor: fb.perFactor, suggest: fb.suggest },
        toRate: partnerApplications
          .filter((a) => a.status === 'approved' && !a.screening?.outcome && a.screening?.decision && now - new Date(a.screening.decision.at).getTime() >= SCREEN_RATE_AFTER)
          .map((a) => ({ id: a.id, code: a.code, name: a.form.personal.fullName, role: a.role, decidedAt: (a.screening as ApplicationScreening).decision!.at }))
          .sort((a, b) => a.decidedAt.localeCompare(b.decidedAt)),
      };
    }),

  saveScoringConfig: (weights, confirm, userId) =>
    simulateWrite((): ScoringSaveResult => {
      const admin = screeningAdmin(userId);
      const problem = screeningWeightsProblem(weights);
      if (problem) throw new RepositoryError(problem);
      const now = new Date();
      const before = screeningQueueIds(scoringConfig.weights, now);
      const trial: Weights = { ...weights };
      const after = partnerApplications
        .filter((a) => a.status === 'submitted')
        .map((a) => screeningRowOf(a, trial, now))
        .sort(screeningOrder)
        .map((r) => r.id);
      const reshuffle = screeningReshuffle(before, after);
      // A change that would move a lot of the queue is said out loud first, so a weighting is never changed by accident.
      if (reshuffle >= RESHUFFLE_SHARE && !confirm) return { saved: false, reshuffle, queueSize: before.length };
      scoringConfig.weights = trial;
      scoringConfig.updatedAt = now.toISOString();
      scoringConfig.updatedByName = admin.name;
      return { saved: true, reshuffle, queueSize: before.length };
    }),

  recordApplicantOutcome: (applicationId, input, userId) =>
    simulateWrite((): ScreeningDetailView => {
      const admin = screeningAdmin(userId);
      const app = screeningApp(applicationId);
      if (app.status !== 'approved' || !app.screening?.decision) throw new RepositoryError('not_approved');
      const now = new Date();
      app.screening.outcome = { rating: input.rating, at: now.toISOString(), byName: admin.name, ...(input.note?.trim() ? { note: input.note.trim() } : {}) };
      app.events.push(applicationEvent('outcome', admin.name, input.rating));
      return screeningDetailOf(app, now);
    }),

  /* --------------------------------- Recruitment: interview scheduling (144) */
  getInterviewBoard: (userId) =>
    simulateRead((): InterviewBoardView => {
      ivAdmin(userId);
      const now = Date.now();
      // Someone moved forward long ago who never had an interview is history, not a pending job (the same cutoff the commitment uses).
      const rows = partnerApplications.filter((a) => a.status === 'approved' && (!!a.interview || now - new Date(a.screening?.decision?.at ?? 0).getTime() < IV_ARRANGE_DUE * 10)).map((a) => ivRowOf(a, now)).sort((a, b) => IV_RANK[a.phase] - IV_RANK[b.phase] || (a.slot?.start ?? a.approvedAt ?? '').localeCompare(b.slot?.start ?? b.approvedAt ?? ''));
      const n = (p: IvPhase) => rows.filter((r) => r.phase === p).length;
      return {
        rows,
        counts: { toArrange: n('to_arrange'), invited: n('invited'), scheduled: n('scheduled') + n('move_requested'), needsOutcome: n('needs_outcome'), completed: n('completed') },
        availability: JSON.parse(JSON.stringify(interviewAvailability)) as InterviewAvailability,
        openSlots: ivSlots(interviewAvailability, ivBusy(), now).length,
      };
    }),

  getInterviewDetail: (applicationId, userId) =>
    simulateRead((): InterviewDetailView => {
      ivAdmin(userId);
      return ivDetailOf(ivApp(applicationId), Date.now());
    }),

  inviteToInterview: (applicationId, input, userId) =>
    simulateWrite((): InterviewDetailView => {
      const admin = ivAdmin(userId);
      const app = ivApp(applicationId);
      if (app.status !== 'approved') throw new RepositoryError('not_approved');
      const now = Date.now();
      const phase = ivPhaseOf(app.interview, now);
      if (phase !== 'to_arrange' && phase !== 'cancelled' && phase !== 'missed') throw new RepositoryError('already_active');
      const modes = INTERVIEW_MODE_LIST.filter((m) => input.modes.includes(m));
      const problem = ivDetailsProblem(modes, input.details);
      if (problem) throw new RepositoryError(problem);
      const at = new Date(now).toISOString();
      const prior = app.interview;
      app.interview = {
        status: 'invited',
        modes,
        details: { ...(modes.includes('video') ? { videoLink: (input.details.videoLink ?? '').trim() } : {}), ...(modes.includes('in_person') ? { place: (input.details.place ?? '').trim() } : {}) },
        invitedAt: at,
        invitedByName: admin.name,
        ...(input.note?.trim() ? { inviteNote: input.note.trim() } : {}),
        misses: 0,
        reschedules: prior?.reschedules ?? 0,
        addenda: prior?.addenda ?? [],
        remindersSent: [],
        events: [...(prior?.events ?? []), ivEvent('invited', admin.name, modes.join(', '))],
      };
      ivMessage(app, 'interview_invite', 'invite', admin.name, {}, input.note);
      app.updatedAt = at;
      return ivDetailOf(app, now);
    }),

  skipInterview: (applicationId, reason, userId) =>
    simulateWrite((): InterviewDetailView => {
      const admin = ivAdmin(userId);
      const app = ivApp(applicationId);
      if (app.status !== 'approved') throw new RepositoryError('not_approved');
      const now = Date.now();
      const phase = ivPhaseOf(app.interview, now);
      if (phase !== 'to_arrange' && phase !== 'invited' && phase !== 'cancelled' && phase !== 'missed') throw new RepositoryError('already_active');
      if (reason.replace(/[^\p{L}\p{N}]/gu, '').length < IV_REASON_MIN) throw new RepositoryError('reason_required');
      const at = new Date(now).toISOString();
      const prior = app.interview;
      app.interview = { status: 'skipped', modes: prior?.modes ?? [], details: prior?.details ?? {}, invitedAt: prior?.invitedAt ?? at, invitedByName: prior?.invitedByName ?? admin.name, misses: prior?.misses ?? 0, reschedules: prior?.reschedules ?? 0, skipped: { at, byName: admin.name, reason: reason.trim() }, addenda: prior?.addenda ?? [], remindersSent: [], events: [...(prior?.events ?? []), ivEvent('skipped', admin.name, reason.trim())] };
      app.updatedAt = at;
      return ivDetailOf(app, now);
    }),

  scheduleInterview: (applicationId, input, userId) =>
    simulateWrite((): InterviewDetailView => {
      const admin = ivAdmin(userId);
      const app = ivApp(applicationId);
      if (app.status !== 'approved') throw new RepositoryError('not_approved');
      const now = Date.now();
      const phase = ivPhaseOf(app.interview, now);
      if (phase === 'completed' || phase === 'skipped' || phase === 'needs_outcome') throw new RepositoryError('already_active');
      const moving = app.interview?.status === 'scheduled';
      if (moving && (input.reason ?? '').replace(/[^\p{L}\p{N}]/gu, '').length < IV_REASON_MIN) throw new RepositoryError('reason_required');
      const details = { ...(app.interview?.details ?? {}), ...(input.details ?? {}) };
      const problemWith = ivDetailsProblem([input.mode], details);
      if (problemWith === 'link_required' || problemWith === 'place_required') throw new RepositoryError(problemWith);
      const av = interviewAvailability;
      const slotProblem = ivAdminSlotProblem(ivBusy(app.id), now, input.start, av.slotMinutes, av.bufferMinutes);
      if (slotProblem) throw new RepositoryError(slotProblem === 'past' ? 'slot_past' : 'slot_taken');
      const start = new Date(input.start);
      const at = new Date(now).toISOString();
      const slot = { start: start.toISOString(), end: new Date(start.getTime() + av.slotMinutes * 60_000).toISOString(), mode: input.mode, chosenAt: at, chosenBy: 'admin' as const };
      const prior = app.interview;
      const modes = prior?.modes.length ? (prior.modes.includes(input.mode) ? prior.modes : [...prior.modes, input.mode]) : [input.mode];
      app.interview = {
        status: 'scheduled',
        modes,
        details: { ...(modes.includes('video') && details.videoLink ? { videoLink: details.videoLink.trim() } : {}), ...(modes.includes('in_person') && details.place ? { place: details.place.trim() } : {}) },
        invitedAt: prior?.invitedAt ?? at,
        invitedByName: prior?.invitedByName ?? admin.name,
        ...(prior?.inviteNote ? { inviteNote: prior.inviteNote } : {}),
        slot,
        misses: prior?.misses ?? 0,
        reschedules: (prior?.reschedules ?? 0) + (moving ? 1 : 0),
        addenda: prior?.addenda ?? [],
        remindersSent: [],
        events: [...(prior?.events ?? []), ivEvent(moving ? 'rescheduled' : 'slot_chosen', admin.name, moving ? input.reason?.trim() : undefined)],
      };
      if (moving) ivMessage(app, 'interview_confirmed', 'adminMoved', admin.name, { at: slot.start, mode: slot.mode }, input.reason);
      else ivMessage(app, 'interview_confirmed', 'confirmed', admin.name, { at: slot.start, mode: slot.mode });
      app.updatedAt = at;
      return ivDetailOf(app, now);
    }),

  requestInterviewMove: (applicationId, reason, userId) =>
    simulateWrite((): InterviewDetailView => {
      const admin = ivAdmin(userId);
      const app = ivApp(applicationId);
      const i = app.interview;
      if (!i || i.status !== 'scheduled' || !i.slot) throw new RepositoryError('not_open');
      const now = Date.now();
      if (reason !== 'availability' && reason.replace(/[^\p{L}\p{N}]/gu, '').length < IV_REASON_MIN) throw new RepositoryError('reason_required');
      if (!i.moveRequest) {
        i.moveRequest = { at: new Date(now).toISOString(), reason: reason === 'availability' ? 'availability' : reason.trim(), byName: admin.name };
        i.events.push(ivEvent('move_requested', admin.name, i.moveRequest.reason));
        // The confirmed time stands until a new one is chosen: the applicant is told plainly, and nobody is left without an appointment.
        if (reason === 'availability') ivMessage(app, 'interview_move', 'moveAvailability', admin.name, { at: i.slot.start });
        else ivMessage(app, 'interview_move', 'move', admin.name, { at: i.slot.start }, reason);
      }
      return ivDetailOf(app, now);
    }),

  confirmInterviewSlot: (applicationId, userId) =>
    simulateWrite((): InterviewDetailView => {
      const admin = ivAdmin(userId);
      const app = ivApp(applicationId);
      const i = app.interview;
      if (!i || i.status !== 'scheduled' || !i.slot) throw new RepositoryError('not_open');
      i.slot.chosenBy = 'admin';
      i.events.push(ivEvent('slot_chosen', admin.name, 'kept'));
      return ivDetailOf(app, Date.now());
    }),

  cancelInterview: (applicationId, reason, userId) =>
    simulateWrite((): InterviewDetailView => {
      const admin = ivAdmin(userId);
      const app = ivApp(applicationId);
      const i = app.interview;
      if (!i || (i.status !== 'invited' && i.status !== 'scheduled' && i.status !== 'missed')) throw new RepositoryError('not_open');
      if (reason.replace(/[^\p{L}\p{N}]/gu, '').length < IV_REASON_MIN) throw new RepositoryError('reason_required');
      i.status = 'cancelled';
      delete i.slot;
      delete i.moveRequest;
      i.events.push(ivEvent('cancelled', admin.name, reason.trim()));
      ivMessage(app, 'interview_cancelled', 'cancelled', admin.name, {}, reason);
      return ivDetailOf(app, Date.now());
    }),

  markInterviewMissed: (applicationId, userId) =>
    simulateWrite((): InterviewDetailView => {
      const admin = ivAdmin(userId);
      const app = ivApp(applicationId);
      const i = app.interview;
      if (!i || i.status !== 'scheduled' || !i.slot) throw new RepositoryError('not_open');
      const now = Date.now();
      if (now < new Date(i.slot.start).getTime()) throw new RepositoryError('not_started');
      const when = i.slot.start;
      i.status = 'missed';
      i.misses += 1;
      delete i.slot;
      delete i.moveRequest;
      i.events.push(ivEvent('missed', admin.name));
      // Not a strike: the person is told it happens and given the way to choose again; only after repeated misses does Admin take over, kindly.
      ivMessage(app, 'interview_missed', i.misses >= IV_MAX_MISSES ? 'missedLast' : 'missed', admin.name, { at: when });
      return ivDetailOf(app, now);
    }),

  completeInterview: (applicationId, input, userId) =>
    simulateWrite((): InterviewDetailView => {
      const admin = ivAdmin(userId);
      const app = ivApp(applicationId);
      const i = app.interview;
      if (!i || i.status !== 'scheduled' || !i.slot) throw new RepositoryError('not_open');
      const now = Date.now();
      if (now < new Date(i.slot.start).getTime()) throw new RepositoryError('not_started');
      const problem = ivCompleteProblem(input);
      if (problem) throw new RepositoryError(problem);
      const r = input.ratings as NonNullable<PartnerInterview['completed']>['ratings'];
      const concernText = (input.concern?.text ?? '').trim();
      i.status = 'completed';
      i.completed = {
        at: new Date(now).toISOString(),
        byName: admin.name,
        ratings: { communication: r.communication, reliability: r.reliability, experience: r.experience },
        note: input.note.trim(),
        ...(input.concern?.category && concernText ? { concern: { category: input.concern.category, text: concernText } } : {}),
        outcome: input.outcome as NonNullable<PartnerInterview['completed']>['outcome'],
        ...(input.outcome !== 'recommend' ? { outcomeReason: (input.outcomeReason ?? '').trim() } : {}),
      };
      delete i.moveRequest;
      i.events.push(ivEvent('completed', admin.name, input.outcome));
      app.updatedAt = i.completed.at;
      return ivDetailOf(app, now);
    }),

  addInterviewAddendum: (applicationId, input, userId) =>
    simulateWrite((): InterviewDetailView => {
      const admin = ivAdmin(userId);
      const app = ivApp(applicationId);
      const i = app.interview;
      if (!i || i.status !== 'completed') throw new RepositoryError('not_completed');
      if (input.text.replace(/[^\p{L}\p{N}]/gu, '').length < IV_NOTE_MIN) throw new RepositoryError('note_required');
      const concernText = (input.concern?.text ?? '').trim();
      if (input.concern && (!input.concern.category || concernText.replace(/[^\p{L}\p{N}]/gu, '').length < IV_NOTE_MIN)) throw new RepositoryError('concern_text');
      interviewEventCounter += 1;
      i.addenda.push({ id: `ivad-${interviewEventCounter}`, at: new Date().toISOString(), byName: admin.name, text: input.text.trim(), ...(input.concern ? { concern: { category: input.concern.category, text: concernText } } : {}) });
      i.events.push(ivEvent('addendum', admin.name, input.concern ? input.concern.category : undefined));
      return ivDetailOf(app, Date.now());
    }),

  saveInterviewAvailability: (availability, userId) =>
    simulateWrite((): InterviewSaveResult => {
      const admin = ivAdmin(userId);
      const next: InterviewAvailability = JSON.parse(JSON.stringify({ ...availability, closedDates: [...new Set(availability.closedDates)].sort() })) as InterviewAvailability;
      const problem = ivAvailabilityProblem(next);
      if (problem) throw new RepositoryError(problem);
      Object.assign(interviewAvailability, next, { updatedAt: new Date().toISOString(), updatedByName: admin.name });
      const now = Date.now();
      // Nothing already confirmed is cancelled: the ones that no longer fit are handed back so Admin asks each person, or keeps the time.
      const conflicts = partnerApplications.filter((a) => ivRowOf(a, now).conflict).map((a) => ({ id: a.id, name: a.form.personal.fullName, start: (a.interview as PartnerInterview).slot!.start }));
      return { availability: JSON.parse(JSON.stringify(interviewAvailability)) as InterviewAvailability, conflicts };
    }),

  getInterviewForApplicant: (applicationId, key) =>
    simulateRead((): InterviewApplicantView => {
      const { app } = applicationFor(applicationId, { key });
      if (app.status !== 'approved') throw new RepositoryError('not_approved');
      return ivApplicantViewOf(app, Date.now());
    }),

  chooseInterviewSlot: (applicationId, key, input) =>
    simulateWrite((): InterviewApplicantView => {
      const { app } = applicationFor(applicationId, { key });
      if (app.status !== 'approved') throw new RepositoryError('not_approved');
      const i = app.interview;
      const now = Date.now();
      if (!i || !ivSelfServe(i, now)) throw new RepositoryError(i?.status === 'scheduled' ? 'too_late' : 'not_open');
      if (!i.modes.includes(input.mode)) throw new RepositoryError('mode_not_offered');
      const problem = ivSlotProblem(interviewAvailability, ivBusy(app.id), now, input.start);
      if (problem) throw new RepositoryError(problem === 'past' ? 'slot_past' : problem === 'too_soon' ? 'slot_too_soon' : problem === 'closed' ? 'slot_closed' : problem === 'outside' ? 'slot_outside' : 'slot_taken');
      const start = new Date(input.start);
      const at = new Date(now).toISOString();
      const moving = i.status === 'scheduled';
      i.slot = { start: start.toISOString(), end: new Date(start.getTime() + interviewAvailability.slotMinutes * 60_000).toISOString(), mode: input.mode, chosenAt: at, chosenBy: 'applicant' };
      i.status = 'scheduled';
      delete i.moveRequest;
      if (moving) i.reschedules += 1;
      i.remindersSent = [];
      i.events.push(ivEvent(moving ? 'rescheduled' : 'slot_chosen', app.form.personal.fullName));
      ivMessage(app, 'interview_confirmed', 'confirmed', 'AIEC', { at: i.slot.start, mode: input.mode });
      app.updatedAt = at;
      return ivApplicantViewOf(app, now);
    }),

  /* --------------------------------- Recruitment: background and document verification (145) */
  getVerificationBoard: (userId) =>
    simulateRead((): VerificationBoardView => {
      vfAdmin(userId);
      const now = Date.now();
      const rows = partnerApplications.filter((a) => vfLive(a, now)).map((a) => vfRowOf(a, now)).sort((a, b) => (a.gate === 'blocked' ? 0 : a.gate === 'conditional' ? 1 : 2) - (b.gate === 'blocked' ? 0 : b.gate === 'conditional' ? 1 : 2) || b.failed + b.lapsed - (a.failed + a.lapsed) || b.waitingDays - a.waitingDays);
      return { rows, counts: { all: rows.length, blocked: rows.filter((r) => r.gate === 'blocked').length, conditional: rows.filter((r) => r.gate === 'conditional').length, clear: rows.filter((r) => r.gate === 'clear').length, failed: rows.filter((r) => r.failed + r.lapsed > 0).length }, service: { ...verificationService } };
    }),

  getVerification: (applicationId, userId) =>
    simulateRead((): VerificationDetailView => {
      vfAdmin(userId);
      return vfDetailOf(vfApp(applicationId), Date.now());
    }),

  getVerificationGate: (applicationId, userId) =>
    simulateRead(() => {
      vfAdmin(userId);
      const app = vfApp(applicationId);
      return vfGate(vfRequired(app.role, app.form), app.verification, Date.now());
    }),

  runVerificationCheck: (applicationId, itemKey, userId) =>
    simulateWrite((): VerificationDetailView => {
      const admin = vfAdmin(userId);
      const app = vfApp(applicationId);
      const item = vfRequired(app.role, app.form).find((i) => i.key === itemKey);
      if (!item) throw new RepositoryError('not_found');
      if (!item.thirdParty) throw new RepositoryError('not_third_party');
      const now = Date.now();
      if (vfItemState(app.verification?.records[itemKey], now) === 'passed') throw new RepositoryError('already_resolved');
      if (app.verification?.records[itemKey]?.redFlag) throw new RepositoryError('not_open');
      // An outage never stalls the pipeline: Admin is told to use the manual fallback, with a stronger note.
      if (verificationService.status === 'down') throw new RepositoryError('service_unavailable');
      const r = vfServiceCheck(app.role, app.form);
      const v = vfOf(app);
      const at = new Date(now).toISOString();
      if (r.result === 'inconclusive') v.events.push(vfEvent('service_check', admin.name, itemKey, `inconclusive:${r.detail}`));
      else {
        vfRecord(app, itemKey, { status: r.result === 'passed' ? 'passed' : 'failed', method: 'third_party', at, byName: admin.name, reference: `IDV-${app.code.slice(-4)}-${Math.floor(now / 1000) % 10000}`, note: r.detail });
        v.events.push(vfEvent('service_check', admin.name, itemKey, r.result));
      }
      syncVerification(now);
      return vfDetailOf(app, now);
    }),

  recordVerification: (applicationId, itemKey, input, userId) =>
    simulateWrite((): VerificationDetailView => {
      const admin = vfAdmin(userId);
      const app = vfApp(applicationId);
      const item = vfRequired(app.role, app.form).find((i) => i.key === itemKey);
      if (!item) throw new RepositoryError('not_found');
      const now = Date.now();
      const refs = app.form.references;
      const problem = vfManualProblem({ result: input.result, how: input.how, note: input.note, serviceDown: verificationService.status === 'down', item, redFlag: input.redFlag, verifiedReferences: refs.filter((r) => r.outcome?.status === 'verified').length, noReferences: app.form.noReferences });
      if (problem) throw new RepositoryError(problem);
      // Clearing something that failed needs the reason it now holds, not a quick tick: what changed is kept with the record.
      if (app.verification?.records[itemKey]?.status === 'failed' && input.result === 'passed' && input.note.replace(/[^\p{L}\p{N}]/gu, '').length < 25) throw new RepositoryError('fallback_note_required');
      const at = new Date(now).toISOString();
      vfRecord(app, itemKey, { status: input.result, method: 'manual', at, byName: admin.name, note: input.note.trim(), how: input.how, ...(verificationService.status === 'down' && item.thirdParty ? { serviceDown: true } : {}), ...(input.redFlag ? { redFlag: true } : {}) });
      vfOf(app).events.push(vfEvent('manual', admin.name, itemKey, input.result));
      syncVerification(now);
      return vfDetailOf(app, now);
    }),

  grantConditionalVerification: (applicationId, itemKey, input, userId) =>
    simulateWrite((): VerificationDetailView => {
      const admin = vfAdmin(userId);
      const app = vfApp(applicationId);
      const required = vfRequired(app.role, app.form);
      const item = required.find((i) => i.key === itemKey);
      if (!item) throw new RepositoryError('not_found');
      const now = Date.now();
      const v = vfOf(app);
      const open = required.filter((i) => vfItemState(v.records[i.key], now) === 'conditional').length;
      const due = new Date(`${input.dueDate}T23:59:59`);
      const problem = vfConditionalProblem(item, vfItemState(v.records[itemKey], now), input.reason, due.toISOString(), open, now);
      if (problem) throw new RepositoryError(problem);
      const at = new Date(now).toISOString();
      vfRecord(app, itemKey, { status: 'conditional', method: 'manual', at, byName: admin.name, note: input.reason.trim(), conditional: { dueAt: due.toISOString(), reason: input.reason.trim(), grantedBy: admin.name, at } });
      v.events.push(vfEvent('conditional', admin.name, itemKey, input.dueDate));
      return vfDetailOf(app, now);
    }),

  setVerificationService: (status, userId) =>
    simulateWrite((): VerificationServiceView => {
      const admin = vfAdmin(userId);
      verificationService.status = status;
      verificationService.changedAt = new Date().toISOString();
      verificationService.changedByName = admin.name;
      return { ...verificationService };
    }),

  /* --------------------------------- Recruitment: offer and onboarding agreement (146) */
  getOfferBoard: (userId) =>
    simulateRead((): OfferBoardView => {
      ofAdmin(userId);
      const now = Date.now();
      const order: Record<OfferStage, number> = { to_prepare: 0, draft: 1, sent: 2, withdrawn: 3, interview_open: 4, verifying: 5, waitlisted: 6, signed: 7 };
      const rows = partnerApplications.filter((a) => a.status === 'approved' && (!!a.offer || !!a.interview || !!a.verification || now - new Date(a.screening?.decision?.at ?? 0).getTime() < IV_ARRANGE_DUE * 10)).map((a) => ofRowOf(a, now)).sort((a, b) => Number(b.openRequest) - Number(a.openRequest) || order[a.stage] - order[b.stage] || (a.approvedAt ?? '').localeCompare(b.approvedAt ?? ''));
      return { rows, counts: { toPrepare: rows.filter((r) => r.stage === 'to_prepare').length, sent: rows.filter((r) => r.stage === 'sent').length, signed: rows.filter((r) => r.stage === 'signed').length, requests: rows.filter((r) => r.openRequest).length, stepsOpen: rows.filter((r) => r.stage === 'signed' && r.capability === 'basic').length } };
    }),

  getOfferDetail: (applicationId, userId) =>
    simulateRead((): OfferDetailView => {
      ofAdmin(userId);
      return ofDetailOf(ofApp(applicationId), Date.now());
    }),

  prepareOffer: (applicationId, input, userId) =>
    simulateWrite((): OfferDetailView => {
      const admin = ofAdmin(userId);
      const app = ofApp(applicationId);
      const now = Date.now();
      if (app.offer?.status === 'signed') throw new RepositoryError('already_signed');
      if (app.offer?.status === 'sent') throw new RepositoryError('already_sent');
      if (app.waitlist) throw new RepositoryError('waitlisted');
      if (ofInterviewOpen(app)) throw new RepositoryError('interview_open');
      const gate = ofGateOf(app, now);
      // The offer cannot even be drafted while a required check is open, failed or lapsed (145's gate).
      if (gate.state === 'blocked') throw new RepositoryError('verification_open');
      const sig = ivSignal(app.interview);
      if (sig.level === 'block' && (input.overrideReason ?? '').replace(/[^\p{L}\p{N}]/gu, '').length < OF_REASON_MIN) throw new RepositoryError('concern_override_required');
      if (ofPhoneTaken(app)) throw new RepositoryError('phone_taken');
      const activeZones = zones.filter((z) => z.status === 'active').map((z) => z.id);
      const territory = [...new Set(input.territoryZoneIds)].filter((z) => activeZones.includes(z));
      if (app.role !== 'supplier' && territory.length === 0) throw new RepositoryError('territory_required');
      const tpl = templateInForce(app.role, now);
      const prior = app.offer;
      offerCounter += 1;
      const at = new Date(now).toISOString();
      const kept = prior?.addendum?.items.filter((it) => ofTermDefs[app.role].some((d) => d.key === it.key && d.negotiable)) ?? [];
      app.offer = {
        status: 'draft',
        documentNo: prior?.documentNo ?? `AIEC-PA-${1000 + offerCounter + partnerApplications.filter((a) => a.offer).length}`,
        role: app.role,
        templateId: tpl.id,
        templateVersion: tpl.version,
        wording: tpl.wording,
        terms: { ...tpl.terms, ...(app.role !== 'supplier' ? { territoryZoneIds: territory } : {}) },
        ...(prior?.addendum && kept.length ? { addendum: { ...prior.addendum, items: kept } } : {}),
        requests: prior?.requests ?? [],
        ...(sig.level === 'block' ? { concernOverride: { reason: (input.overrideReason ?? '').trim(), byName: admin.name, at } } : {}),
        gateAtPrepare: gate.state === 'conditional' ? 'conditional' : 'clear',
        preparedAt: at,
        preparedByName: admin.name,
        events: [...(prior?.events ?? []), ofEvent('prepared', admin.name, `v${tpl.version}`)],
      };
      return ofDetailOf(app, now);
    }),

  setOfferAddendum: (applicationId, input, userId) =>
    simulateWrite((): OfferDetailView => {
      const admin = ofAdmin(userId);
      const app = ofApp(applicationId);
      const o = app.offer;
      if (!o || (o.status !== 'draft' && o.status !== 'sent')) throw new RepositoryError('not_open');
      const problem = ofAddendumProblem(app.role, o.terms, input.items, input.reason);
      if (problem) throw new RepositoryError(problem);
      const at = new Date().toISOString();
      o.addendum = { items: input.items.map((i) => ({ key: i.key, value: i.value })), reason: input.reason.trim(), approvedByName: admin.name, approvedAt: at };
      o.events.push(ofEvent('addendum', admin.name, input.items.map((i) => `${i.key}=${i.value}`).join(', ')));
      return ofDetailOf(app, Date.now());
    }),

  sendOffer: (applicationId, userId) =>
    simulateWrite((): OfferDetailView => {
      const admin = ofAdmin(userId);
      const app = ofApp(applicationId);
      const o = app.offer;
      if (!o || o.status !== 'draft') throw new RepositoryError('not_open');
      const now = Date.now();
      // The gate is checked again at the moment of sending, not only when it was drafted.
      if (ofGateOf(app, now).state === 'blocked') throw new RepositoryError('verification_open');
      o.status = 'sent';
      o.sentAt = new Date(now).toISOString();
      o.events.push(ofEvent('sent', admin.name));
      screeningMessage(app, 'offer_sent', 'agreement.message.sent', admin.name);
      app.updatedAt = o.sentAt;
      return ofDetailOf(app, now);
    }),

  withdrawOffer: (applicationId, reason, userId) =>
    simulateWrite((): OfferDetailView => {
      const admin = ofAdmin(userId);
      const app = ofApp(applicationId);
      const o = app.offer;
      if (!o || (o.status !== 'draft' && o.status !== 'sent')) throw new RepositoryError('not_open');
      if (reason.replace(/[^\p{L}\p{N}]/gu, '').length < 10) throw new RepositoryError('reason_required');
      const wasSent = o.status === 'sent';
      o.status = 'withdrawn';
      o.withdrawn = { at: new Date().toISOString(), byName: admin.name, reason: reason.trim() };
      o.events.push(ofEvent('withdrawn', admin.name, reason.trim()));
      if (wasSent) screeningMessage(app, 'offer_term_response', 'agreement.message.withdrawn', admin.name, reason);
      return ofDetailOf(app, Date.now());
    }),

  respondTermRequest: (applicationId, requestId, input, userId) =>
    simulateWrite((): OfferDetailView => {
      const admin = ofAdmin(userId);
      const app = ofApp(applicationId);
      const o = app.offer;
      const req = o?.requests.find((r) => r.id === requestId);
      if (!o || o.status !== 'sent' || !req || req.response) throw new RepositoryError('not_open');
      const note = input.note.trim();
      if (input.outcome === 'approved') {
        const problem = ofAddendumProblem(app.role, o.terms, input.items ?? [], note);
        if (problem) throw new RepositoryError(problem);
        o.addendum = { items: (input.items ?? []).map((i) => ({ key: i.key, value: i.value })), reason: note, approvedByName: admin.name, approvedAt: new Date().toISOString() };
        o.events.push(ofEvent('addendum', admin.name, (input.items ?? []).map((i) => `${i.key}=${i.value}`).join(', ')));
      } else if (note.replace(/[^\p{L}\p{N}]/gu, '').length < OF_REQUEST_MIN) throw new RepositoryError('reason_required');
      req.response = { at: new Date().toISOString(), byName: admin.name, outcome: input.outcome, note };
      o.events.push(ofEvent('response', admin.name, input.outcome));
      screeningMessage(app, 'offer_term_response', input.outcome === 'approved' ? 'agreement.message.approved' : 'agreement.message.declined', admin.name, note);
      syncOffers(Date.now());
      return ofDetailOf(app, Date.now());
    }),

  markActivationStep: (applicationId, step, done, userId) =>
    simulateWrite((): OfferDetailView => {
      const admin = ofAdmin(userId);
      const app = ofApp(applicationId);
      const a = app.offer?.activation;
      if (!app.offer || !a || !a.steps[step]) throw new RepositoryError('not_open');
      a.steps[step] = done ? { done: true, at: new Date().toISOString(), byName: admin.name } : { done: false };
      app.offer.events.push(ofEvent('step', admin.name, `${step}:${done ? 'done' : 'open'}`));
      return ofDetailOf(app, Date.now());
    }),

  getAgreementTemplates: (userId) =>
    simulateRead((): AgreementTemplatesView => {
      ofAdmin(userId);
      const now = Date.now();
      return { roles: (['surveyor', 'technician', 'supplier'] as const).map((role) => ({ role, current: JSON.parse(JSON.stringify(templateInForce(role, now))) as PartnerAgreementTemplate, versions: agreementTemplates.filter((t) => t.role === role).sort((a, b) => b.version - a.version).map((t) => JSON.parse(JSON.stringify(t)) as PartnerAgreementTemplate), defs: ofDefs(role) })) };
    }),

  publishAgreementTemplate: (role, input, userId) =>
    simulateWrite((): AgreementTemplatesView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      if (input.changeNote.replace(/[^\p{L}\p{N}]/gu, '').length < OF_REASON_MIN) throw new RepositoryError('reason_required');
      const today = new Date(now);
      const p = (n: number) => String(n).padStart(2, '0');
      const todayKey = `${today.getFullYear()}-${p(today.getMonth() + 1)}-${p(today.getDate())}`;
      if (!/^\d{4}-\d{2}-\d{2}$/.test(input.effectiveFrom) || input.effectiveFrom < todayKey) throw new RepositoryError('effective_past');
      const defs = ofTermDefs[role];
      const terms: AgreementTerms = {};
      for (const d of defs) {
        const v = Number((input.terms as Record<string, unknown>)[d.key]);
        if (!Number.isFinite(v) || v < d.min || v > d.max) throw new RepositoryError('invalid_terms');
        (terms as Record<string, unknown>)[d.key] = v;
      }
      if (role === 'supplier') terms.qualityStandards = (input.terms.qualityStandards ?? '').trim() || ofDefaultTerms('supplier').qualityStandards;
      const last = agreementTemplates.filter((t) => t.role === role).sort((a, b) => b.version - a.version)[0];
      // A new version is for agreements prepared from now on: nothing already offered or signed is touched.
      agreementTemplates.push({ id: `pat-${role}-${last.version + 1}`, role, version: last.version + 1, effectiveFrom: input.effectiveFrom, terms, wording: 'v1', changeNote: input.changeNote.trim(), createdByName: admin.name, createdAt: new Date(now).toISOString(), isDemo: true });
      return { roles: (['surveyor', 'technician', 'supplier'] as const).map((r) => ({ role: r, current: JSON.parse(JSON.stringify(templateInForce(r, now))) as PartnerAgreementTemplate, versions: agreementTemplates.filter((t) => t.role === r).sort((a, b) => b.version - a.version).map((t) => JSON.parse(JSON.stringify(t)) as PartnerAgreementTemplate), defs: ofDefs(r) })) };
    }),

  getOfferForApplicant: (applicationId, key) =>
    simulateRead((): OfferApplicantView => {
      const { app } = applicationFor(applicationId, { key });
      if (app.status !== 'approved') throw new RepositoryError('not_approved');
      return ofApplicantViewOf(app);
    }),

  requestTermChange: (applicationId, key, text) =>
    simulateWrite((): OfferApplicantView => {
      const { app } = applicationFor(applicationId, { key });
      if (app.status !== 'approved') throw new RepositoryError('not_approved');
      const o = app.offer;
      if (!o || o.status !== 'sent') throw new RepositoryError('not_open');
      if (o.requests.some((r) => !r.response)) throw new RepositoryError('request_open');
      if (text.replace(/[^\p{L}\p{N}]/gu, '').length < OF_REQUEST_MIN) throw new RepositoryError('request_short');
      offerEventCounter += 1;
      o.requests.push({ id: `ofreq-${offerEventCounter}`, at: new Date().toISOString(), text: text.trim() });
      o.events.push(ofEvent('request', app.form.personal.fullName));
      syncOffers(Date.now());
      return ofApplicantViewOf(app);
    }),

  signPartnerAgreement: (applicationId, key, input) =>
    simulateWrite((): OfferApplicantView => {
      const { app } = applicationFor(applicationId, { key });
      if (app.status !== 'approved') throw new RepositoryError('not_approved');
      const o = app.offer;
      if (!o) throw new RepositoryError('not_open');
      if (o.status === 'signed') throw new RepositoryError('already_signed');
      if (o.status !== 'sent') throw new RepositoryError('not_open');
      const problem = ofSignProblem({ consent: input.consentGiven, otpVerified: input.otpVerified, method: input.method, data: input.data, signerName: input.signerName });
      if (problem) throw new RepositoryError(problem);
      // A question about a term waits for its answer: signing over an unanswered request would sign something they have said they want to discuss.
      if (o.requests.some((r) => !r.response)) throw new RepositoryError('request_open');
      if (ofPhoneTaken(app)) throw new RepositoryError('phone_taken');
      const at = new Date().toISOString();
      o.signature = { at, method: input.method, data: input.data, signerName: input.signerName.trim(), language: input.language, otpVerified: input.otpVerified, viaFallback: input.viaFallback, consentGiven: true };
      o.status = 'signed';
      o.events.push(ofEvent('signed', input.signerName.trim(), input.viaFallback ? 'fallback' : 'otp'));
      ofActivate(app, o, at);
      screeningMessage(app, 'offer_signed', 'agreement.message.signed', 'AIEC');
      app.updatedAt = at;
      return ofApplicantViewOf(app);
    }),

  /* --------------------------------- Recruitment: the pipeline overview (147) */
  getRecruitmentDashboard: (period, userId) =>
    simulateRead((): RecruitmentDashboardView => {
      ofAdmin(userId);
      return rdBuild(period, Date.now());
    }),

  waitlistApplicant: (applicationId, reason, userId) =>
    simulateWrite((): RecruitmentDashboardView => {
      const admin = ofAdmin(userId);
      const app = ofApp(applicationId);
      if (app.offer?.status === 'signed') throw new RepositoryError('already_signed');
      if (app.offer?.status === 'sent') throw new RepositoryError('already_sent');
      if (reason.replace(/[^\p{L}\p{N}]/gu, '').length < RD_WAITLIST_MIN) throw new RepositoryError('reason_required');
      app.waitlist = { at: new Date().toISOString(), byName: admin.name, reason: reason.trim() };
      screeningMessage(app, 'waitlisted', 'recruitment.message.waitlisted', admin.name);
      return rdBuild(90, Date.now());
    }),

  releaseWaitlisted: (applicationId, userId) =>
    simulateWrite((): RecruitmentDashboardView => {
      ofAdmin(userId);
      const app = ofApp(applicationId);
      if (!app.waitlist) throw new RepositoryError('not_open');
      delete app.waitlist;
      return rdBuild(90, Date.now());
    }),

  /* --------------------------------- Training module library (151) */
  getTrainingLibrary: (scope, userId) =>
    simulateRead((): TrainingLibraryView => {
      const person = tnPersonOf(userId);
      if (!person) throw new RepositoryError('forbidden');
      const now = Date.now();
      const status = tnStatusFn(person.userIds, now);
      const pool = trainingModules.filter((m) => m.status === 'published');
      const shown = pool.filter((m) => (scope === 'required' ? tnRequired(m, person.roles) : scope === 'mine' ? tnRelevant(m, person.roles) : true));
      const gate = tnJobGate(pool, person.roles, status, (id) => asCertified(person.userIds, id, now));
      const topicCount = (topic: TrainingTopic) => { const req = pool.filter((m) => m.topic === topic && tnRequired(m, person.roles)); return { required: req.length, completed: req.filter((m) => status(m.id) === 'completed').length }; };
      return {
        person: { name: person.name, roles: person.roles },
        modules: shown.map((m) => tnViewOf(m, person, now)).sort((a, b) => TN_TOPICS.indexOf(a.topic) - TN_TOPICS.indexOf(b.topic) || a.order - b.order),
        curriculum: tnCurriculum(pool, person.roles, status),
        byTopic: { onboarding: topicCount('onboarding'), safety: topicCount('safety'), customer: topicCount('customer'), product: topicCount('product') },
        jobGate: { applies: gate.applies, cleared: gate.cleared, missing: gate.missing.map((m) => ({ id: m.id, code: m.code, needs: (status(m.id) === 'completed' ? 'test' : 'lessons') as 'lessons' | 'test' })) },
        at: new Date(now).toISOString(),
      };
    }),

  recordTrainingProgress: (moduleId, input, userId) =>
    simulateWrite((): TrainingModuleView => {
      const person = tnPersonOf(userId);
      if (!person) throw new RepositoryError('forbidden');
      const m = byId(trainingModules, moduleId);
      if (!m) throw new RepositoryError('not_found');
      const now = Date.now();
      const status = tnStatusFn(person.userIds, now);
      const problem = tnStartProblem(m, person.roles, tnLockedBy(m, trainingModules, status));
      if (problem) throw new RepositoryError(problem);
      const at = new Date(now).toISOString();
      const version = tnCurrentVersion(m, now).version;
      const mine = trainingLessons.filter((l) => l.moduleId === moduleId);
      // A module with lessons is finished only by playing them (completeLesson); one without cannot be started.
      if (mine.length === 0) throw new RepositoryError('invalid_state');
      if (input.status === 'completed') throw new RepositoryError('invalid_state');
      const own = trainingProgress.find((p) => p.userId === userId && p.moduleId === moduleId);
      if (own && own.status === 'completed') {
        if (tnStatus(m, own, now) === 'completed') return tnViewOf(m, person, now);
        // A retake after a revision: what they finished and that has not changed since stays done; only what moved is asked again.
        for (const l of mine) {
          if (l.changedInVersion <= own.version && !lessonProgress.some((p) => p.userId === userId && p.lessonId === l.id && p.completedAt)) {
            const total = lsDuration(l);
            lessonProgress.push({ userId, lessonId: l.id, moduleId, version: own.version, positionS: 0, furthestS: total, checks: l.checks.map((c) => ({ checkId: c.id, attempts: [], clearedAt: own.completedAt ?? at })), startedAt: own.startedAt, updatedAt: at, completedAt: own.completedAt ?? at });
          }
        }
      }
      if (!own) trainingProgress.push({ userId, moduleId, status: 'in_progress', startedAt: at, version, lessonsDone: 0 });
      tnSyncModuleProgress(m, userId, person, now);
      return tnViewOf(m, person, now);
    }),

  /* --------------------------------- Certification badges and progress (155) */
  getCertifications: (userId) =>
    simulateRead((): CertificationsView => {
      const person = tnPersonOf(userId);
      if (!person) throw new RepositoryError('forbidden');
      const now = Date.now();
      const all = certBadges.filter((b) => person.userIds.includes(b.userId)).sort((a, b) => b.issuedAt.localeCompare(a.issuedAt));
      const latestIds = new Set(certLatestOf(person.userIds).map((b) => b.id));
      const badges = all.map((b) => certBadgeViewOf(b, latestIds.has(b.id), now));
      const latest = badges.filter((b) => b.latest);
      const required = trainingModules.filter((m) => m.status === 'published' && tnRequired(m, person.roles) && asOf(m.id));
      return {
        person: { name: person.name, roles: person.roles }, badges,
        summary: { current: latest.filter((b) => b.status === 'valid' || b.status === 'expiring').length, expiring: latest.filter((b) => b.status === 'expiring').length, expired: latest.filter((b) => b.status === 'expired').length, earlier: latest.filter((b) => b.earlierStandard).length, required: required.length, requiredHeld: required.filter((m) => latest.some((b) => b.moduleId === m.id && (b.status === 'valid' || b.status === 'expiring'))).length },
        nextSteps: certNextSteps(person, now), standing: certStandingOf(userId, now), hidden: certPrefs.some((p) => p.userId === userId && p.hidden), at: new Date(now).toISOString(),
      };
    }),

  setCertificationVisibility: (hidden, userId) =>
    simulateWrite(() => {
      if (!tnPersonOf(userId)) throw new RepositoryError('forbidden');
      const pref = certPrefs.find((p) => p.userId === userId);
      if (pref) pref.hidden = hidden; else certPrefs.push({ userId, hidden });
      return { hidden };
    }),

  /* --------------------------------- Quiz and certification (154) */
  getAssessment: (moduleId, userId) =>
    simulateRead((): AssessmentView => {
      const now = Date.now();
      const { person, m, a } = asAccess(moduleId, userId, now);
      return asView(m, a, person, now);
    }),

  startAssessmentAttempt: (moduleId, userId) =>
    simulateWrite((): AssessmentAttemptView => {
      const now = Date.now();
      const { person, m, a } = asAccess(moduleId, userId, now);
      const st = asStateOf(m, a, person.userIds, now);
      if (st.state === 'certified' && !st.renewable) throw new RepositoryError('already_certified');
      if (st.state === 'certified' && st.cooldownUntil) throw new RepositoryError('cooldown');
      if (st.state === 'locked') throw new RepositoryError('not_ready');
      if (st.state === 'cooldown') throw new RepositoryError('cooldown');
      const version = tnCurrentVersion(m, now).version;
      const at = new Date(now).toISOString();
      // An attempt begun on content that has since been revised is set aside: nobody is tested on a standard that no longer reads that way.
      for (const x of assessmentAttempts) if (x.assessmentId === a.id && x.userId === userId && x.status === 'in_progress' && x.version !== version) { x.status = 'void'; x.updatedAt = at; }
      const open = assessmentAttempts.find((x) => x.assessmentId === a.id && x.userId === userId && x.status === 'in_progress' && x.version === version);
      if (open) return asAttemptViewOf(open, a, m);
      assessmentAttemptCounter += 1;
      const id = `at-${assessmentAttemptCounter}`;
      const total = assessmentAttempts.filter((x) => x.assessmentId === a.id && person.userIds.includes(x.userId) && x.status !== 'void').length;
      const att: AssessmentAttempt = { id, assessmentId: a.id, moduleId: m.id, userId, version, attemptNumber: total + 1, questionIds: asOrder(id, asQuestions(a, version).map((q) => q.id)), answers: [], status: 'in_progress', startedAt: at, updatedAt: at };
      assessmentAttempts.push(att);
      return asAttemptViewOf(att, a, m);
    }),

  saveAssessmentDraft: (attemptId, answers, userId) =>
    simulateWrite(() => {
      const att = byId(assessmentAttempts, attemptId);
      if (!att || att.userId !== userId) throw new RepositoryError('attempt_not_found');
      if (att.status !== 'in_progress') throw new RepositoryError('already_submitted');
      const a = byId(assessments, att.assessmentId) as Assessment;
      const kept: AssessmentAnswer[] = [];
      for (const ans of answers) {
        if (!att.questionIds.includes(ans.questionId)) throw new RepositoryError('unknown_question');
        if (ans.selected.length === 0) continue;
        const problem = asAnswerProblem(a.questions.find((q) => q.id === ans.questionId), ans.selected);
        if (problem) throw new RepositoryError(problem);
        kept.push({ questionId: ans.questionId, selected: [...new Set(ans.selected)].sort() });
      }
      att.answers = kept;
      att.updatedAt = new Date().toISOString();
      return { saved: kept.length };
    }),

  submitAssessment: (attemptId, answers, userId) =>
    simulateWrite((): AssessmentResultView => {
      const now = Date.now();
      const att = byId(assessmentAttempts, attemptId);
      if (!att || att.userId !== userId) throw new RepositoryError('attempt_not_found');
      if (att.status !== 'in_progress') throw new RepositoryError('already_submitted');
      const { person, m, a } = asAccess(att.moduleId, userId, now);
      const at = new Date(now).toISOString();
      if (att.version !== tnCurrentVersion(m, now).version) { att.status = 'void'; att.updatedAt = at; throw new RepositoryError('outdated'); }
      const given: AssessmentAnswer[] = [];
      for (const ans of answers) {
        if (!att.questionIds.includes(ans.questionId)) throw new RepositoryError('unknown_question');
        const problem = asAnswerProblem(a.questions.find((q) => q.id === ans.questionId), ans.selected);
        if (problem) throw new RepositoryError(problem);
        given.push({ questionId: ans.questionId, selected: [...new Set(ans.selected)].sort() });
      }
      // Never handed in blind: every question has an answer.
      if (att.questionIds.some((id) => !given.some((g) => g.questionId === id))) throw new RepositoryError('incomplete');
      const questions = att.questionIds.map((id) => a.questions.find((q) => q.id === id)).filter((q): q is NonNullable<typeof q> => !!q);
      const scored = asScore(questions, given);
      att.answers = given;
      att.status = 'submitted';
      att.submittedAt = at;
      att.updatedAt = at;
      att.correctCount = scored.correctCount;
      att.score = scored.score;
      att.passPercent = a.passPercent;
      att.passed = asPassed(scored.score, a.passPercent);
      // Passing is the one event that issues the certification; nothing else does.
      const held = asBadgeOf(person.userIds, m, now);
      // The certification this one renews: the one still held, or the one that ran out.
      const prior = held ?? certBadges.filter((b) => b.moduleId === m.id && person.userIds.includes(b.userId)).sort((x, y) => y.issuedAt.localeCompare(x.issuedAt))[0];
      if (att.passed && (!held || asRenewable(held, now))) {
        certCounter += 1;
        certBadges.push({ id: `cb-${att.id}`, code: `AIEC-CT-${certCounter}`, userId, moduleId: m.id, assessmentId: a.id, version: att.version, score: scored.score, attemptId: att.id, issuedAt: at, expiresAt: asExpiry(at, a.validMonths), ...(prior ? { renewedFromId: prior.id } : {}) });
      }
      syncAssessmentAlerts(now);
      syncCertifications(now);
      return asResultOf(att, a, m, person, now);
    }),

  getAssessmentOverview: (adminId) =>
    simulateRead((): AssessmentOverviewView => {
      ofAdmin(adminId);
      const now = Date.now();
      syncAssessmentAlerts(now);
      syncCertifications(now);
      return { rows: assessments.map((a) => asOverviewRow(a, now)), at: new Date(now).toISOString() };
    }),

  saveAssessmentConfig: (assessmentId, input, adminId) =>
    simulateWrite((): AssessmentOverviewRow => {
      ofAdmin(adminId);
      const a = byId(assessments, assessmentId);
      if (!a) throw new RepositoryError('no_assessment');
      const problem = asConfigProblem(input.passPercent, input.cooldownHours, input.validMonths);
      if (problem) throw new RepositoryError(problem);
      a.validMonths = input.validMonths;
      a.passPercent = input.passPercent;
      a.cooldownHours = [input.cooldownHours[0], input.cooldownHours[1], input.cooldownHours[2]];
      return asOverviewRow(a, Date.now());
    }),

  /* --------------------------------- Lesson player (152) */
  getModuleLessons: (moduleId, userId) =>
    simulateRead((): ModuleLessonsView => {
      const person = tnPersonOf(userId);
      if (!person) throw new RepositoryError('forbidden');
      const m = byId(trainingModules, moduleId);
      if (!m) throw new RepositoryError('not_found');
      const now = Date.now();
      const problem = tnStartProblem(m, person.roles, tnLockedBy(m, trainingModules, tnStatusFn(person.userIds, now)));
      if (problem) throw new RepositoryError(problem);
      if (!trainingLessons.some((l) => l.moduleId === moduleId)) throw new RepositoryError('no_lessons');
      return tnModuleLessonsOf(m, person, now);
    }),

  saveLessonPlayback: (lessonId, input, userId) =>
    simulateWrite((): LessonView => {
      const now = Date.now();
      const { person, l, m, lv } = tnLessonAccess(lessonId, userId, now);
      if (lv.state === 'done') return lv;
      const at = new Date(now).toISOString();
      const row = tnLessonRowForWrite(userId, l, tnCurrentVersion(m, now).version, at);
      const clamp = lsClamp(l, lsCleared(tnLessonRowOf(person.userIds, l.id)), input.positionS, input.furthestS);
      // Playback only ever moves forward as far as it has genuinely been played; going back (to replay) does not lose it.
      row.furthestS = Math.max(row.furthestS, clamp.furthestS);
      row.positionS = Math.min(clamp.positionS, row.furthestS);
      row.updatedAt = at;
      tnSyncModuleProgress(m, userId, person, now);
      return tnModuleLessonsOf(m, person, now).lessons.find((x) => x.id === lessonId) as LessonView;
    }),

  answerLessonCheck: (lessonId, checkId, selected, userId) =>
    simulateWrite((): LessonAnswerResult => {
      const now = Date.now();
      const { person, l, m, lv } = tnLessonAccess(lessonId, userId, now);
      const check = l.checks.find((c) => c.id === checkId);
      if (!check) throw new RepositoryError('unknown_check');
      const bad = lsAnswerProblem(check, selected);
      if (bad) throw new RepositoryError(bad);
      const at = new Date(now).toISOString();
      const row = tnLessonRowForWrite(userId, l, tnCurrentVersion(m, now).version, at);
      // A check can only be answered once the lesson has been played up to it.
      if (row.furthestS < lsCheckAt(l, check) - 1 && lv.state !== 'done') throw new RepositoryError('invalid_state');
      let resp = row.checks.find((c) => c.checkId === checkId);
      if (!resp) { resp = { checkId, attempts: [] }; row.checks.push(resp); }
      const correct = lsIsCorrect(check, selected);
      if (!resp.clearedAt) {
        resp.attempts.push({ at, selected: [...new Set(selected)].sort(), correct });
        if (correct) resp.clearedAt = at;
      }
      row.updatedAt = at;
      tnSyncModuleProgress(m, userId, person, now);
      const view = tnModuleLessonsOf(m, person, now).lessons.find((x) => x.id === lessonId) as LessonView;
      return { correct, cleared: !!resp.clearedAt, attempts: resp.attempts.length, lesson: view };
    }),

  completeLesson: (lessonId, userId) =>
    simulateWrite((): LessonCompleteResult => {
      const now = Date.now();
      const { person, l, m, lv } = tnLessonAccess(lessonId, userId, now);
      if (lv.state !== 'done') {
        const at = new Date(now).toISOString();
        const row = tnLessonRowForWrite(userId, l, tnCurrentVersion(m, now).version, at);
        const problem = lsCompleteProblem(l, row);
        if (problem) throw new RepositoryError(problem);
        row.completedAt = at;
        row.positionS = lsDuration(l);
        row.furthestS = lsDuration(l);
        row.updatedAt = at;
        tnSyncModuleProgress(m, userId, person, now);
      }
      const view = tnModuleLessonsOf(m, person, now);
      const idx = view.lessons.findIndex((x) => x.id === lessonId);
      const next = view.lessons.slice(idx + 1).find((x) => x.state === 'current');
      return { lesson: view.lessons[idx], module: view, moduleDone: view.moduleDone, nextLessonId: next?.id ?? null };
    }),

  /* --------------------------------- SOP document repository (153) */
  getSopLibrary: (userId) =>
    simulateRead((): SopLibraryView => {
      const u = spReader(userId);
      return spLibraryOf(userId, u.role === 'admin', Date.now());
    }),

  toggleSopBookmark: (docId, on, userId) =>
    simulateWrite(() => {
      const u = spReader(userId);
      const now = Date.now();
      if (!spLibraryOf(userId, u.role === 'admin', now).docs.some((d) => d.id === docId)) throw new RepositoryError('not_found');
      const at = sopBookmarks.findIndex((b) => b.userId === userId && b.docId === docId);
      if (on && at < 0) sopBookmarks.push({ userId, docId, at: new Date(now).toISOString() });
      if (!on && at >= 0) sopBookmarks.splice(at, 1);
      return { docId, bookmarked: on };
    }),

  addSopCategory: (input, adminId) =>
    simulateWrite((): SopCategoryView => {
      const admin = ofAdmin(adminId);
      const existing = [...SOP_BUILT_IN.map((id) => id), ...sopCategories.flatMap((c) => [c.name, c.nameHi ?? '', c.nameMr ?? ''])].filter(Boolean);
      const problem = sopCategoryProblem(input.name, [...existing, 'Installation', 'Delivery', 'Safety', 'Quality']);
      if (problem) throw new RepositoryError(problem);
      const cat: SopCategory = { id: `sc-${sopCategories.length + 1}`, name: input.name.trim(), ...(input.nameHi?.trim() ? { nameHi: input.nameHi.trim() } : {}), ...(input.nameMr?.trim() ? { nameMr: input.nameMr.trim() } : {}), createdByName: admin.name, createdAt: new Date().toISOString() };
      sopCategories.push(cat);
      return { id: cat.id, name: spCategoryName(cat), builtIn: false, count: 0 };
    }),

  saveSopReference: (input: SopReferenceInput, adminId) =>
    simulateWrite((): SopDocumentView => {
      const admin = ofAdmin(adminId);
      const now = Date.now();
      const doc = input.docId ? byId(sopReferences, input.docId) : undefined;
      if (input.docId && !doc) throw new RepositoryError(spLibraryOf(adminId, true, now).docs.some((d) => d.id === input.docId) ? 'not_editable' : 'not_found');
      const prev = doc ? [...doc.versions].sort((a, b) => b.version - a.version)[0] : null;
      const problem = sopReferenceProblem(input, { categoryIds: sopCategories.map((c) => c.id), previousEffective: prev?.effectiveFrom ?? null, now });
      if (problem) throw new RepositoryError(problem);
      const at = new Date(now).toISOString();
      const en = input.steps.en.map((x) => x.trim()).filter(Boolean);
      const clean = (a: string[]) => a.map((x) => x.trim()).filter(Boolean);
      const hi = clean(input.steps.hi);
      const mr = clean(input.steps.mr);
      const items = en.map((text, i) => ({ en: text, ...(hi[i] ? { hi: hi[i] } : {}), ...(mr[i] ? { mr: mr[i] } : {}) }));
      const version = { version: (prev?.version ?? 0) + 1, effectiveFrom: new Date(`${input.effectiveFrom}T00:00:00.000Z`).toISOString(), changeNote: prev ? input.changeNote.trim() : 'First published.', publishedByName: admin.name, publishedAt: at, items };
      let target = doc;
      if (!target) {
        target = { id: `sref-${sopReferences.length + 1}`, categoryId: input.categoryId, title: input.title.en.trim(), ...(input.title.hi?.trim() ? { titleHi: input.title.hi.trim() } : {}), ...(input.title.mr?.trim() ? { titleMr: input.title.mr.trim() } : {}), versions: [], createdByName: admin.name, createdAt: at };
        sopReferences.push(target);
      } else {
        // A new version keeps the document where it is and may carry a corrected title.
        target.title = input.title.en.trim();
        if (input.title.hi?.trim()) target.titleHi = input.title.hi.trim(); else delete target.titleHi;
        if (input.title.mr?.trim()) target.titleMr = input.title.mr.trim(); else delete target.titleMr;
      }
      target.versions.push(version);
      return spLibraryOf(adminId, true, now).docs.find((d) => d.id === (target as SopReferenceDocument).id) as SopDocumentView;
    }),

  /* --------------------------------- Partner deactivation and exit (150) */
  getExitBoard: (userId) =>
    simulateRead((): ExitBoardView => {
      ofAdmin(userId);
      const now = Date.now();
      syncPartnerExits(now);
      const rows = partnerExits.map((e) => exRowOf(e, now));
      const year = rows.filter((r) => r.status !== 'cancelled' && now - new Date(r.startedAt).getTime() < 365 * 86_400_000);
      const tally = new Map<string, { reason: string; kind: ExitKind; count: number }>();
      for (const r of year) {
        const k = `${r.kind}:${r.reason}`;
        const cur = tally.get(k) ?? { reason: r.reason, kind: r.kind, count: 0 };
        cur.count += 1;
        tally.set(k, cur);
      }
      const tenure = partnerExits.filter((e) => e.status === 'completed').map((e) => { const j = exPartner(e.partnerId); const from = (j.user?.joinedAt ?? (j.supplier ? supplierUserFor(j.supplier)?.joinedAt ?? j.supplier.invitedAt : undefined)); return from ? (new Date(`${e.lastDay}T00:00:00`).getTime() - new Date(from).getTime()) / (30 * 86_400_000) : null; }).filter((x): x is number => x !== null && x >= 0);
      return {
        open: rows.filter((r) => r.status === 'in_progress').sort((a, b) => a.lastDay.localeCompare(b.lastDay)),
        done: rows.filter((r) => r.status !== 'in_progress').sort((a, b) => (b.completedAt ?? b.startedAt).localeCompare(a.completedAt ?? a.startedAt)),
        attrition: { total: year.length, involuntary: year.filter((r) => r.kind === 'involuntary').length, byReason: [...tally.values()].sort((a, b) => b.count - a.count), byType: { surveyor: year.filter((r) => r.partnerType === 'surveyor').length, technician: year.filter((r) => r.partnerType === 'technician').length, supplier: year.filter((r) => r.partnerType === 'supplier').length }, avgTenureMonths: tenure.length >= 3 ? Math.round(tenure.reduce((n, x) => n + x, 0) / tenure.length) : null },
      };
    }),

  getPartnerExit: (partnerId, userId) =>
    simulateRead((): PartnerExitView => {
      ofAdmin(userId);
      const now = Date.now();
      syncPartnerExits(now);
      return exViewOf(partnerId, now);
    }),

  startPartnerExit: (partnerId, input, userId) =>
    simulateWrite((): PartnerExitView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      const info = exPartner(partnerId);
      if (exitUnderWay(partnerId)) throw new RepositoryError('exit_open');
      if (info.status !== 'active') throw new RepositoryError('not_active');
      const problem = exStartProblem(input, tcToday(now), tcToday(now + EX_LAST_DAY_MAX * 86_400_000));
      if (problem) throw new RepositoryError(problem);
      exitCounter += 1;
      const at = new Date(now).toISOString();
      const exit: PartnerExit = { id: `ex-${exitCounter}`, code: `AIEC-EX-${1000 + exitCounter}`, partnerId, partnerType: info.type, partnerName: info.name, kind: input.kind, reason: input.reason, note: input.note.trim(), lastDay: input.kind === 'involuntary' ? tcToday(now) : input.lastDay, startedAt: at, startedByName: admin.name, status: 'in_progress', actions: [], events: [], isDemo: true };
      partnerExits.push(exit);
      exEvent(exit, 'started', admin.name, input.reason);
      if (input.kind === 'involuntary') {
        // A serious violation: nothing waits. Access ends first, and the work and the money are handled afterwards by someone who is not them.
        exEndAccess(exit, admin.name, true, now);
        raiseAlert({ titleKey: EXIT_VIOLATION_ALERT, context: `${info.name} was removed from the network (${input.reason})`, severity: 'high', category: input.reason === 'safety_violation' ? 'safety' : 'staffing', relatedId: `exit:${exit.id}`, sourceRoute: `/partner-exit/${partnerId}` });
      }
      return exViewOf(partnerId, now);
    }),

  resolveExitItems: (partnerId, input, userId) =>
    simulateWrite((): PartnerExitView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      const exit = exOpenExit(partnerId);
      if (exLetters(input.note) < EX_ACTION_NOTE_MIN) throw new RepositoryError('note_required');
      const work = exWorkOf(exit, partnerId, exit.partnerType).filter((w) => w.type === input.type && input.itemIds.includes(w.id));
      if (work.length === 0 || work.length !== new Set(input.itemIds).size) throw new RepositoryError('item_not_open');
      const allowed: Record<ExitItemType, ExitActionKind[]> = { lead: ['reassigned', 'returned_to_pool'], job: ['reassigned'], order: exit.kind === 'voluntary' ? ['reassigned', 'finish_first', 'alternate_sourcing', 'cancelled'] : ['reassigned', 'alternate_sourcing', 'cancelled'] };
      if (!allowed[input.type].includes(input.action)) throw new RepositoryError(input.action === 'finish_first' ? 'finish_not_allowed' : 'action_invalid');
      const at = new Date(now).toISOString();
      let toName: string | undefined;
      if (input.action === 'reassigned' || input.action === 'alternate_sourcing') {
        if (!input.toId) throw new RepositoryError('target_required');
        const to = input.type === 'order' ? byId(suppliers, input.toId) : byId(users, input.toId);
        const okTarget = input.type === 'lead' ? (to as User | null)?.role === 'surveyor' : input.type === 'job' ? (to as User | null)?.role === 'technician' : !!to;
        const activeTarget = input.type === 'order' ? (to as Supplier | null)?.status === 'active' : (to as User | null)?.status === 'active';
        if (!to || !okTarget || !activeTarget || input.toId === partnerId || !acceptsNewWork(input.toId)) throw new RepositoryError('target_invalid');
        toName = to.name;
      }
      for (const w of work) {
        if (w.type === 'lead') {
          const lead = byId(leads, w.id) as Lead;
          const toId = input.action === 'reassigned' ? (input.toId as string) : '';
          patchInPlace(leads, lead.id, { surveyorId: toId, updatedAt: at });
          pushTimelineEvent({ leadId: lead.id, kind: 'reassigned', actorName: admin.name, at, detail: input.note.trim(), fromValue: nameOf(partnerId), toValue: toId ? nameOf(toId) : undefined });
        } else if (w.type === 'job') {
          const job = byId(jobs, w.id) as Job;
          const toId = input.toId as string;
          let crew = crewOf(job);
          if (!crew.some((c) => c.userId === toId)) crew = [...crew, { userId: toId, role: 'assistant' as const, stepIds: [] }];
          const member = crew.find((c) => c.userId === partnerId);
          const isLead = job.technicianId === partnerId;
          if (isLead && !tcCanLead(toId)) throw new RepositoryError('target_invalid');
          if (!trainingClear(toId)) throw new RepositoryError('training_incomplete');
          // Their finished steps keep their name; what is still open goes to the person taking over, with their notes carried on the job's own team log.
          const openOwned = (member?.stepIds ?? []).filter((id) => job.steps.find((st) => st.id === id)?.status !== 'complete');
          const next = crew.filter((c) => c.userId !== partnerId).map((c) => (c.userId === toId ? { ...c, role: isLead ? ('lead' as const) : c.role, stepIds: isLead ? [] : [...new Set([...c.stepIds, ...openOwned])] } : c));
          logTeam(job, teamEvent('reassigned', admin.name, nameOf(partnerId), input.note.trim()), { crew: next, ...(isLead ? { technicianId: toId } : {}) });
          if (isLead) logTeam(byId(jobs, job.id) as Job, teamEvent('lead_changed', admin.name, nameOf(toId), input.note.trim()));
          // A site visit left open by someone who has gone is closed at the moment they were last known to be there, never guessed.
          for (const v of siteCheckIns.filter((x) => x.jobId === job.id && x.userId === partnerId && !x.checkOutAt)) patchInPlace(siteCheckIns, v.id, { checkOutAt: v.checkInAt, checkOutNote: 'Closed when the partner left the network' } as Partial<SiteCheckIn>);
        } else if (input.action === 'reassigned') {
          const po = byId(supplierPurchaseOrders, w.id) as SupplierPurchaseOrder;
          if (po.status === 'sent') throw new RepositoryError('action_invalid');
          const repriced = (po.lineItems ?? []).map((line): PurchaseOrderLineItem => { const price = catalogPriceFor(input.toId as string, line.category) ?? 0; return { ...line, catalogUnitPriceAtDraft: price, agreedUnitPrice: price }; });
          patchInPlace(supplierPurchaseOrders, po.id, { supplierId: input.toId as string, lineItems: repriced, approvedBy: undefined, approvedAt: undefined, selection: undefined, matchedByRulesVersion: undefined });
        } else if (input.action === 'cancelled' && w.detail !== 'sent') {
          patchInPlace(supplierPurchaseOrders, w.id, { status: 'failed' as const, failureReason: `Partner exit ${exit.code}` });
        }
        exit.actions.push({ id: `exa-${exit.actions.length + 1}-${exit.id}`, itemType: w.type, itemId: w.id, label: w.label, action: input.action, ...(input.toId ? { toId: input.toId } : {}), ...(toName ? { toName } : {}), note: input.note.trim(), byName: admin.name, at });
      }
      exEvent(exit, 'work_handled', admin.name, `${work.length} ${input.type}`);
      if (exit.partnerType === 'supplier' && input.action !== 'finish_first') {
        const sup = byId(suppliers, partnerId);
        const portal = sup ? supplierUserFor(sup) : undefined;
        if (sup && portal && (input.action === 'cancelled' || input.action === 'alternate_sourcing')) {
          const thread = ensureSupplierThread(partnerId);
          pushSupplierMessage(thread, { author: 'aiec', authorName: admin.name, authorUserId: admin.id, body: input.note.trim(), channel: 'in_app', at, expectsReply: false });
        }
      }
      exMaybeComplete(exit, now);
      return exViewOf(partnerId, now);
    }),

  confirmExitSettlement: (partnerId, input, userId) =>
    simulateWrite((): PartnerExitView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      const exit = exOpenExit(partnerId);
      const at = new Date(now).toISOString();
      if (exit.settlement?.withheld && input.releaseNote !== undefined) {
        if (exLetters(input.releaseNote) < EX_WITHHOLD_MIN) throw new RepositoryError('reason_required');
        delete exit.settlement.withheld;
        exEvent(exit, 'withhold_released', admin.name, input.releaseNote.trim());
        return exViewOf(partnerId, now);
      }
      if (exit.settlement && exit.settlement.status !== 'proposed') throw new RepositoryError('settlement_locked');
      if (input.withholdReason !== undefined && (exit.kind !== 'involuntary' || exLetters(input.withholdReason) < EX_WITHHOLD_MIN)) throw new RepositoryError('reason_required');
      const calc = exSettlementOf(partnerId, exit.partnerType);
      exit.settlement = { calculatedAt: at, byName: admin.name, lines: calc.lines, held: calc.held, amount: calc.amount, status: 'proposed', ...(input.withholdReason !== undefined ? { withheld: { reason: input.withholdReason.trim(), byName: admin.name, at } } : {}) };
      exEvent(exit, 'settlement_confirmed', admin.name, String(calc.amount));
      return exViewOf(partnerId, now);
    }),

  recordExitAgreement: (partnerId, input, userId) =>
    simulateWrite((): PartnerExitView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      const exit = exOpenExit(partnerId);
      const s = exit.settlement;
      if (!s) throw new RepositoryError('settlement_missing');
      if (s.status !== 'proposed') throw new RepositoryError('settlement_locked');
      if (exLetters(input.note) < EX_ACTION_NOTE_MIN) throw new RepositoryError('note_required');
      s.status = 'agreed';
      s.agreed = { at: new Date(now).toISOString(), byName: admin.name, how: input.how, note: input.note.trim() };
      exEvent(exit, 'settlement_agreed', admin.name, input.how);
      exMaybeComplete(exit, now);
      return exViewOf(partnerId, now);
    }),

  raiseExitSettlementDispute: (partnerId, input, userId) =>
    simulateWrite((): PartnerExitView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      const exit = exOpenExit(partnerId);
      const s = exit.settlement;
      if (!s) throw new RepositoryError('settlement_missing');
      if (s.status === 'paid' || s.dispute?.status === 'open') throw new RepositoryError(s.status === 'paid' ? 'settlement_locked' : 'dispute_open');
      if (s.dispute) throw new RepositoryError('settlement_locked');
      if (!(input.claimedAmount > exTotal(s))) throw new RepositoryError('amount_invalid');
      if (exLetters(input.grounds) < EX_DISPUTE_MIN) throw new RepositoryError('note_required');
      s.status = 'disputed';
      s.dispute = { id: `exd-${exit.id}`, claimedAmount: Math.round(input.claimedAmount), grounds: input.grounds.trim(), raisedAt: new Date(now).toISOString(), raisedByName: admin.name, status: 'open' };
      exEvent(exit, 'settlement_disputed', admin.name, String(input.claimedAmount));
      return exViewOf(partnerId, now);
    }),

  decideExitSettlementDispute: (partnerId, input, userId) =>
    simulateWrite((): PartnerExitView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      const exit = exOpenExit(partnerId);
      const s = exit.settlement;
      if (!s?.dispute || s.dispute.status !== 'open') throw new RepositoryError('no_dispute');
      const problem = exDecisionProblem(input, exTotal(s), s.dispute.claimedAmount);
      if (problem) throw new RepositoryError(problem === 'amount_invalid' ? 'amount_invalid' : 'note_required');
      const extra = exDecidedExtra(input.outcome, input.amount, exTotal(s), s.dispute.claimedAmount);
      const at = new Date(now).toISOString();
      s.dispute.status = 'decided';
      s.dispute.decision = { outcome: input.outcome, amount: extra, note: input.note.trim(), byName: admin.name, at };
      if (extra > 0) {
        let entryId: string | undefined;
        // The ledger is the one record of what a person is paid: a decision in their favour becomes an entry in it, not a figure kept on the side.
        if (exit.partnerType !== 'supplier') {
          closureCommissionCounter += 1;
          entryId = `c-new-${closureCommissionCounter}`;
          commissions.push({ id: entryId, userId: partnerId, reasonKey: 'commission.reason.exitSettlement', amount: extra, status: 'approved', earnedAt: at, isDemo: true });
        }
        s.adjustment = { amount: extra, ...(entryId ? { entryId } : {}), at };
      }
      s.status = 'agreed';
      s.agreed = { at, byName: admin.name, how: 'decision', note: input.note.trim() };
      exEvent(exit, 'dispute_decided', admin.name, `${input.outcome}:${extra}`);
      exMaybeComplete(exit, now);
      return exViewOf(partnerId, now);
    }),

  recordExitPayment: (partnerId, input, userId) =>
    simulateWrite((): PartnerExitView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      const exit = exOpenExit(partnerId);
      const s = exit.settlement;
      if (!s) throw new RepositoryError('settlement_missing');
      if (exit.partnerType === 'supplier') throw new RepositoryError('action_invalid');
      if (s.withheld) throw new RepositoryError('withheld');
      if (s.status !== 'agreed') throw new RepositoryError('settlement_locked');
      if (exTotal(s) <= 0) throw new RepositoryError('nothing_to_pay');
      if (input.reference.trim().length < 4) throw new RepositoryError('reference_required');
      const at = new Date(now).toISOString();
      for (const l of s.lines.filter((x) => x.kind === 'commission_payable')) {
        const c = byId(commissions, l.ref);
        if (c && c.status === 'approved') patchInPlace(commissions, c.id, { status: 'paid' as const, paidAt: at });
      }
      if (s.adjustment?.entryId) patchInPlace(commissions, s.adjustment.entryId, { status: 'paid' as const, paidAt: at });
      s.status = 'paid';
      s.paid = { at, byName: admin.name, reference: input.reference.trim(), amount: exTotal(s) };
      exEvent(exit, 'paid', admin.name, input.reference.trim());
      exMaybeComplete(exit, now);
      return exViewOf(partnerId, now);
    }),

  endPartnerAccess: (partnerId, userId) =>
    simulateWrite((): PartnerExitView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      const exit = exOpenExit(partnerId);
      if (exit.accessRevoked) throw new RepositoryError('access_ended');
      const v = exViewOf(partnerId, now);
      if (v.blockers.length > 0) throw new RepositoryError('gate_blocked');
      exEndAccess(exit, admin.name, false, now);
      exMaybeComplete(exit, now);
      return exViewOf(partnerId, now);
    }),

  recordExitInterview: (partnerId, input, userId) =>
    simulateWrite((): PartnerExitView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      const exit = exitLatest(partnerId);
      if (!exit || exit.status === 'cancelled') throw new RepositoryError('not_open');
      if (exit.interview) throw new RepositoryError('settlement_locked');
      if (input.how !== 'declined' && !input.reasons.every((r) => (EX_INTERVIEW_REASONS as readonly string[]).includes(r))) throw new RepositoryError('reason_required');
      if (input.how !== 'declined' && input.reasons.length === 0 && exLetters(input.notes) < EX_ACTION_NOTE_MIN) throw new RepositoryError('note_required');
      exit.interview = { at: new Date(now).toISOString(), byName: admin.name, how: input.how, reasons: input.how === 'declined' ? [] : input.reasons, wouldReturn: input.how === 'declined' ? null : input.wouldReturn, notes: input.notes.trim() };
      exEvent(exit, 'interview', admin.name, input.how);
      return exViewOf(partnerId, now);
    }),

  cancelPartnerExit: (partnerId, reason, userId) =>
    simulateWrite((): PartnerExitView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      const exit = exOpenExit(partnerId);
      if (exit.accessRevoked) throw new RepositoryError('access_ended');
      if (exLetters(reason) < EX_REASON_MIN) throw new RepositoryError('reason_required');
      exit.status = 'cancelled';
      exit.cancelled = { at: new Date(now).toISOString(), byName: admin.name, reason: reason.trim() };
      exEvent(exit, 'cancelled', admin.name, reason.trim());
      return exViewOf(partnerId, now);
    }),

  /* --------------------------------- Partner directory (149) */
  searchPartnerDirectory: (filter, userId) =>
    simulateRead((): PartnerDirectoryView => {
      ofAdmin(userId);
      const rows = pdRows(Date.now());
      const hit = pdFilter(rows, filter);
      const sorted = [...hit].sort((a, b) => (filter.sort === 'joined' ? (b.roles[0].joinedAt ?? '').localeCompare(a.roles[0].joinedAt ?? '') : a.name.localeCompare(b.name)));
      const offset = filter.offset ?? 0;
      const page = filter.limit === 0 ? sorted : sorted.slice(offset, offset + (filter.limit ?? 25));
      const count = (list: PartnerDirectoryRowView[], pick: (r: DirectoryRoleView) => string, key: string) => list.reduce((n, row) => n + (row.roles.some((r) => pick(r) === key) ? 1 : 0), 0);
      const forType = pdFilter(rows, filter, 'type');
      const forStatus = pdFilter(rows, filter, 'status');
      return {
        rows: page,
        total: hit.length,
        typeCounts: { all: forType.length, surveyor: count(forType, (r) => r.type, 'surveyor'), technician: count(forType, (r) => r.type, 'technician'), supplier: count(forType, (r) => r.type, 'supplier') },
        statusCounts: { all: forStatus.length, active: count(forStatus, (r) => r.status, 'active'), pending: count(forStatus, (r) => r.status, 'pending'), deactivated: count(forStatus, (r) => r.status, 'deactivated'), rejected: count(forStatus, (r) => r.status, 'rejected') },
        zones: zones.filter((z) => z.status === 'active').map((z) => ({ id: z.id, name: z.name })),
      };
    }),

  getPartnerDirectoryProfile: (key, userId) =>
    simulateRead((): PartnerDirectoryProfileView => {
      ofAdmin(userId);
      return pdProfile(key, Date.now());
    }),

  reassignPartnerTerritory: (partnerId, input, userId) =>
    simulateWrite((): PartnerDirectoryProfileView => {
      const admin = ofAdmin(userId);
      const u = byId(users, partnerId);
      if (!u) throw new RepositoryError('not_found');
      if (u.role !== 'surveyor') throw new RepositoryError('not_surveyor');
      if (u.status !== 'active') throw new RepositoryError('not_active');
      if (input.reason.replace(/[^\p{L}\p{N}]/gu, '').length < PD_REASON_MIN) throw new RepositoryError('reason_required');
      const active = zones.filter((z) => z.status === 'active');
      if (input.zoneIds.some((id) => !active.some((z) => z.id === id))) throw new RepositoryError('unknown_zone');
      const before = active.filter((z) => z.assignedUserIds.includes(partnerId)).map((z) => z.id);
      const next = [...new Set(input.zoneIds)];
      if (before.length === next.length && before.every((id) => next.includes(id))) throw new RepositoryError('no_change');
      for (const z of active) {
        const has = z.assignedUserIds.includes(partnerId);
        const want = next.includes(z.id);
        if (has && !want) patchInPlace(zones, z.id, { assignedUserIds: z.assignedUserIds.filter((x) => x !== partnerId) });
        if (!has && want) patchInPlace(zones, z.id, { assignedUserIds: [...z.assignedUserIds, partnerId] });
      }
      territoryChangeCounter += 1;
      partnerTerritoryChanges.push({ id: `ptc-${territoryChangeCounter}`, partnerId, from: before, to: next, reason: input.reason.trim(), byName: admin.name, at: new Date().toISOString(), isDemo: true });
      const phone = pdPhoneKey(u.phone);
      return pdProfile(phone ? `p:${phone}` : `r:${partnerId}`, Date.now());
    }),

  /* --------------------------------- Partner tier and category assignment (148) */
  getTierBoard: (userId) =>
    simulateRead((): PartnerTierBoardView => {
      ofAdmin(userId);
      const now = Date.now();
      tcEnsure(now);
      const ids = [...users.filter((u) => (u.role === 'surveyor' || u.role === 'technician') && u.status === 'active').map((u) => u.id), ...suppliers.filter((x) => x.status === 'active').map((x) => x.id)];
      const rows = ids.map((id) => tcRowOf(id, now));
      return { rows, counts: { total: rows.length, promotionDue: rows.filter((r) => r.promotionDue).length, incident: rows.filter((r) => r.incident).length, review: rows.filter((r) => r.reviewDue).length, dispute: rows.filter((r) => r.disputeOpen).length } };
    }),

  getPartnerTier: (partnerId, userId) =>
    simulateRead((): PartnerTierDetailView => {
      ofAdmin(userId);
      if (!tcPartnerRole(partnerId)) throw new RepositoryError('not_found');
      return tcDetailOf(partnerId, Date.now());
    }),

  assignPartnerTier: (partnerId, input, userId) =>
    simulateWrite((): PartnerTierDetailView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      tcEnsure(now);
      const review = tierReviews.find((r) => r.userId === partnerId && !r.resolved);
      tcAssign(partnerId, { ...input, ...(review ? { kind: 'review' as const } : {}) }, admin.name, now);
      if (review) review.resolved = { at: new Date(now).toISOString(), byName: admin.name, reason: input.reason.trim() };
      return tcDetailOf(partnerId, now);
    }),

  deferTierPromotion: (partnerId, input, userId) =>
    simulateWrite((): PartnerTierDetailView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      tcEnsure(now);
      const role = tcPartnerRole(partnerId);
      if (!role) throw new RepositoryError('not_found');
      if (input.reason.replace(/[^\p{L}\p{N}]/gu, '').length < TIER_REASON_MIN) throw new RepositoryError('reason_required');
      const row = tcRowOf(partnerId, now);
      if (!row.promotionDue && !row.deferred && !row.incident) throw new RepositoryError('not_open');
      if (!/^\d{4}-\d{2}-\d{2}$/.test(input.until) || input.until <= tcToday(now) || input.until > tcToday(now + TIER_DEFER_MAX_DAYS * 86_400_000)) throw new RepositoryError('defer_invalid');
      for (let i = tierDeferrals.length - 1; i >= 0; i -= 1) if (tierDeferrals[i].userId === partnerId) tierDeferrals.splice(i, 1);
      tierDeferrals.push({ userId: partnerId, until: input.until, reason: input.reason.trim(), byName: admin.name, at: new Date(now).toISOString() });
      return tcDetailOf(partnerId, now);
    }),

  reviewGrandfathered: (partnerId, reason, userId) =>
    simulateWrite((): PartnerTierDetailView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      tcEnsure(now);
      const review = tierReviews.find((r) => r.userId === partnerId && !r.resolved);
      if (!review) throw new RepositoryError('not_open');
      if (reason.replace(/[^\p{L}\p{N}]/gu, '').length < TIER_REASON_MIN) throw new RepositoryError('reason_required');
      review.resolved = { at: new Date(now).toISOString(), byName: admin.name, reason: reason.trim() };
      return tcDetailOf(partnerId, now);
    }),

  raiseTierDispute: (partnerId, grounds, userId) =>
    simulateWrite((): PartnerTierDetailView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      tcEnsure(now);
      const role = tcPartnerRole(partnerId);
      if (!role) throw new RepositoryError('not_found');
      if (grounds.replace(/[^\p{L}\p{N}]/gu, '').length < TIER_REASON_MIN) throw new RepositoryError('grounds_required');
      if (tierDisputes.some((d) => d.userId === partnerId && d.status === 'open')) throw new RepositoryError('dispute_open');
      const row = tcRowOf(partnerId, now);
      tierCounter += 1;
      tierDisputes.push({ id: `td-${tierCounter}`, userId: partnerId, grounds: grounds.trim(), raisedAt: new Date(now).toISOString(), raisedByName: admin.name, criteriaVersion: role === 'supplier' ? 1 : tcInForce(role, now).version, tierAtRaise: row.tier, status: 'open', isDemo: true });
      return tcDetailOf(partnerId, now);
    }),

  decideTierDispute: (disputeId, input, userId) =>
    simulateWrite((): PartnerTierDetailView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      tcEnsure(now);
      const d = byId(tierDisputes, disputeId);
      if (!d) throw new RepositoryError('not_found');
      if (d.status !== 'open') throw new RepositoryError('not_open');
      if (input.note.replace(/[^\p{L}\p{N}]/gu, '').length < TIER_REASON_MIN) throw new RepositoryError('reason_required');
      const at = new Date(now).toISOString();
      if (input.outcome === 'tier_changed') {
        if (!input.tier) throw new RepositoryError('tier_required');
        tcAssign(d.userId, { tier: input.tier, reason: input.note, effectiveFrom: input.effectiveFrom ?? tcToday(now), exception: true, incidentAcknowledged: true, kind: 'dispute' }, admin.name, now);
      }
      d.status = 'decided';
      d.decision = { outcome: input.outcome, note: input.note.trim(), byName: admin.name, at };
      return tcDetailOf(d.userId, now);
    }),

  getTierCriteria: (userId) =>
    simulateRead((): TierCriteriaView => {
      ofAdmin(userId);
      const now = Date.now();
      return {
        roles: (['surveyor', 'technician'] as const).map((role) => ({ role, current: tcInForce(role, now), versions: tierCriteria.filter((c) => c.role === role).sort((a, b) => b.version - a.version) })),
        supplier: { minOrders: GRADUATION_MIN_ORDERS, minScore: Math.round(GRADUATION_MIN_SCORE * 100) },
      };
    }),

  publishTierCriteria: (role, input, userId) =>
    simulateWrite((): TierCriteriaView => {
      const admin = ofAdmin(userId);
      const now = Date.now();
      tcEnsure(now);
      const problem = tierCriteriaProblem(role, input.tiers, tcToday(now), input.effectiveFrom, input.changeNote);
      if (problem) throw new RepositoryError(problem);
      const latest = Math.max(...tierCriteria.filter((c) => c.role === role).map((c) => c.version));
      const id = `tcv-${role}-${latest + 1}`;
      tierCriteria.push({ id, role, version: latest + 1, effectiveFrom: input.effectiveFrom, tiers: JSON.parse(JSON.stringify(input.tiers)) as TierCriteriaVersion['tiers'], changeNote: input.changeNote.trim(), createdByName: admin.name, createdAt: new Date(now).toISOString(), isDemo: true });
      // Raising the bar never reassesses anyone silently: whoever no longer meets the tier they hold is put up for a review by a date, and stays where they are meanwhile.
      const dueBy = tcToday(new Date(`${input.effectiveFrom}T00:00:00`).getTime() + TIER_REVIEW_WITHIN);
      for (const u of users.filter((x) => x.role === role && x.status === 'active')) {
        const cur = tcCurrentEntry(u.id, now).current?.tier ?? (role === 'technician' ? 'certified' : 'new');
        const idx = tierIndexOf(role, cur);
        const unmet = input.tiers.slice(1, idx + 1).flatMap((t) => tierEvaluate(t.criteria, tcMetrics(u.id, now))).some((r) => !r.ok);
        if (unmet && !tierReviews.some((r) => r.userId === u.id && !r.resolved)) tierReviews.push({ userId: u.id, versionId: id, dueBy });
      }
      return {
        roles: (['surveyor', 'technician'] as const).map((r) => ({ role: r, current: tcInForce(r, now), versions: tierCriteria.filter((c) => c.role === r).sort((a, b) => b.version - a.version) })),
        supplier: { minOrders: GRADUATION_MIN_ORDERS, minScore: Math.round(GRADUATION_MIN_SCORE * 100) },
      };
    }),

  /* --------------------------------- Recruitment: the public front door (141) */
  getRecruitmentLanding: () =>
    simulateRead((): RecruitmentLandingView => ({
      areas: zones.filter((z) => z.status === 'active').map((z) => z.name),
      demand: rcDemandOf(recruitmentLastDay(Date.now())),
    })),

  submitRecruitmentInterest: (input) =>
    simulateWrite((): RecruitmentInterestResult => {
      const phone = rcPhone(input.phone);
      const roles = [...new Set(input.roles)];
      const problem = rcInterestProblem({ name: input.name, phone, roles, consent: input.consent });
      if (problem) throw new RepositoryError(problem);
      const now = Date.now();
      const at = new Date(now).toISOString();
      const channel = (RECRUIT_CHANNELS as readonly string[]).includes(input.source.channel) ? input.source.channel : 'other';
      // Someone who already works with AIEC in that role is pointed to sign in, never recorded as a new applicant.
      const partnerRoles = new Set(users.filter((u) => u.phone === phone && u.status === 'active').map((u) => u.role as string));
      const asking = roles.filter((r) => r === 'undecided' || !partnerRoles.has(r));
      if (asking.length === 0) throw new RepositoryError('already_partner');
      const items: RecruitmentInterestResult['items'] = [];
      for (const role of asking) {
        const existing = recruitmentInterests.find((i) => i.phone === phone && i.role === role && i.status !== 'withdrawn');
        if (existing) {
          existing.touches.push({ at, channel, ...(input.source.campaign ? { campaign: input.source.campaign } : {}) });
          items.push({ id: existing.id, code: existing.code, role, created: false });
          continue;
        }
        recruitmentCounter += 1;
        const rec: RecruitmentInterest = {
          id: `ri-${recruitmentCounter}`,
          code: `AIEC-RI-${1000 + recruitmentCounter}`,
          name: input.name.trim(),
          phone,
          role,
          source: { channel, ...(input.source.campaign ? { campaign: input.source.campaign } : {}), ...(input.source.referrerCode ? { referrerCode: input.source.referrerCode } : {}) },
          interestedAt: at,
          language: input.language,
          contactConsent: true,
          ...(input.guided ? { guided: { answers: Object.fromEntries(Object.entries(input.guided.answers).filter(([, v]) => !!v)) as Record<string, string>, suggested: input.guided.suggested } } : {}),
          status: 'interested',
          touches: [],
          isDemo: true,
        };
        recruitmentInterests.push(rec);
        items.push({ id: rec.id, code: rec.code, role, created: true });
      }
      syncRecruitmentIntake(now);
      return { items, demand: rcDemandOf(recruitmentLastDay(now)) };
    }),

  markRecruitmentStarted: (interestId, phone) =>
    simulateWrite(() => {
      const i = byId(recruitmentInterests, interestId);
      if (!i || i.phone !== rcPhone(phone)) throw new RepositoryError('not_found');
      if (i.status === 'interested') patchInPlace(recruitmentInterests, i.id, { status: 'started' as const, startedAt: new Date().toISOString() });
    }),

  /* --------------------------------- Handover completion certificate (140) */
  getCompletionBoard: (userId) =>
    simulateRead((): CompletionBoardView => {
      const user = byId(users, userId);
      if (!user || (user.role !== 'admin' && user.role !== 'customer')) throw new RepositoryError('forbidden');
      const now = Date.now();
      const mine = jobs.filter((j) => (user.role === 'admin' || byId(deals, j.dealId)?.customerId === userId) && (j.status === 'handover_pending' || !!completionOf(j.id)));
      return {
        viewer: user.role === 'admin' ? 'admin' : 'customer',
        rows: mine
          .map((j) => {
            const v = completionViewOf(j, user.role as WrRole, now);
            return { jobId: j.id, code: j.code, siteName: j.siteName, status: v.status, certificateNo: v.certificateNo, issuedAt: v.issuedAt };
          })
          .filter((r) => user.role === 'admin' || r.status === 'issued' || handoverUnlocked(r.jobId))
          .sort((a, b) => (a.issuedAt ?? '9').localeCompare(b.issuedAt ?? '9')),
      };
    }),

  getCompletion: (jobId, userId) =>
    simulateRead((): CompletionView => {
      const { job, role } = completionActor(jobId, userId);
      return completionViewOf(job, role, Date.now());
    }),

  issueCompletionCertificate: (jobId, input, userId) =>
    simulateWrite((): CompletionView => {
      const { job, user, role } = completionActor(jobId, userId);
      if (role !== 'admin') throw new RepositoryError('not_admin');
      if (completionOf(job.id)) throw new RepositoryError('already_issued');
      if (job.status !== 'handover_pending') throw new RepositoryError('invalid_state');
      const now = Date.now();
      const walk = walkthroughOf(job.id);
      const readiness = coReadiness({ unlocked: handoverUnlocked(job.id), conducted: walk.conducted ? { at: walk.conducted.at } : null, mode: walk.mode, signedOff: !!walk.signoff, warrantyRegistered: !!registrationOf(job.id) }, now);
      const problem = coIssueProblem({ readiness, waiveReason: input.waiveSignoffReason });
      if (problem) throw new RepositoryError(problem);
      const at = new Date(now).toISOString();
      const deal = byId(deals, job.dealId) as Deal;
      const lead = resolveLead(deal.leadId);
      const plan = payoutPlanOf(job, now);
      const summary = completionSummaryOf(job, now);

      // Every payout, from this one event. An entry already on record for the deal is released, never duplicated.
      const lines: FinalPayoutLine[] = plan.lines.map((l) => {
        let entry = l.existingId ? byId(commissions, l.existingId) : undefined;
        if (!entry && l.role === 'surveyor' && lead) entry = byId(commissions, createOrReuseLeadConvertedCommission(deal, lead));
        if (!entry) {
          finalPayoutCounter += 1;
          entry = { id: `c-fin-${finalPayoutCounter}`, userId: l.userId, ...(lead ? { leadId: lead.id } : {}), dealId: deal.id, reasonKey: l.reasonKey, amount: l.amount, status: 'approved', earnedAt: at, isDemo: true };
          commissions.push(entry);
        }
        patchInPlace(commissions, entry.id, { jobId: job.id, payoutRole: l.role, ...(entry.status === 'projected' ? { status: 'approved' as const } : {}) });
        const { existingId: _existing, ...rest } = l;
        void _existing;
        return { ...rest, id: `fp-${entry.id}`, commissionId: entry.id, amount: entry.amount };
      });

      certificateCounter += 1;
      const rec: HandoverCompletion = {
        jobId: job.id,
        certificateNo: `AIEC-HC-${5000 + certificateCounter}`,
        issuedAt: at,
        issuedByName: user.name,
        ...(readiness.problems.length > 0 ? { signoffWaived: { reason: (input.waiveSignoffReason ?? '').trim() } } : {}),
        summary,
        team: plan.team,
        payout: { triggeredAt: at, lines, pools: plan.pools },
        judgements: [],
        isDemo: true,
      };
      handoverCompletions.push(rec);
      patchInPlace(jobs, job.id, { status: 'completed' as const, completedAt: at });
      if (lead) {
        pushTimelineEvent({ leadId: lead.id, kind: 'note_added', actorName: user.name, at, detail: `Handover certificate ${rec.certificateNo} issued; project complete and final payouts triggered` });
        messageLeadFromTemplate(lead, 'tpl-handover-certificate', { certificateNo: rec.certificateNo }, at);
      }
      return completionViewOf(byId(jobs, job.id) as Job, 'admin', now);
    }),

  recordPayoutJudgement: (jobId, input, userId) =>
    simulateWrite((): CompletionView => {
      const { job, user, role } = completionActor(jobId, userId);
      if (role !== 'admin') throw new RepositoryError('not_admin');
      const rec = completionOf(job.id);
      if (!rec) throw new RepositoryError('not_issued');
      const allowed = new Set(rec.payout.lines.map((l) => l.commissionId));
      const ids = input.decision === 'no_change' ? [] : [...new Set(input.commissionIds ?? [])].filter((id) => allowed.has(id));
      const entries = ids.map((id) => byId(commissions, id)).filter((e): e is CommissionEntry => !!e);
      const problem = fpJudgementProblem({
        decision: input.decision,
        issue: input.issue,
        reason: input.reason,
        targets: entries.map((e) => ({ status: e.status, held: !!e.heldBy, amount: e.amount, ...(input.amounts && input.amounts[e.id] !== undefined ? { newAmount: input.amounts[e.id] } : {}) })),
      });
      if (problem) throw new RepositoryError(problem);
      judgementCounter += 1;
      const at = new Date().toISOString();
      const id = `pj-${judgementCounter}`;
      const changes: PayoutJudgement['changes'] = entries.map((e) => {
        const before = { status: e.status, amount: e.amount };
        if (input.decision === 'hold') patchInPlace(commissions, e.id, { status: 'projected' as const, heldBy: id });
        else if (input.decision === 'release') patchInPlace(commissions, e.id, { status: 'approved' as const, heldBy: undefined });
        else patchInPlace(commissions, e.id, { amount: (input.amounts as Record<string, number>)[e.id] });
        const now = byId(commissions, e.id) as CommissionEntry;
        return { commissionId: e.id, userId: e.userId, name: nameOf(e.userId), before, after: { status: now.status, amount: now.amount } };
      });
      rec.judgements.unshift({ id, at, byName: user.name, issue: input.issue.trim(), decision: input.decision, reason: input.reason.trim(), changes });
      return completionViewOf(job, 'admin', Date.now());
    }),

  /* --------------------------------- Warranty & AMC registration (139) */
  getWarrantyBoard: (userId) =>
    simulateRead((): WarrantyBoardView => {
      const user = byId(users, userId);
      if (!user || (user.role !== 'admin' && user.role !== 'customer')) throw new RepositoryError('forbidden');
      const mine = jobs.filter((j) => (user.role === 'admin' || byId(deals, j.dealId)?.customerId === userId) && (j.status === 'handover_pending' || j.status === 'completed'));
      return {
        viewer: user.role === 'admin' ? 'admin' : 'customer',
        rows: mine
          .map((j) => ({ jobId: j.id, code: j.code, siteName: j.siteName, view: warrantyViewOf(j, user.role as WrRole, Date.now()) }))
          .filter((r) => r.view.status !== 'not_ready' || user.role === 'admin')
          .map((r) => ({ jobId: r.jobId, code: r.code, siteName: r.siteName, status: r.view.status, amcStatus: r.view.amc?.status ?? null })),
      };
    }),

  getWarranty: (jobId, userId) =>
    simulateRead((): WarrantyView => {
      const { job, role } = warrantyActor(jobId, userId);
      return warrantyViewOf(job, role, Date.now());
    }),

  registerWarrantyAndAmc: (jobId, input, userId) =>
    simulateWrite((): WarrantyView => {
      const { job, user, role } = warrantyActor(jobId, userId);
      if (registrationOf(job.id)) throw new RepositoryError('already_registered');
      const startsOn = handoverDayOf(job);
      const terms = startsOn ? warrantyTermsOf(job, startsOn) : null;
      if (!startsOn || !terms) throw new RepositoryError('not_ready');
      const extra = input.extraVisits ?? 0;
      const problem = wrAmcProblem({ choice: input.choice, ...(input.tier ? { tier: input.tier } : {}), extraVisits: extra, ...(input.note ? { note: input.note } : {}), isAdmin: role === 'admin', tierExists: !!input.tier && pricingConfig.amcTiers.some((t) => t.tier === input.tier) });
      if (problem) throw new RepositoryError(problem);
      const at = new Date().toISOString();
      const reg: WarrantyRegistration = { jobId: job.id, registeredAt: at, registeredByName: user.name, registeredByRole: role, startsOn, terms, reminders: [], isDemo: true };
      reg.amc = input.choice === 'enrol' ? buildAmc({ tier: input.tier as WrTierId, extraVisits: extra, ...(input.note ? { note: input.note } : {}) }, terms.service.endsOn, user.name, at) : { status: input.choice, extraVisits: 0, ...(input.note?.trim() ? { note: input.note.trim() } : {}), decidedAt: at, decidedByName: user.name, terms: [] };
      planReminders(reg);
      warrantyRegistrations.push(reg);
      return warrantyViewOf(job, role, Date.now());
    }),

  enrolAmc: (jobId, input, userId) =>
    simulateWrite((): WarrantyView => {
      const { job, user, role } = warrantyActor(jobId, userId);
      const reg = registrationOf(job.id);
      if (!reg) throw new RepositoryError('not_registered');
      if (reg.amc?.status === 'active') throw new RepositoryError('invalid_state');
      const extra = input.extraVisits ?? 0;
      const problem = wrAmcProblem({ choice: 'enrol', tier: input.tier, extraVisits: extra, ...(input.note ? { note: input.note } : {}), isAdmin: role === 'admin', tierExists: pricingConfig.amcTiers.some((t) => t.tier === input.tier) });
      if (problem) throw new RepositoryError(problem);
      const at = new Date().toISOString();
      reg.amc = buildAmc({ tier: input.tier, extraVisits: extra, ...(input.note ? { note: input.note } : {}) }, reg.terms.service.endsOn, user.name, at);
      // Whatever was waiting to raise AMC again is no longer needed.
      for (const r of reg.reminders) if (!r.sentAt && !r.skipped && r.kind !== 'amc_renewal') r.skipped = 'enrolled';
      planReminders(reg);
      return warrantyViewOf(job, role, Date.now());
    }),

  renewAmc: (jobId, userId) =>
    simulateWrite((): WarrantyView => {
      const { job, user, role } = warrantyActor(jobId, userId);
      const reg = registrationOf(job.id);
      if (!reg?.amc || reg.amc.status !== 'active' || !reg.amc.tier) throw new RepositoryError('not_registered');
      const last = reg.amc.terms[reg.amc.terms.length - 1];
      if (qcDay(Date.now()) < wrAddDays(last.endsOn, -WR_RENEW_DAYS[0])) throw new RepositoryError('too_early');
      const tier = pricingConfig.amcTiers.find((t) => t.tier === reg.amc!.tier);
      if (!tier) throw new RepositoryError('no_amc_tiers');
      const start = wrAddDays(last.endsOn, 1);
      const at = new Date().toISOString();
      reg.amc.terms.push({ n: last.n + 1, startsOn: start, endsOn: wrEndOfTerm(start, 12), price: wrAmcPrice(tier, reg.amc.tier, reg.amc.extraVisits), addedByName: user.name, at });
      // The reminders for the term that has just been renewed are finished with; the new term gets its own.
      for (const r of reg.reminders) if (!r.sentAt && !r.skipped && r.kind === 'amc_renewal') r.skipped = 'superseded';
      planReminders(reg);
      return warrantyViewOf(job, role, Date.now());
    }),

  /* --------------------------------- Customer handover walkthrough (138) */
  getWalkthroughBoard: (userId) =>
    simulateRead((): WalkthroughBoardView => {
      const user = byId(users, userId);
      if (!user) throw new RepositoryError('forbidden');
      const mine = jobs.filter((j) => {
        if (user.role === 'admin') return j.status === 'handover_pending' || j.status === 'completed' || j.status === 'qc_pending';
        if (user.role === 'customer') return byId(deals, j.dealId)?.customerId === userId && (j.status === 'handover_pending' || j.status === 'completed');
        return user.role === 'technician' && (isOnJob(j, userId) || qcOf(j.id)?.inspectorId === userId) && (j.status === 'handover_pending' || j.status === 'completed');
      });
      if (user.role !== 'admin' && user.role !== 'customer' && user.role !== 'technician') throw new RepositoryError('forbidden');
      return {
        viewer: user.role === 'admin' ? 'admin' : user.role === 'customer' ? 'customer' : 'conductor',
        rows: mine
          .map((j) => ({ j, w: walkthroughOf(j.id) }))
          .map(({ j, w }) => ({ jobId: j.id, code: j.code, siteName: j.siteName, status: walkthroughStatusOf(j, w), scheduledFor: w.scheduledFor ? { ...w.scheduledFor } : null, mode: w.mode ?? null }))
          .filter((r) => r.status !== 'locked' || user.role === 'admin'),
      };
    }),

  getWalkthrough: (jobId, userId) =>
    simulateRead((): WalkthroughView => {
      const { job, role } = walkthroughActor(jobId, userId);
      return walkthroughViewOf(job, role);
    }),

  arrangeWalkthrough: (jobId, input, userId) =>
    simulateWrite((): WalkthroughView => {
      const { job, user, role } = walkthroughActor(jobId, userId);
      const w = walkthroughOf(job.id);
      if (role === 'customer') throw new RepositoryError('forbidden');
      if (!handoverUnlocked(job.id)) throw new RepositoryError('not_unlocked');
      if (w.conducted) throw new RepositoryError('invalid_state');
      const conductor = walkthroughViewOf(job, role).conductors.find((c) => c.id === input.conductorId);
      const problem = wtArrangeProblem({ mode: input.mode, conductorId: conductor?.id, ...(input.representative ? { representative: input.representative } : {}) });
      if (problem) throw new RepositoryError(problem);
      if (input.date && (!/^\d{4}-\d{2}-\d{2}$/.test(input.date) || input.date < qcDay(Date.now()))) throw new RepositoryError('date_required');
      Object.assign(w, { mode: input.mode, conductorId: conductor!.id, conductorName: conductor!.name });
      if (input.date) w.scheduledFor = { date: input.date, window: input.window ?? 'morning' };
      else delete w.scheduledFor;
      if (input.mode === 'site_representative' && input.representative) w.representative = { name: input.representative.name.trim(), phone: input.representative.phone.trim(), relationship: input.representative.relationship.trim() };
      else delete w.representative;
      wtEvent(w, 'arranged', user.name, `${input.mode}${input.date ? ` ${input.date}` : ''}: ${conductor!.name}`);
      return walkthroughViewOf(job, role);
    }),

  tickWalkthroughItem: (jobId, itemId, done, userId) =>
    simulateWrite((): WalkthroughView => {
      const { job, user, role } = walkthroughActor(jobId, userId);
      const w = walkthroughOf(job.id);
      if (role === 'customer') throw new RepositoryError('forbidden');
      if (!handoverUnlocked(job.id)) throw new RepositoryError('not_unlocked');
      if (w.conducted || !w.mode) throw new RepositoryError('invalid_state');
      if (!wtScriptFor(!!sopSpecOf(job)?.powerBackup).some((i) => i.id === itemId)) throw new RepositoryError('not_found');
      if (done) w.script[itemId] = { at: new Date().toISOString(), byName: user.name };
      else delete w.script[itemId];
      return walkthroughViewOf(job, role);
    }),

  provideWalkthroughDocument: (jobId, kind, how, userId) =>
    simulateWrite((): WalkthroughView => {
      const { job, user, role } = walkthroughActor(jobId, userId);
      const w = walkthroughOf(job.id);
      if (role === 'customer') throw new RepositoryError('forbidden');
      if (!handoverUnlocked(job.id)) throw new RepositoryError('not_unlocked');
      if (w.conducted || !w.mode) throw new RepositoryError('invalid_state');
      const doc = walkthroughViewOf(job, role).documents.find((d) => d.kind === kind);
      if (!doc) throw new RepositoryError('not_found');
      if (!doc.ready) throw new RepositoryError('documents_open');
      w.documents[kind] = { at: new Date().toISOString(), how, byName: user.name };
      return walkthroughViewOf(job, role);
    }),

  completeWalkthrough: (jobId, userId) =>
    simulateWrite((): WalkthroughView => {
      const { job, user, role } = walkthroughActor(jobId, userId);
      const w = walkthroughOf(job.id);
      if (role === 'customer') throw new RepositoryError('forbidden');
      if (!handoverUnlocked(job.id)) throw new RepositoryError('not_unlocked');
      if (w.conducted) throw new RepositoryError('invalid_state');
      const view = walkthroughViewOf(job, role);
      if (view.conductProblem) throw new RepositoryError(view.conductProblem);
      w.conducted = { at: new Date().toISOString(), byName: user.name };
      wtEvent(w, 'conducted', user.name, w.mode);
      return walkthroughViewOf(job, role);
    }),

  signOffWalkthrough: (jobId, input, userId) =>
    simulateWrite((): WalkthroughView => {
      const { job, user, role } = walkthroughActor(jobId, userId);
      const w = walkthroughOf(job.id);
      if (!handoverUnlocked(job.id)) throw new RepositoryError('not_unlocked');
      const onDevice = role !== 'customer';
      if (onDevice && w.mode !== 'in_person') throw new RepositoryError('forbidden');
      const problem = wtSignoffProblem({ conducted: !!w.conducted, signed: !!w.signoff, understood: input.understood, onDevice, signature: input.signature ?? '', signer: input.signerName ?? '' });
      if (problem) throw new RepositoryError(problem);
      const at = new Date().toISOString();
      w.signoff = { at, signerName: onDevice ? (input.signerName as string).trim() : user.name, mode: onDevice ? 'on_device' : 'own_account', recordedByName: user.name, ...(onDevice && input.signature ? { signature: input.signature } : {}), ...(input.note?.trim() ? { note: input.note.trim() } : {}) };
      wtEvent(w, 'signed_off', user.name, onDevice ? 'on the conductor’s device' : 'in their own account');
      return walkthroughViewOf(job, role);
    }),

  recordWalkthroughAmc: (jobId, input, userId) =>
    simulateWrite((): WalkthroughView => {
      const { job, user, role } = walkthroughActor(jobId, userId);
      const w = walkthroughOf(job.id);
      if (!handoverUnlocked(job.id)) throw new RepositoryError('not_unlocked');
      if (!w.conducted) throw new RepositoryError('not_conducted');
      const problem = wtAmcProblem(input);
      if (problem) throw new RepositoryError(problem);
      if (input.tier && !pricingConfig.amcTiers.some((t) => t.tier === input.tier)) throw new RepositoryError('tier_required');
      w.amc = { choice: input.choice, ...(input.choice === 'enrol' && input.tier ? { tier: input.tier } : {}), at: new Date().toISOString(), byName: user.name, ...(input.note?.trim() ? { note: input.note.trim() } : {}) };
      wtEvent(w, 'amc', user.name, `${input.choice}${input.tier ? ` ${input.tier}` : ''}`);
      return walkthroughViewOf(job, role);
    }),

  submitWalkthroughFeedback: (jobId, input, userId) =>
    simulateWrite((): WalkthroughView => {
      const { job, user, role } = walkthroughActor(jobId, userId);
      const w = walkthroughOf(job.id);
      if (!w.signoff) throw new RepositoryError('not_conducted');
      if (role !== 'customer' && w.signoff.mode !== 'on_device') throw new RepositoryError('forbidden');
      if (w.feedback) throw new RepositoryError('invalid_state');
      const problem = wtScoreProblem(input.score);
      if (problem) throw new RepositoryError(problem);
      const at = new Date().toISOString();
      w.feedback = { score: input.score, ...(input.comment?.trim() ? { comment: input.comment.trim() } : {}), at, byName: user.name };
      wtEvent(w, 'feedback', user.name, String(input.score));
      // A low score on a lift that passed every check is a relationship signal worth understanding, beside the technical record.
      if (wtIsNegative(input.score)) raiseAlert({ titleKey: 'walkthrough.alert.negative', context: `${job.code} · ${job.siteName}: ${input.score}/5${w.feedback.comment ? ` · ${w.feedback.comment}` : ''}`, severity: 'medium', category: 'quality', relatedId: `wtfb:${job.id}`, sourceRoute: `/handover-walkthrough/${job.id}`, location: job.location });
      return walkthroughViewOf(job, role);
    }),

  addWalkthroughQuestion: (jobId, text, userId) =>
    simulateWrite((): WalkthroughView => {
      const { job, user, role } = walkthroughActor(jobId, userId);
      const w = walkthroughOf(job.id);
      if (!handoverUnlocked(job.id)) throw new RepositoryError('not_unlocked');
      const problem = wtQuestionProblem(text);
      if (problem) throw new RepositoryError(problem);
      walkthroughCounter += 1;
      w.followUps.push({ id: `wtq-${walkthroughCounter}`, text: text.trim(), at: new Date().toISOString(), byName: user.name });
      wtEvent(w, 'question', user.name, text);
      return walkthroughViewOf(job, role);
    }),

  answerWalkthroughQuestion: (jobId, questionId, text, adminId) =>
    simulateWrite((): WalkthroughView => {
      const admin = adminOnly(adminId);
      const job = byId(jobs, jobId);
      if (!job) throw new RepositoryError('not_found');
      const w = walkthroughOf(job.id);
      const q = w.followUps.find((f) => f.id === questionId);
      if (!q) throw new RepositoryError('not_found');
      if (q.answer) throw new RepositoryError('invalid_state');
      if (text.trim().length < 5) throw new RepositoryError('answer_required');
      q.answer = { text: text.trim(), at: new Date().toISOString(), byName: admin.name };
      wtEvent(w, 'answered', admin.name, text);
      return walkthroughViewOf(job, 'admin');
    }),

  /* --------------------------------- Final handover checklist (137) */
  getHandoverChecklist: (jobId, userId) =>
    simulateRead((): HandoverChecklistView => {
      const { job, viewer } = handoverActor(jobId, userId);
      return handoverViewOf(job, viewer);
    }),

  confirmHandoverDocument: (jobId, kind, userId) =>
    simulateWrite((): HandoverChecklistView => {
      const { job, user, viewer } = handoverActor(jobId, userId);
      if (job.status !== 'qc_pending' && job.status !== 'handover_pending') throw new RepositoryError('invalid_state');
      const g = handoverGateOf(job);
      const doc = g.docs.find((d) => d.kind === kind);
      if (!doc || !g.basis) throw new RepositoryError('not_found');
      if (doc.state === 'blocked') throw new RepositoryError('blocked_doc');
      if (doc.state === 'issue') throw new RepositoryError('invalid_state');
      g.rec.docs[kind] = { basis: { ...g.basis }, confirmedAt: new Date().toISOString(), confirmedByName: user.name };
      return handoverViewOf(job, viewer);
    }),

  flagHandoverDocIssue: (jobId, kind, text, userId) =>
    simulateWrite((): HandoverChecklistView => {
      const { job, user, viewer } = handoverActor(jobId, userId);
      const problem = hoIssueProblem(text);
      if (problem) throw new RepositoryError(problem);
      const rec = handoverRecordOf(job.id);
      snagCounter += 1;
      rec.issues.push({ id: `hdi-${snagCounter}`, kind, text: text.trim(), raisedByName: user.name, at: new Date().toISOString() });
      return handoverViewOf(job, viewer);
    }),

  resolveHandoverDocIssue: (jobId, issueId, resolution, userId) =>
    simulateWrite((): HandoverChecklistView => {
      const { job, user, viewer } = handoverActor(jobId, userId);
      const rec = handoverRecordOf(job.id);
      const issue = rec.issues.find((i) => i.id === issueId);
      if (!issue) throw new RepositoryError('not_found');
      if (issue.resolvedAt) throw new RepositoryError('invalid_state');
      const problem = hoIssueProblem(resolution);
      if (problem) throw new RepositoryError(problem);
      Object.assign(issue, { resolvedAt: new Date().toISOString(), resolvedByName: user.name, resolution: resolution.trim() });
      // A document that had a real problem is checked again: it is never ready just because the flag was cleared.
      delete rec.docs[issue.kind];
      return handoverViewOf(job, viewer);
    }),

  correctHandoverDocument: (jobId, kind, note, userId) =>
    simulateWrite((): HandoverChecklistView => {
      const { job, user, viewer } = handoverActor(jobId, userId);
      const g = handoverGateOf(job);
      const doc = g.docs.find((d) => d.kind === kind);
      if (!doc || !g.basis) throw new RepositoryError('not_found');
      const problem = hoCorrectionProblem({ note, state: doc.state });
      if (problem) throw new RepositoryError(problem);
      const at = new Date().toISOString();
      snagCounter += 1;
      g.rec.corrections.push({ id: `hdc-${snagCounter}`, kind, note: note.trim(), byName: user.name, at });
      g.rec.docs[kind] = { basis: { ...g.basis }, confirmedAt: at, confirmedByName: user.name };
      return handoverViewOf(job, viewer);
    }),

  requestHandoverAdminReview: (jobId, reason, adminId) =>
    simulateWrite((): HandoverChecklistView => {
      const { job, user, viewer } = handoverActor(jobId, adminId);
      if (viewer !== 'admin') throw new RepositoryError('forbidden');
      const rec = handoverRecordOf(job.id);
      if (rec.adminReview || rec.confirmations.length > 0 || job.status !== 'qc_pending') throw new RepositoryError('invalid_state');
      if (reason.trim().length < HO_REVIEW_REASON_MIN) throw new RepositoryError('review_reason_required');
      rec.adminReview = { reason: reason.trim(), addedByName: user.name, addedAt: new Date().toISOString() };
      return handoverViewOf(job, viewer);
    }),

  completeHandoverAdminReview: (jobId, note, adminId) =>
    simulateWrite((): HandoverChecklistView => {
      const { job, user, viewer } = handoverActor(jobId, adminId);
      if (viewer !== 'admin') throw new RepositoryError('forbidden');
      const rec = handoverRecordOf(job.id);
      if (!rec.adminReview) throw new RepositoryError('no_review');
      if (rec.adminReview.completedAt) throw new RepositoryError('invalid_state');
      if (note.trim().length < HO_REVIEW_NOTE_MIN) throw new RepositoryError('review_note_required');
      Object.assign(rec.adminReview, { completedAt: new Date().toISOString(), completedByName: user.name, note: note.trim() });
      return handoverViewOf(job, viewer);
    }),

  confirmReadyForHandover: (jobId, userId) =>
    simulateWrite((): HandoverChecklistView => {
      const { job, user, viewer, assignment } = handoverActor(jobId, userId);
      const g = handoverGateOf(job);
      if (g.legacy || g.status === 'confirmed') throw new RepositoryError('already_confirmed');
      if (g.problems.length > 0) throw new RepositoryError('not_ready');
      if (job.status !== 'qc_pending' && job.status !== 'handover_pending') throw new RepositoryError('invalid_state');
      const at = new Date().toISOString();
      g.rec.confirmations.push({ at, byUserId: user.id, byName: user.name });
      // This is what unlocks the walkthrough: the job moves to handover, and the quality check is over.
      patchInPlace(jobs, job.id, { status: 'handover_pending' as const });
      if (assignment && qcActive(assignment)) {
        assignment.status = 'completed';
        assignment.events.push(qcEvent('scheduled', user.name, 'Quality check complete: ready for handover'));
      }
      return handoverViewOf(byId(jobs, job.id) as Job, viewer);
    }),

  /* --------------------------------- Rework assignment (136) */
  getRework: (snagId, userId) =>
    simulateRead((): ReworkView => {
      const { r } = snagOf(snagId, userId, 'read');
      return reworkViewOf(r, userId, Date.now());
    }),

  assignRework: (snagId, technicianId, reason, adminId) =>
    simulateWrite((): ReworkView => {
      const { r, user } = snagOf(snagId, adminId, 'admin');
      if (r.status !== 'open' && r.status !== 'assigned' && r.status !== 'in_progress') throw new RepositoryError('invalid_state');
      const tech = byId(users, technicianId);
      if (!tech || tech.role !== 'technician' || tech.status !== 'active') throw new RepositoryError('not_technician');
      if (!trainingClear(tech.id)) throw new RepositoryError('training_incomplete');
      if (r.ownerId === tech.id) throw new RepositoryError('invalid_state');
      const problem = rwReassignProblem({ hasOwner: !!r.ownerId, reason });
      if (problem) throw new RepositoryError(problem);
      const now = Date.now();
      for (const m of reworkGroupOf(r)) {
        if (m.status !== 'open' && m.status !== 'assigned' && m.status !== 'in_progress') continue;
        const again = !!m.ownerId;
        // The person who had it stops: their open attempt is closed with the reason, and what they did stays on the record.
        for (const round of m.rework?.rounds ?? []) if (!round.completedAt) Object.assign(round, { completedAt: new Date(now).toISOString(), notes: round.notes ?? `Reassigned: ${reason.trim()}` });
        Object.assign(m, { ownerId: tech.id, ownerName: tech.name, assignedAt: new Date(now).toISOString(), dueAt: new Date(now + REWORK_DUE[m.severity]).toISOString(), status: 'assigned' as const });
        m.events.push(snagEvent(again ? 'reassigned' : 'assigned', user.name, reason.trim() ? `${tech.name}: ${reason.trim()}` : tech.name));
      }
      return reworkViewOf(r, adminId, now);
    }),

  startRework: (snagId, technicianId) =>
    simulateWrite((): ReworkView => {
      const { r, user } = reworkOwnerOf(snagId, technicianId);
      if (r.status !== 'assigned') throw new RepositoryError('invalid_state');
      const at = new Date().toISOString();
      const rw = reworkOf(r);
      rw.rounds.push({ n: rw.rounds.length + 1, startedAt: at, startedById: user.id, startedByName: user.name, evidence: [] });
      for (const m of reworkGroupOf(r)) if (m.ownerId === user.id && m.status === 'assigned') {
        m.status = 'in_progress';
        m.events.push(snagEvent('rework_started', user.name, undefined, at));
      }
      return reworkViewOf(r, technicianId, Date.now());
    }),

  completeRework: (snagId, input, technicianId) =>
    simulateWrite((): ReworkView => {
      const { r, user } = reworkOwnerOf(snagId, technicianId);
      const problem = rwCompleteProblem({ status: r.status, notes: input.notes, evidenceCount: input.evidence.length });
      if (problem) throw new RepositoryError(problem);
      if (input.evidence.length > 6) throw new RepositoryError('too_many_attachments');
      const round = reworkOf(r).rounds.find((x) => !x.completedAt);
      if (!round) throw new RepositoryError('invalid_state');
      const id = `${r.id}-rw${round.n}`;
      const evidence = input.evidence.map((m, n) => {
        const bad = evidenceProblem(m.kind, { kind: m.kind, mimeType: m.mimeType, sizeBytes: m.sizeBytes, durationS: m.durationS });
        if (bad) throw new RepositoryError(bad);
        return mediaToEvidence(m, `${id}-ev${n + 1}`, 'qc.rework', user);
      });
      const at = new Date().toISOString();
      Object.assign(round, { completedAt: at, notes: input.notes.trim(), evidence });
      // Done is never closed: it is handed to QC to re-check, for this snag and every snag that shares its cause.
      for (const m of reworkGroupOf(r)) if (m.ownerId === user.id && (m.status === 'in_progress' || m.status === 'assigned')) {
        Object.assign(m, { status: 'ready_for_retest' as const, fixedById: user.id, fixedAt: at });
        m.events.push(snagEvent('ready_for_retest', user.name, input.notes, at));
      }
      return reworkViewOf(r, technicianId, Date.now());
    }),

  handBackRework: (snagId, reason, technicianId) =>
    simulateWrite((): ReworkView => {
      const { r, user } = reworkOwnerOf(snagId, technicianId);
      if (r.status !== 'assigned' && r.status !== 'in_progress') throw new RepositoryError('invalid_state');
      const problem = rwHandBackProblem(reason);
      if (problem) throw new RepositoryError(problem);
      const at = new Date().toISOString();
      for (const round of r.rework?.rounds ?? []) if (!round.completedAt) Object.assign(round, { completedAt: at, notes: round.notes ?? `Handed back: ${reason.trim()}` });
      for (const m of reworkGroupOf(r)) if (m.ownerId === user.id) {
        m.status = 'open';
        delete m.ownerId;
        delete m.ownerName;
        delete m.assignedAt;
        delete m.dueAt;
        m.events.push(snagEvent('handed_back', user.name, reason, at));
      }
      return reworkViewOf(r, technicianId, Date.now());
    }),

  escalateRework: (snagId, input, userId) =>
    simulateWrite((): ReworkView => {
      const { r, user, role } = snagOf(snagId, userId, 'read');
      if (role !== 'owner' && role !== 'admin') throw new RepositoryError('not_owner');
      if (!sgIsOpen(r.status) || r.status === 'disputed' || r.status === 'ready_for_retest') throw new RepositoryError('invalid_state');
      const problem = rwEscalateProblem({ from: r.severity, to: input.severity, note: input.note });
      if (problem) throw new RepositoryError(problem);
      const now = Date.now();
      const from = r.severity;
      reworkOf(r).scope.push({ at: new Date(now).toISOString(), byName: user.name, note: input.note.trim(), from, to: input.severity });
      r.severity = input.severity;
      if (r.ownerId && r.dueAt) r.dueAt = new Date(Math.min(new Date(r.dueAt).getTime(), now + REWORK_DUE[input.severity])).toISOString();
      r.events.push(snagEvent('escalated', user.name, `${from} → ${input.severity}: ${input.note.trim()}`, new Date(now).toISOString()));
      const job = byId(jobs, r.jobId) as Job;
      // Reaching safety-critical has its own beacon (the list's); a wider scope at the same or a lower grade still tells Admin.
      if (input.severity !== 'safety_critical') raiseAlert({ titleKey: 'snagRework.alert.escalated', context: `${job.code} · ${job.siteName}: ${r.title ?? r.itemId}`, severity: 'high', category: 'quality', relatedId: `snagesc:${r.id}:${reworkOf(r).scope.length}`, sourceRoute: `/rework/${r.id}`, location: job.location });
      syncSnagAlerts(now);
      return reworkViewOf(r, userId, now);
    }),

  requestReworkPart: (snagId, input, technicianId) =>
    simulateWrite((): ReworkView => {
      const { r, user } = reworkOwnerOf(snagId, technicianId);
      if (r.status !== 'assigned' && r.status !== 'in_progress') throw new RepositoryError('invalid_state');
      const problem = rwPartProblem(input);
      if (problem) throw new RepositoryError(problem);
      const at = new Date().toISOString();
      snagCounter += 1;
      reworkOf(r).parts.push({ id: `rwp-${snagCounter}`, description: input.description.trim(), quantity: input.quantity, ...(input.note?.trim() ? { note: input.note.trim() } : {}), requestedByName: user.name, requestedAt: at });
      r.events.push(snagEvent('part_requested', user.name, `${input.quantity} × ${input.description.trim()}`, at));
      return reworkViewOf(r, technicianId, Date.now());
    }),

  listReworkPartOptions: (adminId) =>
    simulateRead((): ReworkPartOption[] => {
      adminOnly(adminId);
      return reworkPartOptions();
    }),

  orderReworkPart: (snagId, partId, input, adminId) =>
    simulateWrite((): ReworkView => {
      const { r, user, job } = snagOf(snagId, adminId, 'admin');
      const part = r.rework?.parts.find((p) => p.id === partId);
      if (!part) throw new RepositoryError('not_found');
      if (part.poId) throw new RepositoryError('already_ordered');
      const option = reworkPartOptions().find((o) => o.itemId === input.itemId);
      if (!option) throw new RepositoryError('supplier_unavailable');
      if (!Number.isInteger(input.quantity) || input.quantity < 1) throw new RepositoryError('quantity_required');
      const deal = byId(deals, job.dealId);
      if (!deal) throw new RepositoryError('not_found');
      const at = new Date().toISOString();
      supplierPurchaseOrderCounter += 1;
      poLineItemCounter += 1;
      const po: SupplierPurchaseOrder = {
        id: `spo-new-${supplierPurchaseOrderCounter}`,
        code: `AIEC-PO-${9000 + supplierPurchaseOrderCounter}`,
        dealId: deal.id,
        supplierId: option.supplierId,
        status: 'draft',
        triggeredAt: at,
        lineItems: [{ id: `poli-${poLineItemCounter}`, category: option.category, description: option.description, quantity: input.quantity, catalogUnitPriceAtDraft: option.unitPrice, agreedUnitPrice: option.unitPrice }],
        reworkSnagId: r.id,
        isDemo: true,
      };
      supplierPurchaseOrders.push(po);
      Object.assign(part, { poId: po.id, itemId: option.itemId, orderedByName: user.name, orderedAt: at });
      r.events.push(snagEvent('part_ordered', user.name, `${po.code}: ${option.description}`, at));
      return reworkViewOf(r, adminId, Date.now());
    }),

  /* --------------------------------- Defect / snag list (135) */
  getSnagBoard: (userId, jobId) =>
    simulateRead((): SnagBoardView => snagBoardOf(userId, jobId, Date.now())),

  getSnag: (snagId, userId) =>
    simulateRead((): SnagDetailView => {
      const { r } = snagOf(snagId, userId, 'read');
      return snagDetailOf(r, userId, Date.now());
    }),

  addSnag: (jobId, input, userId) =>
    simulateWrite((): SnagDetailView => {
      ensureSnagSeeds();
      const user = byId(users, userId);
      const job = byId(jobs, jobId);
      if (!user) throw new RepositoryError('forbidden');
      if (!job) throw new RepositoryError('not_found');
      const role = snagRoleOf(job, null, userId);
      if (role !== 'admin' && role !== 'inspector') throw new RepositoryError('forbidden');
      if (job.status !== 'qc_pending' && job.status !== 'handover_pending') throw new RepositoryError('not_ready');
      const problem = sgRaiseProblem({ title: input.title, note: input.note, severity: input.severity, evidenceCount: input.evidence.length });
      if (problem) throw new RepositoryError(problem);
      if (input.evidence.length > 6) throw new RepositoryError('too_many_attachments');
      snagCounter += 1;
      const id = `rw-${snagCounter}`;
      const evidence = input.evidence.map((m, n) => {
        const bad = evidenceProblem(m.kind, { kind: m.kind, mimeType: m.mimeType, sizeBytes: m.sizeBytes, durationS: m.durationS });
        if (bad) throw new RepositoryError(bad);
        return mediaToEvidence(m, `${id}-ev${n + 1}`, 'qc.snag', user);
      });
      const at = new Date().toISOString();
      const r: ReworkRequest = { id, code: `SNAG-${snagCounter}`, jobId: job.id, source: 'snag', itemId: 'manual', title: input.title.trim(), note: input.note.trim(), evidence, raisedByName: user.name, raisedAt: at, severity: input.severity, status: 'open', events: [snagEvent('raised', user.name, input.note, at)], isDemo: true };
      reworkRequests.push(r);
      syncSnagAlerts(Date.now());
      return snagDetailOf(r, userId, Date.now());
    }),

  assignSnags: (snagIds, technicianId, adminId) =>
    simulateWrite((): SnagBoardView => {
      const admin = adminOnly(adminId);
      ensureSnagSeeds();
      const tech = byId(users, technicianId);
      if (!tech || tech.role !== 'technician' || tech.status !== 'active') throw new RepositoryError('not_technician');
      const picked = snagIds.map((id) => byId(reworkRequests, id));
      if (picked.length === 0 || picked.some((r) => !r)) throw new RepositoryError('not_found');
      const list = picked as ReworkRequest[];
      if (list.some((r) => r.status !== 'open' && r.status !== 'assigned' && r.status !== 'in_progress')) throw new RepositoryError('invalid_state');
      const now = Date.now();
      for (const r of list) {
        const again = !!r.ownerId && r.ownerId !== tech.id;
        if (r.ownerId === tech.id) continue;
        Object.assign(r, { ownerId: tech.id, ownerName: tech.name, assignedAt: new Date(now).toISOString(), dueAt: new Date(now + REWORK_DUE[r.severity]).toISOString(), status: r.status === 'open' ? ('assigned' as const) : r.status });
        r.events.push(snagEvent(again ? 'reassigned' : 'assigned', admin.name, tech.name));
      }
      return snagBoardOf(adminId, undefined, now);
    }),

  regradeSnag: (snagId, severity, reason, adminId) =>
    simulateWrite((): SnagDetailView => {
      const { r, user } = snagOf(snagId, adminId, 'admin');
      if (!sgIsOpen(r.status) || r.severity === severity) throw new RepositoryError('invalid_state');
      const problem = sgRegradeProblem({ source: r.source, from: r.severity, to: severity, reason });
      if (problem) throw new RepositoryError(problem);
      const from = r.severity;
      r.severity = severity;
      if (r.ownerId && r.assignedAt) r.dueAt = new Date(new Date(r.assignedAt).getTime() + REWORK_DUE[severity]).toISOString();
      r.events.push(snagEvent('regraded', user.name, `${from} → ${severity}: ${reason.trim()}`));
      syncSnagAlerts(Date.now());
      return snagDetailOf(r, adminId, Date.now());
    }),

  linkSnags: (input, userId) =>
    simulateWrite((): SnagBoardView => {
      ensureSnagSeeds();
      const members = input.snagIds.map((id) => byId(reworkRequests, id));
      if (members.some((m) => !m)) throw new RepositoryError('not_found');
      const list = members as ReworkRequest[];
      const { user } = snagOf(list[0].id, userId, 'qc');
      const problem = sgLinkProblem({ members: list.map((m) => ({ id: m.id, jobId: m.jobId, source: m.source, status: m.status })), primaryId: input.primaryId, note: input.note });
      if (problem) throw new RepositoryError(problem);
      const groupId = `grp-${++snagCounter}`;
      for (const m of list) {
        Object.assign(m, { groupId, groupPrimaryId: input.primaryId, groupNote: input.note.trim() });
        m.events.push(snagEvent('linked', user.name, input.note));
      }
      return snagBoardOf(userId, list[0].jobId, Date.now());
    }),

  disputeSnag: (snagId, reason, userId) =>
    simulateWrite((): SnagDetailView => {
      const { r, user, role } = snagOf(snagId, userId, 'read');
      if (role !== 'owner' && role !== 'lead') throw new RepositoryError('not_owner');
      if (!sgIsOpen(r.status) || r.status === 'disputed') throw new RepositoryError('invalid_state');
      const problem = sgDisputeProblem(reason);
      if (problem) throw new RepositoryError(problem);
      r.dispute = { reason: reason.trim(), byName: user.name, at: new Date().toISOString(), fromStatus: r.status as 'open' | 'assigned' | 'in_progress' | 'ready_for_retest' };
      r.status = 'disputed';
      r.events.push(snagEvent('disputed', user.name, reason));
      return snagDetailOf(r, userId, Date.now());
    }),

  decideSnagDispute: (snagId, decision, note, adminId) =>
    simulateWrite((): SnagDetailView => {
      const { r, user } = snagOf(snagId, adminId, 'admin');
      if (r.status !== 'disputed' || !r.dispute) throw new RepositoryError('invalid_state');
      const problem = sgDecisionProblem({ kind: decision, note, source: r.source, severity: r.severity });
      if (problem) throw new RepositoryError(problem);
      const at = new Date().toISOString();
      r.dispute.decision = { kind: decision, note: note.trim(), byName: user.name, at };
      if (decision === 'finding_stands') r.status = r.dispute.fromStatus;
      else if (decision === 'retest_ordered') r.status = 'ready_for_retest';
      else {
        r.status = 'withdrawn';
        r.events.push(snagEvent('withdrawn', user.name, note, at));
      }
      r.events.push(snagEvent('dispute_decided', user.name, `${decision}: ${note.trim()}`, at));
      syncSnagAlerts(Date.now());
      return snagDetailOf(r, adminId, Date.now());
    }),

  waiveSnag: (snagId, input, userId) =>
    simulateWrite((): SnagDetailView => {
      const { r, user } = snagOf(snagId, userId, 'qc');
      if (!sgIsOpen(r.status) || r.status === 'disputed') throw new RepositoryError('invalid_state');
      const problem = sgWaiveProblem({ severity: r.severity, by: input.by, note: input.note });
      if (problem) throw new RepositoryError(problem);
      const at = new Date().toISOString();
      r.waiver = { by: input.by.trim(), note: input.note.trim(), recordedByName: user.name, at };
      r.status = 'waived';
      r.events.push(snagEvent('waived', user.name, `${input.by.trim()}: ${input.note.trim()}`, at));
      return snagDetailOf(r, userId, Date.now());
    }),

  verifySnag: (snagId, note, userId) =>
    simulateWrite((): SnagDetailView => {
      const { r, user } = snagOf(snagId, userId, 'qc');
      const problem = sgVerifyProblem({ source: r.source, status: r.status, verifierId: userId, fixedById: r.fixedById });
      if (problem) throw new RepositoryError(problem);
      const at = new Date().toISOString();
      const close = (x: ReworkRequest, via?: string) => {
        Object.assign(x, { status: 'verified' as const, verifiedAt: at, verifiedByName: user.name, ...(via ? { resolvedVia: via } : {}) });
        x.events.push(snagEvent('verified', user.name, via ? `Resolved with ${r.code}` : note, at));
      };
      close(r);
      // Fixing the root cause resolves every snag linked to it.
      if (r.groupId && r.groupPrimaryId === r.id) for (const m of reworkRequests) if (m.groupId === r.groupId && m.id !== r.id && sgIsOpen(m.status)) close(m, r.id);
      syncSnagAlerts(Date.now());
      return snagDetailOf(r, userId, Date.now());
    }),

  /* --------------------------------- Compliance certification (134) */
  getComplianceCertification: (jobId, userId) =>
    simulateRead((): ComplianceView => {
      const { job, viewer } = complianceActor(jobId, userId, false);
      return complianceViewOf(job, viewer);
    }),

  issueComplianceCertificate: (jobId, input, adminId) =>
    simulateWrite((): ComplianceView => {
      const { job, user } = complianceActor(jobId, adminId, true);
      ensureComplianceSeeds();
      if (currentCertOf(job.id)) throw new RepositoryError('already_issued');
      const spec = lockedSpecOf(byId(deals, job.dealId)?.leadId ?? '');
      if (!spec) throw new RepositoryError('no_spec');
      if (!certReadinessOf(job).ready) throw new RepositoryError('not_ready');
      const problem = certStandardsProblem(spec.driveType, input);
      if (problem) throw new RepositoryError(problem);
      const primary = certPrimaryOf(spec.driveType, input) as ComplianceCertificate['primary'];
      const state = jobStateOf(job);
      const g = guidanceOf(state);
      const at = new Date().toISOString();
      complianceCounter += 1;
      complianceCertificates.push({
        id: `cc-${complianceCounter}`,
        code: `CERT-${job.code}`,
        jobId: job.id,
        version: 1,
        driveType: spec.driveType,
        quotationCode: spec.quotationCode,
        primary: { ...primary },
        basis: primary.id === certStandardFor(spec.driveType) ? 'drive_type' : 'selected',
        ...(input.overrideReason?.trim() ? { overrideReason: input.overrideReason.trim() } : {}),
        additional: input.additional.map((a) => ({ ...a })),
        state,
        guidance: { state: g.state, fallback: g.fallback, authority: g.authority, steps: g.steps, note: g.note },
        package: certPackageOf(job, at),
        issuedAt: at,
        issuedByName: user.name,
        isDemo: true,
      });
      return complianceViewOf(job, 'admin');
    }),

  reissueComplianceCertificate: (jobId, input, adminId) =>
    simulateWrite((): ComplianceView => {
      const { job, user } = complianceActor(jobId, adminId, true);
      const current = currentCertOf(job.id);
      if (!current || current.historic) throw new RepositoryError('not_issued');
      const reasonProblem = certReissueProblem(input.reason);
      if (reasonProblem) throw new RepositoryError(reasonProblem);
      const problem = certStandardsProblem(current.driveType, input);
      if (problem) throw new RepositoryError(problem);
      const primary = certPrimaryOf(current.driveType, input) as ComplianceCertificate['primary'];
      const state = jobStateOf(job);
      const g = guidanceOf(state);
      const at = new Date().toISOString();
      complianceCounter += 1;
      const id = `cc-${complianceCounter}`;
      // The evidence package stays exactly as it was issued: a reissue corrects paperwork, it is never a fresh look at the lift.
      complianceCertificates.push({
        id,
        code: `CERT-${job.code}-R${current.version}`,
        jobId: job.id,
        version: current.version + 1,
        driveType: current.driveType,
        quotationCode: current.quotationCode,
        primary: { ...primary },
        basis: primary.id === certStandardFor(current.driveType) ? 'drive_type' : 'selected',
        ...(input.overrideReason?.trim() ? { overrideReason: input.overrideReason.trim() } : {}),
        additional: input.additional.map((a) => ({ ...a })),
        state,
        guidance: { state: g.state, fallback: g.fallback, authority: g.authority, steps: g.steps, note: g.note },
        package: current.package,
        issuedAt: at,
        issuedByName: user.name,
        supersedes: current.id,
        isDemo: true,
      });
      patchInPlace(complianceCertificates, current.id, { supersededBy: id, voidedAt: at, voidReason: input.reason.trim() });
      return complianceViewOf(job, 'admin');
    }),

  saveStateGuidance: (input, adminId) =>
    simulateWrite((): StateInspectionGuidance => {
      const admin = adminOnly(adminId);
      const steps = input.steps.map((x) => x.trim()).filter(Boolean);
      const problem = guidanceProblem({ state: input.state.trim() || null, authority: input.authority, steps });
      if (problem) throw new RepositoryError(problem);
      const at = new Date().toISOString();
      const existing = stateGuidance.find((x) => x.state === input.state.trim());
      const next: StateInspectionGuidance = { id: existing?.id ?? `sg-new-${stateGuidance.length + 1}`, state: input.state.trim(), authority: input.authority.trim(), steps, note: input.note.trim(), updatedByName: admin.name, updatedAt: at, isDemo: true };
      if (existing) patchInPlace(stateGuidance, existing.id, next);
      else stateGuidance.push(next);
      return { ...next, steps: [...next.steps] };
    }),

  /* --------------------------------- QC mechanical check (132) */
  getMechanicalCheck: (jobId, userId) =>
    simulateRead((): QcMechView => {
      const { job, viewer, assignment } = mechActor(jobId, userId);
      return mechViewOf(job, userId, viewer, assignment);
    }),

  recordMechanicalResult: (jobId, itemId, input, inspectorId) =>
    simulateWrite((): QcMechView => {
      const { job, user, viewer, assignment } = mechActor(jobId, inspectorId);
      if (viewer !== 'inspector' || !assignment || !qcActive(assignment)) throw new RepositoryError('not_inspector');
      if (job.status !== 'qc_pending') throw new RepositoryError('not_ready');
      const check = mechCheckOf(job.id);
      if (check.signedOff) throw new RepositoryError('invalid_state');
      const floors = mechFloorsOf(job);
      const reading = { measures: input.measures, floors: input.floors, ...(input.rubric ? { rubric: input.rubric } : {}) };
      const problem = mechAttemptProblem({ itemId, verdict: input.verdict, reading, floorCount: floors, note: input.note, evidenceCount: input.evidence.length, overrideReason: input.overrideReason });
      if (problem) throw new RepositoryError(problem);
      if (input.evidence.length > 6) throw new RepositoryError('too_many_attachments');
      const now = Date.now();
      const at = input.capturedAt ? new Date(input.capturedAt).getTime() : now;
      if (Number.isNaN(at)) throw new RepositoryError('captured_invalid');
      if (at > now + 60_000) throw new RepositoryError('captured_in_future');
      const list = check.attempts[itemId] ?? (check.attempts[itemId] = []);
      // A message sent twice (a phone that was offline) is one recording.
      const id = input.clientId ? `qma-${input.clientId}` : `qma-${++mechCounter}`;
      if (!list.some((a) => a.id === id)) {
        const suggested = mechSuggest(itemId, reading, floors);
        const evidence = input.evidence.map((m, n) => {
          const bad = evidenceProblem(m.kind, { kind: m.kind, mimeType: m.mimeType, sizeBytes: m.sizeBytes, durationS: m.durationS });
          if (bad) throw new RepositoryError(bad);
          return mediaToEvidence(m, `${id}-ev${n + 1}`, `qc.${itemId}`, user);
        });
        const attempt: QcMechAttempt = { id, n: list.length + 1, verdict: input.verdict, suggested, ...(input.overrideReason?.trim() ? { overrideReason: input.overrideReason.trim() } : {}), measures: input.measures.map((m) => ({ ...m })), floors: input.floors.map((f) => ({ ...f })), ...(input.rubric ? { rubric: input.rubric } : {}), ...(input.note?.trim() ? { note: input.note.trim() } : {}), evidence, at: new Date(at).toISOString(), byUserId: user.id, byName: user.name, ...(input.verdict === 'exception' ? { review: { status: 'pending' as const } } : {}) };
        list.push(attempt);
        // The first thing recorded is the inspection starting.
        if (assignment.status !== 'in_progress') {
          assignment.status = 'in_progress';
          assignment.events.push(qcEvent('scheduled', user.name, 'Inspection started'));
        }
        if (input.verdict === 'fail') {
          raiseChecklistSnag(job, 'qc_mechanical', itemId, attempt.note ?? '', evidence, user.name, attempt.at);
        } else if (input.verdict === 'pass') {
          // A recheck that passes is what closes the snag raised by the earlier fail.
          verifyChecklistSnags(job, 'qc_mechanical', itemId, user.name, attempt.at);
        }
        syncQcMechAlerts(now);
      }
      return mechViewOf(job, inspectorId, viewer, assignment);
    }),

  reviewMechanicalException: (jobId, itemId, decision, note, adminId) =>
    simulateWrite((): QcMechView => {
      adminOnly(adminId);
      const { job, user, viewer, assignment } = mechActor(jobId, adminId);
      const list = mechCheckOf(job.id).attempts[itemId] ?? [];
      const last = list[list.length - 1];
      if (!last || last.verdict !== 'exception' || last.review?.status !== 'pending') throw new RepositoryError('invalid_state');
      if (decision === 'reject' && note.trim().length < NOTE_MIN_MECH) throw new RepositoryError('note_required');
      last.review = { status: decision === 'accept' ? 'accepted' : 'rejected', byName: user.name, at: new Date().toISOString(), ...(note.trim() ? { note: note.trim() } : {}) };
      // Rejecting an exception makes it a fail, and a fail has to be put right.
      if (decision === 'reject') raiseChecklistSnag(job, 'qc_mechanical', itemId, note.trim(), last.evidence, user.name, last.review.at as string);
      syncQcMechAlerts(Date.now());
      return mechViewOf(job, adminId, viewer, assignment);
    }),

  raiseInstallDiscrepancy: (jobId, itemId, description, inspectorId) =>
    simulateWrite((): QcMechView => {
      const { job, user, viewer, assignment } = mechActor(jobId, inspectorId);
      if (viewer !== 'inspector') throw new RepositoryError('not_inspector');
      if (!MECH_ITEMS.includes(itemId)) throw new RepositoryError('unknown_item');
      if (description.trim().length < NOTE_MIN_MECH) throw new RepositoryError('note_required');
      if (mechCheckOf(job.id).signedOff) throw new RepositoryError('invalid_state');
      qcFindings.push({ id: `qcf-${++mechCounter}`, jobId: job.id, itemId, description: description.trim(), raisedByName: user.name, raisedAt: new Date().toISOString(), isDemo: true });
      return mechViewOf(job, inspectorId, viewer, assignment);
    }),

  explainDiscrepancy: (findingId, text, userId) =>
    simulateWrite((): QcMechView => {
      const f = qcFindings.find((x) => x.id === findingId);
      if (!f) throw new RepositoryError('not_found');
      const { job, user, viewer, assignment } = mechActor(f.jobId, userId);
      if (viewer === 'inspector') throw new RepositoryError('forbidden');
      if (f.acceptedAt) throw new RepositoryError('invalid_state');
      if (text.trim().length < NOTE_MIN_MECH) throw new RepositoryError('note_required');
      f.explanation = { text: text.trim(), byName: user.name, at: new Date().toISOString() };
      return mechViewOf(job, userId, viewer, assignment);
    }),

  acceptDiscrepancy: (findingId, userId) =>
    simulateWrite((): QcMechView => {
      const f = qcFindings.find((x) => x.id === findingId);
      if (!f) throw new RepositoryError('not_found');
      const { job, user, viewer, assignment } = mechActor(f.jobId, userId);
      if (viewer === 'lead') throw new RepositoryError('forbidden');
      if (!f.explanation || f.acceptedAt) throw new RepositoryError('invalid_state');
      f.acceptedAt = new Date().toISOString();
      f.acceptedByName = user.name;
      return mechViewOf(job, userId, viewer, assignment);
    }),

  signOffMechanical: (jobId, inspectorId) =>
    simulateWrite((): QcMechView => {
      const { job, user, viewer, assignment } = mechActor(jobId, inspectorId);
      if (viewer !== 'inspector') throw new RepositoryError('not_inspector');
      const check = mechCheckOf(job.id);
      if (check.signedOff) throw new RepositoryError('invalid_state');
      const view = mechViewOf(job, inspectorId, viewer, assignment);
      if (view.signOff.problem) throw new RepositoryError(view.signOff.problem);
      check.signedOff = { at: new Date().toISOString(), byUserId: user.id, byName: user.name };
      return mechViewOf(job, inspectorId, viewer, assignment);
    }),

  /* --------------------------------- QC inspector assignment (131) */
  getQcBoard: (userId) =>
    simulateRead((): QcBoardView => {
      ensureQcSeeds();
      const user = byId(users, userId);
      if (!user) throw new RepositoryError('forbidden');
      if (user.role !== 'admin' && user.role !== 'technician') throw new RepositoryError('forbidden');
      const isAdmin = user.role === 'admin';
      const now = Date.now();
      const candidates = jobs.filter((j) => {
        if (isAdmin) return j.status === 'qc_pending' || j.status === 'in_progress' || j.status === 'on_hold' || !!qcOf(j.id);
        const a = qcOf(j.id);
        return !!a && a.inspectorId === userId;
      });
      const rows = candidates
        .map((j): QcBoardRow => {
          const r = qcReadinessOf(j);
          const a = qcOf(j.id);
          const beyond = j.status === 'qc_pending' || j.status === 'handover_pending' || j.status === 'completed';
          return {
            jobId: j.id,
            code: j.code,
            siteName: j.siteName,
            jobStatus: j.status,
            ready: r.ready,
            readyAt: r.readyAt,
            waitingHours: r.ready && r.readyAt ? Math.max(0, Math.round((now - new Date(r.readyAt).getTime()) / 3_600_000)) : null,
            problems: [...(r.installationOpen > 0 ? (['installation_open'] as const) : []), ...(r.safetyOpen > 0 ? (['safety_open'] as const) : []), ...(r.awaitingLead ? (['awaiting_lead'] as const) : []), ...(r.onHold ? (['on_hold'] as const) : []), ...(!beyond && r.installationOpen === 0 && r.safetyOpen === 0 && !r.awaitingLead && !r.onHold ? (['not_finished'] as const) : [])],
            assignment: a ? { inspectorName: a.inspectorName, mode: a.mode, status: a.status, scheduledDate: a.scheduledDate ?? null, window: a.window ?? null, conflict: !!a.conflict && !a.conflict.clearedAt } : null,
            preference: !!j.qcPreference,
          };
        })
        .sort((a, b) => Number(b.ready && !b.assignment) - Number(a.ready && !a.assignment) || Number(b.ready) - Number(a.ready) || a.code.localeCompare(b.code));
      const weekAgo = qcDay(now - 7 * 86_400_000);
      const weekAhead = qcDay(now + 7 * 86_400_000);
      return {
        rows,
        inspectors: isAdmin
          ? users
              .filter((u) => u.role === 'technician' && u.status === 'active' && acceptsNewWork(u.id) && trainingClear(u.id) && missingQcSkills(u.skills).length === 0)
              .map((u) => ({ userId: u.id, name: u.name, eligibleInGeneral: true, qcThisWeek: qcAssignments.filter((a) => a.inspectorId === u.id && qcActive(a) && a.scheduledDate && a.scheduledDate >= weekAgo && a.scheduledDate <= weekAhead).length, unavailable: inspectorOff.filter((o) => o.userId === u.id && o.date >= qcDay(now)).map((o) => ({ ...o })) }))
          : [],
        totals: { ready: rows.filter((r) => r.ready).length, unassigned: rows.filter((r) => r.ready && !r.assignment).length, scheduled: rows.filter((r) => r.assignment?.status === 'scheduled').length, conflicts: rows.filter((r) => r.assignment?.conflict).length },
        viewer: isAdmin ? 'admin' : 'inspector',
      };
    }),

  getQcJob: (jobId, userId) =>
    simulateRead((): QcJobDetail => {
      const { job } = qcActor(jobId, userId);
      return qcJobDetailOf(job, userId, Date.now());
    }),

  assignQcInspector: (jobId, input, adminId) =>
    simulateWrite((): QcJobDetail => {
      adminOnly(adminId);
      const { job, user } = qcActor(jobId, adminId);
      qcRequireReady(job);
      const existing = qcOf(job.id);
      if (existing && qcActive(existing)) throw new RepositoryError('already_assigned');
      const person = byId(users, input.inspectorId);
      if (!person || person.role !== 'technician') throw new RepositoryError('unknown_inspector');
      if (!trainingClear(person.id)) throw new RepositoryError('training_incomplete');
      const { mode, gaps } = qcNamable(job, person, input.exceptionNote);
      const now = new Date().toISOString();
      qcCounter += 1;
      const a: QcAssignment = { id: `qca-${qcCounter}`, jobId: job.id, inspectorId: person.id, inspectorName: person.name, mode, ...(gaps.length ? { exceptionGaps: gaps } : {}), ...(mode === 'admin_exception' ? { exceptionNote: (input.exceptionNote ?? '').trim() } : {}), status: 'assigned', assignedAt: now, assignedByName: user.name, previous: [], events: [qcEvent(mode === 'admin_exception' ? 'exception_assigned' : 'assigned', user.name, mode === 'admin_exception' ? (input.exceptionNote ?? '').trim() : undefined)], isDemo: true };
      qcAssignments.push(a);
      notifyQcInspector(a, `${job.code} was assigned to ${person.name} for quality check`);
      return qcJobDetailOf(job, adminId, Date.now());
    }),

  assignAdminAsInspector: (jobId, reason, adminId) =>
    simulateWrite((): QcJobDetail => {
      adminOnly(adminId);
      const { job, user } = qcActor(jobId, adminId);
      qcRequireReady(job);
      const existing = qcOf(job.id);
      if (existing && qcActive(existing)) throw new RepositoryError('already_assigned');
      if (reason.trim().length < QC_EXCEPTION_NOTE_MIN) throw new RepositoryError('exception_note_required');
      const now = new Date().toISOString();
      qcCounter += 1;
      const a: QcAssignment = { id: `qca-${qcCounter}`, jobId: job.id, inspectorId: user.id, inspectorName: user.name, mode: 'admin_exception', exceptionGaps: ['admin_role'], exceptionNote: reason.trim(), status: 'assigned', assignedAt: now, assignedByName: user.name, previous: [], events: [qcEvent('exception_assigned', user.name, reason.trim())], isDemo: true };
      qcAssignments.push(a);
      logAutomatedAction({ sourceKey: 'qc.admin_exception', triggeringCondition: `No independent, qualified inspector was named for ${job.code}`, actionTaken: 'Recorded Admin as the quality-check inspector, as a documented exception', affectedRecordId: a.id, affectedRecordType: 'other', subjectLabel: job.code });
      return qcJobDetailOf(job, adminId, Date.now());
    }),

  reassignQcInspector: (jobId, input, adminId) =>
    simulateWrite((): QcJobDetail => {
      adminOnly(adminId);
      const { job, user } = qcActor(jobId, adminId);
      const a = qcOf(job.id);
      if (!a || (a.status !== 'assigned' && a.status !== 'scheduled')) throw new RepositoryError('invalid_state');
      qcRequireReady(job);
      if (input.reason.trim().length < QC_REASON_MIN) throw new RepositoryError('reason_required');
      if (input.inspectorId === a.inspectorId) throw new RepositoryError('same_inspector');
      const isSelf = input.inspectorId === adminId;
      const person = byId(users, input.inspectorId);
      if (!person || (person.role !== 'technician' && !isSelf)) throw new RepositoryError('unknown_inspector');
      let mode: QcAssignment['mode'] = 'inspector';
      let gaps: string[] = [];
      if (isSelf) {
        if ((input.exceptionNote ?? '').trim().length < QC_EXCEPTION_NOTE_MIN) throw new RepositoryError('exception_note_required');
        mode = 'admin_exception';
        gaps = ['admin_role'];
      } else ({ mode, gaps } = qcNamable(job, person as User, input.exceptionNote));
      const keepSlot = !!(a.scheduledDate && a.window) && busyBecause(inspectorBusyFacts(input.inspectorId, a.id), a.scheduledDate, a.window) === null;
      a.previous.push({ inspectorId: a.inspectorId, inspectorName: a.inspectorName, until: new Date().toISOString(), reason: input.reason.trim() });
      a.inspectorId = (person as User).id;
      a.inspectorName = (person as User).name;
      a.mode = mode;
      a.exceptionGaps = gaps.length ? gaps : undefined;
      a.exceptionNote = mode === 'admin_exception' ? (input.exceptionNote ?? '').trim() : undefined;
      delete a.conflict;
      a.assignedAt = new Date().toISOString();
      a.assignedByName = user.name;
      if (!keepSlot) {
        delete a.scheduledDate;
        delete a.window;
        delete a.customerAgreedAt;
        a.status = 'assigned';
      }
      a.events.push(qcEvent('reassigned', user.name, input.reason.trim()));
      if (mode === 'inspector') notifyQcInspector(a, `${job.code} was reassigned to ${a.inspectorName}`);
      syncQcAssignments(false, Date.now());
      return qcJobDetailOf(job, adminId, Date.now());
    }),

  recordQcPreference: (jobId, input, adminId) =>
    simulateWrite((): QcJobDetail => {
      adminOnly(adminId);
      const { job, user } = qcActor(jobId, adminId);
      const today = qcDay(Date.now());
      const dates = [...new Set(input.dates)].sort();
      if (dates.length === 0 || dates.length > 5) throw new RepositoryError('dates_invalid');
      for (const d of dates) if (!/^\d{4}-\d{2}-\d{2}$/.test(d) || d < today || !isWorkingDay(d)) throw new RepositoryError('dates_invalid');
      const pref: QcVisitPreference = { dates, window: input.window, ...(input.note?.trim() ? { note: input.note.trim() } : {}), recordedByName: user.name, at: new Date().toISOString() };
      const updated = patchInPlace(jobs, job.id, { qcPreference: pref });
      const a = qcOf(job.id);
      if (a) a.events.push(qcEvent('preference_recorded', user.name, dates.join(', ')));
      return qcJobDetailOf(updated, adminId, Date.now());
    }),

  scheduleQcVisit: (jobId, input, adminId) =>
    simulateWrite((): QcJobDetail => {
      adminOnly(adminId);
      const { job, user } = qcActor(jobId, adminId);
      const a = qcOf(job.id);
      if (!a || (a.status !== 'assigned' && a.status !== 'scheduled')) throw new RepositoryError('invalid_state');
      qcRequireReady(job);
      const isAdminInspector = a.inspectorId === adminId;
      const busy = isAdminInspector ? null : busyBecause(inspectorBusyFacts(a.inspectorId, a.id), input.date, input.window);
      const pref = job.qcPreference;
      const problem = schedulingProblem({ date: input.date, window: input.window, today: qcDay(Date.now()), now: Date.now(), busy, matchesPreference: matchesPreference(pref, input.date, input.window), customerAgreed: input.customerAgreed });
      if (problem) throw new RepositoryError(problem);
      const wasScheduled = a.status === 'scheduled';
      a.scheduledDate = input.date;
      a.window = input.window;
      a.status = 'scheduled';
      a.customerAgreedAt = new Date().toISOString();
      a.events.push(qcEvent(wasScheduled ? 'rescheduled' : 'scheduled', user.name, `${input.date} ${input.window}`));
      if (!isAdminInspector) notifyQcInspector(a, `The quality check of ${job.code} was ${wasScheduled ? 'moved to' : 'booked for'} ${input.date}`);
      return qcJobDetailOf(job, adminId, Date.now());
    }),

  reportQcConflict: (jobId, note, inspectorId) =>
    simulateWrite((): QcJobDetail => {
      const { job, user, isAdmin } = qcActor(jobId, inspectorId);
      if (isAdmin) throw new RepositoryError('forbidden');
      const a = qcOf(job.id);
      if (!a || !qcActive(a)) throw new RepositoryError('invalid_state');
      if (note.trim().length < QC_REASON_MIN) throw new RepositoryError('reason_required');
      if (a.conflict && !a.conflict.clearedAt) throw new RepositoryError('already_flagged');
      a.conflict = { kind: 'self_reported', involvement: involvementOf(user.id, user.name, involvementFactsOf(job)), note: note.trim(), flaggedAt: new Date().toISOString(), byName: user.name };
      a.events.push(qcEvent('conflict_flagged', user.name, note.trim()));
      syncQcAssignments(false, Date.now());
      return qcJobDetailOf(job, inspectorId, Date.now());
    }),

  clearQcConflict: (jobId, note, adminId) =>
    simulateWrite((): QcJobDetail => {
      adminOnly(adminId);
      const { job, user } = qcActor(jobId, adminId);
      const a = qcOf(job.id);
      if (!a || !a.conflict || a.conflict.clearedAt) throw new RepositoryError('invalid_state');
      if (note.trim().length < QC_EXCEPTION_NOTE_MIN) throw new RepositoryError('exception_note_required');
      a.conflict = { ...a.conflict, clearedAt: new Date().toISOString(), clearedNote: note.trim(), clearedByName: user.name };
      a.events.push(qcEvent('conflict_cleared', user.name, note.trim()));
      syncQcAssignments(false, Date.now());
      return qcJobDetailOf(job, adminId, Date.now());
    }),

  setInspectorUnavailable: (input, byId_) =>
    simulateWrite((): InspectorUnavailability[] => {
      ensureQcSeeds();
      const by = byId(users, byId_);
      if (!by) throw new RepositoryError('forbidden');
      const target = input.userId ?? byId_;
      if (by.role !== 'admin' && target !== byId_) throw new RepositoryError('forbidden');
      if (by.role !== 'admin' && by.role !== 'technician') throw new RepositoryError('forbidden');
      const who = byId(users, target);
      if (!who || who.role !== 'technician') throw new RepositoryError('unknown_inspector');
      if (!/^\d{4}-\d{2}-\d{2}$/.test(input.date) || input.date < qcDay(Date.now())) throw new RepositoryError('dates_invalid');
      if (input.reason.trim().length < 3) throw new RepositoryError('reason_required');
      if (inspectorOff.some((u) => u.userId === target && u.date === input.date && (u.window === 'all' || u.window === input.window))) throw new RepositoryError('already_set');
      qcCounter += 1;
      inspectorOff.push({ id: `iu-${qcCounter}`, userId: target, date: input.date, window: input.window, reason: input.reason.trim(), setByName: by.name, at: new Date().toISOString() });
      return inspectorOff.filter((u) => u.userId === target).map((u) => ({ ...u }));
    }),

  clearInspectorUnavailable: (id, byId_) =>
    simulateWrite((): InspectorUnavailability[] => {
      ensureQcSeeds();
      const by = byId(users, byId_);
      const entry = inspectorOff.find((u) => u.id === id);
      if (!by || !entry) throw new RepositoryError('not_found');
      if (by.role !== 'admin' && entry.userId !== byId_) throw new RepositoryError('forbidden');
      inspectorOff.splice(inspectorOff.indexOf(entry), 1);
      return inspectorOff.filter((u) => u.userId === entry.userId).map((u) => ({ ...u }));
    }),

  /* --------------------------------- Technician team coordination (130) */
  getJobTeam: (jobId, userId) =>
    simulateRead((): JobTeamView => {
      const { job } = teamActor(jobId, userId);
      return jobTeamViewOf(job, userId, Date.now());
    }),

  postTeamMessage: (jobId, input, userId) =>
    simulateWrite((): JobTeamView => {
      const { job, user } = teamActor(jobId, userId);
      const text = input.text.trim();
      if (!text) throw new RepositoryError('text_required');
      if (text.length > TEAM_TEXT_MAX) throw new RepositoryError('text_too_long');
      const now = Date.now();
      const at = input.capturedAt ? new Date(input.capturedAt).getTime() : now;
      if (Number.isNaN(at)) throw new RepositoryError('captured_invalid');
      if (at > now + 60_000) throw new RepositoryError('captured_in_future');
      const id = input.clientId ? `tm-${input.clientId}` : `tm-${++teamCounter}`;
      // A message written without signal is sent when there is some; sending it twice is harmless.
      if (!jobTeamMessages.some((m) => m.id === id)) jobTeamMessages.push({ id, jobId: job.id, authorId: user.id, authorName: user.name, text, createdAt: new Date(at).toISOString(), kind: 'message', readBy: [user.id], isDemo: true });
      return jobTeamViewOf(job, userId, now);
    }),

  markTeamMessagesRead: (jobId, userId) =>
    simulateWrite((): void => {
      const { job } = teamActor(jobId, userId);
      for (const m of jobTeamMessages) if (m.jobId === job.id && !m.readBy.includes(userId)) m.readBy.push(userId);
    }),

  addHandoffNote: (jobId, input, userId) =>
    simulateWrite((): JobTeamView => {
      const { job, user, isAdmin } = teamActor(jobId, userId);
      if (isAdmin) throw new RepositoryError('forbidden');
      const text = input.text.trim();
      if (text.length < HANDOFF_MIN) throw new RepositoryError('note_required');
      if (text.length > TEAM_TEXT_MAX) throw new RepositoryError('text_too_long');
      if (input.toUserId && (input.toUserId === userId || !isOnJob(job, input.toUserId))) throw new RepositoryError('unknown_member');
      if (job.status === 'completed') throw new RepositoryError('read_only');
      const now = Date.now();
      const at = input.capturedAt ? new Date(input.capturedAt).getTime() : now;
      if (Number.isNaN(at)) throw new RepositoryError('captured_invalid');
      if (at > now + 60_000) throw new RepositoryError('captured_in_future');
      const id = input.clientId ? `ho-${input.clientId}` : `ho-${++teamCounter}`;
      if (!jobHandoffs.some((h) => h.id === id)) {
        const own = ownStepIds(job, userId);
        const open = job.steps.filter((st) => st.status !== 'complete' && (own === null || own.includes(st.id))).map((st) => st.id);
        const to = input.toUserId ? byId(users, input.toUserId) : undefined;
        jobHandoffs.push({ id, jobId: job.id, fromUserId: user.id, fromName: user.name, ...(to ? { toUserId: to.id, toName: to.name } : {}), text, openStepIds: open, createdAt: new Date(at).toISOString(), acknowledgedBy: [], isDemo: true });
      }
      return jobTeamViewOf(job, userId, now);
    }),

  acknowledgeHandoff: (noteId, userId) =>
    simulateWrite((): JobTeamView => {
      const note = jobHandoffs.find((h) => h.id === noteId) ?? (ensureTeamSeeds(), jobHandoffs.find((h) => h.id === noteId));
      if (!note) throw new RepositoryError('not_found');
      const { job, user, isAdmin } = teamActor(note.jobId, userId);
      if (isAdmin) throw new RepositoryError('forbidden');
      if (note.fromUserId === userId || (note.toUserId && note.toUserId !== userId)) throw new RepositoryError('forbidden');
      if (!note.acknowledgedBy.some((a) => a.userId === userId)) note.acknowledgedBy.push({ userId, name: user.name, at: new Date().toISOString() });
      return jobTeamViewOf(job, userId, Date.now());
    }),

  assignTeamSteps: (jobId, memberId, input, byId_) =>
    simulateWrite((): JobTeamView => {
      const { job, user } = teamManager(jobId, byId_);
      if (job.status === 'completed') throw new RepositoryError('read_only');
      const crew = crewOf(job);
      const member = crew.find((c) => c.userId === memberId);
      if (!member) throw new RepositoryError('unknown_member');
      if (member.userId === job.technicianId) throw new RepositoryError('lead_owns_all');
      const known = new Set(job.steps.map((st) => st.id));
      if (input.stepIds.some((id) => !known.has(id))) throw new RepositoryError('unknown_step');
      // A step has one owner: giving it to this person takes it from whoever held it, and only unfinished steps are worth handing over.
      const openIds = new Set(input.stepIds.filter((id) => job.steps.find((st) => st.id === id)?.status !== 'complete'));
      const next = crew.map((c) => (c.userId === memberId ? { ...c, stepIds: [...new Set([...c.stepIds.filter((id) => job.steps.find((st) => st.id === id)?.status === 'complete' || openIds.has(id)), ...openIds])], ...(input.responsibility !== undefined ? { responsibility: input.responsibility.trim() || undefined } : {}) } : { ...c, stepIds: c.stepIds.filter((id) => !openIds.has(id)) }));
      // What was set aside for this person and is no longer ticked goes back to the lead.
      const kept = next.find((c) => c.userId === memberId) as JobCrewMember;
      kept.stepIds = kept.stepIds.filter((id) => openIds.has(id) || job.steps.find((st) => st.id === id)?.status === 'complete');
      logTeam(job, teamEvent('steps_assigned', user.name, byId(users, memberId)?.name, `${openIds.size}`), { crew: next });
      return jobTeamViewOf(byId(jobs, job.id) as Job, byId_, Date.now());
    }),

  delegateLead: (jobId, input, byId_) =>
    simulateWrite((): JobTeamView => {
      const { job, user, isAdmin } = teamActor(jobId, byId_);
      // Only the lead themself (or Admin) hands the authority over: someone holding it for a few days cannot pass it on.
      if (!isAdmin && job.technicianId !== byId_) throw new RepositoryError('not_lead');
      const to = crewOf(job).find((c) => c.userId === input.toUserId);
      if (!to || to.userId === job.technicianId) throw new RepositoryError('unknown_member');
      if (!tcCanLead(to.userId)) throw new RepositoryError('tier_cannot_lead');
      if (!trainingClear(to.userId)) throw new RepositoryError('training_incomplete');
      if (input.reason.trim().length < 8) throw new RepositoryError('reason_required');
      const okDay = (s: string) => /^\d{4}-\d{2}-\d{2}$/.test(s) && !Number.isNaN(new Date(`${s}T00:00:00`).getTime());
      if (!okDay(input.from) || !okDay(input.until) || input.until < input.from) throw new RepositoryError('dates_invalid');
      const todayKey = dayKey(Date.now());
      if (input.until < todayKey) throw new RepositoryError('dates_invalid');
      if ((new Date(`${input.until}T00:00:00`).getTime() - new Date(`${input.from}T00:00:00`).getTime()) / 86_400_000 > DELEGATION_MAX_DAYS) throw new RepositoryError('dates_too_long');
      const name = byId(users, to.userId)?.name ?? to.userId;
      const d: JobLeadDelegation = { toUserId: to.userId, toName: name, from: input.from, until: input.until, reason: input.reason.trim(), byName: user.name, at: new Date().toISOString() };
      logTeam(job, teamEvent('delegated', user.name, name, `${input.from} → ${input.until}`), { leadDelegation: d });
      return jobTeamViewOf(byId(jobs, job.id) as Job, byId_, Date.now());
    }),

  endLeadDelegation: (jobId, byId_) =>
    simulateWrite((): JobTeamView => {
      const { job, user, isAdmin } = teamActor(jobId, byId_);
      if (!isAdmin && job.technicianId !== byId_) throw new RepositoryError('not_lead');
      const d = job.leadDelegation;
      if (!d || d.revokedAt) throw new RepositoryError('invalid_state');
      logTeam(job, teamEvent('delegation_ended', user.name, d.toName), { leadDelegation: { ...d, revokedAt: new Date().toISOString() } });
      return jobTeamViewOf(byId(jobs, job.id) as Job, byId_, Date.now());
    }),

  addTeamMember: (jobId, technicianId, input, adminId) =>
    simulateWrite((): JobTeamView => {
      adminOnly(adminId);
      const { job, user } = teamActor(jobId, adminId);
      const tech = byId(users, technicianId);
      if (!tech || tech.role !== 'technician' || tech.status !== 'active' || !acceptsNewWork(tech.id)) throw new RepositoryError('unknown_member');
      if (!trainingClear(tech.id)) throw new RepositoryError('training_incomplete');
      if (isOnJob(job, technicianId)) throw new RepositoryError('already_on_job');
      if (job.status === 'completed') throw new RepositoryError('read_only');
      const known = new Set(job.steps.filter((st) => st.status !== 'complete').map((st) => st.id));
      const stepIds = input.stepIds.filter((id) => known.has(id));
      const crew = crewOf(job).map((c) => ({ ...c, stepIds: c.stepIds.filter((id) => !stepIds.includes(id)) }));
      crew.push({ userId: tech.id, role: 'assistant', stepIds, ...(input.responsibility?.trim() ? { responsibility: input.responsibility.trim() } : {}) });
      logTeam(job, teamEvent('added', user.name, tech.name), { crew });
      return jobTeamViewOf(byId(jobs, job.id) as Job, adminId, Date.now());
    }),

  reassignTeamMember: (jobId, memberId, input, adminId) =>
    simulateWrite((): JobTeamView => {
      adminOnly(adminId);
      const { job, user } = teamActor(jobId, adminId);
      if (input.reason.trim().length < 8) throw new RepositoryError('reason_required');
      const crew = crewOf(job);
      const member = crew.find((c) => c.userId === memberId);
      if (!member) throw new RepositoryError('unknown_member');
      const isLead = memberId === job.technicianId;
      if (isLead && !input.newLeadId) throw new RepositoryError('new_lead_required');
      if (isLead && (!input.newLeadId || input.newLeadId === memberId || !crew.some((c) => c.userId === input.newLeadId))) throw new RepositoryError('unknown_member');
      // Someone still checked in here cannot be taken off the job: their time on site has to be closed first.
      if (siteCheckIns.some((v) => v.jobId === job.id && v.userId === memberId && !v.checkOutAt)) throw new RepositoryError('still_checked_in');
      const newLead = isLead ? (input.newLeadId as string) : job.technicianId;
      const receiverId = input.handStepsTo && crew.some((c) => c.userId === input.handStepsTo) && input.handStepsTo !== memberId ? input.handStepsTo : newLead;
      const openOwned = member.stepIds.filter((id) => job.steps.find((st) => st.id === id)?.status !== 'complete');
      const next = crew
        .filter((c) => c.userId !== memberId)
        .map((c) => {
          if (c.userId === newLead) return { ...c, role: 'lead' as const, stepIds: [] };
          if (c.userId === receiverId) return { ...c, stepIds: [...new Set([...c.stepIds, ...openOwned])] };
          return c;
        });
      const name = byId(users, memberId)?.name ?? memberId;
      const d = job.leadDelegation && (job.leadDelegation.toUserId === memberId || isLead) && !job.leadDelegation.revokedAt ? { ...job.leadDelegation, revokedAt: new Date().toISOString() } : job.leadDelegation;
      // Their finished steps keep their name (completedByName): the partial progress stays theirs, and the rest of the team carries on.
      logTeam(job, teamEvent('reassigned', user.name, name, input.reason.trim()), { crew: next, technicianId: newLead, ...(d ? { leadDelegation: d } : {}) });
      if (isLead && newLead) logTeam(byId(jobs, job.id) as Job, teamEvent('lead_changed', user.name, byId(users, newLead)?.name, input.reason.trim()));
      return jobTeamViewOf(byId(jobs, job.id) as Job, adminId, Date.now());
    }),

  changeJobLead: (jobId, newLeadId, reason, adminId) =>
    simulateWrite((): JobTeamView => {
      adminOnly(adminId);
      const { job, user } = teamActor(jobId, adminId);
      if (reason.trim().length < 8) throw new RepositoryError('reason_required');
      const crew = crewOf(job);
      if (newLeadId === job.technicianId || !crew.some((c) => c.userId === newLeadId)) throw new RepositoryError('unknown_member');
      if (!tcCanLead(newLeadId)) throw new RepositoryError('tier_cannot_lead');
      if (!trainingClear(newLeadId)) throw new RepositoryError('training_incomplete');
      const next = crew.map((c) => (c.userId === newLeadId ? { ...c, role: 'lead' as const, stepIds: [] } : c.userId === job.technicianId ? { ...c, role: 'assistant' as const, stepIds: [] } : c));
      logTeam(job, teamEvent('lead_changed', user.name, byId(users, newLeadId)?.name, reason.trim()), { crew: next, technicianId: newLeadId });
      return jobTeamViewOf(byId(jobs, job.id) as Job, adminId, Date.now());
    }),

  flagTeamDisagreement: (jobId, note, userId) =>
    simulateWrite((): JobTeamView => {
      const { job, user, isAdmin } = teamActor(jobId, userId);
      if (isAdmin) throw new RepositoryError('forbidden');
      if (note.trim().length < HANDOFF_MIN) throw new RepositoryError('note_required');
      if (job.status === 'completed' || job.status === 'handover_pending') throw new RepositoryError('job_finished');
      if (jobIssues.some((i) => i.jobId === job.id && i.teamDisagreement && i.status === 'open')) throw new RepositoryError('already_open');
      issueCounter += 1;
      const id = `iss-new-${issueCounter}`;
      const createdAt = new Date().toISOString();
      const description = `Team disagreement: ${note.trim()}`;
      jobIssues.push({ id, code: `AIEC-ISS-${1000 + issueCounter}`, jobId: job.id, category: 'other', severity: 'minor', description, sopGap: false, teamDisagreement: true, evidence: [], status: 'open', groupId: id, reportedByUserId: user.id, reportedByName: user.name, createdAt, events: [issueEvent('reported', actorOf(user), description, { at: createdAt })], isDemo: true });
      jobTeamMessages.push({ id: `tm-${++teamCounter}`, jobId: job.id, authorId: user.id, authorName: user.name, text: note.trim(), createdAt, kind: 'disagreement', issueId: id, readBy: [user.id], isDemo: true });
      syncTeamAlerts(false, Date.now());
      return jobTeamViewOf(job, userId, Date.now());
    }),

  signOffForQuality: (jobId, userId) =>
    simulateWrite((): JobTeamView => {
      const { job, user, isAdmin } = teamActor(jobId, userId);
      if (isAdmin) throw new RepositoryError('forbidden');
      if (!leadIdsOf(job).includes(userId)) throw new RepositoryError('not_lead');
      if (job.status !== 'in_progress') throw new RepositoryError(job.status === 'on_hold' ? 'job_on_hold' : 'read_only');
      if (job.leadSignOff) throw new RepositoryError('invalid_state');
      const version = sopVersionOf(job);
      if (!qcReadiness(version.steps, job.steps, sopSpecOf(job)).ready) throw new RepositoryError('not_ready');
      const signed = logTeam(job, teamEvent('signed_off', user.name), { leadSignOff: { at: new Date().toISOString(), byUserId: user.id, byName: user.name } });
      sopFinishIfDone(signed, version);
      return jobTeamViewOf(byId(jobs, job.id) as Job, userId, Date.now());
    }),

  /* --------------------------------- Installation progress timeline (129) */
  getInstallationTimeline: (jobId, userId) =>
    simulateRead((): InstallTimelineView => {
      const { job, user, audience } = timelineActor(jobId, userId);
      return timelineViewOf(job, user, audience, Date.now());
    }),

  listInstallationTimelines: (userId) =>
    simulateRead((): TimelineListItem[] => {
      const user = byId(users, userId);
      if (!user) throw new RepositoryError('forbidden');
      const now = Date.now();
      const mine = jobs.filter((j) => (user.role === 'admin' ? true : user.role === 'technician' ? isOnJob(j, userId) : user.role === 'customer' ? byId(deals, j.dealId)?.customerId === userId : false));
      return mine
        .map((j): TimelineListItem => {
          const core = timelineCoreOf(j, now);
          const hiddenFromCustomer = user.role === 'customer' && !!j.customerTimelineHidden;
          return { jobId: j.id, code: j.code, siteName: j.siteName, status: j.status, percent: core.stepsTotal ? Math.round((core.stepsDone / core.stepsTotal) * 100) : 0, currentAt: hiddenFromCustomer ? null : new Date(core.estimate.currentAt).toISOString(), slipDays: core.estimate.slipDays, slipped: core.estimate.slipped, blocked: core.stoppedNow, current: core.current, hiddenFromCustomer };
        })
        .sort((a, b) => (a.status === 'completed' ? 1 : 0) - (b.status === 'completed' ? 1 : 0) || a.code.localeCompare(b.code));
    }),

  setTimelineCustomerVisible: (jobId, visible, note, adminId) =>
    simulateWrite((): InstallTimelineView => {
      adminOnly(adminId);
      const { job, user } = timelineActor(jobId, adminId);
      if (!visible && note.trim().length < 8) throw new RepositoryError('reason_required');
      const updated = patchInPlace(jobs, job.id, { customerTimelineHidden: visible ? undefined : { at: new Date().toISOString(), byName: user.name, ...(note.trim() ? { note: note.trim() } : {}) } });
      return timelineViewOf(updated, user, 'staff', Date.now());
    }),

  /* --------------------------------- As-installed material log (128) */
  getMaterialLog: (jobId, userId) =>
    simulateRead((): MaterialLogView => {
      const { job } = materialActor(jobId, userId);
      return materialLogViewOf(job, userId);
    }),

  saveMaterialLog: (jobId, input, technicianId) =>
    simulateWrite((): MaterialLogView => {
      const { job, user, role } = materialActor(jobId, technicianId);
      if (user.role === 'admin') throw new RepositoryError('forbidden');
      // Only the lead writes it: an assistant sees it, and answers for their own steps elsewhere.
      if (role !== 'lead') throw new RepositoryError('not_lead');
      if (!materialStarted(job)) throw new RepositoryError('not_started');
      const existing = materialLogs.find((l) => l.jobId === job.id);
      if (existing?.status === 'confirmed') throw new RepositoryError('invalid_state');
      const now = Date.now();
      const at = input.capturedAt ? new Date(input.capturedAt).getTime() : now;
      if (Number.isNaN(at)) throw new RepositoryError('captured_invalid');
      if (at > now + 60_000) throw new RepositoryError('captured_in_future');
      const plan = materialPlanOf(job, false);
      const seenLines = new Set<string>();
      const uses: JobMaterialUse[] = input.uses.map((raw) => {
        const line = raw.lineItemId ? plan.find((p) => p.id === raw.lineItemId) : undefined;
        if (raw.lineItemId && !line) throw new RepositoryError('unknown_line');
        if (raw.lineItemId) {
          if (seenLines.has(raw.lineItemId)) throw new RepositoryError('duplicate_line');
          seenLines.add(raw.lineItemId);
        }
        materialUseCounter += 1;
        const clean: JobMaterialUse = {
          id: raw.id && !raw.id.startsWith('mu-seed-') ? raw.id : `mu-${materialUseCounter}`,
          source: line ? 'delivered' : raw.source,
          ...(line ? { lineItemId: line.id, poCode: line.poCode, ...(line.supplierId ? { supplierId: line.supplierId } : {}) } : {}),
          // A planned row is the plan's own, never the phone's copy of it.
          category: line ? line.category : raw.category.trim(),
          description: line ? line.description : raw.description.trim(),
          plannedQty: line ? line.quantity : 0,
          usedQty: raw.usedQty,
          leftoverQty: raw.leftoverQty,
          ...(raw.leftoverQty > 0 && raw.leftoverAction ? { leftoverAction: raw.leftoverAction } : {}),
          ...(raw.deviation ? { deviation: { kind: raw.deviation.kind, reason: raw.deviation.reason.trim(), ...(raw.deviation.replacesLineItemId ? { replacesLineItemId: raw.deviation.replacesLineItemId } : {}) } } : {}),
          identifiers: raw.identifiers.map((i) => ({ legible: i.legible, ...(i.serial?.trim() ? { serial: i.serial.trim() } : {}), ...(i.batch?.trim() ? { batch: i.batch.trim() } : {}), ...(i.note?.trim() ? { note: i.note.trim() } : {}) })),
          ...(line && line.state !== 'on_site' ? { deliveryUnconfirmed: true } : {}),
          ...(raw.unitCost !== undefined && raw.unitCost >= 0 ? { unitCost: raw.unitCost } : {}),
        };
        return clean;
      });
      // A used row whose deviation is left over from an earlier edit (used in full) is not a deviation: drop it so the record stays honest.
      for (const u of uses) if (u.lineItemId && u.deviation && u.usedQty + u.leftoverQty === u.plannedQty && u.usedQty > 0 && u.leftoverQty === 0 && !u.deviation.reason.trim()) delete u.deviation;
      const problems = logProblems(uses, plan.map((p) => p.id), input.confirm);
      if (problems.length > 0) throw new RepositoryError(problems[0].problem);
      const savedAt = new Date(at).toISOString();
      if (existing) {
        existing.uses = uses;
        existing.savedAt = savedAt;
        existing.savedByName = user.name;
        if (input.confirm) {
          existing.status = 'confirmed';
          existing.confirmedAt = savedAt;
          existing.confirmedByName = user.name;
        }
      } else {
        materialLogs.push({ jobId: job.id, uses, status: input.confirm ? 'confirmed' : 'draft', savedAt, savedByName: user.name, ...(input.confirm ? { confirmedAt: savedAt, confirmedByName: user.name } : {}), reopened: [], isDemo: true });
      }
      if (input.confirm) syncMaterialDeviations(false, now);
      return materialLogViewOf(job, technicianId);
    }),

  reopenMaterialLog: (jobId, reason, adminId) =>
    simulateWrite((): MaterialLogView => {
      adminOnly(adminId);
      const { job, user } = materialActor(jobId, adminId);
      const log = materialLogs.find((l) => l.jobId === job.id);
      if (!log || log.status !== 'confirmed') throw new RepositoryError('invalid_state');
      if (reason.trim().length < REASON_MIN) throw new RepositoryError('reason_required');
      log.status = 'draft';
      delete log.confirmedAt;
      delete log.confirmedByName;
      log.reopened.push({ at: new Date().toISOString(), byName: user.name, reason: reason.trim() });
      syncMaterialDeviations(false, Date.now());
      return materialLogViewOf(job, adminId);
    }),

  getMaterialBoard: (adminId) =>
    simulateRead((): MaterialBoardView => {
      adminOnly(adminId);
      ensureMaterialSeeds();
      const now = Date.now();
      const rows = jobs
        .filter((j) => materialStarted(j) || materialLogs.some((l) => l.jobId === j.id))
        .map((j): MaterialBoardRow => {
          const log = materialLogs.find((l) => l.jobId === j.id);
          const uses = log?.uses ?? [];
          return { jobId: j.id, jobCode: j.code, siteName: j.siteName, status: j.status, logStatus: log ? log.status : 'none', deviations: uses.filter((u) => u.deviation).length, substitutions: uses.filter((u) => u.deviation?.kind === 'substitute').length, leftovers: uses.reduce((sum, u) => sum + u.leftoverQty, 0), savedAt: log?.savedAt ?? null };
        })
        .sort((a, b) => (a.logStatus === 'confirmed' ? 1 : 0) - (b.logStatus === 'confirmed' ? 1 : 0) || a.jobCode.localeCompare(b.jobCode));
      return {
        rows,
        patterns: materialPatternsOf(now),
        pool: materialPoolOf(null),
        totals: { jobs: rows.length, confirmed: rows.filter((r) => r.logStatus === 'confirmed').length, waiting: rows.filter((r) => r.logStatus !== 'confirmed').length, deviations: rows.reduce((sum, r) => sum + r.deviations, 0) },
      };
    }),

  getAsInstalledParts: (jobId, userId) =>
    simulateRead((): AsInstalledView => {
      const { job } = materialActor(jobId, userId);
      const log = materialLogs.find((l) => l.jobId === job.id);
      if (!log || log.status !== 'confirmed') return { jobId: job.id, confirmedAt: null, parts: [] };
      return {
        jobId: job.id,
        confirmedAt: log.confirmedAt ?? null,
        parts: log.uses
          .filter((u) => u.usedQty > 0)
          .map((u): AsInstalledPart => ({ category: u.category, description: u.description, quantity: u.usedQty, source: u.source, poCode: u.poCode ?? null, supplierId: u.supplierId ?? null, identifiers: u.identifiers.map((i) => ({ ...i })), substituted: u.deviation?.kind === 'substitute' })),
      };
    }),

  /* --------------------------------- Issue / blocker reports (127) */
  getJobIssues: (jobId, userId) =>
    simulateRead((): JobIssuesView => {
      const { job } = issueActor(jobId, userId, false);
      return jobIssuesViewOf(job, userId, Date.now());
    }),

  listIssueBoard: (adminId) =>
    simulateRead((): IssueBoardView => {
      adminOnly(adminId);
      const now = Date.now();
      const list = [...jobIssues].sort((a, b) => b.createdAt.localeCompare(a.createdAt));
      return {
        issues: list.map((i) => issueViewOf(i, adminId, now)),
        patterns: patternsOf(jobIssues, issuePatternReviews, now).map((p): IssuePatternView => ({ ...p, stepLabelKey: jobs.flatMap((j) => j.steps).find((st) => st.id === p.stepId)?.labelKey ?? null })),
        categories: categoryCounts(jobIssues, now),
        totals: { open: list.filter((i) => i.status === 'open').length, blocking: list.filter((i) => i.status === 'open' && i.severity === 'blocking').length, safety: list.filter((i) => i.status === 'open' && i.severity === 'safety').length, resolved: list.filter((i) => i.status === 'resolved').length },
      };
    }),

  reportJobIssue: (jobId, input, technicianId) =>
    simulateWrite((): JobIssuesView => {
      const { job, user } = issueActor(jobId, technicianId, true);
      if (user.role === 'admin') throw new RepositoryError('forbidden');
      if (job.status === 'completed' || job.status === 'handover_pending') throw new RepositoryError('job_finished');
      const problem = reportProblem({ category: input.category, severity: input.severity, description: input.description, attachments: input.evidence.length });
      if (problem) throw new RepositoryError(problem);
      if (input.stepId && !job.steps.some((x) => x.id === input.stepId)) throw new RepositoryError('unknown_step');
      const now = Date.now();
      const at = input.capturedAt ? new Date(input.capturedAt).getTime() : now;
      if (Number.isNaN(at)) throw new RepositoryError('captured_invalid');
      if (at > now + 60_000) throw new RepositoryError('captured_in_future');
      const linked = input.linkTo ? byId(jobIssues, input.linkTo) : undefined;
      if (input.linkTo && (!linked || linked.jobId !== job.id)) throw new RepositoryError('not_found');
      issueCounter += 1;
      const id = `iss-new-${issueCounter}`;
      const createdAt = new Date(at).toISOString();
      const evidence = input.evidence.map((m, n) => {
        const bad = evidenceProblem('photo' === m.kind ? 'photo' : 'video', { kind: m.kind, mimeType: m.mimeType, sizeBytes: m.sizeBytes, durationS: m.durationS });
        if (bad) throw new RepositoryError(bad);
        return { id: `${id}-ev${n + 1}`, slotId: 'issue', kind: m.kind, fileName: m.fileName, previewUrl: m.previewUrl, ...(m.mediaUrl ? { mediaUrl: m.mediaUrl } : {}), mimeType: m.mimeType, sizeBytes: m.sizeBytes, ...(m.durationS !== undefined ? { durationS: m.durationS } : {}), capturedAt: m.capturedAt, ...(m.location ? { location: m.location } : {}), byUserId: user.id, byName: user.name };
      });
      const created: JobIssue = {
        id,
        code: `AIEC-ISS-${1000 + issueCounter}`,
        jobId: job.id,
        category: input.category,
        severity: input.severity,
        description: input.description.trim(),
        ...(input.stepId ? { stepId: input.stepId } : {}),
        sopGap: !!input.sopGap && !!input.stepId,
        evidence,
        status: 'open',
        groupId: linked ? linked.groupId : id,
        reportedByUserId: user.id,
        reportedByName: user.name,
        createdAt,
        events: [issueEvent('reported', actorOf(user), input.description.trim(), { at: createdAt }), ...(linked ? [issueEvent('linked', actorOf(user), `Same problem as ${linked.code}`)] : [])],
        isDemo: true,
      };
      jobIssues.push(created);
      const after = syncIssueHold(job);
      if (after.status === 'on_hold' && after.heldBy === ISSUE_HOLD && job.status !== 'on_hold') created.events.push(issueEvent('paused', { id: 'system', name: 'AIEC', role: 'system' }, 'Work on this job is paused until this is resolved.'));
      syncIssueAlerts(false, now);
      return jobIssuesViewOf(byId(jobs, job.id) as Job, technicianId, now);
    }),

  addIssueNote: (issueId, note, userId) =>
    simulateWrite((): JobIssuesView => {
      const issue = issueOrThrow(issueId);
      const { job, user } = issueActor(issue.jobId, userId, true);
      if (note.trim().length < ISSUE_NOTE_MIN) throw new RepositoryError('note_required');
      patchInPlace(jobIssues, issue.id, { events: [...issue.events, issueEvent(user.role === 'admin' ? 'admin_note' : 'note', actorOf(user), note.trim())] });
      return jobIssuesViewOf(job, userId, Date.now());
    }),

  setIssueSeverity: (issueId, severity, note, userId) =>
    simulateWrite((): JobIssuesView => {
      const issue = issueOrThrow(issueId);
      const { job, user } = issueActor(issue.jobId, userId, true);
      if (issue.status !== 'open') throw new RepositoryError('invalid_state');
      if (note.trim().length < ISSUE_NOTE_MIN) throw new RepositoryError('note_required');
      if (severity === issue.severity) throw new RepositoryError('invalid_state');
      // A safety concern is never quietly downgraded, and a technician can only make a report more serious, never less.
      if (!severityAtLeast(severity, minSeverityFor(issue.category))) throw new RepositoryError('severity_too_low');
      if (user.role !== 'admin' && !severityAtLeast(severity, issue.severity)) throw new RepositoryError('forbidden');
      patchInPlace(jobIssues, issue.id, { severity, events: [...issue.events, issueEvent('severity', actorOf(user), note.trim(), { from: issue.severity, to: severity })] });
      syncIssueHold(job);
      syncIssueAlerts(false, Date.now());
      return jobIssuesViewOf(byId(jobs, job.id) as Job, userId, Date.now());
    }),

  addIssueEvidence: (issueId, media, userId) =>
    simulateWrite((): JobIssuesView => {
      const issue = issueOrThrow(issueId);
      const { job, user } = issueActor(issue.jobId, userId, true);
      if (issue.evidence.length >= 8) throw new RepositoryError('too_many_attachments');
      const bad = evidenceProblem(media.kind, { kind: media.kind, mimeType: media.mimeType, sizeBytes: media.sizeBytes, durationS: media.durationS });
      if (bad) throw new RepositoryError(bad);
      issueCounter += 1;
      const ev = { id: `${issue.id}-ev${issueCounter}`, slotId: 'issue', kind: media.kind, fileName: media.fileName, previewUrl: media.previewUrl, ...(media.mediaUrl ? { mediaUrl: media.mediaUrl } : {}), mimeType: media.mimeType, sizeBytes: media.sizeBytes, ...(media.durationS !== undefined ? { durationS: media.durationS } : {}), capturedAt: media.capturedAt, ...(media.location ? { location: media.location } : {}), byUserId: user.id, byName: user.name };
      patchInPlace(jobIssues, issue.id, { evidence: [...issue.evidence, ev], events: [...issue.events, issueEvent('evidence', actorOf(user))] });
      return jobIssuesViewOf(job, userId, Date.now());
    }),

  resolveJobIssue: (issueId, how, note, userId) =>
    simulateWrite((): JobIssuesView => {
      const issue = issueOrThrow(issueId);
      const { job, user } = issueActor(issue.jobId, userId, true);
      const role = user.role === 'admin' ? 'admin' : 'technician';
      if (issue.status !== 'open') throw new RepositoryError('invalid_state');
      if (!canResolve(issue, role, userId)) throw new RepositoryError(issue.severity === 'safety' ? 'safety_admin_only' : 'forbidden');
      if (note.trim().length < ISSUE_NOTE_MIN) throw new RepositoryError('note_required');
      const resolution = { how, note: note.trim(), byName: user.name, byRole: role as 'admin' | 'technician', at: new Date().toISOString() };
      patchInPlace(jobIssues, issue.id, { status: 'resolved' as const, resolution, events: [...issue.events, issueEvent('resolved', actorOf(user), note.trim())] });
      const before = byId(jobs, job.id) as Job;
      const after = syncIssueHold(before);
      if (before.status === 'on_hold' && after.status !== 'on_hold') {
        const closed = byId(jobIssues, issue.id) as JobIssue;
        closed.events.push(issueEvent('resumed', { id: 'system', name: 'AIEC', role: 'system' }, 'Work on this job can continue.'));
      }
      syncIssueAlerts(false, Date.now());
      return jobIssuesViewOf(byId(jobs, job.id) as Job, userId, Date.now());
    }),

  reopenJobIssue: (issueId, note, userId) =>
    simulateWrite((): JobIssuesView => {
      const issue = issueOrThrow(issueId);
      const { job, user } = issueActor(issue.jobId, userId, true);
      const role = user.role === 'admin' ? 'admin' : 'technician';
      if (!canReopen(issue, role, Date.now()) || (role !== 'admin' && issue.reportedByUserId !== userId)) throw new RepositoryError('invalid_state');
      if (note.trim().length < ISSUE_NOTE_MIN) throw new RepositoryError('note_required');
      patchInPlace(jobIssues, issue.id, { status: 'open' as const, resolution: undefined, events: [...issue.events, issueEvent('reopened', actorOf(user), note.trim())] });
      syncIssueHold(byId(jobs, job.id) as Job);
      syncIssueAlerts(false, Date.now());
      return jobIssuesViewOf(byId(jobs, job.id) as Job, userId, Date.now());
    }),

  linkJobIssues: (issueId, otherIssueId, userId) =>
    simulateWrite((): JobIssuesView => {
      const issue = issueOrThrow(issueId);
      const other = issueOrThrow(otherIssueId);
      const { job, user } = issueActor(issue.jobId, userId, true);
      if (other.jobId !== issue.jobId || other.id === issue.id) throw new RepositoryError('invalid_state');
      if (other.groupId === issue.groupId) throw new RepositoryError('invalid_state');
      // Two groups become one, named by the earlier report.
      const keep = issue.createdAt <= other.createdAt ? issue.groupId : other.groupId;
      const drop = keep === issue.groupId ? other.groupId : issue.groupId;
      for (const x of jobIssues.filter((i) => i.groupId === drop)) patchInPlace(jobIssues, x.id, { groupId: keep });
      patchInPlace(jobIssues, issue.id, { events: [...(byId(jobIssues, issue.id) as JobIssue).events, issueEvent('linked', actorOf(user), `Same problem as ${other.code}`)] });
      return jobIssuesViewOf(job, userId, Date.now());
    }),

  reviewIssuePattern: (stepId, outcome, note, adminId) =>
    simulateWrite((): IssueBoardView => {
      const admin = adminOnly(adminId);
      if (note.trim().length < ISSUE_NOTE_MIN) throw new RepositoryError('note_required');
      if (!patternsOf(jobIssues, issuePatternReviews, Date.now()).some((p) => p.stepId === stepId)) throw new RepositoryError('not_found');
      issuePatternReviews.push({ stepId, outcome, note: note.trim(), byName: admin.name, at: new Date().toISOString() });
      syncIssueAlerts(false, Date.now());
      const now = Date.now();
      const list = [...jobIssues].sort((a, b) => b.createdAt.localeCompare(a.createdAt));
      return {
        issues: list.map((i) => issueViewOf(i, adminId, now)),
        patterns: patternsOf(jobIssues, issuePatternReviews, now).map((p): IssuePatternView => ({ ...p, stepLabelKey: jobs.flatMap((j) => j.steps).find((st) => st.id === p.stepId)?.labelKey ?? null })),
        categories: categoryCounts(jobIssues, now),
        totals: { open: list.filter((i) => i.status === 'open').length, blocking: list.filter((i) => i.status === 'open' && i.severity === 'blocking').length, safety: list.filter((i) => i.status === 'open' && i.severity === 'safety').length, resolved: list.filter((i) => i.status === 'resolved').length },
      };
    }),

  /* --------------------------------- Safety compliance checklist (126) */
  getSafetyChecklist: (jobId, userId) =>
    simulateRead((): SafetyChecklistView => {
      const { job } = safetyActor(jobId, userId, 'read');
      return safetyViewOf(job, userId);
    }),

  recordSafetyResult: (jobId, itemId, input, technicianId) =>
    simulateWrite((): SafetyChecklistView => {
      const { job, user } = safetyActor(jobId, technicianId, 'technician');
      if (job.status !== 'in_progress') throw new RepositoryError(job.status === 'on_hold' ? 'job_on_hold' : job.status === 'scheduled' || job.status === 'materials_pending' ? 'not_started' : 'read_only');
      const entry = safetyEntryOrThrow(job, itemId);
      const view = safetyItemViewOf(job, entry, technicianId, safetyEntriesOf(job));
      if (!view.canRecord) throw new RepositoryError('not_yours');
      const t = safetyTestFor(job, itemId);
      const problem = resultProblem(t, input.result, { measured: input.measured, note: input.note }, { missingSlots: view.missingSlotIds, unmetDeps: view.waitingFor, requiresReading: view.requiresReading });
      if (problem) throw new RepositoryError(problem);
      const now = Date.now();
      const at = input.capturedAt ? new Date(input.capturedAt).getTime() : now;
      if (Number.isNaN(at)) throw new RepositoryError('captured_invalid');
      if (at > now + 60_000) throw new RepositoryError('captured_in_future');
      if (at < new Date(job.startedAt ?? job.scheduledFor).getTime()) throw new RepositoryError('captured_before_job');
      const attempt: SafetyAttempt = { id: `sat-new-${(safetyCounter += 1)}`, n: t.attempts.length + 1, result: input.result, at: new Date(at).toISOString(), byUserId: user.id, byName: user.name, ...(input.measured?.trim() ? { measured: input.measured.trim() } : {}), ...(input.note?.trim() ? { note: input.note.trim() } : {}) };
      const attempts = [...t.attempts, attempt];
      const holds = [...t.holds];
      // A check that has failed this many times is not one more fix away: Admin looks at it first.
      if (input.result === 'fail' && attempts.filter((a) => a.result === 'fail').length >= MAX_FAILS) holds.push({ reason: 'too_many_fails', at: attempt.at });
      patchInPlace(jobSafetyTests, t.id, { attempts, holds });
      syncSafetyAlerts(false, now);
      // Everything on the checklist done may be all a job was waiting for: it moves to quality check without anyone reopening it.
      sopFinishIfDone(byId(jobs, job.id) as Job, sopVersionOf(job));
      return safetyViewOf(byId(jobs, job.id) as Job, technicianId);
    }),

  recordSafetyFix: (jobId, itemId, kind, note, technicianId) =>
    simulateWrite((): SafetyChecklistView => {
      const { job, user } = safetyActor(jobId, technicianId, 'technician');
      if (job.status !== 'in_progress') throw new RepositoryError(job.status === 'on_hold' ? 'job_on_hold' : 'read_only');
      const entry = safetyEntryOrThrow(job, itemId);
      const view = safetyItemViewOf(job, entry, technicianId, safetyEntriesOf(job));
      if (!view.canRecord) throw new RepositoryError('not_yours');
      const t = safetyTestFor(job, itemId);
      const problem = fixProblem(t, note);
      if (problem) throw new RepositoryError(problem);
      const now = new Date().toISOString();
      const attempts = t.attempts.map((a, i) => (i === t.attempts.length - 1 ? { ...a, fix: { kind, note: note.trim(), at: now, byName: user.name } } : a));
      // A fundamental defect is not a fix-and-retest: it waits for Admin.
      const holds = kind === 'needs_rework' ? [...t.holds, { reason: 'needs_rework' as const, at: now }] : t.holds;
      patchInPlace(jobSafetyTests, t.id, { attempts, holds });
      syncSafetyAlerts(false, Date.now());
      return safetyViewOf(job, technicianId);
    }),

  raiseSafetyDisagreement: (jobId, itemId, note, technicianId) =>
    simulateWrite((): SafetyChecklistView => {
      const { job, user } = safetyActor(jobId, technicianId, 'technician');
      const entry = safetyEntryOrThrow(job, itemId);
      const view = safetyItemViewOf(job, entry, technicianId, safetyEntriesOf(job));
      if (!view.canRecord) throw new RepositoryError('not_yours');
      const t = safetyTestFor(job, itemId);
      const problem = disagreementProblem(t, note);
      if (problem) throw new RepositoryError(problem);
      patchInPlace(jobSafetyTests, t.id, { disagreement: { note: note.trim(), raisedByName: user.name, at: new Date().toISOString() } });
      syncSafetyAlerts(false, Date.now());
      return safetyViewOf(job, technicianId);
    }),

  resolveSafetyDisagreement: (jobId, itemId, decision, note, adminId) =>
    simulateWrite((): SafetyChecklistView => {
      const { job, user } = safetyActor(jobId, adminId, 'admin');
      const t = safetyTestOf(job.id, itemId);
      if (!t?.disagreement || t.disagreement.resolution) throw new RepositoryError('nothing_to_review');
      if (note.trim().length < RESOLUTION_NOTE_MIN) throw new RepositoryError('note_required');
      patchInPlace(jobSafetyTests, t.id, { disagreement: { ...t.disagreement, resolution: { decision, note: note.trim(), byName: user.name, at: new Date().toISOString() } } });
      syncSafetyAlerts(false, Date.now());
      return safetyViewOf(job, adminId);
    }),

  releaseSafetyHold: (jobId, itemId, note, adminId) =>
    simulateWrite((): SafetyChecklistView => {
      const { job, user } = safetyActor(jobId, adminId, 'admin');
      const t = safetyTestOf(job.id, itemId);
      const hold = t?.holds.find((h) => !h.releasedAt);
      if (!t || !hold) throw new RepositoryError('nothing_to_review');
      if (note.trim().length < RESOLUTION_NOTE_MIN) throw new RepositoryError('note_required');
      const now = new Date().toISOString();
      // Released means it may be tested again: for a fundamental fault, the rework is done. The failed attempt's fix is kept as it was written.
      const attempts = t.attempts.map((a, i) => (i === t.attempts.length - 1 && a.result === 'fail' && a.fix?.kind === 'needs_rework' ? { ...a, fix: { ...a.fix, kind: 'part_replaced' as SafetyFixKind, note: `${a.fix.note} — rework done: ${note.trim()}` } } : a));
      patchInPlace(jobSafetyTests, t.id, { attempts, holds: t.holds.map((h) => (h === hold ? { ...h, releasedAt: now, releasedByName: user.name, releaseNote: note.trim() } : h)) });
      syncSafetyAlerts(false, Date.now());
      return safetyViewOf(job, adminId);
    }),

  overrideSafetyItem: (jobId, itemId, engineerName, reason, adminId) =>
    simulateWrite((): SafetyChecklistView => {
      const { job, user } = safetyActor(jobId, adminId, 'admin');
      safetyEntryOrThrow(job, itemId);
      const t = safetyTestFor(job, itemId);
      const problem = overrideProblem(t, reason, engineerName);
      if (problem) throw new RepositoryError(problem);
      patchInPlace(jobSafetyTests, t.id, { override: { byUserId: user.id, byName: user.name, engineerName: engineerName.trim(), reason: reason.trim(), at: new Date().toISOString() }, holds: t.holds.map((h) => (h.releasedAt ? h : { ...h, releasedAt: new Date().toISOString(), releasedByName: user.name, releaseNote: 'Accepted by override.' })) });
      syncSafetyAlerts(false, Date.now());
      sopFinishIfDone(byId(jobs, job.id) as Job, sopVersionOf(job));
      return safetyViewOf(byId(jobs, job.id) as Job, adminId);
    }),

  listSafetyStateItems: (adminId) =>
    simulateRead((): SafetyStateItem[] => {
      adminOnly(adminId);
      return safetyStateItems.map((i) => ({ ...i }));
    }),

  addSafetyStateItem: (input, adminId) =>
    simulateWrite((): SafetyStateItem => {
      const admin = adminOnly(adminId);
      if (input.label.trim().length < 5 || input.method.trim().length < 15 || input.state.trim().length < 3) throw new RepositoryError('invalid_input');
      safetyCounter += 1;
      const created: SafetyStateItem = { id: `ssi-new-${safetyCounter}`, state: input.state.trim(), label: input.label.trim(), method: input.method.trim(), requiresReading: input.requiresReading, active: true, createdByName: admin.name, createdAt: new Date().toISOString(), isDemo: true };
      safetyStateItems.push(created);
      return { ...created };
    }),

  setSafetyStateItemActive: (id, active, adminId) =>
    simulateWrite((): SafetyStateItem => {
      adminOnly(adminId);
      const found = byId(safetyStateItems, id);
      if (!found) throw new RepositoryError('not_found');
      return { ...patchInPlace(safetyStateItems, id, { active }) };
    }),

  getPreInspectionSummary: (jobId, userId, summaryId) =>
    simulateRead((): PreInspectionSummaryView => {
      const { job } = safetyActor(jobId, userId, 'read');
      const stored = summaryId ? preInspectionSummaries.find((x) => x.id === summaryId && x.jobId === job.id) : undefined;
      if (summaryId && !stored) throw new RepositoryError('not_found');
      return preInspectionViewOf(job, stored);
    }),

  generatePreInspectionSummary: (jobId, userId) =>
    simulateWrite((): PreInspectionSummaryView => {
      const { job, user } = safetyActor(jobId, userId, 'read');
      const live = preInspectionViewOf(job);
      const version = preInspectionSummaries.filter((x) => x.jobId === job.id).length + 1;
      safetyCounter += 1;
      const created: PreInspectionSummary = { id: `pis-${safetyCounter}`, jobId: job.id, version, generatedAt: new Date().toISOString(), generatedByName: user.name, ready: live.ready, state: live.state, stateFallback: live.stateFallback, lines: live.lines.map((l) => ({ ...l })), isDemo: true };
      preInspectionSummaries.push(created);
      return preInspectionViewOf(job, created);
    }),

  /* --------------------------------- Site check-in / check-out (125) */
  getSiteTime: (jobId, userId) =>
    simulateRead((): SiteTimeView => {
      const { job } = siteActor(jobId, userId, false);
      return siteTimeViewOf(job, userId, Date.now());
    }),

  checkInToSite: (jobId, technicianId, input) =>
    simulateWrite((): SiteTimeView => {
      const { job, user } = siteActor(jobId, technicianId, true);
      const now = Date.now();
      const view = siteTimeViewOf(job, technicianId, now);
      if (view.problem) throw new RepositoryError(view.problem);
      const at = siteTimeOrThrow(input.capturedAt, now);
      // A visit made without signal keeps its own time, but it cannot overlap one the person already has.
      if (siteCheckIns.some((v) => v.userId === technicianId && (!v.checkOutAt || v.checkOutAt > at) && v.checkInAt <= at && v.jobId !== job.id)) throw new RepositoryError('captured_invalid');
      if (siteCheckIns.some((v) => v.userId === technicianId && v.jobId === job.id && v.checkOutAt && v.checkOutAt > at)) throw new RepositoryError('captured_invalid');
      const driftM = input.location ? Math.round(haversineKm(input.location, job.location) * 1000) : null;
      const read = readPresence({ driftM, accuracyM: input.accuracyM, radiusM: view.job.radiusM });
      const reason = (input.reason ?? '').trim();
      if ((read.verdict === 'mismatch' || read.verdict === 'unverified') && reason.length < OVERRIDE_REASON_MIN) throw new RepositoryError('reason_required');
      siteCheckInCounter += 1;
      const created: SiteCheckIn = {
        id: `sci-new-${siteCheckInCounter}`,
        jobId: job.id,
        userId: user.id,
        userName: user.name,
        checkInAt: at,
        checkInLocation: input.location,
        checkInAccuracyM: input.accuracyM,
        checkInDriftM: driftM,
        checkInVerdict: read.verdict,
        ...(reason ? { checkInReason: reason } : {}),
        isDemo: user.isDemo,
      };
      siteCheckIns.push(created);
      patchInPlace(users, user.id, { onDuty: true, lastSeenAt: at, ...(input.location ? { location: input.location } : {}) });
      // Borderline is recorded and left alone (no alert fatigue). A fix that cannot be explained, or none at all, is Admin's to know.
      if (read.verdict === 'mismatch' || read.verdict === 'unverified') {
        raiseAlert({
          titleKey: read.verdict === 'mismatch' ? 'siteCheckIn.alert.offSite' : 'siteCheckIn.alert.unverified',
          context: `${job.code} · ${job.siteName} · ${user.name}${driftM !== null ? ` · ${driftM} m` : ''}: ${reason}`,
          severity: read.verdict === 'mismatch' ? 'medium' : 'low',
          category: 'staffing',
          relatedId: `sitein:${created.id}`,
          sourceRoute: `/admin/tracking/technician/${user.id}`,
          ...(input.location ? { location: input.location } : {}),
        });
      }
      return siteTimeViewOf(job, technicianId, now);
    }),

  checkOutOfSite: (jobId, technicianId, input) =>
    simulateWrite((): SiteTimeView => {
      const { job, user } = siteActor(jobId, technicianId, true);
      const now = Date.now();
      const open = siteCheckIns.find((v) => v.userId === technicianId && v.jobId === job.id && !v.checkOutAt);
      if (!open) throw new RepositoryError('not_checked_in');
      // A visit left open over a day has no honest end: the person says when they really left (confirmLateCheckout).
      if (isStale(open, now)) throw new RepositoryError('stale_visit');
      const at = siteTimeOrThrow(input.capturedAt, now);
      if (new Date(at).getTime() < new Date(open.checkInAt).getTime()) throw new RepositoryError('captured_invalid');
      const openSteps = siteOpenStepsOf(job, technicianId);
      const note = (input.note ?? '').trim();
      if (openSteps.length > 0) {
        if (!input.leaveReason) throw new RepositoryError('leave_reason_required');
        if (input.leaveReason === 'other' && note.length < LEAVE_NOTE_MIN) throw new RepositoryError('reason_required');
      }
      patchInPlace(siteCheckIns, open.id, {
        checkOutAt: at,
        checkOutKind: 'manual',
        checkOutLocation: input.location ?? null,
        ...(input.leaveReason ? { leaveReason: input.leaveReason } : {}),
        ...(note ? { leaveNote: note } : {}),
        ...(openSteps.length > 0 ? { openStepIds: openSteps.map((st) => st.id) } : {}),
      });
      patchInPlace(users, user.id, { lastSeenAt: at, ...(input.location ? { location: input.location } : {}) });
      // Leaving with steps open is told to Admin, and how loudly depends on why and on whether a safety step was in hand.
      if (openSteps.length > 0 && input.leaveReason) {
        const safety = openSteps.some((st) => st.current && st.safetyCritical);
        const severity = leaveSeverity(input.leaveReason, safety);
        raiseAlert({
          titleKey: 'siteCheckIn.alert.checkoutIncomplete',
          context: `${job.code} · ${job.siteName} · ${user.name}: ${openSteps.length} steps open${note ? ` (${note})` : ''}`,
          severity,
          category: safety && (severity === 'high' || severity === 'critical') ? 'safety' : 'quality',
          relatedId: `siteout:${open.id}`,
          sourceRoute: `/admin/tracking/technician/${user.id}`,
        });
      }
      return siteTimeViewOf(job, technicianId, now);
    }),

  confirmLateCheckout: (visitId, technicianId, leftAt, note) =>
    simulateWrite((): SiteTimeView => {
      const v = byId(siteCheckIns, visitId);
      if (!v) throw new RepositoryError('not_found');
      if (v.userId !== technicianId) throw new RepositoryError('forbidden');
      const { job, user } = siteActor(v.jobId, technicianId, true);
      const now = Date.now();
      if (v.checkOutAt || !isStale(v, now)) throw new RepositoryError('invalid_state');
      const bad = leaveTimeProblem(v.checkInAt, leftAt, now);
      if (bad) throw new RepositoryError(`leave_${bad}`);
      patchInPlace(siteCheckIns, v.id, { checkOutAt: new Date(leftAt).toISOString(), checkOutKind: 'confirmed_late', closedAt: new Date(now).toISOString(), ...((note ?? '').trim() ? { leaveNote: (note as string).trim() } : {}) });
      patchInPlace(users, user.id, { lastSeenAt: new Date(now).toISOString() });
      return siteTimeViewOf(job, technicianId, now);
    }),

  pingSiteLocation: (technicianId, point, at) =>
    simulateWrite((): void => {
      const now = Date.now();
      const open = siteCheckIns.find((v) => v.userId === technicianId && !v.checkOutAt && !isStale(v, now));
      if (!open || !byId(users, technicianId)) return;
      patchInPlace(users, technicianId, { location: point, lastSeenAt: siteTimeOrThrow(at, now) });
    }),

  /* --------------------------------- Auto-reconciliation (120) */
  getReconciliationBoard: (byUserId) =>
    simulateRead((): ReconBoard => {
      adminOnly(byUserId);
      const now = Date.now();
      syncReconciliation(now);
      const ledger = new Map(ledgerEntriesOf().map((l) => [l.id, l]));
      const views = reconExceptions.map((e) => reconExceptionView(e, now, ledger));
      const open = views.filter((v) => v.status === 'open').sort((a, b) => SEVERITY_RANK[a.severity] - SEVERITY_RANK[b.severity] || b.ageDays - a.ageDays);
      const explained = views
        .filter((v) => v.status !== 'open')
        .sort((a, b) => (b.reconciled?.at ?? b.clearedAt ?? '').localeCompare(a.reconciled?.at ?? a.clearedAt ?? ''))
        .slice(0, 20);
      const pending = currentReconciliation(now).outcome.pending.map((id) => ledger.get(id)).filter((x): x is LedgerSideView => !!x);
      const latest = reconRuns[reconRuns.length - 1];
      return {
        feed: { ...bankFeed },
        latest: latest ? reconRunRow(latest) : null,
        runs: [...reconRuns].reverse().slice(0, 40).map(reconRunRow),
        open,
        explained,
        pending,
        nextRunAt: new Date(nextSlot(now)).toISOString(),
        totals: {
          // A run that could not run compared nothing: the last real comparison is the figure worth showing.
          matched: [...reconRuns].reverse().find((r) => r.status !== 'could_not_run')?.matchedCount ?? 0,
          open: open.length,
          serious: open.filter((v) => v.severity === 'critical').length,
          explained: reconExceptions.filter((e) => e.status === 'reconciled').length,
          pending: pending.length,
          openIn: open.filter((v) => v.direction === 'in').reduce((n, v) => n + v.amount, 0),
          openOut: open.filter((v) => v.direction === 'out').reduce((n, v) => n + v.amount, 0),
        },
      };
    }),

  getReconciliationRun: (runId, byUserId) =>
    simulateRead((): ReconRunDetail => {
      adminOnly(byUserId);
      const run = byId(reconRuns, runId);
      if (!run) throw new RepositoryError('not_found');
      const now = Date.now();
      const ledger = new Map(ledgerEntriesOf().map((l) => [l.id, l]));
      return {
        ...reconRunRow(run),
        windowFrom: run.windowFrom,
        windowTo: run.windowTo,
        matchedAmount: run.matchedAmount,
        matched: run.matched.flatMap((m) => {
          const b = byId(bankTransactions, m.bankId);
          const l = ledger.get(m.ledgerId);
          return b && l ? [{ bank: bankSideOf(b), ledger: l, difference: m.difference }] : [];
        }),
        unmatched: run.unmatched.flatMap((u) => {
          const e = byId(reconExceptions, u.exceptionId);
          return e ? [reconExceptionView(e, now, ledger)] : [];
        }),
      };
    }),

  runReconciliation: (byUserId) =>
    simulateWrite((): ReconRunRow => {
      const actor = adminOnly(byUserId);
      const now = Date.now();
      ensureReconSeeded(now);
      const up = bankFeed.status === 'connected';
      const run = runReconciliationAt(now, 'manual', actor.name, { up, reason: bankFeed.reason });
      if (up) bankFeed = { ...bankFeed, lastStatementAt: new Date(now).toISOString() };
      syncReconciliationAlerts(now);
      syncCommitments(now);
      return reconRunRow(run);
    }),

  markReconciled: (exceptionId, input, byUserId) =>
    simulateWrite((): ReconExceptionView => {
      const actor = adminOnly(byUserId);
      const e = byId(reconExceptions, exceptionId);
      if (!e) throw new RepositoryError('not_found');
      if (e.status !== 'open') throw new RepositoryError('invalid_state');
      const problem = reconcileProblem(e, input.category, input.note, !!input.confirmSerious);
      if (problem) throw new RepositoryError(problem);
      const now = Date.now();
      patchInPlace(reconExceptions, e.id, { status: 'reconciled', reconciled: { category: input.category, note: input.note.trim(), byName: actor.name, at: new Date(now).toISOString(), confirmedSerious: !!input.confirmSerious } });
      syncReconciliationAlerts(now);
      syncCommitments(now);
      const ledger = new Map(ledgerEntriesOf().map((l) => [l.id, l]));
      return reconExceptionView(byId(reconExceptions, e.id)!, now, ledger);
    }),

  setBankFeed: (status, byUserId) =>
    simulateWrite((): BankFeed => {
      adminOnly(byUserId);
      const now = Date.now();
      bankFeed = { status, since: new Date(now).toISOString(), reason: status === 'unavailable' ? 'outage' : undefined, lastStatementAt: bankFeed.lastStatementAt };
      syncReconciliation(now);
      syncCommitments(now);
      return { ...bankFeed };
    }),

  /* --------------------------------- Supplier payment analytics (119) */
  getSupplierPaymentAnalytics: (months, byUserId) =>
    simulateRead((): SupplierPaymentAnalytics => {
      adminOnly(byUserId);
      const now = Date.now();
      syncSupplierPayments(now);
      syncSupplierReviewFlags(now);
      return computeSupplierPaymentAnalytics(months, now);
    }),

  saveSpendNote: (input, byUserId) =>
    simulateWrite((): SpendNoteView => {
      const actor = adminOnly(byUserId);
      const label = input.label.trim();
      if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(input.month) || label.length < NOTE_LABEL_MIN) throw new RepositoryError('invalid_input');
      const now = Date.now();
      if (input.month > monthKey(new Date(now).toISOString())) throw new RepositoryError('in_future');
      if (!supplierPayments.some((p) => p.status === 'executed' && p.executedAt && monthKey(p.executedAt) === input.month)) throw new RepositoryError('no_spend');
      if (spendNotes.some((n) => n.month === input.month)) throw new RepositoryError('duplicate');
      spendNoteCounter += 1;
      const created: SupplierSpendNote = { id: `sn-new-${spendNoteCounter}`, month: input.month, label, note: input.note?.trim() || undefined, createdByName: actor.name, createdAt: new Date(now).toISOString(), isDemo: true };
      spendNotes.push(created);
      return spendNoteView(created);
    }),

  removeSpendNote: (noteId, byUserId) =>
    simulateWrite(() => {
      adminOnly(byUserId);
      const index = spendNotes.findIndex((n) => n.id === noteId);
      if (index === -1) throw new RepositoryError('not_found');
      spendNotes.splice(index, 1);
    }),

  /* --------------------------------------------- Delivery analytics (110) */
  getDeliveryAnalytics: (months, byUserId) =>
    simulateRead((): DeliveryAnalytics => {
      adminOnly(byUserId);
      const now = Date.now();
      syncPartnerFeeds(now);
      return computeDeliveryAnalytics(months, now);
    }),

  saveDeliveryDisruption: (input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const label = input.label.trim();
      const start = new Date(`${input.startsOn}T00:00:00`).getTime();
      const end = new Date(`${input.endsOn}T00:00:00`).getTime();
      if (label.length < 3 || Number.isNaN(start) || Number.isNaN(end)) throw new RepositoryError('invalid_input');
      if (end < start) throw new RepositoryError('dates_reversed');
      // A disruption is a spell, not a season: long ones would quietly hide a real decline.
      if ((end - start) / DAY_MS > 90) throw new RepositoryError('too_long');
      if (start > Date.now() + DAY_MS) throw new RepositoryError('in_future');
      if (deliveryDisruptions.some((d) => d.label.toLowerCase() === label.toLowerCase() && d.startsOn === input.startsOn)) throw new RepositoryError('duplicate');
      disruptionCounter += 1;
      const created: DeliveryDisruption = { id: `dis-new-${disruptionCounter}`, label, note: input.note?.trim() || undefined, startsOn: input.startsOn, endsOn: input.endsOn, createdByName: actor.name, createdAt: new Date().toISOString(), isDemo: true };
      deliveryDisruptions.push(created);
      const view = computeDeliveryAnalytics(6, Date.now()).disruptions.find((d) => d.id === created.id);
      return view ?? { id: created.id, label, note: created.note ?? null, startsOn: created.startsOn, endsOn: created.endsOn, source: 'admin' as const, deliveriesAffected: 0 };
    }),

  removeDeliveryDisruption: (disruptionId, byUserId) =>
    simulateWrite(() => {
      adminOnly(byUserId);
      const index = deliveryDisruptions.findIndex((d) => d.id === disruptionId);
      if (index === -1) throw new RepositoryError('not_found');
      deliveryDisruptions.splice(index, 1);
    }),

  getTransitEstimate: (city, byUserId) =>
    simulateRead((): TransitEstimate => {
      catalogActor(byUserId);
      const from = windowStart(12, Date.now());
      const key = city.trim().toLowerCase();
      const summary = transitSummary(analyticsTrips().filter((t) => t.city.toLowerCase() === key && new Date(t.arrivedAt).getTime() >= from).map((t) => t.hours));
      return { city: city.trim(), trips: summary.trips, emerging: summary.emerging, suggestedDays: summary.suggestedDays, typicalHours: summary.medianHours };
    }),

  /* --------------------------------------------- Delivery partners (109) */
  getPartnerBoard: (byUserId) =>
    simulateRead((): PartnerBoard => {
      adminOnly(byUserId);
      const now = Date.now();
      syncPartnerFeeds(now);
      const cities = new Set<string>();
      for (const p of deliveryPartners) p.serviceAreas.forEach((a) => cities.add(a));
      for (const sp of suppliers) if (sp.city) cities.add(sp.city);
      for (const lead of leads) if (lead.city) cities.add(lead.city);
      return {
        partners: deliveryPartners.map((p) => partnerRowOf(p, now)).sort((a, b) => Number(a.status === 'paused') - Number(b.status === 'paused') || b.stats.score - a.stats.score),
        bookable: bookablePos(),
        analysis: partnerDelayAnalysis(now),
        knownCities: [...cities].sort(),
      };
    }),

  createDeliveryPartner: (input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const v = validatePartnerInput(input);
      if (deliveryPartners.some((p) => p.name.toLowerCase() === v.name.toLowerCase())) throw new RepositoryError('duplicate');
      partnerCounter += 1;
      const at = new Date().toISOString();
      const partner: DeliveryPartner = {
        id: `dp-new-${partnerCounter}`,
        name: v.name,
        contactName: v.contactName,
        phone: v.phone,
        email: v.email,
        serviceAreas: v.serviceAreas,
        liveTrackingSupported: v.liveTrackingSupported,
        feedStatus: 'connected',
        rateCardRef: v.rateCardRef,
        rateCardEffectiveFrom: at,
        lanes: [],
        status: 'active',
        events: [],
        createdAt: at,
        isDemo: true,
      };
      // A newcomer starts with no rating at all: neutral, neither blocked nor flattered.
      partner.events = partnerEvents(partner, 'onboarded', actor.name, 'New carrier. Rated only once they have delivered a few loads.');
      deliveryPartners.push(partner);
      return partnerRowOf(partner, Date.now());
    }),

  updateDeliveryPartner: (partnerId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const partner = partnerOrThrow(partnerId);
      const v = validatePartnerInput(input);
      if (deliveryPartners.some((p) => p.id !== partner.id && p.name.toLowerCase() === v.name.toLowerCase())) throw new RepositoryError('duplicate');
      // Withdrawing live tracking while a live delivery is in flight would strand its pin.
      if (!v.liveTrackingSupported && partner.liveTrackingSupported && shipmentLegs.some((l) => l.partnerId === partner.id && l.source === 'live_gps' && !l.milestones.some((m) => m.milestone === 'arrived'))) throw new RepositoryError('live_in_flight');
      const changedRate = v.rateCardRef !== partner.rateCardRef;
      const updated = patchInPlace(deliveryPartners, partner.id, {
        name: v.name,
        contactName: v.contactName,
        phone: v.phone,
        email: v.email,
        serviceAreas: v.serviceAreas,
        liveTrackingSupported: v.liveTrackingSupported,
        rateCardRef: v.rateCardRef,
        rateCardEffectiveFrom: changedRate ? new Date().toISOString() : partner.rateCardEffectiveFrom,
        feedStatus: v.liveTrackingSupported ? partner.feedStatus : 'connected',
        feedBrokenSince: v.liveTrackingSupported ? partner.feedBrokenSince : undefined,
        events: partnerEvents(partner, 'details', actor.name),
      });
      syncPartnerFeeds(Date.now());
      return partnerRowOf(updated, Date.now());
    }),

  addPartnerLane: (partnerId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const partner = partnerOrThrow(partnerId);
      const origin = input.originCity.trim();
      const destination = input.destinationCity.trim();
      if (origin.length < 2 || destination.length < 2 || !(input.distanceKm > 0) || !(input.ratePerTrip > 0) || !(input.transitDays >= 1)) throw new RepositoryError('invalid_input');
      // A lane is served, or it is not on the card.
      if (!serves(partner, destination)) throw new RepositoryError('area_not_served');
      const same = (l: DeliveryPartnerLane) => l.originCity.toLowerCase() === origin.toLowerCase() && l.destinationCity.toLowerCase() === destination.toLowerCase();
      partnerLaneCounter += 1;
      const lane: DeliveryPartnerLane = { id: `dpl-new-${partnerLaneCounter}`, originCity: origin, destinationCity: destination, distanceKm: Math.round(input.distanceKm), ratePerTrip: Math.round(input.ratePerTrip), transitDays: Math.round(input.transitDays) };
      // Re-quoting a lane replaces its price: the card never holds two for one route.
      const updated = patchInPlace(deliveryPartners, partner.id, {
        lanes: [...partner.lanes.filter((l) => !same(l)), lane],
        events: partnerEvents(partner, 'lane_added', actor.name, `${origin} → ${destination}: ₹${lane.ratePerTrip.toLocaleString('en-IN')}`),
      });
      return partnerRowOf(updated, Date.now());
    }),

  setPartnerStatus: (partnerId, status, note, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const partner = partnerOrThrow(partnerId);
      if (partner.status === status) throw new RepositoryError('invalid_state');
      if (status === 'paused' && note.trim().length < 4) throw new RepositoryError('note_required');
      const updated = patchInPlace(deliveryPartners, partner.id, { status, events: partnerEvents(partner, status === 'paused' ? 'paused' : 'resumed', actor.name, note) });
      return partnerRowOf(updated, Date.now());
    }),

  setPartnerFeed: (partnerId, feed, note, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const partner = partnerOrThrow(partnerId);
      if (!partner.liveTrackingSupported) throw new RepositoryError('no_live_feed');
      if (partner.feedStatus === feed) throw new RepositoryError('invalid_state');
      if (feed === 'outage' && note.trim().length < 4) throw new RepositoryError('note_required');
      const now = Date.now();
      patchInPlace(deliveryPartners, partner.id, {
        feedStatus: feed,
        feedBrokenSince: feed === 'outage' ? new Date(now).toISOString() : undefined,
        events: partnerEvents(partner, feed === 'outage' ? 'feed_outage' : 'feed_restored', actor.name, note),
      });
      syncPartnerFeeds(now);
      syncCommitments(now);
      return partnerRowOf(byId(deliveryPartners, partner.id)!, now);
    }),

  bookDeliveryPartner: (poId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const po = deliveryPoOrThrow(poId);
      const partner = partnerOrThrow(input.partnerId);
      const supplier = byId(suppliers, po.supplierId!)!;
      const site = shipmentSite(po.dealId);
      if (!site) throw new RepositoryError('no_destination');
      const siteCity = cityOfDeal(po.dealId);
      // The booking only ever offers a carrier that serves the site, and the repository holds the same line.
      const why = unavailableFor(partner, siteCity);
      if (why === 'paused') throw new RepositoryError('partner_paused');
      if (why === 'area') throw new RepositoryError('area_not_served');
      if (input.vehicleLabel.trim().length < 2 || input.driverName.trim().length < 2) throw new RepositoryError('invalid_input');
      const onALeg = new Set(shipmentLegs.flatMap((l) => l.lineItemIds));
      const lines = (po.lineItems ?? []).filter((l) => input.lineIds.includes(l.id));
      if (lines.length === 0 || lines.length !== input.lineIds.length || lines.some((l) => lineStageOf(po, l) !== 'ready_to_ship' || onALeg.has(l.id))) throw new RepositoryError('invalid_state');
      const now = Date.now();
      const mode = trackingModeOf(partner);
      const source: ShipmentLeg['source'] = mode === 'live' ? 'live_gps' : 'manual';
      const origin = originFor(supplier.city);
      const lane = laneFor(partner, supplier.city ?? '', siteCity);
      movePoLinesSync(po.id, lines.map((l) => l.id), 'shipped', actor, `Booked with ${partner.name}`);
      shipmentCounter += 1;
      const at = new Date(now).toISOString();
      const leg: ShipmentLeg = {
        id: `shp-new-${shipmentCounter}`,
        poId: po.id,
        dealId: po.dealId,
        supplierId: supplier.id,
        lineItemIds: lines.map((l) => l.id),
        vehicleLabel: input.vehicleLabel.trim(),
        driverName: input.driverName.trim(),
        driverPhone: input.driverPhone?.trim() || undefined,
        source,
        origin: { name: `${supplier.name}, ${origin.name}`, lat: origin.lat, lng: origin.lng },
        dispatchedAt: at,
        etaAt: estimateEtaAt(origin, site, now),
        partnerId: partner.id,
        freightCost: lane?.ratePerTrip,
        bookedByName: actor.name,
        milestones: [{ milestone: 'dispatched', at, source: source === 'live_gps' ? 'gps' : 'manual', byName: source === 'manual' ? actor.name : undefined, note: mode === 'fallback' ? `${partner.name}'s live tracking is down, so milestones only.` : undefined }],
        isDemo: true,
      };
      shipmentLegs.push(leg);
      patchInPlace(deliveryPartners, partner.id, { events: partnerEvents(partner, 'booked', actor.name, `${po.code} to ${site.siteName}`) });
      // Tell the supplier who is coming, when it can be read in the app.
      if (supplierUserFor(supplier)) {
        pushSupplierMessage(ensureSupplierThread(supplier.id, po.id), {
          author: 'aiec',
          authorName: actor.name,
          authorUserId: actor.id,
          body: `${partner.name} will collect ${lines.map((l) => l.description).join(', ')} for ${site.siteName} (${leg.vehicleLabel}, driver ${leg.driverName}). Please have it ready to load.`,
          channel: 'in_app',
          at,
          expectsReply: false,
          poRef: po.id,
        });
      }
      notifyCustomerOfMilestone(leg.id, 'dispatched');
      syncCommitments(now);
      return { legId: leg.id, trackingMode: mode, freightCost: lane?.ratePerTrip ?? null };
    }),

  /* --------------------------------------------- Delivery SOP (107) */
  getDeliverySopBoard: (byUserId) =>
    simulateRead((): DeliverySopBoard => {
      adminOnly(byUserId);
      const now = Date.now();
      const templates = deliverySops.map((t) => sopTemplateViewOf(t, now));
      const known = new Set(deliverySops.map((t) => t.category));
      const seen = new Set<string>([...KNOWN_PART_CATEGORIES, ...supplierPurchaseOrders.flatMap((p) => (p.lineItems ?? []).map((l) => l.category))]);
      return { templates, untemplated: [...seen].filter((c) => !known.has(c)).sort() };
    }),

  saveDeliverySopVersion: (input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const now = Date.now();
      if (input.changeNote.trim().length < 4) throw new RepositoryError('note_required');
      const steps = input.steps.map((s) => ({ ...s, label: s.label.trim() }));
      if (checkSteps(steps, false).length > 0) throw new RepositoryError('invalid_steps');
      const effective = new Date(input.effectiveFrom).getTime();
      const startOfToday = new Date(now).setHours(0, 0, 0, 0);
      // A procedure can be scheduled or take effect today, but never rewrite the past.
      if (Number.isNaN(effective) || effective < startOfToday) throw new RepositoryError('effective_in_past');
      let template = input.templateId ? byId(deliverySops, input.templateId) : undefined;
      if (input.templateId && !template) throw new RepositoryError('not_found');
      const createdAt = new Date(now).toISOString();
      if (!template) {
        const category = (input.category ?? '').trim().toLowerCase().replace(/[^a-z0-9_]+/g, '_').replace(/^_+|_+$/g, '');
        if (category.length < 2 || category === MASTER_CATEGORY || deliverySops.some((t) => t.category === category)) throw new RepositoryError('invalid_category');
        // A category's own template exists to add steps to the master's; it cannot be empty.
        if (steps.length === 0) throw new RepositoryError('invalid_steps');
        sopCounter += 1;
        template = { id: `sop-new-${sopCounter}`, category, name: category, versions: [], createdByName: actor.name, createdAt, isDemo: true };
        deliverySops.push(template);
      }
      const latest = [...template.versions].sort((a, b) => b.version - a.version)[0];
      // Versions keep their order in time: a new one cannot take effect before the one it amends.
      if (latest && effective < new Date(latest.effectiveFrom).getTime()) throw new RepositoryError('effective_before_previous');
      if (template.category !== MASTER_CATEGORY && steps.length === 0) throw new RepositoryError('invalid_steps');
      const version: DeliverySopVersion = {
        id: `${template.id}-v${(latest?.version ?? 0) + 1}`,
        templateId: template.id,
        version: (latest?.version ?? 0) + 1,
        effectiveFrom: new Date(effective).toISOString(),
        // A step that already existed keeps its id, so older results still line up with it.
        steps: steps.map((s, i) => ({ ...s, id: s.id ?? `${template!.id}-v${(latest?.version ?? 0) + 1}-s${i + 1}` })),
        changeNote: input.changeNote.trim(),
        createdByName: actor.name,
        createdAt,
      };
      const updated = patchInPlace(deliverySops, template.id, { versions: [...template.versions, version] });
      return sopTemplateViewOf(updated, now);
    }),

  /* --------------------------------------------- Stock in transit (106) */
  getTransitBoard: (byUserId) =>
    simulateRead((): TransitBoard => {
      adminOnly(byUserId);
      const now = Date.now();
      const lines = transitLinesOf(now);
      // Delayed lines, across whoever is making them: one supplier late is the scorecard's job,
      // several suppliers late on the same part is the market's.
      const delayed = lines.filter((l) => l.delaySeverity).map((l) => ({ category: l.category, supplierId: l.supplierId, supplierName: l.supplierName, poId: l.poId, value: l.value }));
      const recent = now - 30 * 86_400_000;
      for (const c of delayCases) {
        if (c.status === 'open' || !c.recoveredAt || new Date(c.recoveredAt).getTime() < recent) continue;
        const po = byId(supplierPurchaseOrders, c.poId);
        for (const line of po?.lineItems ?? []) delayed.push({ category: line.category, supplierId: c.supplierId, supplierName: byId(suppliers, c.supplierId)?.name ?? '', poId: c.poId, value: 0 });
      }
      const capDeals = capacityDeals(lines, now);
      return {
        lines,
        totals: transitTotalsOf(lines),
        insights: categoryPatterns(delayed),
        capacity: {
          weeks: capacityWeeks(capDeals.map((d) => ({ dealId: d.dealId, readyBy: d.readyBy, confidence: d.confidence, installStart: d.installStart, status: d.status })), now),
          deals: capDeals,
        },
        orphans: orphanRows(),
        redirectTargets: deals.filter((d) => d.status === 'won').map((d) => ({ dealId: d.id, code: d.code, siteName: resolveLead(d.leadId)?.siteName ?? d.code })),
      };
    }),

  getInTransitTotals: (byUserId) =>
    simulateRead((): TransitTotals => {
      adminOnly(byUserId);
      return transitTotalsOf(transitLinesOf(Date.now()));
    }),

  resolveOrphanedPo: (poId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const po = byId(supplierPurchaseOrders, poId);
      if (!po || !isOrphanedPo(po)) throw new RepositoryError('not_found');
      if (po.orphanResolution || po.receivedAt) throw new RepositoryError('invalid_state');
      const at = new Date().toISOString();
      const supplier = po.supplierId ? byId(suppliers, po.supplierId) : null;
      if (input.kind === 'redirect') {
        const target = input.toDealId ? byId(deals, input.toDealId) : undefined;
        // Only to a deal that is live: parts must not be re-attached to another cancelled one.
        if (!target || target.status !== 'won' || target.id === po.dealId) throw new RepositoryError('invalid_input');
        const from = po.dealId;
        patchInPlace(supplierPurchaseOrders, po.id, { dealId: target.id, orphanResolution: { kind: 'redirect', toDealId: target.id, note: input.note?.trim() || undefined, decidedByName: actor.name, decidedAt: at } });
        // Everything that followed the parts to the old site follows them to the new one.
        for (const leg of shipmentLegs.filter((l) => l.poId === po.id)) patchInPlace(shipmentLegs, leg.id, { dealId: target.id });
        for (const sch of deliverySchedules.filter((s) => s.poId === po.id)) patchInPlace(deliverySchedules, sch.id, { dealId: target.id, jobId: undefined });
        for (const c of delayCases.filter((x) => x.poId === po.id)) patchInPlace(delayCases, c.id, { dealId: target.id });
        logAutomatedAction({
          sourceKey: 'delivery.po_redirected',
          triggeringCondition: `${po.code} was ordered for ${from}, which is no longer a live deal`,
          actionTaken: `Redirected it to ${target.code}`,
          affectedRecordId: po.id,
          affectedRecordType: 'purchase_order',
          subjectLabel: po.code,
        });
        syncCommitments(Date.now());
        return { threadId: null };
      }
      if ((input.note ?? '').trim().length < 4) throw new RepositoryError('invalid_input');
      let threadId: string | null = null;
      // Told to the supplier in the order's own conversation, when they have somewhere to read it.
      if (supplier && supplierUserFor(supplier)) {
        const thread = ensureSupplierThread(supplier.id, po.id);
        pushSupplierMessage(thread, {
          author: 'aiec',
          authorName: actor.name,
          authorUserId: actor.id,
          body: `The customer deal for ${po.code} has been cancelled. Please stop work and arrange to take the parts back. ${input.note!.trim()}`,
          channel: 'in_app',
          at,
          expectsReply: true,
          poRef: po.id,
        });
        threadId = thread.id;
      }
      patchInPlace(supplierPurchaseOrders, po.id, { orphanResolution: { kind: 'return', note: input.note!.trim(), decidedByName: actor.name, decidedAt: at } });
      syncCommitments(Date.now());
      return { threadId };
    }),

  /* ------------------------------ Delivery delay escalation (105) */
  getDelayBoard: (byUserId) =>
    simulateRead((): DelayBoard => {
      adminOnly(byUserId);
      const now = Date.now();
      // The heartbeat keeps this current; reading it first means a screen opened between beats is never behind.
      syncDelayCases(now);
      const recent = now - 3 * 86_400_000;
      const rows = delayCases.filter((c) => byId(supplierPurchaseOrders, c.poId)).map((c) => delayRowOf(c, now));
      const open = rows
        .filter((r) => r.status === 'open')
        .map((r) => ({ ...r, severity: r.severity ?? r.worstSeverity }))
        .sort((a, b) => compareDelays({ severity: a.severity, impact: a.impact, gapHours: a.gapHours, dealValue: a.dealValue }, { severity: b.severity, impact: b.impact, gapHours: b.gapHours, dealValue: b.dealValue }));
      const recovered = rows.filter((r) => r.status === 'recovered' && r.recoveredAt && new Date(r.recoveredAt).getTime() > recent).sort((a, b) => ((b.recoveredAt ?? '') < (a.recoveredAt ?? '') ? -1 : 1));
      return { open, recovered };
    }),

  tagDelayCause: (caseIds, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      if (caseIds.length === 0) throw new RepositoryError('invalid_input');
      const label = input.externalLabel?.trim();
      if (input.cause === 'external_event' && (!label || label.length < 3)) throw new RepositoryError('label_required');
      const now = Date.now();
      const at = new Date(now).toISOString();
      for (const id of caseIds) {
        const c = delayCaseOrThrow(id);
        if (c.status !== 'open') throw new RepositoryError('invalid_state');
        const po = byId(supplierPurchaseOrders, c.poId)!;
        let moved: string | undefined;
        if (input.cause === 'external_event') {
          // Nobody's fault, so the supplier is measured against when it can actually arrive, not the date before the flood.
          const facts = delayFactsOf(po, now);
          const promised = promisedDeliveryOf(po);
          if (facts && promised && new Date(facts.currentEta).getTime() > new Date(promised).getTime()) {
            patchInPlace(supplierPurchaseOrders, po.id, { expectedDeliveryDate: endOfDayIso(facts.currentEta.slice(0, 10)) });
            moved = promised;
          }
          ratingCounter += 1;
          scoreContextNotes.push({
            id: `scn-new-${ratingCounter}`,
            supplierId: c.supplierId,
            note: `${po.code} was delayed by ${label}. The delivery date was moved, so it does not count against the on-time rate.`,
            addedBy: actor.name,
            addedAt: at,
            isDemo: true,
          });
        }
        patchInPlace(delayCases, c.id, {
          rootCause: input.cause,
          rootCauseNote: input.note?.trim() || undefined,
          externalLabel: input.cause === 'external_event' ? label : undefined,
          causeTaggedByName: actor.name,
          causeTaggedAt: at,
          promiseMovedFrom: moved ?? c.promiseMovedFrom,
        });
      }
      syncDelayCases(now);
      syncCommitments(now);
    }),

  contactSupplierAboutDelay: (caseId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const c = delayCaseOrThrow(caseId);
      const po = byId(supplierPurchaseOrders, c.poId);
      const supplier = byId(suppliers, c.supplierId);
      if (!po || !supplier) throw new RepositoryError('not_found');
      if (input.body.trim().length < 4) throw new RepositoryError('invalid_input');
      const thread = ensureSupplierThread(supplier.id, po.id);
      const at = new Date().toISOString();
      if (input.channel === 'in_app') {
        // Nothing waits in an inbox nobody opens.
        if (!supplierUserFor(supplier)) throw new RepositoryError('no_portal');
        pushSupplierMessage(thread, { author: 'aiec', authorName: actor.name, authorUserId: actor.id, body: input.body.trim(), channel: 'in_app', at, expectsReply: input.expectsReply, poRef: po.id });
      } else {
        pushSupplierMessage(thread, { author: 'aiec', authorName: actor.name, authorUserId: actor.id, body: input.body.trim(), channel: input.channel, at, loggedBy: actor.name, expectsReply: input.expectsReply, poRef: po.id, readAt: at });
      }
      patchInPlace(delayCases, c.id, { contactedSupplierAt: at });
      syncCommitments(Date.now());
      return { threadId: thread.id };
    }),

  notifyDelayCustomers: (caseIds, byUserId) =>
    simulateWrite((): NotifyDelayResult => {
      const actor = adminOnly(byUserId);
      const now = Date.now();
      const at = new Date(now).toISOString();
      const result: NotifyDelayResult = { notified: 0, skipped: [] };
      // One message per customer, however many of their orders are late.
      const told = new Set<string>();
      for (const id of caseIds) {
        const c = delayCaseOrThrow(id);
        if (c.status !== 'open') throw new RepositoryError('invalid_state');
        const po = byId(supplierPurchaseOrders, c.poId)!;
        const facts = delayFactsOf(po, now);
        const message = delayMessageFor(c, facts);
        const eta = facts?.currentEta ?? at;
        if (!message.lead || !message.template) {
          result.skipped.push({ caseId: id, reason: 'no_contact' });
          continue;
        }
        if (c.customerNotifiedAt && !etaMovedSince(c.customerNotifiedEta, eta)) {
          result.skipped.push({ caseId: id, reason: 'already_told' });
          continue;
        }
        if (isOptedOutSync(message.lead.contactPhone, message.template.channel)) {
          result.skipped.push({ caseId: id, reason: 'opted_out' });
          continue;
        }
        if (!told.has(message.lead.id)) {
          let conversation = conversations.find((cv) => cv.leadId === message.lead!.id) ?? null;
          if (!conversation) {
            conversationCounter += 1;
            conversation = { id: `conv-new-${conversationCounter}`, leadId: message.lead.id, lastMessageAt: at, isDemo: true };
            conversations.push(conversation);
          }
          messageCounter += 1;
          commMessages.push({ id: `cm-new-${messageCounter}`, conversationId: conversation.id, channel: message.channel, sender: 'agent', body: message.body, templateGroupId: message.template.groupId, status: 'sent', at, handled: true });
          patchInPlace(conversations, conversation.id, { lastMessageAt: at });
          told.add(message.lead.id);
          result.notified += 1;
          void actor;
        }
        patchInPlace(delayCases, c.id, { customerNotifiedAt: at, customerNotifiedEta: eta });
      }
      syncCommitments(now);
      return result;
    }),

  escalateDelay: (caseId, note, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const c = delayCaseOrThrow(caseId);
      if (c.status !== 'open') throw new RepositoryError('invalid_state');
      if (note.trim().length < 4) throw new RepositoryError('invalid_input');
      const po = byId(supplierPurchaseOrders, c.poId)!;
      raiseAlert({
        titleKey: 'deliveryDelay.alert.escalated',
        context: `${po.code} · ${byId(suppliers, c.supplierId)?.name ?? ''} · ${note.trim()}`,
        severity: 'high',
        category: 'supplier',
        relatedId: c.id,
        sourceRoute: `/delivery-delays?case=${c.id}`,
      });
      patchInPlace(delayCases, c.id, { escalatedAt: new Date().toISOString(), escalatedByName: actor.name });
      syncCommitments(Date.now());
    }),

  /* ------------------------------------------- Delivery scheduling (101) */
  getDeliveryBoard: (byUserId) =>
    simulateRead((): DeliveryBoard => {
      const { supplierId } = threadViewer(byUserId);
      const now = Date.now();
      const recent = now - 60 * 86_400_000;
      const cards = supplierPurchaseOrders
        .filter((po) => po.status === 'sent' && po.supplierId && byId(suppliers, po.supplierId))
        .filter((po) => !supplierId || po.supplierId === supplierId)
        // Delivered orders stay for the calendar's recent past, and only if they were booked.
        .filter((po) => !po.receivedAt || (scheduleOfPo(po.id) && new Date(po.receivedAt).getTime() > recent))
        .map((po) => deliveryCardFor(po, now));
      return {
        cards,
        ownAvailability: supplierId ? availabilityOf(supplierId) : null,
        availabilityBySupplier: Object.fromEntries(dispatchAvailability.filter((a) => !supplierId || a.supplierId === supplierId).map((a) => [a.supplierId, a])),
      };
    }),

  getDeliverySlots: (poId, byUserId) =>
    simulateRead((): DeliverySlotView | null => {
      const { supplierId } = threadViewer(byUserId);
      const po = byId(supplierPurchaseOrders, poId);
      if (!po || po.status !== 'sent' || !po.supplierId || (supplierId && po.supplierId !== supplierId)) return null;
      const availability = availabilityOf(po.supplierId);
      const others = deliverySchedules.filter((s) => s.supplierId === po.supplierId && s.poId !== po.id);
      return { availability, days: slotDays(availability, others, Date.now()) };
    }),

  setSiteReadiness: (dealId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      if (!byId(deals, dealId) && !supplierPurchaseOrders.some((p) => p.dealId === dealId)) throw new RepositoryError('not_found');
      const complete = Object.values(input.items).every(Boolean);
      // Confirmation is somebody on site vouching for the whole list — never a bare tick.
      if (complete && input.contactName.trim().length < 2) throw new RepositoryError('contact_required');
      const now = new Date().toISOString();
      const previous = readinessOf(dealId);
      const wasConfirmed = readinessConfirmed(previous);
      const next: SiteReadiness = {
        ...previous,
        dealId,
        items: { ...input.items },
        contactName: input.contactName.trim() || previous.contactName,
        confirmedAt: complete ? (wasConfirmed ? previous.confirmedAt : now) : undefined,
        confirmedBy: complete ? (wasConfirmed ? previous.confirmedBy : actor.name) : undefined,
        isDemo: true,
      };
      const index = siteReadinessRecords.findIndex((r) => r.dealId === dealId);
      if (index === -1) siteReadinessRecords.push(next);
      else siteReadinessRecords[index] = next;
      return next;
    }),

  scheduleDelivery: (poId, input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const po = deliveryPoOrThrow(poId);
      const existing = scheduleOfPo(poId);
      if (po.receivedAt || existing?.status === 'scheduled') throw new RepositoryError('invalid_state');
      // Structurally: no date for a shipment that would arrive at a site with no shaft to receive it.
      if (!readinessConfirmed(readinessOf(po.dealId))) throw new RepositoryError('readiness_required');
      const dependsOn = input.dependsOnPoId === undefined ? existing?.dependsOnPoId : input.dependsOnPoId;
      const now = Date.now();
      assertBookable(po, input.date, input.window, dependsOn, now);
      const late = laterThanPromise(input.date, promisedDeliveryOf(po));
      if (late && !input.lateCause) throw new RepositoryError('late_cause_required');
      const at = new Date(now).toISOString();
      const promiseMovedFrom = late ? movePromiseIfSiteCaused(po, input.date, input.lateCause!) : undefined;
      const event = deliveryEvent({ kind: 'scheduled', at, byName: actor.name, byRole: 'admin', date: input.date, window: input.window, cause: late ? input.lateCause : undefined, reason: input.note?.trim() || undefined, promiseMovedFrom });
      let schedule: DeliverySchedule;
      if (existing) {
        schedule = patchInPlace(deliverySchedules, existing.id, { status: 'scheduled', date: input.date, window: input.window, dependsOnPoId: dependsOn ?? undefined, events: [...existing.events, event] });
      } else {
        deliveryCounter += 1;
        schedule = { id: `dsch-new-${deliveryCounter}`, poId, dealId: po.dealId, supplierId: po.supplierId!, status: 'scheduled', date: input.date, window: input.window, dependsOnPoId: dependsOn ?? undefined, failedAttempts: 0, events: [event], createdAt: at, isDemo: true };
        deliverySchedules.push(schedule);
      }
      return finishDeliveryBooking(po, schedule, at);
    }),

  rescheduleDelivery: (poId, input, byUserId) =>
    simulateWrite(() => {
      const { actor, supplierId } = threadViewer(byUserId);
      const po = deliveryPoOrThrow(poId);
      if (supplierId && po.supplierId !== supplierId) throw new RepositoryError('forbidden');
      const existing = scheduleOfPo(poId);
      if (po.receivedAt || existing?.status !== 'scheduled' || !existing.date || !existing.window) throw new RepositoryError('invalid_state');
      const byRole = actor.role === 'admin' ? 'admin' : 'supplier';
      // A supplier can only ever move a date on its own account.
      const cause: DeliveryRescheduleCause = byRole === 'supplier' ? 'supplier' : input.cause;
      // Always with a reason — it keeps the customer's expectations honest and feeds the supplier's record.
      if (input.reason.trim().length < 4) throw new RepositoryError('reason_required');
      if (input.date === existing.date && input.window === existing.window && input.dependsOnPoId === undefined) throw new RepositoryError('invalid_input');
      if (byRole === 'admin' && !readinessConfirmed(readinessOf(po.dealId))) throw new RepositoryError('readiness_required');
      const dependsOn = input.dependsOnPoId === undefined ? existing.dependsOnPoId : input.dependsOnPoId;
      const now = Date.now();
      assertBookable(po, input.date, input.window, dependsOn, now);
      const at = new Date(now).toISOString();
      const promiseMovedFrom = movePromiseIfSiteCaused(po, input.date, cause);
      const event = deliveryEvent({
        kind: 'rescheduled', at, byName: actor.name, byRole, date: input.date, window: input.window, fromDate: existing.date, fromWindow: existing.window, cause, reason: input.reason.trim(), promiseMovedFrom,
      });
      const schedule = patchInPlace(deliverySchedules, existing.id, { date: input.date, window: input.window, dependsOnPoId: dependsOn ?? undefined, events: [...existing.events, event] });
      return finishDeliveryBooking(po, schedule, at);
    }),

  recordDeliveryAttempt: (poId, note, byUserId) =>
    simulateWrite(() => {
      const { actor, supplierId } = threadViewer(byUserId);
      const po = deliveryPoOrThrow(poId);
      if (supplierId && po.supplierId !== supplierId) throw new RepositoryError('forbidden');
      const existing = scheduleOfPo(poId);
      if (po.receivedAt || existing?.status !== 'scheduled') throw new RepositoryError('invalid_state');
      if (note.trim().length < 10) throw new RepositoryError('reason_required');
      const at = new Date().toISOString();
      const byRole = actor.role === 'admin' ? 'admin' : 'supplier';
      const event = deliveryEvent({ kind: 'attempt_failed', at, byName: actor.name, byRole, date: existing.date, window: existing.window, reason: note.trim() });
      // Not a reschedule: the trip was made and wasted. The site's confirmation is void until it's vouched for again.
      const schedule = patchInPlace(deliverySchedules, existing.id, { status: 'attempt_failed', date: undefined, window: undefined, failedAttempts: existing.failedAttempts + 1, events: [...existing.events, event] });
      const readiness = readinessOf(po.dealId);
      const reset: SiteReadiness = { ...readiness, confirmedAt: undefined, confirmedBy: undefined, resetReason: note.trim(), resetAt: at };
      const index = siteReadinessRecords.findIndex((r) => r.dealId === po.dealId);
      if (index === -1) siteReadinessRecords.push(reset);
      else siteReadinessRecords[index] = reset;
      raiseAlert({
        titleKey: 'deliveryScheduling.alert.attemptFailed',
        context: `${po.code}${siteOfDeal(po.dealId).siteName ? ` — ${siteOfDeal(po.dealId).siteName}` : ''}: ${note.trim()}`,
        severity: 'high',
        category: 'supplier',
        relatedId: po.id,
        sourceRoute: `/deliveries?poId=${po.id}`,
      });
      syncCommitments(Date.now());
      return schedule;
    }),

  saveDispatchAvailability: (input, byUserId) =>
    simulateWrite(() => {
      const { actor, supplierId } = threadViewer(byUserId);
      if (supplierId && input.supplierId !== supplierId) throw new RepositoryError('forbidden');
      if (!byId(suppliers, input.supplierId)) throw new RepositoryError('not_found');
      const weekdays = [...new Set(input.weekdays)].sort();
      const windows = [...new Set(input.windows)];
      const validKey = (k: string) => /^\d{4}-\d{2}-\d{2}$/.test(k) && !Number.isNaN(parseKey(k).getTime());
      if (weekdays.length === 0 || weekdays.some((d) => !Number.isInteger(d) || d < 0 || d > 6)) throw new RepositoryError('invalid_input');
      if (windows.length === 0) throw new RepositoryError('invalid_input');
      if (!Number.isInteger(input.maxPerDay) || input.maxPerDay < 1 || input.maxPerDay > 10) throw new RepositoryError('invalid_input');
      if (!Number.isInteger(input.leadDays) || input.leadDays < 0 || input.leadDays > 30) throw new RepositoryError('invalid_input');
      if (input.blackouts.length > 60 || input.blackouts.some((b) => !validKey(b.date) || b.reason.trim().length < 2)) throw new RepositoryError('invalid_input');
      const next: SupplierDispatchAvailability = {
        supplierId: input.supplierId,
        weekdays,
        windows,
        maxPerDay: input.maxPerDay,
        leadDays: input.leadDays,
        blackouts: [...input.blackouts].map((b) => ({ date: b.date, reason: b.reason.trim() })).sort((a, b) => (a.date < b.date ? -1 : 1)),
        updatedBy: actor.name,
        updatedAt: new Date().toISOString(),
        isDemo: true,
      };
      const index = dispatchAvailability.findIndex((a) => a.supplierId === input.supplierId);
      if (index === -1) dispatchAvailability.push(next);
      else dispatchAvailability[index] = next;
      return next;
    }),

  /* ------------------------------------------ Supplier payment terms (100) */
  getSupplierPaymentTerms: (byUserId) =>
    simulateRead((): SupplierPaymentTermsView => {
      adminOnly(byUserId);
      const now = Date.now();
      const rows = suppliers.map((supplier): SupplierTermsRow => {
        const { settings, custom } = effectiveSettings(supplier, paymentTermsConfig);
        const rated = supplierOrderRatings.filter((r) => r.supplierId === supplier.id).length;
        const score = computeSupplierPerformanceScore(supplier);
        return {
          supplier,
          tier: tierOf(supplier),
          settings,
          custom,
          score,
          ratedOrders: rated,
          graduateTo: graduationFor(tierOf(supplier), score, rated),
          agreementNetDays: agreementStateFor(supplier.id).current?.terms.paymentTermsDays ?? null,
        };
      });
      const rank: Record<SupplierRetention['status'], number> = { paused: 0, held: 1, withheld: 2, released: 3 };
      return {
        config: paymentTermsConfig,
        tierUsage: Object.fromEntries(TRUST_TIERS.map((t) => [t, rows.filter((r) => r.tier === t && !r.custom).length])) as Record<SupplierTrustTier, number>,
        suppliers: rows.sort((a, b) => TRUST_TIERS.indexOf(a.tier) - TRUST_TIERS.indexOf(b.tier) || a.supplier.name.localeCompare(b.supplier.name)),
        retentions: supplierRetentions
          .map((retention) => ({
            retention,
            poCode: byId(supplierPurchaseOrders, retention.poId)?.code ?? retention.poId,
            supplierName: byId(suppliers, retention.supplierId)?.name ?? '',
            overdueForReview: retention.status === 'held' && now - new Date(retention.heldAt).getTime() > RETENTION_REVIEW_AFTER,
          }))
          .sort((a, b) => rank[a.retention.status] - rank[b.retention.status] || (a.retention.heldAt < b.retention.heldAt ? 1 : -1)),
        history: [...supplierTermsHistory].sort((a, b) => (a.at < b.at ? 1 : -1)),
      };
    }),

  updateTierDefaults: (tier, settings, reason, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      if (checkSettings(settings).length > 0) throw new RepositoryError('invalid_input');
      if (reason.trim().length < 10) throw new RepositoryError('reason_required');
      const at = new Date().toISOString();
      paymentTermsConfig = { ...paymentTermsConfig, tiers: { ...paymentTermsConfig.tiers, [tier]: { ...settings } }, updatedBy: actor.name, updatedAt: at };
      recordTermsChange({ kind: 'tier_defaults', toTier: tier, settings, reason: reason.trim(), scoreAtChange: null, ratedOrdersAtChange: 0, by: actor.name, at });
      return paymentTermsConfig;
    }),

  setSupplierPaymentTier: (supplierId, tier, reason, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const supplier = byId(suppliers, supplierId);
      if (!supplier) throw new RepositoryError('not_found');
      if (reason.trim().length < 10) throw new RepositoryError('reason_required');
      const from = tierOf(supplier);
      if (from === tier) return supplier;
      const { score, rated } = supplierScoreNow(supplierId);
      const at = new Date().toISOString();
      recordTermsChange({ supplierId, kind: 'tier', fromTier: from, toTier: tier, reason: reason.trim(), scoreAtChange: score, ratedOrdersAtChange: rated, by: actor.name, at });
      // Orders already sent keep the terms frozen on them.
      return patchInPlace(suppliers, supplierId, { paymentTier: tier });
    }),

  setSupplierTermsOverride: (supplierId, settings, reason, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const supplier = byId(suppliers, supplierId);
      if (!supplier) throw new RepositoryError('not_found');
      if (reason.trim().length < 10) throw new RepositoryError('reason_required');
      if (settings && checkSettings(settings).length > 0) throw new RepositoryError('invalid_input');
      if (!settings && !supplier.paymentTermsOverride) return supplier;
      const { score, rated } = supplierScoreNow(supplierId);
      const at = new Date().toISOString();
      recordTermsChange({
        supplierId,
        kind: settings ? 'override_set' : 'override_cleared',
        settings: settings ?? undefined,
        reason: reason.trim(),
        scoreAtChange: score,
        ratedOrdersAtChange: rated,
        by: actor.name,
        at,
      });
      return patchInPlace(suppliers, supplierId, {
        paymentTermsOverride: settings ? { settings: { ...settings }, reason: reason.trim(), setBy: actor.name, setAt: at } : undefined,
      });
    }),

  decideRetention: (retentionId, decision, reason, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const r = byId(supplierRetentions, retentionId);
      if (!r) throw new RepositoryError('not_found');
      if (r.status === 'released' || r.status === 'withheld') throw new RepositoryError('invalid_state');
      // Keeping a supplier's money is never done without saying why.
      if (reason.trim().length < (decision === 'withhold' ? 10 : 4)) throw new RepositoryError('reason_required');
      return patchInPlace(supplierRetentions, retentionId, {
        status: decision === 'release' ? 'released' : 'withheld',
        decidedAt: new Date().toISOString(),
        decidedBy: actor.name,
        decisionReason: reason.trim(),
      });
    }),

  /* ------------------------------------ Supplier communication thread (099) */
  listSupplierThreads: (byUserId) =>
    simulateRead((): SupplierThreadSummary[] => {
      const { actor, supplierId } = threadViewer(byUserId);
      const now = Date.now();
      const viewerSide = actor.role === 'admin' ? 'aiec' : 'supplier';
      const rank = (s: SupplierThreadSummary) =>
        s.awaiting?.from === viewerSide ? (s.awaiting.overdue ? 0 : 1) : s.awaiting?.overdue ? 2 : s.awaiting ? 3 : 4;
      return supplierThreads
        .filter((th) => !supplierId || th.supplierId === supplierId)
        .map((th) => threadSummary(th, viewerSide, now))
        .sort((a, b) => rank(a) - rank(b) || ((a.lastMessage?.at ?? '') < (b.lastMessage?.at ?? '') ? 1 : -1));
    }),

  getSupplierThread: (ref, byUserId) =>
    simulateRead((): SupplierThreadView | null => {
      const { supplierId: ownSupplierId } = threadViewer(byUserId);
      const thread =
        'threadId' in ref
          ? byId(supplierThreads, ref.threadId)
          : supplierThreads.find((th) => th.supplierId === ref.supplierId && (th.relatedPoId ?? null) === (ref.poId ?? null));
      const supplierId = thread?.supplierId ?? ('supplierId' in ref ? ref.supplierId : null);
      const supplier = supplierId ? byId(suppliers, supplierId) : null;
      if (!supplier || (ownSupplierId && ownSupplierId !== supplier.id)) return null;
      const poId = thread ? thread.relatedPoId : 'poId' in ref ? ref.poId : undefined;
      const po = poId ? byId(supplierPurchaseOrders, poId) : null;
      if (poId && (!po || po.supplierId !== supplier.id)) return null;
      const messages = thread ? supplierMessages.filter((msg) => msg.threadId === thread.id).sort(byMessageAt) : [];
      const waiting = awaitingReply(messages);
      return {
        threadId: thread?.id ?? null,
        supplier,
        supplierHasPortal: !!supplierUserFor(supplier),
        po: po ? { id: po.id, code: po.code, dealId: po.dealId, stage: poStageOf(po), promisedDelivery: promisedDeliveryOf(po) } : null,
        messages,
        // The order's own record, shown in its conversation — derived, never copied.
        systemEvents: po?.sentAt
          ? [
              { id: `${po.id}-sent`, at: po.sentAt, stage: 'sent' as PoFulfilmentStage },
              ...uniquePoStageEvents(po).map((e) => ({ id: e.id, at: e.at, stage: e.toStage })),
            ]
          : [],
        awaiting: waiting ? { from: waiting.from, since: waiting.since, overdue: isUnanswered(waiting, Date.now()) } : null,
        lastSupplierResponseAt: lastSupplierResponseAt(messages),
        poOptions: supplierPurchaseOrders
          .filter((p) => p.supplierId === supplier.id && p.status === 'sent')
          .sort((a, b) => ((a.sentAt ?? '') < (b.sentAt ?? '') ? 1 : -1))
          .map((p) => ({ id: p.id, code: p.code })),
      };
    }),

  markSupplierThreadRead: (threadId, byUserId) =>
    simulateWrite(() => {
      const { actor, supplierId } = threadViewer(byUserId);
      const thread = byId(supplierThreads, threadId);
      if (!thread || (supplierId && thread.supplierId !== supplierId)) throw new RepositoryError('not_found');
      const otherSide = actor.role === 'admin' ? 'supplier' : 'aiec';
      const at = new Date().toISOString();
      for (let i = 0; i < supplierMessages.length; i += 1) {
        const msg = supplierMessages[i];
        if (msg.threadId === threadId && msg.author === otherSide && !msg.readAt) supplierMessages[i] = { ...msg, readAt: at };
      }
    }),

  postSupplierMessage: (input, byUserId) =>
    simulateWrite(() => {
      const { actor, supplierId } = threadViewer(byUserId);
      if (supplierId && input.supplierId !== supplierId) throw new RepositoryError('forbidden');
      const supplier = byId(suppliers, input.supplierId);
      if (!supplier) throw new RepositoryError('not_found');
      if (!input.body.trim()) throw new RepositoryError('invalid_input');
      // An in-app message to a supplier with no portal login would never be read.
      if (actor.role === 'admin' && !supplierUserFor(supplier)) throw new RepositoryError('no_portal');
      return pushSupplierMessage(ensureSupplierThread(supplier.id, input.poId), {
        author: actor.role === 'admin' ? 'aiec' : 'supplier',
        authorName: actor.name,
        authorUserId: actor.id,
        body: input.body.trim(),
        channel: 'in_app',
        at: new Date().toISOString(),
        expectsReply: input.expectsReply,
        poRef: input.poRef,
        attachmentName: input.attachmentName,
      });
    }),

  logSupplierContact: (input, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const supplier = byId(suppliers, input.supplierId);
      if (!supplier) throw new RepositoryError('not_found');
      if (input.body.trim().length < 4) throw new RepositoryError('invalid_input');
      // Logged after the fact, never ahead of it.
      if (Number.isNaN(new Date(input.at).getTime()) || new Date(input.at).getTime() > Date.now() + 60_000) throw new RepositoryError('invalid_input');
      return pushSupplierMessage(ensureSupplierThread(supplier.id, input.poId), {
        author: input.author,
        authorName: input.author === 'aiec' ? actor.name : supplier.name,
        authorUserId: input.author === 'aiec' ? actor.id : undefined,
        body: input.body.trim(),
        channel: input.channel,
        at: new Date(input.at).toISOString(),
        loggedBy: actor.name,
        expectsReply: input.expectsReply,
        poRef: input.poRef,
        // Both sides were there — nothing is waiting to be read.
        readAt: new Date().toISOString(),
      });
    }),

  flagSupplierMessageToRecord: (messageId, note, byUserId) =>
    simulateWrite(() => {
      const actor = adminOnly(byUserId);
      const message = byId(supplierMessages, messageId);
      if (!message) throw new RepositoryError('not_found');
      if (message.flaggedNoteId) throw new RepositoryError('invalid_state');
      if (note.trim().length < 10) throw new RepositoryError('invalid_input');
      const thread = byId(supplierThreads, message.threadId)!;
      ratingCounter += 1;
      const created: SupplierScoreContextNote = {
        id: `scn-new-${ratingCounter}`,
        supplierId: thread.supplierId,
        // Admin's own words, with the message quoted as it was — the record
        // says what was actually said, not a paraphrase of it.
        note: `${note.trim()} — “${message.body}”`,
        sourceMessageId: message.id,
        sourceThreadId: thread.id,
        addedBy: actor.name,
        addedAt: new Date().toISOString(),
        isDemo: true,
      };
      scoreContextNotes.push(created);
      patchInPlace(supplierMessages, messageId, { flaggedNoteId: created.id });
      return created;
    }),

  searchSupplierMessages: (query, byUserId) =>
    simulateRead((): SupplierMessageSearchHit[] => {
      const { supplierId } = threadViewer(byUserId);
      const q = query.trim().toLowerCase();
      if (q.length < 2) return [];
      return supplierMessages
        .map((message) => ({ message, thread: byId(supplierThreads, message.threadId)! }))
        .filter(({ thread }) => !supplierId || thread.supplierId === supplierId)
        .map(({ message, thread }) => ({
          threadId: thread.id,
          supplierName: byId(suppliers, thread.supplierId)?.name ?? '',
          poCode: thread.relatedPoId ? (byId(supplierPurchaseOrders, thread.relatedPoId)?.code ?? null) : null,
          message,
        }))
        .filter((hit) => [hit.message.body, hit.message.authorName, hit.supplierName, hit.poCode ?? '', hit.message.attachmentName ?? ''].some((x) => x.toLowerCase().includes(q)))
        .sort((a, b) => (a.message.at < b.message.at ? 1 : -1))
        .slice(0, 50);
    }),

  acknowledgeAgreementVersion: (versionId, byUserId) =>
    simulateWrite(() => {
      const actor = catalogActor(byUserId);
      const version = byId(supplierAgreementVersions, versionId);
      if (!version) throw new RepositoryError('not_found');
      const supplier = byId(suppliers, version.supplierId);
      // Only the supplier themselves can say "this is what we signed".
      if (!supplier || actor.role !== 'supplier' || supplierUserFor(supplier)?.id !== actor.id) throw new RepositoryError('forbidden');
      if (version.acknowledgedAt) return version;
      return patchInPlace(supplierAgreementVersions, versionId, { acknowledgedBy: actor.name, acknowledgedAt: new Date().toISOString() });
    }),

  /* ------------------------------------- Manufacturer production (096) */
  getProductionRecord: (recordId, byUserId) =>
    simulateRead((): ProductionRecordResult => {
      const actor = catalogActor(byUserId);
      let record = byId(productionRecords, recordId);
      const lineItemId = recordId.replace(/^prod-/, '');
      const po = record ? byId(supplierPurchaseOrders, record.poId) : supplierPurchaseOrders.find((p) => p.lineItems?.some((l) => l.id === lineItemId));
      const line = po?.lineItems?.find((l) => l.id === (record?.lineItemId ?? lineItemId));
      if (!po || !line) return { status: 'unavailable', reason: 'not_found' };
      const supplier = po.supplierId ? byId(suppliers, po.supplierId) : null;
      if (actor.role === 'supplier' && (!supplier || supplierUserFor(supplier)?.id !== actor.id)) return { status: 'unavailable', reason: 'not_found' };
      if (!supplier?.isManufacturer) return { status: 'unavailable', reason: 'not_manufacturer' };
      const lineStage = lineStageOf(po, line);
      if (!record) {
        if (po.status !== 'sent' || stageIndex(lineStage) < stageIndex('in_production')) return { status: 'unavailable', reason: 'not_in_production' };
        record = newProductionRecord(po, line, lineStageEnteredAt(po, line));
      }
      const deal = byId(deals, po.dealId);
      const stall = assessStall(record, productionRecords, Date.now());
      const siblings = record.batchId ? productionRecords.filter((r) => r.batchId === record!.batchId && r.id !== record!.id) : [];
      return {
        status: 'ok',
        view: {
          record,
          poCode: po.code,
          dealId: po.dealId,
          lineDescription: line.description,
          category: line.category,
          supplierName: supplier.name,
          dealCode: deal?.code ?? '',
          siteName: deal ? (resolveLead(deal.leadId)?.siteName ?? '') : '',
          lineStage,
          completionPct: completionPct(record),
          daysInStage: stall.daysInStage,
          expectedDays: stall.expectedDays,
          expectedIsDefault: stall.expectedIsDefault,
          stalled: stall.stalled,
          nextStage: nextStage(record),
          evidenceRequired: EVIDENCE_REQUIRED_STAGES.includes(record.currentStage) && !record.evidence.some((e) => e.stage === record!.currentStage),
          batchSiblings: siblings.map((r) => {
            const sib = lineFor(r);
            return { recordId: r.id, poCode: sib.po?.code ?? '', lineDescription: sib.line?.description ?? '', currentStage: r.currentStage };
          }),
          canUpdate: po.status === 'sent' && lineStage !== 'delivered',
        },
      };
    }),

  advanceProductionStage: (recordId, input, byUserId) =>
    simulateWrite(() => {
      const actor = catalogActor(byUserId);
      const record = byId(productionRecords, recordId);
      if (!record) throw new RepositoryError('not_found');
      assertProductionAccess(record, actor);
      // Admin signing off a manufacturer's stage is standing in for them.
      if (actor.role === 'admin' && !input.note?.trim()) throw new RepositoryError('note_required');
      const at = new Date().toISOString();
      const batch = input.applyToBatch && record.batchId
        ? productionRecords.filter((r) => r.batchId === record.batchId && r.id !== record.id && r.currentStage === record.currentStage)
        : [];
      // All or nothing: a batch sibling missing its test evidence stops the lot.
      for (const r of [record, ...batch]) {
        if (EVIDENCE_REQUIRED_STAGES.includes(r.currentStage) && !r.evidence.some((e) => e.stage === r.currentStage)) {
          throw new RepositoryError('evidence_required');
        }
      }
      const updated = advanceOne(record, actor, input.note, at, false);
      for (const sibling of batch) advanceOne(sibling, actor, input.note, at, true);
      return updated;
    }),

  regressProductionStage: (recordId, toStage, reason, byUserId) =>
    simulateWrite(() => {
      const actor = catalogActor(byUserId);
      const record = byId(productionRecords, recordId);
      if (!record) throw new RepositoryError('not_found');
      assertProductionAccess(record, actor);
      if (!reason.trim()) throw new RepositoryError('reason_required');
      if (record.stages.indexOf(toStage) < 0 || record.stages.indexOf(toStage) >= record.stages.indexOf(record.currentStage)) {
        throw new RepositoryError('invalid_stage');
      }
      const at = new Date().toISOString();
      const { po, line } = lineFor(record);
      // Reopening finished production takes the line back from "ready to ship".
      if (record.currentStage === 'complete' && po && line) {
        if (stageIndex(lineStageOf(po, line)) >= stageIndex('shipped')) throw new RepositoryError('already_shipped');
        // Moving the line back reopens the record (logging the reason once).
        movePoLinesSync(po.id, [line.id], 'in_production', actor, reason);
      }
      const current = byId(productionRecords, recordId)!;
      if (current.currentStage === toStage) return current;
      return patchInPlace(productionRecords, recordId, {
        currentStage: toStage,
        stageEnteredAt: at,
        completedAt: undefined,
        events: [...current.events, productionEvent(current, actor, { kind: 'regressed', fromStage: current.currentStage, toStage, reason: reason.trim() }, at)],
      });
    }),

  skipProductionStage: (recordId, stage, reason, byUserId) =>
    simulateWrite(() => {
      const actor = catalogActor(byUserId);
      const record = byId(productionRecords, recordId);
      if (!record) throw new RepositoryError('not_found');
      assertProductionAccess(record, actor);
      if (!reason.trim()) throw new RepositoryError('reason_required');
      if (stage === 'complete' || EVIDENCE_REQUIRED_STAGES.includes(stage)) throw new RepositoryError('not_skippable');
      const index = record.stages.indexOf(stage);
      if (index < 0 || index < record.stages.indexOf(record.currentStage)) throw new RepositoryError('invalid_stage');
      const at = new Date().toISOString();
      const stages = record.stages.filter((s) => s !== stage);
      const skippingCurrent = record.currentStage === stage;
      const moveTo = skippingCurrent ? stages[index] : record.currentStage;
      return patchInPlace(productionRecords, recordId, {
        stages,
        currentStage: moveTo,
        stageEnteredAt: skippingCurrent ? at : record.stageEnteredAt,
        events: [...record.events, productionEvent(record, actor, { kind: 'skipped', fromStage: stage, toStage: moveTo, reason: reason.trim() }, at)],
      });
    }),

  addProductionEvidence: (recordId, input, byUserId) =>
    simulateWrite(() => {
      const actor = catalogActor(byUserId);
      const record = byId(productionRecords, recordId);
      if (!record) throw new RepositoryError('not_found');
      assertProductionAccess(record, actor);
      if (!input.fileName.trim()) throw new RepositoryError('invalid_input');
      productionCounter += 1;
      const evidence: ProductionEvidence = {
        id: `pev-new-${productionCounter}`,
        stage: record.currentStage,
        fileName: input.fileName.trim(),
        kind: input.kind,
        previewUrl: input.previewUrl,
        note: input.note?.trim() || undefined,
        uploadedBy: actor.name,
        uploadedAt: new Date().toISOString(),
      };
      return patchInPlace(productionRecords, recordId, { evidence: [...record.evidence, evidence] });
    }),

  setSupplierManufacturer: (supplierId, isManufacturer) =>
    simulateWrite(() => {
      if (!byId(suppliers, supplierId)) throw new RepositoryError('not_found');
      return patchInPlace(suppliers, supplierId, { isManufacturer });
    }),

  /* --------------------------------------- Supplier order tracking (095) */
  listSupplierOrderBoard: (byUserId) =>
    simulateRead(() => {
      const actor = catalogActor(byUserId);
      let supplierScope: string | null = null;
      if (actor.role === 'supplier') {
        const own = suppliers.find((sp) => supplierUserFor(sp)?.id === actor.id);
        if (!own) return [];
        supplierScope = own.id;
      } else if (actor.role !== 'admin') {
        throw new RepositoryError('forbidden');
      }
      const now = Date.now();
      const recentCutoff = now - days(30);
      return supplierPurchaseOrders
        .filter((po) => po.status === 'sent' && po.lineItems && (!supplierScope || po.supplierId === supplierScope))
        .filter((po) => !po.receivedAt || new Date(po.receivedAt).getTime() >= recentCutoff)
        .map((po): SupplierOrderCard => {
          const supplier = po.supplierId ? byId(suppliers, po.supplierId) ?? undefined : undefined;
          const deal = byId(deals, po.dealId);
          const lines = (po.lineItems ?? []).map((line) => {
            const record = supplier?.isManufacturer ? byId(productionRecords, productionIdFor(line.id)) : null;
            return {
              line,
              stage: lineStageOf(po, line),
              stageEnteredAt: lineStageEnteredAt(po, line),
              production: record
                ? { recordId: record.id, stage: record.currentStage, completionPct: completionPct(record), stalled: assessStall(record, productionRecords, now).stalled }
                : undefined,
            };
          });
          const delay = assessDelay(po, supplier, supplierPurchaseOrders, now);
          return {
            po,
            supplierName: supplier?.name ?? '',
            dealCode: deal?.code ?? '',
            siteName: deal ? (resolveLead(deal.leadId)?.siteName ?? '') : '',
            totalValue: poTotalOf(po.lineItems ?? []),
            stage: poStageOf(po),
            stageEnteredAt: delay.stageEnteredAt,
            lines,
            partial: new Set(lines.map((l) => l.stage)).size > 1,
            delay: {
              daysInStage: delay.daysInStage,
              typicalDays: delay.typicalDays,
              typicalIsDefault: delay.typicalIsDefault,
              projectedDelivery: delay.projectedDelivery,
              risk: delay.risk,
            },
            supplierHasLogin: Boolean(supplier && supplierUserFor(supplier)),
          };
        })
        .sort((a, b) => ({ overdue: 0, at_risk: 1, on_track: 2 })[a.delay.risk] - ({ overdue: 0, at_risk: 1, on_track: 2 })[b.delay.risk] || a.stageEnteredAt.localeCompare(b.stageEnteredAt));
    }),

  updatePurchaseOrderFulfilment: (poId, input, byUserId) =>
    simulateWrite(() => movePoLinesSync(poId, input.lineIds, input.toStage, catalogActor(byUserId), input.note)),

  /* ------------------------------------------ Auto-PO trigger rules (094) */
  getAutoPoRules: () => simulateRead(() => ({ ...autoPoRules })),

  updateAutoPoRules: (patch, byUserId) =>
    simulateWrite(() => {
      if (catalogActor(byUserId).role !== 'admin') throw new RepositoryError('forbidden');
      const next = { ...autoPoRules, ...patch };
      const w = next.weights;
      const weightsValid =
        [w.price, w.speed, w.performance].every((v) => Number.isInteger(v) && v >= 0 && v <= 100) && w.price + w.speed + w.performance === 100;
      if (!weightsValid) throw new RepositoryError('invalid_weights');
      if (!Number.isFinite(next.approvalThreshold) || next.approvalThreshold < 0) throw new RepositoryError('invalid_input');
      autoPoRules = { ...next, version: autoPoRules.version + 1, updatedBy: nameOf(byUserId), updatedAt: new Date().toISOString() };
      return { ...autoPoRules };
    }),

  simulateAutoPoMatching: (input, byUserId) =>
    simulateWrite(() => {
      if (catalogActor(byUserId).role !== 'admin') throw new RepositoryError('forbidden');
      const rules: AutoPoRules = { ...autoPoRules, ...input.rulesOverride };
      const results = matchRequiredCategories(input.driveType, input.assignedSupplierId, rules);
      const share = valueShareOf(results);
      const simulation: AutoPoSimulationResult = {
        at: new Date().toISOString(),
        byName: nameOf(byUserId),
        rulesVersion: autoPoRules.version,
        usedUnsavedRules: Boolean(input.rulesOverride && Object.keys(input.rulesOverride).length > 0),
        driveType: input.driveType,
        assignedSupplierId: input.assignedSupplierId,
        results,
        totalValue: share.reduce((sum, v) => sum + v.value, 0),
        // One PO per chosen supplier, exactly as drafting would group them.
        wouldNeedApproval: share.some((v) => v.value > rules.approvalThreshold),
        valueShare: share.map(({ supplierId, supplierName, sharePct }) => ({ supplierId, supplierName, sharePct })),
      };
      autoPoRules = { ...autoPoRules, lastSimulation: simulation };
      return simulation;
    }),

  draftPurchaseOrdersNow: (dealId, byUserId) =>
    simulateWrite(() => {
      if (catalogActor(byUserId).role !== 'admin') throw new RepositoryError('forbidden');
      const deal = byId(deals, dealId);
      if (!deal) throw new RepositoryError('not_found');
      if (deal.status !== 'won') throw new RepositoryError('invalid_state');
      if (supplierPurchaseOrders.some((po) => po.dealId === dealId && po.lineItems)) throw new RepositoryError('already_drafted');
      const created = draftPurchaseOrdersForDeal(deal, nameOf(byUserId));
      pushTimelineEvent({
        leadId: deal.leadId,
        kind: 'note_added',
        actorName: nameOf(byUserId),
        at: new Date().toISOString(),
        detail: `Drafted ${created.map((po) => po.code).join(', ') || 'no'} purchase order(s) ahead of the automatic trigger`,
      });
      return created;
    }),

  /* ------------------------------------------ Supplier catalog (093) */
  listCatalogItems: (filter) =>
    simulateRead(() => {
      const lowest = lowestLivePriceByCategory();
      return supplierCatalogItems
        .filter((item) => !filter?.supplierId || item.supplierId === filter.supplierId)
        .map((item): CatalogItemView => {
          const categoryLowestPrice = lowest.get(item.category) ?? null;
          const pending = item.pendingPriceChangeId ? byId(catalogPriceChanges, item.pendingPriceChangeId) : null;
          return {
            item,
            supplierName: byId(suppliers, item.supplierId)?.name ?? '',
            categoryLowestPrice,
            pctAboveLowest: item.status === 'active' ? pctOver(item.unitPrice, categoryLowestPrice) : null,
            pendingChange: pending?.status === 'pending' ? pending : null,
            inFlightPoCount: inFlightPoCountFor(item),
          };
        })
        .sort((a, b) => a.item.category.localeCompare(b.item.category) || a.item.unitPrice - b.item.unitPrice);
    }),

  listCatalogPriceHistory: (itemId) =>
    simulateRead(() =>
      catalogPriceChanges
        .filter((c) => c.itemId === itemId)
        .sort((a, b) => (a.requestedAt < b.requestedAt ? 1 : a.requestedAt > b.requestedAt ? -1 : 0)),
    ),

  listPendingCatalogReviews: () =>
    simulateRead(() => {
      const lowest = lowestLivePriceByCategory();
      return catalogPriceChanges
        .filter((c) => c.status === 'pending')
        .map((change): CatalogPendingReview | null => {
          const item = byId(supplierCatalogItems, change.itemId);
          if (!item) return null;
          return {
            change,
            item,
            supplierName: byId(suppliers, change.supplierId)?.name ?? '',
            pctChange: change.fromPrice !== null ? pctOver(change.toPrice, change.fromPrice) : null,
            categoryLowestPrice: lowest.get(item.category) ?? null,
          };
        })
        .filter((r): r is CatalogPendingReview => r !== null)
        .sort((a, b) => (a.change.requestedAt < b.change.requestedAt ? -1 : 1));
    }),

  getCatalogSettings: () => simulateRead(() => ({ ...catalogSettings })),

  updateCatalogSettings: (priceReviewThresholdPct, byUserId) =>
    simulateWrite(() => {
      if (catalogActor(byUserId).role !== 'admin') throw new RepositoryError('forbidden');
      if (!Number.isFinite(priceReviewThresholdPct) || priceReviewThresholdPct < 1 || priceReviewThresholdPct > 50) {
        throw new RepositoryError('invalid_input');
      }
      catalogSettings = { priceReviewThresholdPct, updatedBy: nameOf(byUserId), updatedAt: new Date().toISOString() };
      return { ...catalogSettings };
    }),

  getSupplierForUser: (userId) =>
    simulateRead(() => {
      const user = byId(users, userId);
      if (!user || user.role !== 'supplier' || !user.gstin) return null;
      const gstin = user.gstin.toUpperCase();
      return suppliers.find((s) => s.gstin?.toUpperCase() === gstin) ?? null;
    }),

  saveCatalogItem: (input, byUserId) =>
    simulateWrite(() => {
      const actor = catalogActor(byUserId);
      const supplier = assertCatalogAccess(actor, input.supplierId);
      const existing = input.id ? byId(supplierCatalogItems, input.id) : null;
      if (input.id && (!existing || existing.supplierId !== supplier.id)) throw new RepositoryError('not_found');
      if (existing?.status === 'rejected' || existing?.status === 'discontinued') throw new RepositoryError('not_editable');
      return saveCatalogEntrySync(
        supplier,
        {
          category: existing?.category ?? input.category,
          description: input.description,
          specification: input.specification,
          driveTypes: input.driveTypes,
          unitPrice: input.unitPrice,
          leadTimeDays: input.leadTimeDays,
        },
        existing,
        actor,
        actor.role === 'admin' ? 'admin' : 'supplier',
      );
    }),

  setCatalogItemStatus: (itemId, status, byUserId) =>
    simulateWrite(() => {
      const item = byId(supplierCatalogItems, itemId);
      if (!item) throw new RepositoryError('not_found');
      assertCatalogAccess(catalogActor(byUserId), item.supplierId);
      if (status === 'discontinued') {
        if (item.status !== 'active' && item.status !== 'pending_review') throw new RepositoryError('not_editable');
        // POs already drafted keep their own snapshotted lines untouched;
        // only new drafting stops seeing this item.
        supersedePendingChange(item);
        return patchInPlace(supplierCatalogItems, itemId, {
          status: 'discontinued',
          pendingPrice: undefined,
          pendingPriceChangeId: undefined,
          updatedAt: new Date().toISOString(),
        });
      }
      if (item.status !== 'discontinued') throw new RepositoryError('not_editable');
      ensureSupplierCategory(item.supplierId, item.category);
      return patchInPlace(supplierCatalogItems, itemId, { status: 'active', updatedAt: new Date().toISOString() });
    }),

  reviewCatalogPriceChange: (changeId, decision, byUserId, reason) =>
    simulateWrite(() => {
      if (catalogActor(byUserId).role !== 'admin') throw new RepositoryError('forbidden');
      const change = byId(catalogPriceChanges, changeId);
      if (!change) throw new RepositoryError('not_found');
      if (change.status !== 'pending') throw new RepositoryError('not_pending');
      const item = byId(supplierCatalogItems, change.itemId);
      if (!item) throw new RepositoryError('not_found');
      const now = new Date().toISOString();
      const reviewer = nameOf(byUserId);
      if (decision === 'reject') {
        if (!reason?.trim()) throw new RepositoryError('reason_required');
        patchInPlace(supplierCatalogItems, item.id, {
          status: item.status === 'pending_review' ? 'rejected' : item.status,
          pendingPrice: undefined,
          pendingPriceChangeId: undefined,
        });
        return patchInPlace(catalogPriceChanges, changeId, { status: 'rejected', reviewedBy: reviewer, reviewedAt: now, rejectionReason: reason.trim() });
      }
      patchInPlace(supplierCatalogItems, item.id, {
        unitPrice: change.toPrice,
        status: item.status === 'pending_review' ? 'active' : item.status,
        pendingPrice: undefined,
        pendingPriceChangeId: undefined,
        updatedAt: now,
      });
      ensureSupplierCategory(item.supplierId, item.category);
      return patchInPlace(catalogPriceChanges, changeId, { status: 'applied', reviewedBy: reviewer, reviewedAt: now });
    }),

  previewCatalogBulkUpload: (supplierId, csvText, byUserId) =>
    simulateRead(() => {
      const actor = catalogActor(byUserId);
      return planCatalogBulkUpload(assertCatalogAccess(actor, supplierId), csvText, actor).map((p) => p.row);
    }),

  applyCatalogBulkUpload: (supplierId, csvText, byUserId) =>
    simulateWrite(() => {
      const actor = catalogActor(byUserId);
      const supplier = assertCatalogAccess(actor, supplierId);
      const result: CatalogBulkResult = { created: 0, updated: 0, sentForReview: 0, skipped: 0 };
      for (const { row, entry, existing } of planCatalogBulkUpload(supplier, csvText, actor)) {
        if (row.verdict === 'invalid' || row.action === 'unchanged') {
          result.skipped += 1;
          continue;
        }
        const saved = saveCatalogEntrySync(supplier, entry, existing, actor, 'bulk_upload');
        if (saved.outcome !== 'saved') result.sentForReview += 1;
        else if (row.action === 'create') result.created += 1;
        else result.updated += 1;
      }
      return result;
    }),

  /* ------------------------------------------ Manager layer (all roles) */
  // Each run is one synchronous pass, so two overlapping ticks (a slow tab,
  // a double mount) can't interleave — the second simply finds nothing left
  // to do.
  runFollowUpEngine: () => simulateWrite(() => runFollowUpEngineSync(Date.now())),

  listMyWork: (userId) =>
    simulateRead((): MyWork => {
      const now = Date.now();
      const horizon = now + days(MY_WORK_HORIZON_DAYS);
      const open = commitments.filter((c) => c.status === 'open' && !c.paused);
      const mineAll = open.filter((c) => c.ownerUserId === userId).sort(byDueThenAmount);
      const mine = mineAll.filter((c) => new Date(c.dueAt).getTime() <= horizon);
      const escalatedToMe = open
        .filter((c) => c.escalatedToUserId === userId && c.ownerUserId !== userId && c.escalationLevel >= 3)
        .sort(byDueThenAmount);
      return {
        mine: mine.map((c) => toWorkItem(c, now)),
        laterCount: mineAll.length - mine.length,
        escalatedToMe: escalatedToMe.map((c) => toWorkItem(c, now)),
      };
    }),

  listWorkNotifications: (userId) =>
    simulateRead(() =>
      workNotifications
        .filter((n) => n.userId === userId)
        .map((notification): WorkNotificationView | null => {
          const commitment = commitments.find((c) => c.id === notification.commitmentId);
          return commitment ? { notification, commitment, ownerName: nameOf(commitment.ownerUserId) } : null;
        })
        .filter((v): v is WorkNotificationView => v !== null)
        .sort((a, b) => (a.notification.at < b.notification.at ? 1 : a.notification.at > b.notification.at ? -1 : b.notification.id.localeCompare(a.notification.id)))
        .slice(0, 50),
    ),

  markWorkNotificationsRead: (userId) =>
    simulateWrite(() => {
      const at = new Date().toISOString();
      for (let i = 0; i < workNotifications.length; i += 1) {
        if (workNotifications[i].userId === userId && !workNotifications[i].readAt) workNotifications[i] = { ...workNotifications[i], readAt: at };
      }
    }),

  getReliability: (userId) =>
    simulateRead((): ReliabilityScore => {
      const now = Date.now();
      const mine = commitments.filter((c) => c.ownerUserId === userId);
      const done = mine.filter((c) => c.status === 'done' && c.completedAt);
      const onTime = done.filter((c) => c.completedAt! <= c.dueAt).length;
      return {
        completed: done.length,
        onTime,
        onTimePct: done.length >= 3 ? Math.round((onTime / done.length) * 100) : null,
        openOverdue: mine.filter((c) => c.status === 'open' && !c.paused && new Date(c.dueAt).getTime() < now).length,
      };
    }),

  listAutomatedActions: (limit = 20) => simulateRead(() => [...automatedActionLog].reverse().slice(0, limit)),

  acknowledgePurchaseOrder: (poId, byUserId) => simulateWrite(() => acknowledgePurchaseOrderSync(poId, byUserId)),

  completeCommitmentQuickAction: (commitmentId, byUserId) =>
    simulateWrite(() => {
      const commitment = commitments.find((c) => c.id === commitmentId);
      if (!commitment) throw new RepositoryError('not_found');
      if (commitment.status !== 'open') return commitment;
      const action = RULE_BY_KIND[commitment.kind].quickAction;
      if (!action) throw new RepositoryError('no_quick_action');
      // Only the owner may say "done" on their own promise.
      if (commitment.ownerUserId !== byUserId) throw new RepositoryError('not_owner');
      if (action === 'complete_task') completeFollowUpTaskSync(commitment.subject.id, nameOf(byUserId));
      else acknowledgePurchaseOrderSync(commitment.subject.id, byUserId);
      // Reflect it at once rather than on the next tick.
      syncCommitments(Date.now());
      return commitmentByKey.get(commitment.key) ?? commitment;
    }),

  listZones: () => simulateRead(() => [...zones]),

  saveZone: (zone: GeoZone) =>
    simulateWrite(() => {
      const index = zones.findIndex((z) => z.id === zone.id);
      if (index === -1) zones.push(zone);
      else zones[index] = zone;
      return zone;
    }),

  getRoutePlan: (userId) =>
    simulateRead(() => routePlans.find((r) => r.userId === userId) ?? null),

  listSiteVisits: (filter) =>
    simulateRead(() =>
      siteVisits
        .filter((v) => !filter?.status || filter.status.includes(v.status))
        .sort((a, b) => b.checkInAt.localeCompare(a.checkInAt)),
    ),

  setSiteVisitStatus: (id, status, reason) =>
    simulateWrite(() =>
      patchInPlace(siteVisits, id, {
        status,
        flagReason: reason,
      } as Partial<SiteVisitVerification>),
    ),

  /* -------------------------------------------------------- Commission */
  listCommissions: (userId) =>
    simulateRead(() =>
      commissions
        .filter((c) => !userId || c.userId === userId)
        .sort((a, b) => b.earnedAt.localeCompare(a.earnedAt)),
    ),

  /* -------------------------------------------------------- Automation */
  listAutomations: () => simulateRead(() => [...automations]),

  toggleAutomation: (id, enabled) =>
    simulateWrite(() =>
      patchInPlace(automations, id, {
        enabled,
        status: enabled ? 'healthy' : 'paused',
      } as Partial<AutomationRule>),
    ),

  /* --------------------------------------------------------- Analytics */
  getSeries: (key) => simulateRead(() => seedSeries[SERIES_KEYS[key]]),

  getFunnel: () =>
    simulateRead(() => {
      const order: Lead['stage'][] = [
        'captured',
        'contacted',
        'site_visit',
        'quoted',
        'negotiation',
        'won',
      ];
      // A lead sitting at 'quoted' has already passed through every earlier
      // stage — a funnel counts cumulative reach, not current occupancy.
      const rank = (stage: Lead['stage']) => order.indexOf(stage);
      return order.map<FunnelStage>((stage) => {
        const reached = leads.filter((l) => l.stage !== 'lost' && rank(l.stage) >= rank(stage));
        return {
          stage,
          count: reached.length,
          value: reached.reduce((sum, l) => sum + l.estimatedValue, 0),
        };
      });
    }),

  getExecutiveKpis: () =>
    simulateRead<ExecutiveKpis>(() => {
      const monthStart = startOfMonth();
      const prevStart = startOfPrevMonth();

      const thisMonthLeads = leads.filter((l) => new Date(l.createdAt).getTime() >= monthStart);
      const prevMonthLeads = leads.filter((l) => {
        const t = new Date(l.createdAt).getTime();
        return t >= prevStart && t < monthStart;
      });

      const wonDeals = deals.filter((d) => d.status === 'won');
      const revenueThisMonth = wonDeals
        .filter((d) => d.closedAt && new Date(d.closedAt).getTime() >= monthStart)
        .reduce((sum, d) => sum + d.agreedPrice, 0);
      const revenuePrevMonth = wonDeals
        .filter((d) => {
          if (!d.closedAt) return false;
          const t = new Date(d.closedAt).getTime();
          return t >= prevStart && t < monthStart;
        })
        .reduce((sum, d) => sum + d.agreedPrice, 0);

      const closed = leads.filter((l) => l.stage === 'won' || l.stage === 'lost');
      const conversionRate = closed.length ? leads.filter((l) => l.stage === 'won').length / closed.length : 0;

      const overdue = payments.filter((p) => p.status === 'overdue');
      const automationRuns = automations.reduce((sum, a) => sum + a.runsToday, 0);
      const automationFailures = automations.reduce((sum, a) => sum + a.failuresToday, 0);

      return {
        leadsThisMonth: thisMonthLeads.length,
        leadsDelta: delta(thisMonthLeads.length, prevMonthLeads.length),
        conversionRate,
        conversionDelta: 0.06,
        revenueThisMonth,
        revenueDelta: delta(revenueThisMonth, revenuePrevMonth),
        activeJobs: jobs.filter((j) => j.status !== 'completed').length,
        overduePayments: overdue.length,
        overdueAmount: overdue.reduce((sum, p) => sum + p.amount, 0),
        avgDealSize: wonDeals.length
          ? Math.round(wonDeals.reduce((sum, d) => sum + d.agreedPrice, 0) / wonDeals.length)
          : 0,
        openAlerts: alerts.filter((a) => a.status === 'open').length,
        automationSuccessRate: automationRuns
          ? (automationRuns - automationFailures) / automationRuns
          : 1,
      };
    }),

  getSurveyorScores: () =>
    simulateRead(() =>
      users
        .filter((u) => u.role === 'surveyor' && u.status === 'active')
        .map<SurveyorScore>((u) => {
          const own = leads.filter((l) => l.surveyorId === u.id);
          const won = own.filter((l) => l.stage === 'won');
          const closed = own.filter((l) => l.stage === 'won' || l.stage === 'lost');
          return {
            userId: u.id,
            name: u.name,
            leadsCaptured: own.length,
            conversions: won.length,
            conversionRate: closed.length ? won.length / closed.length : 0,
            revenue: won.reduce((sum, l) => sum + l.estimatedValue, 0),
            commissionEarned: commissions
              .filter((c) => c.userId === u.id && c.status !== 'forfeited')
              .reduce((sum, c) => sum + c.amount, 0),
            avgResponseHours: 4 + (u.id.charCodeAt(u.id.length - 1) % 7),
            rating: u.rating ?? 0,
          };
        })
        .sort((a, b) => b.revenue - a.revenue),
    ),

  getTechnicianScores: () => simulateRead(() => users.filter((u) => u.role === 'technician' && u.status === 'active').map(technicianScoreOf).sort((a, b) => b.rating - a.rating)),

  getRegionConversion: () =>
    simulateRead(() => {
      const byRegion = new Map<string, RegionConversion>();
      for (const lead of leads) {
        const region = lead.city;
        const row =
          byRegion.get(region) ?? { region, leads: 0, conversions: 0, rate: 0, revenue: 0 };
        row.leads += 1;
        if (lead.stage === 'won') {
          row.conversions += 1;
          row.revenue += lead.estimatedValue;
        }
        byRegion.set(region, row);
      }
      return [...byRegion.values()]
        .map((r) => ({ ...r, rate: r.leads ? r.conversions / r.leads : 0 }))
        .sort((a, b) => b.revenue - a.revenue);
    }),

  /* ---------------------------------------------- Communication: templates */
  listCommTemplates: (filter) =>
    simulateRead(() =>
      commTemplates
        .filter((t) => !filter?.channel || t.channel === filter.channel)
        .filter((t) => !filter?.associatedStage || t.associatedStage === filter.associatedStage)
        .filter((t) => !filter?.language || t.language === filter.language)
        .sort((a, b) => a.name.localeCompare(b.name)),
    ),

  getTemplateGroup: (groupId) => simulateRead(() => commTemplates.filter((t) => t.groupId === groupId)),

  saveCommTemplateBody: (id, body, editedBy) =>
    simulateWrite(() => {
      const template = findTemplate(id);
      const now = new Date().toISOString();
      const nextVersion = (template.versions.at(-1)?.version ?? 0) + 1;
      return patchInPlace(commTemplates, id, {
        body,
        mergeFields: extractMergeFields(body),
        updatedAt: now,
        updatedBy: editedBy,
        versions: [...template.versions, { version: nextVersion, body, editedBy, editedAt: now }],
      });
    }),

  setCommTemplateStatus: (id, status) => simulateWrite(() => patchInPlace(commTemplates, id, { status })),

  /* ---------------------------------------------- Communication: sequences */
  listSequences: () => simulateRead(() => [...commSequences].sort((a, b) => a.priority - b.priority)),

  saveSequence: (sequence) =>
    simulateWrite(() => {
      const now = new Date().toISOString();
      const index = sequence.id ? commSequences.findIndex((s) => s.id === sequence.id) : -1;
      const saved: CommSequence = {
        ...sequence,
        id: sequence.id || `seq-new-${(sequenceCounter += 1)}`,
        updatedAt: now,
      };
      if (index === -1) commSequences.push(saved);
      else commSequences[index] = saved;
      return saved;
    }),

  toggleSequence: (id, isActive) =>
    simulateWrite(() => patchInPlace(commSequences, id, { isActive, updatedAt: new Date().toISOString() })),

  testSendSequence: (sequenceId, leadId) =>
    simulateRead(() => {
      const sequence = byId(commSequences, sequenceId);
      if (!sequence) throw new RepositoryError('not_found');
      const lead = resolveLead(leadId);
      if (!lead) throw new RepositoryError('not_found');
      const values = buildMergeValuesForLead(lead);
      const language = lead.preferredLanguage ?? 'en';
      return [...sequence.steps]
        .sort((a, b) => a.order - b.order)
        .map<SequenceTestStep>((step) => {
          const template = templateInGroup(step.templateGroupId, language) ?? templateInGroup(step.templateGroupId, 'en');
          return {
            stepId: step.id,
            order: step.order,
            waitDays: step.waitDays,
            channel: template?.channel ?? 'sms',
            renderedBody: template ? renderTemplateBody(template.body, values) : '',
          };
        });
    }),

  /* ------------------------------------------ Communication: conversations */
  listConversations: (filter) =>
    simulateRead(() =>
      conversations
        .filter((c) => !filter?.assignedAgentId || c.assignedAgentId === filter.assignedAgentId)
        .map((c) => {
          const lead = resolveLead(c.leadId);
          if (!lead) return null;
          return { ...c, lead, messages: commMessages.filter((m) => m.conversationId === c.id).sort((a, b) => a.at.localeCompare(b.at)) };
        })
        .filter((c): c is ConversationWithContext => c !== null)
        .sort((a, b) => b.lastMessageAt.localeCompare(a.lastMessageAt)),
    ),

  getConversation: (id) =>
    simulateRead(() => {
      const conv = byId(conversations, id);
      if (!conv) return null;
      const lead = resolveLead(conv.leadId);
      if (!lead) return null;
      return { ...conv, lead, messages: commMessages.filter((m) => m.conversationId === id).sort((a, b) => a.at.localeCompare(b.at)) };
    }),

  sendAgentMessage: (conversationId, body, agentName) =>
    simulateWrite(() => {
      const conv = byId(conversations, conversationId);
      if (!conv) throw new RepositoryError('not_found');
      const now = new Date().toISOString();
      const message: CommMessage = {
        id: `cm-new-${(messageCounter += 1)}`,
        conversationId,
        channel: 'whatsapp',
        sender: 'agent',
        senderName: agentName,
        body,
        status: 'sent',
        at: now,
        handled: true,
      };
      commMessages.push(message);
      // A human reply pauses the automated sequence for a cool-down window so
      // a bot nudge never lands right after a person just personally replied.
      const cooldownUntil = new Date(Date.now() + 4 * 60 * 60 * 1000).toISOString();
      patchInPlace(conversations, conversationId, { lastMessageAt: now, sequencePausedUntil: cooldownUntil });
      return message;
    }),

  assignConversation: (conversationId, agentId) =>
    simulateWrite(() => patchInPlace(conversations, conversationId, { assignedAgentId: agentId })),

  markMessageHandled: (messageId) =>
    simulateWrite(() => patchInPlace(commMessages, messageId, { handled: true, requiresHumanReview: false })),

  /* -------------------------------------------------- Communication: calls */
  listCallLog: (filter) =>
    simulateRead(() =>
      callLog.filter((c) => !filter?.leadId || c.leadId === filter.leadId).sort((a, b) => b.at.localeCompare(a.at)),
    ),

  logCall: (leadId, loggedBy) =>
    simulateWrite(() => {
      const call: CallLogEntry = {
        id: `cl-new-${(callCounter += 1)}`,
        leadId,
        outcome: null,
        durationSec: 0,
        at: new Date().toISOString(),
        consentGiven: false,
        loggedBy,
        isDemo: true,
      };
      callLog.unshift(call);
      return call;
    }),

  setCallDisposition: (id, outcome, durationSec, consentGiven) =>
    simulateWrite(() => {
      const updated = patchInPlace(callLog, id, consentGiven === undefined ? { outcome, durationSec } : { outcome, durationSec, consentGiven });
      if (outcome === 'connected_interested') {
        const lead = byId(leads, updated.leadId);
        if (lead) {
          const currentRank = rankOf(lead.stage);
          // Nudges the lead toward Quoted readiness — advances one real stage
          // at a time, never jumps straight to Quoted (that still needs a
          // linked deal, same gate the Kanban board enforces).
          if (currentRank >= 0 && currentRank < rankOf('quoted') - 1) {
            const nextStage = PIPELINE_RANK[currentRank + 1];
            const now = new Date().toISOString();
            patchInPlace(leads, lead.id, { stage: nextStage, stageEnteredAt: now, updatedAt: now });
            pushTimelineEvent({
              leadId: lead.id,
              kind: 'stage_changed',
              actorName: 'Automation',
              at: now,
              fromValue: lead.stage,
              toValue: nextStage,
              detail: 'Call disposition: Connected - Interested',
            });
            recomputeActiveScores(scoreWeightingProfile);
          }
        }
      }
      return updated;
    }),

  /* --------------------------------------------- Communication: broadcasts */
  listBroadcasts: () => simulateRead(() => [...broadcasts].sort((a, b) => b.createdAt.localeCompare(a.createdAt))),

  previewBroadcastSegment: (filter) =>
    simulateRead(() => {
      const q = filter.query?.trim().toLowerCase();
      const matched = leads
        .filter((l) => !l.duplicateOfLeadId)
        .filter((l) => !filter.stage || filter.stage.includes(l.stage))
        .filter((l) => !filter.surveyorId || l.surveyorId === filter.surveyorId)
        .filter((l) => !filter.city || l.city === filter.city)
        .filter((l) => !filter.source || filter.source.includes(l.source))
        .filter((l) => !q || l.siteName.toLowerCase().includes(q) || l.builderName.toLowerCase().includes(q));
      const eligible = matched.filter((l) => !isOptedOutSync(l.contactPhone, 'sms'));
      // Roughly matches typical DLT-routed transactional SMS pricing.
      const COST_PER_SMS = 0.18;
      return {
        leadIds: eligible.map((l) => l.id),
        excludedOptedOutCount: matched.length - eligible.length,
        estimatedCost: Math.round(eligible.length * COST_PER_SMS * 100) / 100,
      };
    }),

  createBroadcast: (input) =>
    simulateWrite(() => {
      const now = new Date().toISOString();
      const immediate = !input.scheduledFor;
      const delivered = immediate ? Math.round(input.leadIds.length * 0.92) : 0;
      const failed = immediate ? input.leadIds.length - delivered : 0;
      const broadcast: SmsBroadcast = {
        id: `bc-new-${(broadcastCounter += 1)}`,
        name: input.name,
        segmentDescription: input.segmentDescription,
        segmentLeadIds: input.leadIds,
        messageBody: input.messageBody,
        scheduledFor: input.scheduledFor,
        status: immediate ? 'sent' : 'scheduled',
        sentCount: immediate ? input.leadIds.length : 0,
        deliveredCount: delivered,
        failedCount: failed,
        failureBreakdown: failed > 0 ? splitFailureReasons(failed) : undefined,
        optedOutExcludedCount: 0,
        estimatedCost: Math.round(input.leadIds.length * 0.18 * 100) / 100,
        actualCost: immediate ? Math.round(input.leadIds.length * 0.18 * 100) / 100 : undefined,
        createdAt: now,
        isDemo: true,
      };
      broadcasts.unshift(broadcast);
      return broadcast;
    }),

  cancelBroadcast: (id) =>
    simulateWrite(() => {
      const b = byId(broadcasts, id);
      if (!b) throw new RepositoryError('not_found');
      if (b.status !== 'scheduled') throw new RepositoryError('not_cancellable');
      return patchInPlace(broadcasts, id, { status: 'cancelled' as const });
    }),

  /* ------------------------------------------------- Communication: AI bot */
  getBotConfig: () => simulateRead(() => ({ ...botConfig })),

  updateBotConfig: (patch) =>
    simulateWrite(() => {
      const nextMax = patch.allowedDiscountMaxPct ?? botConfig.allowedDiscountMaxPct;
      if (nextMax > MAX_SAFE_BOT_DISCOUNT_PCT) throw new RepositoryError('discount_exceeds_margin_floor');
      botConfig = { ...botConfig, ...patch, updatedAt: new Date().toISOString() };
      return { ...botConfig };
    }),

  simulateBotReply: (sampleMessage, configOverride) =>
    simulateRead(() => runBotSimulation(sampleMessage, { ...botConfig, ...configOverride })),

  /* ------------------------------------------- Communication: reply inbox */
  listReplyInboxItems: () =>
    simulateRead(() => {
      const items: ReplyInboxItem[] = [];
      for (const message of commMessages) {
        if (message.sender !== 'customer' || message.handled || !message.requiresHumanReview) continue;
        const conversation = byId(conversations, message.conversationId);
        if (!conversation) continue;
        const lead = resolveLead(conversation.leadId);
        if (!lead) continue;
        const waitingMinutes = businessMinutesSince(message.at);
        items.push({ kind: 'message', message, conversation, lead, slaBreached: waitingMinutes > SLA_MINUTES, waitingMinutes });
      }

      // A missed-call-back request: the newest call attempt for a lead went
      // unanswered. Once a fresh call is placed (any outcome, even
      // undispositioned), that becomes the newest record and this item
      // naturally drops out — no separate "handled" flag needed.
      const newestCallByLead = new Map<string, CallLogEntry>();
      for (const call of callLog) {
        const current = newestCallByLead.get(call.leadId);
        if (!current || call.at > current.at) newestCallByLead.set(call.leadId, call);
      }
      for (const call of newestCallByLead.values()) {
        if (call.outcome !== 'no_answer') continue;
        const lead = resolveLead(call.leadId);
        if (!lead) continue;
        const waitingMinutes = businessMinutesSince(call.at);
        items.push({ kind: 'missed_call', call, lead, slaBreached: waitingMinutes > SLA_MINUTES, waitingMinutes });
      }

      return items.sort((a, b) => b.waitingMinutes - a.waitingMinutes);
    }),

  /* ----------------------------------------------- Communication: opt-outs */
  listOptOutEvents: () => simulateRead(() => [...optOutEvents].sort((a, b) => b.at.localeCompare(a.at))),

  recordOptOutEvent: (input) =>
    simulateWrite(() => {
      const event: OptOutEvent = {
        id: `oo-new-${(optOutCounter += 1)}`,
        contactPhone: input.contactPhone,
        contactName: input.contactName,
        channel: input.channel,
        type: input.type,
        source: input.source,
        reason: input.reason,
        at: new Date().toISOString(),
        recordedBy: input.recordedBy,
        isDemo: true,
      };
      optOutEvents.unshift(event);
      return event;
    }),

  isOptedOut: (contactPhone, channel) => simulateRead(() => isOptedOutSync(contactPhone, channel)),

  /* ------------------------------------------ Communication: trigger rules */
  listTriggerRules: () =>
    simulateRead(() => [...triggerRules].sort((a, b) => a.priority - b.priority || b.createdAt.localeCompare(a.createdAt))),

  saveTriggerRule: (rule) =>
    simulateWrite(() => {
      if (rule.id) return patchInPlace(triggerRules, rule.id, { ...rule });
      const created: TriggerRule = { ...rule, id: `tr-new-${(ruleCounter += 1)}`, createdAt: new Date().toISOString(), isDemo: true };
      triggerRules.push(created);
      return created;
    }),

  toggleTriggerRule: (id, enabled) => simulateWrite(() => patchInPlace(triggerRules, id, { enabled })),

  simulateTriggerRules: (stage) =>
    simulateRead(() => {
      const matching = [...triggerRules]
        .filter((r) => r.triggerStage === stage)
        .sort((a, b) => a.priority - b.priority || b.createdAt.localeCompare(a.createdAt));
      let topFired: TriggerRule | null = null;
      return matching.map<TriggerRuleEvaluation>((rule) => {
        if (!rule.enabled) return { rule, wouldFire: false };
        if (rule.allowStacking) return { rule, wouldFire: true };
        if (!topFired) {
          topFired = rule;
          return { rule, wouldFire: true };
        }
        return { rule, wouldFire: false, suppressedByRuleId: topFired.id };
      });
    }),

  /* -------------------------------------------- Communication: analytics */
  getCommunicationAnalytics: () =>
    simulateRead(() => {
      const channels: CommChannel[] = ['sms', 'whatsapp', 'call'];
      const channelStats: ChannelStat[] = channels.map((channel) => {
        if (channel === 'call') {
          const totalSent = callLog.length;
          const responded = callLog.filter((c) => c.outcome === 'connected_interested' || c.outcome === 'connected_not_interested').length;
          return { channel, totalSent, responseRatePct: totalSent ? responded / totalSent : 0, cost: 0 };
        }
        const sent = commMessages.filter((m) => m.channel === channel && m.sender !== 'customer').length;
        const responded = commMessages.filter((m) => m.channel === channel && m.sender === 'customer').length;
        const cost = channel === 'sms' ? broadcasts.reduce((sum, b) => sum + (b.actualCost ?? 0), 0) : 0;
        return { channel, totalSent: sent, responseRatePct: sent ? Math.min(1, responded / sent) : 0, cost };
      });

      const EARLY_DATA_THRESHOLD = 3;
      const templateStats: TemplateStat[] = templateSeedsUnique().map((groupId) => {
        const sends = commMessages.filter((m) => m.templateGroupId === groupId);
        const responded = sends.filter((m) => {
          const conv = byId(conversations, m.conversationId);
          if (!conv) return false;
          return commMessages.some((reply) => reply.conversationId === conv.id && reply.sender === 'customer' && reply.at > m.at);
        }).length;
        const template = commTemplates.find((t) => t.groupId === groupId && t.language === 'en');
        const wonLeadsReached = sends
          .map((m) => byId(conversations, m.conversationId)?.leadId)
          .filter((id): id is string => Boolean(id))
          .map((id) => resolveLead(id))
          .filter((l): l is Lead => l !== null && l.stage === 'won').length;
        return {
          templateGroupId: groupId,
          templateName: template?.name ?? groupId,
          channel: template?.channel ?? 'sms',
          totalSent: sends.length,
          responseRatePct: sends.length ? Math.min(1, responded / sends.length) : 0,
          conversionInfluenceScore: sends.length ? Math.round((wonLeadsReached / sends.length) * 100) : 0,
          earlyData: sends.length < EARLY_DATA_THRESHOLD,
        };
      });

      // Real daily buckets from actual outbound send timestamps, not a
      // fabricated trend line.
      const dayBuckets = new Map<string, number>();
      for (const message of commMessages) {
        if (message.sender === 'customer') continue;
        const day = message.at.slice(0, 10);
        dayBuckets.set(day, (dayBuckets.get(day) ?? 0) + 1);
      }
      const volumeTrend: SeriesPoint[] = [...dayBuckets.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([t, v]) => ({ t, v }));

      const inboxItemsAll = commMessages.filter((m) => m.sender === 'customer' && m.requiresHumanReview);
      const withinSla = inboxItemsAll.filter((m) => !m.handled || businessMinutesSince(m.at) <= SLA_MINUTES).length;

      return {
        channelStats,
        templateStats,
        volumeTrend,
        slaCompliancePct: inboxItemsAll.length ? withinSla / inboxItemsAll.length : 1,
        // Stand-in for a real incident feed (a status-page or PagerDuty
        // integration) that doesn't exist yet — a fixed demo annotation so
        // Admin sees a depressed number explained rather than misread as a
        // content problem, per the module spec's outage edge case. A
        // translation key, like `escalateReasonKey` elsewhere — never raw
        // English from the data layer.
        outageNote: 'commAnalytics.outageNote',
      };
    }),
};

function templateSeedsUnique(): string[] {
  return [...new Set(commTemplates.map((t) => t.groupId))];
}
